          {/* Badge for Correct/Incorrect - Absolute pos */}
          {isAnswered && !isEditMode && (
             <div className="absolute top-0 right-0 p-4 no-print animate-fade-in-up z-10">
                <div className={`flex items-center gap-1 font-bold px-3 py-1 rounded-full shadow-sm text-base ${isCorrect ? 'bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300' : 'bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300'}`}>
                    {isCorrect ? <Star className="w-4 h-4 fill-emerald-700 dark:fill-emerald-300" /> : <XCircle className="w-4 h-4" />}
                    {isCorrect ? "+1 Điểm" : "0 Điểm"}
                </div>
             </div>
