import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation, FileText, Printer, FileJson, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset }) => {
  // State logic
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');

  // UI/Tool State
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Prevent interfering with inputs if any
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

        if (viewMode === 'slide') {
            if (e.key === 'ArrowRight' || e.key === 'Space') {
                handleNextAction();
            } else if (e.key === 'ArrowLeft') {
                handlePrevAction();
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide, slideStep, viewMode, slides.length]);

  // Fullscreen Handler
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        containerRef.current.requestFullscreen().catch((err) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const handlePrevAction = () => {
    if (slideStep > 1) {
        setSlideStep(s => s - 1);
    } else if (currentSlide > 0) {
        setCurrentSlide(c => c - 1);
        setSlideStep(3); // Go to end of previous slide
    }
  };

  const handleNextAction = () => {
    if (slideStep < 3) {
        setSlideStep(s => s + 1);
    } else if (currentSlide < slides.length - 1) {
        setCurrentSlide(c => c + 1);
        setSlideStep(1); // Go to start of next slide
    }
  };

  const jumpToSlide = (idx: number) => {
      setCurrentSlide(idx);
      setSlideStep(1);
      setShowNav(false);
      if (viewMode === 'doc') {
          // Scroll to element in doc mode
          const el = document.getElementById={`section-${idx}`);
          if (el) el.scrollIntoView({ behavior: 'smooth' });
      }
  };

  const handleExportJSON = () => {
    const exportData = {
        type: 'theory',
        timestamp: Date.now(),
        config,
        data
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `lecture-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const renderSlideContent = (section: TheorySection) => {
     // Scaling style
     const scaleStyle = { fontSize: `${zoomLevel * 100}%` };

     return (
        <div className="flex flex-col h-full p-8 md:p-12 lg:p-16 max-w-6xl mx-auto justify-center" style={scaleStyle}>
            {/* 1. Title */}
            <div className={`transition-all duration-500 transform ${slideStep >= 1 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <h2 className="text-4xl md:text-5xl font-black text-teal-700 dark:text-teal-400 mb-8 border-b-4 border-teal-500 pb-4 inline-block">
                    {section.title}
                </h2>
            </div>

            {/* 2. Theory Content */}
            <div className={`flex-1 overflow-y-auto mb-8 transition-all duration-500 delay-100 transform ${slideStep >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <div className="text-2xl md:text-3xl text-slate-700 dark:text-slate-200 leading-relaxed space-y-4 font-medium">
                     <MathRenderer content={section.content} />
                </div>
            </div>

            {/* 3. Example */}
            <div className={`bg-slate-100 dark:bg-slate-800 p-6 rounded-2xl border-l-8 border-teal-500 shadow-lg transition-all duration-500 delay-200 transform ${slideStep >= 3 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <div className="flex items-center gap-3 mb-3">
                    <span className="bg-teal-600 text-white font-bold px-3 py-1 rounded text-sm uppercase tracking-wider">Ví dụ</span>
                    <span className="text-slate-500 dark:text-slate-400 text-sm font-semibold italic">Minh họa điển hình</span>
                </div>
                {section.examples && section.examples.length > 0 && (
                    <div className="space-y-4">
                        <div className="text-xl text-slate-800 dark:text-slate-100 font-bold">
                            <MathRenderer content={section.examples[0].problem} />
                        </div>
                        <div className="text-lg text-slate-600 dark:text-slate-300 border-t border-slate-200 dark:border-slate-700 pt-3">
                            <span className="font-bold text-teal-700 dark:text-teal-400">Giải: </span>
                            <MathRenderer content={section.examples[0].solution} />
                        </div>
                        <div className="text-base text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-900 p-3 rounded-lg italic border border-slate-200 dark:border-slate-700">
                             💡 <span className="font-semibold">Mấu chốt:</span> {section.examples[0].explanation}
                        </div>
                    </div>
                )}
            </div>
        </div>
     );
  };

  return (
    <div 
        ref={containerRef}
        className={`
            bg-slate-50 dark:bg-slate-900 font-sans selection:bg-teal-100 selection:text-teal-800 dark:selection:bg-teal-900 dark:selection:text-teal-200 relative transition-all duration-300
            ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}
            ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
            ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full' : ''}
        `}
    >

        {/* Content Wrapper for Side Mode */}
        <div className={`
             transition-all duration-300 ease-in-out h-full flex flex-col
             ${showBlackboard && blackboardMode === 'side' 
                ? 'w-[50vw] h-screen fixed left-0 top-0 overflow-hidden z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl bg-slate-50 dark:bg-slate-900' 
                : 'w-full'}
        `}>

            {/* Top Toolbar - Hidden in Fullscreen */}
            <div className={`bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-30 shadow-sm no-print transition-all ${isFullscreen ? 'hidden' : ''}`}>
                <div className="flex items-center gap-4">
                    <button onClick={onReset} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                    </button>
                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-700"></div>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setViewMode('slide')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <Presentation className="w-4 h-4" /> Slide
                        </button>
                        <button 
                            onClick={() => setViewMode('doc')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'doc' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <FileText className="w-4 h-4" /> Tài liệu
                        </button>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={handleExportJSON}
                        className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700"
                    >
                        <FileJson className="w-4 h-4" /> <span className="hidden sm:inline">JSON</span>
                    </button>
                    <button 
                        onClick={() => window.print()}
                        className="flex items-center gap-2 px-3 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg font-bold text-sm shadow-sm transition-colors"
                    >
                        <Printer className="w-4 h-4" /> <span className="hidden sm:inline">In ấn</span>
                    </button>
                </div>
            </div>

            {/* Main Content Area */}
            <div className={`flex-grow overflow-hidden relative ${isFullscreen ? 'h-full' : ''}`}>
                {viewMode === 'doc' ? (
                    <div className="h-full overflow-y-auto custom-scrollbar">
                        <div className="max-w-4xl mx-auto p-6 md:p-12 pb-24">
                            <div className="text-center mb-10 border-b-2 border-teal-100 dark:border-teal-900 pb-6">
                                <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-4">{data.topic}</h1>
                                <p className="text-lg text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">{data.overview}</p>
                            </div>
                            <div className="space-y-12">
                                {data.sections.map((sec, idx) => (
                                    <div id={`section-${idx}`} key={idx} className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 break-inside-avoid scroll-mt-20">
                                        <h3 className="text-2xl font-bold text-teal-700 dark:text-teal-400 mb-6 flex items-center gap-3">
                                            <span className="w-8 h-8 rounded-full bg-teal-100 dark:bg-teal-900/50 flex items-center justify-center text-sm">{idx + 1}</span>
                                            {sec.title}
                                        </h3>
                                        <div className="text-lg text-slate-800 dark:text-slate-200 mb-6 space-y-2">
                                            <MathRenderer content={sec.content} />
                                        </div>
                                        {sec.examples && sec.examples.map((ex, i) => (
                                            <div key={i} className="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-xl border border-slate-200 dark:border-slate-700">
                                                <div className="font-bold text-slate-900 dark:text-slate-100 mb-2">Ví dụ:</div>
                                                <div className="mb-2"><MathRenderer content={ex.problem} /></div>
                                                <div className="pl-4 border-l-4 border-teal-300 dark:border-teal-700 text-slate-700 dark:text-slate-300">
                                                    <MathRenderer content={ex.solution} />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center relative">
                        {/* Slide Content */}
                        <div key={currentSlide} className="w-full h-full animate-fade-in">
                            {renderSlideContent(slides[currentSlide])}
                        </div>

                        {/* Navigation Arrows (Bottom Corners) */}
                        <button 
                            onClick={handlePrevAction} 
                            disabled={currentSlide === 0 && slideStep === 1} 
                            className="fixed left-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Lùi lại"
                        >
                            <ChevronLeft className="w-8 h-8 group-hover:-translate-x-1 transition-transform" />
                        </button>

                        <button 
                            onClick={handleNextAction} 
                            disabled={currentSlide === slides.length - 1 && slideStep >= 3} 
                            className="fixed right-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Tiếp tục"
                        >
                            <ChevronRight className="w-8 h-8 group-hover:translate-x-1 transition-transform" />
                        </button>

                        {/* Progress Indicator (Bottom Center) - Only visible if Dock is collapsed or not conflicting */}
                        <div className="absolute bottom-6 left-0 right-0 flex justify-center pointer-events-none">
                             <div className="flex flex-col items-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-md px-4 py-2 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-sm">
                                <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">
                                    Slide {currentSlide + 1} / {slides.length}
                                </span>
                                <div className="flex gap-1.5">
                                    {[1, 2, 3].map(step => (
                                        <div key={step} className={`h-1.5 w-1.5 rounded-full transition-all duration-300 ${step <= slideStep ? 'bg-teal-500 scale-110' : 'bg-slate-300 dark:bg-slate-600'}`} />
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* --- DOCK --- */}
        <div className="no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-300">

            {/* Navigation Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Mục lục bài giảng</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="flex flex-col gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar">
                        {slides.map((sec, idx) => {
                            const isActive = idx === currentSlide;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToSlide(idx)}
                                    className={`p-3 rounded-xl font-medium transition-all text-sm text-left shadow-sm border border-transparent flex items-center gap-3
                                        ${isActive 
                                            ? 'bg-teal-100 dark:bg-teal-900 text-teal-800 dark:text-teal-200 ring-1 ring-teal-500' 
                                            : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600'}
                                    `}
                                >
                                    <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isActive ? 'bg-teal-500 text-white' : 'bg-slate-200 dark:bg-slate-600'}`}>{idx + 1}</span>
                                    <span className="truncate">{sec.title}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Main Dock Bar */}
            <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={() => !isDockExpanded && setIsDockExpanded(true)}
            >
                {isDockExpanded ? (
                    <>
                        {/* Fullscreen Toggle */}
                        {isFullscreen && (
                            <>
                                <button onClick={() => setIsFullscreen(false)} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white" title="Thoát toàn màn hình">
                                    <Minimize className="w-5 h-5" />
                                </button>
                                <div className="w-px h-6 bg-white/20 mx-1"></div>
                            </>
                        )}

                        {/* View Mode Switcher */}
                        <button 
                            onClick={() => setViewMode(prev => prev === 'slide' ? 'doc' : 'slide')}
                            className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-teal-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title={viewMode === 'slide' ? "Chuyển sang chế độ Văn bản" : "Chuyển sang chế độ Trình chiếu"}
                        >
                            {viewMode === 'slide' ? <Presentation className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                        </button>

                         {/* Zoom Tools */}
                         <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-teal-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-teal-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                        {/* Laser Pointer */}
                        <button 
                            onClick={() => setIsLaserPointer(!isLaserPointer)}
                            className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Bật/Tắt Laser Pointer"
                        >
                            <MousePointer2 className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Navigation / TOC */}
                        <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-teal-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Mục lục">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                        {/* Blackboard */}
                        <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                        {/* Random Picker */}
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Close / Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <Menu className="w-5 h-5" />
                    </div>
                )}
            </div>
        </div>

        {/* --- MODALS --- */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation, FileText, Printer, FileJson, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut, RefreshCw } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // State logic
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');

  // UI/Tool State
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Prevent interfering with inputs if any
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

        if (viewMode === 'slide') {
            if (e.key === 'ArrowRight' || e.key === 'Space') {
                handleNextAction();
            } else if (e.key === 'ArrowLeft') {
                handlePrevAction();
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide, slideStep, viewMode, slides.length]);

  // Fullscreen Handler
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        // Cast to any to avoid potential TS issues with requestFullscreen in some environments
        (containerRef.current as any).requestFullscreen().catch((err: any) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const handlePrevAction = () => {
    if (slideStep > 1) {
        setSlideStep(s => s - 1);
    } else if (currentSlide > 0) {
        setCurrentSlide(c => c - 1);
        setSlideStep(3); // Go to end of previous slide
    }
  };

  const handleNextAction = () => {
    if (slideStep < 3) {
        setSlideStep(s => s + 1);
    } else if (currentSlide < slides.length - 1) {
        setCurrentSlide(c => c + 1);
        setSlideStep(1); // Go to start of next slide
    }
  };

  const jumpToSlide = (idx: number) => {
      setCurrentSlide(idx);
      setSlideStep(1);
      setShowNav(false);
      if (viewMode === 'doc') {
          // Scroll to element in doc mode
          const el = document.getElementById(`section-${idx}`);
          if (el) el.scrollIntoView({ behavior: 'smooth' });
      }
  };

  const handleExportJSON = () => {
    const exportData = {
        type: 'theory',
        timestamp: Date.now(),
        config,
        data
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `lecture-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const renderSlideContent = (section: TheorySection) => {
     // Scaling style
     const scaleStyle = { fontSize: `${zoomLevel * 100}%` };

     return (
        <div className="flex flex-col h-full p-8 md:p-12 lg:p-16 max-w-6xl mx-auto justify-center" style={scaleStyle}>
            {/* 1. Title */}
            <div className={`transition-all duration-500 transform ${slideStep >= 1 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <h2 className="text-4xl md:text-5xl font-black text-teal-700 dark:text-teal-400 mb-8 border-b-4 border-teal-500 pb-4 inline-block">
                    {section.title}
                </h2>
            </div>

            {/* 2. Theory Content */}
            <div className={`flex-1 overflow-y-auto mb-8 transition-all duration-500 delay-100 transform ${slideStep >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <div className="text-2xl md:text-3xl text-slate-700 dark:text-slate-200 leading-relaxed space-y-4 font-medium">
                     <MathRenderer content={section.content} />
                </div>
            </div>

            {/* 3. Example */}
            <div className={`bg-slate-100 dark:bg-slate-800 p-6 rounded-2xl border-l-8 border-teal-500 shadow-lg transition-all duration-500 delay-200 transform ${slideStep >= 3 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                <div className="flex items-center gap-3 mb-3">
                    <span className="bg-teal-600 text-white font-bold px-3 py-1 rounded text-sm uppercase tracking-wider">Ví dụ</span>
                    <span className="text-slate-500 dark:text-slate-400 text-sm font-semibold italic">Minh họa điển hình</span>
                </div>
                {section.examples && section.examples.length > 0 && (
                    <div className="space-y-4">
                        <div className="text-xl text-slate-800 dark:text-slate-100 font-bold">
                            <MathRenderer content={section.examples[0].problem} />
                        </div>
                        <div className="text-lg text-slate-600 dark:text-slate-300 border-t border-slate-200 dark:border-slate-700 pt-3">
                            <span className="font-bold text-teal-700 dark:text-teal-400">Giải: </span>
                            <MathRenderer content={section.examples[0].solution} />
                        </div>
                        <div className="text-base text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-900 p-3 rounded-lg italic border border-slate-200 dark:border-slate-700">
                             💡 <span className="font-semibold">Mấu chốt:</span> {section.examples[0].explanation}
                        </div>
                    </div>
                )}
            </div>
        </div>
     );
  };

  return (
    <div 
        ref={containerRef}
        className={`
            bg-slate-50 dark:bg-slate-900 font-sans selection:bg-teal-100 selection:text-teal-800 dark:selection:bg-teal-900 dark:selection:text-teal-200 relative transition-all duration-300
            ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}
            ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
            ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full' : ''}
        `}
    >

        {/* Content Wrapper for Side Mode */}
        <div className={`
             transition-all duration-300 ease-in-out h-full flex flex-col
             ${showBlackboard && blackboardMode === 'side' 
                ? 'w-[50vw] h-screen fixed left-0 top-0 overflow-hidden z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl bg-slate-50 dark:bg-slate-900' 
                : 'w-full'}
        `}>

            {/* Top Toolbar - Hidden in Fullscreen */}
            <div className={`bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-30 shadow-sm no-print transition-all ${isFullscreen ? 'hidden' : ''}`}>
                <div className="flex items-center gap-4">
                    <button onClick={onReset} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                    </button>
                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-700"></div>
                    <button onClick={onRegenerate} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-teal-600 dark:text-teal-400 hover:bg-teal-50 dark:hover:bg-teal-900/20 border border-transparent hover:border-teal-100 dark:hover:border-teal-800 transition-colors">
                        <RefreshCw className="w-4 h-4" /> <span className="hidden sm:inline">Tạo lại bài giảng</span>
                    </button>
                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-700"></div>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setViewMode('slide')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <Presentation className="w-4 h-4" /> Slide
                        </button>
                        <button 
                            onClick={() => setViewMode('doc')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'doc' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <FileText className="w-4 h-4" /> Tài liệu
                        </button>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={handleExportJSON}
                        className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700"
                    >
                        <FileJson className="w-4 h-4" /> <span className="hidden sm:inline">JSON</span>
                    </button>
                    <button 
                        onClick={() => window.print()}
                        className="flex items-center gap-2 px-3 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg font-bold text-sm shadow-sm transition-colors"
                    >
                        <Printer className="w-4 h-4" /> <span className="hidden sm:inline">In ấn</span>
                    </button>
                </div>
            </div>

            {/* Main Content Area */}
            <div className={`flex-grow overflow-hidden relative ${isFullscreen ? 'h-full' : ''}`}>
                {viewMode === 'doc' ? (
                    <div className="h-full overflow-y-auto custom-scrollbar">
                        <div className="max-w-4xl mx-auto p-6 md:p-12 pb-24">
                            <div className="text-center mb-10 border-b-2 border-teal-100 dark:border-teal-900 pb-6">
                                <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-4">{data.topic}</h1>
                                <p className="text-lg text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">{data.overview}</p>
                            </div>
                            <div className="space-y-12">
                                {data.sections.map((sec, idx) => (
                                    <div id={`section-${idx}`} key={idx} className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 break-inside-avoid scroll-mt-20">
                                        <h3 className="text-2xl font-bold text-teal-700 dark:text-teal-400 mb-6 flex items-center gap-3">
                                            <span className="w-8 h-8 rounded-full bg-teal-100 dark:bg-teal-900/50 flex items-center justify-center text-sm">{idx + 1}</span>
                                            {sec.title}
                                        </h3>
                                        <div className="text-lg text-slate-800 dark:text-slate-200 mb-6 space-y-2">
                                            <MathRenderer content={sec.content} />
                                        </div>
                                        {sec.examples && sec.examples.map((ex, i) => (
                                            <div key={i} className="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-xl border border-slate-200 dark:border-slate-700">
                                                <div className="font-bold text-slate-900 dark:text-slate-100 mb-2">Ví dụ:</div>
                                                <div className="mb-2"><MathRenderer content={ex.problem} /></div>
                                                <div className="pl-4 border-l-4 border-teal-300 dark:border-teal-700 text-slate-700 dark:text-slate-300">
                                                    <MathRenderer content={ex.solution} />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center relative">
                        {/* Slide Content */}
                        <div key={currentSlide} className="w-full h-full animate-fade-in">
                            {renderSlideContent(slides[currentSlide])}
                        </div>

                        {/* Navigation Arrows (Bottom Corners) */}
                        <button 
                            onClick={handlePrevAction} 
                            disabled={currentSlide === 0 && slideStep === 1} 
                            className="fixed left-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Lùi lại"
                        >
                            <ChevronLeft className="w-8 h-8 group-hover:-translate-x-1 transition-transform" />
                        </button>

                        <button 
                            onClick={handleNextAction} 
                            disabled={currentSlide === slides.length - 1 && slideStep >= 3} 
                            className="fixed right-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Tiếp tục"
                        >
                            <ChevronRight className="w-8 h-8 group-hover:translate-x-1 transition-transform" />
                        </button>

                        {/* Progress Indicator (Bottom Center) - Only visible if Dock is collapsed or not conflicting */}
                        <div className="absolute bottom-6 left-0 right-0 flex justify-center pointer-events-none">
                             <div className="flex flex-col items-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-md px-4 py-2 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-sm">
                                <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">
                                    Slide {currentSlide + 1} / {slides.length}
                                </span>
                                <div className="flex gap-1.5">
                                    {[1, 2, 3].map(step => (
                                        <div key={step} className={`h-1.5 w-1.5 rounded-full transition-all duration-300 ${step <= slideStep ? 'bg-teal-500 scale-110' : 'bg-slate-300 dark:bg-slate-600'}`} />
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* --- DOCK --- */}
        <div className="no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-300">

            {/* Navigation Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Mục lục bài giảng</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="flex flex-col gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar">
                        {slides.map((sec, idx) => {
                            const isActive = idx === currentSlide;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToSlide(idx)}
                                    className={`p-3 rounded-xl font-medium transition-all text-sm text-left shadow-sm border border-transparent flex items-center gap-3
                                        ${isActive 
                                            ? 'bg-teal-100 dark:bg-teal-900 text-teal-800 dark:text-teal-200 ring-1 ring-teal-500' 
                                            : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600'}
                                    `}
                                >
                                    <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isActive ? 'bg-teal-500 text-white' : 'bg-slate-200 dark:bg-slate-600'}`}>{idx + 1}</span>
                                    <span className="truncate">{sec.title}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Main Dock Bar */}
            <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={() => !isDockExpanded && setIsDockExpanded(true)}
            >
                {isDockExpanded ? (
                    <>
                        {/* Fullscreen Toggle */}
                        {isFullscreen && (
                            <>
                                <button onClick={() => setIsFullscreen(false)} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white" title="Thoát toàn màn hình">
                                    <Minimize className="w-5 h-5" />
                                </button>
                                <div className="w-px h-6 bg-white/20 mx-1"></div>
                            </>
                        )}

                        {/* View Mode Switcher */}
                        <button 
                            onClick={() => setViewMode(prev => prev === 'slide' ? 'doc' : 'slide')}
                            className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-teal-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title={viewMode === 'slide' ? "Chuyển sang chế độ Văn bản" : "Chuyển sang chế độ Trình chiếu"}
                        >
                            {viewMode === 'slide' ? <Presentation className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                        </button>

                         {/* Zoom Tools */}
                         <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-teal-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-teal-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                        {/* Laser Pointer */}
                        <button 
                            onClick={() => setIsLaserPointer(!isLaserPointer)}
                            className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Bật/Tắt Laser Pointer"
                        >
                            <MousePointer2 className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Navigation / TOC */}
                        <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-teal-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Mục lục">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                        {/* Blackboard */}
                        <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                        {/* Random Picker */}
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Close / Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <Menu className="w-5 h-5" />
                    </div>
                )}
            </div>
        </div>

        {/* --- MODALS --- */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation, FileText, Printer, FileJson, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut, RefreshCw, Palette } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

// Color Themes configuration
const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc',
    bg: 'bg-teal-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-teal-700 dark:text-teal-400', 
    accent: 'text-teal-600',
    border: 'border-teal-500', 
    highlightBg: 'bg-teal-100 dark:bg-teal-900/50',
    highlightText: 'text-teal-800 dark:text-teal-200',
    exampleBg: 'bg-white dark:bg-slate-800',
    exampleBorder: 'border-teal-400'
  },
  blue: { 
    name: 'Xanh Dương',
    bg: 'bg-blue-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-blue-700 dark:text-blue-400', 
    accent: 'text-blue-600',
    border: 'border-blue-500', 
    highlightBg: 'bg-blue-100 dark:bg-blue-900/50',
    highlightText: 'text-blue-800 dark:text-blue-200',
    exampleBg: 'bg-white dark:bg-slate-800',
    exampleBorder: 'border-blue-400'
  },
  violet: { 
    name: 'Tím Mộng Mơ',
    bg: 'bg-violet-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-violet-700 dark:text-violet-400', 
    accent: 'text-violet-600',
    border: 'border-violet-500', 
    highlightBg: 'bg-violet-100 dark:bg-violet-900/50',
    highlightText: 'text-violet-800 dark:text-violet-200',
    exampleBg: 'bg-white dark:bg-slate-800',
    exampleBorder: 'border-violet-400'
  },
  rose: { 
    name: 'Hồng Phấn',
    bg: 'bg-rose-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-rose-700 dark:text-rose-400', 
    accent: 'text-rose-600',
    border: 'border-rose-500', 
    highlightBg: 'bg-rose-100 dark:bg-rose-900/50',
    highlightText: 'text-rose-800 dark:text-rose-200',
    exampleBg: 'bg-white dark:bg-slate-800',
    exampleBorder: 'border-rose-400'
  },
  amber: { 
    name: 'Cam Vàng',
    bg: 'bg-amber-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-amber-700 dark:text-amber-400', 
    accent: 'text-amber-600',
    border: 'border-amber-500', 
    highlightBg: 'bg-amber-100 dark:bg-amber-900/50',
    highlightText: 'text-amber-800 dark:text-amber-200',
    exampleBg: 'bg-white dark:bg-slate-800',
    exampleBorder: 'border-amber-400'
  },
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // State logic
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');

  // UI/Tool State
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1);

  // Theme State
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showThemePicker, setShowThemePicker] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Prevent interfering with inputs if any
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

        if (viewMode === 'slide') {
            if (e.key === 'ArrowRight' || e.key === 'Space') {
                handleNextAction();
            } else if (e.key === 'ArrowLeft') {
                handlePrevAction();
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide, slideStep, viewMode, slides.length]);

  // Close popovers when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showThemePicker && !target.closest('.theme-picker-container') && !target.closest('.theme-toggle-btn')) {
        setShowThemePicker(false);
      }
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showThemePicker, showNav]);

  // Fullscreen Handler
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        // Cast to any to avoid potential TS issues with requestFullscreen in some environments
        (containerRef.current as any).requestFullscreen().catch((err: any) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const handlePrevAction = () => {
    if (slideStep > 1) {
        setSlideStep(s => s - 1);
    } else if (currentSlide > 0) {
        setCurrentSlide(c => c - 1);
        setSlideStep(3); // Go to end of previous slide
    }
  };

  const handleNextAction = () => {
    if (slideStep < 3) {
        setSlideStep(s => s + 1);
    } else if (currentSlide < slides.length - 1) {
        setCurrentSlide(c => c + 1);
        setSlideStep(1); // Go to start of next slide
    }
  };

  const jumpToSlide = (idx: number) => {
      setCurrentSlide(idx);
      setSlideStep(1);
      setShowNav(false);
      if (viewMode === 'doc') {
          // Scroll to element in doc mode
          const el = document.getElementById(`section-${idx}`);
          if (el) el.scrollIntoView({ behavior: 'smooth' });
      }
  };

  const handleExportJSON = () => {
    const exportData = {
        type: 'theory',
        timestamp: Date.now(),
        config,
        data
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `lecture-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const renderSlideContent = (section: TheorySection) => {
     // Scaling style
     const scaleStyle = { fontSize: `${zoomLevel * 100}%` };
     const theme = SLIDE_THEMES[activeTheme];

     return (
        <div className={`flex flex-col h-full w-full px-6 md:px-16 py-8 md:py-12 ${theme.bg}`} style={scaleStyle}>
            {/* 1. Title Area */}
            <div className={`flex-shrink-0 mb-6 transition-all duration-700 transform ${slideStep >= 1 ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`}>
                <h2 className={`text-4xl md:text-6xl font-black ${theme.primary} leading-tight border-l-8 ${theme.border} pl-6`}>
                    {section.title}
                </h2>
            </div>

            {/* 2. Theory Content Area - Maximize space */}
            <div className={`flex-1 overflow-y-auto mb-6 pr-4 custom-scrollbar transition-all duration-700 delay-100 transform ${slideStep >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
                {/* 
                   Dynamic styling for strong tags using Tailwind arbitrary variants on the parent.
                   We target the child <strong> tags generated by MathRenderer.
                */}
                <div className={`
                    text-3xl md:text-4xl ${theme.text} leading-relaxed font-medium space-y-6
                    [&_strong]:font-black 
                    [&_strong]:${theme.highlightText.replace(' ', ' [&_strong]:')} 
                    [&_strong]:${theme.highlightBg.replace(' ', ' [&_strong]:')}
                    [&_strong]:px-2 [&_strong]:py-0.5 [&_strong]:rounded-lg [&_strong]:box-decoration-clone
                    [&_ul]:list-none
                `}>
                     <MathRenderer content={section.content} />
                </div>
            </div>

            {/* 3. Example Area - Distinct block at bottom */}
            <div className={`flex-shrink-0 mt-auto transition-all duration-700 delay-200 transform ${slideStep >= 3 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
                {section.examples && section.examples.length > 0 && (
                    <div className={`${theme.exampleBg} p-6 md:p-8 rounded-3xl border-2 ${theme.exampleBorder} shadow-xl relative overflow-hidden`}>
                        {/* Decorative background element */}
                        <div className={`absolute top-0 right-0 w-32 h-32 ${theme.highlightBg} rounded-bl-full -mr-10 -mt-10 opacity-50`}></div>

                        <div className="relative z-10">
                            <div className="flex items-center gap-3 mb-4">
                                <span className={`px-4 py-1.5 rounded-full text-white font-bold uppercase text-sm tracking-wider bg-gradient-to-r from-slate-700 to-slate-600 shadow-md`}>
                                    Ví dụ minh họa
                                </span>
                            </div>

                            <div className="flex flex-col md:flex-row gap-6 md:items-start">
                                <div className="flex-1">
                                    <div className={`text-2xl md:text-3xl font-bold ${theme.primary} mb-2`}>
                                        <MathRenderer content={section.examples[0].problem} />
                                    </div>
                                    <div className={`text-xl md:text-2xl ${theme.text} border-t ${theme.border} pt-3 mt-3 opacity-90`}>
                                        <span className="font-bold underline decoration-2 underline-offset-4">Giải:</span> <MathRenderer content={section.examples[0].solution} />
                                    </div>
                                </div>
                                <div className={`md:w-1/3 p-4 rounded-xl ${theme.highlightBg} border ${theme.border} border-opacity-30`}>
                                     <div className={`text-lg font-bold ${theme.accent} flex items-center gap-2 mb-1`}>
                                        <Lightbulb className="w-5 h-5" /> Mấu chốt:
                                     </div>
                                     <div className={`text-lg ${theme.text} italic leading-snug`}>
                                        {section.examples[0].explanation}
                                     </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
     );
  };

  const Lightbulb = ({className}: {className?: string}) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
      <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-1 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5" />
      <path d="M9 18h6" />
      <path d="M10 22h4" />
    </svg>
  );

  return (
    <div 
        ref={containerRef}
        className={`
            bg-slate-50 dark:bg-slate-900 font-sans selection:bg-teal-100 selection:text-teal-800 dark:selection:bg-teal-900 dark:selection:text-teal-200 relative transition-all duration-300
            ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}
            ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
            ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full' : ''}
        `}
    >

        {/* Content Wrapper for Side Mode */}
        <div className={`
             transition-all duration-300 ease-in-out h-full flex flex-col
             ${showBlackboard && blackboardMode === 'side' 
                ? 'w-[50vw] h-screen fixed left-0 top-0 overflow-hidden z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl bg-slate-50 dark:bg-slate-900' 
                : 'w-full'}
        `}>

            {/* Top Toolbar - Hidden in Fullscreen */}
            <div className={`bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-30 shadow-sm no-print transition-all ${isFullscreen ? 'hidden' : ''}`}>
                <div className="flex items-center gap-4">
                    <button onClick={onReset} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                    </button>
                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-700"></div>
                    <button onClick={onRegenerate} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-teal-600 dark:text-teal-400 hover:bg-teal-50 dark:hover:bg-teal-900/20 border border-transparent hover:border-teal-100 dark:hover:border-teal-800 transition-colors">
                        <RefreshCw className="w-4 h-4" /> <span className="hidden sm:inline">Tạo lại bài giảng</span>
                    </button>
                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-700"></div>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setViewMode('slide')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <Presentation className="w-4 h-4" /> Slide
                        </button>
                        <button 
                            onClick={() => setViewMode('doc')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'doc' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <FileText className="w-4 h-4" /> Tài liệu
                        </button>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={handleExportJSON}
                        className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700"
                    >
                        <FileJson className="w-4 h-4" /> <span className="hidden sm:inline">JSON</span>
                    </button>
                    <button 
                        onClick={() => window.print()}
                        className="flex items-center gap-2 px-3 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg font-bold text-sm shadow-sm transition-colors"
                    >
                        <Printer className="w-4 h-4" /> <span className="hidden sm:inline">In ấn</span>
                    </button>
                </div>
            </div>

            {/* Main Content Area */}
            <div className={`flex-grow overflow-hidden relative ${isFullscreen ? 'h-full' : ''}`}>
                {viewMode === 'doc' ? (
                    <div className="h-full overflow-y-auto custom-scrollbar">
                        <div className="max-w-4xl mx-auto p-6 md:p-12 pb-24">
                            <div className="text-center mb-10 border-b-2 border-teal-100 dark:border-teal-900 pb-6">
                                <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-4">{data.topic}</h1>
                                <p className="text-lg text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">{data.overview}</p>
                            </div>
                            <div className="space-y-12">
                                {data.sections.map((sec, idx) => (
                                    <div id={`section-${idx}`} key={idx} className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 break-inside-avoid scroll-mt-20">
                                        <h3 className="text-2xl font-bold text-teal-700 dark:text-teal-400 mb-6 flex items-center gap-3">
                                            <span className="w-8 h-8 rounded-full bg-teal-100 dark:bg-teal-900/50 flex items-center justify-center text-sm">{idx + 1}</span>
                                            {sec.title}
                                        </h3>
                                        <div className="text-lg text-slate-800 dark:text-slate-200 mb-6 space-y-2">
                                            <MathRenderer content={sec.content} />
                                        </div>
                                        {sec.examples && sec.examples.map((ex, i) => (
                                            <div key={i} className="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-xl border border-slate-200 dark:border-slate-700">
                                                <div className="font-bold text-slate-900 dark:text-slate-100 mb-2">Ví dụ:</div>
                                                <div className="mb-2"><MathRenderer content={ex.problem} /></div>
                                                <div className="pl-4 border-l-4 border-teal-300 dark:border-teal-700 text-slate-700 dark:text-slate-300">
                                                    <MathRenderer content={ex.solution} />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center relative bg-black">
                        {/* Slide Content */}
                        <div key={currentSlide} className="w-full h-full animate-fade-in bg-white dark:bg-slate-900">
                            {renderSlideContent(slides[currentSlide])}
                        </div>

                        {/* Navigation Arrows (Bottom Corners) */}
                        <button 
                            onClick={handlePrevAction} 
                            disabled={currentSlide === 0 && slideStep === 1} 
                            className="fixed left-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Lùi lại"
                        >
                            <ChevronLeft className="w-8 h-8 group-hover:-translate-x-1 transition-transform" />
                        </button>

                        <button 
                            onClick={handleNextAction} 
                            disabled={currentSlide === slides.length - 1 && slideStep >= 3} 
                            className="fixed right-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                            title="Tiếp tục"
                        >
                            <ChevronRight className="w-8 h-8 group-hover:translate-x-1 transition-transform" />
                        </button>

                        {/* Progress Indicator (Bottom Center) */}
                        <div className="absolute bottom-6 left-0 right-0 flex justify-center pointer-events-none">
                             <div className="flex flex-col items-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-md px-4 py-2 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-sm">
                                <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">
                                    Slide {currentSlide + 1} / {slides.length}
                                </span>
                                <div className="flex gap-1.5">
                                    {[1, 2, 3].map(step => (
                                        <div key={step} className={`h-1.5 w-1.5 rounded-full transition-all duration-300 ${step <= slideStep ? 'bg-teal-500 scale-110' : 'bg-slate-300 dark:bg-slate-600'}`} />
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* --- DOCK --- */}
        <div className="no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-300">

            {/* Theme Picker Popover */}
            {isDockExpanded && showThemePicker && (
               <div className="mb-4 w-64 bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up theme-picker-container">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 mb-3 text-center text-sm uppercase tracking-wide">Chọn màu Slide</h3>
                    <div className="grid grid-cols-5 gap-2">
                        {Object.entries(SLIDE_THEMES).map(([key, theme]) => (
                            <button
                                key={key}
                                onClick={() => { setActiveTheme(key as ThemeKey); setShowThemePicker(false); }}
                                className={`w-10 h-10 rounded-full border-2 transition-transform hover:scale-110 shadow-sm flex items-center justify-center
                                    ${activeTheme === key ? 'border-slate-800 dark:border-white scale-110' : 'border-transparent'}
                                `}
                                style={{ background: key === 'teal' ? '#0d9488' : key === 'blue' ? '#2563eb' : key === 'violet' ? '#7c3aed' : key === 'rose' ? '#e11d48' : '#d97706' }}
                                title={theme.name}
                            >
                                {activeTheme === key && <div className="w-2 h-2 bg-white rounded-full" />}
                            </button>
                        ))}
                    </div>
               </div>
            )}

            {/* Navigation Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Mục lục bài giảng</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="flex flex-col gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar">
                        {slides.map((sec, idx) => {
                            const isActive = idx === currentSlide;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToSlide(idx)}
                                    className={`p-3 rounded-xl font-medium transition-all text-sm text-left shadow-sm border border-transparent flex items-center gap-3
                                        ${isActive 
                                            ? 'bg-teal-100 dark:bg-teal-900 text-teal-800 dark:text-teal-200 ring-1 ring-teal-500' 
                                            : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600'}
                                    `}
                                >
                                    <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isActive ? 'bg-teal-500 text-white' : 'bg-slate-200 dark:bg-slate-600'}`}>{idx + 1}</span>
                                    <span className="truncate">{sec.title}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Main Dock Bar */}
            <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={() => !isDockExpanded && setIsDockExpanded(true)}
            >
                {isDockExpanded ? (
                    <>
                        {/* Fullscreen Toggle */}
                        {isFullscreen && (
                            <>
                                <button onClick={() => setIsFullscreen(false)} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white" title="Thoát toàn màn hình">
                                    <Minimize className="w-5 h-5" />
                                </button>
                                <div className="w-px h-6 bg-white/20 mx-1"></div>
                            </>
                        )}

                        {/* View Mode Switcher */}
                        <button 
                            onClick={() => setViewMode(prev => prev === 'slide' ? 'doc' : 'slide')}
                            className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-teal-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title={viewMode === 'slide' ? "Chuyển sang chế độ Văn bản" : "Chuyển sang chế độ Trình chiếu"}
                        >
                            {viewMode === 'slide' ? <Presentation className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                        </button>

                        {/* Theme Picker Button */}
                        <button 
                            onClick={() => setShowThemePicker(!showThemePicker)}
                            className={`theme-toggle-btn p-3 rounded-full transition-colors ${showThemePicker ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Đổi màu Slide"
                        >
                            <Palette className="w-5 h-5" />
                        </button>

                         {/* Zoom Tools */}
                         <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-teal-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-teal-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                        {/* Laser Pointer */}
                        <button 
                            onClick={() => setIsLaserPointer(!isLaserPointer)}
                            className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Bật/Tắt Laser Pointer"
                        >
                            <MousePointer2 className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Navigation / TOC */}
                        <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-teal-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Mục lục">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                        {/* Blackboard */}
                        <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                        {/* Random Picker */}
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Close / Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <Menu className="w-5 h-5" />
                    </div>
                )}
            </div>
        </div>

        {/* --- MODALS --- */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
