                                className="fixed left-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
