type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // State logic
  const [currentSlide, setCurrentSlide] = useState(0);

  // slideStep: 1 = Theory View, 2 = Example View
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');

  // Interaction State for Solution
  const [showExampleSolution, setShowExampleSolution] = useState(false);

  // UI/Tool State
  const [showControls, setShowControls] = useState(true); // Toggle Header/Dock
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [isExporting, setIsExporting] = useState(false);

  // Theme State
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showThemePicker, setShowThemePicker] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  // Reset example solution visibility when slide changes
  useEffect(() => {
    setShowExampleSolution(false);
  }, [currentSlide, slideStep]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Prevent interfering with inputs if any
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

        if (viewMode === 'slide') {
            if (e.key === 'ArrowRight' || e.key === 'Space') {
                handleNextAction();
            } else if (e.key === 'ArrowLeft') {
                handlePrevAction();
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide, slideStep, viewMode, slides.length]);

  // Close popovers when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showThemePicker && !target.closest('.theme-picker-container') && !target.closest('.theme-toggle-btn')) {
        setShowThemePicker(false);
      }
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showThemePicker, showNav]);

  // Fullscreen Handler
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        // Cast to any to avoid potential TS issues with requestFullscreen in some environments
        (containerRef.current as any).requestFullscreen().catch((err: any) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const handlePrevAction = () => {
    // If currently in Example view (step 2), go back to Theory view (step 1) of SAME slide
    if (slideStep === 2) {
        setSlideStep(1);
    } 
    // If currently in Theory view (step 1), go to previous slide
    else if (currentSlide > 0) {
        // If previous slide has examples, go to its Example view (step 2)
        // Otherwise go to its Theory view (step 1)
        const prevSlideIdx = currentSlide - 1;
        const hasExamples = slides[prevSlideIdx].examples && slides[prevSlideIdx].examples.length > 0;
        setCurrentSlide(prevSlideIdx);
        setSlideStep(hasExamples ? 2 : 1);
    }
  };

  const handleNextAction = () => {
    const currentSection = slides[currentSlide];
    const hasExamples = currentSection.examples && currentSection.examples.length > 0;

    // If currently in Theory view (step 1) AND examples exist, go to Example view (step 2)
    if (slideStep === 1 && hasExamples) {
        setSlideStep(2);
    } 
    // Otherwise (if already in Example view, or no examples), go to Next Slide
    else if (currentSlide < slides.length - 1) {
        setCurrentSlide(prev => prev + 1);
        setSlideStep(1);
    }
  };

  const jumpToSlide = (idx: number) => {
      setCurrentSlide(idx);
      setSlideStep(1);
      setShowNav(false);
      if (viewMode === 'doc') {
          // Scroll to element in doc mode
          const el = document.getElementById(`section-${idx}`);
          if (el) el.scrollIntoView({ behavior: 'smooth' });
      }
  };

  const handleExportJSON = () => {
    const exportData = {
        type: 'theory',
        timestamp: Date.now(),
        config,
        data
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const saveFunc = (FileSaver as any).saveAs || FileSaver;
    saveFunc(blob, `Bai_Giang_${config.subject}_${Date.now()}.json`);
  };

  const handleDownloadWord = async () => {
    setIsExporting(true);
    try {
        const sections = data.sections.map((sec, idx) => {
            const contentParagraphs = sec.content.split('\n')
                .filter(line => line.trim() !== '')
                .map(line => {
                    // Remove starting stars or bullets if present
                    const cleanLine = line.replace(/^[★•\-\s]+/, '').trim().replace(/\*\*/g, '');
                    return new Paragraph({
                        text: cleanLine,
                        bullet: { level: 0 },
                        spacing: { after: 120 }
                    });
                });

            const exampleContent = [];
            if (sec.examples && sec.examples.length > 0) {
                sec.examples.forEach(ex => {
                     exampleContent.push(
                         new Paragraph({ 
                             text: "Ví dụ minh họa:", 
                             heading: HeadingLevel.HEADING_3,
                             spacing: { before: 200, after: 100 },
                             color: "2E7D32" 
                         }),
                         new Paragraph({ 
                             children: [new TextRun({ text: ex.problem.replace(/\*\*/g, ''), italics: true })],
                             spacing: { after: 100 }
                         }),
                         new Paragraph({ 
                            children: [new TextRun({ text: "Lời giải:", bold: true })],
                            spacing: { after: 50 }
                        }),
                        new Paragraph({ 
                            text: ex.solution.replace(/\*\*/g, ''),
                            spacing: { after: 100 }
                        }),
                        new Paragraph({ 
                            children: [new TextRun({ text: "Giải thích mấu chốt: ", bold: true }), new TextRun({ text: ex.explanation.replace(/\*\*/g, '') })],
                            spacing: { after: 300 }
                        })
                     );
                });
            }

            return [
                new Paragraph({ 
                    text: `${idx + 1}. ${sec.title}`, 
                    heading: HeadingLevel.HEADING_2,
                    spacing: { before: 400, after: 200 }
                }),
                ...contentParagraphs,
                ...exampleContent
            ];
        }).flat();

        const doc = new Document({
            creator: "Smart Practice Exam Studio",
            title: data.topic,
            sections: [{
                properties: {},
                children: [
                    new Paragraph({ text: data.topic.toUpperCase(), heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }),
                    new Paragraph({ text: `Môn: ${config.subject} | ${config.grade}`, alignment: AlignmentType.CENTER }),
                    new Paragraph({ text: data.overview, alignment: AlignmentType.CENTER, spacing: { after: 400, before: 200 }, italics: true }),
                    ...sections
                ],
            }],
        });

        const blob = await Packer.toBlob(doc);
        const saveFunc = (FileSaver as any).saveAs || FileSaver;
        saveFunc(blob, `Bai_Giang_${config.subject}_${Date.now()}.docx`);
    } catch (e) {
        console.error(e);
        alert("Có lỗi khi tạo file Word.");
    } finally {
        setIsExporting(false);
    }
  };

  const renderSlideContent = (section: TheorySection) => {
     // Use Zoom property for scaling
     const scaleStyle = { zoom: zoomLevel } as any;
     const theme = SLIDE_THEMES[activeTheme];

     // Split content by newline to create list items
     const contentLines = section.content.split('\n').filter(line => line.trim() !== '');

     return (
        <div className={`flex flex-col h-full w-full px-6 md:px-16 py-8 md:py-12 ${theme.bg}`} style={scaleStyle}>
            {/* Slide Title - Always visible but maybe slightly different style for Example view */}
            <div className={`flex-shrink-0 mb-6 transition-all duration-500`}>
                <h2 className={`text-4xl md:text-5xl font-black ${theme.primary} leading-tight border-l-8 ${theme.border} pl-6`}>
                    {section.title}
                    {slideStep === 2 && <span className="text-slate-400 font-medium text-3xl ml-4 block md:inline md:mt-0 mt-2">- Ví dụ minh họa</span>}
                </h2>
            </div>

            {/* --- VIEW 1: THEORY CONTENT --- */}
            {slideStep === 1 && (
                <div className="flex-1 overflow-y-auto pr-4 custom-scrollbar animate-fade-in-up">
                    <div className={`
                        text-3xl md:text-4xl ${theme.text} leading-relaxed font-medium space-y-6
                        [&_strong]:font-black 
                        [&_strong]:${theme.highlightText.replace(' ', ' [&_strong]:')} 
                        [&_strong]:${theme.highlightBg.replace(' ', ' [&_strong]:')}
                        [&_strong]:px-2 [&_strong]:py-0.5 [&_strong]:rounded-lg [&_strong]:box-decoration-clone
                    `}>
                        {contentLines.map((line, idx) => {
                            const cleanLine = line.replace(/^[\s\u2022\u2605\-\*]+/, '').trim();
                            return (
                                <div key={idx} className="flex items-start gap-4">
                                    <div className={`flex-shrink-0 mt-2 ${theme.starColor}`}>
                                        <Star className="w-6 h-6 fill-current" />
                                    </div>
                                    <div className="flex-1">
                                        <MathRenderer content={cleanLine} />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* --- VIEW 2: EXAMPLE CONTENT (Full focus) --- */}
            {slideStep === 2 && section.examples && section.examples.length > 0 && (
                <div className="flex-1 overflow-y-auto animate-fade-in pr-2 pb-4">
                     <div className={`${theme.exampleBg} p-8 md:p-10 rounded-3xl border-2 ${theme.exampleBorder} shadow-2xl relative overflow-hidden transition-all duration-300 flex flex-col`}>
                        {/* Decorative background element */}
                        <div className={`absolute top-0 right-0 w-48 h-48 ${theme.highlightBg} rounded-bl-full -mr-16 -mt-16 opacity-50`}></div>

                        <div className="relative z-10 flex flex-col">
                            {/* Problem Statement */}
                            <div className="mb-6">
                                <div className={`text-3xl md:text-4xl font-bold ${theme.primary} leading-snug`}>
                                    <MathRenderer content={section.examples[0].problem} />
                                </div>
                            </div>

                            {/* Solution Section */}
                            <div className="border-t-2 border-dashed border-slate-200 dark:border-slate-700 pt-6 mt-2">
                                {!showExampleSolution ? (
                                    <div className="flex flex-col items-center justify-center py-4 gap-4">
                                        <p className="text-slate-400 italic text-lg">Học sinh suy nghĩ trước khi xem lời giải</p>
                                        <button 
                                            onClick={() => setShowExampleSolution(true)}
                                            className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-bold text-xl text-white shadow-xl transition-transform hover:scale-105 active:scale-95 ${theme.btnBg}`}
                                        >
                                            <Eye className="w-6 h-6" /> Xem lời giải chi tiết
                                        </button>
                                    </div>
                                ) : (
                                    <div className="animate-fade-in space-y-6">
                                        <div className={`text-2xl md:text-3xl ${theme.text}`}>
                                            <span className="font-bold underline decoration-4 underline-offset-4 text-emerald-600 dark:text-emerald-400 block mb-4">Lời giải:</span>
                                            <div className="pl-6 border-l-4 border-slate-200 dark:border-slate-700">
                                                <MathRenderer content={section.examples[0].solution} />
                                            </div>
                                        </div>

                                        <div className={`p-6 rounded-2xl ${theme.highlightBg} border ${theme.border} border-opacity-30 mt-6`}>
                                            <div className={`text-xl font-bold ${theme.accent} flex items-center gap-2 mb-2`}>
                                                <Lightbulb className="w-6 h-6 fill-current" /> Mấu chốt:
                                            </div>
                                            <div className={`text-xl ${theme.text} italic leading-snug`}>
                                                {section.examples[0].explanation}
                                            </div>
                                        </div>

                                        <div className="pt-2 text-center">
                                            <button 
                                                onClick={() => setShowExampleSolution(false)}
                                                className="text-base font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 flex items-center justify-center gap-2 mx-auto py-2"
                                            >
                                                <EyeOff className="w-5 h-5" /> Ẩn lời giải
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
     );
  };

  return (
    <div 
        ref={containerRef}
        className={`
            bg-slate-50 dark:bg-slate-900 font-sans selection:bg-teal-100 selection:text-teal-800 dark:selection:bg-teal-900 dark:selection:text-teal-200 relative transition-all duration-300
            ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}
            ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
            ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full' : ''}
        `}
    >

        {/* Content Wrapper for Side Mode */}
        <div className={`
             transition-all duration-300 ease-in-out h-full flex flex-col
             ${showBlackboard && blackboardMode === 'side' 
                ? 'w-[50vw] h-screen fixed left-0 top-0 overflow-hidden z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl bg-slate-50 dark:bg-slate-900' 
                : 'w-full'}
        `}>

            {/* --- TOP TOOLBAR (Auto-hide based on click) --- */}
            <div className={`
                bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-40 shadow-sm no-print transition-all duration-500 ease-in-out
                ${!showControls && viewMode === 'slide' ? '-translate-y-full opacity-0 absolute w-full' : 'translate-y-0 opacity-100'}
            `}>
                <div className="flex items-center gap-4 flex-1 overflow-hidden">
                    <button onClick={onReset} className="flex-shrink-0 flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                    </button>

                    {/* LESSON TOPIC TITLE */}
                    <div className="h-8 w-px bg-slate-300 dark:bg-slate-600 mx-2"></div>
                    <div className="flex items-center gap-2 overflow-hidden">
                        <BookOpen className="w-5 h-5 text-teal-600 dark:text-teal-400 flex-shrink-0" />
                        <h1 className="text-lg md:text-xl font-bold text-slate-800 dark:text-white truncate" title={data.topic}>
                            {data.topic}
                        </h1>
                    </div>
                </div>

                <div className="flex items-center gap-2 flex-shrink-0">
                    <div className="hidden md:flex gap-2 mr-2">
                        <button 
                            onClick={() => setViewMode('slide')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <Presentation className="w-4 h-4" /> Slide
                        </button>
                        <button 
                            onClick={() => setViewMode('doc')}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'doc' ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300 ring-1 ring-teal-200 dark:ring-teal-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <FileText className="w-4 h-4" /> Tài liệu
                        </button>
                    </div>

                    <div className="h-8 w-px bg-slate-200 dark:bg-slate-600 mx-1"></div>

                    <button 
                        onClick={handleExportJSON}
                        className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 shadow-sm transition-all"
                        title="Lưu file để chỉnh sửa sau này"
                    >
                        <Save className="w-4 h-4" /> <span className="hidden sm:inline">Lưu</span>
                    </button>

                    <button 
                        onClick={handleDownloadWord} 
                        disabled={isExporting} 
                        className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 dark:bg-blue-700 text-white hover:bg-blue-700 dark:hover:bg-blue-600 shadow-sm transition-all disabled:opacity-50"
                        title="Xuất bài giảng ra Word"
                    >
                        {isExporting ? <span className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></span> : <Download className="w-4 h-4" />} <span className="hidden sm:inline">Word</span>
                    </button>

                    <button 
                        onClick={() => window.print()}
                        className="flex items-center gap-2 px-3 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg font-bold text-sm shadow-sm transition-colors border border-slate-200 dark:border-slate-600"
                        title="In ấn"
                    >
                        <Printer className="w-4 h-4" />
                    </button>

                    <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Main Content Area */}
            <div className={`flex-grow overflow-hidden relative ${isFullscreen ? 'h-full' : ''}`}>
                {viewMode === 'doc' ? (
                    <div className="h-full overflow-y-auto custom-scrollbar">
                        <div className="max-w-4xl mx-auto p-6 md:p-12 pb-24">
                            <div className="text-center mb-10 border-b-2 border-teal-100 dark:border-teal-900 pb-6">
                                <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-4">{data.topic}</h1>
                                <p className="text-lg text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">{data.overview}</p>
                            </div>
                            <div className="space-y-12">
                                {data.sections.map((sec, idx) => (
                                    <div id={`section-${idx}`} key={idx} className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 break-inside-avoid scroll-mt-20">
                                        <h3 className="text-2xl font-bold text-teal-700 dark:text-teal-400 mb-6 flex items-center gap-3">
                                            <span className="w-8 h-8 rounded-full bg-teal-100 dark:bg-teal-900/50 flex items-center justify-center text-sm">{idx + 1}</span>
                                            {sec.title}
                                        </h3>
                                        <div className="text-lg text-slate-800 dark:text-slate-200 mb-6 space-y-2">
                                            <MathRenderer content={sec.content} />
                                        </div>
                                        {sec.examples && sec.examples.map((ex, i) => (
                                            <div key={i} className="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-xl border border-slate-200 dark:border-slate-700">
                                                <div className="font-bold text-slate-900 dark:text-slate-100 mb-2">Ví dụ:</div>
                                                <div className="mb-2"><MathRenderer content={ex.problem} /></div>
                                                <div className="pl-4 border-l-4 border-teal-300 dark:border-teal-700 text-slate-700 dark:text-slate-300">
                                                    <MathRenderer content={ex.solution} />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div 
                        className="w-full h-full flex flex-col items-center justify-center relative bg-black cursor-default"
                        onClick={() => setShowControls(prev => !prev)} // Click to toggle controls
                    >
                        {/* Slide Content */}
                        <div 
                            key={`${currentSlide}-${slideStep}`} 
                            className="w-full h-full animate-fade-in bg-white dark:bg-slate-900"
                            onClick={(e) => e.stopPropagation()} // Prevent toggle when clicking content interactive areas
                        >
                            {/* Wrapper to handle toggle click on background parts */}
                            <div className="w-full h-full" onClick={() => setShowControls(prev => !prev)}>
                                {renderSlideContent(slides[currentSlide])}
                            </div>
                        </div>

                        {/* Navigation Arrows (Bottom Corners) - Conditional Render based on showControls or Hover */}
                        <div className={`transition-opacity duration-300 ${!showControls ? 'opacity-0 hover:opacity-100' : 'opacity-100'}`}>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handlePrevAction(); }} 
                                disabled={currentSlide === 0 && slideStep === 1} 
                                className="fixed left-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                                title="Lùi lại"
                            >
                                <ChevronLeft className="w-8 h-8 group-hover:-translate-x-1 transition-transform" />
                            </button>

                            <button 
                                onClick={(e) => { e.stopPropagation(); handleNextAction(); }} 
                                disabled={currentSlide === slides.length - 1 && (slideStep === 2 || !slides[currentSlide].examples?.length)} 
                                className="fixed right-6 bottom-6 z-40 p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-teal-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                                title="Tiếp tục"
                            >
                                <ChevronRight className="w-8 h-8 group-hover:translate-x-1 transition-transform" />
                            </button>
                        </div>

                        {/* Progress Indicator (Bottom Center) */}
                        <div className={`absolute bottom-6 left-0 right-0 flex justify-center pointer-events-none transition-opacity duration-500 ${!showControls ? 'opacity-0' : 'opacity-100'}`}>
                             <div className="flex flex-col items-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-md px-4 py-2 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-sm">
                                <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">
                                    Slide {currentSlide + 1} / {slides.length}
                                </span>
                                <div className="flex gap-1.5">
                                    {/* Simple Dots for slides */}
                                    {slides.map((_, idx) => (
                                        <div key={idx} className={`h-1.5 w-1.5 rounded-full transition-all duration-300 ${idx === currentSlide ? 'bg-teal-500 scale-125' : 'bg-slate-300 dark:bg-slate-600'}`} />
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* --- DOCK --- */}
        <div className={`no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-500 ease-in-out ${!showControls ? 'translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>

            {/* Theme Picker Popover */}
            {isDockExpanded && showThemePicker && (
               <div className="mb-4 w-64 bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up theme-picker-container">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 mb-3 text-center text-sm uppercase tracking-wide">Chọn màu Slide</h3>
                    <div className="grid grid-cols-5 gap-2">
                        {Object.entries(SLIDE_THEMES).map(([key, theme]) => (
                            <button
                                key={key}
                                onClick={() => { setActiveTheme(key as ThemeKey); setShowThemePicker(false); }}
                                className={`w-10 h-10 rounded-full border-2 transition-transform hover:scale-110 shadow-sm flex items-center justify-center
                                    ${activeTheme === key ? 'border-slate-800 dark:border-white scale-110' : 'border-transparent'}
                                `}
                                style={{ background: key === 'teal' ? '#0d9488' : key === 'blue' ? '#2563eb' : key === 'violet' ? '#7c3aed' : key === 'rose' ? '#e11d48' : '#d97706' }}
                                title={theme.name}
                            >
                                {activeTheme === key && <div className="w-2 h-2 bg-white rounded-full" />}
                            </button>
                        ))}
                    </div>
               </div>
            )}

            {/* Navigation Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Mục lục bài giảng</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="flex flex-col gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar">
                        {slides.map((sec, idx) => {
                            const isActive = idx === currentSlide;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToSlide(idx)}
                                    className={`p-3 rounded-xl font-medium transition-all text-sm text-left shadow-sm border border-transparent flex items-center gap-3
                                        ${isActive 
                                            ? 'bg-teal-100 dark:bg-teal-900 text-teal-800 dark:text-teal-200 ring-1 ring-teal-500' 
                                            : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600'}
                                    `}
                                >
                                    <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isActive ? 'bg-teal-500 text-white' : 'bg-slate-200 dark:bg-slate-600'}`}>{idx + 1}</span>
                                    <span className="truncate">{sec.title}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Main Dock Bar */}
            <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={(e) => { e.stopPropagation(); !isDockExpanded && setIsDockExpanded(true); }}
            >
                {isDockExpanded ? (
                    <>
                        {/* Fullscreen Toggle */}
                        {isFullscreen && (
                            <>
                                <button onClick={() => setIsFullscreen(false)} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white" title="Thoát toàn màn hình">
                                    <Minimize className="w-5 h-5" />
                                </button>
                                <div className="w-px h-6 bg-white/20 mx-1"></div>
                            </>
                        )}

                        {/* View Mode Switcher */}
                        <button 
                            onClick={() => setViewMode(prev => prev === 'slide' ? 'doc' : 'slide')}
                            className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-teal-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title={viewMode === 'slide' ? "Chuyển sang chế độ Văn bản" : "Chuyển sang chế độ Trình chiếu"}
                        >
                            {viewMode === 'slide' ? <Presentation className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                        </button>

                        {/* Theme Picker Button */}
                        <button 
                            onClick={() => setShowThemePicker(!showThemePicker)}
                            className={`theme-toggle-btn p-3 rounded-full transition-colors ${showThemePicker ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Đổi màu Slide"
                        >
                            <Palette className="w-5 h-5" />
                        </button>

                         {/* Zoom Tools */}
                         <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-teal-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-teal-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                        {/* Laser Pointer */}
                        <button 
                            onClick={() => setIsLaserPointer(!isLaserPointer)}
                            className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                            title="Bật/Tắt Laser Pointer"
                        >
                            <MousePointer2 className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Navigation / TOC */}
                        <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-teal-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Mục lục">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                        {/* Blackboard */}
                        <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                        {/* Random Picker */}
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
