import React, { useState, useEffect } from 'react';
import { ExamConfig, ExamMatrix, StudyGuideData, ExportData } from './types';
import { generateExam, generateStudyGuide } from './services/geminiService';
import ConfigForm from './components/ConfigForm';
import { ExamPreview } from './components/ExamPreview';
import StudyGuidePreview from './components/StudyGuidePreview';
import { GraduationCap, Loader2, Moon, Sun } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<'config' | 'preview'>('config');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);

  // Theme State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('theme') === 'dark' || 
             (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Apply Theme Side Effect
  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      html.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // State for different data types
  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);

  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async (newConfig: ExamConfig) => {
    setLoading(true);
    setError(null);
    setConfig(newConfig);

    // Clear previous data
    if (step === 'config') {
        setExamData(null);
        setStudyGuideData(null);
    }

    try {
      if (newConfig.mode === 'theory') {
        const data = await generateStudyGuide(newConfig);
        setStudyGuideData(data);
        setExamData(null);
      } else {
        const data = await generateExam(newConfig);
        setExamData(data);
        setStudyGuideData(null);
      }
      setStep('preview');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Có lỗi xảy ra trong quá trình sinh đề. Vui lòng thử lại hoặc giảm số lượng câu hỏi.");
    } finally {
      setLoading(false);
    }
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const jsonStr = e.target?.result as string;
        if (!jsonStr) return;

        const imported = JSON.parse(jsonStr) as ExportData;

        // Basic validation
        if (!imported.type || !imported.config || !imported.data) {
          throw new Error("File không đúng định dạng Smart Practice.");
        }

        setConfig(imported.config);

        if (imported.type === 'theory') {
          setStudyGuideData(imported.data as StudyGuideData);
          setExamData(null);
        } else {
          setExamData(imported.data as ExamMatrix);
          setStudyGuideData(null);
        }

        setStep('preview');
        setError(null);
      } catch (err: any) {
        console.error(err);
        setError("Lỗi khi đọc file: " + err.message);
      }
    };
    reader.readAsText(file);
  };

  const handleReset = () => {
    setStep('config');
    // We keep config for convenience, but clear data
    setExamData(null);
    setStudyGuideData(null);
    setError(null);
  };

  const handleRegenerate = () => {
    if (config) {
      handleGenerate(config);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-800 dark:selection:bg-indigo-900 dark:selection:text-indigo-200 relative transition-colors duration-300">

      {/* Loading Overlay */}
      {loading && (
        <div className="fixed inset-0 z-[60] bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-12 h-12 text-indigo-600 dark:text-indigo-400 animate-spin mb-4" />
          <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">Đang khởi tạo dữ liệu...</h3>
          <p className="text-slate-500 dark:text-slate-400">Hệ thống AI đang phân tích và sinh nội dung mới</p>
        </div>
      )}

      {/* Navbar */}
      <nav className="bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 px-4 py-3 sticky top-0 z-50 no-print transition-colors duration-300">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2 text-indigo-700 dark:text-indigo-400">
            <GraduationCap className="w-8 h-8" />
            <div 
              className="cursor-pointer"
              onClick={() => { if(step === 'preview') handleReset(); }}
            >
              <h1 className="text-xl font-bold tracking-tight leading-none">Trợ Lý Luyện Thi</h1>
              <span className="text-xs font-medium text-slate-500 dark:text-slate-400 tracking-wider">THÔNG MINH</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button 
               onClick={() => setIsDarkMode(!isDarkMode)}
               className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition-colors"
               title={isDarkMode ? "Chuyển sang chế độ Sáng" : "Chuyển sang chế độ Tối"}
             >
               {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
             </button>
             <div className="text-sm font-bold text-slate-700 dark:text-slate-300 hidden sm:block border-l border-slate-300 dark:border-slate-600 pl-4">
                Giáo viên: Vũ Tiến Lực
             </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="p-4 md:p-8">

        {error && (
          <div className="max-w-3xl mx-auto mb-6 p-4 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg text-red-700 dark:text-red-300 flex items-center justify-between animate-fade-in">
             <span className="font-medium">{error}</span>
             <button onClick={() => setError(null)} className="text-red-500 hover:text-red-700 dark:hover:text-red-200 font-bold p-1">✕</button>
          </div>
        )}

        {step === 'config' ? (
          <div className="flex flex-col items-center justify-center min-h-[80vh]">
            <div className="text-center mb-10 space-y-4 max-w-2xl">
              <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 dark:text-slate-50 tracking-tight">
                Trợ lý <span className="text-indigo-600 dark:text-indigo-400">Sư phạm AI</span>
              </h1>
              <p className="text-lg text-slate-600 dark:text-slate-400">
                Tạo đề thi trắc nghiệm, tự luận hoặc soạn bài giảng trọng tâm với công nghệ AI tiên tiến.
              </p>
            </div>
            <ConfigForm 
              onGenerate={handleGenerate} 
              isLoading={loading} 
              onImport={handleImport}
            />
          </div>
        ) : (
          config && (
            <>
              {config.mode !== 'theory' && examData && (
                <ExamPreview 
                  config={config} 
                  data={examData} 
                  onReset={handleReset} 
                  onRegenerate={handleRegenerate}
                />
              )}
              {config.mode === 'theory' && studyGuideData && (
                <StudyGuidePreview 
                  config={config} 
                  data={studyGuideData} 
                  onReset={handleReset}
                  onRegenerate={handleRegenerate} 
                />
              )}
            </>
          )
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700 py-8 mt-12 no-print transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 text-center text-slate-400 dark:text-slate-500 text-sm">
          <p>© 2024 Trợ Lý Luyện Thi Thông Minh. Powered by Google Gemini.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

