// --- UTILS: LATEX TO DOCX EQUATION PARSER (Duplicated for standalone component) ---
const symbolMap: Record<string, string> = {
    '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ', '\\Delta': 'Δ',
    '\\epsilon': 'ε', '\\theta': 'θ', '\\lambda': 'λ', '\\mu': 'μ', '\\pi': 'π',
    '\\sigma': 'σ', '\\Sigma': 'Σ', '\\phi': 'φ', '\\omega': 'ω', '\\Omega': 'Ω',
    '\\infty': '∞', '\\pm': '±', '\\approx': '≈', '\\neq': '≠', '\\leq': '≤',
    '\\geq': '≥', '\\times': '×', '\\cdot': '·', '\\div': '÷', '\\rightarrow': '→',
    '\\leftrightarrow': '↔', '\\Rightarrow': '⇒', '\\in': '∈', '\\subset': '⊂',
    '\\cup': '∪', '\\cap': '∩', '\\emptyset': '∅', '\\circ': '∘'
};

const cleanLatex = (latex: string) => {
    let clean = latex;
    Object.keys(symbolMap).forEach(key => {
        const regex = new RegExp(key.replace(/\\/g, '\\\\'), 'g');
        clean = clean.replace(regex, symbolMap[key]);
    });
    clean = clean.replace(/\\text\{([^}]+)\}/g, '$1');
    clean = clean.replace(/\\(left|right)/g, '');
    return clean;
};

// Recursive function to generate Word Math Objects from a string
const parseMathString = (str: string): any[] => {
    const nodes: any[] = [];
    let current = str;

    while (current.length > 0) {
        // 1. Check for \frac{num}{den}
        const fracMatch = current.match(/^\\frac\{/);
        if (fracMatch) {
            let depth = 1;
            let splitIndex = -1;
            let endIndex = -1;

            // Find the split between }{
            for (let i = 6; i < current.length; i++) {
                if (current[i] === '{') depth++;
                else if (current[i] === '}') depth--;

                if (depth === 0) {
                    if (current[i+1] === '{') {
                        splitIndex = i;
                        depth = 1;
                        i++; // skip the {
                    } else {
                        endIndex = i;
                        break;
                    }
                }
            }

            if (splitIndex !== -1 && endIndex !== -1) {
                const numStr = current.substring(6, splitIndex);
                const denStr = current.substring(splitIndex + 2, endIndex);

                nodes.push(new MathFraction({
                    numerator: parseMathString(numStr),
                    denominator: parseMathString(denStr)
                }));
                current = current.substring(endIndex + 1);
                continue;
            }
        }

        // 2. Check for \sqrt{content}
        const sqrtMatch = current.match(/^\\sqrt\{/);
        if (sqrtMatch) {
            let depth = 1;
            let endIndex = -1;
            for (let i = 6; i < current.length; i++) {
                if (current[i] === '{') depth++;
                else if (current[i] === '}') depth--;
                if (depth === 0) {
                    endIndex = i;
                    break;
                }
            }
            if (endIndex !== -1) {
                const content = current.substring(6, endIndex);
                nodes.push(new MathRadical({
                    degree: [], // Empty for square root
                    children: parseMathString(content)
                }));
                current = current.substring(endIndex + 1);
                continue;
            }
        }

        // 3. Superscripts (e.g., x^2 or x^{2})
        const superMatch = current.match(/^\^(\{([^}]+)\}|([0-9a-zA-Z]))/);
        if (superMatch && nodes.length > 0) {
            const lastNode = nodes.pop();
            const exponent = superMatch[2] || superMatch[3];
            nodes.push(new MathSuperScript({
                children: [lastNode],
                superScript: parseMathString(exponent)
            }));
            current = current.substring(superMatch[0].length);
            continue;
        }

        // 4. Subscripts (e.g., x_2 or x_{2})
        if (current.startsWith('_') && nodes.length > 0) {
             const subContentMatch = current.match(/^_(\{([^}]+)\}|([0-9a-zA-Z]))/);
             if (subContentMatch) {
                const lastNode = nodes.pop();
                const subscript = subContentMatch[2] || subContentMatch[3];
                nodes.push(new MathSubScript({
                    children: [lastNode],
                    subScript: parseMathString(subscript)
                }));
                current = current.substring(subContentMatch[0].length);
                continue;
             }
        }

        // 5. Basic Token
        const nextSpecial = current.search(/[\\^_]/);
        if (nextSpecial === -1) {
            nodes.push(new MathRun(current));
            current = "";
        } else if (nextSpecial === 0) {
            if (current.startsWith('\\')) {
                 const cmdMatch = current.match(/^(\\[a-zA-Z]+)/);
                 if (cmdMatch) {
                     nodes.push(new MathRun(cleanLatex(cmdMatch[1])));
                     current = current.substring(cmdMatch[1].length);
                 } else {
                     nodes.push(new MathRun(current[0]));
                     current = current.substring(1);
                 }
            } else {
                nodes.push(new MathRun(current[0]));
                current = current.substring(1);
            }
        } else {
            const textPart = current.substring(0, nextSpecial);
            nodes.push(new MathRun(textPart));
            current = current.substring(nextSpecial);
        }
    }
    return nodes;
};

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // State logic
  const [currentSlide, setCurrentSlide] = useState(0);

  // slideStep: 1 = Theory View, 2 = Example View
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');

  // Interaction State for Solution
  const [showExampleSolution, setShowExampleSolution] = useState(false);

  // UI/Tool State
  const [showControls, setShowControls] = useState(true); // Toggle Header/Dock
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [isExporting, setIsExporting] = useState(false);

  // Theme State
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showThemePicker, setShowThemePicker] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  // Reset example solution visibility when slide changes
  useEffect(() => {
    setShowExampleSolution(false);
  }, [currentSlide, slideStep]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Prevent interfering with inputs if any
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

        if (viewMode === 'slide') {
            if (e.key === 'ArrowRight' || e.key === 'Space') {
                handleNextAction();
            } else if (e.key === 'ArrowLeft') {
                handlePrevAction();
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSlide, slideStep, viewMode, slides.length]);

  // Close popovers when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showThemePicker && !target.closest('.theme-picker-container') && !target.closest('.theme-toggle-btn')) {
        setShowThemePicker(false);
      }
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showThemePicker, showNav]);

  // Fullscreen Handler
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        // Cast to any to avoid potential TS issues with requestFullscreen in some environments
        (containerRef.current as any).requestFullscreen().catch((err: any) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const handlePrevAction = () => {
    // If currently in Example view (step 2), go back to Theory view (step 1) of SAME slide
    if (slideStep === 2) {
        setSlideStep(1);
    } 
    // If currently in Theory view (step 1), go to previous slide
    else if (currentSlide > 0) {
        // If previous slide has examples, go to its Example view (step 2)
        // Otherwise go to its Theory view (step 1)
        const prevSlideIdx = currentSlide - 1;
        const hasExamples = slides[prevSlideIdx].examples && slides[prevSlideIdx].examples.length > 0;
        setCurrentSlide(prevSlideIdx);
        setSlideStep(hasExamples ? 2 : 1);
    }
  };

  const handleNextAction = () => {
    const currentSection = slides[currentSlide];
    const hasExamples = currentSection.examples && currentSection.examples.length > 0;

    // If currently in Theory view (step 1) AND examples exist, go to Example view (step 2)
    if (slideStep === 1 && hasExamples) {
        setSlideStep(2);
    } 
    // Otherwise (if already in Example view, or no examples), go to Next Slide
    else if (currentSlide < slides.length - 1) {
        setCurrentSlide(prev => prev + 1);
        setSlideStep(1);
    }
  };

  const jumpToSlide = (idx: number) => {
      setCurrentSlide(idx);
      setSlideStep(1);
      setShowNav(false);
      if (viewMode === 'doc') {
          // Scroll to element in doc mode
          const el = document.getElementById(`section-${idx}`);
          if (el) el.scrollIntoView({ behavior: 'smooth' });
      }
  };

  const handleExportJSON = () => {
    const exportData = {
        type: 'theory',
        timestamp: Date.now(),
        config,
        data
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const saveFunc = (FileSaver as any).saveAs || FileSaver;
    saveFunc(blob, `Bai_Giang_${config.subject}_${Date.now()}.json`);
  };

  // Helper to parse content mixed with LaTeX ($...$) and Bold (**...**) into Docx Paragraph Children
  const parseContentToDocx = (content: string) => {
      // Split by LaTeX delimiters ($...$) AND Bold delimiters (**...**)
      // Capturing groups are included in the result array
      const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

      return parts.filter(part => part !== '').map((part) => {
          if (part.startsWith('$') && part.endsWith('$')) {
              // It's a math equation
              // Use enhanced parser
              const cleanMath = cleanLatex(part.slice(1, -1).trim());
              return new DocxMath({
                  children: parseMathString(cleanMath)
              });
          } else if (part.startsWith('**') && part.endsWith('**')) {
              // It's bold text
              return new TextRun({
                  text: part.slice(2, -2),
                  bold: true,
                  size: 24 // 12pt
              });
          } else {
              // Regular text
              return new TextRun({
                  text: part,
                  size: 24 // 12pt
              });
          }
      });
  };

  const handleDownloadWord = async () => {
    setIsExporting(true);
    try {
        const sections = data.sections.map((sec, idx) => {
            const contentParagraphs = sec.content.split('\n')
                .filter(line => line.trim() !== '')
                .map(line => {
                    // Remove starting stars or bullets if present
                    const cleanLine = line.replace(/^[★•\-\s]+/, '').trim();
                    return new Paragraph({
                        children: parseContentToDocx(cleanLine),
                        bullet: { level: 0 },
                        spacing: { after: 120 }
                    });
                });

            const exampleContent = [];
            if (sec.examples && sec.examples.length > 0) {
                sec.examples.forEach(ex => {
                     exampleContent.push(
                         new Paragraph({ 
                             heading: HeadingLevel.HEADING_3,
                             spacing: { before: 200, after: 100 },
                             children: [
                                new TextRun({
                                    text: "Ví dụ minh họa:",
                                    color: "2E7D32"
                                })
                             ]
                         }),
                         new Paragraph({ 
                             children: parseContentToDocx(ex.problem), // Use parse helper
                             spacing: { after: 100 }
                         }),
                         new Paragraph({ 
                            children: [new TextRun({ text: "Lời giải:", bold: true })],
                            spacing: { after: 50 }
                        }),
                        new Paragraph({ 
                            children: parseContentToDocx(ex.solution), // Use parse helper
                            spacing: { after: 100 }
                        }),
                        new Paragraph({ 
                            children: [
                                new TextRun({ text: "Giải thích mấu chốt: ", bold: true }), 
                                ...parseContentToDocx(ex.explanation) // Use parse helper for explanation too
                            ],
                            spacing: { after: 300 }
                        })
                     );
                });
            }

            return [
                new Paragraph({ 
                    text: `${idx + 1}. ${sec.title}`, 
                    heading: HeadingLevel.HEADING_2,
                    spacing: { before: 400, after: 200 }
                }),
                ...contentParagraphs,
                ...exampleContent
            ];
        }).flat();

        const doc = new Document({
            creator: "Trợ Lý Luyện Thi Thông Minh",
            title: data.topic,
            sections: [{
                properties: {},
                children: [
                    new Paragraph({ text: data.topic.toUpperCase(), heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }),
                    new Paragraph({ text: `Môn: ${config.subject} | ${config.grade}`, alignment: AlignmentType.CENTER }),
                    new Paragraph({ 
                        alignment: AlignmentType.CENTER, 
                        spacing: { after: 400, before: 200 },
                        children: [
                            new TextRun({
                                text: data.overview,
                                italics: true
                            })
                        ]
                    }),
                    ...sections
                ],
            }],
        });

        const blob = await Packer.toBlob(doc);
        const saveFunc = (FileSaver as any).saveAs || FileSaver;
        saveFunc(blob, `Bai_Giang_${config.subject}_${Date.now()}.docx`);
    } catch (e) {
        console.error(e);
        alert("Có lỗi khi tạo file Word.");
    } finally {
        setIsExporting(false);
    }
  };

  const renderSlideContent = (section: TheorySection) => {
     // Use Zoom property for scaling
     const scaleStyle = { zoom: zoomLevel } as any;
     const theme = SLIDE_THEMES[activeTheme];

     // Split content by newline to create list items
     const contentLines = section.content.split('\n').filter(line => line.trim() !== '');

     return (
        <div className={`flex flex-col h-full w-full px-6 md:px-16 py-8 md:py-12 ${theme.bg}`} style={scaleStyle}>
            {/* Slide Title - Always visible but maybe slightly different style for Example view */}
            <div className={`flex-shrink-0 mb-6 transition-all duration-500`}>
                <h2 className={`text-4xl md:text-5xl font-black ${theme.primary} leading-tight border-l-8 ${theme.border} pl-6`}>
                    {section.title}
                    {slideStep === 2 && <span className="text-slate-400 font-medium text-3xl ml-4 block md:inline md:mt-0 mt-2">- Ví dụ minh họa</span>}
                </h2>
            </div>

            {/* --- VIEW 1: THEORY CONTENT --- */}
            {slideStep === 1 && (
                <div className="flex-1 overflow-y-auto pr-4 custom-scrollbar animate-fade-in-up">
                    <div className={`
                        text-3xl md:text-4xl ${theme.text} leading-relaxed font-medium space-y-6
                        [&_strong]:font-black 
                        [&_strong]:${theme.highlightText.replace(' ', ' [&_strong]:')} 
                        [&_strong]:${theme.highlightBg.replace(' ', ' [&_strong]:')}
                        [&_strong]:px-2 [&_strong]:py-0.5 [&_strong]:rounded-lg [&_strong]:box-decoration-clone
                    `}>
                        {contentLines.map((line, idx) => {
                            const cleanLine = line.replace(/^[\s\u2022\u2605\-\*]+/, '').trim();
                            return (
                                <div key={idx} className="flex items-start gap-4">
                                    <div className={`flex-shrink-0 mt-2 ${theme.starColor}`}>
                                        <Star className="w-6 h-6 fill-current" />
                                    </div>
                                    <div className="flex-1">
                                        <MathRenderer content={cleanLine} />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* --- VIEW 2: EXAMPLE CONTENT (Full focus) --- */}
            {slideStep === 2 && section.examples && section.examples.length > 0 && (
                <div className="flex-1 overflow-y-auto animate-fade-in pr-2 pb-4">
                     <div className={`${theme.exampleBg} p-8 md:p-10 rounded-3xl border-2 ${theme.exampleBorder} shadow-2xl relative overflow-hidden transition-all duration-300 flex flex-col`}>
                        {/* Decorative background element */}
                        <div className={`absolute top-0 right-0 w-48 h-48 ${theme.highlightBg} rounded-bl-full -mr-16 -mt-16 opacity-50`}></div>

                        <div className="relative z-10 flex flex-col">
                            {/* Problem Statement */}
                            <div className="mb-6">
                                <div className={`text-3xl md:text-4xl font-bold ${theme.primary} leading-snug`}>
                                    <MathRenderer content={section.examples[0].problem} />
                                </div>
                            </div>

                            {/* Solution Section */}
                            <div className="border-t-2 border-dashed border-slate-200 dark:border-slate-700 pt-6 mt-2">
                                {!showExampleSolution ? (
                                    <div className="flex flex-col items-center justify-center py-4 gap-4">
                                        <p className="text-slate-400 italic text-lg">Học sinh suy nghĩ trước khi xem lời giải</p>
