                                 <div className="flex items-center justify-between px-6 py-3 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50 rounded-t-3xl">
                                     <div className="flex items-center gap-2">
                                         {activeHints[q.id] && !showAnswers && !activeSolutions[q.id] ? (
                                             <span className="text-indigo-600 dark:text-indigo-400 font-bold flex items-center gap-2 text-lg"><Lightbulb className="w-6 h-6"/> Gợi ý</span>
                                         ) : (
                                             <span className="text-emerald-600 dark:text-emerald-400 font-bold flex items-center gap-2 text-lg"><CheckCircle className="w-6 h-6"/> Lời giải chi tiết</span>
                                         )}
                                     </div>
                                     <button 
                                         onClick={() => {
                                             if (activeHints[q.id]) toggleHint(q.id);
                                             if (activeSolutions[q.id]) toggleSolution(q.id);
                                         }}
                                         className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
                                         title="Thu gọn"
                                     >
                                         <ChevronDown className="w-6 h-6" />
                                     </button>
                                 </div>

                                 {/* Content */}
                                 <div className="flex-1 overflow-y-auto p-6">
                                      {activeHints[q.id] && q.hints && (
                                          <div className="mb-6">
                                              <ul className="list-disc list-inside space-y-3 pl-2 text-slate-700 dark:text-slate-200 text-xl md:text-2xl leading-relaxed">
                                                 {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                                              </ul>
                                          </div>
                                      )}

                                      {(showAnswers || activeSolutions[q.id]) && (
                                         <div className="text-xl md:text-2xl leading-relaxed">
                                              <p className="mb-4 font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-3">
                                                 Đáp án đúng: <span className="bg-emerald-100 dark:bg-emerald-800 px-3 py-1 rounded-lg"><MathRenderer content={q.correctAnswer} /></span>
                                              </p>
                                              <div className="text-slate-800 dark:text-slate-100 whitespace-pre-wrap">
                                                 <MathRenderer content={q.solution} inline={false} />
                                              </div>
                                         </div>
                                      )}
                                 </div>
                            </div>
                       )}
                  </div>
              )}
          </div>
        </div>
    );
  };

  return (
    <div ref={containerRef} className={`min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors duration-300 relative ${isFullscreen ? 'h-screen overflow-hidden' : 'pb-32'}`}>

        {/* --- DOCK TOOLBAR --- */}
        <div className={`nav-dock-container fixed z-50 left-1/2 -translate-x-1/2 bottom-6 bg-white/90 dark:bg-slate-800/90 backdrop-blur-lg border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl p-2 flex items-center gap-2 transition-all duration-300 no-print ${isDockExpanded ? 'w-auto' : 'w-14 h-14 overflow-hidden'}`}>

             {/* Toggle Button */}
             <button 
                className="nav-toggle-btn w-10 h-10 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors flex-shrink-0"
                onClick={() => setIsDockExpanded(!isDockExpanded)}
                title={isDockExpanded ? "Thu gọn thanh công cụ" : "Mở rộng"}
             >
                {isDockExpanded ? <ChevronDown className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
             </button>

             {isDockExpanded && (
                <>
                   <div className="h-6 w-px bg-slate-300 dark:bg-slate-600 mx-1"></div>

                   <button onClick={onReset} className="p-2 text-slate-600 dark:text-slate-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-xl transition-colors" title="Quay lại"><RotateCcw className="w-5 h-5"/></button>
                   <button onClick={onRegenerate} className="p-2 text-slate-600 dark:text-slate-300 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-xl transition-colors" title="Tạo đề mới tương tự"><RefreshCw className="w-5 h-5"/></button>

                   <div className="h-6 w-px bg-slate-300 dark:bg-slate-600 mx-1"></div>

                   <button onClick={handlePrintStudent} className="p-2 text-slate-600 dark:text-slate-300 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-xl transition-colors flex flex-col items-center gap-0.5" title="In đề cho Học sinh"><User className="w-5 h-5"/><span className="text-[9px] font-bold">HS</span></button>
                   <button onClick={handlePrintTeacher} className="p-2 text-slate-600 dark:text-slate-300 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/30 rounded-xl transition-colors flex flex-col items-center gap-0.5" title="In đề có Lời giải (GV)"><CheckCircle className="w-5 h-5"/><span className="text-[9px] font-bold">GV</span></button>
                   <button onClick={handleExportJSON} className="p-2 text-slate-600 dark:text-slate-300 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/30 rounded-xl transition-colors" title="Lưu JSON"><Save className="w-5 h-5"/></button>
                   <button onClick={handleDownloadWord} className="p-2 text-slate-600 dark:text-slate-300 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-colors" title="Tải file Word"><FileText className="w-5 h-5"/></button>

                   <div className="h-6 w-px bg-slate-300 dark:bg-slate-600 mx-1"></div>

                   <button onClick={() => setViewMode(viewMode === 'list' ? 'slide' : 'list')} className="p-2 text-slate-600 dark:text-slate-300 hover:text-purple-500 hover:bg-purple-50 dark:hover:bg-purple-900/30 rounded-xl transition-colors" title={viewMode === 'list' ? "Chuyển sang Trình chiếu" : "Chuyển sang Dạng danh sách"}>
                      {viewMode === 'list' ? <MonitorPlay className="w-5 h-5"/> : <LayoutGrid className="w-5 h-5"/>}
                   </button>
                   <button onClick={() => setIsEditMode(!isEditMode)} className={`p-2 rounded-xl transition-colors ${isEditMode ? 'bg-red-100 text-red-600 dark:bg-red-900 dark:text-red-300' : 'text-slate-600 dark:text-slate-300 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-orange-900/30'}`} title="Chế độ Chỉnh sửa / Xóa câu"><Edit className="w-5 h-5"/></button>

                   <button 
                      onClick={() => setShowAnswers(!showAnswers)} 
                      className={`p-2 rounded-xl transition-colors ${showAnswers ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900 dark:text-emerald-300' : 'text-slate-600 dark:text-slate-300 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/30'}`} 
                      title={showAnswers ? "Ẩn toàn bộ đáp án" : "Hiện toàn bộ đáp án"}
                   >
                      {showAnswers ? <Eye className="w-5 h-5"/> : <EyeOff className="w-5 h-5"/>}
                   </button>

                   <div className="h-6 w-px bg-slate-300 dark:bg-slate-600 mx-1"></div>

                   <button onClick={() => setShowBlackboard(!showBlackboard)} className={`p-2 rounded-xl transition-colors ${showBlackboard ? 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300' : 'text-slate-600 dark:text-slate-300 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/30'}`} title="Bảng đen nháp"><PenTool className="w-5 h-5"/></button>
                   <button onClick={() => setShowRandomPicker(!showRandomPicker)} className={`p-2 rounded-xl transition-colors ${showRandomPicker ? 'bg-pink-100 text-pink-600 dark:bg-pink-900 dark:text-pink-300' : 'text-slate-600 dark:text-slate-300 hover:text-pink-500 hover:bg-pink-50 dark:hover:bg-pink-900/30'}`} title="Quay số ngẫu nhiên"><Dices className="w-5 h-5"/></button>

                   <button onClick={toggleFullScreen} className="p-2 text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white rounded-xl transition-colors" title="Toàn màn hình">
                       {isFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}
                   </button>
                </>
             )}
        </div>

        {/* --- HEADER INFO (List Mode Only) --- */}
        {!isFullscreen && viewMode === 'list' && (
            <div className="bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 py-6 px-4 mb-6 text-center no-print">
                 <h2 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-slate-100 uppercase mb-2">{config.topic}</h2>
                 <div className="flex flex-wrap justify-center gap-4 text-sm font-medium text-slate-500 dark:text-slate-400">
                     <span className="bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-full">{config.subject} - {config.grade}</span>
                     <span className="bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-full">Số câu: {questions.length}</span>
                 </div>
                 {/* Student Input */}
                 <div className="mt-6 max-w-md mx-auto flex gap-2">
                     <input 
                       type="text" 
                       placeholder="Họ và tên học sinh..." 
                       value={studentName}
                       onChange={(e) => setStudentName(e.target.value)}
                       className="flex-grow px-4 py-2 rounded-lg border-2 border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 focus:border-indigo-500 outline-none transition-colors"
                     />
                     <button 
                        onClick={handleSubmitExam}
                        disabled={isSubmitted}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold px-6 py-2 rounded-lg shadow-md disabled:bg-slate-400 transition-colors"
                     >
                        {isSubmitted ? 'Đã Nộp' : 'Nộp Bài'}
                     </button>
                 </div>
            </div>
        )}

        {/* --- MAIN CONTENT AREA --- */}
        <div className={`max-w-7xl mx-auto ${viewMode === 'slide' ? 'h-[calc(100vh-100px)]' : ''}`}>

             {viewMode === 'slide' ? (
                 // --- SLIDE VIEW ---
                 <div className="h-full flex items-center justify-center p-4">
                     {/* Left Nav */}
                     <button 
                        onClick={prevSlide}
                        disabled={currentSlide === 0}
                        className="hidden md:flex flex-col items-center justify-center w-12 h-24 rounded-l-xl bg-white dark:bg-slate-800 text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all shadow-lg border border-slate-200 dark:border-slate-700 disabled:opacity-30 disabled:cursor-not-allowed z-10 mr-[-10px]"
                     >
                         <ChevronLeft className="w-8 h-8" />
                     </button>

                     <div className="flex-1 h-full w-full max-w-5xl z-0 transition-transform duration-300">
                        {questions.length > 0 && renderQuestionCard(questions[currentSlide], currentSlide, true)}
                     </div>

                     {/* Right Nav */}
                     <button 
                        onClick={nextSlide}
                        disabled={currentSlide === questions.length - 1}
                        className="hidden md:flex flex-col items-center justify-center w-12 h-24 rounded-r-xl bg-white dark:bg-slate-800 text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all shadow-lg border border-slate-200 dark:border-slate-700 disabled:opacity-30 disabled:cursor-not-allowed z-10 ml-[-10px]"
                     >
                         <ChevronRight className="w-8 h-8" />
                     </button>
                 </div>
             ) : (
                 // --- LIST VIEW ---
                 <div className="max-w-4xl mx-auto p-4 md:p-0 mt-8">
                     {/* Printable Header */}
                     <div className="hidden print-header text-center mb-8 border-b-2 border-black pb-4">
                         <h1 className="text-2xl font-bold uppercase">{config.topic}</h1>
                         <p className="text-lg mt-2">Môn: {config.subject} - {config.grade}</p>
                         <div className="flex justify-between mt-4 px-10 font-bold">
                             <p>Họ và tên: ...........................................................</p>
                             <p>Lớp: ....................</p>
                         </div>
                     </div>

                     {questions.length === 0 ? (
                         <div className="text-center p-10 bg-white dark:bg-slate-800 rounded-2xl shadow-sm">
                             <p className="text-slate-500">Danh sách câu hỏi trống.</p>
                         </div>
                     ) : (
                         questions.map((q, idx) => renderQuestionCard(q, idx, false))
                     )}

                     {/* Submit Button (List Mode) */}
                     {!isSubmitted && questions.length > 0 && (
                         <div className="mt-8 text-center pb-20 no-print">
                             <button 
                                onClick={handleSubmitExam}
                                className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xl px-10 py-4 rounded-2xl shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all flex items-center justify-center gap-3 mx-auto"
                             >
                                 <Send className="w-6 h-6" /> NỘP BÀI VÀ XEM KẾT QUẢ
                             </button>
                         </div>
                     )}
                 </div>
             )}
        </div>

        {/* --- SCORE MODAL --- */}
        {showScoreModal && (
            <div className="fixed inset-0 z-[60] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden relative border border-slate-200 dark:border-slate-700 animate-scale-up">
                    <button onClick={() => setShowScoreModal(false)} className="absolute top-4 right-4 p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors">
                        <X className="w-6 h-6 text-slate-500" />
                    </button>

                    <div className="p-8 text-center">
                        <div className="mb-6 flex justify-center">
                            {feedback.emoji}
                        </div>
                        <h2 className={`text-3xl font-black mb-2 ${feedback.color}`}>
                            {results.score} / 10
                        </h2>
                        <p className="text-slate-600 dark:text-slate-300 font-medium text-lg mb-6">
                            {feedback.text}
                        </p>

                        <div className="grid grid-cols-3 gap-4 mb-8">
                            <div className="bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-xl border border-emerald-100 dark:border-emerald-800">
                                <span className="block text-2xl font-bold text-emerald-600 dark:text-emerald-400">{results.correct}</span>
                                <span className="text-xs font-bold text-emerald-800 dark:text-emerald-300 uppercase">Đúng</span>
                            </div>
