                                <span className="text-xs font-bold text-red-800 dark:text-red-300 uppercase">Sai</span>
                            </div>
                            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-xl border border-blue-100 dark:border-blue-800">
