                                Xem lại bài
                            </button>
                            <button onClick={onReset} className="flex-1 py-3 rounded-xl font-bold bg-indigo-600 text-white hover:bg-indigo-700 transition-colors">
                                Làm đề mới
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* --- BLACKBOARD --- */}
        {showBlackboard && (
             <Blackboard 
                onClose={() => setShowBlackboard(false)} 
                mode={blackboardMode} 
                onModeChange={setBlackboardMode} 
             />
        )}

        {/* --- RANDOM PICKER --- */}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}

        {/* --- SLIDE NAV INDICATOR (Slide Mode) --- */}
        {viewMode === 'slide' && (
            <div className="absolute top-20 left-1/2 -translate-x-1/2 bg-white/50 dark:bg-slate-900/50 backdrop-blur px-4 py-1 rounded-full text-xs font-bold text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700">
                Câu {currentSlide + 1} / {questions.length}
            </div>
        )}
    </div>
  );
};

