                        </div>
                      )}

                      <div className="w-px h-6 bg-white/20 mx-1"></div>

                      <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`}>
