                        </div>
                        <div className="h-3 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                            <div 
                                className="h-full bg-gradient-to-r from-emerald-400 to-teal-500 transition-all duration-1000" 
                                style={{ width: `${(results.correct / results.total) * 100}%` }}
                            ></div>
                        </div>
                    </div>

                    <div className="space-y-3">
                         <button onClick={() => setShowScoreModal(false)} className="w-full py-3 rounded-xl bg-indigo-600 text-white font-bold shadow-lg hover:bg-indigo-700 transition-transform active:scale-95">Xem lại bài làm</button>
                         <button onClick={onReset} className="w-full py-3 rounded-xl bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-200 font-bold border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 transition-colors">Làm đề mới</button>
                         <button onClick={handlePrintStudent} className="w-full py-3 rounded-xl bg-emerald-600 text-white font-bold shadow-lg hover:bg-emerald-700 transition-transform active:scale-95 flex items-center justify-center gap-2">
                            <Printer className="w-4 h-4" /> In Phiếu Kết Quả
