              title="Nhập văn bản"
            >
              <Type className="w-4 h-4" />
            </button>

            <button
              onClick={() => imageInputRef.current?.click()}
              className="p-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
              title="Chèn hình ảnh từ máy tính"
            >
