            <button
              onClick={() => setTool('triangle')}
              className={`p-1.5 rounded-lg transition-colors ${tool === 'triangle' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-300 hover:text-white hover:bg-white/10'}`}
              title="Hình Tam giác"
