              <Circle className="w-4 h-4" />
            </button>

            <button
              onClick={() => setTool('ellipse')}
              className={`p-1.5 rounded-lg transition-colors ${tool === 'ellipse' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-300 hover:text-white hover:bg-white/10'}`}
              title="Hình Elip"
