            <button
              onClick={() => setTool('eraser')}
              className={`p-1.5 rounded-lg transition-colors ${tool === 'eraser' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-300 hover:text-white hover:bg-white/10'}`}
              title="Tẩy"
            >
              <Eraser className="w-4 h-4" />
