          </div>

          {/* Actions */}
          <div className="flex flex-col gap-1">
             <button
              onClick={toggleGrid}
              className={`p-1.5 rounded-lg transition-colors ${isGridMode ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:text-white hover:bg-white/10'}`}
              title="Bật/Tắt hệ trục Oxy"
