          <button
            onClick={onClose}
            className="p-1.5 rounded-full bg-slate-800 text-slate-300 hover:bg-red-600 hover:text-white transition-colors"
            title="Đóng hoàn toàn"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}
    </div>
