// --- ADVANCED LATEX TO DOCX PARSER ---

const SYMBOL_MAP: Record<string, string> = {
    // Greek
    '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ', '\\epsilon': 'ε', '\\varepsilon': 'ε',
    '\\zeta': 'ζ', '\\eta': 'η', '\\theta': 'θ', '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ',
    '\\mu': 'μ', '\\nu': 'ν', '\\xi': 'ξ', '\\pi': 'π', '\\rho': 'ρ', '\\sigma': 'σ',
    '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ', '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
    '\\Delta': 'Δ', '\\Gamma': 'Γ', '\\Lambda': 'Λ', '\\Omega': 'Ω', '\\Phi': 'Φ', '\\Pi': 'Π',
    '\\Sigma': 'Σ', '\\Theta': 'Θ',

    // Operators & Symbols
    '\\times': '×', '\\cdot': '·', '\\div': '÷', '\\pm': '±', '\\mp': '∓',
    '\\leq': '≤', '\\geq': '≥', '\\neq': '≠', '\\approx': '≈', '\\equiv': '≡',
    '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃', '\\cup': '∪', '\\cap': '∩',
    '\\infty': '∞', '\\forall': '∀', '\\exists': '∃', '\\emptyset': '∅', '\\nabla': '∇',
    '\\partial': '∂', '\\angle': '∠', '\\perp': '⊥', '\\parallel': '∥',
    '\\rightarrow': '→', '\\leftarrow': '←', '\\leftrightarrow': '↔', '\\Rightarrow': '⇒', '\\Leftrightarrow': '⇔',
    '\\circ': '∘', '\\bullet': '•', '^{\\circ}': '°'
};

// Helper to find the end index of a balanced brace group starting at `start`
const findBalancedBrace = (str: string, start: number): number => {
    let depth = 0;
    for (let i = start; i < str.length; i++) {
        if (str[i] === '{') depth++;
        else if (str[i] === '}') {
            depth--;
            if (depth === 0) return i;
        }
    }
    return -1;
};

// Recursive parser function
const parseLatexToDocxNodes = (latex: string): any[] => {
    const nodes: any[] = [];
    let i = 0;

    while (i < latex.length) {
        const char = latex[i];

        // 1. Handle Commands (starting with \)
        if (char === '\\') {
            // Find the command name
            const commandMatch = latex.slice(i).match(/^\\([a-zA-Z]+)/);
            if (commandMatch) {
                const cmd = commandMatch[1];
                const cmdLen = commandMatch[0].length;
                let nextIdx = i + cmdLen;

                // --- STRUCTURES ---

                // \frac{num}{den}
                if (cmd === 'frac') {
                    if (latex[nextIdx] === '{') {
                        const endNum = findBalancedBrace(latex, nextIdx);
                        if (endNum !== -1 && latex[endNum + 1] === '{') {
                            const endDen = findBalancedBrace(latex, endNum + 1);
                            if (endDen !== -1) {
                                const numLatex = latex.slice(nextIdx + 1, endNum);
                                const denLatex = latex.slice(endNum + 2, endDen);
                                nodes.push(new MathFraction({
                                    numerator: parseLatexToDocxNodes(numLatex),
                                    denominator: parseLatexToDocxNodes(denLatex)
                                }));
                                i = endDen + 1;
                                continue;
                            }
                        }
                    }
                }

                // \sqrt[deg]{content} or \sqrt{content}
                else if (cmd === 'sqrt') {
                    let degreeNodes: any[] = [];
                    // Check for optional degree [n]
                    if (latex[nextIdx] === '[') {
                        const endDeg = latex.indexOf(']', nextIdx);
                        if (endDeg !== -1) {
                            degreeNodes = parseLatexToDocxNodes(latex.slice(nextIdx + 1, endDeg));
                            nextIdx = endDeg + 1;
                        }
                    }
                    if (latex[nextIdx] === '{') {
                        const endContent = findBalancedBrace(latex, nextIdx);
                        if (endContent !== -1) {
                            const contentLatex = latex.slice(nextIdx + 1, endContent);
                            nodes.push(new MathRadical({
                                degree: degreeNodes,
                                children: parseLatexToDocxNodes(contentLatex)
                            }));
                            i = endContent + 1;
                            continue;
                        }
                    }
                }

                // \text{...}
                else if (cmd === 'text') {
                    if (latex[nextIdx] === '{') {
                        const endText = findBalancedBrace(latex, nextIdx);
                        if (endText !== -1) {
                            // Text inside math should be preserved as literal text
                            nodes.push(new MathRun(latex.slice(nextIdx + 1, endText)));
                            i = endText + 1;
                            continue;
                        }
                    }
                }

                // \sum, \int (Basic N-ary support - treating arguments as sub/sup later)
                // Note: docx MathSum/MathIntegral usually wraps the limits.
                // Simplified: Just output the symbol, limits will be handled by ^ and _ logic naturally if placed after.
                // However, 'docx' has specific classes. Let's try to detect valid limits if possible, otherwise symbol.
                else if (['sum', 'int', 'prod', 'coprod'].includes(cmd)) {
                     // For simplicity in this parser version, we map these to MathRun with special chars
                     // or use the specialized classes if we can lookahead for _ and ^.
                     // A cleaner way for Word is to just use the unicode Char, and let the _ and ^ logic handle the placement.
                     // Word automatically converts "Sum char" + "Sub/Sup" into the N-ary visual.
                     let symbol = '';
                     if(cmd === 'sum') symbol = '∑';
                     else if(cmd === 'int') symbol = '∫';
                     else if(cmd === 'prod') symbol = '∏';

                     nodes.push(new MathRun(symbol));
                     i += cmdLen;
                     continue;
                }

                // \vec{x}, \hat{x}, \overline{x} (Accents)
                // 'docx' support for accents via `MathAccents` is verbose. 
                // Fallback: just parse content.
                else if (['vec', 'hat', 'overline', 'bar'].includes(cmd)) {
                     if (latex[nextIdx] === '{') {
                        const endAcc = findBalancedBrace(latex, nextIdx);
                        if (endAcc !== -1) {
                            // Just extracting content for now to avoid complexity
                            // Ideally wrap in MathAccent
                            nodes.push(...parseLatexToDocxNodes(latex.slice(nextIdx + 1, endAcc)));
                            i = endAcc + 1;
                            continue;
                        }
                     }
                }

                // Symbols (Greek, etc.)
                else if (SYMBOL_MAP[`\\${cmd}`]) {
                    nodes.push(new MathRun(SYMBOL_MAP[`\\${cmd}`]));
                    i += cmdLen;
                    continue;
                }

                // Unknown command - ignore backslash, treat as text
                else {
                    // Skip backslash, parse cmd as text
                    // nodes.push(new MathRun(cmd)); 
                    // Better: ignore
                    i += cmdLen;
                    continue;
                }
            } else {
                // Single backslash?
                i++;
                continue;
            }
        }

        // 2. Superscripts (^) and Subscripts (_)
        else if (char === '^' || char === '_') {
            // Need to determine the "Base".
            // In Docx, MathSuperScript takes children (base) and superScript (exponent).
            // This parser produces a flat list. We need to POP the last element to use as base.

            const lastNode = nodes.pop();
            // If no last node, can't script. Just ignore or treat as char.
            if (!lastNode) {
                nodes.push(new MathRun(char));
                i++;
                continue;
            }

            // Parse the argument (script)
            let scriptNodes: any[] = [];
            let nextStart = i + 1;
            let nextEnd = nextStart;

            if (latex[nextStart] === '{') {
                nextEnd = findBalancedBrace(latex, nextStart);
                if (nextEnd !== -1) {
                    scriptNodes = parseLatexToDocxNodes(latex.slice(nextStart + 1, nextEnd));
                    nextEnd++; // skip closing brace
                } else {
                    // Broken brace, take rest
                    scriptNodes = [new MathRun(latex.slice(nextStart))];
                    nextEnd = latex.length;
                }
            } else {
                // Single char arg
                if (nextStart < latex.length) {
                    // If it's a command like \alpha, we need to lookahead? 
                    // Simplified: just take 1 char. 
                    // For robust single-token parsing (like x^\alpha), we'd need full tokenization.
                    // Fallback: Just take 1 char for now.
                    scriptNodes = [new MathRun(latex[nextStart])];
                    nextEnd++;
                }
            }

            if (char === '^') {
                nodes.push(new MathSuperScript({
                    children: [lastNode],
                    superScript: scriptNodes
                }));
            } else {
                nodes.push(new MathSubScript({
                    children: [lastNode],
                    subScript: scriptNodes
                }));
            }

            i = nextEnd;
            continue;
        }

        // 3. Braces grouping { } (if not consumed by commands)
        else if (char === '{') {
            // Usually grouping for layout, just parse inside
            const endGroup = findBalancedBrace(latex, i);
            if (endGroup !== -1) {
                nodes.push(...parseLatexToDocxNodes(latex.slice(i + 1, endGroup)));
                i = endGroup + 1;
                continue;
            } else {
                i++;
            }
        }
        else if (char === '}') {
            // Should not happen if balanced, skip
            i++;
        }

        // 4. Literal Characters
        else {
            // Accumulate simple text to avoid creating too many MathRuns
            let text = char;
            let j = i + 1;
            while (j < latex.length) {
                const c = latex[j];
                // Stop at special chars
                if (c === '\\' || c === '^' || c === '_' || c === '{' || c === '}') break;
                text += c;
                j++;
            }
            nodes.push(new MathRun(text));
            i = j;
        }
    }
    return nodes;
};


