import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

const createClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const client = createClient();
  // Cập nhật model name chính xác theo hướng dẫn
  const smartModel = "gemini-3-pro-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      // Matrix Mode Instructions
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      // Exam Mode Instructions (Single Topic)
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ TUYỆT ĐỐI TIÊU CHUẨN BLOOM (30-40-30):
          - 30% câu hỏi ở mức Nhận biết / Thông hiểu (Dễ).
          - 40% câu hỏi ở mức Vận dụng (Trung bình).
          - 30% câu hỏi ở mức Vận dụng cao (Khó / Xuất sắc).

          PHÂN BỔ DẠNG BÀI:
          - Các câu Dễ và Trung bình: Ưu tiên dùng dạng Trắc nghiệm (${QuestionType.MULTIPLE_CHOICE}).
          - Các câu Khó / Vận dụng cao: Ưu tiên dùng dạng Tự luận (${QuestionType.ESSAY}) để đánh giá tư duy.
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao (Nguyên tắc: Dễ trước khó sau).' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề trọng tâm: "${config.topic}".
        Số lượng câu hỏi: ${config.questionCount}.
        Loại câu hỏi: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là nhà giáo dục Việt Nam xuất sắc, giáo viên giỏi đa môn, 
có 20 năm kinh nghiệm giảng dạy và nghiên cứu sách giáo khoa theo CTGDPT 2018,
chuyên gia ra đề kiểm tra – đánh giá năng lực học sinh THPT.

Bạn hiểu rõ:
- Mục tiêu cần đạt của CTGDPT 2018
- Cấu trúc đề kiểm tra hiện hành trong các trường phổ thông Việt Nam
- Đặc điểm học sinh theo từng khối lớp
- Yêu cầu phân hóa và đánh giá năng lực

Hãy tạo một bộ đề luyện tập cho môn ${config.subject}, lớp ${config.grade},
bám sát sách giáo khoa (ghi rõ bộ sách),
có ma trận mức độ (nhận biết – thông hiểu – vận dụng – vận dụng cao),
cấu trúc đề hợp lý, có đáp án và hướng dẫn chấm chi tiết.
    Yêu cầu:
- Nội dung câu hỏi bám sát kiến thức trọng tâm SGK
- Có câu hỏi gắn với thực tế, đời sống hoặc liên môn
- Không đánh đố, không máy móc
- Mức độ khó tăng dần
- Ngôn ngữ chuẩn mực, rõ ràng, phù hợp học sinh Việt Nam
- Có đáp án, thang điểm và nhận xét sư phạm ngắn cho từng câu

    ${structureInstruction}

    Cấu hình độ khó: ${difficultyInstruction}
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Người dùng có cung cấp một tài liệu đính kèm (Hình ảnh hoặc PDF).
    Hãy PHÂN TÍCH KỸ nội dung trong file đính kèm đó.
    Dựa trên kiến thức, bài tập, hoặc ngữ liệu có trong file, hãy soạn ra bộ câu hỏi MỚI (tương tự dạng bài hoặc phát triển từ ngữ liệu đó).
    KHÔNG CHÉP LẠI Y NGUYÊN câu hỏi trong file nếu đó là file bài tập (hãy thay số liệu hoặc ngữ cảnh để tạo đề mới), trừ khi đề bài yêu cầu trích xuất.
    `;
  }

  promptText += `
    Yêu cầu quan trọng:
    1. Nội dung phải chuẩn theo chương trình GDPT 2018 của Bộ Giáo dục & Đào tạo Việt Nam.
    2. Các câu hỏi phải rõ ràng, không trùng lặp.
    3. Phải cung cấp đáp án đúng. Lời giải (solution) cần VIẾT TẮT, CỰC KỲ NGẮN GỌN, SÚC TÍCH, đi thẳng vào các bước biến đổi công thức chính, lược bỏ tối đa các câu văn dẫn dắt rườm rà.
    4. Phải cung cấp 2 gợi ý (hints) cho học sinh để kích thích tư duy (không cho đáp án ngay trong gợi ý).
    5. QUY TẮC DẠNG CÂU HỎI (Type):
       - Nếu cấu trúc đề yêu cầu rõ dạng (Trắc nghiệm/Tự luận) thì phải tuân thủ.
    6. QUY TẮC LỰA CHỌN (Options):
       - Nếu type là '${QuestionType.MULTIPLE_CHOICE}': BẮT BUỘC phải có mảng 'options' gồm 4 lựa chọn A, B, C, D.
       - Nếu type là '${QuestionType.ESSAY}': Mảng 'options' để rỗng hoặc null.
    7. ĐỊNH DẠNG TOÁN HỌC: Tất cả các công thức toán học, phương trình, biểu thức biến số (x, y, z...) PHẢI được viết dưới dạng LaTeX và đặt trong dấu $ (ví dụ: $x^2 + 2x + 1 = 0$, $\\frac{1}{2}$, $\\alpha$). Tuyệt đối không dùng Unicode math thông thường nếu có thể dùng LaTeX.
    8. MỤC TIÊU (Objectives): Hãy liệt kê 3-5 mục tiêu kiến thức, kỹ năng chính mà học sinh cần đạt được thông qua bài luyện tập này.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING, description: "Nội dung câu hỏi, chứa công thức LaTeX trong dấu $" },
      type: { type: Type.STRING, description: "Loại câu hỏi (Trắc nghiệm hoặc Tự luận)" },
      difficulty: { type: Type.STRING, description: "Mức độ (ví dụ: Nhận biết, Vận dụng)" },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Danh sách 4 lựa chọn nếu là trắc nghiệm (chứa LaTeX). Null hoặc rỗng nếu là tự luận"
      },
      correctAnswer: { type: Type.STRING, description: "Đáp án đúng (ví dụ: 'A' hoặc giá trị cụ thể chứa LaTeX)" },
      solution: { type: Type.STRING, description: "Hướng dẫn giải cực kỳ ngắn gọn, chỉ ghi các bước biến đổi chính (chứa LaTeX)" },
      hints: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "2 gợi ý sư phạm để học sinh tự nghĩ (chứa LaTeX)"
      },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "Tiêu đề bài thi (VD: Đề ôn tập...)" },
      objectives: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING }, 
        description: "Danh sách 3-5 mục tiêu kiến thức cần đạt" 
      },
      summary: { type: Type.STRING, description: "Tóm tắt ma trận đề (ví dụ: 3 câu TN dễ, 4 câu TN trung bình, 3 câu TL khó...)" },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [];

    // Add uploaded file if exists
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    // Add text prompt
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel, // Sử dụng đúng biến smartModel
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as ExamMatrix;
    return data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate exam. Please check your API Key and try again.");
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const client = createClient();
  // Cập nhật model name chính xác theo hướng dẫn
  const smartModel = "gemini-3-pro-preview";

  let promptText = `
    Bạn là một giảng viên đại học xuất sắc và chuyên gia sư phạm.
    Hãy soạn một bài giảng tóm tắt kiến thức trọng tâm (Lecture Notes) theo phong cách Slide thuyết trình.
    Môn: ${config.subject}, ${config.grade}.
    Chủ đề: "${config.topic}".
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Dựa trên TÀI LIỆU ĐÍNH KÈM (Hình ảnh/PDF) mà tôi cung cấp.
    Hãy phân tích nội dung trong đó để tóm tắt lý thuyết và tạo ra các ví dụ minh họa tương tự.
    Nội dung bài giảng phải bám sát tài liệu được cung cấp.
    `;
  }

  promptText += `
    Yêu cầu ĐẶC BIỆT cho chế độ SLIDE TRÌNH CHIẾU:
    1. Chia nội dung thành các mục rõ ràng.
    2. Trong phần 'content' (Lý thuyết): 
       - TUYỆT ĐỐI KHÔNG viết đoạn văn dài.
       - Chỉ sử dụng các gạch đầu dòng (bullet points) ngắn gọn.
       - QUAN TRỌNG: BẮT BUỘC dùng ký tự "★" (Ngôi sao) hoặc "•" (Chấm tròn) ở đầu mỗi ý. 
       - TUYỆT ĐỐI KHÔNG dùng dấu gạch ngang "-" làm đầu dòng vì sẽ gây nhầm lẫn nghiêm trọng với dấu trừ trong công thức toán học.
       - BẮT BUỘC dùng ký tự xuống dòng (\n) giữa các ý chính. Mỗi gạch đầu dòng phải nằm trên một dòng riêng biệt.
       - Mỗi ý phải súc tích, đi thẳng vào định nghĩa hoặc công thức.
       - Giới hạn nội dung để hiển thị vừa vặn trên 1 slide cỡ chữ lớn.
    3. Phần ví dụ minh họa: Chọn 1 ví dụ điển hình nhất cho mỗi mục lý thuyết.
    4. ĐỊNH DẠNG QUAN TRỌNG (Highlight):
       - Bắt buộc sử dụng dấu ** (markdown bold) bao quanh các TỪ KHÓA, ĐỊNH NGHĨA QUAN TRỌNG, TÊN ĐỊNH LÝ, và CÔNG THỨC GỐC. 
    5. ĐỊNH DẠNG TOÁN HỌC: Bắt buộc dùng LaTeX trong dấu $ cho mọi biểu thức toán học.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  const studyGuideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING, description: "Tên chủ đề chính (viết hoa)" },
      overview: { type: Type.STRING, description: "Giới thiệu tổng quan về chủ đề ngắn gọn (1-2 câu)" },
      sections: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Tiêu đề Slide (Ví dụ: 1. Định lý Pytago)" },
            content: { type: Type.STRING, description: "Nội dung tóm tắt dạng gạch đầu dòng (Bắt đầu bằng ★ hoặc •), chứa LaTeX" },
            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING, description: "Đề bài ví dụ (chứa LaTeX)" },
                  solution: { type: Type.STRING, description: "Lời giải ngắn gọn (chứa LaTeX)" },
                  explanation: { type: Type.STRING, description: "Giải thích mấu chốt" }
                },
                required: ["problem", "solution", "explanation"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "overview", "sections"]
  };

  try {
    const parts: any[] = [];

    // Add uploaded file if exists
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    // Add text prompt
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel, // Sử dụng đúng biến smartModel
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.5,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as StudyGuideData;
    return data;
  } catch (error) {
    console.error("Gemini API Error (Study Guide):", error);
    throw new Error("Failed to generate study guide.");
  }
};

