                      <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`}>
