        ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full max-w-7xl' : ''}
      `} 
      ref={containerRef}
    >

      {/* Side Mode Content Wrapper */}
      <div className={`
         transition-all duration-300 ease-in-out
         ${showBlackboard && blackboardMode === 'side' 
            ? 'w-[50vw] h-[calc(100vh-64px)] fixed left-0 top-[64px] overflow-y-auto z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl px-4 md:px-6 pt-4 pb-24 bg-slate-50 dark:bg-slate-900' 
            : ''}
      `}>

        {/* Top Bar - Hidden in Fullscreen */}
        <div className={`no-print bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 p-4 sticky top-4 z-20 flex flex-wrap gap-4 justify-between items-center transition-all ${isFullscreen ? 'hidden' : ''}`}>
            <div className="flex items-center gap-2">
            <button onClick={onReset} className="text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200 font-medium text-sm px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">← Tạo đề mới</button>
            <div className="h-6 w-px bg-slate-300 dark:bg-slate-600"></div>
