import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import { Printer, CheckCircle, Eye, EyeOff, Lightbulb, ChevronDown, ChevronRight, FileText, Download, FileSignature, Save, LayoutGrid, ArrowUp, X, Menu, PenTool, Maximize, Minimize, RefreshCw, User, Trophy, Send, XCircle, Star, MonitorPlay, MousePointer2, ZoomIn, ZoomOut, ChevronLeft, ArrowRight, ArrowLeft, Trash2, Edit, Target, Dices, Smile, Frown, Award, PartyPopper, RotateCcw } from 'lucide-react';
import MathRenderer from './MathRenderer';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Math as DocxMath, MathRun, MathFraction, MathRadical, MathSuperScript, MathSubScript, MathSum, MathIntegral, MathLimitLower, Header, Footer, PageNumber, TabStopType, TabStopPosition, UnderlineType, MathDelimiter, MathMatrix } from 'docx';
import FileSaver from 'file-saver';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

// Visual styles for options A, B, C, D
const OPTION_THEMES = [
  { 
