                >
                    <ChevronLeft className="w-8 h-8" />
                </button>

                <div className="w-full h-full mx-auto px-4 md:px-20 pb-4">
                    <div key={currentSlide} className={`h-full w-full ${slideDirection === 'next' ? 'animate-slide-in-right' : 'animate-slide-in-left'}`}>
                        {questions.length > 0 && renderQuestionCard(questions[currentSlide], currentSlide, true)}
                    </div>
                </div>

                {/* Navigation Buttons - Bottom Corners */}
                <button 
                    onClick={prevSlide}
                    disabled={currentSlide === 0}
                    className="fixed left-6 bottom-6 z-40 p-3 md:p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                    title="Câu trước (Phím mũi tên trái)"
                >
                    <ChevronLeft className="w-8 h-8 group-hover:-translate-x-1 transition-transform" />
                </button>

                <button 
                    onClick={nextSlide}
                    disabled={currentSlide === questions.length - 1}
                    className="fixed right-6 bottom-6 z-40 p-3 md:p-4 rounded-full bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/5 dark:hover:bg-white/10 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 group"
                    title="Câu tiếp theo (Phím mũi tên phải)"
                >
                    <ChevronRight className="w-8 h-8 group-hover:translate-x-1 transition-transform" />
                </button>
            </div>
            )}
        </div>

