// --- ADVANCED LATEX TO DOCX PARSER V2.0 ---

const SYMBOL_MAP: Record<string, string> = {
    // Greek
    '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ', '\\epsilon': 'ε', '\\varepsilon': 'ε',
    '\\zeta': 'ζ', '\\eta': 'η', '\\theta': 'θ', '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ',
    '\\mu': 'μ', '\\nu': 'ν', '\\xi': 'ξ', '\\pi': 'π', '\\rho': 'ρ', '\\sigma': 'σ',
    '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ', '\\varphi': 'φ', '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
    '\\Delta': 'Δ', '\\Gamma': 'Γ', '\\Lambda': 'Λ', '\\Omega': 'Ω', '\\Phi': 'Φ', '\\Pi': 'Π',
    '\\Sigma': 'Σ', '\\Theta': 'Θ',

    // Operators & Relations
    '\\times': '×', '\\cdot': '·', '\\div': '÷', '\\pm': '±', '\\mp': '∓',
    '\\leq': '≤', '\\geq': '≥', '\\neq': '≠', '\\approx': '≈', '\\equiv': '≡', '\\sim': '∼',
    '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃', '\\subseteq': '⊆', '\\supseteq': '⊇',
    '\\cup': '∪', '\\cap': '∩', '\\setminus': '\\',
    '\\infty': '∞', '\\forall': '∀', '\\exists': '∃', '\\emptyset': '∅', '\\nabla': '∇',
    '\\partial': '∂', '\\angle': '∠', '\\perp': '⊥', '\\parallel': '∥',
    '\\rightarrow': '→', '\\leftarrow': '←', '\\leftrightarrow': '↔', 
    '\\Rightarrow': '⇒', '\\Leftarrow': '⇐', '\\Leftrightarrow': '⇔',
    '\\longmapsto': '↦', '\\to': '→',
    '\\circ': '∘', '\\bullet': '•', '^{\\circ}': '°', '\\deg': '°',

    // Sets
    '\\mathbb{R}': 'ℝ', '\\mathbb{N}': 'ℕ', '\\mathbb{Z}': 'ℤ', '\\mathbb{Q}': 'ℚ', '\\mathbb{C}': 'ℂ',
};

// Helper to find the end index of a balanced brace group starting at `start`
const findBalancedBrace = (str: string, start: number): number => {
    let depth = 0;
    for (let i = start; i < str.length; i++) {
        if (str[i] === '{') depth++;
        else if (str[i] === '}') {
            depth--;
            if (depth === 0) return i;
        }
    }
    return -1;
};

// Main Parser Class-like structure for state management
class LatexParser {
    latex: string;
    index: number;

    constructor(latex: string) {
        this.latex = latex;
        this.index = 0;
    }

    parse(): any[] {
        const nodes: any[] = [];

        while (this.index < this.latex.length) {
            const char = this.latex[this.index];

            if (char === '\\') {
                const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);

                if (match) {
                    const cmd = match[1];
                    this.index += match[0].length;

                    // --- COMMAND HANDLERS ---

                    // 1. Fractions
                    if (cmd === 'frac' || cmd === 'dfrac') {
                        const num = this.parseGroup();
                        const den = this.parseGroup();
                        nodes.push(new MathFraction({ numerator: num, denominator: den }));
                    }

                    // 2. Roots
                    else if (cmd === 'sqrt') {
                        let degree = [];
                        if (this.peek() === '[') {
                            degree = this.parseOptionalGroup();
                        }
                        const content = this.parseGroup();
                        nodes.push(new MathRadical({ degree, children: content }));
                    }

                    // 3. Integrals, Sums (Only Sum and Integral supported nicely in simplified docx export)
                    else if (cmd === 'int') {
                        this.handleIntegral(nodes);
                    }
                    else if (cmd === 'sum') {
                        this.handleSum(nodes);
                    }

                    // 4. Limits
                    else if (cmd === 'lim') {
                        this.handleLimit(nodes);
                    }

                    // 5. Functions (sin, cos, log, etc.)
                    else if (['sin', 'cos', 'tan', 'cot', 'log', 'ln', 'exp', 'min', 'max'].includes(cmd)) {
                         nodes.push(new MathRun(cmd + " ")); 
                    }

                    // 6. Accents - Fallback to simple content rendering
                    else if (['vec', 'hat', 'overline', 'bar', 'tilde'].includes(cmd)) {
                        const content = this.parseGroup();
                        nodes.push(...content);
                        // Optional: Append accent char as run if critical, but complex to align.
                    }

                    // 7. Text
                    else if (cmd === 'text' || cmd === 'mbox') {
                        const textContent = this.extractGroupContent();
                        nodes.push(new MathRun(textContent));
                    }

                    // 8. Environments (Cases) - Fallback to simple list with semicolons
                    else if (cmd === 'begin') {
                        const envName = this.extractGroupContent();
                        if (envName === 'cases') {
                            const endTag = '\\end{cases}';
                            const endIndex = this.latex.indexOf(endTag, this.index);

                            if (endIndex !== -1) {
                                const content = this.latex.slice(this.index, endIndex);
                                this.index = endIndex + endTag.length;

                                // Open brace to indicate system
                                nodes.push(new MathRun("{ "));

                                // Split by \\ for rows
                                const rows = content.split(/\\\\/);
                                rows.forEach((row, i) => {
                                    // Replace alignment & with space
                                    const cleanRow = row.replace(/&/g, ' ').trim();
                                    if(cleanRow) {
                                        const rowNodes = new LatexParser(cleanRow).parse();
                                        nodes.push(...rowNodes);
                                        // Add semicolon separator between equations, except last one
                                        if (i < rows.length - 1) {
                                            nodes.push(new MathRun("; "));
                                        }
                                    }
                                });
                            }
                        } else {
                            // unknown env, skip start tag
                        }
                    }
                    else if (cmd === 'end') {
                        // Skip \end{...}
                         this.extractGroupContent(); 
                    }

                    // 9. Formatting
                    else if (['left', 'right'].includes(cmd)) {
                        // Ignore delimiters
                        // Just consume next char if it's a delimiter char
                         const nextChar = this.latex[this.index];
                         if (nextChar && ['(', ')', '[', ']', '|', '{', '}', '.'].includes(nextChar)) {
                             if (nextChar !== '.') { // dot is null delimiter in latex
                                nodes.push(new MathRun(nextChar));
                             }
                             this.index++;
                         } else if (nextChar === '\\') {
                             // maybe \{ or \}
                             // let next iteration handle it
                         }
                    }

                    // 10. Symbols
                    else if (SYMBOL_MAP[`\\${cmd}`]) {
                        nodes.push(new MathRun(SYMBOL_MAP[`\\${cmd}`]));
                    }

                    // Fallback
                    else {
                        // Unknown command
                    }

                    // Consume \limits if present (formatting hint)
                    if (this.latex.startsWith('\\limits', this.index)) {
                        this.index += 7;
                    }
                } 
                else {
                    // Escaped char like \{ or \%
                    const nextChar = this.latex[this.index];
                    if (['{', '}', '%', '$', '&', '#', '_'].includes(nextChar)) {
                         nodes.push(new MathRun(nextChar));
                         this.index++;
                    } else {
                         // space or other
                         this.index++;
                    }
                }
            }

            // Superscript / Subscript
            else if (char === '^' || char === '_') {
                this.handleScript(char, nodes);
            }

            // Grouping
            else if (char === '{') {
                const group = this.parseGroup();
                nodes.push(...group);
            }
            else if (char === '}') {
                this.index++;
            }

            else {
                // Regular Text
                // Consume until next special char
                let text = char;
                this.index++;
                while(this.index < this.latex.length) {
                    const c = this.latex[this.index];
                    if (['\\', '^', '_', '{', '}'].includes(c)) break;
                    text += c;
                    this.index++;
                }
                nodes.push(new MathRun(text));
            }
        }
        return nodes;
    }

    // --- HELPER METHODS ---

    peek(): string {
        return this.latex[this.index];
    }

    // Parse { ... } and return nodes
    parseGroup(): any[] {
        if (this.latex[this.index] !== '{') {
             const char = this.latex[this.index];
             this.index++;
             return [new MathRun(char)];
        }

        const start = this.index;
        const end = findBalancedBrace(this.latex, start);
        if (end === -1) {
            this.index = this.latex.length; // error
            return [];
        }

        const content = this.latex.slice(start + 1, end);
        this.index = end + 1;

        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    parseOptionalGroup(): any[] {
        if (this.latex[this.index] !== '[') return [];
        const end = this.latex.indexOf(']', this.index);
        if (end === -1) return [];

        const content = this.latex.slice(this.index + 1, end);
        this.index = end + 1;
        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    extractGroupContent(): string {
         if (this.latex[this.index] !== '{') return '';
         const start = this.index;
         const end = findBalancedBrace(this.latex, start);
         if (end === -1) return '';
         this.index = end + 1;
         return this.latex.slice(start + 1, end);
    }

    handleScript(type: string, nodes: any[]) {
        this.index++; // consume ^ or _
        const lastNode = nodes.pop();

        // Parse the script content
        let scriptNodes: any[] = [];
        if (this.latex[this.index] === '{') {
            scriptNodes = this.parseGroup();
        } else {
            const char = this.latex[this.index];
             if (char === '\\') {
                 // read command
                 const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);
                 if (match) {
                     const sub = new LatexParser(match[0]);
                     scriptNodes = sub.parse();
                     this.index += match[0].length;
                 } else {
                     this.index++;
                 }
             } else {
                scriptNodes = [new MathRun(char)];
                this.index++;
             }
        }

        if (!lastNode) {
            nodes.push(new MathRun(type)); // fallback
            nodes.push(...scriptNodes);
            return;
        }

        if (type === '^') {
            nodes.push(new MathSuperScript({ children: [lastNode], superScript: scriptNodes }));
        } else {
            nodes.push(new MathSubScript({ children: [lastNode], subScript: scriptNodes }));
        }
    }

    handleSum(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathSum({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    handleIntegral(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathIntegral({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    parseLimits() {
        let subScript: any[] | undefined;
        let superScript: any[] | undefined;

        // Check for \limits which is optional
        if (this.latex.startsWith('\\limits', this.index)) {
             this.index += 7;
        }

        // Look ahead for _ and ^ (order doesn't matter)
        for (let k = 0; k < 2; k++) {
            this.skipSpaces();
            if (this.latex[this.index] === '_') {
                this.index++;
                subScript = this.parseArg();
            } else if (this.latex[this.index] === '^') {
                this.index++;
                superScript = this.parseArg();
            } else {
                break;
            }
        }
        return { subScript, superScript };
    }

    handleLimit(nodes: any[]) {
        // \lim_{x \to 0}
        this.skipSpaces();
        let limit: any[] = [];
        if (this.latex[this.index] === '_') {
             this.index++;
             limit = this.parseArg();
        }

        nodes.push(new MathLimitLower({
            children: [new MathRun("lim")],
            limit: limit
        }));
    }

    skipSpaces() {
        while(this.latex[this.index] === ' ') this.index++;
    }

    parseArg(): any[] {
        if (this.latex[this.index] === '{') return this.parseGroup();
        const char = this.latex[this.index];
        this.index++;
        return [new MathRun(char)];
    }
}


export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // Local state for questions to allow deletion/modification
  const [questions, setQuestions] = useState<Question[]>(data.questions);

  const [showAnswers, setShowAnswers] = useState(false);
  const [activeHints, setActiveHints] = useState<Record<number, boolean>>({});
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [isExporting, setIsExporting] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);

  // Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Presentation Mode State
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideDirection, setSlideDirection] = useState<'next' | 'prev'>('next'); // State for animation direction
  const [zoomLevel, setZoomLevel] = useState(1); // 1 = 100%
  const [isLaserPointer, setIsLaserPointer] = useState(false);

  // Student Practice State
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, number | string>>({}); // Supports both index (MC) and string (Essay)
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Sync state with props when data changes
  useEffect(() => {
    setQuestions(data.questions);
    setUserAnswers({});
    setIsSubmitted(false);
    setShowScoreModal(false);
    setShowAnswers(false);
    setStudentName('');
    setCurrentSlide(0);
    setViewMode('list');
    setIsEditMode(false);
  }, [data]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Avoid stealing focus from input fields
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight' || e.key === ' ') {
          nextSlide();
        } else if (e.key === 'ArrowLeft') {
          prevSlide();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentSlide, questions.length]);

  // Close nav when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showNav]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        containerRef.current.requestFullscreen().catch((err) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const nextSlide = () => {
    if (currentSlide < questions.length - 1) {
      setSlideDirection('next');
      setCurrentSlide(prev => prev + 1);
      // Auto close solution when switching slides for clean look
      if (!showAnswers) setActiveSolutions({});
    }
  };

  const prevSlide = () => {
    if (currentSlide > 0) {
      setSlideDirection('prev');
      setCurrentSlide(prev => prev - 1);
    }
  };

  const jumpToQuestion = (idx: number) => {
    if (viewMode === 'slide') {
      // Determine direction for smooth jump
      setSlideDirection(idx > currentSlide ? 'next' : 'prev');
      setCurrentSlide(idx);
    } else {
      const element = document.getElementById(`question-${idx}`);
      if (element) {
        // If in side mode, we scroll the window or the inner container depending on implementation.
        // For simplicity, we use scrollIntoView which works in both cases
        element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    setShowNav(false);
  };

  const toggleHint = (id: number) => {
    setActiveHints(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleSolution = (id: number) => {
    setActiveSolutions(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return; 

    // Only set if not already set (toggle behavior could be implemented if needed)
    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: optionIdx
    }));
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode) return;

    // Limit to 4 characters
    if (value.length > 4) return;

    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: value.toUpperCase() // Auto uppercase
    }));
  };

  const handleDeleteQuestion = (idxToDelete: number) => {
    if (!window.confirm(`Bạn có chắc chắn muốn xóa Câu ${idxToDelete + 1} không?`)) {
        return;
    }

    // 1. Calculate new questions
    const newQuestions = questions.filter((_, idx) => idx !== idxToDelete);
    setQuestions(newQuestions);

    // 2. Adjust slide index if necessary
    if (viewMode === 'slide') {
        if (currentSlide === idxToDelete) {
            // If deleting current slide, move to the last available or 0
            if (currentSlide >= newQuestions.length) {
                setCurrentSlide(Math.max(0, newQuestions.length - 1));
            }
        } else if (currentSlide > idxToDelete) {
            // If deleting a preceding slide, shift current index down
            setCurrentSlide(c => Math.max(0, c - 1));
        }
    } else {
         // In list mode, ensure we don't have out of bounds if switching views later
         if (currentSlide >= newQuestions.length) {
            setCurrentSlide(Math.max(0, newQuestions.length - 1));
         }
    }

    // 3. Shift User Answers (keys are indices)
    setUserAnswers(prevAnswers => {
        const newAnswers: Record<number, number | string> = {};
        Object.keys(prevAnswers).forEach(keyStr => {
            const key = parseInt(keyStr);
            if (key < idxToDelete) {
                newAnswers[key] = prevAnswers[key];
            } else if (key > idxToDelete) {
                newAnswers[key - 1] = prevAnswers[key];
            }
        });
        return newAnswers;
    });

    // 4. Reset submission state as the test content has changed
    setIsSubmitted(false);
  };

  const handleSubmitExam = () => {
    const answeredCount = Object.keys(userAnswers).length;

    if (answeredCount < questions.length) {
      if (!confirm(`Bạn mới làm ${answeredCount}/${questions.length} câu. Bạn có chắc chắn muốn nộp bài để xem tổng kết không?`)) {
        return;
      }
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    setShowAnswers(true);
  };

  const calculateScore = () => {
    let correctCount = 0;
    const totalQuestions = questions.length;
    const answeredCount = Object.keys(userAnswers).length;

    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];

      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
             const selectedLabel = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.trim().toUpperCase().startsWith(selectedLabel)) {
                correctCount++;
             }
          } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
             // Compare strings for Essay (normalize removing LaTeX $ and spaces)
             const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
             const cleanUser = userAns.trim().toUpperCase();
             if (cleanUser && cleanCorrect === cleanUser) {
                 correctCount++;
             }
          }
      }
    });

    return {
        correct: correctCount,
        answered: answeredCount,
        total: totalQuestions,
        score: totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 10 * 100) / 100 : 0
    };
  };

  const getFeedback = (score: number) => {
    if (score === 10) return { text: "Tuyệt đối! Em là thiên tài!", color: "text-purple-600 dark:text-purple-400", emoji: <PartyPopper className="w-12 h-12 text-purple-500 animate-bounce" /> };
    if (score >= 9) return { text: "Xuất sắc! Em là niềm tự hào của lớp!", color: "text-emerald-600 dark:text-emerald-400", emoji: <Trophy className="w-12 h-12 text-yellow-400" /> };
    if (score >= 8) return { text: "Rất tốt! Giữ vững phong độ nhé!", color: "text-blue-600 dark:text-blue-400", emoji: <Star className="w-12 h-12 text-blue-400 fill-current" /> };
    if (score >= 6.5) return { text: "Khá tốt! Cần cẩn thận hơn một chút.", color: "text-indigo-600 dark:text-indigo-400", emoji: <Smile className="w-12 h-12 text-indigo-400" /> };
    if (score >= 5) return { text: "Đạt yêu cầu. Cần ôn tập kỹ hơn các câu sai.", color: "text-amber-600 dark:text-amber-400", emoji: <Award className="w-12 h-12 text-amber-400" /> };
    return { text: "Cần cố gắng nhiều hơn. Đừng nản chí!", color: "text-red-600 dark:text-red-400", emoji: <Frown className="w-12 h-12 text-red-400" /> };
  };

  // ... (Print and Export functions remain the same) ...
  const handlePrintStudent = () => {
    document.body.classList.add('printing-student');
    window.print();
    setTimeout(() => { document.body.classList.remove('printing-student'); }, 500);
  };
  const handlePrintTeacher = () => {
    if (!showAnswers) {
      if(confirm('Bạn có muốn bật hiện đáp án trước khi in lời giải không?')) {
        setShowAnswers(true);
        setTimeout(() => window.print(), 100);
        return;
      }
    }
    window.print();
  };

  const handleExportJSON = () => {
    const exportData = { type: 'exam', timestamp: Date.now(), config, data: { ...data, questions } };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const saveFunc = (FileSaver as any).saveAs || FileSaver;
    saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.json`);
  };

  // Helper to parse content mixed with LaTeX ($...$) and Bold (**...**) into Docx Paragraph Children
  const parseContentToDocx = (content: string) => {
      // Split by LaTeX delimiters ($...$) AND Bold delimiters (**...**)
      // Capturing groups are included in the result array
      const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

      return parts.filter(part => part !== '').map((part) => {
          if (part.startsWith('$') && part.endsWith('$')) {
              // It's a math equation
              // Use the new enhanced parser V2
              const cleanMath = part.slice(1, -1).trim();
              const parser = new LatexParser(cleanMath);
              const mathNodes = parser.parse();
              return new DocxMath({
                  children: mathNodes
              });
          } else if (part.startsWith('**') && part.endsWith('**')) {
              // It's bold text
              return new TextRun({
                  text: part.slice(2, -2),
                  bold: true,
                  size: 24 // 12pt
              });
          } else {
              // Regular text
              return new TextRun({
                  text: part,
                  size: 24 // 12pt
              });
          }
      });
  };

  const handleDownloadWord = async () => {
      setIsExporting(true);
      try {
        const docQuestions = questions.flatMap((q, index) => {

          // Gộp "Câu X." và nội dung vào cùng một paragraph
          const questionParagraph = new Paragraph({ 
              children: [
                  new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 24 }),
                  ...parseContentToDocx(q.content)
              ],
              spacing: { after: 150 } 
          });

          const parts = [
            questionParagraph,
          ];

          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options) {
            q.options.forEach((opt, idx) => {
              const label = ['A', 'B', 'C', 'D'][idx];
              let cleanOpt = opt.replace(/^[A-D][\.\)\s]+/, '').trim();

              parts.push(new Paragraph({ 
                  children: [
                      new TextRun({ text: `${label}. `, bold: true, size: 24 }),
                      ...parseContentToDocx(cleanOpt)
                  ], 
                  indent: { left: 720 }, 
                  spacing: { after: 50 } 
              }));
            });
          }
          if (q.type === QuestionType.ESSAY) {
              // Word export for Essay: Add 4 boxes placeholder
              parts.push(new Paragraph({ 
                children: [new TextRun({ text: "Trả lời: [  ] [  ] [  ] [  ]", font: "Courier New", size: 28 })], 
                spacing: { before: 200, after: 200 } 
              }));
          }

          parts.push(
              new Paragraph({ 
                  children: [
                      new TextRun({ text: "Lời giải", bold: true, size: 22, underline: { type: UnderlineType.SINGLE, color: "000000" } })
                  ], 
                  spacing: { before: 200 } 
              }),
              new Paragraph({ 
                  children: [
                      new TextRun({ text: "Đáp án đúng: ", bold: true, color: "008000", size: 24 }),
                      ...parseContentToDocx(q.correctAnswer)
                  ] 
              }),
              new Paragraph({ 
                  children: parseContentToDocx(q.solution), 
                  spacing: { after: 400 } 
              })
          );
          return parts;
        });

        const doc = new Document({
          creator: "Trợ Lý Luyện Thi Thông Minh", title: `${config.subject} - ${config.grade}`,
          sections: [{ 
            headers: {
                default: new Header({
                    children: [
                        new Paragraph({
                            children: [
                                new TextRun({ text: "Thầy Vũ Tiến Lực - Trường THPT Nguyễn Hữu Cảnh", bold: true, size: 20 }),
                                new TextRun({ text: "\t" }),
                                new TextRun({ children: ["Trang ", PageNumber.CURRENT], size: 20 })
                            ],
                            tabStops: [
                                { type: TabStopType.RIGHT, position: TabStopPosition.MAX }
                            ],
                        })
                    ]
                })
            },
            properties: {}, 
            children: [
              new Paragraph({ text: "PHIẾU LUYỆN TẬP", heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }),
              new Paragraph({ text: `Môn: ${config.subject} | ${config.grade}`, heading: HeadingLevel.HEADING_2, alignment: AlignmentType.CENTER }),
              new Paragraph({ text: `Chủ đề: ${config.topic}`, alignment: AlignmentType.CENTER, spacing: { after: 400 } }),
              ...docQuestions
            ] 
          }],
        });
        const blob = await Packer.toBlob(doc);
        const saveFunc = (FileSaver as any).saveAs || FileSaver;
        saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.docx`);
      } catch (e) { console.error(e); alert("Có lỗi khi tạo file Word."); } finally { setIsExporting(false); }
  };

  const results = calculateScore();
  const feedback = getFeedback(results.score);

  // Helper to render a single question card
  const renderQuestionCard = (q: Question, idx: number, isSlideMode: boolean) => {
    const isAnswered = userAnswers[idx] !== undefined;
    const userAns = userAnswers[idx];
    let isCorrect = false;

    if (isAnswered) {
        if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
            const label = ['A', 'B', 'C', 'D'][userAns];
            isCorrect = q.correctAnswer.trim().toUpperCase().startsWith(label);
        } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
            const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
            const cleanUser = userAns.trim().toUpperCase();
            isCorrect = (cleanUser !== '' && cleanCorrect === cleanUser);
        }
    }

    const canViewSolution = showAnswers || isAnswered || isSubmitted;

    // Apply scaling
    const scaleStyle = { fontSize: `${zoomLevel * 100}%` };

    // Zoom effect class for fullscreen
    const zoomEffectClass = (isSlideMode && isFullscreen) ? 'scale-105 origin-top' : 'scale-100 origin-top';

    return (
        <div 
          id={`question-${idx}`}
          key={`${q.id}-${idx}`} 
          className={`print-break-inside-avoid bg-white dark:bg-slate-800 shadow-xl border relative overflow-hidden transition-all duration-300
             ${isSlideMode ? 'h-full flex flex-col p-4 md:px-8 pt-4 rounded-3xl animate-fade-in' : 'p-8 md:p-10 rounded-3xl mb-12'}
             ${isAnswered || isSubmitted
                ? (isCorrect ? 'border-emerald-200 dark:border-emerald-700 ring-2 ring-emerald-100 dark:ring-emerald-900/30' : 'border-red-200 dark:border-red-700 ring-2 ring-red-100 dark:ring-red-900/30')
                : 'border-slate-100 dark:border-slate-700'
             }
             ${isEditMode ? 'ring-2 ring-dashed ring-slate-300 dark:ring-slate-600' : ''}
          `}
          style={scaleStyle}
        >
          {/* Watermark Number */}
          <div className="absolute top-0 right-0 p-4 opacity-10 font-black text-9xl text-slate-300 dark:text-slate-600 select-none pointer-events-none">
            {idx + 1}
          </div>

          {/* Delete Button (Edit Mode) */}
          {isEditMode && (
             <div className="absolute top-4 right-4 z-20 animate-fade-in">
                <button 
                  onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleDeleteQuestion(idx); }}
                  className="flex items-center gap-1 bg-red-100 dark:bg-red-900/50 hover:bg-red-200 dark:hover:bg-red-900/80 text-red-600 dark:text-red-300 px-3 py-1.5 rounded-full font-bold shadow-sm transition-colors border border-red-200 dark:border-red-800"
                  title="Xóa câu hỏi này"
                >
                    <Trash2 className="w-4 h-4" /> Xóa
                </button>
             </div>
          )}

          {/* Badge for Correct/Incorrect - Absolute pos */}
          {isAnswered && !isEditMode && (
             <div className="absolute top-0 right-0 p-4 no-print animate-fade-in-up z-10">
                <div className={`flex items-center gap-1 font-bold px-3 py-1 rounded-full shadow-sm text-base ${isCorrect ? 'bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300' : 'bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300'}`}>
                    {isCorrect ? <Star className="w-4 h-4 fill-emerald-700 dark:fill-emerald-300" /> : <XCircle className="w-4 h-4" />}
                    {isCorrect ? "+1 Điểm" : "0 Điểm"}
                </div>
             </div>
          )}

          <div className={`flex flex-col h-full ${isSlideMode ? '' : 'gap-6'}`}>

              {/* --- QUESTION CONTENT AREA --- */}
              <div className={`relative z-10 ${isSlideMode ? 'mb-4 flex-shrink-0' : 'mb-2'} transition-transform duration-700 ease-out ${zoomEffectClass}`}>
                {!isSlideMode && (
                    <div className="flex items-center gap-3 mb-4">
                        <span className="flex items-center justify-center w-10 h-10 rounded-full bg-indigo-600 dark:bg-indigo-500 text-white font-bold text-lg shadow-md">
                            {idx + 1}
                        </span>
                        <span className="text-sm font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                            {q.difficulty}
                        </span>
                    </div>
                )}

                <div className={`text-[1.5em] leading-tight text-slate-800 dark:text-slate-100 font-medium ${isSlideMode ? 'text-[1.8em]' : ''}`}>
                  {isSlideMode && <span className="text-indigo-600 dark:text-indigo-400 font-bold mr-2">Câu {idx + 1}:</span>}
                  <MathRenderer content={q.content} />
                </div>
              </div>

              {/* --- OPTIONS / ANSWER AREA --- */}
              <div className={isSlideMode ? 'flex-grow overflow-y-auto pr-2 pb-24' : ''}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                    <div className={`grid grid-cols-1 md:grid-cols-2 gap-5 mt-2`}>
                    {q.options.map((opt, optIdx) => {
                        const label = ['A', 'B', 'C', 'D'][optIdx];
                        const cleanContent = opt.replace(/^[A-D][\.\)\s]+/, '').trim().replace(/\*\*/g, '');
                        const theme = OPTION_THEMES[optIdx % 4];

                        const isSelected = userAns === optIdx;
                        const isCorrectAnswer = q.correctAnswer.trim().toUpperCase().startsWith(label);

                        let stateStyles = `border-2 ${theme.bg} ${theme.border} ${theme.text}`;

                        if (!isAnswered && !isSubmitted) {
                            stateStyles = `${theme.bg} ${theme.border} ${theme.text} ${theme.hover} hover:scale-[1.01] cursor-pointer`;
                        } else {
                            if (isCorrectAnswer) stateStyles = `bg-emerald-100 dark:bg-emerald-900/30 border-emerald-500 dark:border-emerald-500 text-emerald-900 dark:text-emerald-200 ring-2 ring-emerald-200 dark:ring-emerald-800`;
                            else if (isSelected && !isCorrectAnswer) stateStyles = `bg-red-100 dark:bg-red-900/30 border-red-500 dark:border-red-500 text-red-900 dark:text-red-200 opacity-80`;
                            else stateStyles = `${theme.bg} border-transparent opacity-50 grayscale`;
                        }

                        if (isEditMode) {
                            stateStyles = `${theme.bg} ${theme.border} ${theme.text} opacity-80 cursor-not-allowed`;
                        }

                        return (
                        <div 
                            key={optIdx}
                            onClick={() => handleOptionSelect(idx, optIdx)}
                            className={`relative group flex items-start gap-4 p-5 rounded-2xl transition-all duration-200 text-[1.2em] leading-snug ${stateStyles}`}
                        >
                            <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-lg font-bold text-xl transition-colors
                            ${(isAnswered || isSubmitted) && isCorrectAnswer ? 'bg-emerald-500 text-white' : ''}
                            ${(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer ? 'bg-red-500 text-white' : ''}
                            ${(!isAnswered && !isSubmitted) ? (theme.labelBg + ' ' + theme.text) : (!isCorrectAnswer && !isSelected ? 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400' : '')}
                            `}>
                            {label}.
                            </div>
                            <div className="flex-grow pt-1"><MathRenderer content={cleanContent} /></div>
                            {(isAnswered || isSubmitted) && isCorrectAnswer && <CheckCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-emerald-600 dark:text-emerald-400" />}
                            {(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer && <XCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-red-500 dark:text-red-400" />}
                        </div>
                        );
                    })}
                    </div>
                )}

                {/* ESSAY / SHORT ANSWER INPUT - 4 Chars Box */}
                {q.type === QuestionType.ESSAY && (
                    <div className="my-6">
                        <label className="block text-slate-500 dark:text-slate-400 font-bold text-sm mb-3 uppercase tracking-wider">
                            Điền kết quả (Tối đa 4 ký tự):
                        </label>
                        <div className="relative w-fit">
                            <input
                                type="text"
                                maxLength={4}
                                value={typeof userAns === 'string' ? userAns : ''}
                                onChange={(e) => handleEssayChange(idx, e.target.value)}
                                disabled={isSubmitted || isEditMode}
                                placeholder="____"
                                className={`w-48 h-16 text-center text-4xl font-mono tracking-[0.3em] font-bold uppercase border-2 rounded-xl outline-none transition-all shadow-inner
                                    ${(isAnswered || isSubmitted)
                                        ? (isCorrect
                                            ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300'
                                            : 'border-red-500 bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300')
                                        : 'border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 dark:focus:ring-indigo-900/30'}
                                `}
                            />
                            {/* Validation Icon inside/near input */}
                            {(isAnswered || isSubmitted) && (
                                <div className="absolute top-1/2 -right-10 -translate-y-1/2">
                                    {isCorrect 
                                        ? <CheckCircle className="w-8 h-8 text-emerald-500 dark:text-emerald-400 animate-bounce" /> 
                                        : <XCircle className="w-8 h-8 text-red-500 dark:text-red-400" />
                                    }
                                </div>
                            )}
                        </div>
                        <p className="mt-2 text-xs text-slate-400 dark:text-slate-500 italic">
                            * Nhập chính xác kết quả số hoặc chữ cái. Ví dụ: 10, -5, A, 3.14
                        </p>
                    </div>
                )}

                {/* --- SLIDE MODE: SOLUTION TOGGLE & CONTENT (MOVED HERE) --- */}
                {isSlideMode && !showAnswers && (
                    <div className="mt-8 mb-4">
                        {canViewSolution ? (
                            <button 
                                onClick={() => toggleSolution(q.id)}
                                className="w-full md:w-auto px-8 py-3 rounded-full bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 font-bold text-lg flex items-center justify-center gap-2 transition-all shadow-sm mx-auto border-2 border-slate-200 dark:border-slate-600"
                            >
                                {activeSolutions[q.id] ? <EyeOff className="w-5 h-5"/> : <Key className="w-5 h-5"/>}
                                {activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải chi tiết'}
                            </button>
                        ) : (
                            <div className="flex justify-center mt-8">
                                <div className="text-slate-400 italic flex items-center gap-2 bg-slate-50 dark:bg-slate-800/50 px-6 py-3 rounded-full">
                                    <EyeOff className="w-5 h-5" /> Hãy chọn đáp án để xem lời giải
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* --- SLIDE MODE: EXPANDED SOLUTION DISPLAY --- */}
                {isSlideMode && (showAnswers || activeSolutions[q.id]) && (
                    <div className="mt-6 mb-12 animate-fade-in-up">
                        <div className="bg-emerald-50 dark:bg-emerald-900/10 border-2 border-emerald-100 dark:border-emerald-900/50 rounded-3xl p-6 md:p-8 shadow-sm">
                            <h4 className="font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-3 mb-6 pb-4 border-b border-emerald-200 dark:border-emerald-800/50">
                                <CheckCircle className="w-8 h-8 fill-current" /> Lời giải chi tiết
                            </h4>

                            <div className="text-xl md:text-2xl text-slate-800 dark:text-slate-100 space-y-6 leading-relaxed">
                                <p className="font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-3">
                                    Đáp án đúng: <span className="bg-emerald-200 dark:bg-emerald-800 text-emerald-900 dark:text-white px-4 py-1 rounded-xl shadow-sm"><MathRenderer content={q.correctAnswer} /></span>
                                </p>

                                {/* Structured Solution Content */}
                                <div className="space-y-4">
                                    {q.solution.split('\n').filter(line => line.trim() !== '').map((line, i) => (
                                        <div key={i} className="flex items-start gap-4">
                                            <span className="text-emerald-500 mt-1.5 flex-shrink-0 text-xl">✦</span>
                                            <div className="flex-1">
                                                <MathRenderer content={line} />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Collapse Button inside */}
                            <div className="mt-8 flex justify-center">
                                <button 
                                    onClick={() => toggleSolution(q.id)}
                                    className="text-emerald-600 dark:text-emerald-400 hover:text-emerald-800 dark:hover:text-emerald-200 font-bold flex items-center gap-2 px-4 py-2 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 rounded-full transition-colors"
                                >
                                    <ChevronUp className="w-5 h-5" /> Thu gọn
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                 {/* Hints & Solutions (LIST MODE ONLY) */}
                 {!isSlideMode && (
                     <div className="space-y-2 text-base mt-6">
                        <div className="flex flex-wrap gap-2">
                            <button 
                                onClick={() => toggleHint(q.id)}
                                className="font-medium text-indigo-600 dark:text-indigo-300 hover:text-indigo-800 dark:hover:text-indigo-200 flex items-center gap-2 px-4 py-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors"
                            >
                                <Lightbulb className="w-5 h-5" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Xem gợi ý'}
                            </button>

                            {!showAnswers && (
                                <>
                                {canViewSolution ? (
                                    <button onClick={() => toggleSolution(q.id)} className="text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 flex items-center gap-1 px-4 py-2 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors">
                                        {activeSolutions[q.id] ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}
                                        {activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải chi tiết'}
                                    </button>
                                ) : (
                                    <div className="text-sm text-slate-400 italic px-4 py-2 flex items-center gap-2">
                                        <EyeOff className="w-4 h-4" /> Trả lời để xem giải
                                    </div>
                                )}
                                </>
                            )}
                        </div>

                         {activeHints[q.id] && q.hints && (
                             <div className="bg-indigo-50 dark:bg-indigo-900/20 p-6 rounded-2xl border border-indigo-100 dark:border-indigo-800 text-lg text-indigo-900 dark:text-indigo-200 animate-fade-in shadow-inner mt-2">
                                 <ul className="list-disc list-inside space-y-2 pl-2">
                                     {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                                 </ul>
                             </div>
                         )}

                         {(showAnswers || activeSolutions[q.id]) && (
                             <div className="mt-4 p-6 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border-2 border-emerald-100 dark:border-emerald-800 text-emerald-900 dark:text-emerald-100 shadow-sm animate-fade-in">
                                 <h4 className="font-bold text-xl mb-3 flex items-center gap-2 border-b border-emerald-200 dark:border-emerald-700 pb-2">
                                     <CheckCircle className="w-6 h-6" /> Đáp án & Lời giải chi tiết
                                 </h4>
                                 <p className="mb-4 font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                                     Đáp án: <span className="px-3 py-1 bg-emerald-200 dark:bg-emerald-800 rounded-lg"><MathRenderer content={q.correctAnswer} /></span>
                                 </p>
                                 <div className="text-lg whitespace-pre-wrap leading-relaxed">
                                     <MathRenderer content={q.solution} inline={false} />
                                 </div>
                             </div>
                         )}
                     </div>
                 )}
              </div>

              {/* --- FOOTER INFO (SLIDE MODE ONLY - Simplified) --- */}
              {isSlideMode && (
                  <div className="mt-auto flex flex-col gap-4">
                       <div className="flex flex-wrap items-center justify-between gap-4 border-t border-slate-100/50 dark:border-slate-700/50 pt-6">
                           <div className="flex items-center gap-3">
                               <span className="text-sm font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600">
                                    {q.difficulty}
                                </span>
                                <button 
                                    onClick={() => toggleHint(q.id)}
                                    className="text-sm font-medium text-indigo-600 dark:text-indigo-300 hover:text-indigo-800 dark:hover:text-indigo-200 flex items-center gap-1 px-3 py-1 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-full transition-colors"
                                >
                                    <Lightbulb className="w-4 h-4" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Gợi ý'}
                                </button>
                           </div>
                       </div>

                       {/* Hint Display (Bottom Drawer style for Hint only) */}
                       {activeHints[q.id] && (
                            <div className="absolute bottom-0 left-0 right-0 h-[40%] bg-white dark:bg-slate-800 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.15)] border-t border-slate-200 dark:border-slate-700 z-30 flex flex-col animate-fade-in-up">
                                 <div className="flex items-center justify-between px-6 py-3 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50 rounded-t-3xl">
                                     <div className="flex items-center gap-2">
                                         <span className="text-indigo-600 dark:text-indigo-400 font-bold flex items-center gap-2 text-lg"><Lightbulb className="w-6 h-6"/> Gợi ý</span>
                                     </div>
                                     <button 
                                         onClick={() => toggleHint(q.id)}
                                         className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
                                         title="Thu gọn"
                                     >
                                         <ChevronDown className="w-6 h-6" />
                                     </button>
                                 </div>
                                 <div className="flex-1 overflow-y-auto p-6">
                                      {q.hints && (
                                          <div className="mb-6">
                                              <ul className="list-disc list-inside space-y-3 pl-2 text-slate-700 dark:text-slate-200 text-xl md:text-2xl leading-relaxed">
                                                 {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                                              </ul>
                                          </div>
                                      )}
                                 </div>
                            </div>
                       )}
                  </div>
              )}
          </div>
        </div>
    );
  };

  if (questions.length === 0) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-8 text-center text-slate-500 dark:text-slate-400">
              <div className="bg-slate-100 dark:bg-slate-800 p-8 rounded-full mb-4">
                 <FileText className="w-12 h-12 text-slate-400 dark:text-slate-500" />
              </div>
              <h2 className="text-xl font-bold text-slate-700 dark:text-slate-200">Chưa có câu hỏi nào</h2>
              <p className="mb-6">Bạn đã xóa hết câu hỏi hoặc dữ liệu trống.</p>
              <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-bold">Tạo đề mới</button>
          </div>
      )
  }

  return (
    <div 
      className={`
        mx-auto bg-slate-50 dark:bg-slate-900 relative transition-all duration-300
        ${isFullscreen ? 'overflow-hidden h-screen' : 'pb-24'}
        ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
        ${!showBlackboard || blackboardMode === 'bottom' ? (viewMode === 'slide' ? 'w-full max-w-[98vw]' : 'w-full max-w-7xl') : ''}
      `} 
      ref={containerRef}
    >
      <style>{`
        @keyframes slideInRight {
          from { opacity: 0; transform: translateX(30px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideInLeft {
          from { opacity: 0; transform: translateX(-30px); }
          to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-in-right { animation: slideInRight 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-slide-in-left { animation: slideInLeft 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>

      {/* Side Mode Content Wrapper */}
      <div className={`
         transition-all duration-300 ease-in-out
         ${showBlackboard && blackboardMode === 'side' 
            ? 'w-[50vw] h-[calc(100vh-64px)] fixed left-0 top-[64px] overflow-y-auto z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl px-4 md:px-6 pt-4 pb-24 bg-slate-50 dark:bg-slate-900' 
            : ''}
      `}>

        {/* Top Bar - Hidden in Fullscreen */}
        <div className={`no-print bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 p-4 sticky top-4 z-20 flex flex-wrap gap-4 justify-between items-center transition-all ${isFullscreen ? 'hidden' : ''}`}>
            <div className="flex items-center gap-2">
            <button onClick={onReset} className="text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200 font-medium text-sm px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">← Tạo đề mới</button>
            <div className="h-6 w-px bg-slate-300 dark:bg-slate-600"></div>
            <button onClick={onRegenerate} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 border border-transparent hover:border-indigo-100 dark:hover:border-indigo-800 transition-colors">
                <RefreshCw className="w-4 h-4" /> <span className="hidden sm:inline">Đề tương tự</span>
            </button>
            <div className="h-6 w-px bg-slate-300 dark:bg-slate-600"></div>
            <button 
                    onClick={() => setIsEditMode(!isEditMode)} 
                    className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-colors ${isEditMode ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 border border-orange-200 dark:border-orange-800' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
            >
                    <Edit className="w-4 h-4" /> <span className="hidden sm:inline">{isEditMode ? 'Đang chỉnh sửa' : 'Chỉnh sửa'}</span>
            </button>
            </div>
            <div className="flex flex-wrap gap-2 items-center">
            <button onClick={toggleFullScreen} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700">
                <Maximize className="w-4 h-4" /> <span className="hidden sm:inline">Toàn màn hình</span>
            </button>

            <button 
                onClick={handleExportJSON}
                className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 shadow-sm transition-all"
                title="Lưu file để chỉnh sửa sau này"
            >
                <Save className="w-4 h-4" /> <span className="hidden sm:inline">Lưu</span>
            </button>

            <button onClick={handleDownloadWord} disabled={isExporting} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 dark:bg-blue-700 text-white hover:bg-blue-700 dark:hover:bg-blue-600 shadow-sm transition-all disabled:opacity-50">
                {isExporting ? <span className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></span> : <Download className="w-4 h-4" />} <span className="hidden sm:inline">Word</span>
            </button>
            <div className="h-8 w-px bg-slate-200 dark:bg-slate-600 mx-1"></div>
            <div className="flex gap-2">
                <button onClick={handlePrintStudent} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-300 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-700 shadow-sm"><FileSignature className="w-4 h-4" /> In đề A4</button>
                <button onClick={handlePrintTeacher} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-indigo-600 dark:bg-indigo-700 text-white hover:bg-indigo-700 dark:hover:bg-indigo-600 shadow-sm"><Printer className="w-4 h-4" /> In Lời Giải</button>
            </div>
            </div>
        </div>

        {/* Info Bar - White Theme with Black Text */}
        <div className={`no-print bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-slate-200 shadow-sm p-4 flex flex-col sm:flex-row justify-between items-center gap-4 ${isFullscreen ? 'absolute top-0 left-0 right-0 z-10 rounded-none bg-white/95 dark:bg-slate-900/95 backdrop-blur-sm' : 'rounded-xl mt-4 relative'}`}>
            <div className="flex items-center gap-3 w-full sm:w-auto">
                <div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-lg text-indigo-600 dark:text-indigo-400"><User className="w-5 h-5" /></div>
                <input 
                    type="text" 
                    placeholder="Nhập tên học sinh..." 
                    value={studentName}
                    onChange={(e) => setStudentName(e.target.value)}
                    disabled={isSubmitted}
                    className="bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-600 rounded-lg px-3 py-1.5 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900 outline-none placeholder-slate-400 dark:placeholder-slate-500 text-base font-medium w-full sm:w-64 transition-all"
                />
            </div>
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-700 px-4 py-1.5 rounded-full border border-slate-200 dark:border-slate-600">
                    <CheckCircle className="w-5 h-5 text-emerald-500" />
                    <span className="font-bold text-lg text-slate-900 dark:text-slate-100">{results.correct} / {results.total}</span>
                </div>
                <div className="text-sm font-medium text-slate-500 dark:text-slate-400">
                    Làm bài: <span className="text-slate-900 dark:text-slate-200 font-semibold">{results.answered}/{results.total}</span> câu
                </div>
            </div>
        </div>

        {/* --- CONTENT AREA --- */}
        <div className={`print-container min-h-screen ${isFullscreen ? 'h-full flex flex-col pt-20 pb-24 px-4' : 'pt-6'}`}>

            {/* Printable Header - DYNAMIC */}
