// --- ADVANCED LATEX TO DOCX PARSER V2.0 ---

const SYMBOL_MAP: Record<string, string> = {
    // Greek
    '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ', '\\epsilon': 'ε', '\\varepsilon': 'ε',
    '\\zeta': 'ζ', '\\eta': 'η', '\\theta': 'θ', '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ',
    '\\mu': 'μ', '\\nu': 'ν', '\\xi': 'ξ', '\\pi': 'π', '\\rho': 'ρ', '\\sigma': 'σ',
    '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ', '\\varphi': 'φ', '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
    '\\Delta': 'Δ', '\\Gamma': 'Γ', '\\Lambda': 'Λ', '\\Omega': 'Ω', '\\Phi': 'Φ', '\\Pi': 'Π',
    '\\Sigma': 'Σ', '\\Theta': 'Θ',

    // Operators & Relations
    '\\times': '×', '\\cdot': '·', '\\div': '÷', '\\pm': '±', '\\mp': '∓',
    '\\leq': '≤', '\\geq': '≥', '\\neq': '≠', '\\approx': '≈', '\\equiv': '≡', '\\sim': '∼',
    '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃', '\\subseteq': '⊆', '\\supseteq': '⊇',
    '\\cup': '∪', '\\cap': '∩', '\\setminus': '\\',
    '\\infty': '∞', '\\forall': '∀', '\\exists': '∃', '\\emptyset': '∅', '\\nabla': '∇',
    '\\partial': '∂', '\\angle': '∠', '\\perp': '⊥', '\\parallel': '∥',
    '\\rightarrow': '→', '\\leftarrow': '←', '\\leftrightarrow': '↔', 
    '\\Rightarrow': '⇒', '\\Leftarrow': '⇐', '\\Leftrightarrow': '⇔',
    '\\longmapsto': '↦', '\\to': '→',
    '\\circ': '∘', '\\bullet': '•', '^{\\circ}': '°', '\\deg': '°',

    // Sets
    '\\mathbb{R}': 'ℝ', '\\mathbb{N}': 'ℕ', '\\mathbb{Z}': 'ℤ', '\\mathbb{Q}': 'ℚ', '\\mathbb{C}': 'ℂ',
};

// Helper to find the end index of a balanced brace group starting at `start`
const findBalancedBrace = (str: string, start: number): number => {
    let depth = 0;
    for (let i = start; i < str.length; i++) {
        if (str[i] === '{') depth++;
        else if (str[i] === '}') {
            depth--;
            if (depth === 0) return i;
        }
    }
    return -1;
};

// Main Parser Class-like structure for state management
class LatexParser {
    latex: string;
    index: number;

    constructor(latex: string) {
        this.latex = latex;
        this.index = 0;
    }

    parse(): any[] {
        const nodes: any[] = [];

        while (this.index < this.latex.length) {
            const char = this.latex[this.index];

            if (char === '\\') {
                const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);

                if (match) {
                    const cmd = match[1];
                    this.index += match[0].length;

                    // --- COMMAND HANDLERS ---

                    // 1. Fractions
                    if (cmd === 'frac' || cmd === 'dfrac') {
                        const num = this.parseGroup();
                        const den = this.parseGroup();
                        nodes.push(new MathFraction({ numerator: num, denominator: den }));
                    }

                    // 2. Roots
                    else if (cmd === 'sqrt') {
                        let degree = [];
                        if (this.peek() === '[') {
                            degree = this.parseOptionalGroup();
                        }
                        const content = this.parseGroup();
                        nodes.push(new MathRadical({ degree, children: content }));
                    }

                    // 3. Integrals, Sums (Only Sum and Integral supported nicely in simplified docx export)
                    else if (cmd === 'int') {
                        this.handleIntegral(nodes);
                    }
                    else if (cmd === 'sum') {
                        this.handleSum(nodes);
                    }

                    // 4. Limits
                    else if (cmd === 'lim') {
                        this.handleLimit(nodes);
                    }

                    // 5. Functions (sin, cos, log, etc.)
                    else if (['sin', 'cos', 'tan', 'cot', 'log', 'ln', 'exp', 'min', 'max'].includes(cmd)) {
                         nodes.push(new MathRun(cmd + " ")); 
                    }

                    // 6. Accents - Fallback to simple content rendering
                    else if (['vec', 'hat', 'overline', 'bar', 'tilde'].includes(cmd)) {
                        const content = this.parseGroup();
                        nodes.push(...content);
                        // Optional: Append accent char as run if critical, but complex to align.
                    }

                    // 7. Text
                    else if (cmd === 'text' || cmd === 'mbox') {
                        const textContent = this.extractGroupContent();
                        nodes.push(new MathRun(textContent));
                    }

                    // 8. Environments (Cases) - Fallback to simple list with semicolons
                    else if (cmd === 'begin') {
                        const envName = this.extractGroupContent();
                        if (envName === 'cases') {
                            const endTag = '\\end{cases}';
                            const endIndex = this.latex.indexOf(endTag, this.index);

                            if (endIndex !== -1) {
                                const content = this.latex.slice(this.index, endIndex);
                                this.index = endIndex + endTag.length;

                                // Open brace to indicate system
                                nodes.push(new MathRun("{ "));

                                // Split by \\ for rows
                                const rows = content.split(/\\\\/);
                                rows.forEach((row, i) => {
                                    // Replace alignment & with space
                                    const cleanRow = row.replace(/&/g, ' ').trim();
                                    if(cleanRow) {
                                        const rowNodes = new LatexParser(cleanRow).parse();
                                        nodes.push(...rowNodes);
                                        // Add semicolon separator between equations, except last one
                                        if (i < rows.length - 1) {
                                            nodes.push(new MathRun("; "));
                                        }
                                    }
                                });
                            }
                        } else {
                            // unknown env, skip start tag
                        }
                    }
                    else if (cmd === 'end') {
                        // Skip \end{...}
                         this.extractGroupContent(); 
                    }

                    // 9. Formatting
                    else if (['left', 'right'].includes(cmd)) {
                        // Ignore delimiters
                        // Just consume next char if it's a delimiter char
                         const nextChar = this.latex[this.index];
                         if (nextChar && ['(', ')', '[', ']', '|', '{', '}', '.'].includes(nextChar)) {
                             if (nextChar !== '.') { // dot is null delimiter in latex
                                nodes.push(new MathRun(nextChar));
                             }
                             this.index++;
                         } else if (nextChar === '\\') {
                             // maybe \{ or \}
                             // let next iteration handle it
                         }
                    }

                    // 10. Symbols
                    else if (SYMBOL_MAP[`\\${cmd}`]) {
                        nodes.push(new MathRun(SYMBOL_MAP[`\\${cmd}`]));
                    }

                    // Fallback
                    else {
                        // Unknown command
                    }

                    // Consume \limits if present (formatting hint)
                    if (this.latex.startsWith('\\limits', this.index)) {
                        this.index += 7;
                    }
                } 
                else {
                    // Escaped char like \{ or \%
                    const nextChar = this.latex[this.index];
                    if (['{', '}', '%', '$', '&', '#', '_'].includes(nextChar)) {
                         nodes.push(new MathRun(nextChar));
                         this.index++;
                    } else {
                         // space or other
                         this.index++;
                    }
                }
            }

            // Superscript / Subscript
            else if (char === '^' || char === '_') {
                this.handleScript(char, nodes);
            }

            // Grouping
            else if (char === '{') {
                const group = this.parseGroup();
                nodes.push(...group);
            }
            else if (char === '}') {
                this.index++;
            }

            else {
                // Regular Text
                // Consume until next special char
                let text = char;
                this.index++;
                while(this.index < this.latex.length) {
                    const c = this.latex[this.index];
                    if (['\\', '^', '_', '{', '}'].includes(c)) break;
                    text += c;
                    this.index++;
                }
                nodes.push(new MathRun(text));
            }
        }
        return nodes;
    }

    // --- HELPER METHODS ---

    peek(): string {
        return this.latex[this.index];
    }

    // Parse { ... } and return nodes
    parseGroup(): any[] {
        if (this.latex[this.index] !== '{') {
             const char = this.latex[this.index];
             this.index++;
             return [new MathRun(char)];
        }

        const start = this.index;
        const end = findBalancedBrace(this.latex, start);
        if (end === -1) {
            this.index = this.latex.length; // error
            return [];
        }

        const content = this.latex.slice(start + 1, end);
        this.index = end + 1;

        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    parseOptionalGroup(): any[] {
        if (this.latex[this.index] !== '[') return [];
        const end = this.latex.indexOf(']', this.index);
        if (end === -1) return [];

        const content = this.latex.slice(this.index + 1, end);
        this.index = end + 1;
        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    extractGroupContent(): string {
         if (this.latex[this.index] !== '{') return '';
         const start = this.index;
         const end = findBalancedBrace(this.latex, start);
         if (end === -1) return '';
         this.index = end + 1;
         return this.latex.slice(start + 1, end);
    }

    handleScript(type: string, nodes: any[]) {
        this.index++; // consume ^ or _
        const lastNode = nodes.pop();

        // Parse the script content
        let scriptNodes: any[] = [];
        if (this.latex[this.index] === '{') {
            scriptNodes = this.parseGroup();
        } else {
            const char = this.latex[this.index];
             if (char === '\\') {
                 // read command
                 const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);
                 if (match) {
                     const sub = new LatexParser(match[0]);
                     scriptNodes = sub.parse();
                     this.index += match[0].length;
                 } else {
                     this.index++;
                 }
             } else {
                scriptNodes = [new MathRun(char)];
                this.index++;
             }
        }

        if (!lastNode) {
            nodes.push(new MathRun(type)); // fallback
            nodes.push(...scriptNodes);
            return;
        }

        if (type === '^') {
            nodes.push(new MathSuperScript({ children: [lastNode], superScript: scriptNodes }));
        } else {
            nodes.push(new MathSubScript({ children: [lastNode], subScript: scriptNodes }));
        }
    }

    handleSum(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathSum({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    handleIntegral(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathIntegral({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    parseLimits() {
        let subScript: any[] | undefined;
        let superScript: any[] | undefined;

        // Check for \limits which is optional
        if (this.latex.startsWith('\\limits', this.index)) {
             this.index += 7;
        }

        // Look ahead for _ and ^ (order doesn't matter)
        for (let k = 0; k < 2; k++) {
            this.skipSpaces();
            if (this.latex[this.index] === '_') {
                this.index++;
                subScript = this.parseArg();
            } else if (this.latex[this.index] === '^') {
                this.index++;
                superScript = this.parseArg();
            } else {
                break;
            }
        }
        return { subScript, superScript };
    }

    handleLimit(nodes: any[]) {
        // \lim_{x \to 0}
        this.skipSpaces();
        let limit: any[] = [];
        if (this.latex[this.index] === '_') {
             this.index++;
             limit = this.parseArg();
        }

        nodes.push(new MathLimitLower({
            children: [new MathRun("lim")],
            limit: limit
        }));
    }

    skipSpaces() {
        while(this.latex[this.index] === ' ') this.index++;
    }

    parseArg(): any[] {
        if (this.latex[this.index] === '{') return this.parseGroup();
        const char = this.latex[this.index];
        this.index++;
        return [new MathRun(char)];
    }
}


export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // Local state for questions to allow deletion/modification
  const [questions, setQuestions] = useState<Question[]>(data.questions);

  const [showAnswers, setShowAnswers] = useState(false);
  const [activeHints, setActiveHints] = useState<Record<number, boolean>>({});
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [isExporting, setIsExporting] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);

  // Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Presentation Mode State
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideDirection, setSlideDirection] = useState<'next' | 'prev'>('next'); // State for animation direction
  const [zoomLevel, setZoomLevel] = useState(1); // 1 = 100%
  const [isLaserPointer, setIsLaserPointer] = useState(false);

  // Student Practice State
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, number | string>>({}); // Supports both index (MC) and string (Essay)
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Sync state with props when data changes
  useEffect(() => {
    setQuestions(data.questions);
    setUserAnswers({});
    setIsSubmitted(false);
    setShowScoreModal(false);
    setShowAnswers(false);
    setStudentName('');
    setCurrentSlide(0);
    setViewMode('list');
    setIsEditMode(false);
  }, [data]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Avoid stealing focus from input fields
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight' || e.key === ' ') {
          nextSlide();
        } else if (e.key === 'ArrowLeft') {
          prevSlide();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentSlide, questions.length]);

  // Close nav when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showNav]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        containerRef.current.requestFullscreen().catch((err) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const nextSlide = () => {
    if (currentSlide < questions.length - 1) {
      setSlideDirection('next');
      setCurrentSlide(prev => prev + 1);
      // Auto close solution when switching slides for clean look
      if (!showAnswers) setActiveSolutions({});
    }
  };

  const prevSlide = () => {
    if (currentSlide > 0) {
      setSlideDirection('prev');
      setCurrentSlide(prev => prev - 1);
    }
  };

  const jumpToQuestion = (idx: number) => {
    if (viewMode === 'slide') {
      // Determine direction for smooth jump
      setSlideDirection(idx > currentSlide ? 'next' : 'prev');
      setCurrentSlide(idx);
    } else {
      const element = document.getElementById(`question-${idx}`);
      if (element) {
        // If in side mode, we scroll the window or the inner container depending on implementation.
        // For simplicity, we use scrollIntoView which works in both cases
        element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    setShowNav(false);
  };

  const toggleHint = (id: number) => {
    setActiveHints(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleSolution = (id: number) => {
    setActiveSolutions(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return; 

    // Only set if not already set (toggle behavior could be implemented if needed)
    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: optionIdx
    }));
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode) return;

    // Limit to 4 characters
    if (value.length > 4) return;

    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: value.toUpperCase() // Auto uppercase
    }));
  };

  const handleDeleteQuestion = (idxToDelete: number) => {
    if (!window.confirm(`Bạn có chắc chắn muốn xóa Câu ${idxToDelete + 1} không?`)) {
        return;
    }

    // 1. Calculate new questions
    const newQuestions = questions.filter((_, idx) => idx !== idxToDelete);
    setQuestions(newQuestions);

    // 2. Adjust slide index if necessary
    if (viewMode === 'slide') {
        if (currentSlide === idxToDelete) {
            // If deleting current slide, move to the last available or 0
            if (currentSlide >= newQuestions.length) {
                setCurrentSlide(Math.max(0, newQuestions.length - 1));
            }
        } else if (currentSlide > idxToDelete) {
            // If deleting a preceding slide, shift current index down
            setCurrentSlide(c => Math.max(0, c - 1));
        }
    } else {
         // In list mode, ensure we don't have out of bounds if switching views later
         if (currentSlide >= newQuestions.length) {
            setCurrentSlide(Math.max(0, newQuestions.length - 1));
         }
    }

    // 3. Shift User Answers (keys are indices)
    setUserAnswers(prevAnswers => {
        const newAnswers: Record<number, number | string> = {};
        Object.keys(prevAnswers).forEach(keyStr => {
            const key = parseInt(keyStr);
            if (key < idxToDelete) {
                newAnswers[key] = prevAnswers[key];
            } else if (key > idxToDelete) {
                newAnswers[key - 1] = prevAnswers[key];
            }
        });
        return newAnswers;
    });

    // 4. Reset submission state as the test content has changed
    setIsSubmitted(false);
  };

  const handleSubmitExam = () => {
    const answeredCount = Object.keys(userAnswers).length;

    if (answeredCount < questions.length) {
      if (!confirm(`Bạn mới làm ${answeredCount}/${questions.length} câu. Bạn có chắc chắn muốn nộp bài để xem tổng kết không?`)) {
        return;
      }
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    setShowAnswers(true);
  };

  const calculateScore = () => {
    let correctCount = 0;
    const totalQuestions = questions.length;
    const answeredCount = Object.keys(userAnswers).length;

    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];

      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
             const selectedLabel = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.trim().toUpperCase().startsWith(selectedLabel)) {
                correctCount++;
             }
          } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
             // Compare strings for Essay (normalize removing LaTeX $ and spaces)
             const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
             const cleanUser = userAns.trim().toUpperCase();
             if (cleanUser && cleanCorrect === cleanUser) {
                 correctCount++;
             }
          }
      }
    });

    return {
        correct: correctCount,
        answered: answeredCount,
        total: totalQuestions,
        score: totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 10 * 100) / 100 : 0
    };
  };

  const getFeedback = (score: number) => {
    if (score === 10) return { text: "Tuyệt đối! Em là thiên tài!", color: "text-purple-600 dark:text-purple-400", emoji: <PartyPopper className="w-12 h-12 text-purple-500 animate-bounce" /> };
    if (score >= 9) return { text: "Xuất sắc! Em là niềm tự hào của lớp!", color: "text-emerald-600 dark:text-emerald-400", emoji: <Trophy className="w-12 h-12 text-yellow-400" /> };
    if (score >= 8) return { text: "Rất tốt! Giữ vững phong độ nhé!", color: "text-blue-600 dark:text-blue-400", emoji: <Star className="w-12 h-12 text-blue-400 fill-current" /> };
    if (score >= 6.5) return { text: "Khá tốt! Cần cẩn thận hơn một chút.", color: "text-indigo-600 dark:text-indigo-400", emoji: <Smile className="w-12 h-12 text-indigo-400" /> };
    if (score >= 5) return { text: "Đạt yêu cầu. Cần ôn tập kỹ hơn các câu sai.", color: "text-amber-600 dark:text-amber-400", emoji: <Award className="w-12 h-12 text-amber-400" /> };
    return { text: "Cần cố gắng nhiều hơn. Đừng nản chí!", color: "text-red-600 dark:text-red-400", emoji: <Frown className="w-12 h-12 text-red-400" /> };
  };

  // ... (Print and Export functions remain the same) ...
  const handlePrintStudent = () => {
    document.body.classList.add('printing-student');
    window.print();
    setTimeout(() => { document.body.classList.remove('printing-student'); }, 500);
  };
  const handlePrintTeacher = () => {
    if (!showAnswers) {
      if(confirm('Bạn có muốn bật hiện đáp án trước khi in lời giải không?')) {
        setShowAnswers(true);
        setTimeout(() => window.print(), 100);
        return;
      }
    }
    window.print();
  };

  const handleExportJSON = () => {
    const exportData = { type: 'exam', timestamp: Date.now(), config, data: { ...data, questions } };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const saveFunc = (FileSaver as any).saveAs || FileSaver;
    saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.json`);
  };

  // Helper to parse content mixed with LaTeX ($...$) and Bold (**...**) into Docx Paragraph Children
  const parseContentToDocx = (content: string) => {
      // Split by LaTeX delimiters ($...$) AND Bold delimiters (**...**)
      // Capturing groups are included in the result array
      const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

      return parts.filter(part => part !== '').map((part) => {
          if (part.startsWith('$') && part.endsWith('$')) {
              // It's a math equation
              // Use the new enhanced parser V2
              const cleanMath = part.slice(1, -1).trim();
              const parser = new LatexParser(cleanMath);
              const mathNodes = parser.parse();
              return new DocxMath({
                  children: mathNodes
              });
          } else if (part.startsWith('**') && part.endsWith('**')) {
              // It's bold text
              return new TextRun({
                  text: part.slice(2, -2),
                  bold: true,
                  size: 24 // 12pt
              });
          } else {
              // Regular text
              return new TextRun({
                  text: part,
                  size: 24 // 12pt
              });
          }
      });
  };

