// --- ADVANCED LATEX TO DOCX PARSER V2.0 ---

const SYMBOL_MAP: Record<string, string> = {
    // Greek
    '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ', '\\epsilon': 'ε', '\\varepsilon': 'ε',
    '\\zeta': 'ζ', '\\eta': 'η', '\\theta': 'θ', '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ',
    '\\mu': 'μ', '\\nu': 'ν', '\\xi': 'ξ', '\\pi': 'π', '\\rho': 'ρ', '\\sigma': 'σ',
    '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ', '\\varphi': 'φ', '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
    '\\Delta': 'Δ', '\\Gamma': 'Γ', '\\Lambda': 'Λ', '\\Omega': 'Ω', '\\Phi': 'Φ', '\\Pi': 'Π',
    '\\Sigma': 'Σ', '\\Theta': 'Θ',

    // Operators & Relations
    '\\times': '×', '\\cdot': '·', '\\div': '÷', '\\pm': '±', '\\mp': '∓',
    '\\leq': '≤', '\\geq': '≥', '\\neq': '≠', '\\approx': '≈', '\\equiv': '≡', '\\sim': '∼',
    '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃', '\\subseteq': '⊆', '\\supseteq': '⊇',
    '\\cup': '∪', '\\cap': '∩', '\\setminus': '\\',
    '\\infty': '∞', '\\forall': '∀', '\\exists': '∃', '\\emptyset': '∅', '\\nabla': '∇',
    '\\partial': '∂', '\\angle': '∠', '\\perp': '⊥', '\\parallel': '∥',
    '\\rightarrow': '→', '\\leftarrow': '←', '\\leftrightarrow': '↔', 
    '\\Rightarrow': '⇒', '\\Leftarrow': '⇐', '\\Leftrightarrow': '⇔',
    '\\longmapsto': '↦', '\\to': '→',
    '\\circ': '∘', '\\bullet': '•', '^{\\circ}': '°', '\\deg': '°',

    // Sets
    '\\mathbb{R}': 'ℝ', '\\mathbb{N}': 'ℕ', '\\mathbb{Z}': 'ℤ', '\\mathbb{Q}': 'ℚ', '\\mathbb{C}': 'ℂ',
};

// Helper to find the end index of a balanced brace group starting at `start`
const findBalancedBrace = (str: string, start: number): number => {
    let depth = 0;
    for (let i = start; i < str.length; i++) {
        if (str[i] === '{') depth++;
        else if (str[i] === '}') {
            depth--;
            if (depth === 0) return i;
        }
    }
    return -1;
};

// Main Parser Class-like structure for state management
class LatexParser {
    latex: string;
    index: number;

    constructor(latex: string) {
        this.latex = latex;
        this.index = 0;
    }

    parse(): any[] {
        const nodes: any[] = [];

        while (this.index < this.latex.length) {
            const char = this.latex[this.index];

            if (char === '\\') {
                const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);

                if (match) {
                    const cmd = match[1];
                    this.index += match[0].length;

                    // --- COMMAND HANDLERS ---

                    // 1. Fractions
                    if (cmd === 'frac' || cmd === 'dfrac') {
                        const num = this.parseGroup();
                        const den = this.parseGroup();
                        nodes.push(new MathFraction({ numerator: num, denominator: den }));
                    }

                    // 2. Roots
                    else if (cmd === 'sqrt') {
                        let degree = [];
                        if (this.peek() === '[') {
                            degree = this.parseOptionalGroup();
                        }
                        const content = this.parseGroup();
                        nodes.push(new MathRadical({ degree, children: content }));
                    }

                    // 3. Integrals, Sums (Only Sum and Integral supported nicely in simplified docx export)
                    else if (cmd === 'int') {
                        this.handleIntegral(nodes);
                    }
                    else if (cmd === 'sum') {
                        this.handleSum(nodes);
                    }

                    // 4. Limits
                    else if (cmd === 'lim') {
                        this.handleLimit(nodes);
                    }

                    // 5. Functions (sin, cos, log, etc.)
                    else if (['sin', 'cos', 'tan', 'cot', 'log', 'ln', 'exp', 'min', 'max'].includes(cmd)) {
                         nodes.push(new MathRun(cmd + " ")); 
                    }

                    // 6. Accents - Fallback to simple content rendering
                    else if (['vec', 'hat', 'overline', 'bar', 'tilde'].includes(cmd)) {
                        const content = this.parseGroup();
                        nodes.push(...content);
                        // Optional: Append accent char as run if critical, but complex to align.
                    }

                    // 7. Text
                    else if (cmd === 'text' || cmd === 'mbox') {
                        const textContent = this.extractGroupContent();
                        nodes.push(new MathRun(textContent));
                    }

                    // 8. Environments (Cases) - Fallback to simple list with semicolons
                    else if (cmd === 'begin') {
                        const envName = this.extractGroupContent();
                        if (envName === 'cases') {
                            const endTag = '\\end{cases}';
                            const endIndex = this.latex.indexOf(endTag, this.index);

                            if (endIndex !== -1) {
                                const content = this.latex.slice(this.index, endIndex);
                                this.index = endIndex + endTag.length;

                                // Open brace to indicate system
                                nodes.push(new MathRun("{ "));

                                // Split by \\ for rows
                                const rows = content.split(/\\\\/);
                                rows.forEach((row, i) => {
                                    // Replace alignment & with space
                                    const cleanRow = row.replace(/&/g, ' ').trim();
                                    if(cleanRow) {
                                        const rowNodes = new LatexParser(cleanRow).parse();
                                        nodes.push(...rowNodes);
                                        // Add semicolon separator between equations, except last one
                                        if (i < rows.length - 1) {
                                            nodes.push(new MathRun("; "));
                                        }
                                    }
                                });
                            }
                        } else {
                            // unknown env, skip start tag
                        }
                    }
                    else if (cmd === 'end') {
                        // Skip \end{...}
                         this.extractGroupContent(); 
                    }

                    // 9. Formatting
                    else if (['left', 'right'].includes(cmd)) {
                        // Ignore delimiters
                        // Just consume next char if it's a delimiter char
                         const nextChar = this.latex[this.index];
                         if (nextChar && ['(', ')', '[', ']', '|', '{', '}', '.'].includes(nextChar)) {
                             if (nextChar !== '.') { // dot is null delimiter in latex
                                nodes.push(new MathRun(nextChar));
                             }
                             this.index++;
                         } else if (nextChar === '\\') {
                             // maybe \{ or \}
                             // let next iteration handle it
                         }
                    }

                    // 10. Symbols
                    else if (SYMBOL_MAP[`\\${cmd}`]) {
                        nodes.push(new MathRun(SYMBOL_MAP[`\\${cmd}`]));
                    }

                    // Fallback
                    else {
                        // Unknown command
                    }

                    // Consume \limits if present (formatting hint)
                    if (this.latex.startsWith('\\limits', this.index)) {
                        this.index += 7;
                    }
                } 
                else {
                    // Escaped char like \{ or \%
                    const nextChar = this.latex[this.index];
                    if (['{', '}', '%', '$', '&', '#', '_'].includes(nextChar)) {
                         nodes.push(new MathRun(nextChar));
                         this.index++;
                    } else {
                         // space or other
                         this.index++;
                    }
                }
            }

            // Superscript / Subscript
            else if (char === '^' || char === '_') {
                this.handleScript(char, nodes);
            }

            // Grouping
            else if (char === '{') {
                const group = this.parseGroup();
                nodes.push(...group);
            }
            else if (char === '}') {
                this.index++;
            }

            else {
                // Regular Text
                // Consume until next special char
                let text = char;
                this.index++;
                while(this.index < this.latex.length) {
                    const c = this.latex[this.index];
                    if (['\\', '^', '_', '{', '}'].includes(c)) break;
                    text += c;
                    this.index++;
                }
                nodes.push(new MathRun(text));
            }
        }
        return nodes;
    }

    // --- HELPER METHODS ---

    peek(): string {
        return this.latex[this.index];
    }

    // Parse { ... } and return nodes
    parseGroup(): any[] {
        if (this.latex[this.index] !== '{') {
             const char = this.latex[this.index];
             this.index++;
             return [new MathRun(char)];
        }

        const start = this.index;
        const end = findBalancedBrace(this.latex, start);
        if (end === -1) {
            this.index = this.latex.length; // error
            return [];
        }

        const content = this.latex.slice(start + 1, end);
        this.index = end + 1;

        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    parseOptionalGroup(): any[] {
        if (this.latex[this.index] !== '[') return [];
        const end = this.latex.indexOf(']', this.index);
        if (end === -1) return [];

        const content = this.latex.slice(this.index + 1, end);
        this.index = end + 1;
        const subParser = new LatexParser(content);
        return subParser.parse();
    }

    extractGroupContent(): string {
         if (this.latex[this.index] !== '{') return '';
         const start = this.index;
         const end = findBalancedBrace(this.latex, start);
         if (end === -1) return '';
         this.index = end + 1;
         return this.latex.slice(start + 1, end);
    }

    handleScript(type: string, nodes: any[]) {
        this.index++; // consume ^ or _
        const lastNode = nodes.pop();

        // Parse the script content
        let scriptNodes: any[] = [];
        if (this.latex[this.index] === '{') {
            scriptNodes = this.parseGroup();
        } else {
            const char = this.latex[this.index];
             if (char === '\\') {
                 // read command
                 const match = this.latex.slice(this.index).match(/^\\([a-zA-Z]+)/);
                 if (match) {
                     const sub = new LatexParser(match[0]);
                     scriptNodes = sub.parse();
                     this.index += match[0].length;
                 } else {
                     this.index++;
                 }
             } else {
                scriptNodes = [new MathRun(char)];
                this.index++;
             }
        }

        if (!lastNode) {
            nodes.push(new MathRun(type)); // fallback
            nodes.push(...scriptNodes);
            return;
        }

        if (type === '^') {
            nodes.push(new MathSuperScript({ children: [lastNode], superScript: scriptNodes }));
        } else {
            nodes.push(new MathSubScript({ children: [lastNode], subScript: scriptNodes }));
        }
    }

    handleSum(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathSum({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    handleIntegral(nodes: any[]) {
        const { subScript, superScript } = this.parseLimits();
        nodes.push(new MathIntegral({
            subScript,
            superScript,
            children: [], // Ensure children is present to avoid errors
        }));
    }

    parseLimits() {
        let subScript: any[] | undefined;
        let superScript: any[] | undefined;

        // Check for \limits which is optional
        if (this.latex.startsWith('\\limits', this.index)) {
             this.index += 7;
        }

        // Look ahead for _ and ^ (order doesn't matter)
        for (let k = 0; k < 2; k++) {
            this.skipSpaces();
            if (this.latex[this.index] === '_') {
                this.index++;
                subScript = this.parseArg();
            } else if (this.latex[this.index] === '^') {
                this.index++;
                superScript = this.parseArg();
            } else {
                break;
            }
        }
        return { subScript, superScript };
    }

    handleLimit(nodes: any[]) {
        // \lim_{x \to 0}
        this.skipSpaces();
        let limit: any[] = [];
        if (this.latex[this.index] === '_') {
             this.index++;
             limit = this.parseArg();
        }

        nodes.push(new MathLimitLower({
            children: [new MathRun("lim")],
            limit: limit
        }));
    }

    skipSpaces() {
        while(this.latex[this.index] === ' ') this.index++;
    }

    parseArg(): any[] {
        if (this.latex[this.index] === '{') return this.parseGroup();
        const char = this.latex[this.index];
        this.index++;
        return [new MathRun(char)];
    }
}


export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // Local state for questions to allow deletion/modification
  const [questions, setQuestions] = useState<Question[]>(data.questions);

  const [showAnswers, setShowAnswers] = useState(false);
  const [activeHints, setActiveHints] = useState<Record<number, boolean>>({});
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [isExporting, setIsExporting] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);

  // TTS State
  const [speakingId, setSpeakingId] = useState<number | null>(null);

  // Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Presentation Mode State
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideDirection, setSlideDirection] = useState<'next' | 'prev'>('next'); // State for animation direction
  const [zoomLevel, setZoomLevel] = useState(1); // 1 = 100%
  const [isLaserPointer, setIsLaserPointer] = useState(false);

  // Student Practice State
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, number | string>>({}); // Supports both index (MC) and string (Essay)
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Sync state with props when data changes
  useEffect(() => {
    setQuestions(data.questions);
    setUserAnswers({});
    setIsSubmitted(false);
    setShowScoreModal(false);
    setShowAnswers(false);
    setStudentName('');
    setCurrentSlide(0);
    setViewMode('list');
    setIsEditMode(false);
    setSpeakingId(null);
    window.speechSynthesis.cancel();
  }, [data]);

  // Clean up speech on unmount
  useEffect(() => {
    return () => {
      window.speechSynthesis.cancel();
    };
  }, []);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Avoid stealing focus from input fields
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight' || e.key === ' ') {
          nextSlide();
        } else if (e.key === 'ArrowLeft') {
          prevSlide();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentSlide, questions.length]);

  // Close nav when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showNav]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        containerRef.current.requestFullscreen().catch((err) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const nextSlide = () => {
    // Stop speaking when changing slides
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (currentSlide < questions.length - 1) {
      setSlideDirection('next');
      setCurrentSlide(prev => prev + 1);
      // Auto close solution when switching slides for clean look
      if (!showAnswers) setActiveSolutions({});
    }
  };

  const prevSlide = () => {
    // Stop speaking when changing slides
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (currentSlide > 0) {
      setSlideDirection('prev');
      setCurrentSlide(prev => prev - 1);
    }
  };

  const jumpToQuestion = (idx: number) => {
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (viewMode === 'slide') {
      // Determine direction for smooth jump
      setSlideDirection(idx > currentSlide ? 'next' : 'prev');
      setCurrentSlide(idx);
    } else {
      const element = document.getElementById(`question-${idx}`);
      if (element) {
        // If in side mode, we scroll the window or the inner container depending on implementation.
        // For simplicity, we use scrollIntoView which works in both cases
        element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    setShowNav(false);
  };

  const toggleHint = (id: number) => {
    setActiveHints(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleSolution = (id: number) => {
    setActiveSolutions(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return; 

    // Only set if not already set (toggle behavior could be implemented if needed)
    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: optionIdx
    }));
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode) return;

    // Limit to 4 characters
    if (value.length > 4) return;

    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: value.toUpperCase() // Auto uppercase
    }));
  };

  const handleDeleteQuestion = (idxToDelete: number) => {
    if (!window.confirm(`Bạn có chắc chắn muốn xóa Câu ${idxToDelete + 1} không?`)) {
        return;
    }

    // 1. Calculate new questions
    const newQuestions = questions.filter((_, idx) => idx !== idxToDelete);
    setQuestions(newQuestions);

    // 2. Adjust slide index if necessary
    if (viewMode === 'slide') {
        if (currentSlide === idxToDelete) {
            // If deleting current slide, move to the last available or 0
            if (currentSlide >= newQuestions.length) {
                setCurrentSlide(Math.max(0, newQuestions.length - 1));
            }
        } else if (currentSlide > idxToDelete) {
            // If deleting a preceding slide, shift current index down
            setCurrentSlide(c => Math.max(0, c - 1));
        }
    } else {
         // In list mode, ensure we don't have out of bounds if switching views later
         if (currentSlide >= newQuestions.length) {
            setCurrentSlide(Math.max(0, newQuestions.length - 1));
         }
    }

    // 3. Shift User Answers (keys are indices)
    setUserAnswers(prevAnswers => {
        const newAnswers: Record<number, number | string> = {};
        Object.keys(prevAnswers).forEach(keyStr => {
            const key = parseInt(keyStr);
            if (key < idxToDelete) {
                newAnswers[key] = prevAnswers[key];
            } else if (key > idxToDelete) {
                newAnswers[key - 1] = prevAnswers[key];
            }
        });
        return newAnswers;
    });

    // 4. Reset submission state as the test content has changed
    setIsSubmitted(false);
  };

  const handleSpeak = (text: string, id: number) => {
    window.speechSynthesis.cancel();

    if (speakingId === id) {
        setSpeakingId(null);
        return;
    }

    // Clean text: remove markdown bold (**), LaTeX delimiters ($)
    const cleanText = text.replace(/\*\*/g, '').replace(/\$/g, '');

    const utterance = new SpeechSynthesisUtterance(cleanText);
    utterance.lang = 'vi-VN'; // Vietnamese as requested
    utterance.rate = 0.9; // Adjusted rate for Vietnamese
    utterance.pitch = 1;

    utterance.onend = () => setSpeakingId(null);
    utterance.onerror = () => setSpeakingId(null);

    setSpeakingId(id);
    window.speechSynthesis.speak(utterance);
  };

  const handleSubmitExam = () => {
    const answeredCount = Object.keys(userAnswers).length;

    if (answeredCount < questions.length) {
      if (!confirm(`Bạn mới làm ${answeredCount}/${questions.length} câu. Bạn có chắc chắn muốn nộp bài để xem tổng kết không?`)) {
        return;
      }
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    setShowAnswers(true);
  };

  const calculateScore = () => {
    let correctCount = 0;
    const totalQuestions = questions.length;
    const answeredCount = Object.keys(userAnswers).length;

    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];

      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
             const selectedLabel = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.trim().toUpperCase().startsWith(selectedLabel)) {
                correctCount++;
             }
          } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
             // Compare strings for Essay (normalize removing LaTeX $ and spaces)
             const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
             const cleanUser = userAns.trim().toUpperCase();
             if (cleanUser && cleanCorrect === cleanUser) {
                 correctCount++;
             }
          }
      }
    });

    return {
        correct: correctCount,
        answered: answeredCount,
        total: totalQuestions,
        score: totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 10 * 100) / 100 : 0
    };
  };

  const getFeedback = (score: number) => {
    if (score === 10) return { text: "Tuyệt đối! Em là thiên tài!", color: "text-purple-600 dark:text-purple-400", emoji: <PartyPopper className="w-12 h-12 text-purple-500 animate-bounce" /> };
    if (score >= 9) return { text: "Xuất sắc! Em là niềm tự hào của lớp!", color: "text-emerald-600 dark:text-emerald-400", emoji: <Trophy className="w-12 h-12 text-yellow-400" /> };
    if (score >= 8) return { text: "Rất tốt! Giữ vững phong độ nhé!", color: "text-blue-600 dark:text-blue-400", emoji: <Star className="w-12 h-12 text-blue-400 fill-current" /> };
    if (score >= 6.5) return { text: "Khá tốt! Cần cẩn thận hơn một chút.", color: "text-indigo-600 dark:text-indigo-400", emoji: <Smile className="w-12 h-12 text-indigo-400" /> };
    if (score >= 5) return { text: "Đạt yêu cầu. Cần ôn tập kỹ hơn các câu sai.", color: "text-amber-600 dark:text-amber-400", emoji: <Award className="w-12 h-12 text-amber-400" /> };
    return { text: "Cần cố gắng nhiều hơn. Đừng nản chí!", color: "text-red-600 dark:text-red-400", emoji: <Frown className="w-12 h-12 text-red-400" /> };
  };

  // ... (Print and Export functions remain the same) ...
  const handlePrintStudent = () => {
    document.body.classList.add('printing-student');
    window.print();
    setTimeout(() => { document.body.classList.remove('printing-student'); }, 500);
  };
  const handlePrintTeacher = () => {
    if (!showAnswers) {
      if(confirm('Bạn có muốn bật hiện đáp án trước khi in lời giải không?')) {
        setShowAnswers(true);
        setTimeout(() => window.print(), 100);
        return;
      }
    }
    window.print();
  };

  const handleExportJSON = () => {
    const exportData = { type: 'exam', timestamp: Date.now(), config, data: { ...data, questions } };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const saveFunc = (FileSaver as any).saveAs || FileSaver;
    saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.json`);
  };

  // Helper to parse content mixed with LaTeX ($...$) and Bold (**...**) into Docx Paragraph Children
  const parseContentToDocx = (content: string) => {
      // Split by LaTeX delimiters ($...$) AND Bold delimiters (**...**)
      // Capturing groups are included in the result array
      const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

      return parts.filter(part => part !== '').map((part) => {
          if (part.startsWith('$') && part.endsWith('$')) {
              // It's a math equation
              // Use the new enhanced parser V2
              const cleanMath = part.slice(1, -1).trim();
              const parser = new LatexParser(cleanMath);
              const mathNodes = parser.parse();
              return new DocxMath({
                  children: mathNodes
              });
          } else if (part.startsWith('**') && part.endsWith('**')) {
              // It's bold text
              return new TextRun({
                  text: part.slice(2, -2),
                  bold: true,
                  size: 24 // 12pt
              });
          } else {
              // Regular text
              return new TextRun({
                  text: part,
                  size: 24 // 12pt
              });
          }
      });
  };

  const handleDownloadWord = async () => {
      setIsExporting(true);
      try {
        const docQuestions = questions.flatMap((q, index) => {

          // Gộp "Câu X." và nội dung vào cùng một paragraph
          const questionParagraph = new Paragraph({ 
              children: [
                  new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 24 }),
                  ...parseContentToDocx(q.content)
              ],
              spacing: { after: 150 } 
          });

          const parts = [
            questionParagraph,
          ];

          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options) {
            q.options.forEach((opt, idx) => {
              const label = ['A', 'B', 'C', 'D'][idx];
              let cleanOpt = opt.replace(/^[A-D][\.\)\s]+/, '').trim();

              parts.push(new Paragraph({ 
                  children: [
                      new TextRun({ text: `${label}. `, bold: true, size: 24 }),
                      ...parseContentToDocx(cleanOpt)
                  ], 
                  indent: { left: 720 }, 
                  spacing: { after: 50 } 
              }));
            });
          }
          if (q.type === QuestionType.ESSAY) {
              // Word export for Essay: Add 4 boxes placeholder
              parts.push(new Paragraph({ 
                children: [new TextRun({ text: "Trả lời: [  ] [  ] [  ] [  ]", font: "Courier New", size: 28 })], 
                spacing: { before: 200, after: 200 } 
              }));
          }

          parts.push(
              new Paragraph({ 
                  children: [
                      new TextRun({ text: "Lời giải", bold: true, size: 22, underline: { type: UnderlineType.SINGLE, color: "000000" } })
                  ], 
                  spacing: { before: 200 } 
              }),
              new Paragraph({ 
                  children: [
                      new TextRun({ text: "Đáp án đúng: ", bold: true, color: "008000", size: 24 }),
                      ...parseContentToDocx(q.correctAnswer)
                  ] 
              }),
              new Paragraph({ 
                  children: parseContentToDocx(q.solution), 
                  spacing: { after: 400 } 
              })
          );
          return parts;
        });

        const doc = new Document({
          creator: "Trợ Lý Luyện Thi Thông Minh", title: `${config.subject} - ${config.grade}`,
          sections: [{ 
            headers: {
                default: new Header({
                    children: [
                        new Paragraph({
                            children: [
                                new TextRun({ text: "Thầy Vũ Tiến Lực - Trường THPT Nguyễn Hữu Cảnh", bold: true, size: 20 }),
                                new TextRun({ text: "\t" }),
                                new TextRun({ children: ["Trang ", PageNumber.CURRENT], size: 20 })
                            ],
                            tabStops: [
                                { type: TabStopType.RIGHT, position: TabStopPosition.MAX }
                            ],
                        })
                    ]
                })
            },
            properties: {}, 
            children: [
              new Paragraph({ text: "PHIẾU LUYỆN TẬP", heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }),
              new Paragraph({ text: `Môn: ${config.subject} | ${config.grade}`, heading: HeadingLevel.HEADING_2, alignment: AlignmentType.CENTER }),
              new Paragraph({ text: `Chủ đề: ${config.topic}`, alignment: AlignmentType.CENTER, spacing: { after: 400 } }),
              ...docQuestions
            ] 
          }],
        });
        const blob = await Packer.toBlob(doc);
        const saveFunc = (FileSaver as any).saveAs || FileSaver;
        saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.docx`);
      } catch (e) { console.error(e); alert("Có lỗi khi tạo file Word."); } finally { setIsExporting(false); }
  };

  const results = calculateScore();
  const feedback = getFeedback(results.score);

  // Helper to render a single question card
  const renderQuestionCard = (q: Question, idx: number, isSlideMode: boolean) => {
    const isAnswered = userAnswers[idx] !== undefined;
    const userAns = userAnswers[idx];
    let isCorrect = false;

    if (isAnswered) {
        if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
            const label = ['A', 'B', 'C', 'D'][userAns];
            isCorrect = q.correctAnswer.trim().toUpperCase().startsWith(label);
        } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
            const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
            const cleanUser = userAns.trim().toUpperCase();
            isCorrect = (cleanUser !== '' && cleanCorrect === cleanUser);
        }
    }

    const canViewSolution = showAnswers || isAnswered || isSubmitted;

    // Apply scaling
    const scaleStyle = { fontSize: `${zoomLevel * 100}%` };

    // Zoom effect class for fullscreen
    const zoomEffectClass = (isSlideMode && isFullscreen) ? 'scale-105 origin-top' : 'scale-100 origin-top';

    return (
        <div 
          id={`question-${idx}`}
          key={`${q.id}-${idx}`} 
          className={`print-break-inside-avoid bg-white dark:bg-slate-800 shadow-xl border relative overflow-hidden transition-all duration-300
             ${isSlideMode ? 'h-full flex flex-col p-4 md:px-8 pt-4 rounded-3xl animate-fade-in' : 'p-8 md:p-10 rounded-3xl mb-12'}
             ${isAnswered || isSubmitted
                ? (isCorrect ? 'border-emerald-200 dark:border-emerald-700 ring-2 ring-emerald-100 dark:ring-emerald-900/30' : 'border-red-200 dark:border-red-700 ring-2 ring-red-100 dark:ring-red-900/30')
                : 'border-slate-100 dark:border-slate-700'
             }
             ${isEditMode ? 'ring-2 ring-dashed ring-slate-300 dark:ring-slate-600' : ''}
          `}
          style={scaleStyle}
        >
          {/* Watermark Number */}
          <div className="absolute top-0 right-0 p-4 opacity-10 font-black text-9xl text-slate-300 dark:text-slate-600 select-none pointer-events-none">
            {idx + 1}
          </div>

          {/* Delete Button (Edit Mode) */}
          {isEditMode && (
             <div className="absolute top-4 right-4 z-20 animate-fade-in">
                <button 
                  onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleDeleteQuestion(idx); }}
                  className="flex items-center gap-1 bg-red-100 dark:bg-red-900/50 hover:bg-red-200 dark:hover:bg-red-900/80 text-red-600 dark:text-red-300 px-3 py-1.5 rounded-full font-bold shadow-sm transition-colors border border-red-200 dark:border-red-800"
                  title="Xóa câu hỏi này"
                >
                    <Trash2 className="w-4 h-4" /> Xóa
                </button>
             </div>
          )}

          {/* Badge for Correct/Incorrect - Absolute pos */}
          {isAnswered && !isEditMode && (
             <div className="absolute top-0 right-0 p-4 no-print animate-fade-in-up z-10">
                <div className={`flex items-center gap-1 font-bold px-3 py-1 rounded-full shadow-sm text-base ${isCorrect ? 'bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300' : 'bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300'}`}>
                    {isCorrect ? <Star className="w-4 h-4 fill-emerald-700 dark:fill-emerald-300" /> : <XCircle className="w-4 h-4" />}
                    {isCorrect ? "+1 Điểm" : "0 Điểm"}
                </div>
             </div>
          )}

          <div className={`flex flex-col h-full ${isSlideMode ? '' : 'gap-6'}`}>

              {/* --- QUESTION CONTENT AREA --- */}
              <div className={`relative z-10 ${isSlideMode ? 'mb-4 flex-shrink-0' : 'mb-2'} transition-transform duration-700 ease-out ${zoomEffectClass}`}>
                {!isSlideMode && (
                    <div className="flex items-center gap-3 mb-4">
                        <span className="flex items-center justify-center w-10 h-10 rounded-full bg-indigo-600 dark:bg-indigo-500 text-white font-bold text-lg shadow-md">
                            {idx + 1}
                        </span>
                        <span className="text-sm font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                            {q.difficulty}
                        </span>

                        {/* Audio Button - List Mode */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); handleSpeak(q.content, q.id); }}
                            className={`p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors ${speakingId === q.id ? 'text-red-500 animate-pulse bg-red-50 dark:bg-red-900/30' : 'text-slate-400 hover:text-indigo-600'}`}
                            title="Đọc câu hỏi (Tiếng Việt - Giọng chậm)"
                        >
                            {speakingId === q.id ? <StopCircle className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                        </button>
                    </div>
                )}

                <div className={`text-[1.5em] leading-tight text-slate-800 dark:text-slate-100 font-medium ${isSlideMode ? 'text-[1.8em]' : ''}`}>
                  {isSlideMode && (
                     <div className="flex items-center gap-3 mb-2">
                        <span className="text-indigo-600 dark:text-indigo-400 font-bold">Câu {idx + 1}:</span>
                        <span className="text-base font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 align-middle">
                            {q.difficulty}
                        </span>

                        {/* Audio Button - Slide Mode */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); handleSpeak(q.content, q.id); }}
                            className={`p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors ml-2 ${speakingId === q.id ? 'text-red-500 animate-pulse bg-red-50 dark:bg-red-900/30' : 'text-slate-400 hover:text-indigo-600'}`}
                            title="Đọc câu hỏi (Tiếng Việt - Giọng chậm)"
                        >
                            {speakingId === q.id ? <StopCircle className="w-6 h-6" /> : <Volume2 className="w-6 h-6" />}
                        </button>
                     </div>
                  )}
                  <MathRenderer content={q.content} />
                </div>
              </div>

              {/* --- OPTIONS / ANSWER AREA --- */}
              <div className={isSlideMode ? 'flex-grow overflow-y-auto pr-2 pb-40 px-4 md:px-12' : ''}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                    <div className={`grid grid-cols-1 md:grid-cols-2 gap-5 mt-2`}>
                    {q.options.map((opt, optIdx) => {
                        const label = ['A', 'B', 'C', 'D'][optIdx];
                        const cleanContent = opt.replace(/^[A-D][\.\)\s]+/, '').trim().replace(/\*\*/g, '');
                        const theme = OPTION_THEMES[optIdx % 4];

                        const isSelected = userAns === optIdx;
                        const isCorrectAnswer = q.correctAnswer.trim().toUpperCase().startsWith(label);

                        let stateStyles = `border-2 ${theme.bg} ${theme.border} ${theme.text}`;

                        if (!isAnswered && !isSubmitted) {
                            stateStyles = `${theme.bg} ${theme.border} ${theme.text} ${theme.hover} hover:scale-[1.01] cursor-pointer`;
                        } else {
                            if (isCorrectAnswer) stateStyles = `bg-emerald-100 dark:bg-emerald-900/30 border-emerald-500 dark:border-emerald-500 text-emerald-900 dark:text-emerald-200 ring-2 ring-emerald-200 dark:ring-emerald-800`;
                            else if (isSelected && !isCorrectAnswer) stateStyles = `bg-red-100 dark:bg-red-900/30 border-red-500 dark:border-red-500 text-red-900 dark:text-red-200 opacity-80`;
                            else stateStyles = `${theme.bg} border-transparent opacity-50 grayscale`;
                        }

                        if (isEditMode) {
                            stateStyles = `${theme.bg} ${theme.border} ${theme.text} opacity-80 cursor-not-allowed`;
                        }

                        return (
                        <div 
                            key={optIdx}
                            onClick={() => handleOptionSelect(idx, optIdx)}
                            className={`relative group flex items-start gap-4 p-5 rounded-2xl transition-all duration-200 text-[1.2em] leading-snug ${stateStyles}`}
                        >
                            <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-lg font-bold text-xl transition-colors
                            ${(isAnswered || isSubmitted) && isCorrectAnswer ? 'bg-emerald-500 text-white' : ''}
                            ${(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer ? 'bg-red-500 text-white' : ''}
                            ${(!isAnswered && !isSubmitted) ? (theme.labelBg + ' ' + theme.text) : (!isCorrectAnswer && !isSelected ? 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400' : '')}
                            `}>
                            {label}.
                            </div>
                            <div className="flex-grow pt-1"><MathRenderer content={cleanContent} /></div>
                            {(isAnswered || isSubmitted) && isCorrectAnswer && <CheckCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-emerald-600 dark:text-emerald-400" />}
                            {(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer && <XCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-red-500 dark:text-red-400" />}
                        </div>
                        );
                    })}
                    </div>
                )}

                {/* ESSAY / SHORT ANSWER INPUT - 4 Chars Box */}
                {q.type === QuestionType.ESSAY && (
                    <div className="my-6">
                        <label className="block text-slate-500 dark:text-slate-400 font-bold text-sm mb-3 uppercase tracking-wider">
                            Điền kết quả (Tối đa 4 ký tự):
                        </label>
                        <div className="relative w-fit">
                            <input
                                type="text"
                                maxLength={4}
                                value={typeof userAns === 'string' ? userAns : ''}
                                onChange={(e) => handleEssayChange(idx, e.target.value)}
                                disabled={isSubmitted || isEditMode}
                                placeholder="____"
                                className={`w-48 h-16 text-center text-4xl font-mono tracking-[0.3em] font-bold uppercase border-2 rounded-xl outline-none transition-all shadow-inner
                                    ${(isAnswered || isSubmitted)
                                        ? (isCorrect
                                            ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300'
                                            : 'border-red-500 bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300')
                                        : 'border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 dark:focus:ring-indigo-900/30'}
                                `}
                            />
                            {/* Validation Icon inside/near input */}
                            {(isAnswered || isSubmitted) && (
                                <div className="absolute top-1/2 -right-10 -translate-y-1/2">
                                    {isCorrect 
                                        ? <CheckCircle className="w-8 h-8 text-emerald-500 dark:text-emerald-400 animate-bounce" /> 
                                        : <XCircle className="w-8 h-8 text-red-500 dark:text-red-400" />
                                    }
                                </div>
                            )}
                        </div>
                        <p className="mt-2 text-xs text-slate-400 dark:text-slate-500 italic">
                            * Nhập chính xác kết quả số hoặc chữ cái. Ví dụ: 10, -5, A, 3.14
                        </p>
                    </div>
                )}

                {/* --- SLIDE MODE: SOLUTION TOGGLE & CONTENT (ALWAYS VISIBLE) --- */}
                {isSlideMode && !showAnswers && (
                    <div className="mt-8 mb-8 flex flex-wrap gap-3 justify-center">
                        <button 
                            onClick={() => toggleHint(q.id)}
                            className="px-6 py-3 rounded-full bg-indigo-100 hover:bg-indigo-200 dark:bg-indigo-900/50 dark:hover:bg-indigo-900 text-indigo-700 dark:text-indigo-300 font-bold text-lg flex items-center justify-center gap-2 transition-all shadow-sm border border-indigo-200 dark:border-indigo-800"
                        >
                            <Lightbulb className="w-5 h-5" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Gợi ý'}
                        </button>
                        <button 
                            onClick={() => { if(canViewSolution) toggleSolution(q.id); }}
                            disabled={!canViewSolution}
                            className={`px-6 py-3 rounded-full font-bold text-lg flex items-center justify-center gap-2 transition-all shadow-sm border
                                ${canViewSolution 
                                    ? 'bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-600 cursor-pointer' 
                                    : 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 opacity-70 cursor-not-allowed'
                                }
                            `}
                        >
                            {canViewSolution ? (activeSolutions[q.id] ? <EyeOff className="w-5 h-5"/> : <Key className="w-5 h-5"/>) : <Lock className="w-5 h-5"/>}
                            {canViewSolution ? (activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải') : 'Chọn đáp án để xem'}
                        </button>
                    </div>
                )}

                {/* --- SLIDE MODE: HINTS DISPLAY --- */}
                {isSlideMode && activeHints[q.id] && q.hints && (
                    <div className="mt-6 mb-4 animate-fade-in-up">
                        <div className="bg-indigo-50 dark:bg-indigo-900/10 border-2 border-indigo-100 dark:border-indigo-900/50 rounded-3xl p-6 shadow-sm">
                             <div className="flex items-center gap-2 mb-4">
                                <span className="text-indigo-600 dark:text-indigo-400 font-bold flex items-center gap-2 text-xl"><Lightbulb className="w-6 h-6"/> Gợi ý</span>
                             </div>
                             <ul className="list-disc list-inside space-y-3 pl-2 text-slate-700 dark:text-slate-200 text-xl leading-relaxed">
                                {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                             </ul>
                        </div>
                    </div>
                )}

                {/* --- SLIDE MODE: EXPANDED SOLUTION DISPLAY --- */}
                {isSlideMode && (showAnswers || activeSolutions[q.id]) && (
                    <div className="mt-6 mb-12 animate-fade-in-up">
                        <div className="bg-emerald-50 dark:bg-emerald-900/10 border-2 border-emerald-100 dark:border-emerald-900/50 rounded-3xl p-6 md:p-8 shadow-sm">
                            <h4 className="font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-3 mb-6 pb-4 border-b border-emerald-200 dark:border-emerald-800/50">
                                <CheckCircle className="w-8 h-8 fill-current" /> Lời giải chi tiết
                            </h4>

                            <div className="text-xl md:text-2xl text-slate-800 dark:text-slate-100 space-y-6 leading-relaxed">
                                <p className="font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-3">
                                    Đáp án đúng: <span className="bg-emerald-200 dark:bg-emerald-800 text-emerald-900 dark:text-white px-4 py-1 rounded-xl shadow-sm"><MathRenderer content={q.correctAnswer} /></span>
                                </p>

                                {/* Structured Solution Content */}
                                <div className="space-y-4">
                                    {q.solution.split('\n').filter(line => line.trim() !== '').map((line, i) => (
                                        <div key={i} className="flex items-start gap-4">
                                            <span className="text-emerald-500 mt-1.5 flex-shrink-0 text-xl">✦</span>
                                            <div className="flex-1">
                                                <MathRenderer content={line} />
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Collapse Button inside */}
                            <div className="mt-8 flex justify-center">
                                <button 
                                    onClick={() => toggleSolution(q.id)}
                                    className="text-emerald-600 dark:text-emerald-400 hover:text-emerald-800 dark:hover:text-emerald-200 font-bold flex items-center gap-2 px-4 py-2 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 rounded-full transition-colors"
                                >
                                    <ChevronUp className="w-5 h-5" /> Thu gọn
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                 {/* Hints & Solutions (LIST MODE ONLY) */}
                 {!isSlideMode && (
                     <div className="space-y-2 text-base mt-6">
                        <div className="flex flex-wrap gap-2">
                            <button 
                                onClick={() => toggleHint(q.id)}
                                className="font-medium text-indigo-600 dark:text-indigo-300 hover:text-indigo-800 dark:hover:text-indigo-200 flex items-center gap-2 px-4 py-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors"
                            >
                                <Lightbulb className="w-5 h-5" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Xem gợi ý'}
                            </button>

                            {!showAnswers && (
                                <>
                                {canViewSolution ? (
                                    <button onClick={() => toggleSolution(q.id)} className="text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 flex items-center gap-1 px-4 py-2 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors">
                                        {activeSolutions[q.id] ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}
                                        {activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải chi tiết'}
                                    </button>
                                ) : (
                                    <div className="text-sm text-slate-400 italic px-4 py-2 flex items-center gap-2">
                                        <EyeOff className="w-4 h-4" /> Trả lời để xem giải
                                    </div>
                                )}
                                </>
                            )}
                        </div>

                         {activeHints[q.id] && q.hints && (
                             <div className="bg-indigo-50 dark:bg-indigo-900/20 p-6 rounded-2xl border border-indigo-100 dark:border-indigo-800 text-lg text-indigo-900 dark:text-indigo-200 animate-fade-in shadow-inner mt-2">
                                 <ul className="list-disc list-inside space-y-2 pl-2">
                                     {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                                 </ul>
                             </div>
                         )}

                         {(showAnswers || activeSolutions[q.id]) && (
                             <div className="mt-4 p-6 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border-2 border-emerald-100 dark:border-emerald-800 text-emerald-900 dark:text-emerald-100 shadow-sm animate-fade-in">
                                 <h4 className="font-bold text-xl mb-3 flex items-center gap-2 border-b border-emerald-200 dark:border-emerald-700 pb-2">
                                     <CheckCircle className="w-6 h-6" /> Đáp án & Lời giải chi tiết
                                 </h4>
                                 <p className="mb-4 font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                                     Đáp án: <span className="px-3 py-1 bg-emerald-200 dark:bg-emerald-800 rounded-lg"><MathRenderer content={q.correctAnswer} /></span>
                                 </p>
                                 <div className="text-lg whitespace-pre-wrap leading-relaxed">
                                     <MathRenderer content={q.solution} inline={false} />
                                 </div>
                             </div>
                         )}
                     </div>
                 )}
              </div>

              {/* --- FOOTER INFO (SLIDE MODE ONLY) --- */}
              {isSlideMode && (
                  <div className="mt-auto flex flex-col gap-4">
                       {/* Inspirational Quote Footer */}
                        <div className="text-center pointer-events-none z-0 opacity-60 px-4 pb-2">
                            <p className="text-sm md:text-base font-serif italic text-slate-500 dark:text-slate-400">
                                "{STUDY_QUOTES[currentSlide % STUDY_QUOTES.length]}"
                            </p>
                        </div>
                  </div>
              )}
          </div>
        </div>
    );
  };

  if (questions.length === 0) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-8 text-center text-slate-500 dark:text-slate-400">
              <div className="bg-slate-100 dark:bg-slate-800 p-8 rounded-full mb-4">
                 <FileText className="w-12 h-12 text-slate-400 dark:text-slate-500" />
              </div>
              <h2 className="text-xl font-bold text-slate-700 dark:text-slate-200">Chưa có câu hỏi nào</h2>
              <p className="mb-6">Bạn đã xóa hết câu hỏi hoặc dữ liệu trống.</p>
              <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-bold">Tạo đề mới</button>
          </div>
      )
  }

  return (
    <div 
      ref={containerRef}
      className={`min-h-screen flex flex-col relative transition-colors duration-300 bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : ''} ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}`}
    >
      <style>{`
        @keyframes slideInRight {
          from { opacity: 0; transform: translateX(30px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideInLeft {
          from { opacity: 0; transform: translateX(-30px); }
          to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-in-right { animation: slideInRight 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-slide-in-left { animation: slideInLeft 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>

      {/* Side Mode Content Wrapper */}
      <div className={`
         transition-all duration-300 ease-in-out
         ${showBlackboard && blackboardMode === 'side' 
            ? 'w-[50vw] h-[calc(100vh-64px)] fixed left-0 top-[64px] overflow-y-auto z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl px-4 md:px-6 pt-4 pb-24 bg-slate-50 dark:bg-slate-900' 
            : ''}
      `}>

       {/* Top Bar - Auto hide in slide mode if dock is collapsed maybe? Or always visible like StudyGuide? StudyGuide has auto-hide. Let's stick to standard top bar for List mode, and auto-hide for Slide mode */}

       <div className={`
          bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-40 shadow-sm no-print transition-all duration-300
          ${viewMode === 'slide' && !showNav ? '-translate-y-full opacity-0 absolute w-full' : 'translate-y-0 opacity-100'}
       `}>
          {/* Top Bar Content */}
          <div className="flex items-center gap-4 flex-1 overflow-hidden">
             <button onClick={onReset} className="flex-shrink-0 flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                 <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
             </button>
             {/* Title */}
             <div className="h-8 w-px bg-slate-300 dark:bg-slate-600 mx-2"></div>
             <div className="flex items-center gap-2 overflow-hidden text-indigo-700 dark:text-indigo-400">
                <FileSignature className="w-5 h-5 flex-shrink-0" />
                <h1 className="text-lg font-bold truncate text-slate-800 dark:text-white"> {config.topic || 'Bài Luyện Tập'} </h1>
             </div>
          </div>

          <div className="flex items-center gap-2 flex-shrink-0">
             {/* View Switcher */}
             <div className="hidden md:flex gap-2 mr-2">
                 <button onClick={() => setViewMode('list')} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'list' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-1 ring-indigo-200 dark:ring-indigo-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}>
                    <FileText className="w-4 h-4" /> Danh sách
                 </button>
                 <button onClick={() => setViewMode('slide')} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-1 ring-indigo-200 dark:ring-indigo-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}>
                    <PresentationIcon className="w-4 h-4" /> Slide
                 </button>
             </div>
             {/* Export Buttons */}
             <div className="h-8 w-px bg-slate-200 dark:bg-slate-600 mx-1"></div>

             <button onClick={handleExportJSON} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 shadow-sm transition-all" title="Lưu">
                 <Save className="w-4 h-4" /> <span className="hidden sm:inline">Lưu</span>
             </button>
             <button onClick={handleDownloadWord} disabled={isExporting} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 dark:bg-blue-700 text-white hover:bg-blue-700 dark:hover:bg-blue-600 shadow-sm transition-all disabled:opacity-50" title="Word">
                 {isExporting ? <span className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></span> : <Download className="w-4 h-4" />} <span className="hidden sm:inline">Word</span>
             </button>
             <button onClick={handlePrintTeacher} className="flex items-center gap-2 px-3 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg font-bold text-sm shadow-sm transition-colors border border-slate-200 dark:border-slate-600" title="In">
                 <Printer className="w-4 h-4" />
             </button>
             <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                 <Maximize className="w-5 h-5" />
             </button>
          </div>
       </div>

       {/* Main Content */}
       <div className={`flex-grow overflow-hidden relative ${viewMode === 'list' ? 'overflow-y-auto' : ''}`}>

          {viewMode === 'list' ? (
             <div className="max-w-4xl mx-auto p-6 md:p-8 pb-32 print-container">
                 {/* Header Info */}
                 <div className="text-center mb-10 border-b-2 border-indigo-100 dark:border-indigo-900/50 pb-8">
                     <h2 className="text-3xl font-black text-slate-800 dark:text-slate-100 uppercase mb-2">{config.topic}</h2>
                     <p className="text-slate-500 dark:text-slate-400 font-medium">Môn: {config.subject} - {config.grade}</p>

                     {/* Objectives/Summary from Data */}
                     {(data.objectives || data.summary) && (
                        <div className="mt-6 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 text-left">
                            {data.objectives && (
                                <div className="mb-4">
                                    <h4 className="font-bold text-indigo-600 dark:text-indigo-400 flex items-center gap-2 mb-2"><Target className="w-5 h-5"/> Mục tiêu:</h4>
                                    <ul className="list-disc list-inside space-y-1 text-slate-700 dark:text-slate-300">
                                        {data.objectives.map((obj, i) => <li key={i}>{obj}</li>)}
                                    </ul>
                                </div>
                            )}
                            {data.summary && (
                                <div>
                                    <h4 className="font-bold text-indigo-600 dark:text-indigo-400 flex items-center gap-2 mb-2"><LayoutGrid className="w-5 h-5"/> Cấu trúc:</h4>
                                    <p className="text-slate-700 dark:text-slate-300">{data.summary}</p>
                                </div>
                            )}
                        </div>
                     )}
                 </div>

                 {/* Questions List */}
                 <div className="space-y-8">
                    {questions.map((q, idx) => renderQuestionCard(q, idx, false))}
                 </div>

                 {/* Submit Button */}
                 <div className="mt-12 flex flex-col items-center gap-4 no-print">
                    {!isSubmitted ? (
                        <button 
                            onClick={handleSubmitExam}
                            className="px-10 py-4 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-bold text-xl rounded-2xl shadow-xl hover:shadow-2xl transform hover:-translate-y-1 transition-all flex items-center gap-3"
                        >
                            <Send className="w-6 h-6" /> Nộp Bài & Xem Kết Quả
                        </button>
                    ) : (
                        <div className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow-xl border-2 border-indigo-100 dark:border-indigo-900 text-center w-full animate-fade-in-up">
                            <div className="flex justify-center mb-4">{feedback.emoji}</div>
                            <h3 className={`text-3xl font-black mb-2 ${feedback.color}`}>Điểm số: {results.score} / 10</h3>
                            <p className="text-xl text-slate-600 dark:text-slate-300 font-medium mb-6">{feedback.text}</p>
                            <div className="grid grid-cols-3 gap-4 text-center max-w-md mx-auto mb-6">
                                <div className="p-3 bg-emerald-50 dark:bg-emerald-900/30 rounded-xl">
                                    <div className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{results.correct}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Đúng</div>
                                </div>
                                <div className="p-3 bg-red-50 dark:bg-red-900/30 rounded-xl">
                                    <div className="text-2xl font-bold text-red-600 dark:text-red-400">{results.answered - results.correct}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Sai</div>
                                </div>
                                <div className="p-3 bg-slate-100 dark:bg-slate-700 rounded-xl">
                                    <div className="text-2xl font-bold text-slate-600 dark:text-slate-300">{results.total - results.answered}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Bỏ qua</div>
                                </div>
                            </div>
                            <button 
                                onClick={() => { setIsSubmitted(false); setUserAnswers({}); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
                                className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold rounded-lg transition-colors flex items-center gap-2 mx-auto"
                            >
                                <RefreshCw className="w-5 h-5" /> Làm lại
                            </button>
                        </div>
                    )}
                 </div>
             </div>
          ) : (
             // SLIDE MODE
             <div 
                className="w-full h-full flex flex-col items-center justify-center relative bg-slate-100 dark:bg-slate-950 p-4"
                onClick={() => setShowNav(prev => !prev)}
             >
                <div 
                    className="w-full h-full max-w-5xl mx-auto flex flex-col transition-all duration-300"
                    onClick={(e) => e.stopPropagation()}
                >
                    {questions.length > 0 && renderQuestionCard(questions[currentSlide], currentSlide, true)}
                </div>

                {/* Navigation Arrows */}
                <button 
                    onClick={(e) => { e.stopPropagation(); prevSlide(); }} 
                    disabled={currentSlide === 0}
                    className="fixed left-4 top-1/2 -translate-y-1/2 p-4 rounded-full bg-white/20 hover:bg-white/40 dark:bg-black/20 dark:hover:bg-black/40 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 z-30"
                >
                    <ChevronLeft className="w-8 h-8" />
                </button>
                <button 
                    onClick={(e) => { e.stopPropagation(); nextSlide(); }} 
                    disabled={currentSlide === questions.length - 1}
                    className="fixed right-4 top-1/2 -translate-y-1/2 p-4 rounded-full bg-white/20 hover:bg-white/40 dark:bg-black/20 dark:hover:bg-black/40 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-sm border border-slate-200/50 dark:border-slate-700/50 z-30"
                >
                    <ChevronRight className="w-8 h-8" />
                </button>

                {/* Progress Bar */}
                <div className="absolute bottom-6 left-0 right-0 flex justify-center pointer-events-none z-30">
                     <div className="flex flex-col items-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-md px-4 py-2 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-sm">
                        <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">
                            Câu {currentSlide + 1} / {questions.length}
                        </span>
                        <div className="flex gap-1.5">
                            {questions.map((_, idx) => (
                                <div key={idx} className={`h-1.5 rounded-full transition-all duration-300 ${idx === currentSlide ? 'bg-indigo-500 w-6' : 'bg-slate-300 dark:bg-slate-600 w-1.5'}`} />
                            ))}
                        </div>
                    </div>
                </div>
             </div>
          )}

       </div>

       {/* DOCK BAR (Similar to StudyGuide) */}
       <div className={`no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-500 ease-in-out ${viewMode === 'slide' && !showNav ? 'translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>

            {/* Nav Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Danh sách câu hỏi</h3>
                        <div className="flex gap-2">
                            <button onClick={() => setIsEditMode(!isEditMode)} className={`p-1 rounded-lg ${isEditMode ? 'bg-red-100 text-red-600' : 'hover:bg-slate-100 text-slate-500'}`} title="Chế độ chỉnh sửa (Xóa câu)">
                                <Edit className="w-4 h-4" />
                            </button>
                            <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                                <X className="w-5 h-5 text-slate-400" />
                            </button>
                        </div>
                    </div>
                    <div className="grid grid-cols-5 gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar p-1">
                        {questions.map((_, idx) => {
                            const isActive = idx === currentSlide;
                            const isAns = userAnswers[idx] !== undefined;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToQuestion(idx)}
                                    className={`aspect-square rounded-lg font-bold text-sm transition-all shadow-sm border flex items-center justify-center relative
                                        ${isActive 
                                            ? 'bg-indigo-600 text-white ring-2 ring-indigo-300' 
                                            : (isAns ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800' : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600 border-transparent')}
                                    `}
                                >
                                    {idx + 1}
                                    {isEditMode && <span className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border border-white"></span>}
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Main Dock */}
            <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={(e) => { e.stopPropagation(); !isDockExpanded && setIsDockExpanded(true); }}
            >
                {isDockExpanded ? (
                    <>
                         {/* View Mode */}
                        <button 
                            onClick={() => setViewMode(prev => prev === 'slide' ? 'list' : 'slide')}
                            className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-indigo-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}
                        >
                            {viewMode === 'slide' ? <PresentationIcon className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                        </button>

                        {/* Zoom (Slide Only) */}
                        {viewMode === 'slide' && (
                             <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                                <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-indigo-300"><ZoomOut className="w-4 h-4"/></button>
                                <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                                <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-indigo-300"><ZoomIn className="w-4 h-4"/></button>
                            </div>
                        )}

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Tools */}
                        <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`}><MousePointer2 className="w-5 h-5" /></button>
                        <button onClick={() => setShowBlackboard(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-yellow-400 transition-colors"><PenTool className="w-5 h-5" /></button>
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors"><Dices className="w-5 h-5" /></button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Nav Toggle */}
                        <button onClick={() => setShowNav(!showNav)} className={`p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`}><LayoutGrid className="w-5 h-5" /></button>

                         {/* Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <Menu className="w-5 h-5" />
                )}
            </div>
       </div>

       {/* Modals */}
       {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
       {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
       {showScoreModal && isSubmitted && (
           <div className="fixed inset-0 z-[70] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowScoreModal(false)}>
               <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-lg w-full transform scale-100 animate-fade-in-up text-center" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-center mb-4">{feedback.emoji}</div>
                    <h3 className={`text-4xl font-black mb-2 ${feedback.color}`}>{results.score}</h3>
                    <p className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-2">{feedback.text}</p>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Bạn đã trả lời đúng {results.correct}/{results.total} câu.</p>
                    <div className="flex gap-4 justify-center">
                        <button onClick={() => setShowScoreModal(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 rounded-xl font-bold text-slate-700 dark:text-slate-200">Xem lại bài</button>
                        <button onClick={() => { setIsSubmitted(false); setUserAnswers({}); setShowScoreModal(false); window.scrollTo(0,0); }} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold">Làm lại</button>
                    </div>
               </div>
           </div>
       )}

    </div>
  );
};

import React, { useState, useRef } from 'react';
import { SUBJECTS, GRADES, DIFFICULTY_LEVELS, QUESTION_TYPES, SAMPLE_TOPICS } from '../constants';
import { ExamConfig, Subject, QuestionType, DifficultyLevel, GenMode, MatrixRow } from '../types';
import { BookOpen, Brain, Sparkles, Layers, ListChecks, Presentation as PresentationIcon, FileText, Upload, Image as ImageIcon, X, Paperclip, Plus, Trash2, Table2 } from 'lucide-react';

interface ConfigFormProps {
  onGenerate: (config: ExamConfig) => void;
  isLoading: boolean;
  onImport: (file: File) => void;
}

const ConfigForm: React.FC<ConfigFormProps> = ({ onGenerate, isLoading, onImport }) => {
  const [mode, setMode] = useState<GenMode>('exam');
  const [subject, setSubject] = useState<Subject | string>(Subject.MATH);
  const [grade, setGrade] = useState<string>(GRADES[11]); 

  // Single Mode State
  const [topic, setTopic] = useState<string>('');
  const [questionType, setQuestionType] = useState<QuestionType>(QuestionType.MULTIPLE_CHOICE);
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficultyMode, setDifficultyMode] = useState<'progressive' | 'fixed'>('progressive');
  const [targetLevel, setTargetLevel] = useState<DifficultyLevel>(DifficultyLevel.MEDIUM);

  // Matrix Mode State
  const [matrixTitle, setMatrixTitle] = useState<string>('Đề ôn tập học kì');
  const [matrixRows, setMatrixRows] = useState<MatrixRow[]>([
    { topic: '', level: DifficultyLevel.EASY, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.MEDIUM, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.HARD, count: 1, type: QuestionType.ESSAY },
  ]);

  // File upload state
  const [uploadedFile, setUploadedFile] = useState<{name: string, data: string, mimeType: string} | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const resourceInputRef = useRef<HTMLInputElement>(null);

  const suggestedTopics = SAMPLE_TOPICS[subject as Subject] || [];

  const handleAddRow = () => {
    setMatrixRows([...matrixRows, { topic: '', level: DifficultyLevel.MEDIUM, count: 1, type: QuestionType.MULTIPLE_CHOICE }]);
  };

  const handleRemoveRow = (index: number) => {
    if (matrixRows.length > 1) {
      const newRows = [...matrixRows];
      newRows.splice(index, 1);
      setMatrixRows(newRows);
    }
  };

  const handleRowChange = (index: number, field: keyof MatrixRow, value: any) => {
    const newRows = [...matrixRows];
    newRows[index] = { ...newRows[index], [field]: value };
    setMatrixRows(newRows);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Determine the main topic string based on mode
    const finalTopic = mode === 'matrix' ? matrixTitle : (topic || (uploadedFile ? "Nội dung từ tài liệu đính kèm" : ""));

    onGenerate({
      mode,
      subject,
      grade,
      topic: finalTopic,
      // Single Mode props
      questionType: mode === 'exam' ? questionType : undefined,
      questionCount: mode === 'exam' ? questionCount : undefined,
      difficultyMode: mode === 'exam' ? difficultyMode : undefined,
      targetLevel: mode === 'exam' && difficultyMode === 'fixed' ? targetLevel : undefined,
      // Matrix Mode props
      matrixRows: mode === 'matrix' ? matrixRows : undefined,

      includeHints: true,
      uploadedFile: uploadedFile ? { data: uploadedFile.data, mimeType: uploadedFile.mimeType } : null
    });
  };

  const handleImportFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onImport(e.target.files[0]);
    }
    if (e.target.value) e.target.value = '';
  };

  const handleResourceFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();

      reader.onload = (event) => {
        const base64String = event.target?.result as string;
        const base64Data = base64String.split(',')[1];

        setUploadedFile({
          name: file.name,
          mimeType: file.type,
          data: base64Data
        });

        if (mode !== 'matrix' && !topic) {
          setTopic("Nội dung tài liệu: " + file.name);
        }
      };

      reader.readAsDataURL(file);
    }
    if (e.target.value) e.target.value = '';
  };

  const clearUploadedFile = () => {
    setUploadedFile(null);
    if (mode !== 'matrix' && topic.startsWith("Nội dung tài liệu:")) {
        setTopic("");
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-800 rounded-2xl shadow-xl overflow-hidden border border-slate-200 dark:border-slate-700 relative transition-colors duration-300">

      {/* Import Button absolute positioned */}
      <div className="absolute top-4 right-4 z-10">
         <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept=".json"
            onChange={handleImportFileChange}
         />
         <button 
           type="button"
           onClick={() => fileInputRef.current?.click()}
           className="flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:text-indigo-600 dark:hover:text-indigo-400 rounded-lg text-sm font-bold shadow-sm border border-slate-300 dark:border-slate-600 hover:border-indigo-300 transition-all"
           title="Nhập dữ liệu từ file JSON cũ"
         >
            <Upload className="w-4 h-4" />
            <span className="hidden sm:inline">Mở file cũ</span>
         </button>
      </div>

      {/* Mode Tabs */}
      <div className="flex border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 overflow-x-auto">
        <button 
          onClick={() => setMode('exam')}
          className={`flex-1 min-w-[140px] py-4 text-center font-bold text-sm md:text-base flex items-center justify-center gap-2 transition-colors border-b-2 ${
            mode === 'exam' 
              ? 'border-blue-600 text-blue-700 dark:text-blue-400 bg-white dark:bg-slate-800' 
              : 'border-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-700 dark:hover:text-slate-200'
          }`}
        >
          <ListChecks className="w-5 h-5" />
          Chuyên đề Đơn lẻ
        </button>
        <button 
          onClick={() => setMode('matrix')}
          className={`flex-1 min-w-[140px] py-4 text-center font-bold text-sm md:text-base flex items-center justify-center gap-2 transition-colors border-b-2 ${
            mode === 'matrix' 
              ? 'border-indigo-600 text-indigo-700 dark:text-indigo-400 bg-white dark:bg-slate-800' 
              : 'border-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-700 dark:hover:text-slate-200'
          }`}
        >
          <Table2 className="w-5 h-5" />
          Luyện tập Tổng hợp
        </button>
        <button 
          onClick={() => setMode('theory')}
          className={`flex-1 min-w-[140px] py-4 text-center font-bold text-sm md:text-base flex items-center justify-center gap-2 transition-colors border-b-2 ${
            mode === 'theory' 
              ? 'border-teal-600 text-teal-700 dark:text-teal-400 bg-white dark:bg-slate-800' 
              : 'border-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-700 dark:hover:text-slate-200'
          }`}
        >
          <PresentationIcon className="w-5 h-5" />
          Lý Thuyết & Ví Dụ
        </button>
      </div>

      {/* Header Area */}
      <div className="p-8 border-b border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800">
        <h2 className={`text-2xl font-black flex items-center gap-2 ${
            mode === 'exam' ? 'text-blue-700 dark:text-blue-400' : mode === 'matrix' ? 'text-indigo-700 dark:text-indigo-400' : 'text-teal-700 dark:text-teal-400'
        }`}>
          <Sparkles className="w-6 h-6 text-yellow-500" />
          {mode === 'exam' && 'Thiết lập Ma trận Chuyên đề'}
          {mode === 'matrix' && 'Thiết lập Ma trận Tổng hợp'}
          {mode === 'theory' && 'Thiết lập Bài giảng Trọng tâm'}
        </h2>
        <p className="text-slate-500 dark:text-slate-400 mt-2 text-sm pr-20 font-medium">
          {mode === 'exam' && 'Tạo đề sâu cho một chủ đề cụ thể với độ khó tăng dần.'}
          {mode === 'matrix' && 'Tạo đề tổng hợp nhiều chủ đề (Ôn thi HK, THPT QG) theo cấu trúc ma trận chi tiết.'}
          {mode === 'theory' && 'Tạo slide tổng hợp kiến thức trọng tâm và các ví dụ minh họa điển hình.'}
        </p>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-8 bg-white dark:bg-slate-800">

        {/* Basic Info (Subject/Grade) - Common for all */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">Môn học</label>
              <select 
                value={subject} 
                onChange={(e) => setSubject(e.target.value)}
                className="w-full rounded-lg border-slate-300 dark:border-slate-600 border-2 p-2.5 text-slate-800 dark:text-slate-100 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 hover:bg-white dark:hover:bg-slate-950 transition-colors"
              >
                {SUBJECTS.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-1">Khối lớp</label>
              <select 
                value={grade} 
                onChange={(e) => setGrade(e.target.value)}
                className="w-full rounded-lg border-slate-300 dark:border-slate-600 border-2 p-2.5 text-slate-800 dark:text-slate-100 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 hover:bg-white dark:hover:bg-slate-950 transition-colors"
              >
                {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
              </select>
            </div>
        </div>

        {/* --- SINGLE MODE / THEORY MODE CONTENT --- */}
        {mode !== 'matrix' && (
            <div className="space-y-4 animate-fade-in">
                <div className="bg-slate-50 dark:bg-slate-900 p-5 rounded-xl border border-slate-200 dark:border-slate-700 shadow-inner">
                    <label className="block text-sm font-bold text-slate-900 dark:text-slate-200 mb-3">Chủ đề hoặc Tài liệu nguồn</label>
                    <input 
                        type="file" 
                        ref={resourceInputRef} 
                        className="hidden" 
                        accept="image/*,application/pdf"
                        onChange={handleResourceFileChange}
                    />

                    {!uploadedFile ? (
                        <div className="flex flex-col gap-3">
                            <div className="flex gap-2">
                            <input
                                type="text"
                                value={topic}
                                onChange={(e) => setTopic(e.target.value)}
                                placeholder="Nhập chủ đề (VD: Hàm số, Câu điều kiện...)"
                                className="flex-grow rounded-lg border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 border-2 p-3 text-slate-900 dark:text-slate-100 font-medium placeholder-slate-400 dark:placeholder-slate-500 focus:ring-2 focus:ring-indigo-500"
                            />
                            <button
                                type="button"
                                onClick={() => resourceInputRef.current?.click()}
                                className="flex-shrink-0 flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-lg text-indigo-700 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 font-bold"
                            >
                                <Paperclip className="w-4 h-4" /> Ảnh/PDF
                            </button>
                            </div>
                            {suggestedTopics.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                                {suggestedTopics.map(t => (
                                <button key={t} type="button" onClick={() => setTopic(t)} className="text-xs font-medium bg-white dark:bg-slate-700 hover:bg-indigo-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 hover:text-indigo-700 dark:hover:text-indigo-300 px-3 py-1.5 rounded-full border border-slate-200 dark:border-slate-600">
                                    + {t}
                                </button>
                                ))}
                            </div>
                            )}
                        </div>
                    ) : (
                        <div className="flex items-center justify-between bg-white dark:bg-slate-800 border-2 border-indigo-100 dark:border-indigo-900 p-3 rounded-lg shadow-sm">
                            <div className="flex items-center gap-3 overflow-hidden">
