                                <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-indigo-300"><ZoomOut className="w-4 h-4"/></button>
                                <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                                <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-indigo-300"><ZoomIn className="w-4 h-4"/></button>
                            </div>
                        )}

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Tools */}
                        <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`} title="Laser Pointer"><MousePointer2 className="w-5 h-5" /></button>
                        <button onClick={() => setShowBlackboard(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-yellow-400 transition-colors" title="Bảng đen"><PenTool className="w-5 h-5" /></button>
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Vòng quay"><Dices className="w-5 h-5" /></button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Nav Toggle */}
                        <button onClick={() => setShowNav(!showNav)} className={`p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Danh sách câu hỏi"><LayoutGrid className="w-5 h-5" /></button>

                         {/* Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors" title="Thu gọn menu">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <Menu className="w-5 h-5" />
                )}
            </div>
       </div>

       {/* Modals */}
       {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
       {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
       {showScoreModal && isSubmitted && (
           <div className="fixed inset-0 z-[70] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowScoreModal(false)}>
               <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-lg w-full transform scale-100 animate-fade-in-up text-center" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-center mb-4">{feedback.emoji}</div>
                    <h3 className={`text-4xl font-black mb-2 ${feedback.color}`}>{results.score}</h3>
                    <p className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-2">{feedback.text}</p>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Bạn đã trả lời đúng {results.correct}/{results.total} câu.</p>
                    <div className="flex gap-4 justify-center">
                        <button onClick={() => setShowScoreModal(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 rounded-xl font-bold text-slate-700 dark:text-slate-200">Xem lại bài</button>
                        <button onClick={() => { setIsSubmitted(false); setUserAnswers({}); setShowScoreModal(false); window.scrollTo(0,0); }} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold">Làm lại</button>
                    </div>
               </div>
           </div>
       )}

    </div>
  );
};

