                            <h3 className={`text-3xl font-black mb-2 ${feedback.color}`}>Điểm số: {results.score} / 10</h3>
                            <p className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-2">{feedback.text}</p>
                            <div className="grid grid-cols-3 gap-4 text-center max-w-md mx-auto mb-6">
                                <div className="p-3 bg-emerald-50 dark:bg-emerald-900/30 rounded-xl">
                                    <div className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{results.correct}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Đúng</div>
                                </div>
                                <div className="p-3 bg-red-50 dark:bg-red-900/30 rounded-xl">
                                    <div className="text-2xl font-bold text-red-600 dark:text-red-400">{results.answered - results.correct}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Sai</div>
                                </div>
                                <div className="p-3 bg-slate-100 dark:bg-slate-700 rounded-xl">
                                    <div className="text-2xl font-bold text-slate-600 dark:text-slate-300">{results.total - results.answered}</div>
                                    <div className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Bỏ qua</div>
                                </div>
                            </div>
                            <button 
                                onClick={() => { setIsSubmitted(false); setUserAnswers({}); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
                                className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold rounded-lg transition-colors flex items-center gap-2 mx-auto"
                            >
                                <RefreshCw className="w-5 h-5" /> Làm lại
                            </button>
                        </div>
                    )}
                 </div>
             </div>
          ) : (
             // SLIDE MODE - RESPONSIVE FULL SCREEN WITH SIDE BOARD SUPPORT
             <div 
                className={`
                    fixed top-0 left-0 bottom-0 z-50 bg-slate-50 dark:bg-slate-950 flex flex-col justify-center items-start p-0 transition-all duration-300 ease-in-out
                    ${showBlackboard && blackboardMode === 'side' ? 'w-[50vw] border-r border-slate-200 dark:border-slate-700' : 'w-full'}
                `}
                onClick={() => setShowNav(prev => !prev)}
             >
                <div 
                    className="w-full h-full flex flex-col justify-center max-w-full p-4 md:p-8 pl-6 md:pl-16"
                    onClick={(e) => e.stopPropagation()}
                >
                    {questions.length > 0 && renderQuestionCard(questions[currentSlide], currentSlide, true)}
                </div>

                {/* Navigation Arrows */}
                <button 
                    onClick={(e) => { e.stopPropagation(); prevSlide(); }} 
                    disabled={currentSlide === 0}
                    className="fixed left-6 top-1/2 -translate-y-1/2 p-4 rounded-full bg-slate-100/50 hover:bg-white dark:bg-slate-800/50 dark:hover:bg-slate-700 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-lg border border-slate-200/50 dark:border-slate-700/50 z-[60]"
                >
                    <ChevronLeft className="w-8 h-8" />
                </button>
                <button 
                    onClick={(e) => { e.stopPropagation(); nextSlide(); }} 
                    disabled={currentSlide === questions.length - 1}
                    className={`fixed top-1/2 -translate-y-1/2 p-4 rounded-full bg-slate-100/50 hover:bg-white dark:bg-slate-800/50 dark:hover:bg-slate-700 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-lg border border-slate-200/50 dark:border-slate-700/50 z-[60]
                        ${showBlackboard && blackboardMode === 'side' ? 'right-[calc(50vw+24px)]' : 'right-6'}
                    `}
                >
                    <ChevronRight className="w-8 h-8" />
                </button>

                {/* Progress Bar */}
                <div className={`absolute bottom-20 md:bottom-10 left-0 flex justify-center pointer-events-none z-[60] transition-all duration-300 ${showBlackboard && blackboardMode === 'side' ? 'w-[50vw]' : 'w-full'}`}>
                     <div className="flex flex-col items-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-md px-6 py-3 rounded-full border border-slate-200/50 dark:border-slate-700/50 shadow-xl">
                        <span className="text-sm font-bold text-slate-600 dark:text-slate-300 uppercase tracking-widest mb-1">
                            Câu {currentSlide + 1} / {questions.length}
                        </span>
                        <div className="flex gap-2">
                            {questions.map((_, idx) => (
                                <div key={idx} className={`h-2 rounded-full transition-all duration-300 ${idx === currentSlide ? 'bg-indigo-600 w-8' : 'bg-slate-300 dark:bg-slate-600 w-2'}`} />
                            ))}
                        </div>
                    </div>
                </div>
             </div>
          )}

