                            <button onClick={handlePrintTeacher} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 flex items-center gap-2 border-t border-slate-100 dark:border-slate-700">
                                <FileSignature className="w-4 h-4" /> Bản giáo viên (có lời giải)
                            </button>
