                                <>
                                {canViewSolution ? (
                                    <button onClick={() => toggleSolution(q.id)} className="text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 flex items-center gap-1 px-4 py-2 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors">
                                        {activeSolutions[q.id] ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}
                                        {activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải chi tiết'}
                                    </button>
                                ) : (
                                    <div className="text-sm text-slate-400 italic px-4 py-2 flex items-center gap-2">
                                        <EyeOff className="w-4 h-4" /> Trả lời để xem giải
                                    </div>
                                )}
                                </>
                            )}
                        </div>

                         {activeHints[q.id] && q.hints && (
                             <div className="bg-indigo-50 dark:bg-indigo-900/20 p-6 rounded-2xl border border-indigo-100 dark:border-indigo-800 text-lg text-indigo-900 dark:text-indigo-200 animate-fade-in shadow-inner mt-2">
                                 <ul className="list-disc list-inside space-y-2 pl-2">
                                     {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                                 </ul>
                             </div>
                         )}

                         {(showAnswers || activeSolutions[q.id]) && (
                             <div className="mt-4 p-6 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border-2 border-emerald-100 dark:border-emerald-800 text-emerald-900 dark:text-emerald-100 shadow-sm animate-fade-in">
                                 <h4 className="font-bold text-xl mb-3 flex items-center gap-2 border-b border-emerald-200 dark:border-emerald-700 pb-2">
                                     <CheckCircle className="w-6 h-6" /> Đáp án & Lời giải chi tiết
                                 </h4>
                                 <p className="mb-4 font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                                     Đáp án: <span className="px-3 py-1 bg-emerald-200 dark:bg-emerald-800 rounded-lg"><MathRenderer content={q.correctAnswer} /></span>
                                 </p>
                                 <div className="text-lg whitespace-pre-wrap leading-relaxed">
                                     <MathRenderer content={q.solution} inline={false} />
                                 </div>
                             </div>
                         )}
                     </div>
                 )}
              </div>

              {/* --- FOOTER INFO (SLIDE MODE ONLY) --- */}
              {isSlideMode && (
                  <div className="mt-auto flex flex-col gap-4">
                       {/* Inspirational Quote Footer */}
                        <div className="text-center pointer-events-none z-0 opacity-60 px-4 pb-2">
                            <p className="text-sm md:text-base font-serif italic text-slate-500 dark:text-slate-400">
                                "{STUDY_QUOTES[currentSlide % STUDY_QUOTES.length]}"
                            </p>
                        </div>
                  </div>
              )}
          </div>
        </div>
    );
  };

  return (
    <div 
        ref={containerRef}
        className={`
            bg-slate-50 dark:bg-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-800 dark:selection:bg-indigo-900 dark:selection:text-indigo-200 relative transition-all duration-300
            ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}
            ${isLaserPointer ? 'cursor-[url(https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Red_dot.svg/16px-Red_dot.svg.png),_auto]' : ''}
            ${!showBlackboard || blackboardMode === 'bottom' ? 'w-full' : ''}
        `}
    >
      {/* Content Wrapper */}
       <div className={`
             transition-all duration-300 ease-in-out h-full flex flex-col
             ${showBlackboard && blackboardMode === 'side' 
                ? 'w-[50vw] h-screen fixed left-0 top-0 overflow-hidden z-30 border-r border-slate-200 dark:border-slate-700 shadow-2xl bg-slate-50 dark:bg-slate-900' 
                : 'w-full'}
        `}>
          {/* Header */}
          <div className={`
                bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-slate-200 dark:border-slate-700 p-4 flex items-center justify-between gap-4 sticky top-0 z-40 shadow-sm no-print transition-all duration-500 ease-in-out
                ${!showNav && viewMode === 'slide' ? '-translate-y-full opacity-0 absolute w-full' : 'translate-y-0 opacity-100'}
            `}>
             <div className="flex items-center gap-4 flex-1 overflow-hidden">
                 <button onClick={onReset} className="flex-shrink-0 flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white font-medium px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                     <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                 </button>
                 <div className="h-8 w-px bg-slate-300 dark:bg-slate-600 mx-2"></div>
                 <div className="flex items-center gap-2 overflow-hidden">
                     <Brain className="w-5 h-5 text-indigo-600 dark:text-indigo-400 flex-shrink-0" />
                     <h1 className="text-lg md:text-xl font-bold text-slate-800 dark:text-white truncate" title={config.topic}>
                         {config.topic}
                     </h1>
                 </div>
             </div>

             <div className="flex items-center gap-2 flex-shrink-0">
                  {/* View Mode Toggles */}
                  <div className="hidden md:flex gap-2 mr-2">
                       <button onClick={() => setViewMode('list')} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'list' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-1 ring-indigo-200 dark:ring-indigo-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}>
                           <ListChecks className="w-4 h-4" /> Danh sách
                       </button>
                       <button onClick={() => setViewMode('slide')} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-1 ring-indigo-200 dark:ring-indigo-700' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}>
                           <PresentationIcon className="w-4 h-4" /> Slide
                       </button>
                  </div>

                  <div className="h-8 w-px bg-slate-200 dark:bg-slate-600 mx-1"></div>

                  <button onClick={handleExportJSON} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 shadow-sm transition-all" title="Lưu file">
                        <Save className="w-4 h-4" /> <span className="hidden sm:inline">Lưu</span>
                  </button>
                  <button onClick={handleDownloadWord} disabled={isExporting} className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 dark:bg-blue-700 text-white hover:bg-blue-700 dark:hover:bg-blue-600 shadow-sm transition-all disabled:opacity-50" title="Xuất Word">
                      {isExporting ? <span className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></span> : <Download className="w-4 h-4" />} <span className="hidden sm:inline">Word</span>
                  </button>

                   <div className="dropdown relative group">
                        <button className="flex items-center gap-2 px-3 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg font-bold text-sm shadow-sm transition-colors border border-slate-200 dark:border-slate-600">
                             <Printer className="w-4 h-4" />
                        </button>
                        <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden hidden group-hover:block z-50 animate-fade-in-up">
                            <button onClick={handlePrintStudent} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 flex items-center gap-2">
                                <User className="w-4 h-4" /> Bản học sinh (đề trắng)
                            </button>
                            <button onClick={handlePrintTeacher} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 flex items-center gap-2 border-t border-slate-100 dark:border-slate-700">
                                <FileSignature className="w-4 h-4" /> Bản giáo viên (có lời giải)
                            </button>
                        </div>
                   </div>

                  <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                  </button>
             </div>
          </div>

          {/* Main Body */}
          <div className="flex-grow overflow-y-auto overflow-x-hidden custom-scrollbar bg-slate-50 dark:bg-slate-900" onClick={() => setShowNav(prev => !prev)}>
               {viewMode === 'list' ? (
                   <div className="max-w-4xl mx-auto p-6 md:p-12 pb-32">
                        {/* Title Section */}
                        <div className="text-center mb-10">
                             <h2 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tight">{config.topic || "PHIẾU LUYỆN TẬP"}</h2>
                             <p className="text-lg text-slate-600 dark:text-slate-400 font-medium">Môn: {config.subject} - {config.grade}</p>
                             {data.summary && <p className="text-sm text-slate-500 mt-2 italic max-w-2xl mx-auto bg-slate-100 dark:bg-slate-800/50 p-2 rounded-lg">{data.summary}</p>}
                        </div>

                        {/* Questions */}
                        <div>
                             {questions.map((q, i) => renderQuestionCard(q, i, false))}
                        </div>

                        {/* Submit Button */}
                        {!isSubmitted ? (
                             <div className="sticky bottom-6 flex justify-center mt-8">
                                  <button onClick={handleSubmitExam} className="px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xl rounded-full shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all flex items-center gap-3 ring-4 ring-indigo-200 dark:ring-indigo-900">
                                      <Send className="w-6 h-6" /> Nộp bài & Xem kết quả
                                  </button>
                             </div>
                        ) : (
                             <div className="mt-8 p-6 bg-slate-100 dark:bg-slate-800 rounded-2xl text-center border-2 border-slate-200 dark:border-slate-700">
                                  <h3 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2">Đã hoàn thành bài thi!</h3>
                                  <p className="text-slate-600 dark:text-slate-400 mb-4">Bạn có thể xem lại đáp án chi tiết ở trên.</p>
                                  <button onClick={() => { setIsSubmitted(false); setUserAnswers({}); scrollTo(0,0); }} className="px-6 py-2 bg-slate-200 hover:bg-slate-300 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-800 dark:text-slate-200 font-bold rounded-lg transition-colors">
                                      Làm lại
                                  </button>
                             </div>
                        )}
                   </div>
               ) : (
                   <div className="h-full w-full flex flex-col justify-center items-center p-0 m-0">
                        <div className="w-full h-full flex flex-col">
                             {/* Single Card Slide */}
                             {questions.length > 0 && renderQuestionCard(questions[currentSlide], currentSlide, true)}
                        </div>

                        {/* Slide Nav Buttons */}
                        <div className={`fixed bottom-6 inset-x-0 flex justify-between px-6 pointer-events-none ${!showNav ? 'opacity-0 hover:opacity-100' : 'opacity-100'} transition-opacity`}>
                             <button 
                                onClick={(e) => { e.stopPropagation(); prevSlide(); }} 
                                disabled={currentSlide === 0}
                                className="pointer-events-auto p-4 rounded-full bg-slate-900/10 hover:bg-slate-900/20 dark:bg-white/10 dark:hover:bg-white/20 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0"
                             >
                                 <ChevronLeft className="w-8 h-8" />
                             </button>
                             <button 
                                onClick={(e) => { e.stopPropagation(); nextSlide(); }} 
                                disabled={currentSlide === questions.length - 1}
                                className="pointer-events-auto p-4 rounded-full bg-slate-900/10 hover:bg-slate-900/20 dark:bg-white/10 dark:hover:bg-white/20 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white backdrop-blur-md transition-all disabled:opacity-0"
                             >
                                 <ChevronRight className="w-8 h-8" />
                             </button>
                        </div>

                        {/* Slide Progress */}
                        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 pointer-events-none">
                             <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur px-4 py-1.5 rounded-full border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col items-center gap-1">
                                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Câu {currentSlide + 1} / {questions.length}</span>
                                  <div className="flex gap-1">
                                      {questions.map((_, idx) => (
                                          <div key={idx} className={`h-1.5 w-1.5 rounded-full transition-all ${idx === currentSlide ? 'bg-indigo-600 scale-125' : 'bg-slate-300 dark:bg-slate-600'}`} />
                                      ))}
                                  </div>
                             </div>
                        </div>
                   </div>
               )}
          </div>
       </div>

       {/* Dock */}
       <div className={`no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-500 ease-in-out ${!showNav && viewMode === 'slide' ? 'translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
            {/* Nav Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Danh sách câu hỏi</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="grid grid-cols-5 gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar p-1">
                        {questions.map((q, idx) => {
                            const isActive = idx === currentSlide;
                            const isAnswered = userAnswers[idx] !== undefined;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToQuestion(idx)}
                                    className={`
                                        aspect-square rounded-lg font-bold text-sm transition-all shadow-sm border flex items-center justify-center relative
                                        ${isActive 
                                            ? 'bg-indigo-600 text-white ring-2 ring-indigo-300 dark:ring-indigo-500 border-transparent scale-105' 
                                            : isAnswered 
                                                ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800'
                                                : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-indigo-50 dark:hover:bg-slate-600 border-slate-200 dark:border-slate-600'}
                                    `}
                                >
                                    {idx + 1}
                                    {isAnswered && <div className="absolute top-0 right-0 w-2 h-2 bg-emerald-500 rounded-full -mr-0.5 -mt-0.5"></div>}
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Dock Bar */}
             <div 
                className={`
                flex items-center gap-2 bg-slate-900/80 dark:bg-white/10 backdrop-blur-xl text-white shadow-2xl border border-white/10 transition-all duration-300 ease-in-out transform
                ${isDockExpanded 
                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={(e) => { e.stopPropagation(); !isDockExpanded && setIsDockExpanded(true); }}
            >
                {isDockExpanded ? (
                    <>
                         <button onClick={() => setIsEditMode(!isEditMode)} className={`p-3 rounded-full transition-colors ${isEditMode ? 'bg-red-600 text-white' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`} title="Chế độ chỉnh sửa (Xóa câu hỏi)">
                              <Edit className="w-5 h-5" />
                         </button>

                         <button onClick={() => setViewMode(prev => prev === 'slide' ? 'list' : 'slide')} className={`p-3 rounded-full transition-colors ${viewMode === 'slide' ? 'bg-indigo-600 text-white shadow-inner' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`} title={viewMode === 'slide' ? "Chuyển sang Danh sách" : "Chuyển sang Slide"}>
                            {viewMode === 'slide' ? <PresentationIcon className="w-5 h-5" /> : <ListChecks className="w-5 h-5" />}
                        </button>

                        {/* Zoom Tools */}
                         <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-indigo-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-indigo-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                         <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`} title="Laser Pointer">
                            <MousePointer2 className="w-5 h-5" />
                        </button>

                         <div className="w-px h-6 bg-white/20 mx-1"></div>

                         <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Danh sách câu hỏi">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                         <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                         <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <Menu className="w-5 h-5" />
                    </div>
                )}
             </div>
       </div>

       {/* Score Modal */}
        {showScoreModal && (
            <div className="fixed inset-0 z-[80] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden relative border border-slate-200 dark:border-slate-700 animate-bounce-in">
                    <button onClick={() => setShowScoreModal(false)} className="absolute top-4 right-4 p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors z-10">
                        <X className="w-6 h-6 text-slate-500" />
                    </button>

                    <div className="p-8 md:p-12 text-center">
                        <div className="mb-6 flex justify-center">{feedback.emoji}</div>
                        <h2 className={`text-4xl font-black mb-2 ${feedback.color}`}>{feedback.text}</h2>

                        <div className="grid grid-cols-3 gap-4 my-8">
                             <div className="p-4 bg-slate-50 dark:bg-slate-700 rounded-2xl border border-slate-200 dark:border-slate-600">
                                 <div className="text-sm text-slate-500 dark:text-slate-400 font-bold uppercase">Điểm số</div>
                                 <div className={`text-4xl font-black ${feedback.color}`}>{results.score}</div>
                             </div>
                             <div className="p-4 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl border border-emerald-200 dark:border-emerald-800">
                                 <div className="text-sm text-emerald-600 dark:text-emerald-400 font-bold uppercase">Làm đúng</div>
                                 <div className="text-4xl font-black text-emerald-600 dark:text-emerald-400">{results.correct}/{results.total}</div>
                             </div>
                              <div className="p-4 bg-blue-50 dark:bg-blue-900/30 rounded-2xl border border-blue-200 dark:border-blue-800">
                                 <div className="text-sm text-blue-600 dark:text-blue-400 font-bold uppercase">Đã làm</div>
                                 <div className="text-4xl font-black text-blue-600 dark:text-blue-400">{results.answered}/{results.total}</div>
                             </div>
                        </div>

                        <div className="flex justify-center gap-4">
                            <button onClick={() => setShowScoreModal(false)} className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg transition-colors">
                                Xem lại bài làm
                            </button>
                             <button onClick={() => { setShowScoreModal(false); setIsSubmitted(false); setUserAnswers({}); scrollTo(0,0); }} className="px-6 py-3 bg-white hover:bg-slate-50 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-white font-bold rounded-xl shadow-lg border border-slate-200 dark:border-slate-600 transition-colors">
                                Làm lại đề này
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

       {/* Modals */}
       {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
       {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
