  return (
    <div ref={containerRef} className={`bg-slate-50 dark:bg-slate-900 min-h-screen transition-colors duration-300 ${isFullscreen ? 'fixed inset-0 z-50 overflow-auto bg-white dark:bg-slate-900' : ''}`}>

      {/* --- TOP TOOLBAR --- */}
      <div className={`
          bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm border-b border-slate-200 dark:border-slate-700 p-4 sticky top-0 z-40 shadow-sm no-print transition-all duration-500 ease-in-out
          ${!showNav && viewMode === 'slide' ? '-translate-y-full opacity-0 absolute w-full' : 'translate-y-0 opacity-100'}
      `}>
          <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-4 flex-1 w-full md:w-auto overflow-hidden">
