                        <RotateCcw className="w-4 h-4" /> <span className="hidden sm:inline">Quay lại</span>
                    </button>

                    <div className="h-8 w-px bg-slate-300 dark:bg-slate-600 mx-2 hidden md:block"></div>

                    <div className="flex items-center gap-2 overflow-hidden">
                        <ListChecks className="w-5 h-5 text-indigo-600 dark:text-indigo-400 flex-shrink-0" />
                        <h1 className="text-lg font-bold text-slate-800 dark:text-white truncate" title={config.topic}>
                            {config.topic}
                        </h1>
                    </div>
              </div>

              <div className="flex items-center gap-2 flex-shrink-0 overflow-x-auto w-full md:w-auto pb-1 md:pb-0">
