                  <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg mr-2">
                        <button 
                            onClick={() => setViewMode('list')}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-bold transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-600 text-indigo-600 dark:text-indigo-300 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
                        >
                            <FileText className="w-4 h-4" /> Danh sách
                        </button>
                        <button 
                            onClick={() => setViewMode('slide')}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-bold transition-all ${viewMode === 'slide' ? 'bg-white dark:bg-slate-600 text-indigo-600 dark:text-indigo-300 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
                        >
                            <PresentationIcon className="w-4 h-4" /> Slide
                        </button>
                  </div>

                  {/* Actions */}
                  <button 
                      onClick={() => setIsEditMode(!isEditMode)}
                      className={`p-2 rounded-lg transition-colors ${isEditMode ? 'bg-yellow-100 text-yellow-700 border border-yellow-300' : 'bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50'}`}
                      title={isEditMode ? "Tắt chế độ chỉnh sửa" : "Chỉnh sửa đề thi"}
                  >
                      <Edit className="w-5 h-5" />
                  </button>

                  <button 
                      onClick={onRegenerate}
                      className="p-2 rounded-lg bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 transition-colors"
                      title="Tạo đề khác tương tự"
                  >
                      <RefreshCw className="w-5 h-5" />
                  </button>

                  <div className="h-8 w-px bg-slate-200 dark:bg-slate-600 mx-1"></div>

                  <button 
                      onClick={handleExportJSON}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800 hover:bg-indigo-100 dark:hover:bg-indigo-900/40 shadow-sm transition-all"
                      title="Lưu file"
                  >
                      <Save className="w-4 h-4" />
                  </button>

                  <button 
                      onClick={handleDownloadWord} 
                      disabled={isExporting} 
                      className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 dark:bg-blue-700 text-white hover:bg-blue-700 dark:hover:bg-blue-600 shadow-sm transition-all disabled:opacity-50"
                  >
                      {isExporting ? <span className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></span> : <Download className="w-4 h-4" />} Word
                  </button>

                  <div className="relative group">
                    <button className="flex items-center gap-2 px-3 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg font-bold text-sm shadow-sm transition-colors border border-slate-200 dark:border-slate-600">
                        <Printer className="w-4 h-4" />
                    </button>
                    <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 p-1 hidden group-hover:block animate-fade-in z-50">
                        <button onClick={handlePrintStudent} className="w-full text-left px-4 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200">In đề học sinh</button>
                        <button onClick={handlePrintTeacher} className="w-full text-left px-4 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200">In phiếu giáo viên</button>
                    </div>
                  </div>

                  <button onClick={toggleFullScreen} className="p-2 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                        <Maximize className="w-5 h-5" />
                  </button>
              </div>
          </div>
      </div>

      {/* --- MAIN CONTENT --- */}
      <div className={`
        ${viewMode === 'list' ? 'max-w-5xl mx-auto p-4 md:p-8 pb-32' : 'h-[calc(100vh-80px)] w-full overflow-hidden bg-slate-100 dark:bg-black'}
      `}>

          {viewMode === 'list' && (
             <div className="animate-fade-in">
                 {/* Student Name Input (For Printing/Submission) */}
                 <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 mb-8 no-print">
                    <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
                        <div className="flex items-center gap-3 w-full md:w-auto">
                            <User className="w-6 h-6 text-slate-400" />
                            <input 
                                type="text" 
                                placeholder="Họ và tên học sinh..."
                                value={studentName}
                                onChange={(e) => setStudentName(e.target.value)}
                                className="w-full md:w-80 border-b-2 border-slate-200 dark:border-slate-700 bg-transparent py-2 px-1 focus:border-indigo-500 focus:outline-none text-lg font-medium text-slate-800 dark:text-slate-100 placeholder-slate-400"
                            />
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="text-right">
                                <div className="text-sm text-slate-500 dark:text-slate-400">Số câu đã làm</div>
                                <div className="text-xl font-bold text-indigo-600 dark:text-indigo-400">{Object.keys(userAnswers).length}/{questions.length}</div>
                            </div>

                            {/* Timer for List Mode */}
                            {!isSubmitted && (
                                <div className="relative">
                                    <button 
                                        onClick={() => setShowTimerMenu(!showTimerMenu)}
                                        className={`flex items-center gap-2 px-4 py-2 rounded-lg font-bold transition-all border
                                            ${timer !== null && isTimerRunning
                                                ? 'bg-red-50 text-red-600 border-red-200 animate-pulse'
                                                : 'bg-slate-100 text-slate-600 border-slate-200 hover:bg-slate-200'
                                            }
                                        `}
                                    >
                                        <Timer className="w-5 h-5" />
                                        {timer !== null ? formatTime(timer) : 'Bấm giờ'}
                                    </button>

                                    {showTimerMenu && (
                                        <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 p-2 z-50">
                                            {[15, 45, 60, 90].map(min => (
                                                <button key={min} onClick={() => startTimer(min)} className="w-full text-left px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200">{min} Phút</button>
                                            ))}
                                            <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="w-full text-left px-3 py-2 hover:bg-red-50 dark:hover:bg-red-900/30 text-red-600 rounded-lg text-sm font-medium mt-1 border-t border-slate-100 dark:border-slate-700 pt-2">Hủy / Dừng</button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                 </div>

                 {/* Questions List */}
                 <div className="space-y-8">
                      {questions.map((q, idx) => renderQuestionCard(q, idx, false))}
                 </div>

                 {/* Submit Button */}
                 {!isSubmitted && questions.length > 0 && (
                     <div className="mt-12 flex justify-center no-print">
                         <button 
                            onClick={handleSubmitExam}
                            className="group relative px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xl rounded-full shadow-lg hover:shadow-2xl hover:-translate-y-1 transition-all duration-300 flex items-center gap-3 overflow-hidden"
                         >
                            <span className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-shimmer"></span>
                            <Send className="w-6 h-6" /> Nộp bài & Xem kết quả
                         </button>
                     </div>
                 )}
             </div>
          )}

          {viewMode === 'slide' && questions.length > 0 && (
              <div 
                className="w-full h-full flex flex-col items-center justify-center relative p-4"
                onClick={() => setShowNav(prev => !prev)}
              >
                  <div className="w-full h-full max-w-6xl mx-auto flex flex-col" onClick={(e) => e.stopPropagation()}>
                       {renderQuestionCard(questions[currentSlide], currentSlide, true)}
                  </div>

                   {/* Navigation Arrows for Slide Mode */}
                   <div className="fixed bottom-8 left-0 right-0 flex justify-center gap-4 pointer-events-none z-50">
                        <button 
                            onClick={(e) => { e.stopPropagation(); prevSlide(); }}
                            disabled={currentSlide === 0}
                            className="pointer-events-auto p-4 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-md text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white border border-slate-200/50 dark:border-slate-700/50 shadow-lg transition-all disabled:opacity-0"
                        >
                            <ChevronLeft className="w-8 h-8" />
                        </button>

                         {/* Slide Counter */}
                         <div className="pointer-events-auto flex flex-col items-center justify-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-md px-6 rounded-2xl border border-slate-200/50 dark:border-slate-700/50 shadow-lg">
                            <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Câu hỏi</span>
                            <span className="text-xl font-black text-indigo-600 dark:text-indigo-400">{currentSlide + 1} <span className="text-slate-400 text-base font-normal">/ {questions.length}</span></span>
                        </div>

                        <button 
                            onClick={(e) => { e.stopPropagation(); nextSlide(); }}
                            disabled={currentSlide === questions.length - 1}
                            className="pointer-events-auto p-4 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-md text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-white border border-slate-200/50 dark:border-slate-700/50 shadow-lg transition-all disabled:opacity-0"
                        >
                            <ChevronRight className="w-8 h-8" />
                        </button>
                   </div>
              </div>
          )}
      </div>

      {/* --- DOCK --- */}
      <div className={`no-print fixed bottom-6 inset-x-0 mx-auto w-fit z-[60] flex flex-col items-center nav-dock-container transition-all duration-500 ease-in-out ${!showNav && viewMode === 'slide' ? 'translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>

             {/* Navigation Grid Popover */}
            {isDockExpanded && showNav && (
                <div className="mb-4 w-[90vw] max-w-sm bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 dark:border-slate-700/50 p-4 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-4 border-b border-slate-100/50 dark:border-slate-700/50 pb-2">
                        <h3 className="font-bold text-slate-700 dark:text-slate-200">Danh sách câu hỏi</h3>
                        <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                            <X className="w-5 h-5 text-slate-400" />
                        </button>
                    </div>
                    <div className="grid grid-cols-5 gap-2 max-h-[40vh] overflow-y-auto custom-scrollbar">
                        {questions.map((q, idx) => {
                            const isDone = userAnswers[idx] !== undefined;
                            const isActive = idx === currentSlide;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToQuestion(idx)}
                                    className={`w-10 h-10 rounded-lg font-bold transition-all text-sm flex items-center justify-center shadow-sm
                                        ${isActive 
                                            ? 'bg-indigo-600 text-white ring-2 ring-indigo-300' 
                                            : isDone 
                                                ? 'bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300'
                                                : 'bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                                        }
                                    `}
                                >
                                    {idx + 1}
                                </button>
                            );
