                    ? 'p-2 rounded-full scale-100' 
                    : 'px-4 py-3 rounded-full cursor-pointer hover:bg-slate-900/90 dark:hover:bg-white/20 hover:scale-105 active:scale-95'
                }
                `}
                onClick={(e) => { e.stopPropagation(); !isDockExpanded && setIsDockExpanded(true); }}
            >
                {isDockExpanded ? (
                    <>
                        {/* Zoom Tools */}
                        <div className="flex items-center gap-1 bg-white/10 rounded-full px-1 mx-1">
                            <button onClick={() => setZoomLevel(z => Math.max(0.8, z - 0.1))} className="p-2 hover:text-indigo-300"><ZoomOut className="w-4 h-4"/></button>
                            <span className="text-xs font-mono w-8 text-center">{Math.round(zoomLevel * 100)}%</span>
                            <button onClick={() => setZoomLevel(z => Math.min(2, z + 0.1))} className="p-2 hover:text-indigo-300"><ZoomIn className="w-4 h-4"/></button>
                        </div>

                        {/* Blackboard */}
                        <button onClick={() => setShowBlackboard(true)} className={`p-3 rounded-full transition-colors ${showBlackboard ? 'bg-yellow-500 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-yellow-400'}`} title="Bảng đen">
                            <PenTool className="w-5 h-5" />
                        </button>

                         {/* Random Picker */}
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Gọi ngẫu nhiên">
                            <Dices className="w-5 h-5" />
                        </button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Navigation / List */}
                        <button onClick={() => setShowNav(!showNav)} className={`nav-toggle-btn p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Danh sách câu hỏi">
                            <LayoutGrid className="w-5 h-5" />
                        </button>

                         {/* Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <Menu className="w-5 h-5" />
                    </div>
                )}
            </div>
      </div>

      {/* --- SCORE MODAL --- */}
      {showScoreModal && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in">
             <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden border border-slate-200 dark:border-slate-700 animate-fade-in-up">
                 <div className="bg-gradient-to-br from-indigo-500 to-purple-600 p-8 text-center relative overflow-hidden">
                     <div className="absolute top-0 left-0 w-full h-full opacity-20">
                         {/* Confetti or pattern background */}
                         <div className="absolute top-4 left-4 w-12 h-12 rounded-full bg-white blur-xl"></div>
                         <div className="absolute bottom-4 right-4 w-20 h-20 rounded-full bg-yellow-300 blur-xl"></div>
                     </div>

                     <div className="relative z-10 flex flex-col items-center">
                         <div className="mb-4">{feedback.emoji}</div>
                         <h2 className="text-3xl font-black text-white mb-2">Kết quả làm bài</h2>
                         <p className="text-white/90 font-medium text-lg">Học sinh: {studentName || "Ẩn danh"}</p>
                     </div>
                 </div>

                 <div className="p-8">
                     <div className="flex flex-col items-center mb-8">
                         <div className="text-6xl font-black text-slate-800 dark:text-white mb-2 tracking-tighter">
                             {results.score} <span className="text-2xl text-slate-400 font-bold">/ 10</span>
                         </div>
                         <div className={`text-center font-bold text-lg ${feedback.color}`}>
                             {feedback.text}
                         </div>
                     </div>

                     <div className="grid grid-cols-2 gap-4 mb-8">
                         <div className="bg-emerald-50 dark:bg-emerald-900/30 p-4 rounded-xl flex flex-col items-center">
                             <span className="text-slate-500 dark:text-slate-400 text-sm font-bold uppercase">Số câu đúng</span>
                             <span className="text-3xl font-black text-emerald-600 dark:text-emerald-400">{results.correct}</span>
                         </div>
                         <div className="bg-slate-50 dark:bg-slate-700/30 p-4 rounded-xl flex flex-col items-center">
                             <span className="text-slate-500 dark:text-slate-400 text-sm font-bold uppercase">Tổng số câu</span>
                             <span className="text-3xl font-black text-slate-700 dark:text-slate-200">{results.total}</span>
                         </div>
                     </div>

                     <button 
                         onClick={() => setShowScoreModal(false)}
                         className="w-full py-4 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-white font-bold rounded-xl transition-colors"
                     >
                         Xem chi tiết đáp án
                     </button>
                 </div>
             </div>
        </div>
      )}

      {/* --- UTILITY MODALS --- */}
      {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
      {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}

    </div>
  );
}; // End of ExamPreview

