import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import { Printer, CheckCircle, Eye, EyeOff, Lightbulb, ChevronDown, ChevronRight, FileText, Download, FileSignature, Save, LayoutGrid, ArrowUp, X, Menu, PenTool, Maximize, Minimize, RefreshCw, User, Trophy, Send, XCircle, Star, MonitorPlay, MousePointer2, ZoomIn, ZoomOut, ChevronLeft, ArrowRight, ArrowLeft, Trash2, Edit, Target, Dices, Smile, Frown, Award, PartyPopper, RotateCcw, Key, ChevronUp, Quote, Lock, Volume2, StopCircle, Presentation as PresentationIcon } from 'lucide-react';
import MathRenderer from './MathRenderer';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Math as DocxMath, MathRun, MathFraction, MathRadical, MathSuperScript, MathSubScript, MathSum, MathIntegral, MathLimitLower, Header, Footer, PageNumber, TabStopType, TabStopPosition, UnderlineType } from 'docx';
import FileSaver from 'file-saver';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
