                </button>

                {/* Progress Bar */}
                <div className={`absolute bottom-20 md:bottom-10 left-0 flex justify-center pointer-events-none z-[60] transition-all duration-300 ${showBlackboard && blackboardMode === 'side' ? 'w-[50vw]' : 'w-full'}`}>
