                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Tools */}
                        <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white shadow-[0_0_10px_red]' : 'hover:bg-white/10 text-slate-300 hover:text-white'}`} title="Laser Pointer"><MousePointer2 className="w-5 h-5" /></button>
                        <button onClick={() => setShowBlackboard(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-yellow-400 transition-colors" title="Bảng đen"><PenTool className="w-5 h-5" /></button>
                        <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full hover:bg-white/10 text-slate-100 hover:text-indigo-400 transition-colors" title="Vòng quay"><Dices className="w-5 h-5" /></button>

                        <div className="w-px h-6 bg-white/20 mx-1"></div>

                        {/* Nav Toggle */}
                        <button onClick={() => setShowNav(!showNav)} className={`p-3 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-100 hover:text-white'}`} title="Danh sách câu hỏi"><LayoutGrid className="w-5 h-5" /></button>

                         {/* Collapse */}
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors" title="Thu gọn menu">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <Menu className="w-5 h-5" />
                )}
            </div>
       </div>

       {/* Modals */}
       {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
       {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
       {showScoreModal && isSubmitted && (
           <div className="fixed inset-0 z-[70] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowScoreModal(false)}>
               <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-lg w-full transform scale-100 animate-fade-in-up text-center" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-center mb-4">{feedback.emoji}</div>
                    <h3 className={`text-4xl font-black mb-2 ${feedback.color}`}>{results.score}</h3>
                    <p className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-2">{feedback.text}</p>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Bạn đã trả lời đúng {results.correct}/{results.total} câu.</p>
                    <div className="flex gap-4 justify-center">
                        <button onClick={() => setShowScoreModal(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 rounded-xl font-bold text-slate-700 dark:text-slate-200">Xem lại bài</button>
                        <button onClick={() => { setIsSubmitted(false); setUserAnswers({}); setShowScoreModal(false); window.scrollTo(0,0); }} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold">Làm lại</button>
                    </div>
               </div>
           </div>
       )}

    </div>
  );
};

export enum DifficultyLevel {
  VERY_EASY = 'Rất dễ (Nhận biết)',
  EASY = 'Dễ (Thông hiểu)',
  MEDIUM = 'Trung bình (Vận dụng)',
  HARD = 'Khó (Vận dụng cao)',
  VERY_HARD = 'Rất khó (Xuất sắc)',
}

export enum QuestionType {
  MULTIPLE_CHOICE = 'Trắc nghiệm (4 chọn 1)',
  TRUE_FALSE = 'Trắc nghiệm Đúng/Sai',
  ESSAY = 'Tự luận',
  MIXED = 'Kết hợp (TN + Đúng/Sai + Tự luận)',
}

export enum Subject {
  MATH = 'Toán',
  PHYSICS = 'Vật Lý',
  CHEMISTRY = 'Hóa Học',
  BIOLOGY = 'Sinh Học',
  INFORMATICS = 'Tin Học',
  LITERATURE = 'Ngữ Văn',
  HISTORY = 'Lịch Sử',
  GEOGRAPHY = 'Địa Lý',
  ENGLISH = 'Tiếng Anh',
  GDCD = 'GDCD',
  SCIENCE = 'KHTN',
  CLASS_MEETING = 'Sinh hoạt lớp',
  LIFE_SKILLS = 'Kỹ năng sống',
  CAREER_GUIDANCE = 'Trải nghiệm hướng nghiệp',
}

export type GenMode = 'exam' | 'matrix' | 'theory';

export interface MatrixRow {
  topic: string;
  level: DifficultyLevel;
  count: number;
  type: QuestionType;
}

export interface ExamConfig {
  mode: GenMode;
  subject: Subject | string;
  grade: string;
  topic: string; // Used for single topic mode or as a title for matrix mode
  // Exam specific (Single Mode)
  questionType?: QuestionType;
  questionCount?: number;
  difficultyMode?: 'progressive' | 'fixed';
  targetLevel?: DifficultyLevel;
  // Matrix Mode
  matrixRows?: MatrixRow[];

  includeHints?: boolean;
  // Multimodal support
  uploadedFile?: {
    data: string; // base64 string
    mimeType: string;
  } | null;
}

export interface Question {
  id: number;
  content: string;
  type: QuestionType;
  difficulty: string; // e.g., "Nhận biết", "Vận dụng"
  options?: string[]; // For multiple choice
  correctAnswer: string;
  solution: string; // Detailed explanation
  hints?: string[]; // Step-by-step hints
}

export interface ExamMatrix {
  title?: string;
  objectives?: string[]; // Learning objectives
  summary: string;
  questions: Question[];
}

// Structures for Study Guide (Theory & Examples)
export interface Example {
  problem: string;
  solution: string;
  explanation: string;
}

export interface TheorySection {
  title: string;
  content: string; // Bullet points or paragraphs with LaTeX
  examples: Example[];
}

export interface StudyGuideData {
  topic: string;
  overview: string;
  sections: TheorySection[];
}

// Data structure for Export/Import
export interface ExportData {
  type: GenMode;
  timestamp: number;
  config: ExamConfig;
  data: ExamMatrix | StudyGuideData;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

const createClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const client = createClient();
  // Cập nhật model name chính xác theo hướng dẫn
  const smartModel = "gemini-3-pro-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      // Matrix Mode Instructions
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      // Exam Mode Instructions (Single Topic)
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Phân bổ hợp lý giữa 3 dạng bài:
            1. Trắc nghiệm nhiều lựa chọn (4 chọn 1).
            2. Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
            3. Trắc nghiệm trả lời ngắn (Tự luận điền kết quả).

          PHÂN BỔ ĐỘ KHÓ:
          - Dễ/Thông hiểu: Dùng trắc nghiệm 4 chọn 1.
          - Vận dụng: Dùng trắc nghiệm Đúng/Sai.
          - Vận dụng cao: Dùng trả lời ngắn (Tự luận).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao (Nguyên tắc: Dễ trước khó sau).' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề trọng tâm: "${config.topic}".
        Số lượng câu hỏi: ${config.questionCount}.
        Loại câu hỏi: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là nhà giáo dục Việt Nam xuất sắc, giáo viên giỏi đa môn, 
có 20 năm kinh nghiệm giảng dạy và nghiên cứu sách giáo khoa theo CTGDPT 2018,
chuyên gia ra đề kiểm tra – đánh giá năng lực học sinh THPT.

Bạn hiểu rõ:
- Mục tiêu cần đạt của CTGDPT 2018
- Cấu trúc đề kiểm tra hiện hành trong các trường phổ thông Việt Nam từ năm học 2025 trở đi (đặc biệt là dạng trắc nghiệm Đúng/Sai)
- Đặc điểm học sinh theo từng khối lớp
- Yêu cầu phân hóa và đánh giá năng lực

Hãy tạo một bộ đề luyện tập cho môn ${config.subject}, lớp ${config.grade},
bám sát sách giáo khoa (ghi rõ bộ sách),
cấu trúc đề hợp lý, có đáp án và hướng dẫn chấm chi tiết.
    Yêu cầu:
- Nội dung câu hỏi bám sát kiến thức trọng tâm SGK
- Có câu hỏi gắn với thực tế, đời sống hoặc liên môn
- Không đánh đố, không máy móc
- Mức độ khó tăng dần
- Ngôn ngữ chuẩn mực, rõ ràng, phù hợp học sinh Việt Nam
- Có đáp án, thang điểm và nhận xét sư phạm ngắn cho từng câu

    ${structureInstruction}

    Cấu hình độ khó: ${difficultyInstruction}
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Người dùng có cung cấp một tài liệu đính kèm (Hình ảnh hoặc PDF).
    Hãy PHÂN TÍCH KỸ nội dung trong file đính kèm đó.
    Dựa trên kiến thức, bài tập, hoặc ngữ liệu có trong file, hãy soạn ra bộ câu hỏi MỚI (tương tự dạng bài hoặc phát triển từ ngữ liệu đó).
    KHÔNG CHÉP LẠI Y NGUYÊN câu hỏi trong file nếu đó là file bài tập (hãy thay số liệu hoặc ngữ cảnh để tạo đề mới), trừ khi đề bài yêu cầu trích xuất.
    `;
  }

  promptText += `
    Yêu cầu quan trọng:
    1. Nội dung phải chuẩn theo chương trình GDPT 2018 của Bộ Giáo dục & Đào tạo Việt Nam.
    2. Các câu hỏi phải rõ ràng, không trùng lặp.
    3. Phải cung cấp đáp án đúng. Lời giải (solution) cần VIẾT TẮT, CỰC KỲ NGẮN GỌN, SÚC TÍCH, đi thẳng vào các bước biến đổi công thức chính, lược bỏ tối đa các câu văn dẫn dắt rườm rà.
    4. Phải cung cấp 2 gợi ý (hints) cho học sinh để kích thích tư duy (không cho đáp án ngay trong gợi ý).
    5. QUY TẮC DẠNG CÂU HỎI (Type):
       - Nếu type là '${QuestionType.MULTIPLE_CHOICE}': BẮT BUỘC phải có mảng 'options' gồm 4 lựa chọn A, B, C, D. 'correctAnswer' là 'A', 'B', 'C' hoặc 'D'.
       - Nếu type là '${QuestionType.TRUE_FALSE}': BẮT BUỘC phải có mảng 'options' gồm 4 mệnh đề con (a, b, c, d). 'correctAnswer' phải ghi rõ kết quả từng ý theo format: "a) Đ, b) S, c) Đ, d) S" hoặc "a: Đúng, b: Sai...".
       - Nếu type là '${QuestionType.ESSAY}': Mảng 'options' để rỗng hoặc null.
    6. ĐỊNH DẠNG TOÁN HỌC: Tất cả các công thức toán học, phương trình, biểu thức biến số (x, y, z...) PHẢI được viết dưới dạng LaTeX và đặt trong dấu $ (ví dụ: $x^2 + 2x + 1 = 0$, $\\frac{1}{2}$, $\\alpha$). Tuyệt đối không dùng Unicode math thông thường nếu có thể dùng LaTeX.
    7. MỤC TIÊU (Objectives): Hãy liệt kê 3-5 mục tiêu kiến thức, kỹ năng chính mà học sinh cần đạt được thông qua bài luyện tập này.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING, description: "Nội dung câu hỏi chính (Stem), chứa công thức LaTeX trong dấu $" },
      type: { type: Type.STRING, description: "Loại câu hỏi (Trắc nghiệm, Trắc nghiệm Đúng/Sai, Tự luận)" },
      difficulty: { type: Type.STRING, description: "Mức độ (ví dụ: Nhận biết, Vận dụng)" },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Danh sách lựa chọn. Nếu TN 4 chọn 1: 4 đáp án. Nếu Đúng/Sai: 4 mệnh đề."
      },
      correctAnswer: { type: Type.STRING, description: "Đáp án đúng. Nếu Đúng/Sai, trả về chuỗi mô tả trạng thái (VD: a-Đ, b-S, c-Đ, d-S)." },
      solution: { type: Type.STRING, description: "Hướng dẫn giải chi tiết (chứa LaTeX)" },
      hints: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "2 gợi ý sư phạm"
      },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "Tiêu đề bài thi" },
      objectives: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING }, 
        description: "Danh sách 3-5 mục tiêu kiến thức cần đạt" 
      },
      summary: { type: Type.STRING, description: "Tóm tắt ma trận đề" },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [];

    // Add uploaded file if exists
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    // Add text prompt
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel, // Sử dụng đúng biến smartModel
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as ExamMatrix;
    return data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate exam. Please check your API Key and try again.");
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const client = createClient();
  // Cập nhật model name chính xác theo hướng dẫn
  const smartModel = "gemini-3-pro-preview";

  let promptText = `
    Bạn là một giảng viên đại học xuất sắc và chuyên gia sư phạm.
    Hãy soạn một bài giảng tóm tắt kiến thức trọng tâm (Lecture Notes) theo phong cách Slide thuyết trình.
    Môn: ${config.subject}, ${config.grade}.
    Chủ đề: "${config.topic}".
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Dựa trên TÀI LIỆU ĐÍNH KÈM (Hình ảnh/PDF) mà tôi cung cấp.
    Hãy phân tích nội dung trong đó để tóm tắt lý thuyết và tạo ra các ví dụ minh họa tương tự.
    Nội dung bài giảng phải bám sát tài liệu được cung cấp.
    `;
  }

  promptText += `
    Yêu cầu ĐẶC BIỆT cho chế độ SLIDE TRÌNH CHIẾU:
    1. Chia nội dung thành các mục rõ ràng.
    2. Trong phần 'content' (Lý thuyết): 
       - TUYỆT ĐỐI KHÔNG viết đoạn văn dài.
       - Chỉ sử dụng các gạch đầu dòng (bullet points) ngắn gọn.
       - QUAN TRỌNG: BẮT BUỘC dùng ký tự "★" (Ngôi sao) hoặc "•" (Chấm tròn) ở đầu mỗi ý. 
       - TUYỆT ĐỐI KHÔNG dùng dấu gạch ngang "-" làm đầu dòng vì sẽ gây nhầm lẫn nghiêm trọng với dấu trừ trong công thức toán học.
       - BẮT BUỘC dùng ký tự xuống dòng (\n) giữa các ý chính. Mỗi gạch đầu dòng phải nằm trên một dòng riêng biệt.
       - Mỗi ý phải súc tích, đi thẳng vào định nghĩa hoặc công thức.
       - Giới hạn nội dung để hiển thị vừa vặn trên 1 slide cỡ chữ lớn.
    3. Phần ví dụ minh họa: Chọn 1 ví dụ điển hình nhất cho mỗi mục lý thuyết.
    4. ĐỊNH DẠNG QUAN TRỌNG (Highlight):
       - Bắt buộc sử dụng dấu ** (markdown bold) bao quanh các TỪ KHÓA, ĐỊNH NGHĨA QUAN TRỌNG, TÊN ĐỊNH LÝ, và CÔNG THỨC GỐC. 
    5. ĐỊNH DẠNG TOÁN HỌC: Bắt buộc dùng LaTeX trong dấu $ cho mọi biểu thức toán học.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  const studyGuideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING, description: "Tên chủ đề chính (viết hoa)" },
      overview: { type: Type.STRING, description: "Giới thiệu tổng quan về chủ đề ngắn gọn (1-2 câu)" },
      sections: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Tiêu đề Slide (Ví dụ: 1. Định lý Pytago)" },
            content: { type: Type.STRING, description: "Nội dung tóm tắt dạng gạch đầu dòng (Bắt đầu bằng ★ hoặc •), chứa LaTeX" },
            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING, description: "Đề bài ví dụ (chứa LaTeX)" },
                  solution: { type: Type.STRING, description: "Lời giải ngắn gọn (chứa LaTeX)" },
                  explanation: { type: Type.STRING, description: "Giải thích mấu chốt" }
                },
                required: ["problem", "solution", "explanation"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "overview", "sections"]
  };

  try {
    const parts: any[] = [];

    // Add uploaded file if exists
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    // Add text prompt
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel, // Sử dụng đúng biến smartModel
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.5,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as StudyGuideData;
    return data;
  } catch (error) {
    console.error("Gemini API Error (Study Guide):", error);
    throw new Error("Failed to generate study guide.");
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
