                {/* Navigation Arrows */}
                <button 
                    onClick={(e) => { e.stopPropagation(); prevSlide(); }} 
                    disabled={currentSlide === 0}
                    className="fixed left-6 top-1/2 -translate-y-1/2 p-4 rounded-full bg-slate-100/50 hover:bg-white dark:bg-slate-800/50 dark:hover:bg-slate-700 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-lg border border-slate-200/50 dark:border-slate-700/50 z-[60]"
                >
                    <ChevronLeft className="w-8 h-8" />
                </button>
                <button 
                    onClick={(e) => { e.stopPropagation(); nextSlide(); }} 
                    disabled={currentSlide === questions.length - 1}
                    className={`fixed top-1/2 -translate-y-1/2 p-4 rounded-full bg-slate-100/50 hover:bg-white dark:bg-slate-800/50 dark:hover:bg-slate-700 text-slate-500 hover:text-indigo-600 dark:text-slate-400 dark:hover:text-indigo-400 backdrop-blur-md transition-all disabled:opacity-0 shadow-lg border border-slate-200/50 dark:border-slate-700/50 z-[60]
                        ${showBlackboard && blackboardMode === 'side' ? 'right-[calc(50vw+24px)]' : 'right-6'}
