// --- Audio Helpers ---

// Create a reusable AudioContext (singleton pattern)
let audioCtx: AudioContext | null = null;

const getAudioContext = () => {
    if (!audioCtx) {
        audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtx;
};

// Helper to resume audio context on user interaction (browser policy)
const resumeAudioContext = () => {
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') {
        ctx.resume();
    }
};

const playTickSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    // Sharp tick sound
    osc.type = 'square';
    osc.frequency.setValueAtTime(1000, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.05);
    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);

    osc.start();
    osc.stop(ctx.currentTime + 0.05);
};

const playAlarmSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;

    const now = ctx.currentTime;
    const playRing = (time: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(800, time);
        osc.frequency.exponentialRampToValueAtTime(600, time + 0.5);
        gain.gain.setValueAtTime(0.2, time);
        gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);
        osc.start(time);
        osc.stop(time + 0.5);
    };
    playRing(now);
    playRing(now + 0.4);
    playRing(now + 0.8);
};

// WIN SOUND (Applause/Happy Jingle) - Major Arpeggio
const playWinSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;

    const playNote = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.type = 'sine'; // Smooth tone
        osc.frequency.setValueAtTime(freq, startTime);
        gain.gain.setValueAtTime(0, startTime);
        gain.gain.linearRampToValueAtTime(0.2, startTime + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);

        osc.start(startTime);
        osc.stop(startTime + duration);
    };

    // C Major Arpeggio (Happy sound)
    playNote(523.25, now, 0.3); // C5
    playNote(659.25, now + 0.1, 0.3); // E5
    playNote(783.99, now + 0.2, 0.3); // G5
    playNote(1046.50, now + 0.3, 0.6); // C6 (High C)
};

// LOSE SOUND (Disappointed) - Descending Tritone / Sawtooth
const playLoseSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;

    const playTone = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.type = 'sawtooth'; // Rough tone
        osc.frequency.setValueAtTime(freq, startTime);
        osc.frequency.linearRampToValueAtTime(freq - 100, startTime + duration); // Slide down

        gain.gain.setValueAtTime(0.15, startTime);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);

        osc.start(startTime);
        osc.stop(startTime + duration);
    };

    // Sad trombone effect
    playTone(400, now, 0.4);
    playTone(290, now + 0.35, 0.8);
};


export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  // Local state for questions to allow deletion/modification
  const [questions, setQuestions] = useState<Question[]>(data.questions);

  const [showAnswers, setShowAnswers] = useState(false);
  const [activeHints, setActiveHints] = useState<Record<number, boolean>>({});
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [isExporting, setIsExporting] = useState(false);
  const [showNav, setShowNav] = useState(false); 
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);

  // Timer State
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  // TTS State
  const [speakingId, setSpeakingId] = useState<number | null>(null);
  const [currentVoiceIndex, setCurrentVoiceIndex] = useState(0); 

  // Edit Mode State
  const [isEditMode, setIsEditMode] = useState(false);

  // Presentation Mode State
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideDirection, setSlideDirection] = useState<'next' | 'prev'>('next');
  const [zoomLevel, setZoomLevel] = useState(1); 
  const [isLaserPointer, setIsLaserPointer] = useState(false);

  // Student Practice State
  const [studentName, setStudentName] = useState('');
  const [isStarted, setIsStarted] = useState(false);
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({}); // Changed to 'any' to support T/F object
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Sync state with props when data changes
  useEffect(() => {
    setQuestions(data.questions);
    setUserAnswers({});
    setIsSubmitted(false);
    setShowScoreModal(false);
    setShowAnswers(false);
    setStudentName('');
    setIsStarted(false);
    setCurrentSlide(0);
    setViewMode('list');
    setIsEditMode(false);
    setSpeakingId(null);
    setTimer(null);
    setIsTimerRunning(false);
    window.speechSynthesis.cancel();
  }, [data]);

  // Clean up speech on unmount
  useEffect(() => {
    return () => {
      window.speechSynthesis.cancel();
    };
  }, []);

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => {
          if (prev === null) return null;
          const nextVal = prev - 1;

          // Sound effects for last 10 seconds
          if (nextVal <= 10 && nextVal > 0) {
              playTickSound();
          } else if (nextVal === 0) {
              playAlarmSound();
              setIsTimerRunning(false);
          }

          return nextVal;
        });
      }, 1000);
    } else if (timer === 0) {
        setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  // Close timer menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showTimerMenu && !target.closest('.timer-container')) {
        setShowTimerMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showTimerMenu]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isStarted) return;
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight' || e.key === ' ') {
          nextSlide();
        } else if (e.key === 'ArrowLeft') {
          prevSlide();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentSlide, questions.length, isStarted]);

  // Close nav when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (showNav && !target.closest('.nav-dock-container') && !target.closest('.nav-toggle-btn')) {
        setShowNav(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showNav]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) {
        containerRef.current.requestFullscreen().catch((err) => {
          console.error(`Error attempting to enable full-screen mode: ${err.message}`);
        });
      }
    } else {
      document.exitFullscreen();
    }
  };

  const nextSlide = () => {
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (currentSlide < questions.length - 1) {
      setSlideDirection('next');
      setCurrentSlide(prev => prev + 1);
      if (!showAnswers) setActiveSolutions({});
    }
  };

  const prevSlide = () => {
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (currentSlide > 0) {
      setSlideDirection('prev');
      setCurrentSlide(prev => prev - 1);
    }
  };

  const jumpToQuestion = (idx: number) => {
    if (speakingId !== null) {
        window.speechSynthesis.cancel();
        setSpeakingId(null);
    }

    if (viewMode === 'slide') {
      setSlideDirection(idx > currentSlide ? 'next' : 'prev');
      setCurrentSlide(idx);
    } else {
      const element = document.getElementById(`question-${idx}`);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    setShowNav(false);
  };

  const toggleHint = (id: number) => {
    setActiveHints(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleSolution = (id: number) => {
    setActiveSolutions(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleStartExam = () => {
      if (studentName.trim()) {
          setIsStarted(true);
          resumeAudioContext(); // Enable audio context on user gesture
      }
  };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return;

    // Resume audio context just in case (browser policy)
    resumeAudioContext();

    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: optionIdx
    }));
    setTimer(null);
    setIsTimerRunning(false);

    // Play Sound immediately
    const q = questions[questionIdx];
    const label = ['A', 'B', 'C', 'D'][optionIdx];
    const isCorrect = q.correctAnswer.trim().toUpperCase().startsWith(label);
    if (isCorrect) playWinSound();
    else playLoseSound();
  };

  const handleTFSelect = (questionIdx: number, optionIdx: number, isTrue: boolean) => {
    if (isSubmitted || isEditMode) return;

    resumeAudioContext();

    setUserAnswers(prev => {
        const currentAnswer = prev[questionIdx] || {};
        return {
            ...prev,
            [questionIdx]: { ...currentAnswer, [optionIdx]: isTrue }
        };
    });
    setTimer(null);
    setIsTimerRunning(false);

    // Play sound for individual T/F selection
    const q = questions[questionIdx];
    const label = ['a', 'b', 'c', 'd'][optionIdx];
    const cleanCorrect = q.correctAnswer.toLowerCase();
    const regexTrue = new RegExp(`${label}[).:-]?\\s*(đúng|đ|true|t)`, 'i');
    const regexFalse = new RegExp(`${label}[).:-]?\\s*(sai|s|false|f)`, 'i');
    const expectTrue = regexTrue.test(cleanCorrect);
    const expectFalse = regexFalse.test(cleanCorrect);

    let isSubCorrect = false;
    if (expectTrue && isTrue) isSubCorrect = true;
    else if (expectFalse && !isTrue) isSubCorrect = true;

    if (isSubCorrect) playWinSound();
    else playLoseSound();
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode) return;
    if (value.length > 4) return;
    setUserAnswers(prev => ({
      ...prev,
      [questionIdx]: value.toUpperCase() 
    }));

    if (isTimerRunning && value.length > 0) {
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const handleDeleteQuestion = (idxToDelete: number) => {
    if (!window.confirm(`Bạn có chắc chắn muốn xóa Câu ${idxToDelete + 1} không?`)) {
        return;
    }
    const newQuestions = questions.filter((_, idx) => idx !== idxToDelete);
    setQuestions(newQuestions);

    if (viewMode === 'slide') {
        if (currentSlide === idxToDelete) {
            if (currentSlide >= newQuestions.length) {
                setCurrentSlide(Math.max(0, newQuestions.length - 1));
            }
        } else if (currentSlide > idxToDelete) {
            setCurrentSlide(c => Math.max(0, c - 1));
        }
    } else {
         if (currentSlide >= newQuestions.length) {
            setCurrentSlide(Math.max(0, newQuestions.length - 1));
         }
    }

    setUserAnswers(prevAnswers => {
        const newAnswers: Record<number, any> = {};
        Object.keys(prevAnswers).forEach(keyStr => {
            const key = parseInt(keyStr);
            if (key < idxToDelete) {
                newAnswers[key] = prevAnswers[key];
            } else if (key > idxToDelete) {
                newAnswers[key - 1] = prevAnswers[key];
            }
        });
        return newAnswers;
    });

    setIsSubmitted(false);
  };

  const handleSpeak = (question: Question) => {
    window.speechSynthesis.cancel();

    if (speakingId === question.id) {
        setSpeakingId(null);
        return;
    }

    let textToRead = question.content;
    textToRead = textToRead
        .replace(/\$\$[\s\S]*?\$\$/g, ', ') 
        .replace(/\$[^\$]*\$/g, ', ') 
        .replace(/\\\[[\s\S]*?\\\]/g, ', ')
        .replace(/\\\([\s\S]*?\\\)/g, ', ')
        .replace(/\*\*/g, '')
        .replace(/_+/g, ''); 

    if (question.type === QuestionType.MULTIPLE_CHOICE) {
        const randomPrompt = MCQ_PROMPTS[Math.floor(Math.random() * MCQ_PROMPTS.length)];
        textToRead += `. ${randomPrompt}`;
    }

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN'; 
    const randomProfileIndex = Math.floor(Math.random() * VOICE_PROFILES.length);
    const selectedProfile = VOICE_PROFILES[randomProfileIndex];
    setCurrentVoiceIndex(randomProfileIndex);

    utterance.rate = selectedProfile.rate;
    utterance.pitch = selectedProfile.pitch;

    utterance.onend = () => setSpeakingId(null);
    utterance.onerror = () => setSpeakingId(null);

    setSpeakingId(question.id);
    window.speechSynthesis.speak(utterance);
  };

  const startTimer = (minutes: number) => {
      setTimer(minutes * 60);
      setIsTimerRunning(true);
      setShowTimerMenu(false);
  };

  const formatTime = (seconds: number) => {
      const m = Math.floor(seconds / 60);
      const s = seconds % 60;
      return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const handleSubmitExam = () => {
    const answeredCount = Object.keys(userAnswers).length;
    if (answeredCount < questions.length) {
      if (!confirm(`Bạn mới làm ${answeredCount}/${questions.length} câu. Bạn có chắc chắn muốn nộp bài để xem tổng kết không?`)) {
        return;
      }
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    setShowAnswers(true);
  };

  const calculateScore = () => {
    let correctCount = 0;
    const totalQuestions = questions.length;
    const answeredCount = Object.keys(userAnswers).length;

    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];

      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options && typeof userAns === 'number') {
             const selectedLabel = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.trim().toUpperCase().startsWith(selectedLabel)) {
                correctCount++;
             }
          } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
             const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
             const cleanUser = userAns.trim().toUpperCase();
             if (cleanUser && cleanCorrect === cleanUser) {
                 correctCount++;
             }
          } else if (q.type === QuestionType.TRUE_FALSE && typeof userAns === 'object') {
             const cleanCorrect = q.correctAnswer.toLowerCase();
             let isAllCorrect = true;

             ['a', 'b', 'c', 'd'].forEach((key, optIdx) => {
                 const isUserTrue = userAns[optIdx] === true;

                 if (userAns[optIdx] === undefined) {
                     isAllCorrect = false;
                     return;
                 }

                 const regexTrue = new RegExp(`${key}[).:-]?\\s*(đúng|đ|true|t)`, 'i');
                 const regexFalse = new RegExp(`${key}[).:-]?\\s*(sai|s|false|f)`, 'i');

                 const expectTrue = regexTrue.test(cleanCorrect);
                 const expectFalse = regexFalse.test(cleanCorrect);

                 if (expectTrue && !isUserTrue) isAllCorrect = false;
                 if (expectFalse && isUserTrue) isAllCorrect = false;
                 if (!expectTrue && !expectFalse) isAllCorrect = false; 
             });

             if (isAllCorrect) correctCount++;
          }
      }
    });

    return {
        correct: correctCount,
        answered: answeredCount,
        total: totalQuestions,
        score: totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 10 * 100) / 100 : 0
    };
  };

  const getFeedback = (score: number) => {
    let medal = null;
    if (score >= 9) medal = <Medal className="w-16 h-16 text-yellow-400 drop-shadow-lg" />; // Gold
    else if (score >= 7) medal = <Medal className="w-16 h-16 text-slate-400 drop-shadow-lg" />; // Silver
    else if (score >= 5) medal = <Medal className="w-16 h-16 text-amber-600 drop-shadow-lg" />; // Bronze

    if (score === 10) return { text: "Tuyệt đối! Em là thiên tài!", color: "text-purple-600 dark:text-purple-400", emoji: <PartyPopper className="w-12 h-12 text-purple-500 animate-bounce" />, medal };
    if (score >= 9) return { text: "Xuất sắc! Em là niềm tự hào của lớp!", color: "text-emerald-600 dark:text-emerald-400", emoji: <Trophy className="w-12 h-12 text-yellow-400" />, medal };
    if (score >= 8) return { text: "Rất tốt! Giữ vững phong độ nhé!", color: "text-blue-600 dark:text-blue-400", emoji: <Star className="w-12 h-12 text-blue-400 fill-current" />, medal };
    if (score >= 6.5) return { text: "Khá tốt! Cần cẩn thận hơn một chút.", color: "text-indigo-600 dark:text-indigo-400", emoji: <Smile className="w-12 h-12 text-indigo-400" />, medal };
    if (score >= 5) return { text: "Đạt yêu cầu. Cần ôn tập kỹ hơn các câu sai.", color: "text-amber-600 dark:text-amber-400", emoji: <Award className="w-12 h-12 text-amber-400" />, medal };
    return { text: "Cần cố gắng nhiều hơn. Đừng nản chí!", color: "text-red-600 dark:text-red-400", emoji: <Frown className="w-12 h-12 text-red-400" />, medal: null };
  };

  // ... (Print and Export functions remain the same) ...
  const handlePrintStudent = () => { document.body.classList.add('printing-student'); window.print(); setTimeout(() => { document.body.classList.remove('printing-student'); }, 500); };
  const handlePrintTeacher = () => { if (!showAnswers && confirm('Bạn có muốn bật hiện đáp án trước khi in lời giải không?')) { setShowAnswers(true); setTimeout(() => window.print(), 100); return; } window.print(); };
  const handleExportJSON = () => { const exportData = { type: 'exam', timestamp: Date.now(), config, data: { ...data, questions } }; const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' }); const saveFunc = (FileSaver as any).saveAs || FileSaver; saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.json`); };

  // Helper to parse content mixed with LaTeX ($...$) and Bold (**...**) into Docx Paragraph Children
  const parseContentToDocx = (content: string) => {
      // Split by LaTeX delimiters ($...$) AND Bold delimiters (**...**)
      const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);
      return parts.filter(part => part !== '').map((part) => {
          if (part.startsWith('$') && part.endsWith('$')) {
              const cleanMath = part.slice(1, -1).trim();
              return new DocxMath({ children: [new MathRun(cleanMath)] });
          } else if (part.startsWith('**') && part.endsWith('**')) {
              return new TextRun({ text: part.slice(2, -2), bold: true, size: 24 });
          } else {
              return new TextRun({ text: part, size: 24 });
          }
      });
  };

  const handleDownloadWord = async () => {
      setIsExporting(true);
      try {
        const docQuestions = questions.flatMap((q, index) => {
          const questionParagraph = new Paragraph({ 
              children: [
                  new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 24 }),
                  ...parseContentToDocx(q.content)
              ],
              spacing: { after: 150 } 
          });

          const parts = [questionParagraph];

          if (q.type === QuestionType.MULTIPLE_CHOICE && q.options) {
            q.options.forEach((opt, idx) => {
              const label = ['A', 'B', 'C', 'D'][idx];
              let cleanOpt = opt.replace(/^[A-D][\.\)\s]+/, '').trim();
              parts.push(new Paragraph({ children: [new TextRun({ text: `${label}. `, bold: true, size: 24 }), ...parseContentToDocx(cleanOpt)], indent: { left: 720 }, spacing: { after: 50 } }));
            });
          }

          if (q.type === QuestionType.TRUE_FALSE && q.options) {
              const table = new Table({
                  width: { size: 100, type: WidthType.PERCENTAGE },
                  borders: {
                        top: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                        bottom: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                        left: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                        right: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                        insideHorizontal: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                        insideVertical: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
                  },
                  rows: [
                      new TableRow({ children: [
                          new TableCell({ children: [new Paragraph({ text: "Mệnh đề", bold: true })] }),
                          new TableCell({ children: [new Paragraph({ text: "Đúng / Sai", bold: true, alignment: AlignmentType.CENTER })], width: { size: 20, type: WidthType.PERCENTAGE } }),
                      ]}),
                      ...q.options.map(opt => new TableRow({
                          children: [
                              new TableCell({ children: [new Paragraph({ children: parseContentToDocx(opt) })] }),
                              new TableCell({ children: [new Paragraph({ text: "[ ] Đ   [ ] S", alignment: AlignmentType.CENTER })] })
                          ]
                      }))
                  ]
              });
              parts.push(table);
              parts.push(new Paragraph({ text: "", spacing: { after: 200 } })); // Spacer
          }

          if (q.type === QuestionType.ESSAY) {
              parts.push(new Paragraph({ children: [new TextRun({ text: "Trả lời: [  ] [  ] [  ] [  ]", font: "Courier New", size: 28 })], spacing: { before: 200, after: 200 } }));
          }

          parts.push(
              new Paragraph({ children: [new TextRun({ text: "Lời giải", bold: true, size: 22, underline: { type: UnderlineType.SINGLE, color: "000000" } })], spacing: { before: 200 } }),
              new Paragraph({ children: [new TextRun({ text: "Đáp án đúng: ", bold: true, color: "008000", size: 24 }), ...parseContentToDocx(q.correctAnswer)] }),
              new Paragraph({ children: parseContentToDocx(q.solution), spacing: { after: 400 } })
          );
          return parts;
        });

        const doc = new Document({
          creator: "Trợ Lý Luyện Thi Thông Minh", title: `${config.subject} - ${config.grade}`,
          sections: [{ 
            headers: { default: new Header({ children: [new Paragraph({ children: [new TextRun({ text: "Thầy Vũ Tiến Lực - Trường THPT Nguyễn Hữu Cảnh", bold: true, size: 20 }), new TextRun({ text: "\t" }), new TextRun({ children: ["Trang ", PageNumber.CURRENT], size: 20 })], tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }] })] }) },
            properties: {}, 
            children: [new Paragraph({ text: "PHIẾU LUYỆN TẬP", heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }), new Paragraph({ text: `Môn: ${config.subject} | ${config.grade}`, heading: HeadingLevel.HEADING_2, alignment: AlignmentType.CENTER }), new Paragraph({ text: `Chủ đề: ${config.topic}`, alignment: AlignmentType.CENTER, spacing: { after: 400 } }), ...docQuestions] 
          }],
        });
        const blob = await Packer.toBlob(doc);
        const saveFunc = (FileSaver as any).saveAs || FileSaver;
        saveFunc(blob, `De_Luyen_Tap_${config.subject}_${Date.now()}.docx`);
      } catch (e) { console.error(e); alert("Có lỗi khi tạo file Word."); } finally { setIsExporting(false); }
  };

  const results = calculateScore();
  const feedback = getFeedback(results.score);

  const renderQuestionCard = (q: Question, idx: number, isSlideMode: boolean) => {
    const isAnswered = userAnswers[idx] !== undefined;
    const userAns = userAnswers[idx];
    let isCorrect = false;

    // Determine correctness for badge logic (simplified for badge)
    if (isAnswered) {
        if (q.type === QuestionType.MULTIPLE_CHOICE && typeof userAns === 'number') {
            const label = ['A', 'B', 'C', 'D'][userAns];
            isCorrect = q.correctAnswer.trim().toUpperCase().startsWith(label);
        } else if (q.type === QuestionType.ESSAY && typeof userAns === 'string') {
            const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
            const cleanUser = userAns.trim().toUpperCase();
            isCorrect = (cleanUser !== '' && cleanCorrect === cleanUser);
        } else if (q.type === QuestionType.TRUE_FALSE && typeof userAns === 'object') {
             const cleanCorrect = q.correctAnswer.toLowerCase();
             let allSubCorrect = true;
             ['a', 'b', 'c', 'd'].forEach((key, optIdx) => {
                 const isUserTrue = userAns[optIdx] === true;
                 const regexTrue = new RegExp(`${key}[).:-]?\\s*(đúng|đ|true|t)`, 'i');
                 const regexFalse = new RegExp(`${key}[).:-]?\\s*(sai|s|false|f)`, 'i');
                 const expectTrue = regexTrue.test(cleanCorrect);
                 const expectFalse = regexFalse.test(cleanCorrect);
                 if ((expectTrue && !isUserTrue) || (expectFalse && isUserTrue) || (!expectTrue && !expectFalse)) allSubCorrect = false;
             });
             isCorrect = allSubCorrect;
        }
    }

    const canViewSolution = showAnswers || isAnswered || isSubmitted;
    const scaleStyle = { fontSize: `${zoomLevel * 100}%` };
    const zoomEffectClass = (isSlideMode && isFullscreen) ? 'scale-105 origin-top' : 'scale-100 origin-top';

    return (
        <div 
          id={`question-${idx}`}
          key={`${q.id}-${idx}`} 
          className={`print-break-inside-avoid bg-white dark:bg-slate-800 shadow-xl border relative overflow-hidden transition-all duration-300
             ${isSlideMode ? 'h-full flex flex-col p-4 md:p-8 rounded-none border-none shadow-none w-full animate-fade-in' : 'p-8 md:p-10 rounded-3xl mb-12'}
             ${!isSlideMode && (isAnswered || isSubmitted)
                ? (isCorrect ? 'border-emerald-200 dark:border-emerald-700 ring-2 ring-emerald-100 dark:ring-emerald-900/30' : 'border-red-200 dark:border-red-700 ring-2 ring-red-100 dark:ring-red-900/30')
                : (!isSlideMode ? 'border-slate-100 dark:border-slate-700' : '')
             }
             ${isEditMode ? 'ring-2 ring-dashed ring-slate-300 dark:ring-slate-600' : ''}
          `}
          style={scaleStyle}
        >
          {/* Watermark Number */}
          <div className="absolute top-0 right-0 p-4 opacity-10 font-black text-9xl text-slate-300 dark:text-slate-600 select-none pointer-events-none">
            {idx + 1}
          </div>

          {/* Absolute Top Right Timer Button for Slide Mode */}
          {isSlideMode && (
                <div className="absolute top-6 right-6 z-[60] timer-container">
                    <button
                        onClick={(e) => { e.stopPropagation(); setShowTimerMenu(!showTimerMenu); }}
                        className="p-3 rounded-full bg-slate-100/50 hover:bg-slate-200/80 dark:bg-slate-800/50 dark:hover:bg-slate-700/80 backdrop-blur-md text-slate-600 dark:text-slate-300 shadow-sm transition-all"
                        title="Hẹn giờ"
                    >
                        <Timer className="w-6 h-6" />
                    </button>
                    {/* Timer Menu Dropdown */}
                    {showTimerMenu && (
                        <div className="absolute top-full right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 p-2 w-32 animate-fade-in-up">
                            {[1, 2, 3, 5, 10].map(min => (
                                <button key={min} onClick={(e) => { e.stopPropagation(); startTimer(min); }} className="w-full text-left px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200">{min} Phút</button>
                            ))}
                        </div>
                    )}
                </div>
          )}

          {/* Question Content */}
          <div className={`flex flex-col h-full ${isSlideMode ? '' : 'gap-6'}`}>
              <div className={`relative z-10 ${isSlideMode ? 'mb-4 flex-shrink-0' : 'mb-2'} transition-transform duration-700 ease-out ${zoomEffectClass}`}>
                {!isSlideMode && (
                    <div className="flex items-center gap-3 mb-4">
                        <span className="flex items-center justify-center w-10 h-10 rounded-full bg-indigo-600 dark:bg-indigo-500 text-white font-bold text-lg shadow-md">{idx + 1}</span>
                        <span className="text-sm font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{q.difficulty}</span>
                        <button onClick={(e) => { e.stopPropagation(); handleSpeak(q); }} className={`p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors ${speakingId === q.id ? 'text-red-500 animate-pulse bg-red-50 dark:bg-red-900/30' : 'text-slate-400 hover:text-indigo-600'}`}>
                            {speakingId === q.id ? <StopCircle className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                        </button>
                    </div>
                )}

                <div className={`text-[1.5em] leading-tight text-slate-800 dark:text-slate-100 font-medium ${isSlideMode ? 'text-[1.8em]' : ''}`}>
                  {isSlideMode && (
                     <div className="flex items-center gap-3 mb-2">
                        <span className="text-indigo-600 dark:text-indigo-400 font-bold">Câu {idx + 1}:</span>
                        <span className="text-base font-semibold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 align-middle">{q.difficulty}</span>
                        <button onClick={(e) => { e.stopPropagation(); handleSpeak(q); }} className={`p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors ml-2 ${speakingId === q.id ? 'text-red-500 animate-pulse bg-red-50 dark:bg-red-900/30' : 'text-slate-400 hover:text-indigo-600'}`}>
                            {speakingId === q.id ? <StopCircle className="w-6 h-6" /> : VOICE_PROFILES[currentVoiceIndex].icon}
                        </button>
                     </div>
                  )}
                  <MathRenderer content={q.content} />
                </div>
              </div>

              {/* Options */}
              <div className={isSlideMode ? 'flex-grow overflow-y-auto pr-2 pb-40 px-2' : ''}>

                {/* --- MULTIPLE CHOICE --- */}
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                    <div className={`grid grid-cols-1 md:grid-cols-2 gap-5 mt-2`}>
                    {q.options.map((opt, optIdx) => {
                        const label = ['A', 'B', 'C', 'D'][optIdx];
                        const cleanContent = opt.replace(/^[A-D][\.\)\s]+/, '').trim().replace(/\*\*/g, '');
                        const theme = OPTION_THEMES[optIdx % 4];
                        const isSelected = userAns === optIdx;
                        const isCorrectAnswer = q.correctAnswer.trim().toUpperCase().startsWith(label);

                        let stateStyles = `border-2 ${theme.bg} ${theme.border} ${theme.text}`;
                        if (!isAnswered && !isSubmitted) {
                            stateStyles = `${theme.bg} ${theme.border} ${theme.text} ${theme.hover} hover:scale-[1.01] cursor-pointer`;
                        } else {
                            if (isCorrectAnswer) stateStyles = `bg-emerald-100 dark:bg-emerald-900/30 border-emerald-500 dark:border-emerald-500 text-emerald-900 dark:text-emerald-200 ring-2 ring-emerald-200 dark:ring-emerald-800`;
                            else if (isSelected && !isCorrectAnswer) stateStyles = `bg-red-100 dark:bg-red-900/30 border-red-500 dark:border-red-500 text-red-900 dark:text-red-200 opacity-80`;
                            else stateStyles = `${theme.bg} border-transparent opacity-50 grayscale`;
                        }
                        if (isEditMode) stateStyles = `${theme.bg} ${theme.border} ${theme.text} opacity-80 cursor-not-allowed`;

                        return (
                        <div key={optIdx} onClick={() => handleOptionSelect(idx, optIdx)} className={`relative group flex items-start gap-4 p-5 rounded-2xl transition-all duration-200 text-[1.2em] leading-snug ${stateStyles}`}>
                            <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-lg font-bold text-xl transition-colors ${(isAnswered || isSubmitted) && isCorrectAnswer ? 'bg-emerald-500 text-white' : ''} ${(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer ? 'bg-red-500 text-white' : ''} ${(!isAnswered && !isSubmitted) ? (theme.labelBg + ' ' + theme.text) : (!isCorrectAnswer && !isSelected ? 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400' : '')}`}>{label}.</div>
                            <div className="flex-grow pt-1"><MathRenderer content={cleanContent} /></div>
                            {(isAnswered || isSubmitted) && isCorrectAnswer && <CheckCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-emerald-600 dark:text-emerald-400" />}
                            {(isAnswered || isSubmitted) && isSelected && !isCorrectAnswer && <XCircle className="absolute top-1/2 right-4 -translate-y-1/2 w-8 h-8 text-red-500 dark:text-red-400" />}
                        </div>
                        );
                    })}
                    </div>
                )}

                {/* --- TRUE/FALSE --- */}
                {q.type === QuestionType.TRUE_FALSE && q.options && (
                    <div className="mt-4 space-y-4">
                        <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                            <table className="w-full">
                                <thead>
                                    <tr className={`text-left text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-700 ${isSlideMode ? 'text-2xl' : 'text-sm'}`}>
                                        <th className="pb-4 font-bold pl-2">Mệnh đề</th>
                                        <th className="pb-4 font-bold w-48 text-center">Đúng / Sai</th>
                                    </tr>
                                </thead>
                                <tbody className={`divide-y divide-slate-200 dark:divide-slate-700`}>
                                    {q.options.map((opt, optIdx) => {
                                        const label = ['a', 'b', 'c', 'd'][optIdx];
                                        const userState = userAns ? userAns[optIdx] : undefined;

                                        // Determine correct state from correctAnswer string
                                        let correctState = null;
                                        if (isAnswered || isSubmitted) {
                                            const cleanCorrect = q.correctAnswer.toLowerCase();
                                            const regexTrue = new RegExp(`${label}[).:-]?\\s*(đúng|đ|true|t)`, 'i');
                                            const regexFalse = new RegExp(`${label}[).:-]?\\s*(sai|s|false|f)`, 'i');
                                            if (regexTrue.test(cleanCorrect)) correctState = true;
                                            else if (regexFalse.test(cleanCorrect)) correctState = false;
                                        }

                                        return (
                                            <tr key={optIdx} className="group hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
                                                <td className={`py-6 pl-2 pr-4 ${isSlideMode ? 'text-3xl leading-relaxed' : 'text-lg'}`}>
                                                    <div className="flex items-start gap-4">
                                                        <span className="font-bold text-indigo-600 dark:text-indigo-400 mt-1">{label})</span>
                                                        <div className="flex-1"><MathRenderer content={opt.replace(/^[a-d][).]\s*/, '')} inline={true} /></div>
                                                    </div>
                                                </td>
                                                <td className="py-6 align-top">
                                                    <div className="flex justify-center gap-4 mt-1">
                                                        {/* TRUE BUTTON */}
                                                        <button 
                                                            onClick={() => handleTFSelect(idx, optIdx, true)}
                                                            disabled={isSubmitted || isEditMode}
                                                            className={`
                                                                rounded-xl font-bold flex items-center justify-center transition-all border-2
                                                                ${isSlideMode ? 'w-16 h-16 text-2xl' : 'w-10 h-10'}
                                                                ${userState === true 
                                                                    ? 'bg-emerald-600 text-white border-emerald-600 shadow-md scale-110' 
                                                                    : 'bg-white dark:bg-slate-800 text-emerald-600 border-emerald-200 dark:border-emerald-800 hover:bg-emerald-50 dark:hover:bg-emerald-900/30'}
                                                                ${(isAnswered || isSubmitted) && correctState === true ? 'ring-4 ring-offset-2 ring-emerald-400 dark:ring-offset-slate-900' : ''}
                                                                ${(isAnswered || isSubmitted) && userState === true && correctState === false ? 'opacity-50 grayscale' : ''}
                                                            `}
                                                        >
                                                            Đ
                                                        </button>
                                                        {/* FALSE BUTTON */}
                                                        <button 
                                                            onClick={() => handleTFSelect(idx, optIdx, false)}
                                                            disabled={isSubmitted || isEditMode}
                                                            className={`
                                                                rounded-xl font-bold flex items-center justify-center transition-all border-2
                                                                ${isSlideMode ? 'w-16 h-16 text-2xl' : 'w-10 h-10'}
                                                                ${userState === false
                                                                    ? 'bg-red-600 text-white border-red-600 shadow-md scale-110' 
                                                                    : 'bg-white dark:bg-slate-800 text-red-600 border-red-200 dark:border-red-800 hover:bg-red-50 dark:hover:bg-red-900/30'}
                                                                ${(isAnswered || isSubmitted) && correctState === false ? 'ring-4 ring-offset-2 ring-red-400 dark:ring-offset-slate-900' : ''}
                                                                ${(isAnswered || isSubmitted) && userState === false && correctState === true ? 'opacity-50 grayscale' : ''}
                                                            `}
                                                        >
                                                            S
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* --- ESSAY --- */}
                {q.type === QuestionType.ESSAY && (
                    <div className="my-6">
                        <label className="block text-slate-500 dark:text-slate-400 font-bold text-sm mb-3 uppercase tracking-wider">Điền kết quả (Tối đa 4 ký tự):</label>
                        <div className="relative w-fit">
                            <input type="text" maxLength={4} value={typeof userAns === 'string' ? userAns : ''} onChange={(e) => handleEssayChange(idx, e.target.value)} disabled={isSubmitted || isEditMode} placeholder="____" className={`w-48 h-16 text-center text-4xl font-mono tracking-[0.3em] font-bold uppercase border-2 rounded-xl outline-none transition-all shadow-inner ${(isAnswered || isSubmitted) ? (isCorrect ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300' : 'border-red-500 bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300') : 'border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 dark:focus:ring-indigo-900/30'}`} />
                            {(isAnswered || isSubmitted) && <div className="absolute top-1/2 -right-10 -translate-y-1/2">{isCorrect ? <CheckCircle className="w-8 h-8 text-emerald-500 dark:text-emerald-400 animate-bounce" /> : <XCircle className="w-8 h-8 text-red-500 dark:text-red-400" />}</div>}
                        </div>
                    </div>
                )}

                {/* SLIDE MODE: Hints & Solution Buttons */}
                {isSlideMode && !showAnswers && (
                    <div className="mt-8 mb-8 flex flex-wrap gap-3 justify-center">
                        <button onClick={() => toggleHint(q.id)} className="px-6 py-3 rounded-full bg-indigo-100 hover:bg-indigo-200 dark:bg-indigo-900/50 dark:hover:bg-indigo-900 text-indigo-700 dark:text-indigo-300 font-bold text-lg flex items-center justify-center gap-2 transition-all shadow-sm border border-indigo-200 dark:border-indigo-800">
                            <Lightbulb className="w-5 h-5" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Gợi ý'}
                        </button>
                        <button onClick={() => { if(canViewSolution) toggleSolution(q.id); }} disabled={!canViewSolution} className={`px-6 py-3 rounded-full font-bold text-lg flex items-center justify-center gap-2 transition-all shadow-sm border ${canViewSolution ? 'bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-600 cursor-pointer' : 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 opacity-70 cursor-not-allowed'}`}>
                            {canViewSolution ? (activeSolutions[q.id] ? <EyeOff className="w-5 h-5"/> : <Key className="w-5 h-5"/>) : <Lock className="w-5 h-5"/>}
                            {canViewSolution ? (activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải') : 'Chọn đáp án để xem'}
                        </button>
                    </div>
                )}

                {/* --- TIMER SECTION (Big Display Only, Triggered from Top Right) --- */}
                {isSlideMode && isTimerRunning && timer !== null && (
                    <div className="flex flex-col items-center justify-center my-4 min-h-[100px] timer-container animate-fade-in-up">
                        <div className={`text-[6rem] leading-none font-black font-mono tracking-widest drop-shadow-lg transition-all select-none pointer-events-none ${timer && timer <= 10 ? 'text-red-600 animate-pulse scale-110 drop-shadow-[0_0_25px_rgba(220,38,38,0.8)]' : 'text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-violet-600 dark:from-blue-400 dark:to-violet-400'}`}>
                            {formatTime(timer)}
                        </div>
                    </div>
                )}

                {/* Hints Content */}
                {isSlideMode && activeHints[q.id] && q.hints && (
                    <div className="mt-6 mb-4 animate-fade-in-up">
                        <div className="bg-indigo-50 dark:bg-indigo-900/10 border-2 border-indigo-100 dark:border-indigo-900/50 rounded-3xl p-6 shadow-sm">
                             <ul className="list-disc list-inside space-y-3 pl-2 text-slate-700 dark:text-slate-200 text-xl leading-relaxed">
                                {q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}
                             </ul>
                        </div>
                    </div>
                )}

                {/* Solution Content */}
                {isSlideMode && (showAnswers || activeSolutions[q.id]) && (
                    <div className="mt-6 mb-12 animate-fade-in-up">
                        <div className="bg-emerald-50 dark:bg-emerald-900/10 border-2 border-emerald-100 dark:border-emerald-900/50 rounded-3xl p-6 md:p-8 shadow-sm">
                            <h4 className="font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-3 mb-6 pb-4 border-b border-emerald-200 dark:border-emerald-800/50"><CheckCircle className="w-8 h-8 fill-current" /> Lời giải chi tiết</h4>
                            <div className="text-xl md:text-2xl text-slate-800 dark:text-slate-100 space-y-6 leading-relaxed">
                                <p className="font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-3">Đáp án đúng: <span className="bg-emerald-200 dark:bg-emerald-800 text-emerald-900 dark:text-white px-4 py-1 rounded-xl shadow-sm"><MathRenderer content={q.correctAnswer} /></span></p>
                                <div className="space-y-4">
                                    {q.solution.split('\n').filter(line => line.trim() !== '').map((line, i) => (
                                        <div key={i} className="flex items-start gap-4"><span className="text-emerald-500 mt-1.5 flex-shrink-0 text-xl">✦</span><div className="flex-1"><MathRenderer content={line} /></div></div>
                                    ))}
                                </div>
                            </div>
                            <div className="mt-8 flex justify-center"><button onClick={() => toggleSolution(q.id)} className="text-emerald-600 dark:text-emerald-400 hover:text-emerald-800 dark:hover:text-emerald-200 font-bold flex items-center gap-2 px-4 py-2 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 rounded-full transition-colors"><ChevronUp className="w-5 h-5" /> Thu gọn</button></div>
                        </div>
                    </div>
                )}

                 {/* Hints & Solutions (List Mode) */}
                 {!isSlideMode && (
                     <div className="space-y-2 text-base mt-6">
                        <div className="flex flex-wrap gap-2">
                            <button onClick={() => toggleHint(q.id)} className="font-medium text-indigo-600 dark:text-indigo-300 hover:text-indigo-800 dark:hover:text-indigo-200 flex items-center gap-2 px-4 py-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors"><Lightbulb className="w-5 h-5" /> {activeHints[q.id] ? 'Ẩn gợi ý' : 'Xem gợi ý'}</button>
                            {!showAnswers && (
                                canViewSolution ? (
                                    <button onClick={() => toggleSolution(q.id)} className="text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 flex items-center gap-1 px-4 py-2 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition-colors">{activeSolutions[q.id] ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}{activeSolutions[q.id] ? 'Ẩn lời giải' : 'Xem lời giải chi tiết'}</button>
                                ) : (<div className="text-sm text-slate-400 italic px-4 py-2 flex items-center gap-2"><EyeOff className="w-4 h-4" /> Trả lời để xem giải</div>)
                            )}
                        </div>
                         {activeHints[q.id] && q.hints && <div className="bg-indigo-50 dark:bg-indigo-900/20 p-6 rounded-2xl border border-indigo-100 dark:border-indigo-800 text-lg text-indigo-900 dark:text-indigo-200 animate-fade-in shadow-inner mt-2"><ul className="list-disc list-inside space-y-2 pl-2">{q.hints.map((h, i) => <li key={i}><MathRenderer content={h} /></li>)}</ul></div>}
                         {(showAnswers || activeSolutions[q.id]) && <div className="mt-4 p-6 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border-2 border-emerald-100 dark:border-emerald-800 text-emerald-900 dark:text-emerald-100 shadow-sm animate-fade-in"><h4 className="font-bold text-xl mb-3 flex items-center gap-2 border-b border-emerald-200 dark:border-emerald-700 pb-2"><CheckCircle className="w-6 h-6" /> Đáp án & Lời giải chi tiết</h4><p className="mb-4 font-bold text-2xl text-emerald-700 dark:text-emerald-400 flex items-center gap-2">Đáp án: <span className="px-3 py-1 bg-emerald-200 dark:bg-emerald-800 rounded-lg"><MathRenderer content={q.correctAnswer} /></span></p><div className="text-lg whitespace-pre-wrap leading-relaxed"><MathRenderer content={q.solution} inline={false} /></div></div>}
                     </div>
                 )}
              </div>

              {isSlideMode && (
                  <div className="mt-auto flex flex-col gap-4">
                        <div className="text-center pointer-events-none z-0 opacity-60 px-4 pb-2">
                            <p className="text-sm md:text-base font-serif italic text-slate-500 dark:text-slate-400">"{STUDY_QUOTES[currentSlide % STUDY_QUOTES.length]}"</p>
                        </div>
                  </div>
              )}
          </div>
        </div>
    );
  };

  if (questions.length === 0) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-8 text-center text-slate-500 dark:text-slate-400">
              <div className="bg-slate-100 dark:bg-slate-800 p-8 rounded-full mb-4">
                 <FileText className="w-12 h-12 text-slate-400 dark:text-slate-500" />
              </div>
              <h2 className="text-xl font-bold text-slate-700 dark:text-slate-200">Chưa có câu hỏi nào</h2>
              <p className="mb-6">Bạn đã xóa hết câu hỏi hoặc dữ liệu trống.</p>
              <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-bold">Tạo đề mới</button>
          </div>
      )
  }

  // LOGIN SCREEN
  if (!isStarted && !isSubmitted) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gradient-to-br from-indigo-50 to-blue-50 dark:from-slate-900 dark:to-slate-800">
              <div className="w-full max-w-md bg-white dark:bg-slate-800 rounded-3xl shadow-2xl p-8 border border-slate-200 dark:border-slate-700 animate-fade-in-up">
                  <div className="text-center mb-8">
                      <div className="inline-flex p-4 rounded-full bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 mb-4">
                          <User className="w-10 h-10" />
                      </div>
                      <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-2">Chào mừng bạn!</h2>
                      <p className="text-slate-500 dark:text-slate-400">Nhập tên của bạn để bắt đầu làm bài luyện tập.</p>
                  </div>

                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">Họ và tên</label>
                          <input 
                              type="text" 
                              value={studentName}
                              onChange={(e) => setStudentName(e.target.value)}
                              placeholder="Ví dụ: Nguyễn Văn A"
                              className="w-full px-4 py-3 rounded-xl border-2 border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all font-medium text-lg"
                              onKeyDown={(e) => { if(e.key === 'Enter' && studentName.trim()) handleStartExam(); }}
                          />
                      </div>
                      <button 
                          onClick={handleStartExam}
                          disabled={!studentName.trim()}
