                        <div className="flex gap-2">
                            <button onClick={() => setIsEditMode(!isEditMode)} className={`p-1 rounded-lg ${isEditMode ? 'bg-red-100 text-red-600' : 'hover:bg-slate-100 text-slate-500'}`} title="Chế độ chỉnh sửa (Xóa câu)">
                                <Edit className="w-4 h-4" />
                            </button>
                            <button onClick={() => setShowNav(false)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                                <X className="w-5 h-5 text-slate-400" />
                            </button>
                        </div>
                    </div>
                    <div className="grid grid-cols-5 gap-2 max-h-[50vh] overflow-y-auto custom-scrollbar p-1">
                        {questions.map((_, idx) => {
                            const isActive = idx === currentSlide;
                            const isAns = userAnswers[idx] !== undefined;
                            return (
                                <button
                                    key={idx}
                                    onClick={() => jumpToQuestion(idx)}
                                    className={`aspect-square rounded-lg font-bold text-sm transition-all shadow-sm border flex items-center justify-center relative
                                        ${isActive 
                                            ? 'bg-indigo-600 text-white ring-2 ring-indigo-300' 
                                            : (isAns ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800' : 'bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-600 border-transparent')}
                                    `}
                                >
                                    {idx + 1}
                                    {isEditMode && <span className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border border-white"></span>}
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}
       </div>

       {/* Modals */}
       {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
       {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
       {showScoreModal && isSubmitted && (
           <div className="fixed inset-0 z-[70] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowScoreModal(false)}>
               <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-lg w-full transform scale-100 animate-fade-in-up text-center" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-center mb-4">{feedback.emoji}</div>
                    {feedback.medal && <div className="flex justify-center mb-6 animate-bounce scale-150">{feedback.medal}</div>}

                    <h3 className={`text-4xl font-black mb-2 ${feedback.color}`}>{results.score} điểm</h3>
                    <p className="text-xl font-bold text-slate-700 dark:text-slate-200 mb-2">{feedback.text}</p>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Bạn đã trả lời đúng {results.correct}/{results.total} câu.</p>
                    <div className="flex gap-4 justify-center">
                        <button onClick={() => setShowScoreModal(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 rounded-xl font-bold text-slate-700 dark:text-slate-200">Xem lại bài</button>
                        <button onClick={() => { setIsSubmitted(false); setUserAnswers({}); setShowScoreModal(false); window.scrollTo(0,0); }} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold">Làm lại</button>
                    </div>
               </div>
           </div>
       )}

    </div>
  );
};

