// Color Themes configuration
const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc',
    bg: 'bg-teal-50 dark:bg-slate-900', 
    text: 'text-slate-800 dark:text-slate-100',
    primary: 'text-teal-700 dark:text-teal-400', 
