                            <Dices className="w-5 h-5" />
                        </button>
                         {/* Submit Button in Dock (if started) */}
                         {isStarted && !isSubmitted && (
                            <button onClick={handleSubmitExam} className="p-3 rounded-full bg-emerald-600 hover:bg-emerald-500 text-white shadow-lg ml-2 animate-pulse font-bold" title="Nộp bài">
                                <Send className="w-5 h-5" />
                            </button>
                        )}
                        <div className="w-px h-6 bg-white/20 mx-1"></div>
                        <button onClick={(e) => { e.stopPropagation(); setIsDockExpanded(false); setShowNav(false); }} className="p-3 rounded-full hover:bg-white/10 text-slate-300 hover:text-white transition-colors">
                            <ChevronDown className="w-5 h-5" />
                        </button>
                    </>
                ) : (
                    <div className="flex items-center gap-2 font-bold text-sm"><Menu className="w-5 h-5" /></div>
                )}
            </div>
        </div>

        {/* MODALS */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}

        {/* SCORE MODAL */}
        {showScoreModal && (
            <div className="fixed inset-0 z-[70] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-2xl max-w-lg w-full p-8 text-center relative overflow-hidden border border-slate-200 dark:border-slate-700 animate-fade-in-up">
                    <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>
                    <div className="mb-6 flex justify-center">{feedback.emoji}</div>
                    <h2 className={`text-4xl font-black mb-2 ${feedback.color}`}>{results.score} / 10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-medium mb-6">Điểm số của bạn: {results.correct} / {results.total} câu đúng</p>

                    <div className="bg-slate-50 dark:bg-slate-900 rounded-2xl p-6 mb-8 border border-slate-100 dark:border-slate-700">
                        <p className={`text-xl font-bold ${feedback.color} mb-2`}>"{feedback.text}"</p>
                        {feedback.medal && <div className="flex justify-center mt-4">{feedback.medal}</div>}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); }} className="py-3 px-4 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold transition-colors">
                            Xem lại bài làm
                        </button>
                        <button onClick={onReset} className="py-3 px-4 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-bold transition-colors shadow-lg shadow-indigo-200 dark:shadow-none">
                            Làm bài khác
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

