import React, { useEffect, useRef } from 'react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
}

declare global {
  interface Window {
    MathJax: any;
  }
}

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false }) => {
  const containerRef = useRef<any>(null);

  useEffect(() => {
    if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
            // Queue the typesetting
            window.MathJax.typesetPromise?.([containerRef.current])
                .catch((err: any) => {
                    // Suppress harmless errors during fast unmounts/remounts
                    if (err.message && !err.message.includes('context')) {
                        console.warn('MathJax typesetting failed:', err);
                    }
                });
        } catch (e) {
            console.error("MathJax error:", e);
        }
    }
  }, [content]);

  const processContent = (text: string) => {
      if (!text) return null;
      // Split by bold markdown **...**
      const parts = text.split(/(\*\*[^*]+\*\*)/g);
      return parts.map((part, index) => {
          if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="font-bold">{part.slice(2, -2)}</strong>;
          }
          return <span key={index}>{part}</span>;
      });
  };

  const Tag = inline ? 'span' : 'div';

  return (
    <Tag ref={containerRef} className={`math-renderer ${inline ? 'inline-block' : 'block'}`}>
      {processContent(content)}
    </Tag>
  );
};

export default MathRenderer;

