import { MathJax } from 'mathjax-full/js/mathjax.js';
import { TeX } from 'mathjax-full/js/input/tex.js';
import { MathML } from 'mathjax-full/js/output/mathml.js';
import { liteAdaptor } from 'mathjax-full/js/adaptors/liteAdaptor.js';
import { RegisterHTMLHandler } from 'mathjax-full/js/handlers/html.js';
import { convertMathMLToOMML } from 'mathml-to-omml';
import { TextRun, Math as DocxMath } from 'docx';

// Initialize MathJax adaptor
const adaptor = liteAdaptor();
RegisterHTMLHandler(adaptor);

// Setup TeX input and MathML output
const tex = new TeX({ packages: ['base', 'ams'] });
const mathml = new MathML();

// Create MathJax document
const mj = MathJax.document('', {
  InputJax: tex,
  OutputJax: mathml,
});

/**
 * Converts LaTeX string to OMML (Office Math Markup Language) XML string.
 * This allows proper equation rendering in Word documents.
 */
export function latexToOMML(latex: string): string {
  try {
    const node = mj.convert(latex, { display: false });
    const mathML = adaptor.outerHTML(node);
    return convertMathMLToOMML(mathML);
  } catch (error) {
    console.error("Error converting LaTeX to OMML:", error);
    return "";
  }
}

/**
 * Parses a content string containing Markdown bold (**text**) and LaTeX math ($equation$)
 * returns an array of docx children (TextRun or Math) to be used in a Paragraph.
 */
export const parseContentToDocx = (content: string) => {
  if (!content) return [];

  const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);
  const children: any[] = [];

  parts.forEach(part => {
    if (!part) return;

    // === EQUATION ($...$) ===
    if (part.startsWith('$') && part.endsWith('$')) {
      const latex = part.slice(1, -1).trim();
      const omml = latexToOMML(latex);

      if (omml) {
        try {
            // @ts-ignore
            children.push(DocxMath.fromOMML(omml));
        } catch (e) {
            children.push(new TextRun({ text: latex, italics: true }));
        }
      } else {
         children.push(new TextRun({ text: latex, italics: true }));
      }

    // === BOLD (**...**) ===
    } else if (part.startsWith('**') && part.endsWith('**')) {
      children.push(
        new TextRun({
          text: part.slice(2, -2),
          bold: true,
          size: 24, // 12pt
        })
      );

    // === PLAIN TEXT ===
    } else {
      children.push(
        new TextRun({
          text: part,
          size: 24, // 12pt
        })
      );
    }
  });

  return children;
};

