  const [isStarted, setIsStarted] = useState(false);
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setQuestions(data.questions); setUserAnswers({}); setIsSubmitted(false); setShowScoreModal(false);
    setShowAnswers(false); setStudentName(''); setIsStarted(false); setCurrentSlide(0);
    setViewMode('list'); setIsEditMode(false); setSpeakingId(null); setTimer(null);
    setIsTimerRunning(false); window.speechSynthesis.cancel();
  }, [data]);

  useEffect(() => { return () => window.speechSynthesis.cancel(); }, []);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (activeSettingsId !== null && !(event.target as Element).closest('.tts-settings-container')) {
              setActiveSettingsId(null);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [activeSettingsId]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => {
          if (prev === null) return null;
          const nextVal = prev - 1;
          if (nextVal <= 10 && nextVal > 0) playTickSound();
          else if (nextVal === 0) { playAlarmSound(); setIsTimerRunning(false); }
          return nextVal;
        });
      }, 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) containerRef.current.requestFullscreen().catch(console.error);
    } else document.exitFullscreen();
  };

  const jumpToSlide = (idx: number) => {
    if (speakingId !== null) { window.speechSynthesis.cancel(); setSpeakingId(null); }
    if (viewMode === 'slide') setCurrentSlide(idx);
    else { const el = document.getElementById(`question-${idx}`); if (el) el.scrollIntoView({ behavior: 'smooth' }); }
    setShowNav(false);
  };

  const handleStartExam = () => { if (studentName.trim()) { setIsStarted(true); resumeAudioContext(); } };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return;
    resumeAudioContext();
    setUserAnswers(prev => ({ ...prev, [questionIdx]: optionIdx }));
    const q = questions[questionIdx]; const label = ['A', 'B', 'C', 'D'][optionIdx];
    if (q.correctAnswer.trim().toUpperCase().startsWith(label)) playWinSound(); else playLoseSound();
  };

  const handleTFSelect = (questionIdx: number, optionIdx: number, isTrue: boolean) => {
    if (isSubmitted || isEditMode) return;
    resumeAudioContext();
    setUserAnswers(prev => {
        const currentAnswer = prev[questionIdx] || {};
        return { ...prev, [questionIdx]: { ...currentAnswer, [optionIdx]: isTrue } };
    });
    const q = questions[questionIdx]; const label = ['a', 'b', 'c', 'd'][optionIdx];
    const cleanCorrect = q.correctAnswer.toLowerCase();
    const expectTrue = new RegExp(`${label}[).:-]?\\s*(đúng|đ|true|t)`, 'i').test(cleanCorrect);
    const expectFalse = new RegExp(`${label}[).:-]?\\s*(sai|s|false|f)`, 'i').test(cleanCorrect);
    if ((expectTrue && isTrue) || (expectFalse && !isTrue)) playWinSound(); else playLoseSound();
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode || value.length > 4) return;
