// --- Audio Helpers ---
let audioCtx: AudioContext | null = null;
const getAudioContext = () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtx;
};

const resumeAudioContext = () => {
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') ctx.resume();
};

const playTickSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = 'square';
    osc.frequency.setValueAtTime(1000, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.05);
    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);
    osc.start(); osc.stop(ctx.currentTime + 0.05);
};

const playAlarmSound = () => {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;
    const playRing = (time: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'triangle'; osc.frequency.setValueAtTime(800, time);
        osc.frequency.exponentialRampToValueAtTime(600, time + 0.5);
        gain.gain.setValueAtTime(0.2, time); gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);
        osc.start(time); osc.stop(time + 0.5);
    };
    playRing(now); playRing(now + 0.4); playRing(now + 0.8);
};

const playWinSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const playNote = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'sine'; osc.frequency.setValueAtTime(freq, startTime);
        gain.gain.setValueAtTime(0, startTime); gain.gain.linearRampToValueAtTime(0.2, startTime + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);
        osc.start(startTime); osc.stop(startTime + duration);
    };
    playNote(523.25, now, 0.3); playNote(659.25, now + 0.1, 0.3); playNote(783.99, now + 0.2, 0.3); playNote(1046.50, now + 0.3, 0.6);
};

const playLoseSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const playTone = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(freq, startTime);
        osc.frequency.linearRampToValueAtTime(freq - 100, startTime + duration);
        gain.gain.setValueAtTime(0.15, startTime); gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);
        osc.start(startTime); osc.stop(startTime + duration);
    };
    playTone(400, now, 0.4); playTone(290, now + 0.35, 0.8);
};

