  const handleSpeak = (question: Question) => {
    window.speechSynthesis.cancel();
    if (speakingId === question.id) { setSpeakingId(null); return; }
    let textToRead = question.content.replace(/\$\$[\s\S]*?\$\$/g, ', ').replace(/\$[^\$]*\$/g, ', ').replace(/\\\[[\s\S]*?\\\]/g, ', ').replace(/\\\([\s\S]*?\\\)/g, ', ').replace(/\*\*/g, '').replace(/_+/g, ''); 
