let audioCtx: AudioContext | null = null;
const getAudioContext = () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtx;
};

const resumeAudioContext = () => {
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') ctx.resume();
};

const playTickSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const osc = ctx.createOscillator(); const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = 'square'; osc.frequency.setValueAtTime(1000, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.05);
    gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);
    osc.start(); osc.stop(ctx.currentTime + 0.05);
};

const playAlarmSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const playRing = (time: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'triangle'; osc.frequency.setValueAtTime(800, time);
        osc.frequency.exponentialRampToValueAtTime(600, time + 0.5);
        gain.gain.setValueAtTime(0.2, time); gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);
        osc.start(time); osc.stop(time + 0.5);
    };
    playRing(now); playRing(now + 0.4); playRing(now + 0.8);
};

const playWinSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const playNote = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'sine'; osc.frequency.setValueAtTime(freq, startTime);
        gain.gain.setValueAtTime(0, startTime); gain.gain.linearRampToValueAtTime(0.2, startTime + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);
        osc.start(startTime); osc.stop(startTime + duration);
    };
    playNote(523.25, now, 0.3); playNote(659.25, now + 0.1, 0.3); playNote(783.99, now + 0.2, 0.3); playNote(1046.50, now + 0.3, 0.6);
};

const playLoseSound = () => {
    const ctx = getAudioContext(); if (!ctx) return;
    const now = ctx.currentTime;
    const playTone = (freq: number, startTime: number, duration: number) => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(freq, startTime);
        osc.frequency.linearRampToValueAtTime(freq - 100, startTime + duration);
        gain.gain.setValueAtTime(0.15, startTime); gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);
        osc.start(startTime); osc.stop(startTime + duration);
    };
    playTone(400, now, 0.4); playTone(290, now + 0.35, 0.8);
};

export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(false);
  const [activeHints, setActiveHints] = useState<Record<number, boolean>>({});
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [isExporting, setIsExporting] = useState(false);
  const [showNav, setShowNav] = useState(false); 
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [speakingId, setSpeakingId] = useState<number | null>(null);
  const [ttsConfig, setTtsConfig] = useState({ lang: 'vi-VN', voiceIdx: 0, rate: 1.0 });
  const [activeSettingsId, setActiveSettingsId] = useState<number | null>(null);
  const [isEditMode, setIsEditMode] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1); 
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [isStarted, setIsStarted] = useState(false);
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setQuestions(data.questions); setUserAnswers({}); setIsSubmitted(false); setShowScoreModal(false);
    setShowAnswers(false); setStudentName(''); setIsStarted(false); setCurrentSlide(0);
    setViewMode('list'); setIsEditMode(false); setSpeakingId(null); setTimer(null);
    setIsTimerRunning(false); window.speechSynthesis.cancel();
  }, [data]);

  useEffect(() => { return () => window.speechSynthesis.cancel(); }, []);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (activeSettingsId !== null && !(event.target as Element).closest('.tts-settings-container')) {
              setActiveSettingsId(null);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [activeSettingsId]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => {
          if (prev === null) return null;
          const nextVal = prev - 1;
          if (nextVal <= 10 && nextVal > 0) playTickSound();
          else if (nextVal === 0) { playAlarmSound(); setIsTimerRunning(false); }
          return nextVal;
        });
      }, 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) containerRef.current.requestFullscreen().catch(console.error);
    } else document.exitFullscreen();
  };

  const jumpToSlide = (idx: number) => {
    if (speakingId !== null) { window.speechSynthesis.cancel(); setSpeakingId(null); }
    if (viewMode === 'slide') setCurrentSlide(idx);
    else { const el = document.getElementById(`question-${idx}`); if (el) el.scrollIntoView({ behavior: 'smooth' }); }
    setShowNav(false);
  };

  const handleStartExam = () => { if (studentName.trim()) { setIsStarted(true); resumeAudioContext(); } };

  const handleOptionSelect = (questionIdx: number, optionIdx: number) => {
    if (isSubmitted || isEditMode) return;
    resumeAudioContext();
    setUserAnswers(prev => ({ ...prev, [questionIdx]: optionIdx }));
    const q = questions[questionIdx]; const label = ['A', 'B', 'C', 'D'][optionIdx];
    if (q.correctAnswer.trim().toUpperCase().startsWith(label)) playWinSound(); else playLoseSound();
  };

  const handleTFSelect = (questionIdx: number, optionIdx: number, isTrue: boolean) => {
    if (isSubmitted || isEditMode) return;
    resumeAudioContext();
    setUserAnswers(prev => {
        const currentAnswer = prev[questionIdx] || {};
        return { ...prev, [questionIdx]: { ...currentAnswer, [optionIdx]: isTrue } };
    });
    const q = questions[questionIdx]; const label = ['a', 'b', 'c', 'd'][optionIdx];
    const cleanCorrect = q.correctAnswer.toLowerCase();
    const expectTrue = new RegExp(`${label}[).:-]?\\s*(đúng|đ|true|t)`, 'i').test(cleanCorrect);
    const expectFalse = new RegExp(`${label}[).:-]?\\s*(sai|s|false|f)`, 'i').test(cleanCorrect);
    if ((expectTrue && isTrue) || (expectFalse && !isTrue)) playWinSound(); else playLoseSound();
  };

  const handleEssayChange = (questionIdx: number, value: string) => {
    if (isSubmitted || isEditMode || value.length > 4) return;
    setUserAnswers(prev => ({ ...prev, [questionIdx]: value.toUpperCase() }));
  };

  const handleDeleteQuestion = (idxToDelete: number) => {
    if (!window.confirm(`Bạn có chắc chắn muốn xóa Câu ${idxToDelete + 1} không?`)) return;
    setQuestions(questions.filter((_, idx) => idx !== idxToDelete));
  };

  const handleSpeak = (question: Question) => {
    window.speechSynthesis.cancel();
    if (speakingId === question.id) { setSpeakingId(null); return; }
    let textToRead = question.content.replace(/\$\$[\s\S]*?\$\$/g, ', ').replace(/\$[^\$]*\$/g, ', ').replace(/\\\[[\s\S]*?\\\]/g, ', ').replace(/\\\([\s\S]*?\\\)/g, ', ').replace(/\*\*/g, '').replace(/_+/g, ''); 
    if (question.type === QuestionType.MULTIPLE_CHOICE) {
        const promptText = ttsConfig.lang === 'en-US' ? "Which answer is correct?" : MCQ_PROMPTS[Math.floor(Math.random() * MCQ_PROMPTS.length)];
        textToRead += `. ${promptText}`;
    }
    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = ttsConfig.lang;
    const selectedProfile = VOICE_PROFILES[ttsConfig.voiceIdx];
    utterance.rate = ttsConfig.rate * selectedProfile.rate;
    utterance.pitch = selectedProfile.pitch;
    utterance.onend = () => setSpeakingId(null); utterance.onerror = () => setSpeakingId(null);
    setSpeakingId(question.id); window.speechSynthesis.speak(utterance);
  };

  const startTimer = (minutes: number) => { setTimer(minutes * 60); setIsTimerRunning(true); setShowTimerMenu(false); };
  const formatTime = (seconds: number) => { const m = Math.floor(seconds / 60); const s = seconds % 60; return `${m}:${s < 10 ? '0' : ''}${s}`; };

  const calculateScore = () => {
    let correctCount = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE) {
             const label = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.toUpperCase().startsWith(label)) correctCount++;
          } else if (q.type === QuestionType.ESSAY) {
             if (q.correctAnswer.replace(/\$/g, '').trim().toUpperCase() === userAns.trim().toUpperCase()) correctCount++;
          } else if (q.type === QuestionType.TRUE_FALSE) {
             const cc = q.correctAnswer.toLowerCase(); let ok = true;
             ['a', 'b', 'c', 'd'].forEach((k, oi) => {
                 if (userAns[oi] === undefined) { ok = false; return; }
                 const et = new RegExp(`${k}[).:-]?\\s*(đúng|đ|true|t)`, 'i').test(cc);
                 const ef = new RegExp(`${k}[).:-]?\\s*(sai|s|false|f)`, 'i').test(cc);
                 if ((et && !userAns[oi]) || (ef && userAns[oi])) ok = false;
             });
             if (ok) correctCount++;
          }
      }
    });
    const score = questions.length > 0 ? Math.round((correctCount / questions.length) * 10 * 100) / 100 : 0;
    return { correct: correctCount, total: questions.length, score };
  };

  const handleSubmitExam = () => {
    if (Object.keys(userAnswers).length < questions.length) {
        if (!confirm("Bạn chưa trả lời hết các câu hỏi. Vẫn muốn nộp bài chứ?")) return;
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    if (isTimerRunning) setIsTimerRunning(false);
  };

  const handlePrintStudent = () => { document.body.classList.add('printing-student'); window.print(); setTimeout(() => document.body.classList.remove('printing-student'), 500); };
  const handlePrintTeacher = () => { if (!showAnswers && confirm('Bật hiện đáp án trước khi in?')) { setShowAnswers(true); setTimeout(window.print, 100); return; } window.print(); };
  const handleExportJSON = () => { const blob = new Blob([JSON.stringify({ type: 'exam', config, data: { ...data, questions } }, null, 2)], { type: 'application/json' }); FileSaver.saveAs(blob, `Exam_${Date.now()}.json`); };

  const handleDownloadWord = async () => {
      setIsExporting(true);
      try {
        const docChildren = questions.flatMap((q, i) => [
            new Paragraph({ children: [new TextRun({ text: `Câu ${i + 1}. `, bold: true }), ...parseContentToDocx(q.content)], spacing: { before: 200 } }),
            ...(q.type === QuestionType.MULTIPLE_CHOICE && q.options ? q.options.map((o, oi) => new Paragraph({ children: [new TextRun({ text: `${['A','B','C','D'][oi]}. `, bold: true }), ...parseContentToDocx(o.replace(/^[A-D][\.\)\s]+/, ''))], indent: { left: 720 } })) : []),
            new Paragraph({ children: [new TextRun({ text: "Đáp án đúng: ", bold: true }), ...parseContentToDocx(q.correctAnswer)] }),
            new Paragraph({ children: parseContentToDocx(q.solution) })
        ]);
        const doc = new Document({ sections: [{ children: [new Paragraph({ text: config.topic, heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }), ...docChildren] }] });
        const blob = await Packer.toBlob(doc); FileSaver.saveAs(blob, `Exam_${Date.now()}.docx`);
      } catch (e) { alert("Lỗi xuất Word"); } finally { setIsExporting(false); }
  };

  const TtsSettingsPanel = () => (
      <div className="absolute top-full left-0 mt-2 z-[70] bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-200 dark:border-slate-700 p-4 w-64 animate-fade-in text-left">
          <h4 className="font-bold text-slate-700 dark:text-slate-200 mb-3 flex items-center gap-2 text-xs uppercase border-b pb-2"><Ear className="w-4 h-4" /> Giọng đọc</h4>
          <div className="mb-3">
              <label className="text-[10px] font-bold text-slate-400 mb-1 block">Ngôn ngữ</label>
              <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1">
                  <button onClick={() => setTtsConfig(p => ({...p, lang: 'vi-VN'}))} className={`flex-1 text-[10px] py-1 rounded font-bold ${ttsConfig.lang === 'vi-VN' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>Tiếng Việt</button>
                  <button onClick={() => setTtsConfig(p => ({...p, lang: 'en-US'}))} className={`flex-1 text-[10px] py-1 rounded font-bold ${ttsConfig.lang === 'en-US' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>English</button>
              </div>
          </div>
          <div className="mb-3 flex gap-1">
              {VOICE_PROFILES.map((p, i) => (
                  <button key={i} onClick={() => setTtsConfig(p => ({...p, voiceIdx: i}))} className={`flex-1 p-2 rounded-lg border text-center ${ttsConfig.voiceIdx === i ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200'}`}>
                      <div className="flex justify-center mb-1">{p.icon}</div><span className="text-[10px] font-bold">{p.name}</span>
                  </button>
              ))}
          </div>
          <div>
              <label className="text-[10px] font-bold text-slate-400 mb-1 block flex justify-between">Tốc độ <span>{ttsConfig.rate}x</span></label>
              <div className="flex items-center gap-2"><Turtle className="w-3 h-3"/><input type="range" min="0.5" max="2" step="0.1" value={ttsConfig.rate} onChange={(e) => setTtsConfig(p => ({...p, rate: parseFloat(e.target.value)}))} className="flex-1"/><Rabbit className="w-3 h-3"/></div>
          </div>
      </div>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlideMode: boolean) => {
    const isAnswered = userAnswers[idx] !== undefined; const userAns = userAnswers[idx];
    const zoomEffectClass = (isSlideMode && isFullscreen) ? 'scale-105 origin-top' : 'scale-100 origin-top';
    return (
        <div id={`question-${idx}`} key={idx} className={`bg-white dark:bg-slate-800 shadow-xl border overflow-hidden transition-all duration-300 ${isSlideMode ? 'h-full p-8 border-none shadow-none' : 'p-8 rounded-3xl mb-8 border-slate-100 dark:border-slate-700'}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
          <div className="flex flex-col h-full">
              <div className={`relative z-10 transition-transform duration-500 ${zoomEffectClass}`}>
                <div className="flex items-center gap-3 mb-4">
                    <span className="w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold">{idx + 1}</span>
                    <span className="text-xs font-bold px-3 py-1 rounded-full bg-slate-100 dark:bg-slate-700">{q.difficulty}</span>
                    <div className="flex items-center bg-slate-100 dark:bg-slate-700 rounded-full p-1 relative tts-settings-container">
                        <button onClick={(e) => { e.stopPropagation(); handleSpeak(q); }} className={`p-1 rounded-full ${speakingId === q.id ? 'text-red-500' : 'text-slate-400 hover:text-indigo-600'}`}>{speakingId === q.id ? <StopCircle className="w-5 h-5"/> : VOICE_PROFILES[ttsConfig.voiceIdx].icon}</button>
                        <button onClick={(e) => { e.stopPropagation(); setActiveSettingsId(activeSettingsId === q.id ? null : q.id); }} className="p-1 rounded-full text-slate-400 hover:text-indigo-600 ml-1"><Settings className="w-4 h-4"/></button>
                        {activeSettingsId === q.id && <TtsSettingsPanel />}
                    </div>
                </div>
                <div className="text-2xl leading-tight font-medium text-slate-800 dark:text-slate-100"><MathRenderer content={q.content} /></div>
              </div>
              <div className="mt-6 flex-grow overflow-auto">
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {q.options.map((o, oi) => (
                            <button key={oi} onClick={() => handleOptionSelect(idx, oi)} className={`text-left p-4 rounded-xl border-2 transition-all ${userAns === oi ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/30' : 'border-slate-100 dark:border-slate-700 hover:border-indigo-200'}`}>
                                <span className="font-bold mr-2 text-indigo-600">{['A','B','C','D'][oi]}.</span><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline />
                            </button>
                        ))}
                    </div>
                )}
                {q.type === QuestionType.TRUE_FALSE && q.options && (
                    <table className="w-full text-sm">
                        <tbody className="divide-y">
                            {q.options.map((o, oi) => (
                                <tr key={oi} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
                                    <td className="py-3 font-bold text-indigo-600 w-8">{['a','b','c','d'][oi]})</td>
                                    <td className="py-3"><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></td>
                                    <td className="py-3 w-32 flex gap-2">
                                        <button onClick={() => handleTFSelect(idx, oi, true)} className={`px-3 py-1 rounded border ${userAns?.[oi] === true ? 'bg-emerald-600 text-white' : 'bg-white text-emerald-600'}`}>Đ</button>
                                        <button onClick={() => handleTFSelect(idx, oi, false)} className={`px-3 py-1 rounded border ${userAns?.[oi] === false ? 'bg-red-600 text-white' : 'bg-white text-red-600'}`}>S</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
                {q.type === QuestionType.ESSAY && (
                    <input type="text" maxLength={4} value={userAns || ''} onChange={(e) => handleEssayChange(idx, e.target.value)} placeholder="Nhập kết quả..." className="w-48 p-4 text-3xl font-black text-center bg-slate-50 dark:bg-slate-900 rounded-xl border-2 border-slate-200 outline-none focus:border-indigo-600 uppercase" />
                )}
                {(showAnswers || activeSolutions[q.id]) && <div className="mt-8 p-6 bg-emerald-50 dark:bg-emerald-900/20 rounded-2xl border-2 border-emerald-100"><h4 className="font-bold text-emerald-700 mb-2">Đáp án: <MathRenderer content={q.correctAnswer} inline /></h4><div className="text-slate-700 dark:text-slate-300"><MathRenderer content={q.solution} /></div></div>}
              </div>
              {isSlideMode && <div className="mt-auto pt-4 text-center italic text-slate-400 text-sm">"{STUDY_QUOTES[idx % STUDY_QUOTES.length]}"</div>}
          </div>
        </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center p-4">
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl max-w-md w-full text-center border border-slate-200 dark:border-slate-700">
            <User className="w-16 h-16 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-2xl font-black mb-6 dark:text-white">Nhập tên để thi</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} className="w-full p-4 rounded-xl bg-slate-100 dark:bg-slate-900 dark:text-white text-center text-xl font-bold mb-4 outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Họ và tên..." />
            <button onClick={handleStartExam} disabled={!studentName.trim()} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-bold text-xl shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-colors">Vào thi ngay</button>
            <div className="mt-6">
                <button onClick={() => { setIsEditMode(true); setIsStarted(true); }} className="text-slate-400 hover:text-indigo-600 text-sm font-medium">Chế độ giáo viên</button>
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 font-sans ${isFullscreen ? 'fixed inset-0 z-50 overflow-auto' : ''}`}>
        <header className="bg-white/90 dark:bg-slate-800/90 backdrop-blur border-b sticky top-0 z-40 p-4 h-16 flex justify-between items-center transition-colors">
            <div className="flex items-center gap-3">
                <button onClick={onReset} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg dark:text-slate-300"><ArrowLeft className="w-5 h-5"/></button>
                <div className="hidden sm:block">
                    <h1 className="font-bold truncate max-w-[200px] md:max-w-md dark:text-white">{config.topic}</h1>
                    <div className="text-[10px] text-slate-400 uppercase font-black tracking-widest">{config.subject} • {config.grade}</div>
                </div>
            </div>

            {isTimerRunning && timer !== null && (
                 <div className="flex items-center gap-2 px-3 py-1 bg-red-50 text-red-600 rounded-full font-mono font-bold border border-red-100 animate-pulse">
                    <Clock className="w-4 h-4" /> {formatTime(timer)}
                 </div>
            )}

            <div className="flex gap-1 md:gap-2">
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mr-1">
                    <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md ${viewMode === 'list' ? 'bg-white dark:bg-slate-600 text-indigo-600 shadow-sm' : 'text-slate-400'}`}><ListChecks className="w-4 h-4"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-1.5 rounded-md ${viewMode === 'slide' ? 'bg-white dark:bg-slate-600 text-indigo-600 shadow-sm' : 'text-slate-400'}`}><MonitorPlay className="w-4 h-4"/></button>
                </div>
                <button onClick={handleDownloadWord} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg" title="Tải Word">{isExporting ? <RefreshCw className="w-5 h-5 animate-spin"/> : <Download className="w-5 h-5"/>}</button>
                <button onClick={handleSubmitExam} className="px-3 md:px-4 py-2 bg-indigo-600 text-white font-bold rounded-lg text-sm">Nộp bài</button>
                <button onClick={toggleFullScreen} className="p-2 dark:text-slate-300"><Maximize className="w-5 h-5"/></button>
            </div>
        </header>

        <main className={`flex-grow ${viewMode === 'slide' ? 'p-0' : 'p-4 md:p-8 max-w-4xl mx-auto w-full'}`}>
            {viewMode === 'list' ? questions.map((q, i) => (
                <div key={i} className="relative group">
                    {isEditMode && (
                        <button onClick={() => handleDeleteQuestion(i)} className="absolute -right-4 top-4 p-2 bg-red-100 text-red-600 rounded-full opacity-0 group-hover:opacity-100 transition-opacity z-20"><Trash2 className="w-4 h-4"/></button>
                    )}
                    {renderQuestionCard(q, i, false)}
                </div>
            )) : (
                <div className="h-full relative overflow-hidden flex flex-col">
                    {renderQuestionCard(questions[currentSlide], currentSlide, true)}
                    <div className="fixed bottom-20 left-4 md:left-8 right-4 md:right-8 flex justify-between items-center pointer-events-none">
                        <button onClick={() => setCurrentSlide(s => Math.max(0, s - 1))} disabled={currentSlide === 0} className="p-3 md:p-4 bg-white/80 dark:bg-slate-800/80 shadow-xl rounded-full pointer-events-auto disabled:opacity-30 dark:text-white"><ChevronLeft className="w-6 h-6 md:w-8 md:h-8"/></button>
                        <button onClick={() => setCurrentSlide(s => Math.min(questions.length - 1, s + 1))} disabled={currentSlide === questions.length - 1} className="p-3 md:p-4 bg-white/80 dark:bg-slate-800/80 shadow-xl rounded-full pointer-events-auto disabled:opacity-30 dark:text-white"><ChevronRight className="w-6 h-6 md:w-8 md:h-8"/></button>
                    </div>
                </div>
            )}
        </main>

        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur rounded-full p-1.5 flex gap-1 z-[100] border border-white/10 shadow-2xl items-center">
            <button onClick={() => setShowNav(!showNav)} className={`p-2.5 rounded-full transition-colors ${showNav ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'}`} title="Mục lục"><LayoutGrid className="w-5 h-5"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-2.5 rounded-full text-slate-400 hover:text-yellow-400 transition-colors" title="Bảng đen"><PenTool className="w-5 h-5"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-2.5 rounded-full text-slate-400 hover:text-indigo-400 transition-colors" title="Gọi số"><Dices className="w-5 h-5"/></button>
            <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-2.5 rounded-full transition-colors ${isLaserPointer ? 'bg-red-600 text-white' : 'text-slate-400 hover:text-white'}`} title="Laser"><MousePointer2 className="w-5 h-5"/></button>
            <div className="w-px h-5 bg-white/20 mx-1"></div>
            <div className="flex items-center gap-1 bg-white/5 rounded-full px-1">
                <button onClick={() => setZoomLevel(z => Math.max(0.7, z - 0.1))} className="p-1.5 text-slate-400 hover:text-white"><ZoomOut className="w-4 h-4"/></button>
                <span className="text-[10px] font-bold text-white w-7 text-center">{Math.round(zoomLevel*100)}%</span>
                <button onClick={() => setZoomLevel(z => Math.min(1.5, z + 0.1))} className="p-1.5 text-slate-400 hover:text-white"><ZoomIn className="w-4 h-4"/></button>
            </div>
            <button onClick={() => setIsDockExpanded(!isDockExpanded)} className="p-2 text-slate-500 hover:text-white ml-1"><ChevronDown className={`w-4 h-4 transition-transform ${!isDockExpanded ? 'rotate-180' : ''}`}/></button>
        </div>

        {showScoreModal && (
            <div className="fixed inset-0 z-[110] bg-black/70 flex items-center justify-center p-4 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl max-w-sm w-full text-center shadow-2xl border border-slate-200 dark:border-slate-700 animate-fade-in-up">
                    <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Trophy className="w-10 h-10 text-yellow-500"/>
                    </div>
                    <h2 className="text-4xl font-black text-indigo-600 dark:text-indigo-400 mb-1">{calculateScore().score}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-bold mb-6">Kết quả đã được hệ thống ghi lại!</p>
                    <div className="flex flex-col gap-2">
                        <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-colors">Xem lời giải chi tiết</button>
                        <button onClick={onReset} className="w-full py-4 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-bold hover:bg-slate-200 transition-colors">Làm bài mới</button>
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[60] bg-black/40 flex items-end sm:items-center justify-center p-4 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl w-full max-w-md shadow-2xl border border-slate-200 dark:border-slate-700 animate-fade-in-up" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="font-black text-slate-800 dark:text-white">Mục lục câu hỏi</h3>
                        <button onClick={() => setShowNav(false)}><X className="w-5 h-5 text-slate-400"/></button>
                    </div>
                    <div className="grid grid-cols-5 gap-2 max-h-[50vh] overflow-y-auto p-1 custom-scrollbar">
                        {questions.map((_, i) => (
                            <button key={i} onClick={() => jumpToSlide(i)} className={`h-12 rounded-xl font-bold text-sm transition-all ${currentSlide === i ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'}`}>{i + 1}</button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

{
  "name": "Smart Practice Exam Studio",
  "description": "Hệ thống AI sinh đề luyện tập thông minh, soạn bài giảng slide và hỗ trợ giáo viên chuyên sâu.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

// Always initialize GoogleGenAI with the API key from process.env.API_KEY directly in the client creation
const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const client = createClient();
  // Using gemini-3-pro-preview as it's a complex task involving math (LaTeX) and advanced reasoning
  const smartModel = "gemini-3-pro-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      // Matrix Mode Instructions
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      // Exam Mode Instructions (Single Topic)
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Phân bổ hợp lý giữa 3 dạng bài:
            1. Trắc nghiệm nhiều lựa chọn (4 chọn 1).
            2. Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
            3. Trắc nghiệm trả lời ngắn (Tự luận điền kết quả).

          PHÂN BỔ ĐỘ KHÓ:
          - Dễ/Thông hiểu: Dùng trắc nghiệm 4 chọn 1.
          - Vận dụng: Dùng trắc nghiệm Đúng/Sai.
          - Vận dụng cao: Dùng trả lời ngắn (Tự luận).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao (Nguyên tắc: Dễ trước khó sau).' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề trọng tâm: "${config.topic}".
        Số lượng câu hỏi: ${config.questionCount}.
        Loại câu hỏi: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là nhà giáo dục Việt Nam xuất sắc, giáo viên giỏi đa môn, 
có 20 năm kinh nghiệm giảng dạy và nghiên cứu sách giáo khoa theo CTGDPT 2018,
chuyên gia ra đề kiểm tra – đánh giá năng lực học sinh THPT.

Bạn hiểu rõ:
- Mục tiêu cần đạt của CTGDPT 2018
- Cấu trúc đề kiểm tra hiện hành trong các trường phổ thông Việt Nam từ năm học 2025 trở đi (đặc biệt là dạng trắc nghiệm Đúng/Sai)
- Đặc điểm học sinh theo từng khối lớp
- Yêu cầu phân hóa và đánh giá năng lực

Hãy tạo một bộ đề luyện tập cho môn ${config.subject}, lớp ${config.grade},
bám sát sách giáo khoa (ghi rõ bộ sách),
cấu trúc đề hợp lý, có đáp án và hướng dẫn chấm chi tiết.
    Yêu cầu:
- Nội dung câu hỏi bám sát kiến thức trọng tâm SGK
- Có câu hỏi gắn với thực tế, đời sống hoặc liên môn
- Không đánh đố, không máy móc
- Mức độ khó tăng dần
- Ngôn ngữ chuẩn mực, rõ ràng, phù hợp học sinh Việt Nam
- Có đáp án, thang điểm và nhận xét sư phạm ngắn cho từng câu

    ${structureInstruction}

    Cấu hình độ khó: ${difficultyInstruction}
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Người dùng có cung cấp một tài liệu đính kèm (Hình ảnh hoặc PDF).
    Hãy PHÂN TÍCH KỸ nội dung trong file đính kèm đó.
    Dựa trên kiến thức, bài tập, hoặc ngữ liệu có trong file, hãy soạn ra bộ câu hỏi MỚI (tương tự dạng bài hoặc phát triển từ ngữ liệu đó).
    KHÔNG CHÉP LẠI Y NGUYÊN câu hỏi trong file nếu đó là file bài tập (hãy thay số liệu hoặc ngữ cảnh để tạo đề mới), trừ khi đề bài yêu cầu trích xuất.
    `;
  }

  promptText += `
    Yêu cầu quan trọng:
    1. Nội dung phải chuẩn theo chương trình GDPT 2018 của Bộ Giáo dục & Đào tạo Việt Nam.
    2. Các câu hỏi phải rõ ràng, không trùng lặp.
    3. Phải cung cấp đáp án đúng. Lời giải (solution) cần VIẾT TẮT, CỰC KỲ NGẮN GỌN, SÚC TÍCH, đi thẳng vào các bước biến đổi công thức chính, lược bỏ tối đa các câu văn dẫn dắt rườm rà.
    4. Phải cung cấp 2 gợi ý (hints) cho học sinh để kích thích tư duy (không cho đáp án ngay trong gợi ý).
    5. QUY TẮC DẠNG CÂU HỎI (Type):
       - Nếu type là '${QuestionType.MULTIPLE_CHOICE}': BẮT BUỘC phải có mảng 'options' gồm 4 lựa chọn A, B, C, D. 'correctAnswer' là 'A', 'B', 'C' hoặc 'D'.
       - Nếu type là '${QuestionType.TRUE_FALSE}': BẮT BUỘC phải có mảng 'options' gồm 4 mệnh đề con (a, b, c, d). 'correctAnswer' phải ghi rõ kết quả từng ý theo format: "a) Đ, b) S, c) Đ, d) S" hoặc "a: Đúng, b: Sai...".
       - Nếu type là '${QuestionType.ESSAY}': Mảng 'options' để rỗng hoặc null.
    6. ĐỊNH DẠNG TOÁN HỌC: Tất cả các công thức toán học, phương trình, biểu thức biến số (x, y, z...) PHẢI được viết dưới dạng LaTeX và đặt trong dấu $ (ví dụ: $x^2 + 2x + 1 = 0$, $\\frac{1}{2}$, $\\alpha$). Tuyệt đối không dùng Unicode math thông thường nếu có thể dùng LaTeX.
    7. MỤC TIÊU (Objectives): Hãy liệt kê 3-5 mục tiêu kiến thức, kỹ năng chính mà học sinh cần đạt được thông qua bài luyện tập này.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  // Define schema without Schema import to follow guideline strictness
  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING, description: "Nội dung câu hỏi chính (Stem), chứa công thức LaTeX trong dấu $" },
      type: { type: Type.STRING, description: "Loại câu hỏi (Trắc nghiệm, Trắc nghiệm Đúng/Sai, Tự luận)" },
      difficulty: { type: Type.STRING, description: "Mức độ (ví dụ: Nhận biết, Vận dụng)" },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Danh sách lựa chọn. Nếu TN 4 chọn 1: 4 đáp án. Nếu Đúng/Sai: 4 mệnh đề."
      },
      correctAnswer: { type: Type.STRING, description: "Đáp án đúng. Nếu Đúng/Sai, trả về chuỗi mô tả trạng thái (VD: a-Đ, b-S, c-Đ, d-S)." },
      solution: { type: Type.STRING, description: "Hướng dẫn giải chi tiết (chứa LaTeX)" },
      hints: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "2 gợi ý sư phạm"
      },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "Tiêu đề bài thi" },
      objectives: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING }, 
        description: "Danh sách 3-5 mục tiêu kiến thức cần đạt" 
      },
      summary: { type: Type.STRING, description: "Tóm tắt ma trận đề" },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [];

    // Add uploaded file if exists
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    // Add text prompt
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    // Extract text output as a property
    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as ExamMatrix;
    return data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate exam. Please check your API Key and try again.");
  }
};

