import { TextRun } from 'docx';

/**
 * Phiên bản rút gọn: Chuyển đổi LaTeX đơn giản thành TextRun (italics) 
 * để đảm bảo tính ổn định tối đa trong môi trường trình duyệt.
 */
export const parseContentToDocx = (content: string) => {
  if (!content) return [];

  // Phân tách nội dung dựa trên công thức toán ($...$) và chữ đậm (**...**)
  const parts = content.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);
  const children: TextRun[] = [];

  parts.forEach(part => {
    if (!part) return;

    if (part.startsWith('$') && part.endsWith('$')) {
      // Công thức toán học: Chuyển thành chữ nghiêng (italics) để phân biệt trong Word
      children.push(
        new TextRun({
          text: part.slice(1, -1),
          italics: true,
          size: 24, // 12pt
          font: "Times New Roman"
        })
      );
    } else if (part.startsWith('**') && part.endsWith('**')) {
      // Chữ đậm
      children.push(
        new TextRun({
          text: part.slice(2, -2),
          bold: true,
          size: 24,
          font: "Times New Roman"
        })
      );
    } else {
      // Văn bản bình thường
      children.push(
        new TextRun({
          text: part,
          size: 24,
          font: "Times New Roman"
        })
      );
    }
  });

  return children;
};

