  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          // Kiểm tra xem MathJax đã sẵn sàng chưa
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    renderMath();
  }, [content]);

  const processContent = (text: string) => {
    if (!text) return null;
    const parts = text.split(/(\*\*[^*]+\*\*)/g);
    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold">{part.slice(2, -2)}</strong>;
      }
      return <span key={index}>{part}</span>;
    });
  };

  if (inline) {
    return (
      <span ref={containerRef as React.RefObject<HTMLSpanElement>} className="math-renderer inline-block align-middle">
        {processContent(content)}
      </span>
    );
  }

  return (
    <div ref={containerRef as React.RefObject<HTMLDivElement>} className="math-renderer block my-2">
      {processContent(content)}
    </div>
  );
};

export default MathRenderer;

import React, { useState, useEffect } from 'react';
import { ExamConfig, ExamMatrix, StudyGuideData, ExportData } from './types';
import { generateExam, generateStudyGuide } from './services/geminiService';
import ConfigForm from './components/ConfigForm';
import { ExamPreview } from './components/ExamPreview';
import StudyGuidePreview from './components/StudyGuidePreview';
import { GraduationCap, Loader2, Moon, Sun, AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<'config' | 'preview'>('config');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);

  // Theme State with safe localStorage access
  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('theme');
        if (saved) return saved === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
      }
    } catch (e) {
      console.warn("localStorage access denied");
    }
    return false;
  });

  useEffect(() => {
    const html = document.documentElement;
    try {
      if (isDarkMode) {
        html.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        html.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
    } catch (e) {}
  }, [isDarkMode]);

  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async (newConfig: ExamConfig) => {
    setLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      if (newConfig.mode === 'theory') {
        const data = await generateStudyGuide(newConfig);
        setStudyGuideData(data);
        setExamData(null);
      } else {
        const data = await generateExam(newConfig);
        setExamData(data);
        setStudyGuideData(null);
      }
      setStep('preview');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Lỗi hệ thống AI. Vui lòng kiểm tra lại chủ đề hoặc thử lại sau.");
    } finally {
      setLoading(false);
    }
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const jsonStr = e.target?.result as string;
        if (!jsonStr) return;
        const imported = JSON.parse(jsonStr) as ExportData;
        if (!imported.config || !imported.data) throw new Error("File không đúng định dạng.");
        setConfig(imported.config);
        if (imported.type === 'theory') {
          setStudyGuideData(imported.data as StudyGuideData);
          setExamData(null);
        } else {
          setExamData(imported.data as ExamMatrix);
          setStudyGuideData(null);
        }
        setStep('preview');
      } catch (err: any) {
        setError("Lỗi đọc file: " + err.message);
      }
    };
    reader.readAsText(file);
  };

  const handleReset = () => {
    setStep('config');
    setExamData(null);
    setStudyGuideData(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 font-sans transition-colors duration-300">
      {loading && (
        <div className="fixed inset-0 z-[100] bg-white/90 dark:bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-16 h-16 text-indigo-600 dark:text-indigo-400 animate-spin mb-4" />
          <h3 className="text-2xl font-black text-slate-800 dark:text-white">AI Đang Soạn Đề...</h3>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Vui lòng đợi trong giây lát</p>
        </div>
      )}

      <nav className="bg-white/80 dark:bg-slate-800/80 backdrop-blur-md border-b sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 h-16 flex justify-between items-center">
          <div className="flex items-center gap-2 text-indigo-700 dark:text-indigo-400 cursor-pointer" onClick={handleReset}>
            <GraduationCap className="w-8 h-8" />
            <div>
              <h1 className="text-lg font-black leading-none">STUDIO LUYỆN THI</h1>
              <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">SMART AI POWERED</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden lg:block text-right">
                <div className="text-xs font-black text-slate-400 uppercase">Tác giả</div>
                <div className="text-sm font-bold text-slate-700 dark:text-slate-200">Thầy Vũ Tiến Lực</div>
             </div>
             <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
               {isDarkMode ? <Sun className="w-5 h-5 text-yellow-500" /> : <Moon className="w-5 h-5 text-slate-600" />}
             </button>
          </div>
        </div>
      </nav>

      <main className="p-4 md:p-8">
        {error && (
          <div className="max-w-4xl mx-auto mb-8 p-4 bg-red-50 dark:bg-red-900/20 border-2 border-red-100 dark:border-red-800 rounded-2xl flex items-center gap-3 text-red-700 dark:text-red-400 animate-fade-in shadow-sm">
             <AlertTriangle className="w-6 h-6 flex-shrink-0" />
             <span className="font-bold flex-grow">{error}</span>
             <button onClick={() => setError(null)} className="text-xl font-black">✕</button>
          </div>
        )}

        {step === 'config' ? (
          <div className="py-8 md:py-16">
            <div className="text-center mb-12 max-w-2xl mx-auto px-4">
               <h2 className="text-4xl md:text-6xl font-black text-slate-900 dark:text-white mb-4 tracking-tight">
                  Tương lai của <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-blue-500">Giảng dạy</span>
               </h2>
               <p className="text-lg text-slate-500 dark:text-slate-400 font-medium">
                  Hệ thống hỗ trợ giáo viên và học sinh soạn đề, bài giảng thông minh chuẩn chương trình mới 2018.
               </p>
            </div>
            <ConfigForm onGenerate={handleGenerate} isLoading={loading} onImport={handleImport} />
          </div>
        ) : (
          config && (
            <div className="animate-fade-in">
              {config.mode !== 'theory' && examData ? (
                <ExamPreview config={config} data={examData} onReset={handleReset} onRegenerate={() => handleGenerate(config)} />
              ) : config.mode === 'theory' && studyGuideData ? (
                <StudyGuidePreview config={config} data={studyGuideData} onReset={handleReset} onRegenerate={() => handleGenerate(config)} />
              ) : null}
            </div>
          )
        )}
      </main>

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 no-print transition-colors">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-6 text-slate-400 text-sm font-medium">
          <p>© 2024 Smart Practice Exam Studio. Bản quyền thuộc về Thầy Vũ Tiến Lực.</p>
          <div className="flex gap-6">
            <span className="hover:text-indigo-500 cursor-help">Hướng dẫn sử dụng</span>
            <span className="hover:text-indigo-500 cursor-help">Điều khoản dịch vụ</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

