    utterance.lang = ttsConfig.lang;
    const selectedProfile = VOICE_PROFILES[ttsConfig.voiceIdx];
    utterance.rate = ttsConfig.rate * selectedProfile.rate;
    utterance.pitch = selectedProfile.pitch;
    utterance.onend = () => setSpeakingId(null); utterance.onerror = () => setSpeakingId(null);
    setSpeakingId(question.id); window.speechSynthesis.speak(utterance);
  };

  const startTimer = (minutes: number) => { setTimer(minutes * 60); setIsTimerRunning(true); setShowTimerMenu(false); };
  const formatTime = (seconds: number) => { const m = Math.floor(seconds / 60); const s = seconds % 60; return `${m}:${s < 10 ? '0' : ''}${s}`; };

  const calculateScore = () => {
    let correctCount = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns !== undefined) {
          if (q.type === QuestionType.MULTIPLE_CHOICE) {
             const label = ['A', 'B', 'C', 'D'][userAns];
             if (q.correctAnswer.toUpperCase().startsWith(label)) correctCount++;
          } else if (q.type === QuestionType.ESSAY) {
             const cleanUser = userAns.replace(/\$/g, '').trim().toUpperCase();
             const cleanCorrect = q.correctAnswer.replace(/\$/g, '').trim().toUpperCase();
             if (cleanCorrect.includes(cleanUser) && cleanUser.length > 0) correctCount++;
          } else if (q.type === QuestionType.TRUE_FALSE) {
             const cc = q.correctAnswer.toLowerCase(); let ok = true;
             ['a', 'b', 'c', 'd'].forEach((k, oi) => {
                 if (userAns[oi] === undefined) { ok = false; return; }
                 const et = new RegExp(`${k}[).:-]?\\s*(đúng|đ|true|t)`, 'i').test(cc);
                 const ef = new RegExp(`${k}[).:-]?\\s*(sai|s|false|f)`, 'i').test(cc);
                 if ((et && !userAns[oi]) || (ef && userAns[oi])) ok = false;
             });
             if (ok) correctCount++;
          }
      }
    });
    const score = questions.length > 0 ? Math.round((correctCount / questions.length) * 10 * 100) / 100 : 0;
    return { correct: correctCount, total: questions.length, score };
  };

  const handleSubmitExam = () => {
    if (Object.keys(userAnswers).length < questions.length) {
        if (!confirm("Bạn chưa trả lời hết các câu hỏi. Vẫn muốn nộp bài chứ?")) return;
    }
    setIsSubmitted(true);
    setShowScoreModal(true);
    if (isTimerRunning) setIsTimerRunning(false);
  };

  const handleDownloadWord = async () => {
      setIsExporting(true);
      try {
        const docChildren = questions.flatMap((q, i) => [
            new Paragraph({ children: [new TextRun({ text: `Câu ${i + 1}. `, bold: true }), ...parseContentToDocx(q.content)], spacing: { before: 200 } }),
            ...(q.type === QuestionType.MULTIPLE_CHOICE && q.options ? q.options.map((o, oi) => new Paragraph({ children: [new TextRun({ text: `${['A','B','C','D'][oi]}. `, bold: true }), ...parseContentToDocx(o.replace(/^[A-D][\.\)\s]+/, ''))], indent: { left: 720 } })) : []),
            new Paragraph({ children: [new TextRun({ text: "Đáp án đúng: ", bold: true }), ...parseContentToDocx(q.correctAnswer)] }),
            new Paragraph({ children: parseContentToDocx(q.solution) })
        ]);
        const doc = new Document({ sections: [{ children: [new Paragraph({ text: config.topic, heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }), ...docChildren] }] });
        const blob = await Packer.toBlob(doc); FileSaver.saveAs(blob, `Exam_${Date.now()}.docx`);
      } catch (e) { alert("Lỗi xuất Word"); } finally { setIsExporting(false); }
  };

  const TtsSettingsPanel = () => (
      <div className="absolute top-full left-0 mt-2 z-[70] bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-200 dark:border-slate-700 p-4 w-64 animate-fade-in text-left">
          <h4 className="font-bold text-slate-700 dark:text-slate-200 mb-3 flex items-center gap-2 text-xs uppercase border-b pb-2"><Ear className="w-4 h-4" /> Giọng đọc</h4>
          <div className="mb-3">
              <label className="text-[10px] font-bold text-slate-400 mb-1 block">Ngôn ngữ</label>
              <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1">
                  <button onClick={() => setTtsConfig(p => ({...p, lang: 'vi-VN'}))} className={`flex-1 text-[10px] py-1 rounded font-bold ${ttsConfig.lang === 'vi-VN' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>Tiếng Việt</button>
                  <button onClick={() => setTtsConfig(p => ({...p, lang: 'en-US'}))} className={`flex-1 text-[10px] py-1 rounded font-bold ${ttsConfig.lang === 'en-US' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>English</button>
              </div>
          </div>
          <div className="mb-3 flex gap-1">
              {VOICE_PROFILES.map((p, i) => (
                  <button key={i} onClick={() => setTtsConfig(p => ({...p, voiceIdx: i}))} className={`flex-1 p-2 rounded-lg border text-center ${ttsConfig.voiceIdx === i ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200'}`}>
                      <div className="flex justify-center mb-1">{p.icon}</div><span className="text-[10px] font-bold">{p.name}</span>
                  </button>
              ))}
          </div>
          <div>
              <label className="text-[10px] font-bold text-slate-400 mb-1 block flex justify-between">Tốc độ <span>{ttsConfig.rate}x</span></label>
              <div className="flex items-center gap-2"><Turtle className="w-3 h-3"/><input type="range" min="0.5" max="2" step="0.1" value={ttsConfig.rate} onChange={(e) => setTtsConfig(p => ({...p, rate: parseFloat(e.target.value)}))} className="flex-1"/><Rabbit className="w-3 h-3"/></div>
          </div>
      </div>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlideMode: boolean) => {
    const isAnswered = userAnswers[idx] !== undefined; const userAns = userAnswers[idx];

    // Style adjustments for slide mode presentation
    const cardClass = isSlideMode 
        ? 'h-full flex flex-col items-start justify-start p-10 md:p-16 border-none shadow-none bg-white dark:bg-slate-900 overflow-y-auto' 
        : 'bg-white dark:bg-slate-800 shadow-xl border overflow-hidden p-8 rounded-3xl mb-8 border-slate-100 dark:border-slate-700';

    return (
        <div id={`question-${idx}`} key={idx} className={cardClass} style={{ fontSize: `${zoomLevel * 100}%` }}>
          <div className="w-full flex flex-col">
              {/* Header Info */}
              <div className="flex items-center justify-between w-full mb-6 no-print">
                <div className="flex items-center gap-4">
                    <span className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-lg shadow-indigo-200 dark:shadow-none">{idx + 1}</span>
                    <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-300">{q.difficulty}</span>
                    <div className="flex items-center bg-slate-100 dark:bg-slate-700 rounded-full p-1 relative tts-settings-container">
                        <button onClick={(e) => { e.stopPropagation(); handleSpeak(q); }} className={`p-1.5 rounded-full transition-colors ${speakingId === q.id ? 'text-red-500 bg-red-50 dark:bg-red-900/30' : 'text-slate-400 hover:text-indigo-600'}`}>{speakingId === q.id ? <StopCircle className="w-5 h-5"/> : VOICE_PROFILES[ttsConfig.voiceIdx].icon}</button>
                        <button onClick={(e) => { e.stopPropagation(); setActiveSettingsId(activeSettingsId === q.id ? null : q.id); }} className="p-1.5 rounded-full text-slate-400 hover:text-indigo-600 ml-1"><Settings className="w-4 h-4"/></button>
                        {activeSettingsId === q.id && <TtsSettingsPanel />}
                    </div>
                </div>
                {isSlideMode && <div className="text-sm font-black text-slate-300 uppercase tracking-tighter">Slide {idx + 1}/{questions.length}</div>}
              </div>

              {/* Question Content */}
              <div className="mb-10 text-3xl md:text-4xl leading-[1.3] font-semibold text-slate-800 dark:text-slate-100 border-l-8 border-indigo-600 pl-6 py-2">
                <MathRenderer content={q.content} />
              </div>

              {/* Options / Answers Area */}
              <div className="mt-4 w-full">
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full">
                        {q.options.map((o, oi) => (
                            <button 
                                key={oi} 
                                onClick={() => handleOptionSelect(idx, oi)} 
                                className={`group text-left p-6 rounded-2xl border-2 transition-all duration-200 flex items-start gap-4 shadow-sm hover:shadow-md
                                    ${userAns === oi 
                                        ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/40 ring-2 ring-indigo-200' 
                                        : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} ${OPTION_THEMES[oi].hover}`
                                    }`}
                            >
                                <span className={`flex-shrink-0 w-10 h-10 rounded-xl flex items-center justify-center font-black text-xl transition-transform group-hover:scale-110 
                                    ${userAns === oi ? 'bg-indigo-600 text-white' : OPTION_THEMES[oi].labelBg}`}>
                                    {['A','B','C','D'][oi]}
                                </span>
                                <div className={`text-xl md:text-2xl font-medium ${OPTION_THEMES[oi].text} dark:text-slate-100`}>
                                    <MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline />
                                </div>
                            </button>
                        ))}
                    </div>
                )}

                {q.type === QuestionType.TRUE_FALSE && q.options && (
                    <div className="bg-slate-50 dark:bg-slate-900/50 rounded-3xl border border-slate-200 dark:border-slate-700 overflow-hidden shadow-inner">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-slate-100 dark:bg-slate-800 text-slate-500 uppercase text-xs font-black tracking-widest">
                                    <th className="py-4 pl-8 text-left">Nội dung mệnh đề</th>
                                    <th className="py-4 pr-8 text-right">Lựa chọn</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                                {q.options.map((o, oi) => (
                                    <tr key={oi} className="hover:bg-indigo-50/50 dark:hover:bg-indigo-900/10 transition-colors">
                                        <td className="py-6 pl-8">
                                            <div className="flex items-start gap-3">
                                                <span className="font-black text-indigo-600">{['a','b','c','d'][oi]})</span>
                                                <div className="text-xl md:text-2xl"><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                                            </div>
                                        </td>
                                        <td className="py-6 pr-8 text-right">
                                            <div className="flex justify-end gap-3">
                                                <button 
                                                    onClick={() => handleTFSelect(idx, oi, true)} 
                                                    className={`w-14 h-14 rounded-xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-500/30 scale-110' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-emerald-600'}`}
                                                >
                                                    Đ
                                                </button>
                                                <button 
                                                    onClick={() => handleTFSelect(idx, oi, false)} 
                                                    className={`w-14 h-14 rounded-xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-lg shadow-red-500/30 scale-110' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-red-600'}`}
                                                >
                                                    S
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {q.type === QuestionType.ESSAY && (
                    <div className="w-full flex flex-col items-center gap-6 py-10 bg-slate-50 dark:bg-slate-900/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                        <label className="text-sm font-black text-slate-400 uppercase tracking-widest">Nhập kết quả cuối cùng</label>
                        <input 
                            type="text" 
                            value={userAns || ''} 
                            onChange={(e) => handleEssayChange(idx, e.target.value)} 
                            placeholder="..." 
                            className="w-full max-w-md p-6 text-5xl font-black text-center bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-2xl border-4 border-indigo-100 dark:border-indigo-900 outline-none focus:border-indigo-600 shadow-2xl uppercase transition-all" 
                        />
                        <p className="text-xs text-slate-400 italic">Hệ thống sẽ tự động so khớp kết quả</p>
                    </div>
                )}

                {/* Show Answer / Solution if requested */}
                {(showAnswers || activeSolutions[q.id]) && (
                    <div className="mt-12 p-8 bg-emerald-50 dark:bg-emerald-900/20 rounded-3xl border-2 border-emerald-100 dark:border-emerald-800/50 animate-fade-in shadow-xl">
                        <div className="flex items-center gap-2 mb-4">
                            <CheckCircle className="w-8 h-8 text-emerald-600" />
                            <h4 className="font-black text-2xl text-emerald-700 dark:text-emerald-400">Đáp án chính xác: <MathRenderer content={q.correctAnswer} inline /></h4>
                        </div>
                        <div className="h-px bg-emerald-100 dark:bg-emerald-800/50 w-full mb-6"></div>
                        <div className="text-xl md:text-2xl text-slate-700 dark:text-slate-300 leading-relaxed">
                            <MathRenderer content={q.solution} />
                        </div>
                    </div>
                )}
              </div>

              {/* Footer Quote in presentation mode */}
              {isSlideMode && (
                <div className="mt-16 pt-10 border-t border-slate-100 dark:border-slate-800 w-full flex flex-col items-center">
                    <Quote className="w-10 h-10 text-indigo-100 dark:text-slate-800 mb-4" />
                    <p className="max-w-2xl text-center italic text-slate-400 text-xl font-medium leading-relaxed">
                        "{STUDY_QUOTES[idx % STUDY_QUOTES.length]}"
                    </p>
                </div>
              )}
          </div>
        </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-slate-50 dark:bg-slate-900">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] shadow-2xl max-w-md w-full text-center border border-slate-200 dark:border-slate-700 transform transition-all hover:scale-[1.02]">
            <div className="w-24 h-24 bg-indigo-50 dark:bg-indigo-900/30 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-indigo-100 dark:shadow-none">
                <User className="w-12 h-12 text-indigo-600 dark:text-indigo-400" />
            </div>
            <h2 className="text-3xl font-black mb-2 dark:text-white">Bắt đầu Luyện tập</h2>
            <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium">Nhập tên của bạn để hệ thống ghi lại kết quả</p>

            <div className="space-y-4">
                <input 
                    type="text" 
                    value={studentName} 
                    onChange={(e) => setStudentName(e.target.value)} 
                    className="w-full p-5 rounded-2xl bg-slate-100 dark:bg-slate-900 dark:text-white text-center text-2xl font-black mb-2 outline-none focus:ring-4 focus:ring-indigo-100 dark:focus:ring-indigo-900 transition-all placeholder-slate-300" 
                    placeholder="HỌ VÀ TÊN..." 
                />
                <button 
                    onClick={handleStartExam} 
                    disabled={!studentName.trim()} 
                    className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black text-2xl shadow-xl shadow-indigo-200 dark:shadow-none disabled:opacity-50 hover:bg-indigo-700 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
                >
                    <Send className="w-6 h-6" /> VÀO THI NGAY
                </button>
            </div>

            <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-700">
                <button onClick={() => { setIsEditMode(true); setIsStarted(true); }} className="flex items-center gap-2 mx-auto text-slate-400 hover:text-indigo-600 text-sm font-black uppercase tracking-widest transition-colors">
                    <Key className="w-4 h-4" /> Chế độ Giáo viên
                </button>
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 font-sans ${isFullscreen ? 'fixed inset-0 z-50 overflow-auto' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-40 p-4 h-16 flex justify-between items-center transition-all no-print">
            <div className="flex items-center gap-3">
                <button onClick={onReset} className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl dark:text-slate-300 transition-colors" title="Thoát"><ArrowLeft className="w-5 h-5"/></button>
                <div className="hidden sm:block">
                    <h1 className="font-black truncate max-w-[200px] md:max-w-md dark:text-white text-lg">{config.topic}</h1>
                    <div className="text-[10px] text-slate-400 uppercase font-black tracking-[0.2em]">{config.subject} • {config.grade}</div>
                </div>
            </div>

            <div className="flex items-center gap-3">
                {isTimerRunning && timer !== null && (
                    <div className="flex items-center gap-2 px-4 py-1.5 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-full font-mono font-black border border-red-100 dark:border-red-800/50 animate-pulse shadow-sm">
                        <Clock className="w-4 h-4" /> {formatTime(timer)}
                    </div>
                )}

                <div className="flex gap-1 md:gap-2">
                    <div className="flex bg-slate-100 dark:bg-slate-700 rounded-xl p-1 mr-1">
                        <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-600 text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`} title="Xem danh sách"><ListChecks className="w-5 h-5"/></button>
                        <button onClick={() => setViewMode('slide')} className={`p-2 rounded-lg transition-all ${viewMode === 'slide' ? 'bg-white dark:bg-slate-600 text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`} title="Chế độ trình chiếu"><MonitorPlay className="w-5 h-5"/></button>
                    </div>
                    <button onClick={handleDownloadWord} className="p-2.5 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-colors" title="Xuất file Word">{isExporting ? <RefreshCw className="w-5 h-5 animate-spin"/> : <Download className="w-5 h-5"/>}</button>
                    <button onClick={handleSubmitExam} className="px-5 py-2 bg-indigo-600 text-white font-black rounded-xl text-sm shadow-lg shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all">NỘP BÀI</button>
                    <button onClick={toggleFullScreen} className="p-2.5 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl transition-colors">
                        {isFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}
                    </button>
                </div>
            </div>
        </header>

        <main className={`flex-grow relative ${viewMode === 'slide' ? 'p-0 bg-white dark:bg-slate-900' : 'p-4 md:p-8 max-w-5xl mx-auto w-full'}`}>
            {viewMode === 'list' ? questions.map((q, i) => (
                <div key={i} className="relative group animate-fade-in-up" style={{ animationDelay: `${i * 100}ms` }}>
                    {isEditMode && (
                        <button onClick={() => handleDeleteQuestion(i)} className="absolute -right-4 top-4 p-2 bg-red-100 text-red-600 rounded-full opacity-0 group-hover:opacity-100 transition-opacity z-20 shadow-md"><Trash2 className="w-4 h-4"/></button>
                    )}
                    {renderQuestionCard(q, i, false)}
                </div>
            )) : (
                <div className="h-full relative flex flex-col items-center">
                    <div className="w-full flex-grow overflow-hidden flex flex-col items-center">
                        {renderQuestionCard(questions[currentSlide], currentSlide, true)}
                    </div>

                    {/* Slide Navigation Overlay */}
                    <div className="fixed bottom-24 left-8 right-8 flex justify-between items-center pointer-events-none z-50">
                        <button 
                            onClick={() => setCurrentSlide(s => Math.max(0, s - 1))} 
                            disabled={currentSlide === 0} 
                            className={`p-5 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-[30px] pointer-events-auto disabled:opacity-20 border border-slate-100 dark:border-slate-700 text-slate-800 dark:text-white transform transition-all hover:scale-110 active:scale-90 ${currentSlide === 0 ? 'invisible' : ''}`}
                        >
                            <ChevronLeft className="w-10 h-10"/>
                        </button>
                        <button 
                            onClick={() => setCurrentSlide(s => Math.min(questions.length - 1, s + 1))} 
                            disabled={currentSlide === questions.length - 1} 
                            className={`p-5 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-[30px] pointer-events-auto disabled:opacity-20 border border-slate-100 dark:border-slate-700 text-slate-800 dark:text-white transform transition-all hover:scale-110 active:scale-90 ${currentSlide === questions.length - 1 ? 'invisible' : ''}`}
                        >
                            <ChevronRight className="w-10 h-10"/>
                        </button>
                    </div>
                </div>
            )}
        </main>

        {/* Dynamic Dock (Floating Controls) */}
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-1.5 flex gap-1 z-[100] border border-white/20 shadow-[0_20px_50px_rgba(0,0,0,0.5)] items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className={`p-3 rounded-full transition-all ${showNav ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-white/10'}`} title="Danh mục câu hỏi"><LayoutGrid className="w-5 h-5"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 rounded-full text-slate-400 hover:text-yellow-400 hover:bg-white/10 transition-all" title="Bảng giảng bài"><PenTool className="w-5 h-5"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full text-slate-400 hover:text-indigo-400 hover:bg-white/10 transition-all" title="Gọi học sinh ngẫu nhiên"><Dices className="w-5 h-5"/></button>
            <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-all ${isLaserPointer ? 'bg-red-600 text-white shadow-lg shadow-red-500/50' : 'text-slate-400 hover:text-white hover:bg-white/10'}`} title="Bút Laser trình chiếu"><MousePointer2 className="w-5 h-5"/></button>

            <div className="w-px h-6 bg-white/20 mx-1"></div>

            <div className="flex items-center gap-1 bg-black/40 rounded-full px-2 py-0.5">
                <button onClick={() => setZoomLevel(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-400 hover:text-white transition-colors" title="Thu nhỏ"><ZoomOut className="w-4 h-4"/></button>
                <div className="flex flex-col items-center min-w-[50px]">
                    <span className="text-[10px] font-black text-white/50 uppercase leading-none mb-0.5">Cỡ chữ</span>
                    <span className="text-xs font-black text-white leading-none">{Math.round(zoomLevel*100)}%</span>
                </div>
