                        <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black text-xl hover:bg-indigo-700 shadow-xl shadow-indigo-200 dark:shadow-none transition-all active:scale-95">XEM LỜI GIẢI CHI TIẾT</button>
