                    <div className="flex justify-between items-center mb-8">
                        <div>
                            <h3 className="font-black text-2xl text-slate-800 dark:text-white">Danh mục câu hỏi</h3>
                            <p className="text-sm text-slate-400 font-medium">Chọn số câu để di chuyển nhanh</p>
                        </div>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-50 dark:bg-slate-900 rounded-2xl text-slate-400 hover:text-red-500 transition-colors"><X className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-4 sm:grid-cols-5 gap-3 max-h-[50vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((_, i) => (
                            <button 
                                key={i} 
                                onClick={() => jumpToSlide(i)} 
                                className={`h-16 rounded-2xl font-black text-xl transition-all flex items-center justify-center border-2 
                                    ${currentSlide === i 
                                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-xl shadow-indigo-200 dark:shadow-none scale-105' 
                                        : 'bg-slate-50 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border-transparent hover:border-indigo-200 dark:hover:border-indigo-500'
                                    }`}
                            >
                                {i + 1}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {/* Global Components */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}

        {/* Visual Aids */}
        {isLaserPointer && <div className="fixed w-4 h-4 bg-red-600 rounded-full blur-[2px] shadow-[0_0_15px_#dc2626] pointer-events-none z-[200] opacity-80" style={{ left: '-100px', top: '-100px' }} id="laser-pointer-dot" />}
        {isLaserPointer && <script>{`
            document.addEventListener('mousemove', (e) => {
                const dot = document.getElementById('laser-pointer-dot');
                if (dot) {
                    dot.style.left = (e.clientX - 8) + 'px';
                    dot.style.top = (e.clientY - 8) + 'px';
                }
            });
        `}</script>}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation as PresentationIcon, FileText, Printer, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut, RefreshCw, Palette, Star, Eye, EyeOff, Lightbulb, BookOpen, Download, Save, Quote, MonitorPlay } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } from 'docx';
import FileSaver from 'file-saver';
import { parseContentToDocx } from '../utils/docxUtils';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { name: 'Xanh Ngọc', bg: 'bg-teal-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-teal-700 dark:text-teal-400', accent: 'text-teal-600', border: 'border-teal-500', highlightBg: 'bg-teal-100 dark:bg-teal-900/50', highlightText: 'text-teal-800 dark:text-teal-200', exampleBg: 'bg-white dark:bg-slate-800', exampleBorder: 'border-teal-400', starColor: 'text-teal-500 fill-teal-500', btnBg: 'bg-teal-600 hover:bg-teal-700' },
  blue: { name: 'Xanh Dương', bg: 'bg-blue-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-blue-700 dark:text-blue-400', accent: 'text-blue-600', border: 'border-blue-500', highlightBg: 'bg-blue-100 dark:bg-blue-900/50', highlightText: 'text-blue-800 dark:text-blue-200', exampleBg: 'bg-white dark:bg-slate-800', exampleBorder: 'border-blue-400', starColor: 'text-blue-500 fill-blue-500', btnBg: 'bg-blue-600 hover:bg-blue-700' },
  violet: { name: 'Tím Mộng Mơ', bg: 'bg-violet-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-violet-700 dark:text-violet-400', accent: 'text-violet-600', border: 'border-violet-500', highlightBg: 'bg-violet-100 dark:bg-violet-900/50', highlightText: 'text-violet-800 dark:text-violet-200', exampleBg: 'bg-white dark:bg-slate-800', exampleBorder: 'border-violet-400', starColor: 'text-violet-500 fill-violet-500', btnBg: 'bg-violet-600 hover:bg-violet-700' }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLaserPointer, setIsLaserPointer] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [isDockExpanded, setIsDockExpanded] = useState(true);
  const [zoomLevel, setZoomLevel] = useState(1.5);
  const [isExporting, setIsExporting] = useState(false);
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => setShowExampleSolution(false), [currentSlide, slideStep]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { setCurrentSlide(v => v + 1); setSlideStep(1); }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { setCurrentSlide(v => v - 1); setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      if (containerRef.current) containerRef.current.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
        document.exitFullscreen();
        setIsFullscreen(false);
    }
  };

  const handleDownloadWord = async () => {
    setIsExporting(true);
    try {
        const sections = data.sections.flatMap((sec, i) => [
            new Paragraph({ text: `${i + 1}. ${sec.title}`, heading: HeadingLevel.HEADING_2, spacing: { before: 400 } }),
            ...sec.content.split('\n').filter(l => l.trim()).map(l => new Paragraph({ children: parseContentToDocx(l.replace(/^[★•\-\s]+/, '')), bullet: { level: 0 } })),
            ...(sec.examples || []).flatMap(ex => [
                new Paragraph({ children: [new TextRun({ text: "Ví dụ minh họa:", bold: true })], spacing: { before: 200 } }),
                new Paragraph({ children: parseContentToDocx(ex.problem) }),
                new Paragraph({ children: [new TextRun({ text: "Lời giải:", italics: true })] }),
                new Paragraph({ children: parseContentToDocx(ex.solution) })
            ])
        ]);
        const doc = new Document({ sections: [{ children: [new Paragraph({ text: data.topic, heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER }), ...sections] }] });
        const blob = await Packer.toBlob(doc); FileSaver.saveAs(blob, `Lectures_${Date.now()}.docx`);
    } catch (e) { alert("Lỗi Word"); } finally { setIsExporting(false); }
  };

  const theme = SLIDE_THEMES[activeTheme];

  return (
    <div ref={containerRef} className={`bg-slate-50 dark:bg-slate-900 relative transition-all duration-300 ${isFullscreen ? 'fixed inset-0 z-50 h-screen w-screen overflow-hidden' : 'min-h-screen flex flex-col'}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 flex items-center justify-between no-print h-16 sticky top-0 z-40">
            <div className="flex items-center gap-3">
                <button onClick={onReset} className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl transition-colors"><RotateCcw className="w-5 h-5" /></button>
                <h1 className="text-xl font-black truncate max-w-xs md:max-w-md">{data.topic}</h1>
            </div>
            <div className="flex items-center gap-2">
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-xl p-1">
                    <button onClick={() => setViewMode('doc')} className={`p-2 rounded-lg transition-all ${viewMode === 'doc' ? 'bg-white dark:bg-slate-600 text-teal-600 shadow-sm' : 'text-slate-400'}`} title="Xem tài liệu"><FileText className="w-5 h-5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2 rounded-lg transition-all ${viewMode === 'slide' ? 'bg-white dark:bg-slate-600 text-teal-600 shadow-sm' : 'text-slate-400'}`} title="Chế độ Slide"><MonitorPlay className="w-5 h-5"/></button>
                </div>
                <button onClick={handleDownloadWord} className="p-2.5 bg-blue-600 text-white rounded-xl shadow-lg shadow-blue-200 dark:shadow-none transition-all active:scale-95" title="Tải file Word"><Download className="w-5 h-5"/></button>
                <button onClick={toggleFullScreen} className="p-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl transition-colors">
                    {isFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}
                </button>
            </div>
        </header>

        <main className="flex-grow overflow-hidden relative">
            {viewMode === 'doc' ? (
                <div className="h-full overflow-y-auto p-8 md:p-12 max-w-5xl mx-auto bg-white dark:bg-slate-800 shadow-sm animate-fade-in">
                    {data.sections.map((s, i) => (
                        <div key={i} className="mb-16">
                            <h2 className="text-3xl font-black mb-6 border-b-4 border-teal-500 inline-block pb-2">{i+1}. {s.title}</h2>
                            <div className="space-y-4 text-xl leading-relaxed">
                                <MathRenderer content={s.content}/>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className={`h-full w-full flex flex-col ${theme.bg} transition-colors duration-500`}>
                    <div className="flex-grow p-10 md:p-20 flex flex-col items-start justify-start overflow-y-auto" style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className="w-full mb-10 pb-6 border-b-4 border-teal-500 flex justify-between items-end">
                            <h2 className="text-5xl md:text-6xl font-black text-teal-700 dark:text-teal-400 leading-tight">
                                {slides[currentSlide].title}
                            </h2>
                            <div className="text-sm font-black text-teal-300 uppercase tracking-[0.3em]">Slide {currentSlide + 1}</div>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-4xl md:text-5xl leading-relaxed space-y-8 w-full font-medium text-slate-800 dark:text-slate-100 animate-fade-in">
                                <MathRenderer content={slides[currentSlide].content}/>
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-slate-800 p-12 rounded-[40px] border-4 border-teal-400 shadow-2xl animate-fade-in-up flex flex-col items-start">
                                <div className="flex items-center gap-3 mb-8">
                                    <Star className="w-10 h-10 text-teal-500 fill-teal-500" />
                                    <h3 className="text-4xl font-black text-teal-700 dark:text-teal-400 uppercase tracking-widest">Ví dụ minh họa</h3>
                                </div>
                                <div className="text-3xl md:text-4xl mb-12 font-semibold text-slate-800 dark:text-slate-100 leading-relaxed">
                                    <MathRenderer content={slides[currentSlide].examples[0].problem}/>
                                </div>
                                {!showExampleSolution ? (
                                    <button 
                                        onClick={() => setShowExampleSolution(true)} 
                                        className="px-12 py-6 bg-teal-600 text-white font-black text-3xl rounded-[25px] shadow-2xl shadow-teal-200 dark:shadow-none hover:bg-teal-700 active:scale-95 transition-all"
                                    >
                                        XEM LỜI GIẢI
                                    </button>
                                ) : (
                                    <div className="w-full p-8 bg-emerald-50 dark:bg-emerald-900/30 rounded-3xl border-l-8 border-emerald-500 animate-fade-in">
                                        <div className="font-black text-emerald-600 dark:text-emerald-400 text-2xl uppercase mb-4 tracking-tighter">Lời giải chi tiết:</div>
                                        <div className="text-3xl font-medium leading-relaxed">
                                            <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Quote Footer in Slide Mode */}
                        <div className="mt-20 pt-10 border-t border-slate-200 dark:border-slate-800 w-full flex flex-col items-center opacity-30">
                            <Quote className="w-12 h-12 mb-4" />
                            <p className="text-center italic text-xl">"Dùng kiến thức để khai phóng tương lai"</p>
                        </div>
                    </div>

                    <div className="p-8 flex justify-between items-center bg-slate-900/10 dark:bg-slate-950/30 no-print">
                        <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-5 rounded-full bg-white dark:bg-slate-800 shadow-xl hover:bg-teal-600 hover:text-white transition-all disabled:opacity-20 active:scale-90"><ChevronLeft className="w-10 h-10"/></button>

                        <div className="flex flex-col items-center">
                            <div className="flex gap-2 mb-2">
                                {slides.map((_, i) => (
                                    <div key={i} className={`h-1.5 rounded-full transition-all duration-300 ${currentSlide === i ? 'w-8 bg-teal-500' : 'w-2 bg-slate-300 dark:bg-slate-700'}`} />
                                ))}
                            </div>
                            <div className="text-slate-400 font-black text-xs uppercase tracking-widest">NỘI DUNG {currentSlide + 1} / {slides.length}</div>
                        </div>

                        <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-5 rounded-full bg-white dark:bg-slate-800 shadow-xl hover:bg-teal-600 hover:text-white transition-all disabled:opacity-20 active:scale-90"><ChevronRight className="w-10 h-10"/></button>
                    </div>
                </div>
            )}
        </main>

        {/* Dynamic Dock (Floating Controls) */}
        {viewMode === 'slide' && !isFullscreen && (
            <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-1.5 flex gap-1 z-[100] border border-white/20 shadow-2xl items-center no-print">
                <button onClick={() => setShowNav(!showNav)} className={`p-3 rounded-full transition-all ${showNav ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-white/10'}`} title="Mục lục bài giảng"><LayoutGrid className="w-5 h-5"/></button>
                <button onClick={() => setShowBlackboard(true)} className="p-3 rounded-full text-slate-400 hover:text-yellow-400 hover:bg-white/10 transition-all" title="Bảng đen giảng bài"><PenTool className="w-5 h-5"/></button>
                <button onClick={() => setShowRandomPicker(true)} className="p-3 rounded-full text-slate-400 hover:text-indigo-400 hover:bg-white/10 transition-all" title="Gọi số ngẫu nhiên"><Dices className="w-5 h-5"/></button>
                <button onClick={() => setIsLaserPointer(!isLaserPointer)} className={`p-3 rounded-full transition-all ${isLaserPointer ? 'bg-red-600 text-white shadow-lg shadow-red-500/50' : 'text-slate-400 hover:text-white hover:bg-white/10'}`} title="Laser trình chiếu"><MousePointer2 className="w-5 h-5"/></button>

                <div className="w-px h-6 bg-white/20 mx-1"></div>

                <div className="flex items-center gap-1 bg-black/40 rounded-full px-2 py-0.5">
                    <button onClick={() => setZoomLevel(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-400 hover:text-white transition-colors" title="Thu nhỏ"><ZoomOut className="w-4 h-4"/></button>
                    <div className="flex flex-col items-center min-w-[50px]">
                        <span className="text-[10px] font-black text-white/50 uppercase leading-none mb-0.5">Cỡ chữ</span>
                        <span className="text-xs font-black text-white leading-none">{Math.round(zoomLevel*100)}%</span>
                    </div>
                    <button onClick={() => setZoomLevel(z => Math.min(3.0, z + 0.1))} className="p-2 text-slate-400 hover:text-white transition-colors" title="Phóng to (tối đa 300%)"><ZoomIn className="w-4 h-4"/></button>
                </div>

                <button onClick={() => setIsDockExpanded(!isDockExpanded)} className="p-2 text-slate-500 hover:text-white ml-1 transition-all"><ChevronDown className={`w-4 h-4 transition-transform duration-500 ${!isDockExpanded ? 'rotate-180' : ''}`}/></button>
            </div>
        )}

        {/* Modals & Tools */}
        {showBlackboard && <Blackboard onClose={() => setShowBlackboard(false)} mode={blackboardMode} onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
        {showNav && (
            <div className="fixed inset-0 z-[60] bg-black/50 backdrop-blur-sm flex items-end sm:items-center justify-center p-4 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[40px] w-full max-w-xl shadow-2xl border border-slate-200 dark:border-slate-700 animate-fade-in-up" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-8">
                        <div>
                            <h3 className="font-black text-2xl text-slate-800 dark:text-white">Mục lục Slide</h3>
                            <p className="text-sm text-slate-400 font-medium">Chọn slide để di chuyển nhanh</p>
                        </div>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-50 dark:bg-slate-900 rounded-2xl text-slate-400 hover:text-red-500 transition-colors"><X className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 max-h-[50vh] overflow-y-auto p-2 custom-scrollbar">
                        {slides.map((s, i) => (
                            <button 
                                key={i} 
                                onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} 
                                className={`p-4 rounded-2xl font-bold text-sm transition-all text-left border-2 
                                    ${currentSlide === i 
                                        ? 'bg-teal-600 text-white border-teal-600 shadow-xl shadow-teal-200 dark:shadow-none scale-105' 
                                        : 'bg-slate-50 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border-transparent hover:border-teal-200 dark:hover:border-teal-500'
                                    }`}
                            >
                                <span className="block text-[10px] opacity-60 uppercase mb-1">Slide {i+1}</span>
                                <span className="line-clamp-2">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {isLaserPointer && <div className="fixed w-4 h-4 bg-red-600 rounded-full blur-[2px] shadow-[0_0_15px_#dc2626] pointer-events-none z-[200] opacity-80" style={{ left: '-100px', top: '-100px' }} id="laser-pointer-dot-lecture" />}
        {isLaserPointer && <script>{`
            document.addEventListener('mousemove', (e) => {
                const dot = document.getElementById('laser-pointer-dot-lecture');
                if (dot) {
                    dot.style.left = (e.clientX - 8) + 'px';
                    dot.style.top = (e.clientY - 8) + 'px';
                }
            });
        `}</script>}
    </div>
  );
};

