                    <button onClick={() => setViewMode('slide')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-teal-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 transition-colors">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full ${isSidePanelOpen && viewMode === 'slide' ? 'w-1/2 overflow-y-auto border-r-4 border-teal-100' : 'w-full'}`}>
                {viewMode === 'doc' ? (
                    <div className="bg-white p-12 rounded-[3rem] shadow-sm animate-fade-in">
                        {data.sections.map((s, i) => (
                            <div key={i} className="mb-20">
                                <h2 className="text-4xl font-black mb-10 border-b-8 border-teal-500 inline-block pb-4">{i+1}. {s.title}</h2>
                                <div className="space-y-6 text-2xl leading-relaxed"><MathRenderer content={s.content}/></div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-12 md:p-24 ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className="w-full mb-12 pb-8 border-b-8 border-teal-500 flex justify-between items-end">
                            <h2 className="text-6xl md:text-7xl font-black text-teal-700 leading-tight">{slides[currentSlide].title}</h2>
                            <span className="text-sm font-black text-teal-300 uppercase tracking-widest">SLIDE {currentSlide + 1}</span>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-4xl md:text-5xl leading-relaxed space-y-10 w-full animate-fade-in font-medium">
                                <MathRenderer content={slides[currentSlide].content}/>
                            </div>
                        ) : (
                            <div className="w-full bg-white p-16 rounded-[4rem] border-8 border-teal-200 shadow-[0_50px_100px_rgba(0,0,0,0.1)] animate-fade-in-up">
                                <h3 className="text-4xl font-black text-teal-700 mb-10 uppercase tracking-tighter">Ví dụ tiêu biểu</h3>
                                <div className="text-3xl md:text-4xl mb-12 font-semibold leading-relaxed"><MathRenderer content={slides[currentSlide].examples[0].problem}/></div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-16 py-8 bg-teal-600 text-white font-black text-3xl rounded-[3rem] shadow-2xl hover:bg-teal-700 active:scale-95 transition-all">HIỂN THỊ LỜI GIẢI</button>
                                ) : (
                                    <div className="w-full p-10 bg-emerald-50 rounded-[3rem] border-l-[1rem] border-emerald-500 animate-fade-in text-3xl leading-relaxed">
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>

            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 relative z-40">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-24 left-10 right-10 flex justify-between items-center pointer-events-none z-50">
                    <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-teal-50"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-teal-50"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white transition-colors" title="Mục lục"><LayoutGrid className="w-6 h-6"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400 transition-colors" title="Bảng đen"><PenTool className="w-6 h-6"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400 transition-colors" title="Gọi số"><Dices className="w-6 h-6"/></button>
            <div className="w-px h-8 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={() => setZoomLevel(z => Math.max(0.8, z-0.2))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-5 h-5"/></button>
                <span className="text-sm font-black text-white w-12 text-center">{Math.round(zoomLevel*100)}%</span>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.2))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-5 h-5"/></button>
            </div>
        </div>

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/40 flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white p-12 rounded-[4rem] w-full max-w-3xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 text-slate-800 uppercase tracking-tighter">Mục lục Slide</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} className={`p-6 rounded-3xl text-left border-4 transition-all ${currentSlide === i ? 'bg-teal-600 border-teal-600 text-white shadow-xl scale-105' : 'bg-slate-50 border-transparent hover:border-teal-100'}`}>
                                <span className="block text-xs font-black opacity-50 mb-2">SLIDE {i+1}</span>
                                <span className="font-bold text-lg leading-tight line-clamp-2">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

