import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import { Printer, CheckCircle, Eye, EyeOff, Lightbulb, ChevronDown, ChevronRight, FileText, Download, FileSignature, Save, LayoutGrid, ArrowUp, X, Menu, PenTool, Maximize, Minimize, RefreshCw, User, Trophy, Send, XCircle, Star, MonitorPlay, MousePointer2, ZoomIn, ZoomOut, ChevronLeft, ArrowRight, ArrowLeft, Trash2, Edit, Target, Dices, Smile, Frown, Award, PartyPopper, RotateCcw, Key, ChevronUp, Quote, Lock, Volume2, StopCircle, Presentation as PresentationIcon, Timer as TimerIcon, Clock, Bot, Baby, Brain, ListChecks, Hourglass, BellRing, Check, ToggleLeft, ToggleRight, Medal, LogIn, Settings, Languages, Rabbit, Turtle, Ear } from 'lucide-react';
import MathRenderer from './MathRenderer';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } from 'docx';
import FileSaver from 'file-saver';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { parseContentToDocx } from '../utils/docxUtils';

interface ExamPreviewProps {
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const STUDY_QUOTES = [
  "Học, học nữa, học mãi. – V.I. Lenin",
  "Đường đi khó, không khó vì ngăn sông cách núi, mà khó vì lòng người ngại núi e sông. – Nguyễn Thái Học",
  "Hiền tài là nguyên khí của quốc gia. – Thân Nhân Trung",
  "Trên bước đường thành công không có dấu chân của kẻ lười biếng. – Lỗ Tấn",
  "Học tập là hạt giống của kiến thức, kiến thức là hạt giống của hạnh phúc.",
  "Muốn biết phải hỏi, muốn giỏi phải học.",
  "Kiến thức là kho báu, nhưng thực hành là chìa khóa để mở nó."
];

const VOICE_PROFILES = [
    { name: 'Nữ', pitch: 1.0, rate: 1.0, icon: <Volume2 className="w-5 h-5" /> },
    { name: 'Nam', pitch: 0.8, rate: 0.9, icon: <Bot className="w-5 h-5" /> },
    { name: 'Trẻ em', pitch: 1.6, rate: 1.1, icon: <Baby className="w-5 h-5" /> }
];

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(false);
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [speakingId, setSpeakingId] = useState<number | null>(null);
  const [ttsConfig, setTtsConfig] = useState({ lang: 'vi-VN', voiceIdx: 0, rate: 1.0 });
  const [activeSettingsId, setActiveSettingsId] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
        setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false));
    }
  };

  const handleStartExam = () => { if (studentName.trim()) setIsStarted(true); };

  // Fix: changed oIdx type to any to allow string values for essay answers
  const handleOptionSelect = (qIdx: number, oIdx: any) => {
    if (isSubmitted) return;
    setUserAnswers(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  const handleTFSelect = (qIdx: number, oIdx: number, val: boolean) => {
    if (isSubmitted) return;
    setUserAnswers(prev => {
      const current = prev[qIdx] || {};
      return { ...prev, [qIdx]: { ...current, [oIdx]: val } };
    });
  };

  const handleSubmitExam = () => {
    setIsSubmitted(true);
    setShowScoreModal(true);
    setIsTimerRunning(false);
  };

  // Fix: implemented missing calculateScore function
  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE) {
        const correctChar = q.correctAnswer.trim().charAt(0).toUpperCase();
        const userChar = ['A', 'B', 'C', 'D'][userAns as number];
        if (userChar === correctChar) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        ['a', 'b', 'c', 'd'].forEach((label, i) => {
          const isUserTrue = userAns[i] === true;
          const isUserFalse = userAns[i] === false;
          const isCorrectTrue = correctStr.includes(`${label}) đ`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}-đ`) || correctStr.includes(`${label}: đúng`);
          const isCorrectFalse = correctStr.includes(`${label}) s`) || correctStr.includes(`${label}: s`) || correctStr.includes(`${label}-s`) || correctStr.includes(`${label}: sai`);
          if ((isUserTrue && isCorrectTrue) || (isUserFalse && isCorrectFalse)) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.toString().trim().toLowerCase()) {
          rawScore += 1;
        }
      }
    });
    return { score: ((rawScore / (questions.length || 1)) * 10).toFixed(1) };
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const userAns = userAnswers[idx];
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

    return (
      <div 
        className={`flex flex-col h-full bg-white dark:bg-slate-900 transition-all ${isSlide ? 'p-12 md:p-20 items-start justify-start' : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`}
        style={{ fontSize: `${zoomLevel * 100}%` }}
      >
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center gap-4 mb-8 no-print">
                <span className="w-14 h-14 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-3xl shadow-xl">{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">{q.difficulty}</span>
            </div>

            <div className="text-4xl md:text-5xl font-bold text-slate-900 dark:text-slate-100 mb-12 leading-tight border-l-8 border-indigo-600 pl-8 py-2">
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-6 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options?.map((o, oi) => (
                    <button 
                        key={oi} 
                        onClick={() => handleOptionSelect(idx, oi)}
                        className={`group flex items-start gap-5 p-6 rounded-[2rem] border-4 transition-all text-left
                            ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:scale-[1.02]`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-2xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg} text-white`}`}>
                            {['A','B','C','D'][oi]}
                        </span>
                        <div className="text-2xl md:text-3xl font-medium pt-1"><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {q.type === QuestionType.TRUE_FALSE && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 bg-slate-50 dark:bg-slate-800 rounded-3xl border-2 border-slate-200 dark:border-slate-700">
                        <div className="text-xl md:text-2xl font-bold mb-4 flex gap-2">
                            <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                            <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                            <button onClick={() => handleTFSelect(idx, oi, true)} className={`flex-1 py-3 rounded-xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-white text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                            <button onClick={() => handleTFSelect(idx, oi, false)} className={`flex-1 py-3 rounded-xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-lg' : 'bg-white text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}

                {q.type === QuestionType.ESSAY && (
                    <div className="col-span-full">
                        <input 
                            type="text"
                            placeholder="Nhập kết quả..."
                            value={userAnswers[idx] || ''}
                            onChange={(e) => handleOptionSelect(idx, e.target.value)}
                            className="w-full max-w-lg p-6 text-5xl font-black text-center bg-slate-100 dark:bg-slate-800 border-4 border-dashed border-indigo-200 dark:border-indigo-700 rounded-[2.5rem] outline-none focus:border-indigo-600 transition-all uppercase"
                        />
                    </div>
                )}
            </div>

            {(showAnswers || activeSolutions[q.id]) && (
                <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-3xl font-black text-emerald-700 mb-6 flex items-center gap-3"><CheckCircle className="w-10 h-10" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="h-1 bg-emerald-100 mb-8 rounded-full"></div>
                    <div className="text-2xl md:text-3xl leading-relaxed text-slate-800 dark:text-slate-200"><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[3rem] shadow-[0_30px_60px_rgba(0,0,0,0.1)] max-w-md w-full text-center border-4 border-indigo-50">
            <User className="w-24 h-24 text-indigo-600 mx-auto mb-8 bg-indigo-50 p-5 rounded-[2rem]" />
            <h2 className="text-3xl font-black mb-8 dark:text-white">Chào mừng bạn đến với kỳ thi</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="NHẬP HỌ VÀ TÊN..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-8 border-4 border-transparent focus:border-indigo-600 outline-none transition-all" />
            <button onClick={handleStartExam} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all">BẮT ĐẦU NGAY</button>
            {/* Fix: removed call to undefined setIsEditMode */}
            <button onClick={() => { setIsStarted(true); }} className="mt-8 text-slate-400 font-bold hover:text-indigo-600 transition-colors">CHẾ ĐỘ GIÁO VIÊN</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><ArrowLeft className="w-6 h-6"/></button>
                <div>
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white">{config.topic}</h1>
                    <div className="flex gap-4 text-xs font-black text-slate-400 uppercase tracking-widest">
                        <span>{config.subject}</span>
                        <span>•</span>
                        <span>{config.grade}</span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-6">
                {timer !== null && (
                    <div className={`flex items-center gap-3 px-6 py-2.5 rounded-full font-black text-2xl border-4 ${timer < 60 ? 'bg-red-50 border-red-500 text-red-600 animate-pulse' : 'bg-slate-50 border-slate-200 text-slate-700'}`}>
                        <Clock className="w-6 h-6" /> {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                )}
                <div className="flex gap-2 p-1 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={handleSubmitExam} className="px-8 py-3 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 transition-all">NỘP BÀI</button>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 transition-colors">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-8 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full ${showBlackboard && blackboardMode === 'side' ? 'w-1/2 overflow-y-auto border-r-4 border-indigo-100' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
            </div>

            {showBlackboard && blackboardMode === 'side' && (
                <div className="w-1/2 h-full bg-slate-800 relative z-40">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-24 left-10 right-10 flex justify-between items-center pointer-events-none z-50">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="p-6 bg-white shadow-2xl rounded-[2.5rem] pointer-events-auto disabled:opacity-20 border-4 border-indigo-50"><ChevronLeft className="w-12 h-12"/></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="p-6 bg-white shadow-2xl rounded-[2.5rem] pointer-events-auto disabled:opacity-20 border-4 border-indigo-50"><ChevronRight className="w-12 h-12"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white transition-colors" title="Mục lục"><LayoutGrid className="w-6 h-6"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400 transition-colors" title="Bảng đen"><PenTool className="w-6 h-6"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400 transition-colors" title="Gọi số"><Dices className="w-6 h-6"/></button>
            <div className="w-px h-8 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={() => setZoomLevel(z => Math.max(0.8, z-0.2))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-5 h-5"/></button>
                <span className="text-sm font-black text-white w-12 text-center">{Math.round(zoomLevel*100)}%</span>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.2))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-5 h-5"/></button>
            </div>
            <div className="w-px h-8 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className="p-3 text-slate-400 hover:text-red-400 transition-colors"><TimerIcon className="w-6 h-6"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-white p-10 rounded-[3rem] shadow-2xl w-full max-w-sm text-center">
                    <h3 className="text-2xl font-black mb-8">THỜI GIAN LÀM BÀI</h3>
                    <div className="grid grid-cols-3 gap-4 mb-8">
                        {[15, 30, 45, 60, 90, 120].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-4 bg-slate-50 hover:bg-indigo-600 hover:text-white rounded-2xl font-black transition-all border-2 border-slate-100">{m}P</button>
                        ))}
                    </div>
                    <button onClick={() => setShowTimerMenu(false)} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black">HỦY BỎ</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/40 flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white p-10 rounded-[3rem] w-full max-w-2xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 text-slate-800">DANH MỤC CÂU HỎI</h3>
                    <div className="grid grid-cols-5 md:grid-cols-8 gap-3">
                        {questions.map((_, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setShowNav(false); }} className={`h-16 rounded-2xl font-black text-xl border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-110' : 'bg-slate-50 border-transparent hover:border-indigo-100'}`}>{i+1}</button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-xl flex items-center justify-center p-6">
                <div className="bg-white p-12 rounded-[4rem] max-w-md w-full text-center shadow-[0_50px_100px_rgba(0,0,0,0.5)] border-t-[1rem] border-indigo-600">
                    <Trophy className="w-24 h-24 text-yellow-500 mx-auto mb-8 animate-bounce" />
                    <h2 className="text-6xl font-black text-indigo-600 mb-2">{calculateScore().score}/10</h2>
                    <p className="text-slate-500 font-black uppercase tracking-widest text-lg mb-10">Kết quả của {studentName}</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black text-xl hover:bg-indigo-700 transition-all shadow-2xl">XEM LỜI GIẢI CHI TIẾT</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import { Printer, CheckCircle, Eye, EyeOff, Lightbulb, ChevronDown, ChevronRight, FileText, Download, FileSignature, Save, LayoutGrid, ArrowUp, X, Menu, PenTool, Maximize, Minimize, RefreshCw, User, Trophy, Send, XCircle, Star, MonitorPlay, MousePointer2, ZoomIn, ZoomOut, ChevronLeft, ArrowRight, ArrowLeft, Trash2, Edit, Target, Dices, Smile, Frown, Award, PartyPopper, RotateCcw, Key, ChevronUp, Quote, Lock, Volume2, StopCircle, Presentation as PresentationIcon, Timer as TimerIcon, Clock, Bot, Baby, Brain, ListChecks, Hourglass, BellRing, Check, ToggleLeft, ToggleRight, Medal, LogIn, Settings, Languages, Rabbit, Turtle, Ear } from 'lucide-react';
import MathRenderer from './MathRenderer';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } from 'docx';
import FileSaver from 'file-saver';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { parseContentToDocx } from '../utils/docxUtils';

interface ExamPreviewProps {
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { 
    bg: 'bg-blue-50 dark:bg-blue-900/30', 
    border: 'border-blue-300 dark:border-blue-700', 
    text: 'text-blue-900 dark:text-blue-100', 
    labelBg: 'bg-blue-600 text-white shadow-lg shadow-blue-500/30'
  },
  { 
    bg: 'bg-emerald-50 dark:bg-emerald-900/30', 
    border: 'border-emerald-300 dark:border-emerald-700', 
    text: 'text-emerald-900 dark:text-emerald-100', 
    labelBg: 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/30'
  },
  { 
    bg: 'bg-amber-50 dark:bg-amber-900/30', 
    border: 'border-amber-300 dark:border-amber-700', 
    text: 'text-amber-900 dark:text-amber-100', 
    labelBg: 'bg-amber-600 text-white shadow-lg shadow-amber-500/30'
  },
  { 
    bg: 'bg-rose-50 dark:bg-rose-900/30', 
    border: 'border-rose-300 dark:border-rose-700', 
    text: 'text-rose-900 dark:text-rose-100', 
    labelBg: 'bg-rose-600 text-white shadow-lg shadow-rose-500/30'
  }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(false);
  const [activeSolutions, setActiveSolutions] = useState<Record<number, boolean>>({});
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 2x theo yêu cầu
  const [isStarted, setIsStarted] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  // Timer logic
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0));
      }, 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false));
    }
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE) {
        const correctChar = q.correctAnswer.trim().charAt(0).toUpperCase();
        const userChar = ['A', 'B', 'C', 'D'][userAns as number];
        if (userChar === correctChar) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        ['a', 'b', 'c', 'd'].forEach((label, i) => {
          const isUserTrue = userAns[i] === true;
          const isUserFalse = userAns[i] === false;
          const isCorrectTrue = correctStr.includes(`${label}) đ`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}-đ`) || correctStr.includes(`${label}: đúng`);
          const isCorrectFalse = correctStr.includes(`${label}) s`) || correctStr.includes(`${label}: s`) || correctStr.includes(`${label}-s`) || correctStr.includes(`${label}: sai`);
          if ((isUserTrue && isCorrectTrue) || (isUserFalse && isCorrectFalse)) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.toString().trim().toLowerCase()) {
          rawScore += 1;
        }
      }
    });
    return { score: ((rawScore / (questions.length || 1)) * 10).toFixed(1) };
  };

  const handleStartExam = () => { if (studentName.trim()) setIsStarted(true); };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const userAns = userAnswers[idx];
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

    // Slide mode specific layout: Question at top, justify-start
    const slideClass = isSlide 
      ? `p-8 md:p-16 items-start justify-start w-full transition-all duration-500 ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    return (
      <div 
        className={`flex flex-col bg-white dark:bg-slate-900 overflow-y-auto custom-scrollbar ${slideClass}`}
        style={{ fontSize: `${zoomLevel * 100}%` }}
      >
        <div className="w-full flex flex-col items-start text-left">
            {/* Header / Question Number */}
            <div className="flex items-center gap-4 mb-6 no-print">
                <span className="w-12 h-12 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-lg">
                    {idx + 1}
                </span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">
                    {q.difficulty}
                </span>
            </div>

            {/* Question Text - Stays at TOP */}
            <div className="text-4xl md:text-5xl font-extrabold text-slate-900 dark:text-slate-100 mb-10 leading-[1.2] border-l-8 border-indigo-600 pl-6 py-1">
                <MathRenderer content={q.content} />
            </div>

            {/* Options Area */}
            <div className={`w-full grid gap-6 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options?.map((o, oi) => (
                    <button 
                        key={oi} 
                        onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))}
                        className={`group flex items-start gap-4 p-6 rounded-3xl border-4 transition-all text-left shadow-sm
                            ${userAns === oi 
                                ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' 
                                : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400 hover:scale-[1.01]`}`}
                    >
                        <span className={`w-10 h-10 flex-shrink-0 rounded-xl flex items-center justify-center font-black text-xl shadow-md ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>
                            {['A','B','C','D'][oi]}
                        </span>
                        <div className={`text-2xl md:text-3xl font-semibold pt-0.5 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`}>
                            <MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline />
                        </div>
                    </button>
                ))}

                {q.type === QuestionType.TRUE_FALSE && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 bg-slate-50 dark:bg-slate-800 rounded-3xl border-2 border-slate-200 dark:border-slate-700">
                        <div className="text-xl md:text-2xl font-bold mb-4 flex gap-2">
                            <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                            <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                            <button 
                                onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} 
                                className={`flex-1 py-3 rounded-xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-white text-emerald-600 border-emerald-200'}`}
                            >
                                ĐÚNG
                            </button>
                            <button 
                                onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} 
                                className={`flex-1 py-3 rounded-xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-lg' : 'bg-white text-red-600 border-red-200'}`}
                            >
                                SAI
                            </button>
                        </div>
                    </div>
                ))}

                {q.type === QuestionType.ESSAY && (
                    <div className="col-span-full">
                        <input 
                            type="text"
                            placeholder="Nhập kết quả..."
                            value={userAnswers[idx] || ''}
                            onChange={(e) => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: e.target.value }))}
                            className="w-full max-w-lg p-6 text-5xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 dark:border-indigo-700 rounded-[2.5rem] outline-none focus:border-indigo-600 transition-all uppercase"
                        />
                    </div>
                )}
            </div>

            {/* Answer & Solution Overlay */}
            {(showAnswers || activeSolutions[q.id]) && (
                <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-3xl font-black text-emerald-700 mb-6 flex items-center gap-3">
                        <CheckCircle className="w-10 h-10" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline />
                    </h4>
                    <div className="h-1 bg-emerald-100 mb-8 rounded-full"></div>
                    <div className="text-2xl md:text-3xl leading-relaxed text-slate-800 dark:text-slate-200 font-medium">
                        <MathRenderer content={q.solution} />
                    </div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[3rem] shadow-[0_30px_60px_rgba(0,0,0,0.1)] max-w-md w-full text-center border-4 border-indigo-50">
            <User className="w-24 h-24 text-indigo-600 mx-auto mb-8 bg-indigo-50 p-5 rounded-[2rem]" />
            <h2 className="text-3xl font-black mb-8 dark:text-white uppercase tracking-tighter">Bắt đầu Bài tập</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-8 border-4 border-transparent focus:border-indigo-600 outline-none transition-all" />
            <button onClick={handleStartExam} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all">VÀO THI NGAY</button>
            <button onClick={() => { setIsStarted(true); }} className="mt-8 text-slate-400 font-bold hover:text-indigo-600 transition-colors uppercase text-sm tracking-widest">Giao diện Giáo viên</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-2xl transition-all"><ArrowLeft className="w-6 h-6 text-slate-500"/></button>
                <div>
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase">{config.topic}</h1>
                    <div className="flex gap-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                        <span>{config.subject}</span>
                        <span>•</span>
                        <span>{config.grade}</span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <div className="flex gap-2 p-1 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-8 py-3 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 transition-all uppercase text-sm">Nộp bài</button>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-8 max-w-5xl mx-auto w-full'}`}>
            {/* Main Content Area */}
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' 
                  ? questions.map((q, i) => renderQuestionCard(q, i, false)) 
                  : renderQuestionCard(questions[currentSlide], currentSlide, true)}

                {/* Giant Timer at bottom (Slide Mode) */}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-32 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-12 py-6 rounded-[3rem] font-black text-7xl md:text-9xl border-8 shadow-[0_30px_60px_rgba(0,0,0,0.3)] backdrop-blur-xl animate-bounce-slow
                      ${timer <= 10 
                        ? 'bg-red-600/90 border-white text-white animate-pulse' 
                        : 'bg-white/90 dark:bg-slate-800/90 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>

            {/* Side Blackboard */}
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-4 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {/* Slide Navigation Overlay */}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-6 bg-white shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-indigo-50 hover:scale-110 active:scale-90 transition-all"><ChevronLeft className="w-12 h-12 text-indigo-600"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-6 bg-white shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-indigo-50 hover:scale-110 active:scale-90 transition-all"><ChevronRight className="w-12 h-12 text-indigo-600"/></button>
                </div>
            )}
        </main>

        {/* Global Control Dock */}
