import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation as PresentationIcon, FileText, Printer, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut, RefreshCw, Palette, Star, Eye, EyeOff, Lightbulb, BookOpen, Download, Save, Quote, MonitorPlay, Timer as TimerIcon, Clock } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } from 'docx';
import FileSaver from 'file-saver';
import { parseContentToDocx } from '../utils/docxUtils';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { name: 'Xanh Ngọc', bg: 'bg-teal-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-teal-700 dark:text-teal-400', border: 'border-teal-500' },
  blue: { name: 'Xanh Dương', bg: 'bg-blue-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-blue-700 dark:text-blue-400', border: 'border-blue-500' },
  violet: { name: 'Tím Mộng Mơ', bg: 'bg-violet-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-violet-700 dark:text-violet-400', border: 'border-violet-500' }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 2x
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showNav, setShowNav] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => setShowExampleSolution(false), [currentSlide, slideStep]);

  // Timer logic
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false));
    }
  };

  const theme = SLIDE_THEMES[activeTheme];
  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 h-20 flex justify-between items-center px-8 no-print sticky top-0 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><RotateCcw className="w-6 h-6 text-slate-500"/></button>
                <h1 className="text-2xl font-black dark:text-white truncate max-w-md uppercase tracking-tighter">{data.topic}</h1>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-2xl">
                    <button onClick={() => setViewMode('doc')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'doc' ? 'bg-white shadow-lg text-teal-600' : 'text-slate-400'}`}><FileText className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-teal-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${isSidePanelOpen && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'doc' ? (
                    <div className="bg-white p-12 rounded-[3rem] shadow-sm animate-fade-in">
                        {data.sections.map((s, i) => (
                            <div key={i} className="mb-20">
                                <h2 className="text-4xl font-black mb-10 border-b-8 border-teal-500 inline-block pb-4 uppercase tracking-tighter">{i+1}. {s.title}</h2>
                                <div className="space-y-6 text-2xl leading-relaxed font-medium"><MathRenderer content={s.content}/></div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-12 md:p-24 overflow-y-auto custom-scrollbar ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        {/* Title Bar - Always at TOP */}
                        <div className="w-full mb-10 pb-6 border-b-8 border-teal-500 flex justify-between items-end">
                            <h2 className="text-6xl md:text-7xl font-black text-teal-700 leading-tight uppercase tracking-tighter">{slides[currentSlide].title}</h2>
                            <span className="text-sm font-black text-teal-300 uppercase tracking-widest px-4 py-1 bg-white rounded-full shadow-sm mb-2">Trang {currentSlide + 1}</span>
                        </div>

                        {/* Content Area */}
                        {slideStep === 1 ? (
                            <div className="text-4xl md:text-5xl leading-relaxed space-y-10 w-full animate-fade-in font-semibold text-slate-800 dark:text-slate-100">
                                <MathRenderer content={slides[currentSlide].content}/>
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-8 border-teal-200 shadow-[0_50px_100px_rgba(0,0,0,0.1)] animate-fade-in-up">
                                <h3 className="text-4xl font-black text-teal-700 dark:text-teal-400 mb-10 uppercase tracking-tighter flex items-center gap-4"><Star className="w-10 h-10 fill-current" /> Ví dụ Tiêu biểu</h3>
                                <div className="text-3xl md:text-4xl mb-12 font-bold leading-relaxed text-slate-800 dark:text-slate-100">
                                    <MathRenderer content={slides[currentSlide].examples[0].problem}/>
                                </div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-16 py-8 bg-teal-600 text-white font-black text-3xl rounded-[3rem] shadow-2xl hover:bg-teal-700 active:scale-95 transition-all uppercase tracking-tighter">Hiển thị Hướng dẫn</button>
                                ) : (
                                    <div className="w-full p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-l-[1rem] border-emerald-500 animate-fade-in text-3xl leading-relaxed font-medium">
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Giant Timer for Slide Mode */}
                        {viewMode === 'slide' && timer !== null && (
                          <div className="fixed bottom-36 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                            <div className={`px-16 py-8 rounded-[4rem] font-black text-8xl md:text-[10rem] border-8 shadow-2xl backdrop-blur-2xl animate-bounce-slow
                              ${timer <= 10 
                                ? 'bg-red-600/90 border-white text-white animate-pulse' 
                                : 'bg-white/90 dark:bg-slate-800/90 border-teal-600 text-teal-600 dark:text-teal-400'}`}>
                              {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                            </div>
                          </div>
                        )}
                    </div>
                )}
            </div>

            {/* Side Panel Blackboard */}
            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-4 border-teal-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {/* Slide Navigation Overlay */}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-teal-50 hover:scale-110 active:scale-90 transition-all"><ChevronLeft className="w-16 h-16 text-teal-600"/></button>
                    <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-teal-50 hover:scale-110 active:scale-90 transition-all"><ChevronRight className="w-16 h-16 text-teal-600"/></button>
                </div>
            )}
        </main>

        {/* Global Control Bar */}
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white transition-colors" title="Mục lục bài giảng"><LayoutGrid className="w-6 h-6"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400 transition-colors" title="Bảng giảng bài"><PenTool className="w-6 h-6"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400 transition-colors" title="Gọi số ngẫu nhiên"><Dices className="w-6 h-6"/></button>

            <div className="w-px h-8 bg-white/20 mx-2"></div>

            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={() => setZoomLevel(z => Math.max(1.0, z-0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-5 h-5"/></button>
                <div className="flex flex-col items-center min-w-[50px]">
                    <span className="text-[10px] font-black text-white/50 uppercase leading-none">Cỡ</span>
                    <span className="text-sm font-black text-white">{Math.round(zoomLevel)}x</span>
                </div>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-5 h-5"/></button>
            </div>

            <div className="w-px h-8 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-3 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ bài giảng"><TimerIcon className="w-6 h-6"/></button>
        </div>

        {/* Timer Selection Modal */}
        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl w-full max-w-sm text-center border-4 border-teal-50">
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter">Bấm giờ Bài giảng</h3>
                    <div className="grid grid-cols-3 gap-4 mb-8">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-5 bg-slate-50 dark:bg-slate-700 hover:bg-teal-600 hover:text-white rounded-3xl font-black text-2xl transition-all border-4 border-transparent hover:border-white">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-black border-2 border-red-200 uppercase tracking-widest text-xs">Hủy bỏ</button>
                    </div>
                </div>
            </div>
        )}

        {/* Navigation Sidebar / Menu */}
        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/40 flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-10 rounded-[4rem] w-full max-w-3xl shadow-2xl border-4 border-teal-50" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 text-slate-800 dark:text-white uppercase tracking-tighter">Mục lục Slide</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setTimer(null); setIsTimerRunning(false); setShowNav(false); }} className={`p-6 rounded-3xl text-left border-4 transition-all ${currentSlide === i ? 'bg-teal-600 border-teal-600 text-white shadow-xl scale-105' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-teal-100 text-slate-400'}`}>
                                <span className="block text-[10px] font-black opacity-50 mb-2 uppercase">Slide {i+1}</span>
                                <span className="font-bold text-lg leading-tight line-clamp-2">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

