  const [isStarted, setIsStarted] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0));
      }, 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false));
    }
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE) {
        const correctChar = q.correctAnswer.trim().charAt(0).toUpperCase();
        const userChar = ['A', 'B', 'C', 'D'][userAns as number];
        if (userChar === correctChar) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        ['a', 'b', 'c', 'd'].forEach((label, i) => {
          const isUserTrue = userAns[i] === true;
          const isUserFalse = userAns[i] === false;
          const isCorrectTrue = correctStr.includes(`${label}) đ`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}-đ`) || correctStr.includes(`${label}: đúng`);
          const isCorrectFalse = correctStr.includes(`${label}) s`) || correctStr.includes(`${label}: s`) || correctStr.includes(`${label}-s`) || correctStr.includes(`${label}: sai`);
          if ((isUserTrue && isCorrectTrue) || (isUserFalse && isCorrectFalse)) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.toString().trim().toLowerCase()) {
          rawScore += 1;
        }
      }
    });
    return { score: ((rawScore / (questions.length || 1)) * 10).toFixed(1) };
  };

  const handleStartExam = () => { if (studentName.trim()) setIsStarted(true); };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const userAns = userAnswers[idx];
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

    const slideClass = isSlide 
      ? `p-8 md:p-16 items-start justify-start w-full transition-all duration-500 overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    return (
      <div 
        className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar ${slideClass}`}
        style={{ fontSize: `${zoomLevel * 100}%` }}
      >
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center gap-4 mb-8 no-print">
                <span className="w-14 h-14 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-3xl shadow-xl">
                    {idx + 1}
                </span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">
                    {q.difficulty}
                </span>
            </div>

            <div className="text-4xl md:text-5xl font-extrabold text-slate-900 dark:text-slate-100 mb-12 leading-[1.2] border-l-8 border-indigo-600 pl-8 py-2">
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options?.map((o, oi) => (
                    <button 
                        key={oi} 
                        onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))}
                        className={`group flex items-start gap-6 p-8 rounded-[2.5rem] border-4 transition-all text-left shadow-md
                            ${userAns === oi 
                                ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' 
                                : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400 hover:scale-[1.01]`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-2xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>
                            {['A','B','C','D'][oi]}
                        </span>
                        <div className={`text-2xl md:text-3xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`}>
                            <MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline />
                        </div>
                    </button>
                ))}

                {q.type === QuestionType.TRUE_FALSE && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-8 bg-slate-50 dark:bg-slate-800 rounded-[2.5rem] border-2 border-slate-200 dark:border-slate-700">
                        <div className="text-2xl md:text-3xl font-bold mb-6 flex gap-3">
                            <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                            <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-6">
                            <button 
                                onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} 
                                className={`flex-1 py-4 rounded-2xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                            >
                                ĐÚNG
                            </button>
                            <button 
                                onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} 
                                className={`flex-1 py-4 rounded-2xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                            >
                                SAI
                            </button>
                        </div>
                    </div>
                ))}

                {q.type === QuestionType.ESSAY && (
                    <div className="col-span-full">
                        <input 
                            type="text"
                            placeholder="Nhập kết quả..."
                            value={userAnswers[idx] || ''}
                            onChange={(e) => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: e.target.value }))}
                            className="w-full max-w-2xl p-8 text-6xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 dark:border-indigo-700 rounded-[3rem] outline-none focus:border-indigo-600 transition-all uppercase"
                        />
                    </div>
                )}
            </div>

            {(showAnswers || activeSolutions[q.id]) && (
                <div className="mt-16 p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-4xl font-black text-emerald-700 mb-8 flex items-center gap-4">
                        <CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline />
                    </h4>
                    <div className="h-1 bg-emerald-100 mb-10 rounded-full"></div>
                    <div className="text-3xl md:text-4xl leading-relaxed text-slate-800 dark:text-slate-200 font-semibold">
                        <MathRenderer content={q.solution} />
                    </div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl max-w-md w-full text-center border-4 border-indigo-50">
            <User className="w-24 h-24 text-indigo-600 mx-auto mb-8 bg-indigo-50 p-6 rounded-[2.5rem]" />
            <h2 className="text-3xl font-black mb-10 dark:text-white uppercase tracking-tighter">Bắt đầu Bài tập</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-8 rounded-3xl bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all" />
            <button onClick={handleStartExam} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all">VÀO THI NGAY</button>
            <button onClick={() => { setIsStarted(true); }} className="mt-8 text-slate-400 font-bold hover:text-indigo-600 transition-colors uppercase text-sm tracking-widest">Giao diện Giáo viên</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-2xl transition-all"><ArrowLeft className="w-6 h-6 text-slate-500"/></button>
                <div>
                    <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase">{config.topic}</h1>
                    <div className="flex gap-4 text-xs font-black text-slate-400 uppercase tracking-widest">
                        <span>{config.subject}</span>
                        <span>•</span>
                        <span>{config.grade}</span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 transition-all uppercase text-lg">Nộp bài</button>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' 
                  ? questions.map((q, i) => renderQuestionCard(q, i, false)) 
                  : renderQuestionCard(questions[currentSlide], currentSlide, true)}

                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-20 py-10 rounded-[5rem] font-black text-9xl md:text-[12rem] border-[12px] shadow-[0_40px_80px_rgba(0,0,0,0.4)] backdrop-blur-3xl animate-bounce-slow
                      ${timer <= 10 
                        ? 'bg-red-600 border-white text-white animate-pulse' 
                        : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>

            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-indigo-50 hover:scale-110 active:scale-90 transition-all"><ChevronLeft className="w-16 h-16 text-indigo-600"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto disabled:opacity-20 border-4 border-indigo-50 hover:scale-110 active:scale-90 transition-all"><ChevronRight className="w-16 h-16 text-indigo-600"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white transition-colors" title="Mục lục"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400 transition-colors" title="Bảng giảng"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400 transition-colors" title="Quay số"><Dices className="w-7 h-7"/></button>

            <div className="w-px h-10 bg-white/20 mx-2"></div>

            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={() => setZoomLevel(z => Math.max(1.0, z-0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <div className="flex flex-col items-center min-w-[60px]">
                    <span className="text-[12px] font-black text-white/50 uppercase leading-none">Phóng</span>
                    <span className="text-lg font-black text-white">{Math.round(zoomLevel)}x</span>
                </div>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>

            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100">
                    <h3 className="text-3xl font-black mb-10 dark:text-white uppercase tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all border-4 border-transparent hover:border-white shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xl border-2 border-red-200">HỦY HẸN GIỜ</button>
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] w-full max-w-2xl shadow-2xl border-4 border-indigo-50" onClick={e => e.stopPropagation()}>
                    <h3 className="text-4xl font-black mb-12 text-slate-800 dark:text-white uppercase tracking-tighter text-center">Danh mục Câu hỏi</h3>
                    <div className="grid grid-cols-5 md:grid-cols-8 gap-4 max-h-[60vh] overflow-y-auto p-4 custom-scrollbar">
                        {questions.map((_, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setTimer(null); setIsTimerRunning(false); setShowNav(false); }} className={`h-20 rounded-3xl font-black text-2xl border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-110' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-100 text-slate-400'}`}>{i+1}</button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4">{calculateScore().score}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Presentation as PresentationIcon, FileText, Printer, Maximize, Minimize, MousePointer2, LayoutGrid, PenTool, Dices, X, ChevronDown, Menu, ZoomIn, ZoomOut, RefreshCw, Palette, Star, Eye, EyeOff, Lightbulb, BookOpen, Download, Save, Quote, MonitorPlay, Timer as TimerIcon, Clock } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType } from 'docx';
import FileSaver from 'file-saver';
import { parseContentToDocx } from '../utils/docxUtils';

interface StudyGuidePreviewProps {
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { name: 'Xanh Ngọc', bg: 'bg-teal-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-teal-700 dark:text-teal-400', border: 'border-teal-500' },
  blue: { name: 'Xanh Dương', bg: 'bg-blue-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-blue-700 dark:text-blue-400', border: 'border-blue-500' },
  violet: { name: 'Tím Mộng Mơ', bg: 'bg-violet-50 dark:bg-slate-900', text: 'text-slate-800 dark:text-slate-100', primary: 'text-violet-700 dark:text-violet-400', border: 'border-violet-500' }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(2.0); 
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showNav, setShowNav] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => setShowExampleSolution(false), [currentSlide, slideStep]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false));
    }
  };

  const theme = SLIDE_THEMES[activeTheme];
  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  return (
