import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const client = createClient();
  const smartModel = "gemini-3-pro-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Phân bổ hợp lý giữa 3 dạng bài:
            1. Trắc nghiệm nhiều lựa chọn (4 chọn 1).
            2. Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
            3. Trắc nghiệm trả lời ngắn (Tự luận điền kết quả).

          PHÂN BỔ ĐỘ KHÓ:
          - Dễ/Thông hiểu: Dùng trắc nghiệm 4 chọn 1.
          - Vận dụng: Dùng trắc nghiệm Đúng/Sai.
          - Vận dụng cao: Dùng trả lời ngắn (Tự luận).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao (Nguyên tắc: Dễ trước khó sau).' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề trọng tâm: "${config.topic}".
        Số lượng câu hỏi: ${config.questionCount}.
        Loại câu hỏi: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là nhà giáo dục Việt Nam xuất sắc, giáo viên giỏi đa môn, 
có 20 năm kinh nghiệm giảng dạy và nghiên cứu sách giáo khoa theo CTGDPT 2018,
chuyên gia ra đề kiểm tra – đánh giá năng lực học sinh THPT.

Bạn hiểu rõ:
- Mục tiêu cần đạt của CTGDPT 2018
- Cấu trúc đề kiểm tra hiện hành trong các trường phổ thông Việt Nam từ năm học 2025 trở đi (đặc biệt là dạng trắc nghiệm Đúng/Sai)
- Đặc điểm học sinh theo từng khối lớp
- Yêu cầu phân hóa và đánh giá năng lực

Hãy tạo một bộ đề luyện tập cho môn ${config.subject}, lớp ${config.grade},
bám sát sách giáo khoa (ghi rõ bộ sách),
cấu trúc đề hợp lý, có đáp án và hướng dẫn chấm chi tiết.
    Yêu cầu:
- Nội dung câu hỏi bám sát kiến thức trọng tâm SGK
- Có câu hỏi gắn với thực tế, đời sống hoặc liên môn
- Không đánh đố, không máy móc
- Mức độ khó tăng dần
- Ngôn ngữ chuẩn mực, rõ ràng, phù hợp học sinh Việt Nam
- Có đáp án, thang điểm và nhận xét sư phạm ngắn cho từng câu

    ${structureInstruction}

    Cấu hình độ khó: ${difficultyInstruction}
  `;

  if (config.uploadedFile) {
    promptText += `

    QUAN TRỌNG:
    Người dùng có cung cấp một tài liệu đính kèm (Hình ảnh hoặc PDF).
    Hãy PHÂN TÍCH KỸ nội dung trong file đính kèm đó.
    Dựa trên kiến thức, bài tập, hoặc ngữ liệu có trong file, hãy soạn ra bộ câu hỏi MỚI (tương tự dạng bài hoặc phát triển từ ngữ liệu đó).
    KHÔNG CHÉP LẠI Y NGUYÊN câu hỏi trong file nếu đó là file bài tập (hãy thay số liệu hoặc ngữ cảnh để tạo đề mới), trừ khi đề bài yêu cầu trích xuất.
    `;
  }

  promptText += `
    Yêu cầu quan trọng:
    1. Nội dung phải chuẩn theo chương trình GDPT 2018 của Bộ Giáo dục & Đào tạo Việt Nam.
    2. Các câu hỏi phải rõ ràng, không trùng lặp.
    3. Phải cung cấp đáp án đúng. Lời giải (solution) cần VIẾT TẮT, CỰC KỲ NGẮN GỌN, SÚC TÍCH, đi thẳng vào các bước biến đổi công thức chính, lược bỏ tối đa các câu văn dẫn dắt rườm rà.
    4. Phải cung cấp 2 gợi ý (hints) cho học sinh để kích thích tư duy (không cho đáp án ngay trong gợi ý).
    5. QUY TẮC DẠNG CÂU HỎI (Type):
       - Nếu type là '${QuestionType.MULTIPLE_CHOICE}': BẮT BUỘC phải có mảng 'options' gồm 4 lựa chọn A, B, C, D. 'correctAnswer' là 'A', 'B', 'C' hoặc 'D'.
       - Nếu type là '${QuestionType.TRUE_FALSE}': BẮT BUỘC phải có mảng 'options' gồm 4 mệnh đề con (a, b, c, d). 'correctAnswer' phải ghi rõ kết quả từng ý theo format: "a) Đ, b) S, c) Đ, d) S" hoặc "a: Đúng, b: Sai...".
       - Nếu type là '${QuestionType.ESSAY}': Mảng 'options' để rỗng hoặc null.
    6. ĐỊNH DẠNG TOÁN HỌC: Tất cả các công thức toán học, phương trình, biểu thức biến số (x, y, z...) PHẢI được viết dưới dạng LaTeX và đặt trong dấu $ (ví dụ: $x^2 + 2x + 1 = 0$, $\\frac{1}{2}$, $\\alpha$). Tuyệt đối không dùng Unicode math thông thường nếu có thể dùng LaTeX.
    7. MỤC TIÊU (Objectives): Hãy liệt kê 3-5 mục tiêu kiến thức, kỹ năng chính mà học sinh cần đạt được thông qua bài luyện tập này.

    Hãy trả về kết quả dưới dạng JSON.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING, description: "Nội dung câu hỏi chính (Stem), chứa công thức LaTeX trong dấu $" },
      type: { type: Type.STRING, description: "Loại câu hỏi (Trắc nghiệm, Trắc nghiệm Đúng/Sai, Tự luận)" },
      difficulty: { type: Type.STRING, description: "Mức độ (ví dụ: Nhận biết, Vận dụng)" },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Danh sách lựa chọn. Nếu TN 4 chọn 1: 4 đáp án. Nếu Đúng/Sai: 4 mệnh đề."
      },
      correctAnswer: { type: Type.STRING, description: "Đáp án đúng. Nếu Đúng/Sai, trả về chuỗi mô tả trạng thái (VD: a-Đ, b-S, c-Đ, d-S)." },
      solution: { type: Type.STRING, description: "Hướng dẫn giải chi tiết (chứa LaTeX)" },
      hints: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "2 gợi ý sư phạm"
      },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "Tiêu đề bài thi" },
      objectives: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING }, 
        description: "Danh sách 3-5 mục tiêu kiến thức cần đạt" 
      },
      summary: { type: Type.STRING, description: "Tóm tắt ma trận đề" },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }
    parts.push({ text: promptText });

    const response = await client.models.generateContent({
      model: smartModel,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as ExamMatrix;
    return data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to generate exam. Please check your API Key and try again.");
  }
};

