}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); 
  const [isStarted, setIsStarted] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE) {
        if (['A', 'B', 'C', 'D'][userAns] === q.correctAnswer.charAt(0)) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY) {
        if (userAns.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const slideClass = isSlide ? `p-12 md:p-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar ${slideClass}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center gap-4 mb-10 no-print">
                <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-4xl shadow-xl">{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">{q.difficulty}</span>
            </div>

            <div className="text-4xl md:text-5xl font-extrabold text-slate-900 dark:text-slate-100 mb-12 leading-[1.2] border-l-8 border-indigo-600 pl-8 py-2">
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {q.type === QuestionType.MULTIPLE_CHOICE && q.options?.map((o, oi) => (
                    <button key={oi} onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} className={`group flex items-start gap-6 p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAnswers[idx] === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}>
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-2xl shadow-lg ${userAnswers[idx] === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-2xl md:text-3xl font-bold pt-1 ${userAnswers[idx] === oi ? 'text-white' : OPTION_THEMES[oi].text}`}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}
            </div>

            {(showAnswers || isSubmitted) && (
                <div className="mt-16 p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-4xl font-black text-emerald-700 mb-8 flex items-center gap-4"><CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-3xl leading-relaxed font-semibold"><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl max-w-md w-full text-center border-4 border-indigo-50">
            <User className="w-24 h-24 text-indigo-600 mx-auto mb-8 bg-indigo-50 p-6 rounded-[2.5rem]" />
            <h2 className="text-3xl font-black mb-10 dark:text-white uppercase tracking-tighter">Bắt đầu Bài tập</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-8 rounded-3xl bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all" />
            <button onClick={() => studentName.trim() && setIsStarted(true)} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all">VÀO THI NGAY</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg">Nộp bài</button>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-9xl md:text-[14rem] border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={() => setZoomLevel(z => Math.max(1.0, z-0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[50px] text-center">{Math.round(zoomLevel)}x</span>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Trắc nghiệm nhiều lựa chọn (4 chọn 1).
          - Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
          - Trắc nghiệm trả lời ngắn (Điền kết quả).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao.' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề: "${config.topic}".
        Số lượng: ${config.questionCount} câu.
        Loại: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là chuyên gia soạn đề kiểm tra chuẩn CTGDPT 2018.
Tạo đề môn ${config.subject}, lớp ${config.grade}.

QUY TẮC CẤU TRÚC CÂU HỎI (BẮT BUỘC):
1. TRẮC NGHIỆM 4 CHỌN 1:
   - type: "Trắc nghiệm (4 chọn 1)"
   - options: Phải có đúng 4 phần tử. Mỗi phần tử bắt đầu bằng A., B., C., D.
   - correctAnswer: Chỉ gồm 1 chữ cái (VD: "A")

2. TRẮC NGHIỆM ĐÚNG/SAI:
   - type: "Trắc nghiệm Đúng/Sai"
   - content: Là câu dẫn chung.
   - options: Phải có đúng 4 mệnh đề con, bắt đầu bằng a), b), c), d).
   - correctAnswer: Phải liệt kê đúng/sai cho 4 ý. Format: "a: Đúng, b: Sai, c: Đúng, d: Sai"

3. TRẢ LỜI NGẮN / TỰ LUẬN:
   - type: "Tự luận"
   - options: Để mảng rỗng [].
   - correctAnswer: Đáp số hoặc từ khóa ngắn gọn.

YÊU CẦU KHÁC:
- ĐỊNH DẠNG TOÁN HỌC: Luôn dùng LaTeX trong dấu $ (VD: $x^2$, $\\frac{a}{b}$).
- LỜI GIẢI (solution): Viết ngắn gọn, súc tích.
- NGÔN NGỮ: Tiếng Việt chuẩn mực.

${structureInstruction}
${difficultyInstruction}

Trả về JSON theo schema yêu cầu.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      summary: { type: Type.STRING },
      questions: { type: Type.ARRAY, items: questionSchema },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.4,
      },
    });

    return JSON.parse(response.text) as ExamMatrix;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 phút.");
    }
    throw error;
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let promptText = `
    Soạn bài giảng slide tóm tắt kiến thức trọng tâm.
    Môn: ${config.subject}, ${config.grade}. Chủ đề: "${config.topic}".

    QUY TẮC TRÌNH BÀY NỘI DUNG (CỰC KỲ QUAN TRỌNG):
    1. Mỗi ý chính PHẢI bắt đầu bằng ký tự "★". 
    2. PHẢI dùng ký tự xuống dòng (\\n) sau mỗi ký hiệu ★ để tạo dòng mới.
    3. ĐỊNH DẠNG TỪ KHÓA: Các định nghĩa, từ khóa quan trọng PHẢI bao quanh bởi dấu ** (Ví dụ: **Trọng lực**).
    4. TOÁN HỌC: Dùng LaTeX trong dấu $.
    5. CẤU TRÚC: Mỗi slide (section) nên có 3-5 ý ★.

    Trả về JSON.
  `;

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      sections: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            content: { type: Type.STRING },
            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING },
                  solution: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                },
                required: ["problem", "solution", "explanation"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "overview", "sections"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.5,
      },
    });

    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 phút.");
    }
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'slide'>('list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); 
  const [isStarted, setIsStarted] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        // Simple heuristic for T/F score: all 4 sub-options must be correct
        // The correctAnswer format is assumed "a: Đúng, b: Sai..."
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const slideClass = isSlide ? `p-12 md:p-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';
    const userAns = userAnswers[idx];

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar ${slideClass}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center gap-4 mb-10 no-print">
                <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-4xl shadow-xl">{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">{q.difficulty}</span>
            </div>

            <div className="text-4xl md:text-5xl font-extrabold text-slate-900 dark:text-slate-100 mb-12 leading-[1.2] border-l-8 border-indigo-600 pl-8 py-2">
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* TRẮC NGHIỆM 4 CHỌN 1 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-2xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-2xl md:text-3xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {/* TRẮC NGHIỆM ĐÚNG / SAI */}
                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm">
                        <div className="text-2xl md:text-3xl font-bold mb-6 flex gap-3">
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-2xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {/* TỰ LUẬN / TRẢ LỜI NGẮN */}
                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-5xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                      />
                   </div>
                )}
            </div>

            {(showAnswers || isSubmitted) && (
                <div className="mt-16 p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-4xl font-black text-emerald-700 mb-8 flex items-center gap-4"><CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-3xl leading-relaxed font-semibold"><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl max-w-md w-full text-center border-4 border-indigo-50">
            <User className="w-24 h-24 text-indigo-600 mx-auto mb-8 bg-indigo-50 p-6 rounded-[2.5rem]" />
            <h2 className="text-3xl font-black mb-10 dark:text-white uppercase tracking-tighter">Bắt đầu Bài tập</h2>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-8 rounded-3xl bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all" />
            <button onClick={() => studentName.trim() && setIsStarted(true)} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all">VÀO THI NGAY</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg">Nộp bài</button>
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-9xl md:text-[12rem] border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={() => setZoomLevel(z => Math.max(1.0, z-0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[50px] text-center">{Math.round(zoomLevel)}x</span>
                <button onClick={() => setZoomLevel(z => Math.min(3.0, z+0.5))} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Trắc nghiệm nhiều lựa chọn (4 chọn 1).
          - Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
          - Trắc nghiệm trả lời ngắn (Điền kết quả).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao.' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề: "${config.topic}".
        Số lượng: ${config.questionCount} câu.
        Loại: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là chuyên gia soạn đề kiểm tra chuẩn CTGDPT 2018.
Tạo đề môn ${config.subject}, lớp ${config.grade}.

QUY TẮC CẤU TRÚC CÂU HỎI (BẮT BUỘC):
1. TRẮC NGHIỆM 4 CHỌN 1:
   - type: "Trắc nghiệm (4 chọn 1)"
   - options: Phải có đúng 4 phần tử. Mỗi phần tử bắt đầu bằng A., B., C., D.
   - correctAnswer: Chỉ gồm 1 chữ cái (VD: "A")

2. TRẮC NGHIỆM ĐÚNG/SAI:
   - type: "Trắc nghiệm Đúng/Sai"
   - content: Là câu dẫn chung.
   - options: Phải có đúng 4 mệnh đề con, bắt đầu bằng a), b), c), d).
   - correctAnswer: Phải liệt kê đúng/sai cho 4 ý. Format: "a: Đúng, b: Sai, c: Đúng, d: Sai"

3. TRẢ LỜI NGẮN / TỰ LUẬN:
   - type: "Tự luận"
   - options: Để mảng rỗng [].
   - correctAnswer: Đáp số hoặc từ khóa ngắn gọn.

YÊU CẦU KHÁC:
- ĐỊNH DẠNG TOÁN HỌC: Luôn dùng LaTeX trong dấu $ (VD: $x^2$, $\\frac{a}{b}$).
- LỜI GIẢI (solution): Viết ngắn gọn, súc tích.
- NGÔN NGỮ: Tiếng Việt chuẩn mực.

${structureInstruction}
${difficultyInstruction}

Trả về JSON theo schema yêu cầu.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      summary: { type: Type.STRING },
      questions: { type: Type.ARRAY, items: questionSchema },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.4,
      },
    });

    return JSON.parse(response.text) as ExamMatrix;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 phút.");
    }
    throw error;
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
