            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING },
                  solution: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                },
                required: ["problem", "solution", "explanation"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "overview", "sections"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.5,
      },
    });

    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 phút.");
    }
    throw error;
  }
};

import React, { useEffect, useRef } from 'react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
  highlightClass?: string;
}

declare global {
  interface Window {
    MathJax: any;
  }
}

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false, highlightClass = "text-indigo-600 dark:text-indigo-400" }) => {
  const containerRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    renderMath();
  }, [content]);

  const processContent = (text: string) => {
    if (!text) return null;

    // Sửa lỗi AI trả về chuỗi "\n" thay vì ký tự xuống dòng thật
    const sanitizedText = text.replace(/\\n/g, '\n');

    const parts = sanitizedText.split(/(\*\*[^*]+\*\*)/g);
    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return (
          <strong key={index} className={`font-black ${highlightClass}`}>
            {part.slice(2, -2)}
          </strong>
        );
      }
      return <span key={index}>{part}</span>;
    });
  };

  if (inline) {
    return (
      <span ref={containerRef as React.RefObject<HTMLSpanElement>} className="math-renderer inline-block align-middle whitespace-pre-wrap">
        {processContent(content)}
      </span>
    );
  }

  return (
    <div ref={containerRef as React.RefObject<HTMLDivElement>} className="math-renderer block my-2 whitespace-pre-wrap">
      {processContent(content)}
    </div>
  );
};

export default MathRenderer;

import React, { useState } from 'react';
