interface RandomPickerProps {
  onClose: () => void;
}

const GROUP_NAMES = [
  "Biệt đội Siêu Anh Hùng", "Liên minh Công Lý", "Nhóm Thông Thái", "Hội Những Người Chăm Chỉ",
  "Biệt đội Bứt Phá", "Nhóm Sáng Tạo", "Hội Tốc Độ", "Nhóm Đoàn Kết",
  "Đội Quân Thần Tốc", "Nhóm Tư Duy", "Biệt đội Hiếu Học", "Hội Khám Phá",
  "Nhóm Năng Lượng", "Đội Chinh Phục", "Nhóm Kiên Cường", "Hội Nghị Lực"
];

const RandomPicker: React.FC<RandomPickerProps> = ({ onClose }) => {
  const [activeTab, setActiveTab] = useState<'spin' | 'group'>('spin');

  // Spin State
  const [maxNumber, setMaxNumber] = useState(40);
  const [currentNumber, setCurrentNumber] = useState<number | null>(null);
  const [isSpinning, setIsSpinning] = useState(false);
  const [history, setHistory] = useState<number[]>([]);

  // Grouping State
  const [numGroups, setNumGroups] = useState(4);
  const [generatedGroups, setGeneratedGroups] = useState<{name: string, members: number[]}[] | null>(null);
  const [showFullGroups, setShowFullGroups] = useState(false);

  const handleSpin = () => {
    if (isSpinning) return;
    setIsSpinning(true);
    let duration = 1500;
    let startTime = Date.now();
    const animate = () => {
      const now = Date.now();
      const elapsed = now - startTime;
      if (elapsed < duration) {
        const random = Math.floor(Math.random() * maxNumber) + 1;
        setCurrentNumber(random);
        requestAnimationFrame(animate);
      } else {
        const final = Math.floor(Math.random() * maxNumber) + 1;
        setCurrentNumber(final);
        setHistory(prev => [final, ...prev]);
        setIsSpinning(false);
      }
    };
    requestAnimationFrame(animate);
  };

  const handleCreateGroups = () => {
    const students = Array.from({ length: maxNumber }, (_, i) => i + 1);
    // Shuffle students
    for (let i = students.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [students[i], students[j]] = [students[j], students[i]];
    }

    const groups: {name: string, members: number[]}[] = [];
    const names = [...GROUP_NAMES].sort(() => Math.random() - 0.5);

    for (let i = 0; i < numGroups; i++) {
      groups.push({ name: names[i % names.length], members: [] });
    }

    students.forEach((s, idx) => {
      groups[idx % numGroups].members.push(s);
    });

    setGeneratedGroups(groups);
    setShowFullGroups(true);
  };

  return (
    <div className="fixed inset-0 z-[150] bg-black/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in">
      <div className={`bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl overflow-hidden relative border-8 border-indigo-100 transition-all duration-500 ${showFullGroups ? 'w-full h-full max-w-none' : 'w-full max-w-xl'}`}>

        {/* Header */}
        <div className="bg-gradient-to-r from-violet-600 to-indigo-600 p-8 flex justify-between items-center text-white">
            <div className="flex items-center gap-4">
                {activeTab === 'spin' ? <Dices className="w-10 h-10" /> : <Users className="w-10 h-10" />}
                <h2 className="text-3xl font-black uppercase tracking-tighter">
                    {activeTab === 'spin' ? 'Vòng Quay May Mắn' : 'Chia Nhóm Tích Cực'}
                </h2>
            </div>
            <div className="flex items-center gap-4">
                {!showFullGroups && (
                    <div className="flex bg-white/20 p-1 rounded-2xl">
                        <button onClick={() => setActiveTab('spin')} className={`px-4 py-2 rounded-xl font-bold text-sm transition-all ${activeTab === 'spin' ? 'bg-white text-indigo-600 shadow-lg' : 'text-white hover:bg-white/10'}`}>QUAY SỐ</button>
                        <button onClick={() => setActiveTab('group')} className={`px-4 py-2 rounded-xl font-bold text-sm transition-all ${activeTab === 'group' ? 'bg-white text-indigo-600 shadow-lg' : 'text-white hover:bg-white/10'}`}>CHIA NHÓM</button>
                    </div>
                )}
                <button onClick={showFullGroups ? () => setShowFullGroups(false) : onClose} className="p-3 hover:bg-white/20 rounded-full transition-colors">
                    <X className="w-8 h-8" />
                </button>
            </div>
        </div>

        <div className={`p-10 flex flex-col gap-8 h-full overflow-y-auto custom-scrollbar`}>
            {!showFullGroups ? (
                <>
                    <div className="flex items-center justify-center gap-6">
                        <div className="flex flex-col items-center">
                            <label className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">Sĩ số lớp</label>
                            <input 
                                type="number" 
                                min="1" max="100"
                                value={maxNumber}
                                onChange={(e) => setMaxNumber(Math.max(1, parseInt(e.target.value) || 0))}
                                className="w-32 text-center font-black text-5xl p-4 rounded-[2rem] border-4 border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-indigo-600 dark:text-indigo-400 outline-none focus:border-indigo-500 transition-all"
                            />
                        </div>
                        {activeTab === 'group' && (
                            <div className="flex flex-col items-center">
                                <label className="text-slate-400 font-black text-xs uppercase tracking-widest mb-2">Số lượng nhóm</label>
                                <input 
                                    type="number" 
                                    min="2" max="16"
                                    value={numGroups}
                                    onChange={(e) => setNumGroups(Math.max(2, parseInt(e.target.value) || 2))}
                                    className="w-32 text-center font-black text-5xl p-4 rounded-[2rem] border-4 border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-teal-600 dark:text-teal-400 outline-none focus:border-teal-500 transition-all"
                                />
                            </div>
                        )}
                    </div>

                    {activeTab === 'spin' ? (
                        <div className="flex flex-col gap-8">
                            <div className="flex justify-center">
                                <div className={`w-64 h-64 rounded-full flex items-center justify-center border-[12px] shadow-2xl transition-all duration-300 ${isSpinning ? 'border-indigo-400 scale-110 rotate-12' : 'border-indigo-600'}`}>
                                    <span className={`text-9xl font-black text-indigo-600 dark:text-indigo-400 ${isSpinning ? 'blur-sm' : ''}`}>
                                        {currentNumber !== null ? currentNumber : '?'}
                                    </span>
                                </div>
                            </div>
                            <button onClick={handleSpin} disabled={isSpinning} className="w-full py-8 rounded-[3rem] bg-indigo-600 text-white font-black text-4xl shadow-2xl active:scale-95 disabled:opacity-50 transition-all flex items-center justify-center gap-4">
                                {isSpinning ? <RefreshCw className="w-10 h-10 animate-spin" /> : <Sparkles className="w-10 h-10" />}
                                QUAY SỐ
                            </button>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-6">
                            <p className="text-center text-slate-500 font-medium italic">Hệ thống sẽ chia ngẫu nhiên học sinh từ 1 đến {maxNumber} vào {numGroups} nhóm.</p>
                            <button onClick={handleCreateGroups} className="w-full py-8 rounded-[3rem] bg-teal-600 text-white font-black text-4xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                                <Users className="w-10 h-10" />
                                CHIA NHÓM NGAY
                            </button>
                        </div>
                    )}

                    {activeTab === 'spin' && history.length > 0 && (
                        <div className="mt-4 pt-6 border-t-4 border-slate-50 dark:border-slate-700">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <History className="w-5 h-5" /> Lịch sử quay
                            </h3>
                            <div className="flex flex-wrap gap-3 max-h-32 overflow-y-auto p-2">
                                {history.map((num, idx) => (
                                    <span key={idx} className="w-14 h-14 flex items-center justify-center rounded-2xl bg-indigo-50 dark:bg-slate-700 text-indigo-600 dark:text-indigo-300 font-black text-2xl border-2 border-indigo-200 shadow-sm animate-fade-in">{num}</span>
                                ))}
                            </div>
                        </div>
                    )}
                </>
            ) : (
                /* FULL SCREEN GROUP VIEW */
                <div className="flex-grow flex flex-col animate-fade-in-up">
                    <div className="mb-8 text-center">
                        <h2 className="text-5xl font-black text-slate-800 dark:text-white uppercase tracking-tighter mb-2">Kết quả Chia Nhóm</h2>
                        <div className="inline-block px-6 py-2 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 dark:text-indigo-400 rounded-full font-black text-xl uppercase tracking-widest">Sĩ số: {maxNumber} | Nhóm: {numGroups}</div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8 p-4 flex-grow content-start">
                        {generatedGroups?.map((group, gIdx) => (
                            <div key={gIdx} className="bg-slate-50 dark:bg-slate-900 p-8 rounded-[3rem] border-4 border-slate-200 dark:border-slate-700 shadow-xl flex flex-col animate-fade-in" style={{ animationDelay: `${gIdx * 100}ms` }}>
                                <div className="flex items-center gap-4 mb-6">
                                    <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-2xl shadow-lg">{gIdx + 1}</div>
                                    <h3 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tighter leading-tight">{group.name}</h3>
                                </div>
                                <div className="flex flex-wrap gap-3">
                                    {group.members.sort((a,b) => a-b).map(m => (
                                        <span key={m} className="w-14 h-14 flex items-center justify-center rounded-2xl bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-black text-2xl border-2 border-slate-200 dark:border-slate-600 shadow-sm">{m}</span>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="mt-12 flex justify-center pb-10">
                        <button onClick={() => setShowFullGroups(false)} className="px-12 py-5 bg-slate-800 text-white font-black rounded-3xl text-xl hover:bg-slate-700 transition-all shadow-2xl flex items-center gap-3">
                           <LayoutGrid className="w-6 h-6"/> QUAY LẠI THIẾT LẬP
                        </button>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

