          <div className="max-w-4xl mx-auto mb-8 p-5 bg-red-50 dark:bg-red-900/20 border-2 border-red-200 dark:border-red-800 rounded-2xl flex items-center gap-4 text-red-700 dark:text-red-400 animate-fade-in shadow-lg">
             <AlertTriangle className="w-6 h-6 flex-shrink-0" />
