  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => { setShowExampleSolution(false); }, [currentSlide, slideStep]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const theme = SLIDE_THEMES[activeTheme];
  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  // Zoom logic
  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 h-20 flex justify-between items-center px-8 no-print sticky top-0 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><RotateCcw className="w-6 h-6 text-slate-500"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md uppercase tracking-tighter dark:text-white">{data.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{role === 'teacher' ? 'Chế độ giảng dạy' : 'Tài liệu học tập'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
                    <button onClick={() => setViewMode('doc')} className={`p-2 rounded-lg transition-all ${viewMode === 'doc' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Xem dạng văn bản/tài liệu"><FileText className="w-5 h-5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2 rounded-lg transition-all ${viewMode === 'slide' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Trình chiếu Slide"><MonitorPlay className="w-5 h-5"/></button>
                </div>
                <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700" title="Đổi màu giao diện"><Palette className="w-6 h-6"/></button>
                <button onClick={toggleFullScreen} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${isSidePanelOpen && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'doc' ? (
                    <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] shadow-2xl animate-fade-in border border-slate-100 dark:border-slate-700 transition-[font-size] duration-300 ease-out" style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className="mb-14 pb-8 border-b-2 border-slate-100 dark:border-slate-700">
                            <h2 className="text-4xl font-black text-indigo-700 dark:text-indigo-400 mb-4 uppercase tracking-tighter" style={{ fontSize: '1.5em' }}>{data.topic}</h2>
                            <p className="text-xl text-slate-500 font-medium italic" style={{ fontSize: '0.8em' }}>{data.overview}</p>
                        </div>
                        {data.sections.map((s, i) => (
                            <div key={i} className="mb-24 last:mb-0">
                                <h2 className="text-2xl font-black mb-10 border-b-8 border-teal-500 inline-block pb-2 uppercase tracking-tighter text-teal-700 dark:text-teal-400" style={{ fontSize: '1.2em' }}>{i+1}. {s.title}</h2>
                                <div className="text-xl leading-relaxed font-semibold whitespace-pre-wrap mb-10"><MathRenderer content={s.content}/></div>
                                {s.examples && s.examples.length > 0 && (
                                    <div className="p-10 bg-slate-50 dark:bg-slate-900 rounded-[3rem] border-4 border-slate-100 dark:border-slate-800">
                                        <h3 className="text-xl font-black mb-6 flex items-center gap-3"><Star className="w-8 h-8 text-yellow-500 fill-current" /> Ví dụ minh họa</h3>
                                        <div className="text-xl font-bold mb-8"><MathRenderer content={s.examples[0].problem}/></div>
                                        <div className="p-8 bg-emerald-50 dark:bg-emerald-900/30 rounded-[2.5rem] border-l-[1rem] border-emerald-500">
                                            <span className="text-xs font-black text-emerald-600 uppercase mb-4 block">Hướng dẫn:</span>
                                            <div className="text-lg font-medium"><MathRenderer content={s.examples[0].solution}/></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-12 md:p-20 overflow-y-auto custom-scrollbar transition-[font-size] duration-300 ease-out ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className={`w-full mb-8 pb-4 border-b-8 ${theme.border} flex justify-between items-end`}>
                            <h2 className={`text-3xl md:text-4xl font-black ${theme.primary} leading-tight uppercase tracking-tighter`} style={{ fontSize: '1.8em' }}>{slides[currentSlide].title}</h2>
                            <span className={`text-base font-black ${theme.primary} opacity-40 uppercase mb-2 tracking-widest`}>Slide {currentSlide + 1} / {slides.length}</span>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-xl md:text-2xl leading-relaxed space-y-10 w-full animate-fade-in font-bold whitespace-pre-wrap" style={{ fontSize: '1.2em' }}>
                                <MathRenderer content={slides[currentSlide].content} highlightClass={theme.highlight} />
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-[10px] border-indigo-200 shadow-2xl animate-fade-in-up">
                                <h3 className={`text-xl font-black mb-8 flex items-center gap-4 ${theme.primary}`} style={{ fontSize: '1.1em' }}><Star className="w-12 h-12 fill-current" /> Ví dụ Tiêu biểu</h3>
                                <div className="text-xl md:text-2xl mb-12 font-extrabold leading-relaxed text-slate-800 dark:text-slate-100" style={{ fontSize: '1.2em' }}><MathRenderer content={slides[currentSlide].examples[0].problem}/></div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-16 py-8 bg-indigo-600 text-white font-black text-xl rounded-[3rem] shadow-2xl hover:brightness-110 active:scale-95 transition-all uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                                ) : (
                                    <div className="w-full p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-l-[1.5rem] border-emerald-500 animate-fade-in text-xl font-bold leading-relaxed" style={{ fontSize: '1.1em' }}>
                                        <div className="text-xs font-black text-emerald-600 uppercase mb-4 opacity-50">Solution:</div>
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}

                        {viewMode === 'slide' && timer !== null && (
                          <div className="fixed bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                            <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow
                              ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                              {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                            </div>
                          </div>
                        )}
                    </div>
                )}
            </div>

            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-slate-700 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white" title="Danh sách các Slide"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400" title="Dùng bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400" title="Học sinh ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-sm font-black text-white min-w-[35px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-3 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Bấm giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {/* Popups remain the same */}
        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter">Bấm giờ Bài giảng</h3>
                    <div className="grid grid-cols-3 gap-4 mb-8">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-3xl font-black text-2xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-black uppercase text-xs tracking-widest">Dừng Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showThemeMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 flex items-center justify-center p-6" onClick={() => setShowThemeMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-10 rounded-[4rem] shadow-2xl w-full max-w-lg text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter">Giao diện Màu Slide</h3>
                    <div className="grid grid-cols-3 gap-4">
                        {(Object.keys(SLIDE_THEMES) as ThemeKey[]).map((key) => (
                            <button key={key} onClick={() => { setActiveTheme(key); setShowThemeMenu(false); }} className={`p-4 rounded-3xl border-4 transition-all flex flex-col items-center gap-2 ${activeTheme === key ? 'border-indigo-600 scale-105 shadow-xl' : 'border-slate-100 dark:border-slate-700'}`}>
                                <div className={`w-10 h-10 rounded-full ${SLIDE_THEMES[key].bg} border border-slate-300 shadow-inner`}></div>
                                <span className="font-bold text-xs uppercase tracking-tighter">{SLIDE_THEMES[key].name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Mục lục Slide: {slides.length} trang</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} className={`p-6 rounded-[2.5rem] text-left border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1 uppercase tracking-widest">TRANG {i+1}</span>
                                <span className="font-bold text-xl leading-tight line-clamp-2 uppercase tracking-tighter">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    // Zoom style applied to card
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };
    const slideClass = isSlide ? `p-12 md:p-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';
    const userAns = userAnswers[idx];

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-[font-size] duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center gap-4 mb-10 no-print">
                <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
            </div>

            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-12 leading-[1.2] border-l-8 border-indigo-600 pl-8 py-2" style={{ fontSize: '1.5em' }}>
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* TRẮC NGHIỆM 4 CHỌN 1 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {/* TRẮC NGHIỆM ĐÚNG / SAI */}
                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm">
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {/* TỰ LUẬN / TRẢ LỜI NGẮN */}
                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em' }}
                      />
                   </div>
                )}
            </div>

            {(showAnswers || isSubmitted) && (
                <div className="mt-16 p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-2xl font-black text-emerald-700 mb-8 flex items-center gap-4" style={{ fontSize: '1.2em' }}><CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-xl leading-relaxed font-semibold" style={{ fontSize: '1.1em' }}><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter">Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswers(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter">{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswers(!showAnswers)} className={`p-3 rounded-xl transition-all ${showAnswers ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {/* Other modals remain same */}
        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    // Đẩy sát mép trên bằng cách giảm padding-top (pt-4/pt-6)
    const slideClass = isSlide 
      ? `pt-4 pb-16 px-12 md:pt-6 md:pb-24 md:px-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    const userAns = userAnswers[idx];
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-[font-size] duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            {/* Giảm khoảng cách mb từ 10 xuống 6 để đẩy nội dung câu hỏi lên cao hơn */}
            <div className="flex items-center gap-4 mb-6 no-print">
                <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
            </div>

            {/* Sử dụng leading-relaxed để các dòng câu hỏi có khoảng dãn hợp lý */}
            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-10 leading-relaxed border-l-8 border-indigo-600 pl-8 py-2" style={{ fontSize: '1.5em' }}>
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* TRẮC NGHIỆM 4 CHỌN 1 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {/* TRẮC NGHIỆM ĐÚNG / SAI */}
                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm">
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {/* TỰ LUẬN / TRẢ LỜI NGẮN */}
                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em' }}
                      />
                   </div>
                )}
            </div>

            {(showAnswers || isSubmitted) && (
                <div className="mt-16 p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-2xl font-black text-emerald-700 mb-8 flex items-center gap-4" style={{ fontSize: '1.2em' }}><CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-xl leading-relaxed font-semibold" style={{ fontSize: '1.1em' }}><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter">Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswers(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter">{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswers(!showAnswers)} className={`p-3 rounded-xl transition-all ${showAnswers ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswers, setShowAnswers] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    // Đẩy sát mép trên bằng cách giảm padding-top (pt-2/pt-4)
    const slideClass = isSlide 
      ? `pt-2 pb-16 px-12 md:pt-4 md:pb-24 md:px-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    const userAns = userAnswers[idx];
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-[font-size] duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            {/* Thu nhỏ khoảng cách mb để đẩy câu hỏi lên cao nhất có thể */}
            <div className="flex items-center gap-4 mb-4 no-print">
                <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
            </div>

            {/* Sử dụng leading-[1.25] cho nội dung chính (Body) theo yêu cầu 1.2-1.3 */}
            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-8 leading-[1.25] border-l-8 border-indigo-600 pl-8 py-2" style={{ fontSize: '1.5em' }}>
                <MathRenderer content={q.content} />
            </div>

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* TRẮC NGHIỆM 4 CHỌN 1 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-6 md:p-8 rounded-[3rem] border-4 transition-all text-left shadow-md leading-[1.2] ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {/* TRẮC NGHIỆM ĐÚNG / SAI */}
                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 md:p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm leading-[1.25]">
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {/* TỰ LUẬN / TRẢ LỜI NGẮN */}
                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em' }}
                      />
                   </div>
                )}
            </div>

            {(showAnswers || isSubmitted) && (
                <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl">
                    <h4 className="text-2xl font-black text-emerald-700 mb-6 flex items-center gap-4 leading-[1.1]" style={{ fontSize: '1.2em' }}><CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-xl leading-[1.3] font-semibold" style={{ fontSize: '1.1em' }}><MathRenderer content={q.solution} /></div>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-[1.1]">Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswers(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter leading-[1.1]">{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswers(!showAnswers)} className={`p-3 rounded-xl transition-all ${showAnswers ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswers(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, Palette, Star, MonitorPlay, Timer as TimerIcon, BookOpen, School } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc', 
    bg: 'bg-teal-50 dark:bg-slate-900', 
    primary: 'text-teal-700 dark:text-teal-400', 
    border: 'border-teal-500',
    highlight: 'text-teal-600 dark:text-teal-300'
  },
  blue: { 
    name: 'Xanh Dương', 
    bg: 'bg-blue-50 dark:bg-slate-900', 
    primary: 'text-blue-700 dark:text-blue-400', 
    border: 'border-blue-500',
    highlight: 'text-blue-600 dark:text-blue-300'
  },
  violet: { 
    name: 'Tím Mộng Mơ', 
    bg: 'bg-violet-50 dark:bg-slate-900', 
    primary: 'text-violet-700 dark:text-violet-400', 
    border: 'border-violet-500',
    highlight: 'text-violet-600 dark:text-violet-300'
  }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>(role === 'teacher' ? 'slide' : 'doc');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showNav, setShowNav] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => { setShowExampleSolution(false); }, [currentSlide, slideStep]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
        setTimer(null);
        setIsTimerRunning(false);
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const theme = SLIDE_THEMES[activeTheme];
  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  // Zoom logic
  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 h-20 flex justify-between items-center px-8 no-print sticky top-0 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><RotateCcw className="w-6 h-6 text-slate-500"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md uppercase tracking-tighter dark:text-white leading-[1.1]">{data.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{role === 'teacher' ? 'Chế độ giảng dạy' : 'Tài liệu học tập'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
                    <button onClick={() => setViewMode('doc')} className={`p-2 rounded-lg transition-all ${viewMode === 'doc' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Xem dạng văn bản/tài liệu"><FileText className="w-5 h-5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2 rounded-lg transition-all ${viewMode === 'slide' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Trình chiếu Slide"><MonitorPlay className="w-5 h-5"/></button>
                </div>
                <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700" title="Đổi màu giao diện"><Palette className="w-6 h-6"/></button>
                <button onClick={toggleFullScreen} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${isSidePanelOpen && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'doc' ? (
                    <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] shadow-2xl animate-fade-in border border-slate-100 dark:border-slate-700 transition-[font-size] duration-300 ease-out" style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className="mb-14 pb-8 border-b-2 border-slate-100 dark:border-slate-700">
                            <h2 className="text-4xl font-black text-indigo-700 dark:text-indigo-400 mb-4 uppercase tracking-tighter leading-[1.1]" style={{ fontSize: '1.5em' }}>{data.topic}</h2>
                            <p className="text-xl text-slate-500 font-medium italic" style={{ fontSize: '0.8em' }}>{data.overview}</p>
                        </div>
                        {data.sections.map((s, i) => (
                            <div key={i} className="mb-24 last:mb-0">
                                <h2 className="text-2xl font-black mb-10 border-b-8 border-teal-500 inline-block pb-2 uppercase tracking-tighter text-teal-700 dark:text-teal-400 leading-[1.1]" style={{ fontSize: '1.2em' }}>{i+1}. {s.title}</h2>
                                <div className="text-xl leading-[1.3] font-semibold whitespace-pre-wrap mb-10"><MathRenderer content={s.content}/></div>
                                {s.examples && s.examples.length > 0 && (
                                    <div className="p-10 bg-slate-50 dark:bg-slate-900 rounded-[3rem] border-4 border-slate-100 dark:border-slate-800">
                                        <h3 className="text-xl font-black mb-6 flex items-center gap-3 leading-[1.1]"><Star className="w-8 h-8 text-yellow-500 fill-current" /> Ví dụ minh họa</h3>
                                        <div className="text-xl font-bold mb-8 leading-[1.3]"><MathRenderer content={s.examples[0].problem}/></div>
                                        <div className="p-8 bg-emerald-50 dark:bg-emerald-900/30 rounded-[2.5rem] border-l-[1rem] border-emerald-500">
                                            <span className="text-xs font-black text-emerald-600 uppercase mb-4 block">Hướng dẫn:</span>
                                            <div className="text-lg font-medium leading-[1.3]"><MathRenderer content={s.examples[0].solution}/></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-12 md:p-16 overflow-y-auto custom-scrollbar transition-[font-size] duration-300 ease-out ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className={`w-full mb-8 pb-4 border-b-8 ${theme.border} flex justify-between items-end`}>
                            <h2 className={`text-3xl md:text-4xl font-black ${theme.primary} leading-[1.1] uppercase tracking-tighter`} style={{ fontSize: '1.8em' }}>{slides[currentSlide].title}</h2>
                            <span className={`text-base font-black ${theme.primary} opacity-40 uppercase mb-2 tracking-widest`}>Slide {currentSlide + 1} / {slides.length}</span>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-xl md:text-2xl leading-[1.3] space-y-10 w-full animate-fade-in font-bold whitespace-pre-wrap" style={{ fontSize: '1.2em' }}>
                                <MathRenderer content={slides[currentSlide].content} highlightClass={theme.highlight} />
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-[10px] border-indigo-200 shadow-2xl animate-fade-in-up">
                                <h3 className={`text-xl font-black mb-8 flex items-center gap-4 ${theme.primary} leading-[1.1]`} style={{ fontSize: '1.1em' }}><Star className="w-12 h-12 fill-current" /> Ví dụ Tiêu biểu</h3>
                                <div className="text-xl md:text-2xl mb-12 font-extrabold leading-[1.3] text-slate-800 dark:text-slate-100" style={{ fontSize: '1.2em' }}><MathRenderer content={slides[currentSlide].examples[0].problem}/></div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-16 py-8 bg-indigo-600 text-white font-black text-xl rounded-[3rem] shadow-2xl hover:brightness-110 active:scale-95 transition-all uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                                ) : (
                                    <div className="w-full p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-l-[1.5rem] border-emerald-500 animate-fade-in text-xl font-bold leading-[1.3]" style={{ fontSize: '1.1em' }}>
                                        <div className="text-xs font-black text-emerald-600 uppercase mb-4 opacity-50">Solution:</div>
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}

                        {viewMode === 'slide' && timer !== null && (
                          <div className="fixed bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                            <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow
                              ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                              {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                            </div>
                          </div>
                        )}
                    </div>
                )}
            </div>

            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-slate-700 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white" title="Danh sách các Slide"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400" title="Dùng bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400" title="Học sinh ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-sm font-black text-white min-w-[35px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-3 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Bấm giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter leading-[1.1]">Bấm giờ Bài giảng</h3>
                    <div className="grid grid-cols-3 gap-4 mb-8">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-3xl font-black text-2xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-black uppercase text-xs tracking-widest">Dừng Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showThemeMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 flex items-center justify-center p-6" onClick={() => setShowThemeMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-10 rounded-[4rem] shadow-2xl w-full max-w-lg text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter leading-[1.1]">Giao diện Màu Slide</h3>
                    <div className="grid grid-cols-3 gap-4">
                        {(Object.keys(SLIDE_THEMES) as ThemeKey[]).map((key) => (
                            <button key={key} onClick={() => { setActiveTheme(key); setShowThemeMenu(false); }} className={`p-4 rounded-3xl border-4 transition-all flex flex-col items-center gap-2 ${activeTheme === key ? 'border-indigo-600 scale-105 shadow-xl' : 'border-slate-100 dark:border-slate-700'}`}>
                                <div className={`w-10 h-10 rounded-full ${SLIDE_THEMES[key].bg} border border-slate-300 shadow-inner`}></div>
                                <span className="font-bold text-xs uppercase tracking-tighter">{SLIDE_THEMES[key].name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter leading-[1.1]">Mục lục Slide: {slides.length} trang</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} className={`p-6 rounded-[2.5rem] text-left border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1 uppercase tracking-widest">TRANG {i+1}</span>
                                <span className="font-bold text-xl leading-tight line-clamp-2 uppercase tracking-tighter">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  // States for hints and individual answer reveal
  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const toggleRevealAnswer = (idx: number) => {
    setRevealedAnswers(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const toggleRevealHint = (idx: number) => {
    setRevealedHints(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const slideClass = isSlide 
      ? `pt-2 pb-16 px-12 md:pt-4 md:pb-24 md:px-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    const userAns = userAnswers[idx];
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };
    const isAnswerVisible = showAnswersGlobal || isSubmitted || revealedAnswers.has(idx);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-[font-size] duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center justify-between w-full mb-4 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                  <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
                </div>

                {/* Hint Button */}
                {q.hints && q.hints.length > 0 && (
                  <button 
                    onClick={() => toggleRevealHint(idx)}
                    className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-sm uppercase tracking-tighter transition-all ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}
                  >
                    <Lightbulb className={`w-5 h-5 ${isHintVisible ? 'animate-pulse' : ''}`} />
                    {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'}
                  </button>
                )}
            </div>

            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-8 leading-[1.25] border-l-8 border-indigo-600 pl-8 py-2" style={{ fontSize: '1.5em' }}>
                <MathRenderer content={q.content} />
            </div>

            {/* Hint Content */}
            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-8 bg-amber-50 dark:bg-amber-900/20 border-2 border-amber-200 rounded-[3rem] animate-fade-in-up">
                <h5 className="text-amber-700 font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                  <HelpCircle className="w-4 h-4" /> Gợi ý các bước giải:
                </h5>
                <ul className="space-y-4">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-4 text-amber-800 dark:text-amber-200 font-semibold text-lg">
                      <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 dark:bg-amber-800 flex items-center justify-center text-sm font-black">{hIdx + 1}</span>
                      <MathRenderer content={hint} inline />
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* TRẮC NGHIỆM 4 CHỌN 1 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-6 md:p-8 rounded-[3rem] border-4 transition-all text-left shadow-md leading-[1.2] ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {/* TRẮC NGHIỆM ĐÚNG / SAI */}
                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 md:p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm leading-[1.25]">
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {/* TỰ LUẬN / TRẢ LỜI NGẮN */}
                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em' }}
                      />
                   </div>
                )}
            </div>

            {/* Answer Display Area */}
            {isAnswerVisible ? (
                <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl relative overflow-hidden group">
                    <button 
                      onClick={() => toggleRevealAnswer(idx)}
                      className="absolute top-6 right-6 p-2 hover:bg-emerald-100 dark:hover:bg-emerald-800 rounded-full transition-colors no-print"
                    >
                      <X className="w-6 h-6 text-emerald-600" />
                    </button>
                    <h4 className="text-2xl font-black text-emerald-700 mb-6 flex items-center gap-4 leading-[1.1]" style={{ fontSize: '1.2em' }}>
                      <CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline />
                    </h4>
                    <div className="text-xl leading-[1.3] font-semibold" style={{ fontSize: '1.1em' }}>
                      <MathRenderer content={q.solution} />
                    </div>
                </div>
            ) : (
                <div 
                  onClick={() => toggleRevealAnswer(idx)}
                  className="mt-12 w-full p-12 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-4 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center justify-center gap-4 cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/20 hover:border-indigo-300 transition-all group no-print"
                >
                    <div className="w-20 h-20 rounded-full bg-white dark:bg-slate-700 flex items-center justify-center text-slate-400 group-hover:text-indigo-600 group-hover:scale-110 transition-all shadow-md">
                        <Eye className="w-10 h-10" />
                    </div>
                    <span className="text-xl font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Đáp án & Lời giải Chi tiết</span>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-[1.1]">Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswersGlobal(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter leading-[1.1]">{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); setTimer(null); setIsTimerRunning(false); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  // States for hints and individual answer reveal
  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);

  // Tự động ẩn đáp án và gợi ý khi chuyển câu hỏi mới (theo yêu cầu)
  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const toggleRevealAnswer = (idx: number) => {
    setRevealedAnswers(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const toggleRevealHint = (idx: number) => {
    setRevealedHints(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const handleExport = () => {
    const exportData = {
      type: 'exam',
      config: config,
      data: data,
      timestamp: Date.now()
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Exam_${config.topic.replace(/\s+/g, '_')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const slideClass = isSlide 
      ? `pt-2 pb-16 px-12 md:pt-4 md:pb-24 md:px-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    const userAns = userAnswers[idx];
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };
    const isAnswerVisible = showAnswersGlobal || isSubmitted || revealedAnswers.has(idx);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-all duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center justify-between w-full mb-4 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                  <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
                </div>

                {q.hints && q.hints.length > 0 && (
                  <button 
                    onClick={() => toggleRevealHint(idx)}
                    className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-sm uppercase tracking-tighter transition-all ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}
                  >
                    <Lightbulb className={`w-5 h-5 ${isHintVisible ? 'animate-pulse' : ''}`} />
                    {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'}
                  </button>
                )}
            </div>

            {/* Headline style: line-height 1.1 */}
            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-8 border-l-8 border-indigo-600 pl-8 py-2" 
                 style={{ fontSize: '1.5em', lineHeight: 1.1 }}>
                <MathRenderer content={q.content} />
            </div>

            {/* Hint Content: line-height 1.3 */}
            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-8 bg-amber-50 dark:bg-amber-900/20 border-2 border-amber-200 rounded-[3rem] animate-fade-in-up">
                <h5 className="text-amber-700 font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                  <HelpCircle className="w-4 h-4" /> Gợi ý các bước giải:
                </h5>
                <ul className="space-y-4" style={{ lineHeight: 1.3 }}>
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-4 text-amber-800 dark:text-amber-200 font-semibold text-lg">
                      <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 dark:bg-amber-800 flex items-center justify-center text-sm font-black">{hIdx + 1}</span>
                      <MathRenderer content={hint} inline />
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {/* Body elements: line-height 1.3 */}
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-6 md:p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                      style={{ lineHeight: 1.3 }}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 md:p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm" style={{ lineHeight: 1.3 }}>
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em', lineHeight: 1 }}
                      />
                   </div>
                )}
            </div>

            {isAnswerVisible ? (
                <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl relative overflow-hidden group">
                    <button 
                      onClick={() => toggleRevealAnswer(idx)}
                      className="absolute top-6 right-6 p-2 hover:bg-emerald-100 dark:hover:bg-emerald-800 rounded-full transition-colors no-print"
                    >
                      <X className="w-6 h-6 text-emerald-600" />
                    </button>
                    <h4 className="text-2xl font-black text-emerald-700 mb-6 flex items-center gap-4" style={{ fontSize: '1.2em', lineHeight: 1.1 }}>
                      <CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline />
                    </h4>
                    <div className="text-xl font-semibold" style={{ fontSize: '1.1em', lineHeight: 1.3 }}>
                      <MathRenderer content={q.solution} />
                    </div>
                </div>
            ) : (
                <div 
                  onClick={() => toggleRevealAnswer(idx)}
                  className="mt-12 w-full p-12 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-4 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center justify-center gap-4 cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/20 hover:border-indigo-300 transition-all group no-print"
                >
                    <div className="w-20 h-20 rounded-full bg-white dark:bg-slate-700 flex items-center justify-center text-slate-400 group-hover:text-indigo-600 group-hover:scale-110 transition-all shadow-md">
                        <Eye className="w-10 h-10" />
                    </div>
                    <span className="text-xl font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Đáp án & Lời giải Chi tiết</span>
                </div>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswersGlobal(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors" title="Lưu đề thi này">
                    <Save className="w-6 h-6" />
                </button>
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {/* Modals remain the same... */}
        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, Palette, Star, MonitorPlay, Timer as TimerIcon, BookOpen, School, Save } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc', 
    bg: 'bg-teal-50 dark:bg-slate-900', 
    primary: 'text-teal-700 dark:text-teal-400', 
    border: 'border-teal-500',
    highlight: 'text-teal-600 dark:text-teal-300'
  },
  blue: { 
    name: 'Xanh Dương', 
    bg: 'bg-blue-50 dark:bg-slate-900', 
    primary: 'text-blue-700 dark:text-blue-400', 
    border: 'border-blue-500',
    highlight: 'text-blue-600 dark:text-blue-300'
  },
  violet: { 
    name: 'Tím Mộng Mơ', 
    bg: 'bg-violet-50 dark:bg-slate-900', 
    primary: 'text-violet-700 dark:text-violet-400', 
    border: 'border-violet-500',
    highlight: 'text-violet-600 dark:text-violet-300'
  }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>(role === 'teacher' ? 'slide' : 'doc');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showNav, setShowNav] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => { setShowExampleSolution(false); }, [currentSlide, slideStep]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleExport = () => {
    const exportData = {
      type: 'theory',
      config: config,
      data: data,
      timestamp: Date.now()
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Lecture_${data.topic.replace(/\s+/g, '_')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const theme = SLIDE_THEMES[activeTheme];
  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 h-20 flex justify-between items-center px-8 no-print sticky top-0 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><RotateCcw className="w-6 h-6 text-slate-500"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md uppercase tracking-tighter dark:text-white" style={{ lineHeight: 1.1 }}>{data.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{role === 'teacher' ? 'Chế độ giảng dạy' : 'Tài liệu học tập'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors" title="Lưu bài giảng này">
                    <Save className="w-6 h-6" />
                </button>
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
                    <button onClick={() => setViewMode('doc')} className={`p-2 rounded-lg transition-all ${viewMode === 'doc' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Xem dạng văn bản/tài liệu"><FileText className="w-5 h-5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-2 rounded-lg transition-all ${viewMode === 'slide' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`} title="Trình chiếu Slide"><MonitorPlay className="w-5 h-5"/></button>
                </div>
                <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700" title="Đổi màu giao diện"><Palette className="w-6 h-6"/></button>
                <button onClick={toggleFullScreen} className="p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700">{isFullscreen ? <Minimize className="w-6 h-6"/> : <Maximize className="w-6 h-6"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${isSidePanelOpen && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'doc' ? (
                    <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] shadow-2xl animate-fade-in border border-slate-100 dark:border-slate-700 transition-all duration-300 ease-out" style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className="mb-14 pb-8 border-b-2 border-slate-100 dark:border-slate-700">
                            <h2 className="text-4xl font-black text-indigo-700 dark:text-indigo-400 mb-4 uppercase tracking-tighter" style={{ fontSize: '1.5em', lineHeight: 1.1 }}>{data.topic}</h2>
                            <p className="text-xl text-slate-500 font-medium italic" style={{ fontSize: '0.8em', lineHeight: 1.3 }}>{data.overview}</p>
                        </div>
                        {data.sections.map((s, i) => (
                            <div key={i} className="mb-24 last:mb-0">
                                <h2 className="text-2xl font-black mb-10 border-b-8 border-teal-500 inline-block pb-2 uppercase tracking-tighter text-teal-700 dark:text-teal-400" style={{ fontSize: '1.2em', lineHeight: 1.1 }}>{i+1}. {s.title}</h2>
                                <div className="text-xl font-semibold whitespace-pre-wrap mb-10" style={{ lineHeight: 1.3 }}><MathRenderer content={s.content}/></div>
                                {s.examples && s.examples.length > 0 && (
                                    <div className="p-10 bg-slate-50 dark:bg-slate-900 rounded-[3rem] border-4 border-slate-100 dark:border-slate-800">
                                        <h3 className="text-xl font-black mb-6 flex items-center gap-3" style={{ lineHeight: 1.1 }}><Star className="w-8 h-8 text-yellow-500 fill-current" /> Ví dụ minh họa</h3>
                                        <div className="text-xl font-bold mb-8" style={{ lineHeight: 1.3 }}><MathRenderer content={s.examples[0].problem}/></div>
                                        <div className="p-8 bg-emerald-50 dark:bg-emerald-900/30 rounded-[2.5rem] border-l-[1rem] border-emerald-500">
                                            <span className="text-xs font-black text-emerald-600 uppercase mb-4 block">Hướng dẫn:</span>
                                            <div className="text-lg font-medium" style={{ lineHeight: 1.3 }}><MathRenderer content={s.examples[0].solution}/></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-12 md:p-16 overflow-y-auto custom-scrollbar transition-all duration-300 ease-out ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className={`w-full mb-8 pb-4 border-b-8 ${theme.border} flex justify-between items-end`}>
                            <h2 className={`text-3xl md:text-4xl font-black ${theme.primary} uppercase tracking-tighter`} style={{ fontSize: '1.8em', lineHeight: 1.1 }}>{slides[currentSlide].title}</h2>
                            <span className={`text-base font-black ${theme.primary} opacity-40 uppercase mb-2 tracking-widest`}>Slide {currentSlide + 1} / {slides.length}</span>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-xl md:text-2xl space-y-10 w-full animate-fade-in font-bold whitespace-pre-wrap" style={{ fontSize: '1.2em', lineHeight: 1.3 }}>
                                <MathRenderer content={slides[currentSlide].content} highlightClass={theme.highlight} />
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-[10px] border-indigo-200 shadow-2xl animate-fade-in-up">
                                <h3 className={`text-xl font-black mb-8 flex items-center gap-4 ${theme.primary}`} style={{ fontSize: '1.1em', lineHeight: 1.1 }}><Star className="w-12 h-12 fill-current" /> Ví dụ Tiêu biểu</h3>
                                <div className="text-xl md:text-2xl mb-12 font-extrabold text-slate-800 dark:text-slate-100" style={{ fontSize: '1.2em', lineHeight: 1.3 }}><MathRenderer content={slides[currentSlide].examples[0].problem}/></div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-16 py-8 bg-indigo-600 text-white font-black text-xl rounded-[3rem] shadow-2xl hover:brightness-110 active:scale-95 transition-all uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                                ) : (
                                    <div className="w-full p-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-[3rem] border-l-[1.5rem] border-emerald-500 animate-fade-in text-xl font-bold" style={{ fontSize: '1.1em', lineHeight: 1.3 }}>
                                        <div className="text-xs font-black text-emerald-600 uppercase mb-4 opacity-50">Solution:</div>
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}

                        {viewMode === 'slide' && timer !== null && (
                          <div className="fixed bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                            <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow
                              ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                              {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                            </div>
                          </div>
                        )}
                    </div>
                )}
            </div>

            {/* Sidebar & Navigation buttons... */}
            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-slate-700 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="p-8 bg-white/90 dark:bg-slate-800/90 shadow-2xl rounded-full pointer-events-auto border-4 border-white/20 hover:scale-110 transition-all text-indigo-600 disabled:opacity-30"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-2 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-3 text-slate-400 hover:text-white" title="Danh sách các Slide"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-3 text-slate-400 hover:text-yellow-400" title="Dùng bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-3 text-slate-400 hover:text-indigo-400" title="Học sinh ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-sm font-black text-white min-w-[35px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-3 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Bấm giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {/* Other popups... */}
        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>Bấm giờ Bài giảng</h3>
                    <div className="grid grid-cols-3 gap-4 mb-8">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-3xl font-black text-2xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-black uppercase text-xs tracking-widest">Dừng Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showThemeMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 flex items-center justify-center p-6" onClick={() => setShowThemeMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-10 rounded-[4rem] shadow-2xl w-full max-w-lg text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-8 dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>Giao diện Màu Slide</h3>
                    <div className="grid grid-cols-3 gap-4">
                        {(Object.keys(SLIDE_THEMES) as ThemeKey[]).map((key) => (
                            <button key={key} onClick={() => { setActiveTheme(key); setShowThemeMenu(false); }} className={`p-4 rounded-3xl border-4 transition-all flex flex-col items-center gap-2 ${activeTheme === key ? 'border-indigo-600 scale-105 shadow-xl' : 'border-slate-100 dark:border-slate-700'}`}>
                                <div className={`w-10 h-10 rounded-full ${SLIDE_THEMES[key].bg} border border-slate-300 shadow-inner`}></div>
                                <span className="font-bold text-xs uppercase tracking-tighter">{SLIDE_THEMES[key].name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter" style={{ lineHeight: 1.1 }}>Mục lục Slide: {slides.length} trang</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} className={`p-6 rounded-[2.5rem] text-left border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1 uppercase tracking-widest">TRANG {i+1}</span>
                                <span className="font-bold text-xl leading-tight line-clamp-2 uppercase tracking-tighter">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);

  // Reset hints/reveals when moving to a new question in slide mode
  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) setIsTimerRunning(false);
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;

      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const userVal = userAns?.[i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`) || correctStr.includes(`${label}) đ`);
           if (userVal === true && isCorrectTrue) subCorrect++;
           if (userVal === false && !isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const toggleRevealAnswer = (idx: number) => {
    setRevealedAnswers(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const toggleRevealHint = (idx: number) => {
    setRevealedHints(prev => {
      const newSet = new Set(prev);
      if (newSet.has(idx)) newSet.delete(idx);
      else newSet.add(idx);
      return newSet;
    });
  };

  const handleExport = () => {
    const exportData = {
      type: 'exam',
      config: config,
      data: data,
      timestamp: Date.now()
    };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Exam_${config.topic.replace(/\s+/g, '_')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const slideClass = isSlide 
      ? `pt-2 pb-16 px-12 md:pt-4 md:pb-24 md:px-20 items-start justify-start w-full overflow-y-auto ${isSidePanelOpen ? 'md:w-full' : ''}` 
      : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl';

    const userAns = userAnswers[idx];
    const zoomStyle = { fontSize: `${zoomLevel * 100}%` };

    // Logic: Check if student has answered
    const hasAnswered = () => {
        if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
            return userAns !== undefined;
        }
        if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
            return userAns !== undefined && Object.keys(userAns).length > 0;
        }
        if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
            return typeof userAns === 'string' && userAns.trim().length > 0;
        }
        return false;
    };

    const answered = hasAnswered();
    const isAnswerVisible = showAnswersGlobal || isSubmitted || (revealedAnswers.has(idx) && answered);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 custom-scrollbar transition-all duration-300 ease-out ${slideClass}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start text-left">
            <div className="flex items-center justify-between w-full mb-4 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl" style={{ fontSize: '1.2em' }}>{idx + 1}</span>
                  <span className="text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500">Mức: {q.difficulty}</span>
                </div>

                {q.hints && q.hints.length > 0 && (
                  <button 
                    onClick={() => toggleRevealHint(idx)}
                    className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-sm uppercase tracking-tighter transition-all ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}
                  >
                    <Lightbulb className={`w-5 h-5 ${isHintVisible ? 'animate-pulse' : ''}`} />
                    {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'}
                  </button>
                )}
            </div>

            {/* Headline: line-height 1.1 */}
            <div className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-slate-100 mb-8 border-l-8 border-indigo-600 pl-8 py-2" 
                 style={{ fontSize: '1.5em', lineHeight: 1.1 }}>
                <MathRenderer content={q.content} />
            </div>

            {/* Hint Content: line-height 1.3 */}
            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-8 bg-amber-50 dark:bg-amber-900/20 border-2 border-amber-200 rounded-[3rem] animate-fade-in-up">
                <h5 className="text-amber-700 font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                  <HelpCircle className="w-4 h-4" /> Gợi ý các bước giải:
                </h5>
                <ul className="space-y-4" style={{ lineHeight: 1.3 }}>
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-4 text-amber-800 dark:text-amber-200 font-semibold text-lg">
                      <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 dark:bg-amber-800 flex items-center justify-center text-sm font-black">{hIdx + 1}</span>
                      <MathRenderer content={hint} inline />
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-8 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button 
                      key={oi} 
                      onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} 
                      className={`group flex items-start gap-6 p-6 md:p-8 rounded-[3rem] border-4 transition-all text-left shadow-md ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}
                      style={{ lineHeight: 1.3 }}
                    >
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className={`text-xl md:text-2xl font-bold pt-1 ${userAns === oi ? 'text-white' : OPTION_THEMES[oi].text}`} style={{ fontSize: '1.1em' }}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 md:p-8 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-sm" style={{ lineHeight: 1.3 }}>
                        <div className="text-xl md:text-2xl font-bold mb-6 flex gap-3" style={{ fontSize: '1.1em' }}>
                           <span className="text-indigo-600">{['a','b','c','d'][oi]})</span>
                           <MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline />
                        </div>
                        <div className="flex gap-4">
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}
                           >
                              ĐÚNG
                           </button>
                           <button 
                            onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))}
                            className={`flex-1 py-4 rounded-2xl font-black text-xl border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}
                           >
                              SAI
                           </button>
                        </div>
                    </div>
                ))}

                {(q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) && (
                   <div className="col-span-full">
                      <input 
                        type="text"
                        placeholder="Nhập kết quả..."
                        value={userAns || ''}
                        onChange={(e) => !isSubmitted && setUserAnswers(p => ({...p, [idx]: e.target.value}))}
                        className="w-full max-w-2xl p-8 text-3xl font-black text-center bg-slate-50 dark:bg-slate-800 border-4 border-dashed border-indigo-200 rounded-[3rem] focus:border-indigo-600 outline-none uppercase"
                        style={{ fontSize: '1.2em', lineHeight: 1 }}
                      />
                   </div>
                )}
            </div>

            {/* Answer Display Area: ONLY shown if teacher, submitted, OR student answered and toggled it */}
            {(showAnswersGlobal || isSubmitted || answered) && (
                <>
                    {isAnswerVisible ? (
                        <div className="mt-12 p-10 bg-emerald-50 dark:bg-emerald-900/30 rounded-[4rem] border-4 border-emerald-200 w-full animate-fade-in shadow-2xl relative overflow-hidden group">
                            <button 
                            onClick={() => toggleRevealAnswer(idx)}
                            className="absolute top-6 right-6 p-2 hover:bg-emerald-100 dark:hover:bg-emerald-800 rounded-full transition-colors no-print"
                            >
                            <X className="w-6 h-6 text-emerald-600" />
                            </button>
                            <h4 className="text-2xl font-black text-emerald-700 mb-6 flex items-center gap-4" style={{ fontSize: '1.2em', lineHeight: 1.1 }}>
                            <CheckCircle className="w-12 h-12" /> ĐÁP ÁN: <MathRenderer content={q.correctAnswer} inline />
                            </h4>
                            <div className="text-xl font-semibold" style={{ fontSize: '1.1em', lineHeight: 1.3 }}>
                            <MathRenderer content={q.solution} />
                            </div>
                        </div>
                    ) : (
                        <div 
                        onClick={() => toggleRevealAnswer(idx)}
                        className="mt-12 w-full p-12 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-4 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center justify-center gap-4 cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/20 hover:border-indigo-300 transition-all group no-print"
                        >
                            <div className="w-20 h-20 rounded-full bg-white dark:bg-slate-700 flex items-center justify-center text-slate-400 group-hover:text-indigo-600 group-hover:scale-110 transition-all shadow-md">
                                <Eye className="w-10 h-10" />
                            </div>
                            <span className="text-xl font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Đáp án & Lời giải Chi tiết</span>
                        </div>
                    )}
                </>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <div className="w-32 h-32 bg-indigo-50 dark:bg-indigo-900/50 rounded-[3rem] flex items-center justify-center text-indigo-600 mx-auto mb-10">
                <School className="w-16 h-16" />
            </div>
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>Bài thi: {config.topic}</h2>
            <p className="text-slate-500 font-medium mb-12 italic">Môn: {config.subject} - Lớp: {config.grade}</p>

            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="HỌ VÀ TÊN HỌC SINH..." className="w-full p-8 rounded-[2.5rem] bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-10 border-4 border-transparent focus:border-indigo-600 outline-none transition-all uppercase tracking-tighter" />

            <div className="flex flex-col gap-4">
                <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-3xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">BẮT ĐẦU LÀM BÀI</button>
                {role === 'teacher' && (
                    <button onClick={() => { setIsStarted(true); setShowAnswersGlobal(true); setViewMode('slide'); }} className="text-indigo-600 font-black text-lg uppercase tracking-widest mt-4 hover:underline">Vào trực tiếp (Chế độ giảng dạy)</button>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-4">
                <button onClick={onReset} className="p-3 hover:bg-slate-100 rounded-2xl"><ArrowLeft className="w-6 h-6"/></button>
                <div className="flex flex-col">
                    <h1 className="text-xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter" style={{ lineHeight: 1.1 }}>{config.topic}</h1>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang {viewMode === 'slide' ? 'trình chiếu' : 'làm bài'}: {studentName || 'Giáo viên'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors" title="Lưu đề thi này">
                    <Save className="w-6 h-6" />
                </button>
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && (
                    <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Bật/tắt đáp án nhanh">
                        <Eye className="w-6 h-6" />
                    </button>
                )}
                {!isSubmitted && (
                    <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg transition-all hover:bg-emerald-700">Nộp bài</button>
                )}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">{isFullscreen ? <Minimize className="w-7 h-7"/> : <Maximize className="w-7 h-7"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-10 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-7xl md:text-9xl border-[14px] shadow-[0_40px_80px_rgba(0,0,0,0.5)] backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                      {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                    </div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}
            {viewMode === 'slide' && (
                <div className="fixed bottom-12 left-10 right-10 flex justify-between items-center pointer-events-none z-[70]">
                    <button onClick={() => { setCurrentSlide(s => Math.max(0, s-1)); }} disabled={currentSlide === 0} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronLeft className="w-16 h-16"/></button>
                    <button onClick={() => { setCurrentSlide(s => Math.min(questions.length-1, s+1)); }} disabled={currentSlide === questions.length-1} className="p-8 bg-white/90 shadow-2xl rounded-full pointer-events-auto border-4 border-indigo-50 hover:scale-110 transition-all text-indigo-600"><ChevronRight className="w-16 h-16"/></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-2.5 flex gap-3 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white" title="Mục lục câu hỏi"><LayoutGrid className="w-7 h-7"/></button>
            <button onClick={() => setShowBlackboard(true)} className="p-4 text-slate-400 hover:text-yellow-400" title="Bảng viết tay"><PenTool className="w-7 h-7"/></button>
            <button onClick={() => setShowRandomPicker(true)} className="p-4 text-slate-400 hover:text-indigo-400" title="Gọi tên/Chia nhóm ngẫu nhiên"><Dices className="w-7 h-7"/></button>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-4 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white"><ZoomOut className="w-6 h-6"/></button>
                <span className="text-lg font-black text-white min-w-[40px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white"><ZoomIn className="w-6 h-6"/></button>
            </div>
            <div className="w-px h-10 bg-white/20 mx-2"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ thảo luận"><TimerIcon className="w-7 h-7"/></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">Bấm giờ Câu hỏi</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 4, 5].map(m => (
                            <button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>
                        ))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-5 bg-red-50 text-red-600 rounded-3xl font-black text-xs uppercase tracking-widest">Hủy Hẹn Giờ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] max-w-lg w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-black uppercase tracking-widest text-2xl mb-12">Chúc mừng {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-8 bg-indigo-600 text-white rounded-[3rem] font-black text-2xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">Xem Lời giải Chi tiết</button>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-12 rounded-[5rem] w-full max-w-4xl shadow-2xl" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-10">
                        <h3 className="text-3xl font-black uppercase text-slate-800 dark:text-white tracking-tighter">Cấu trúc đề: {questions.length} câu</h3>
                        <button onClick={() => setShowNav(false)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full"><X className="w-8 h-8"/></button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
                        {questions.map((q, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setViewMode('slide'); setShowNav(false); }} className={`p-6 rounded-[2rem] text-center border-4 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 dark:bg-slate-700 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-xs font-black opacity-60 mb-1">CÂU</span>
                                <span className="font-black text-3xl">{i+1}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ExamConfig, ExamMatrix, StudyGuideData, ExportData } from './types';
import { generateExam, generateStudyGuide } from './services/geminiService';
import ConfigForm from './components/ConfigForm';
import { ExamPreview } from './components/ExamPreview';
import StudyGuidePreview from './components/StudyGuidePreview';
import { GraduationCap, Loader2, Moon, Sun, AlertTriangle, User, School, Download, Keyboard, X, Info } from 'lucide-react';

const App: React.FC = () => {
  const [step, setStep] = useState<'config' | 'preview'>('config');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);
  const [role, setRole] = useState<'teacher' | 'student' | null>(null);
  const [showShortcutHelp, setShowShortcutHelp] = useState(false);

  // Theme State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('theme');
        if (saved) return saved === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
      }
    } catch (e) {}
    return false;
  });

  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      html.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Tránh kích hoạt khi đang gõ text
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.key.toLowerCase() === 'k' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        setShowShortcutHelp(prev => !prev);
      }
      if (e.key.toLowerCase() === 'l' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        setIsDarkMode(prev => !prev);
      }
      if (e.key === 'Escape') {
        setShowShortcutHelp(false);
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async (newConfig: ExamConfig) => {
    setLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      if (newConfig.mode === 'theory') {
        const data = await generateStudyGuide(newConfig);
        setStudyGuideData(data);
        setExamData(null);
      } else {
        const data = await generateExam(newConfig);
        setExamData(data);
        setStudyGuideData(null);
      }
      setStep('preview');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Lỗi hệ thống AI. Vui lòng thử lại sau.");
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (!config || (!examData && !studyGuideData)) return;

    const exportData: ExportData = {
      type: config.mode,
      timestamp: Date.now(),
      config: config,
      data: (config.mode === 'theory' ? studyGuideData : examData) as any
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Studio_${config.topic.replace(/\s+/g, '_')}_${new Date().toLocaleDateString('vi-VN')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const jsonStr = e.target?.result as string;
        const imported = JSON.parse(jsonStr) as ExportData;
        if (!imported.config || !imported.data) throw new Error("File không đúng định dạng.");

        setConfig(imported.config);
        if (imported.type === 'theory') {
          setStudyGuideData(imported.data as StudyGuideData);
          setExamData(null);
        } else {
          setExamData(imported.data as ExamMatrix);
          setStudyGuideData(null);
        }
        setStep('preview');
        setRole('teacher');
      } catch (err: any) {
        setError("Lỗi đọc file: " + err.message);
      }
    };
    reader.readAsText(file);
  };

  const handleReset = () => {
    setStep('config');
    setExamData(null);
    setStudyGuideData(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 font-sans transition-colors duration-300">
      {loading && (
        <div className="fixed inset-0 z-[100] bg-white/90 dark:bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-16 h-16 text-indigo-600 dark:text-indigo-400 animate-spin mb-4" />
          <h3 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tighter">AI Đang Xử Lý Dữ Liệu...</h3>
          <p className="text-slate-500 dark:text-slate-400 font-medium italic">Hệ thống đang soạn thảo nội dung chất lượng cao</p>
        </div>
      )}

      <nav className="bg-white/80 dark:bg-slate-800/80 backdrop-blur-md border-b sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 h-16 flex justify-between items-center">
          <div className="flex items-center gap-3 text-indigo-700 dark:text-indigo-400 cursor-pointer" onClick={handleReset}>
            <div className="bg-indigo-600 p-1.5 rounded-xl text-white">
                <GraduationCap className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-lg font-black leading-none uppercase tracking-tighter">Practice Studio</h1>
              <span className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-400">AI Education Hub</span>
            </div>
          </div>

