            <button onClick={() => setShowRandomPicker(true)} className={`p-3 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`} title="Quay số/Chia nhóm (R)">
                <Dices className="w-7 h-7"/>
                <ShortcutLabel>R</ShortcutLabel>
            </button>
            <div className="w-px h-8 bg-white/20 mx-1"></div>
            <div className="flex items-center gap-2 bg-black/30 rounded-full px-3 py-1">
