                  <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[60%] bg-indigo-400 blur-[120px] rounded-full"></div>
                  <div className="absolute bottom-[10%] right-[-5%] w-[35%] h-[50%] bg-emerald-400 blur-[100px] rounded-full"></div>
               </div>

               <div className="max-w-7xl mx-auto px-4 text-center">
                  <div className="inline-flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full shadow-sm mb-8 animate-bounce-slow">
                    <span className="flex h-2 w-2 rounded-full bg-indigo-600"></span>
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">AI-Powered Education v2.0</span>
