                    { icon: ShieldCheck, title: "Chuẩn GDPT 2018", color: "text-emerald-500", bg: "bg-emerald-50", desc: "Bám sát các quy định mới nhất về trắc nghiệm Đúng/Sai và Trả lời ngắn." },
                    { icon: BookOpen, title: "Đa Dạng Môn", color: "text-blue-500", bg: "bg-blue-50", desc: "Hỗ trợ đầy đủ các môn từ Toán, Lý, Hóa đến Văn, Anh và Hoạt động trải nghiệm." }
                  ].map((f, i) => (
                    <div key={i} className="flex flex-col items-center text-center group">
                      <div className={`w-16 h-16 ${f.bg} dark:bg-slate-800 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform shadow-sm`}>
