              <ExamPreview role={role || 'teacher'} config={config} data={examData} onReset={handleReset} onRegenerate={() => handleGenerate(config)} />
            ) : config.mode === 'theory' && studyGuideData ? (
              <StudyGuidePreview role={role || 'teacher'} config={config} data={studyGuideData} onReset={handleReset} onRegenerate={() => handleGenerate(config)} />
            ) : null}
          </div>
        )}
      </main>

      {/* Footer chỉ hiện ở Landing */}
      {step === 'landing' && (
        <footer className="py-12 border-t border-slate-200 dark:border-slate-800 transition-colors bg-white dark:bg-slate-950">
          <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-6 text-slate-400 text-[10px] font-black uppercase tracking-widest">
            <p>© 2024 Practice Studio. AI Education Hub by Vũ Tiến Lực.</p>
            <div className="flex gap-8">
              <span className="hover:text-indigo-500 cursor-pointer" onClick={() => setShowShortcutHelp(true)}>Hỗ trợ</span>
              <span className="hover:text-indigo-500 cursor-pointer">Bảo mật</span>
              <span className="hover:text-indigo-500 cursor-pointer">Điều khoản</span>
