      {showShortcutHelp && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowShortcutHelp(false)}>
            <div className="bg-white dark:bg-slate-800 rounded-[3rem] w-full max-w-2xl overflow-hidden shadow-2xl border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                    <h3 className="text-2xl font-black uppercase tracking-tighter flex items-center gap-3"><Keyboard className="w-8 h-8"/> Tính năng & Phím tắt</h3>
                    <button onClick={() => setShowShortcutHelp(false)} className="p-2 hover:bg-white/20 rounded-full transition-colors"><X className="w-6 h-6"/></button>
                </div>
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
                    <section className="space-y-4">
                        <h4 className="font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest text-xs flex items-center gap-2"><Info className="w-4 h-4"/> Điều khiển Slide</h4>
                        <div className="space-y-3">
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Hiện/Ẩn đáp án</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">A</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Bảng viết tay</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">B</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Quay số ngẫu nhiên</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">R</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Đồng hồ bấm giờ</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">T</kbd></div>
                        </div>
                    </section>
                    <section className="space-y-4">
                        <h4 className="font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest text-xs flex items-center gap-2"><Info className="w-4 h-4"/> Hệ thống</h4>
                        <div className="space-y-3">
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Toàn màn hình</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">F</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Lưu file cục bộ</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">S</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-medium">Phóng to font</span><kbd className="px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded border border-slate-300 dark:border-slate-500 font-bold text-xs">+</kbd></div>
