            <div className="flex items-center gap-3 text-indigo-700 dark:text-indigo-400 cursor-pointer group" onClick={handleReset}>
              <div className="bg-indigo-600 p-1.5 rounded-xl text-white group-hover:rotate-12 transition-transform shadow-lg shadow-indigo-200 dark:shadow-none">
                  <GraduationCap className="w-6 h-6" />
              </div>
              <h1 className="text-lg font-black leading-none uppercase tracking-tighter hidden sm:block">Studio Luyện Thi AI</h1>
            </div>

            <div className="flex items-center gap-4">
               {step === 'config' && (
                 <button onClick={() => setStep('dashboard')} className="text-xs font-bold text-slate-500 hover:text-indigo-600 flex items-center gap-1 uppercase tracking-widest transition-colors">
                    <LayoutDashboard className="w-4 h-4"/> Quay lại Menu
