               )}
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                 {isDarkMode ? <Sun className="w-5 h-5 text-yellow-500" /> : <Moon className="w-5 h-5 text-slate-600" />}
               </button>
            </div>
          </div>
        </nav>
      )}

      <main className="transition-all duration-500">
        {error && (
          <div className="max-w-4xl mx-auto my-6 p-5 bg-red-50 dark:bg-red-900/20 border-2 border-red-200 dark:border-red-800 rounded-2xl flex items-center gap-4 text-red-700 dark:text-red-400 animate-fade-in shadow-lg">
             <AlertTriangle className="w-6 h-6 flex-shrink-0" />
