import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData, MatrixRow, DifficultyLevel } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Gợi ý cấu trúc ma trận đề thi từ AI
 */
export const suggestMatrixStructure = async (subject: string, grade: string, title: string): Promise<MatrixRow[]> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const prompt = `
Bạn là chuyên gia khảo thí. Hãy gợi ý một cấu trúc ma trận đề thi chuẩn cho:
Môn: ${subject}
Lớp: ${grade}
Tiêu đề/Phạm vi: ${title}

YÊU CẦU:
1. Đề xuất từ 3-6 chuyên đề (topics) trọng tâm.
2. Phân bổ mức độ khó (level) từ Nhận biết đến Vận dụng cao.
3. Phân bổ loại câu hỏi (type) phù hợp (Trắc nghiệm cho mức dễ, Tự luận cho mức khó).
4. Tổng số câu nên dao động từ 10-25 câu tùy độ khó.

TRẢ VỀ JSON MẢNG CÁC ĐỐI TƯỢNG MatrixRow:
[
  { "topic": "Tên chuyên đề", "level": "Mức độ", "count": số_câu, "type": "Loại câu" }
]

LƯU Ý:
- "level" phải thuộc: "Rất dễ (Nhận biết)", "Dễ (Thông hiểu)", "Trung bình (Vận dụng)", "Khó (Vận dụng cao)".
- "type" phải thuộc: "Trắc nghiệm (4 chọn 1)", "Trắc nghiệm Đúng/Sai", "Tự luận".
  `;

  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        level: { type: Type.STRING },
        count: { type: Type.INTEGER },
        type: { type: Type.STRING },
      },
      required: ["topic", "level", "count", "type"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      },
    });

    return JSON.parse(response.text) as MatrixRow[];
  } catch (error) {
    console.error("Matrix suggestion failed:", error);
    return [];
  }
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let difficultyInstruction = "";
  let structureInstruction = "";

  if (config.mode === 'matrix' && config.matrixRows) {
      structureInstruction = "CẤU TRÚC ĐỀ THI (BẮT BUỘC TUÂN THỦ): \n";
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu về chủ đề "${row.topic}" - Mức độ: ${row.level} - Dạng: ${row.type}.\n`;
      });
      difficultyInstruction = "Tuân thủ chính xác mức độ khó đã quy định cho từng phần ở trên.";
  } else {
      const isMixed = config.questionType === QuestionType.MIXED;
      if (isMixed) {
        difficultyInstruction = `
          TUÂN THỦ CẤU TRÚC ĐỀ THI MỚI (CT GDPT 2018):
          - Trắc nghiệm nhiều lựa chọn (4 chọn 1).
          - Trắc nghiệm Đúng/Sai (Mỗi câu hỏi có 4 ý a,b,c,d).
          - Trắc nghiệm trả lời ngắn (Điền kết quả).
        `;
      } else {
        difficultyInstruction = config.difficultyMode === 'progressive' 
          ? 'Tăng dần từ Nhận biết/Thông hiểu đến Vận dụng/Vận dụng cao.' 
          : `Cố định ở mức: ${config.targetLevel}`;
      }

      structureInstruction = `
        Chủ đề: "${config.topic}".
        Số lượng: ${config.questionCount} câu.
        Loại: ${config.questionType}.
      `;
  }

  let promptText = `
Bạn là chuyên gia soạn đề kiểm tra chuẩn CTGDPT 2018.
Tạo đề môn ${config.subject}, lớp ${config.grade}.

QUY TẮC CẤU TRÚC CÂU HỎI (BẮT BUỘC):
1. TRẮC NGHIỆM 4 CHỌN 1:
   - type: "Trắc nghiệm (4 chọn 1)"
   - options: Phải có đúng 4 phần tử. Mỗi phần tử bắt đầu bằng A., B., C., D.
   - correctAnswer: Chỉ gồm 1 chữ cái (VD: "A")

2. TRẮC NGHIỆM ĐÚNG/SAI:
   - type: "Trắc nghiệm Đúng/Sai"
   - content: Là câu dẫn chung.
   - options: Phải có đúng 4 mệnh đề con, bắt đầu bằng a), b), c), d).
   - correctAnswer: Phải liệt kê đúng/sai cho 4 ý. Format: "a: Đúng, b: Sai, c: Đúng, d: Sai"

3. TRẢ LỜI NGẮN / TỰ LUẬN:
   - type: "Tự luận"
   - options: Để mảng rỗng [].
   - correctAnswer: Đáp số hoặc từ khóa ngắn gọn.

YÊU CẦU KHÁC:
- ĐỊNH DẠNG TOÁN HỌC: Luôn dùng LaTeX trong dấu $ (VD: $x^2$, $\\frac{a}{b}$).
- LỜI GIẢI (solution): Viết ngắn gọn, súc tích.
- NGÔN NGỮ: Tiếng Việt chuẩn mực.

${structureInstruction}
${difficultyInstruction}

Trả về JSON theo schema yêu cầu.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["id", "content", "difficulty", "correctAnswer", "solution", "hints", "type"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      summary: { type: Type.STRING },
      questions: { type: Type.ARRAY, items: questionSchema },
    },
    required: ["summary", "questions", "objectives"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.4,
      },
    });

    return JSON.parse(response.text) as ExamMatrix;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 minute.");
    }
    throw error;
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let promptText = `
    Bạn là một giảng viên ưu tú. Hãy soạn bài giảng slide tóm tắt kiến thức trọng tâm.
    Môn: ${config.subject}, ${config.grade}. Chủ đề: "${config.topic}".

    YÊU CẦU ĐỊNH DẠNG NỘI DUNG (content) CỰC KỲ KHẮT KHE:
    1. BẮT BUỘC trình bày theo dạng các ý chính.
    2. Mỗi ý chính PHẢI bắt đầu bằng ký tự "★".
    3. PHẢI dùng dấu xuống dòng thực tế (phím Enter) sau mỗi ý để tách các "★" ra các dòng khác nhau. Tuyệt đối không viết chữ "\\n" vào trong chuỗi JSON, hãy dùng ký tự xuống dòng thực sự được escape bởi JSON.
    4. ĐỊNH DẠNG TỪ KHÓA: Các định nghĩa, từ khóa, tên định lý quan trọng PHẢI bao quanh bởi dấu ** (Ví dụ: **Định luật Ôm**). Những phần này sẽ được bôi màu.
    5. TOÁN HỌC: Luôn dùng LaTeX đặt trong dấu $ (Ví dụ: $F = m.a$).
    6. Ví dụ cấu trúc mong muốn:
       ★ **Định nghĩa**: Nội dung định nghĩa...
       ★ **Công thức**: $A = B + C$

    Trả về JSON.
  `;

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      sections: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            content: { type: Type.STRING, description: "Nội dung slide với dấu ★ đầu dòng và xuống dòng thực tế." },
            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING },
                  solution: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                },
                required: ["problem", "solution", "explanation"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "overview", "sections"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({
            inlineData: {
                mimeType: config.uploadedFile.mimeType,
                data: config.uploadedFile.data
            }
        });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.5,
      },
    });

    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    if (error.message?.includes("429")) {
        throw new Error("Hệ thống AI đang quá tải (Quota limit). Vui lòng thử lại sau 1 phút.");
    }
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { SUBJECTS, GRADES, DIFFICULTY_LEVELS, QUESTION_TYPES, SAMPLE_TOPICS } from '../constants';
import { ExamConfig, Subject, QuestionType, DifficultyLevel, GenMode, MatrixRow } from '../types';
import { suggestMatrixStructure } from '../services/geminiService';
import { 
  BookOpen, Brain, Sparkles, Layers, ListChecks, 
  Presentation as PresentationIcon, FileText, Upload, 
  Image as ImageIcon, X, Paperclip, Plus, Trash2, 
  Table2, Loader2, Wand2, Info
} from 'lucide-react';

interface ConfigFormProps {
  onGenerate: (config: ExamConfig) => void;
  isLoading: boolean;
  onImport: (file: File) => void;
  forcedMode?: GenMode;
}

const ConfigForm: React.FC<ConfigFormProps> = ({ onGenerate, isLoading, onImport, forcedMode }) => {
  const [mode, setMode] = useState<GenMode>(forcedMode || 'exam');
  const [subject, setSubject] = useState<Subject | string>(Subject.MATH);
  const [grade, setGrade] = useState<string>(GRADES[11]); 
  const [isSuggesting, setIsSuggesting] = useState(false);

  useEffect(() => {
    if (forcedMode) setMode(forcedMode);
  }, [forcedMode]);

  const [topic, setTopic] = useState<string>('');
  const [questionType, setQuestionType] = useState<QuestionType>(QuestionType.MULTIPLE_CHOICE);
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficultyMode, setDifficultyMode] = useState<'progressive' | 'fixed'>('progressive');
  const [targetLevel, setTargetLevel] = useState<DifficultyLevel>(DifficultyLevel.MEDIUM);

  const [matrixTitle, setMatrixTitle] = useState<string>('');
  const [matrixRows, setMatrixRows] = useState<MatrixRow[]>([
    { topic: '', level: DifficultyLevel.EASY, count: 2, type: QuestionType.MULTIPLE_CHOICE },
  ]);

  const [uploadedFile, setUploadedFile] = useState<{name: string, data: string, mimeType: string} | null>(null);
  const resourceInputRef = useRef<HTMLInputElement>(null);

  const suggestedTopics = SAMPLE_TOPICS[subject as Subject] || [];

  const handleAddRow = () => {
    setMatrixRows([...matrixRows, { topic: '', level: DifficultyLevel.MEDIUM, count: 2, type: QuestionType.MULTIPLE_CHOICE }]);
  };

  const handleRemoveRow = (index: number) => {
    if (matrixRows.length > 1) {
      const newRows = [...matrixRows];
      newRows.splice(index, 1);
      setMatrixRows(newRows);
    }
  };

  const handleRowChange = (index: number, field: keyof MatrixRow, value: any) => {
    const newRows = [...matrixRows];
    newRows[index] = { ...newRows[index], [field]: value };
    setMatrixRows(newRows);
  };

  const handleSuggestMatrix = async () => {
    if (!matrixTitle.trim()) {
        alert("Vui lòng nhập Tiêu đề đề thi để AI hiểu phạm vi kiến thức!");
        return;
    }
    setIsSuggesting(true);
    try {
        const suggestion = await suggestMatrixStructure(subject, grade, matrixTitle);
        if (suggestion && suggestion.length > 0) {
            setMatrixRows(suggestion);
        }
    } catch (e) {
        console.error(e);
    } finally {
        setIsSuggesting(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalTopic = mode === 'matrix' ? matrixTitle : (topic || (uploadedFile ? "Nội dung từ tài liệu đính kèm" : ""));

    onGenerate({
      mode,
      subject,
      grade,
      topic: finalTopic,
      questionType: mode === 'exam' ? questionType : undefined,
      questionCount: mode === 'exam' ? questionCount : undefined,
      difficultyMode: mode === 'exam' ? difficultyMode : undefined,
      targetLevel: mode === 'exam' && difficultyMode === 'fixed' ? targetLevel : undefined,
      matrixRows: mode === 'matrix' ? matrixRows : undefined,
      includeHints: true,
      uploadedFile: uploadedFile ? { data: uploadedFile.data, mimeType: uploadedFile.mimeType } : null
    });
  };

  const handleResourceFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64String = event.target?.result as string;
        const base64Data = base64String.split(',')[1];
        setUploadedFile({ name: file.name, mimeType: file.type, data: base64Data });
        if (mode !== 'matrix' && !topic) {
          setTopic("Nội dung tài liệu: " + file.name);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUploadedFile = () => {
    setUploadedFile(null);
    if (mode !== 'matrix' && topic.startsWith("Nội dung tài liệu:")) {
        setTopic("");
    }
  };

  const totalMatrixQuestions = matrixRows.reduce((acc, row) => acc + (row.count || 0), 0);

  return (
    <div className="w-full bg-white dark:bg-slate-800 rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative transition-all duration-300">

      {!forcedMode && (
        <div className="flex border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 overflow-x-auto">
          <button onClick={() => setMode('exam')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'exam' ? 'border-blue-600 text-blue-700 bg-white' : 'border-transparent text-slate-500'}`}><ListChecks className="w-5 h-5" /> Đơn lẻ</button>
          <button onClick={() => setMode('matrix')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'matrix' ? 'border-indigo-600 text-indigo-700 bg-white' : 'border-transparent text-slate-500'}`}><Table2 className="w-5 h-5" /> Tổng hợp</button>
          <button onClick={() => setMode('theory')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'theory' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-slate-500'}`}><PresentationIcon className="w-5 h-5" /> Lý thuyết</button>
        </div>
      )}

      <div className="p-8 md:p-10 border-b border-slate-50 dark:border-slate-700 flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
