import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData, MatrixRow, DifficultyLevel } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Gợi ý cấu trúc ma trận đề thi từ AI
 */
export const suggestMatrixStructure = async (subject: string, grade: string, title: string): Promise<MatrixRow[]> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const prompt = `
Bạn là chuyên gia khảo thí. Hãy gợi ý một cấu trúc ma trận đề thi chuẩn cho:
Môn: ${subject}
Lớp: ${grade}
Tiêu đề/Phạm vi: ${title}

YÊU CẦU:
1. Đề xuất từ 3-6 chuyên đề (topics) trọng tâm.
2. Phân bổ mức độ khó (level) từ Nhận biết đến Vận dụng cao.
3. Phân bổ loại câu hỏi (type) phù hợp.
4. Tổng số câu nên dao động từ 10-25 câu.

TRẢ VỀ JSON MẢNG MatrixRow:
[
  { "topic": "Tên chuyên đề", "level": "Mức độ", "count": số_câu, "type": "Loại câu" }
]
  `;

  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        level: { type: Type.STRING },
        count: { type: Type.INTEGER },
        type: { type: Type.STRING },
      },
      required: ["topic", "level", "count", "type"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      },
    });

    return JSON.parse(response.text) as MatrixRow[];
  } catch (error) {
    console.error("Matrix suggestion failed:", error);
    return [];
  }
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let structureInstruction = "";
  if (config.mode === 'matrix' && config.matrixRows) {
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu, Chủ đề: "${row.topic}", Mức: ${row.level}, Dạng: ${row.type}.\n`;
      });
  } else {
      structureInstruction = `Chủ đề: "${config.topic}", Số lượng: ${config.questionCount} câu, Dạng: ${config.questionType}.`;
  }

  let promptText = `
Bạn là chuyên gia soạn đề kiểm tra môn ${config.subject}, lớp ${config.grade}.

QUY TẮC LATEX TRONG JSON (BẮT BUỘC - ĐỂ TRÁNH LỖI RENDER):
1. Mọi công thức toán học PHẢI đặt trong dấu $...$ (Ví dụ: $V = \\\\frac{1}{3}Bh$).
2. Trong chuỗi JSON, dấu gạch chéo ngược (backslash) của LaTeX PHẢI được escape bằng HAI dấu gạch chéo ngược (\\\\).
   - SAI: "\\frac{a}{b}"
   - ĐÚNG: "\\\\frac{a}{b}"
3. Tuyệt đối không dùng các ký tự toán học Unicode (như √, π, ∫). PHẢI dùng LaTeX tương ứng (\\\\sqrt, \\\\pi, \\\\int).

QUY TẮC CẤU TRÚC DẠNG CÂU:
- Trắc nghiệm (4 chọn 1): options phải có 4 phần tử bắt đầu bằng A., B., C., D.
- Trắc nghiệm Đúng/Sai: options phải có 4 phần tử a), b), c), d). correctAnswer định dạng: "a: Đúng, b: Sai, c: Đúng, d: Sai".
- Tự luận: Trả lời ngắn gọn, options để trống [].

YÊU CẦU NỘI DUNG:
${structureInstruction}
- Ngôn ngữ: Tiếng Việt chuẩn xác.
- solution: Giải thích chi tiết các bước.
- hints: Danh sách 3-5 bước gợi ý giải bài.

Trả về JSON.
  `;

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      summary: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      questions: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.INTEGER },
            content: { type: Type.STRING },
            type: { type: Type.STRING },
            difficulty: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            solution: { type: Type.STRING },
            hints: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["id", "content", "type", "difficulty", "correctAnswer", "solution", "hints"],
        }
      },
    },
    required: ["summary", "questions"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.3,
      },
    });

    return JSON.parse(response.text) as ExamMatrix;
  } catch (error: any) {
    throw new Error("Lỗi sinh đề: " + error.message);
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let promptText = `
    Soạn bài giảng slide môn ${config.subject}, ${config.grade}. Chủ đề: "${config.topic}".

    QUY TẮC LATEX (BẮT BUỘC):
    - Dùng $...$ cho công thức.
    - Escape backslash trong JSON: Dùng \\\\ (Ví dụ: $x = \\\\frac{-b \\\\pm \\\\sqrt{\\\\Delta}}{2a}$).

    ĐỊNH DẠNG NỘI DUNG:
    - Trình bày dạng ý chính bằng ký tự "★".
    - Tách dòng thực tế giữa các ý.
    - Bôi đậm từ khóa quan trọng bằng **...**.
  `;

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      sections: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            content: { type: Type.STRING },
            examples: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  problem: { type: Type.STRING },
                  solution: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                },
                required: ["problem", "solution"]
              }
            }
          },
          required: ["title", "content", "examples"]
        }
      }
    },
    required: ["topic", "sections"]
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: promptText,
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.4,
      },
    });

    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    throw new Error("Lỗi sinh bài giảng: " + error.message);
  }
};

