import { Document, Packer, Paragraph, TextRun, AlignmentType, SectionType, Math as DocxMath, MathRun } from 'docx';
import saveAs from 'file-saver';
import { ExamMatrix, Question } from '../types';

/**
 * Phân tách nội dung và tạo các thành phần docx (Text hoặc Equation)
 * @param text Nội dung chứa LaTeX $...$
 * @param mode 'equation' | 'latex'
 * @param isCorrect Nếu là đáp án đúng thì gạch chân/bold (dành cho Text)
 */
const parseContentToDocx = (text: string, mode: 'equation' | 'latex', isCorrect: boolean = false) => {
  if (!text) return [];

  // Tách nội dung dựa trên $...$ (LaTeX)
  const parts = text.split(/(\$[^$]+\$)/g);

  return parts.filter(Boolean).map(part => {
    if (part.startsWith('$') && part.endsWith('$')) {
      if (mode === 'equation') {
        const latex = part.slice(1, -1);
        // Render Equation chuẩn Microsoft Word (Alt + =)
        return new DocxMath({
          children: [
            new MathRun(latex.replace(/\\\\/g, '\\'))
          ]
        });
      } else {
        // Chế độ LaTeX: Giữ nguyên $...$ dưới dạng văn bản thường
        return new TextRun({
          text: part,
          size: 26, // 13pt
          font: "Times New Roman",
          underline: isCorrect ? {} : undefined,
          bold: isCorrect
        });
      }
    }

    return new TextRun({
      text: part.replace(/\*\*/g, ""), // Xóa markdown bold
      size: 26,
      font: "Times New Roman",
      underline: isCorrect ? {} : undefined,
      bold: isCorrect
    });
  });
};

/**
 * Kiểm tra xem một phương án có phải là đáp án đúng không
 */
const isOptionCorrect = (q: Question, label: string, index: number): boolean => {
  const correctStr = q.correctAnswer.trim().toUpperCase();
  const labels = ["A", "B", "C", "D"];

  if (labels.includes(correctStr)) {
    return labels[index] === correctStr;
  }

  if (label.trim().toUpperCase().startsWith(correctStr)) {
    return true;
  }

  return false;
};

/**
 * Hàm xuất Word dùng chung cho cả 2 dạng
 */
export const exportExamToWord = async (data: ExamMatrix, subject: string, grade: string, mode: 'equation' | 'latex' = 'equation') => {
  const children: any[] = [
    // --- TIÊU ĐỀ ---
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({ text: "SỞ GIÁO DỤC VÀ ĐÀO TẠO", size: 24, font: "Times New Roman" }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({ text: `ĐỀ KIỂM TRA MÔN ${subject.toUpperCase()} - KHỐI ${grade.toUpperCase()}`, bold: true, size: 30, font: "Times New Roman" }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({ text: `Thời gian làm bài: 45 phút (không kể thời gian giao đề)`, italics: true, size: 22, font: "Times New Roman" }),
      ],
    }),
    new Paragraph({ text: "", spacing: { after: 400 } }),

    // --- PHẦN 1: ĐỀ BÀI ---
    new Paragraph({
      children: [new TextRun({ text: "I. PHẦN CÂU HỎI", bold: true, size: 28, font: "Times New Roman", underline: {} })],
      spacing: { after: 200 }
    }),
  ];

  data.questions.forEach((q, index) => {
    children.push(
      new Paragraph({
        spacing: { before: 240, after: 120 },
        children: [
          new TextRun({ text: `Câu ${index + 1}: `, bold: true, size: 26, font: "Times New Roman" }),
          ...parseContentToDocx(q.content, mode),
        ],
      })
    );

    if (q.options && q.options.length > 0) {
      children.push(
        new Paragraph({
          spacing: { after: 120 },
          children: q.options.flatMap((opt, oi) => {
            const label = ["A. ", "B. ", "C. ", "D. "][oi] || "";
            const cleanOpt = opt.replace(/^[A-D][\.\)\s]+/, "");
            // Dạng LaTeX (Dạng 2) thì gạch chân đáp án đúng ở đề
            const isCorrect = mode === 'latex' ? isOptionCorrect(q, label, oi) : false;

            return [
              new TextRun({ 
                text: label, 
                bold: isCorrect, 
                size: 26, 
                font: "Times New Roman",
                underline: isCorrect ? {} : undefined 
              }),
              ...parseContentToDocx(cleanOpt, mode, isCorrect),
              new TextRun({ text: "            " }),
            ];
          }),
        })
      );
    }
  });

  // --- NGẮT TRANG ---
  children.push(new Paragraph({ text: "", pageBreakBefore: true }));

  // --- PHẦN 2: HƯỚNG DẪN GIẢI ---
  children.push(
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 200, after: 400 },
      children: [
        new TextRun({ text: mode === 'equation' ? "ĐÁP ÁN & LỜI GIẢI CHI TIẾT" : "PHẦN II: HƯỚNG DẪN GIẢI CHI TIẾT", bold: true, size: 32, font: "Times New Roman" }),
      ],
    })
  );

  data.questions.forEach((q, index) => {
    // Viết lại câu hỏi trong phần lời giải (Dạng 2 hoặc Equation đều nên có để tiện theo dõi)
    children.push(
      new Paragraph({
        spacing: { before: 400, after: 150 },
        children: [
          new TextRun({ text: `Câu ${index + 1}: `, bold: true, size: 26, font: "Times New Roman" }),
          ...parseContentToDocx(q.content, mode),
        ],
      })
    );

    // Hiển thị lại các phương án
    if (q.options && q.options.length > 0) {
      children.push(
        new Paragraph({
          spacing: { after: 150 },
          children: q.options.flatMap((opt, oi) => {
            const label = ["A. ", "B. ", "C. ", "D. "][oi] || "";
            const cleanOpt = opt.replace(/^[A-D][\.\)\s]+/, "");
            const isCorrect = isOptionCorrect(q, label, oi);
            return [
              new TextRun({ text: label, bold: isCorrect, size: 24, font: "Times New Roman", underline: isCorrect ? {} : undefined }),
              ...parseContentToDocx(cleanOpt, mode, isCorrect),
              new TextRun({ text: "      " }),
            ];
          }),
        })
      );
    }

    children.push(
      new Paragraph({
        spacing: { before: 100, after: 100 },
        children: [
          new TextRun({ text: "=> Chọn đáp án: ", bold: true, size: 26, font: "Times New Roman" }),
          new TextRun({ text: q.correctAnswer, bold: true, color: "FF0000", size: 26, font: "Times New Roman" }),
        ],
      }),
      new Paragraph({
        spacing: { before: 100, after: 300 },
        children: [
          new TextRun({ text: "Lời giải chi tiết: ", bold: true, italics: true, size: 26, font: "Times New Roman" }),
          ...parseContentToDocx(q.solution, mode),
        ],
      }),
      new Paragraph({
        border: { bottom: { color: "CCCCCC", space: 1, style: "single", size: 6 } }
      })
    );
  });

  const doc = new Document({
    sections: [{
      properties: { type: SectionType.CONTINUOUS },
      children: children
    }]
  });

  try {
    const blob = await Packer.toBlob(doc);
    const fileName = mode === 'equation' ? `De_Thi_Equation_${subject}.docx` : `De_Thi_Latex_Dang2_${subject}.docx`;
    saveAs(blob, fileName.replace(/\s+/g, '_'));
  } catch (error) {
    console.error("Lỗi khi tạo file Word:", error);
    alert("Không thể tạo file Word. Vui lòng thử lại.");
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const ShortcutLabel = ({ children }: { children: React.ReactNode }) => (
    <span className="absolute -top-1.5 -right-1.5 bg-indigo-500/90 text-white text-[8px] font-black px-1 rounded border border-white/30 shadow-sm pointer-events-none">{children}</span>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 ${isSlide ? 'pt-4 pb-24 px-12 md:px-20 items-start justify-start w-full overflow-y-auto' : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-6 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.6em] font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 whitespace-nowrap">Mức: {q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-3 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 rounded-2xl hover:text-indigo-600 transition-colors relative" title="Đọc tiếng Việt (V)"><Volume2 className="w-6 h-6" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-[0.6em] uppercase transition-all relative ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}><Lightbulb className="w-5 h-5" /> {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'} {isSlide && <ShortcutLabel>H</ShortcutLabel>}</button>
                )}
            </div>

            <div className="text-[1.2em] font-extrabold text-slate-900 dark:text-slate-100 mb-8 border-l-[0.3em] border-indigo-600 pl-8 py-1 leading-tight w-full">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-10 bg-amber-50/50 dark:bg-amber-900/10 border-[4px] border-amber-300 rounded-[3rem] animate-fade-in-up shadow-2xl">
                <h5 className="text-amber-700 font-black text-[0.8em] uppercase tracking-tighter mb-8 flex items-center gap-4"><HelpCircle className="w-10 h-10" /> CÁC BƯỚC GIẢI CHI TIẾT:</h5>
                <ul className="space-y-8">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-6 text-amber-950 dark:text-amber-50 font-black text-[0.7em] leading-tight">
                      <span className="flex-shrink-0 w-12 h-12 rounded-2xl bg-amber-600 text-white flex items-center justify-center text-[1em] font-black shadow-lg">{hIdx + 1}</span>
                      <div className="pt-1 flex-grow overflow-x-auto"><MathRenderer content={hint} inline /></div>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-6 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button key={oi} onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} className={`group flex items-center gap-6 p-6 rounded-[2.5rem] border-[4px] transition-all text-left shadow-xl ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}>
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-[0.8em] shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className="text-[0.8em] font-black pt-1"><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-md">
                        <div className="text-[0.8em] font-black mb-6 flex gap-3"><span className="text-indigo-600">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-4">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-10 p-10 bg-emerald-50 dark:bg-emerald-900/20 rounded-[4rem] border-[4px] border-emerald-200 w-full animate-fade-in shadow-2xl relative">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-6 right-6 p-2 hover:bg-emerald-100 rounded-full no-print"><X className="w-6 h-6 text-emerald-600" /></button>
                    <h4 className="text-[0.9em] font-black text-emerald-700 mb-6 flex items-center gap-4"><CheckCircle className="w-10 h-10" /> ĐÁP ÁN ĐÚNG: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.7em] font-bold leading-relaxed border-t-2 border-emerald-100 pt-6"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-10 w-full p-10 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-2 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center gap-4 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all group no-print">
                  <Eye className="w-10 h-10 text-slate-400 group-hover:text-indigo-600" />
                  <span className="text-[0.7em] font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Lời giải chi tiết (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] shadow-2xl max-w-xl w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-24 h-24 text-indigo-600 mx-auto mb-10" />
            <h2 className="text-5xl font-black mb-6 dark:text-white uppercase tracking-tighter leading-none">Bắt đầu: {config.topic}</h2>
            <p className="text-2xl text-slate-500 font-medium mb-14 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-10 rounded-[3rem] bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-12 border-4 border-transparent focus:border-indigo-600 outline-none uppercase tracking-tighter" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-4xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-6">
                <button onClick={onReset} className="p-4 hover:bg-indigo-50 rounded-2xl transition-all" title="Về màn hình chính"><Home className="w-8 h-8 text-indigo-600"/></button>
                <div className="flex flex-col">
                    <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h1>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{viewMode === 'slide' ? 'TRÌNH CHIẾU' : 'LÀM BÀI'}: {studentName || 'GIÁO VIÊN'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex gap-2">
                    <button onClick={handleWordExportEquation} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-xs" title="Xuất Word công thức Equation">
                      <FileOutput className="w-4 h-4" /> WORD (EQUATION)
                    </button>
                    <button onClick={handleWordExportLatex} className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white font-black rounded-xl shadow-lg hover:bg-amber-700 transition-all uppercase text-xs" title="Xuất Word Dạng 2 (LaTeX)">
                      <FileOutput className="w-4 h-4" /> WORD (DẠNG 2)
                    </button>
                </div>
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors relative" title="Lưu dự án JSON (S)"><Save className="w-6 h-6" /><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ danh sách"><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ trình chiếu"><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all relative ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Hiện/Ẩn đáp án (A)"><Eye className="w-6 h-6" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg hover:bg-emerald-700 transition-all">Nộp bài</button>}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 relative" title="Toàn màn hình (F)">{isFullscreen ? <Minimize className="w-8 h-8"/> : <Maximize className="w-8 h-8"/>}<ShortcutLabel>F</ShortcutLabel></button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-8xl md:text-9xl border-[16px] shadow-2xl backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}
            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronLeft className="w-16 h-16"/><ShortcutLabel>←</ShortcutLabel></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronRight className="w-16 h-16"/><ShortcutLabel>→</ShortcutLabel></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-3 flex gap-4 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white relative" title="Mục lục đề (M)"><LayoutGrid className="w-8 h-8"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-4 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`} title="Bảng viết tay (B)"><PenTool className="w-8 h-8"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-4 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`} title="Quay số & Chia nhóm (R)"><Dices className="w-8 h-8"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-10 bg-white/20"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-5 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white relative" title="Thu nhỏ (-)"><ZoomOut className="w-6 h-6"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xl font-black text-white min-w-[50px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white relative" title="Phóng to (+)"><ZoomIn className="w-6 h-6"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-10 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ (T)"><TimerIcon className="w-8 h-8"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-14 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">HẸN GIỜ LÀM BÀI</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-6 bg-red-50 text-red-600 rounded-[2rem] font-black text-xl uppercase">DỪNG HẸN GIỜ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-20 rounded-[5rem] max-w-xl w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-9xl font-black text-indigo-600 dark:text-indigo-400 mb-6 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-3xl text-slate-500 font-black uppercase mb-14">TUYỆT VỜI, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-3xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">XEM CHI TIẾT BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [initialTimerValue, setInitialTimerValue] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Hàm phát tiếng tick-tack
  const playTick = (freq = 800) => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);
      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio not supported or blocked", e);
    }
  };

  // Logic đếm ngược đồng hồ
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) return 0;
          const next = prev - 1;
          // Hiệu ứng âm thanh 5 giây cuối
          if (next <= 5 && next > 0) {
            playTick(next % 2 === 0 ? 800 : 1000);
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  // Reset đồng hồ khi chọn đáp án
  useEffect(() => {
    if (initialTimerValue !== null && isTimerRunning && !isSubmitted) {
      // Tìm xem có sự thay đổi đáp án của câu hỏi hiện tại hay không
      setTimer(initialTimerValue);
    }
  }, [userAnswers[currentSlide]]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const ShortcutLabel = ({ children }: { children: React.ReactNode }) => (
    <span className="absolute -top-1.5 -right-1.5 bg-indigo-500/90 text-white text-[8px] font-black px-1 rounded border border-white/30 shadow-sm pointer-events-none">{children}</span>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 ${isSlide ? 'pt-4 pb-24 px-12 md:px-20 items-start justify-start w-full overflow-y-auto' : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-6 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.6em] font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 whitespace-nowrap">Mức: {q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-3 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 rounded-2xl hover:text-indigo-600 transition-colors relative" title="Đọc tiếng Việt (V)"><Volume2 className="w-6 h-6" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-[0.6em] uppercase transition-all relative ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}><Lightbulb className="w-5 h-5" /> {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'} {isSlide && <ShortcutLabel>H</ShortcutLabel>}</button>
                )}
            </div>

            <div className="text-[1.2em] font-extrabold text-slate-900 dark:text-slate-100 mb-8 border-l-[0.3em] border-indigo-600 pl-8 py-1 leading-tight w-full">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-10 bg-amber-50/50 dark:bg-amber-900/10 border-[4px] border-amber-300 rounded-[3rem] animate-fade-in-up shadow-2xl">
                <h5 className="text-amber-700 font-black text-[0.8em] uppercase tracking-tighter mb-8 flex items-center gap-4"><HelpCircle className="w-10 h-10" /> CÁC BƯỚC GIẢI CHI TIẾT:</h5>
                <ul className="space-y-8">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-6 text-amber-950 dark:text-amber-50 font-black text-[0.7em] leading-tight">
                      <span className="flex-shrink-0 w-12 h-12 rounded-2xl bg-amber-600 text-white flex items-center justify-center text-[1em] font-black shadow-lg">{hIdx + 1}</span>
                      <div className="pt-1 flex-grow overflow-x-auto"><MathRenderer content={hint} inline /></div>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-6 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button key={oi} onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} className={`group flex items-center gap-6 p-6 rounded-[2.5rem] border-[4px] transition-all text-left shadow-xl ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}>
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-[0.8em] shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className="text-[0.8em] font-black pt-1"><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-md">
                        <div className="text-[0.8em] font-black mb-6 flex gap-3"><span className="text-indigo-600">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-4">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-10 p-10 bg-emerald-50 dark:bg-emerald-900/20 rounded-[4rem] border-[4px] border-emerald-200 w-full animate-fade-in shadow-2xl relative">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-6 right-6 p-2 hover:bg-emerald-100 rounded-full no-print"><X className="w-6 h-6 text-emerald-600" /></button>
                    <h4 className="text-[0.9em] font-black text-emerald-700 mb-6 flex items-center gap-4"><CheckCircle className="w-10 h-10" /> ĐÁP ÁN ĐÚNG: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.7em] font-bold leading-relaxed border-t-2 border-emerald-100 pt-6"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-10 w-full p-10 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-2 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center gap-4 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all group no-print">
                  <Eye className="w-10 h-10 text-slate-400 group-hover:text-indigo-600" />
                  <span className="text-[0.7em] font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Lời giải chi tiết (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] shadow-2xl max-w-xl w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-24 h-24 text-indigo-600 mx-auto mb-10" />
            <h2 className="text-5xl font-black mb-6 dark:text-white uppercase tracking-tighter leading-none">Bắt đầu: {config.topic}</h2>
            <p className="text-2xl text-slate-500 font-medium mb-14 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-10 rounded-[3rem] bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-12 border-4 border-transparent focus:border-indigo-600 outline-none uppercase tracking-tighter" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-4xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-6">
                <button onClick={onReset} className="p-4 hover:bg-indigo-50 rounded-2xl transition-all" title="Về màn hình chính"><Home className="w-8 h-8 text-indigo-600"/></button>
                <div className="flex flex-col">
                    <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h1>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{viewMode === 'slide' ? 'TRÌNH CHIẾU' : 'LÀM BÀI'}: {studentName || 'GIÁO VIÊN'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex gap-2">
                    <button onClick={handleWordExportEquation} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-xs" title="Xuất Word công thức Equation">
                      <FileOutput className="w-4 h-4" /> WORD (EQUATION)
                    </button>
                    <button onClick={handleWordExportLatex} className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white font-black rounded-xl shadow-lg hover:bg-amber-700 transition-all uppercase text-xs" title="Xuất Word Dạng 2 (LaTeX)">
                      <FileOutput className="w-4 h-4" /> WORD (DẠNG 2)
                    </button>
                </div>
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors relative" title="Lưu dự án JSON (S)"><Save className="w-6 h-6" /><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ danh sách"><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ trình chiếu"><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all relative ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Hiện/Ẩn đáp án (A)"><Eye className="w-6 h-6" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg hover:bg-emerald-700 transition-all">Nộp bài</button>}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 relative" title="Toàn màn hình (F)">{isFullscreen ? <Minimize className="w-8 h-8"/> : <Maximize className="w-8 h-8"/>}<ShortcutLabel>F</ShortcutLabel></button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-8xl md:text-9xl border-[16px] shadow-2xl backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}
            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronLeft className="w-16 h-16"/><ShortcutLabel>←</ShortcutLabel></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronRight className="w-16 h-16"/><ShortcutLabel>→</ShortcutLabel></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-3 flex gap-4 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white relative" title="Mục lục đề (M)"><LayoutGrid className="w-8 h-8"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-4 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`} title="Bảng viết tay (B)"><PenTool className="w-8 h-8"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-4 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`} title="Quay số & Chia nhóm (R)"><Dices className="w-8 h-8"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-10 bg-white/20"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-5 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white relative" title="Thu nhỏ (-)"><ZoomOut className="w-6 h-6"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xl font-black text-white min-w-[50px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white relative" title="Phóng to (+)"><ZoomIn className="w-6 h-6"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-10 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ (T)"><TimerIcon className="w-8 h-8"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-14 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">HẸN GIỜ LÀM BÀI</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setInitialTimerValue(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setInitialTimerValue(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-6 bg-red-50 text-red-600 rounded-[2rem] font-black text-xl uppercase">DỪNG HẸN GIỜ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-20 rounded-[5rem] max-w-xl w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-9xl font-black text-indigo-600 dark:text-indigo-400 mb-6 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-3xl text-slate-500 font-black uppercase mb-14">TUYỆT VỜI, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-3xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">XEM CHI TIẾT BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1.5); 
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [initialTimerValue, setInitialTimerValue] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Hàm phát tiếng tick-tack vui nhộn
  const playTick = (freq = 800) => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      // Tạo âm sắc vui nhộn hơn bằng cách thay đổi tần số nhanh
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(freq * 0.5, ctx.currentTime + 0.1);

      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);

      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio not supported or blocked", e);
    }
  };

  // Logic đếm ngược đồng hồ
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) {
            setIsTimerRunning(false);
            return 0;
          }
          const next = prev - 1;
          // Hiệu ứng âm thanh 5 giây cuối
          if (next <= 5 && next > 0) {
            playTick(next % 2 === 0 ? 1200 : 900);
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  // Ẩn đồng hồ khi học sinh đã chọn xong đáp án
  useEffect(() => {
    if (userAnswers[currentSlide] !== undefined && isTimerRunning) {
      setTimer(null);
      setIsTimerRunning(false);
    }
  }, [userAnswers[currentSlide]]);

  // Tự động hiện lại đồng hồ khi sang câu mới nếu trước đó có cài đặt timer
  useEffect(() => {
    if (initialTimerValue !== null && viewMode === 'slide' && !isSubmitted) {
      const hasAnswered = userAnswers[currentSlide] !== undefined;
      // Nếu chưa trả lời câu này thì hiện lại đồng hồ với thời gian ban đầu
      if (!hasAnswered) {
        setTimer(initialTimerValue);
        setIsTimerRunning(true);
      } else {
        // Nếu đã trả lời rồi thì ẩn đi
        setTimer(null);
        setIsTimerRunning(false);
      }
    }
  }, [currentSlide, viewMode]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const ShortcutLabel = ({ children }: { children: React.ReactNode }) => (
    <span className="absolute -top-1.5 -right-1.5 bg-indigo-500/90 text-white text-[8px] font-black px-1 rounded border border-white/30 shadow-sm pointer-events-none">{children}</span>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 ${isSlide ? 'pt-4 pb-24 px-12 md:px-20 items-start justify-start w-full overflow-y-auto' : 'p-8 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-6 no-print">
                <div className="flex items-center gap-4">
                  <span className="w-16 h-16 rounded-3xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-xl flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.6em] font-black uppercase tracking-widest px-4 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 whitespace-nowrap">Mức: {q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-3 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 rounded-2xl hover:text-indigo-600 transition-colors relative" title="Đọc tiếng Việt (V)"><Volume2 className="w-6 h-6" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`flex items-center gap-2 px-6 py-2 rounded-2xl font-black text-[0.6em] uppercase transition-all relative ${isHintVisible ? 'bg-amber-500 text-white shadow-lg' : 'bg-amber-50 text-amber-600 border-2 border-amber-200'}`}><Lightbulb className="w-5 h-5" /> {isHintVisible ? 'Đóng Gợi Ý' : 'Xem Gợi Ý'} {isSlide && <ShortcutLabel>H</ShortcutLabel>}</button>
                )}
            </div>

            <div className="text-[1.2em] font-extrabold text-slate-900 dark:text-slate-100 mb-8 border-l-[0.3em] border-indigo-600 pl-8 py-1 leading-tight w-full">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-10 p-10 bg-amber-50/50 dark:bg-amber-900/10 border-[4px] border-amber-300 rounded-[3rem] animate-fade-in-up shadow-2xl">
                <h5 className="text-amber-700 font-black text-[0.8em] uppercase tracking-tighter mb-8 flex items-center gap-4"><HelpCircle className="w-10 h-10" /> CÁC BƯỚC GIẢI CHI TIẾT:</h5>
                <ul className="space-y-8">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="flex gap-6 text-amber-950 dark:text-amber-50 font-black text-[0.7em] leading-tight">
                      <span className="flex-shrink-0 w-12 h-12 rounded-2xl bg-amber-600 text-white flex items-center justify-center text-[1em] font-black shadow-lg">{hIdx + 1}</span>
                      <div className="pt-1 flex-grow overflow-x-auto"><MathRenderer content={hint} inline /></div>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-6 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button key={oi} onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} className={`group flex items-center gap-6 p-6 rounded-[2.5rem] border-[4px] transition-all text-left shadow-xl ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white scale-[1.02]' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}>
                        <span className={`w-12 h-12 flex-shrink-0 rounded-2xl flex items-center justify-center font-black text-[0.8em] shadow-lg ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className="text-[0.8em] font-black pt-1"><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-6 bg-slate-50 dark:bg-slate-800 rounded-[3rem] border-2 border-slate-200 dark:border-slate-700 shadow-md">
                        <div className="text-[0.8em] font-black mb-6 flex gap-3"><span className="text-indigo-600">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-4">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl' : 'bg-white text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-4 rounded-2xl font-black text-[0.6em] border-2 transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white shadow-xl' : 'bg-white text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-10 p-10 bg-emerald-50 dark:bg-emerald-900/20 rounded-[4rem] border-[4px] border-emerald-200 w-full animate-fade-in shadow-2xl relative">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-6 right-6 p-2 hover:bg-emerald-100 rounded-full no-print"><X className="w-6 h-6 text-emerald-600" /></button>
                    <h4 className="text-[0.9em] font-black text-emerald-700 mb-6 flex items-center gap-4"><CheckCircle className="w-10 h-10" /> ĐÁP ÁN ĐÚNG: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.7em] font-bold leading-relaxed border-t-2 border-emerald-100 pt-6"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-10 w-full p-10 bg-slate-100 dark:bg-slate-800 rounded-[4rem] border-2 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center gap-4 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all group no-print">
                  <Eye className="w-10 h-10 text-slate-400 group-hover:text-indigo-600" />
                  <span className="text-[0.7em] font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Hiện Lời giải chi tiết (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-16 rounded-[5rem] shadow-2xl max-w-xl w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-24 h-24 text-indigo-600 mx-auto mb-10" />
            <h2 className="text-5xl font-black mb-6 dark:text-white uppercase tracking-tighter leading-none">Bắt đầu: {config.topic}</h2>
            <p className="text-2xl text-slate-500 font-medium mb-14 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="TÊN HỌC SINH..." className="w-full p-10 rounded-[3rem] bg-slate-100 dark:bg-slate-900 text-center text-3xl font-black mb-12 border-4 border-transparent focus:border-indigo-600 outline-none uppercase tracking-tighter" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-4xl shadow-2xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase tracking-tighter">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 p-4 h-20 flex justify-between items-center px-8 no-print">
            <div className="flex items-center gap-6">
                <button onClick={onReset} className="p-4 hover:bg-indigo-50 rounded-2xl transition-all" title="Về màn hình chính"><Home className="w-8 h-8 text-indigo-600"/></button>
                <div className="flex flex-col">
                    <h1 className="text-2xl font-black truncate max-w-md dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h1>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{viewMode === 'slide' ? 'TRÌNH CHIẾU' : 'LÀM BÀI'}: {studentName || 'GIÁO VIÊN'}</span>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex gap-2">
                    <button onClick={handleWordExportEquation} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-xs" title="Xuất Word công thức Equation">
                      <FileOutput className="w-4 h-4" /> WORD (EQUATION)
                    </button>
                    <button onClick={handleWordExportLatex} className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white font-black rounded-xl shadow-lg hover:bg-amber-700 transition-all uppercase text-xs" title="Xuất Word Dạng 2 (LaTeX)">
                      <FileOutput className="w-4 h-4" /> WORD (DẠNG 2)
                    </button>
                </div>
                <button onClick={handleExport} className="p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors relative" title="Lưu dự án JSON (S)"><Save className="w-6 h-6" /><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex gap-3 p-1.5 bg-slate-100 dark:bg-slate-700 rounded-2xl">
                    <button onClick={() => setViewMode('list')} className={`p-3 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ danh sách"><ListChecks className="w-6 h-6"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-3 rounded-xl transition-all ${viewMode === 'slide' ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400'}`} title="Chế độ trình chiếu"><MonitorPlay className="w-6 h-6"/></button>
                </div>
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-3 rounded-xl transition-all relative ${showAnswersGlobal ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`} title="Hiện/Ẩn đáp án (A)"><Eye className="w-6 h-6" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-lg hover:bg-emerald-700 transition-all">Nộp bài</button>}
                <button onClick={toggleFullScreen} className="p-3 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-700 relative" title="Toàn màn hình (F)">{isFullscreen ? <Minimize className="w-8 h-8"/> : <Maximize className="w-8 h-8"/>}<ShortcutLabel>F</ShortcutLabel></button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-12 max-w-6xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-40 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-24 py-12 rounded-[6rem] font-black text-8xl md:text-9xl border-[16px] shadow-2xl backdrop-blur-3xl animate-bounce-slow ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-slate-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l-8 border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}
            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronLeft className="w-16 h-16"/><ShortcutLabel>←</ShortcutLabel></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-8 p-8 bg-white/50 backdrop-blur shadow-2xl rounded-full text-indigo-600 opacity-0 hover:opacity-100 hover:scale-110 transition-all pointer-events-auto disabled:hidden relative"><ChevronRight className="w-16 h-16"/><ShortcutLabel>→</ShortcutLabel></button>
                </div>
            )}
        </main>

        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl rounded-full p-3 flex gap-4 z-[100] border border-white/20 shadow-2xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-4 text-slate-400 hover:text-white relative" title="Mục lục đề (M)"><LayoutGrid className="w-8 h-8"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-4 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`} title="Bảng viết tay (B)"><PenTool className="w-8 h-8"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-4 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`} title="Quay số & Chia nhóm (R)"><Dices className="w-8 h-8"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-10 bg-white/20"></div>
            <div className="flex items-center gap-3 bg-black/30 rounded-full px-5 py-2">
                <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-white relative" title="Thu nhỏ (-)"><ZoomOut className="w-6 h-6"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xl font-black text-white min-w-[50px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-white relative" title="Phóng to (+)"><ZoomIn className="w-6 h-6"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-10 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-4 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`} title="Hẹn giờ (T)"><TimerIcon className="w-8 h-8"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-14 rounded-[4rem] shadow-2xl w-full max-w-sm text-center border-4 border-indigo-100" onClick={e => e.stopPropagation()}>
                    <h3 className="text-3xl font-black mb-10 uppercase dark:text-white tracking-tighter">HẸN GIỜ LÀM BÀI</h3>
                    <div className="grid grid-cols-3 gap-5 mb-10">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setInitialTimerValue(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-6 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-[2rem] font-black text-3xl transition-all shadow-sm">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setInitialTimerValue(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-6 bg-red-50 text-red-600 rounded-[2rem] font-black text-xl uppercase">DỪNG HẸN GIỜ</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-20 rounded-[5rem] max-w-xl w-full text-center shadow-2xl border-t-[2rem] border-indigo-600">
                    <Trophy className="w-32 h-32 text-yellow-500 mx-auto mb-10 animate-bounce" />
                    <h2 className="text-9xl font-black text-indigo-600 dark:text-indigo-400 mb-6 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-3xl text-slate-500 font-black uppercase mb-14">TUYỆT VỜI, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-10 bg-indigo-600 text-white rounded-[4rem] font-black text-3xl hover:bg-indigo-700 transition-all shadow-2xl uppercase tracking-tighter">XEM CHI TIẾT BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/30', border: 'border-blue-300 dark:border-blue-700', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/30', border: 'border-emerald-300 dark:border-emerald-700', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/30', border: 'border-amber-300 dark:border-amber-700', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/30', border: 'border-rose-300 dark:border-rose-700', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 200%
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [initialTimerValue, setInitialTimerValue] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Hàm phát tiếng tick-tack vui nhộn
  const playTick = (freq = 800) => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      // Tạo âm sắc vui nhộn hơn bằng cách thay đổi tần số nhanh
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(freq * 0.5, ctx.currentTime + 0.1);

      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);

      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio not supported or blocked", e);
    }
  };

  // Logic đếm ngược đồng hồ
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) {
            setIsTimerRunning(false);
            return 0;
          }
          const next = prev - 1;
          // Hiệu ứng âm thanh 5 giây cuối
          if (next <= 5 && next > 0) {
            playTick(next % 2 === 0 ? 1200 : 900);
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  // Ẩn đồng hồ khi học sinh đã chọn xong đáp án
  useEffect(() => {
    if (userAnswers[currentSlide] !== undefined && isTimerRunning) {
      setTimer(null);
      setIsTimerRunning(false);
    }
  }, [userAnswers[currentSlide]]);

  // Tự động hiện lại đồng hồ khi sang câu mới nếu trước đó có cài đặt timer
  useEffect(() => {
    if (initialTimerValue !== null && viewMode === 'slide' && !isSubmitted) {
      const hasAnswered = userAnswers[currentSlide] !== undefined;
      // Nếu chưa trả lời câu này thì hiện lại đồng hồ với thời gian ban đầu
      if (!hasAnswered) {
        setTimer(initialTimerValue);
        setIsTimerRunning(true);
      } else {
        // Nếu đã trả lời rồi thì ẩn đi
        setTimer(null);
        setIsTimerRunning(false);
      }
    }
  }, [currentSlide, viewMode]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const ShortcutLabel = ({ children }: { children: React.ReactNode }) => (
    <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
  );

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    // Style zoom luôn ở 200% (zoomLevel mặc định 2.0)
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    return (
      <div className={`flex flex-col bg-white dark:bg-slate-900 ${isSlide ? 'pt-2 pb-16 px-6 md:px-12 items-start justify-start w-full overflow-y-auto' : 'p-6 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-4 no-print border-b border-slate-100 dark:border-slate-800 pb-2">
                <div className="flex items-center gap-2">
                  <span className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-md flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-500 whitespace-nowrap">{q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-1.5 bg-slate-50 dark:bg-slate-800 rounded-lg hover:text-indigo-600 transition-colors relative" title="Đọc (V)"><Volume2 className="w-5 h-5" /></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`p-1.5 rounded-lg transition-all relative ${isHintVisible ? 'bg-amber-100 text-amber-600' : 'bg-slate-50 text-slate-400'}`}><Lightbulb className="w-5 h-5" /></button>
                )}
            </div>

            <div className="text-[1em] font-medium text-slate-900 dark:text-slate-100 mb-6 w-full leading-normal">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-6 p-4 bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-300 rounded-r-xl">
                <h5 className="text-amber-700 font-bold text-[0.6em] uppercase mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4" /> Gợi ý:</h5>
                <ul className="space-y-2 pl-4 list-disc">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="text-amber-900 dark:text-amber-100 text-[0.6em]"><MathRenderer content={hint} inline /></li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-4 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => (
                    <button key={oi} onClick={() => !isSubmitted && setUserAnswers(prev => ({ ...prev, [idx]: oi }))} className={`group flex items-start gap-4 p-4 rounded-2xl border-2 transition-all text-left ${userAns === oi ? 'bg-indigo-600 border-indigo-600 text-white' : `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`}`}>
                        <span className={`w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center font-bold text-[0.6em] ${userAns === oi ? 'bg-white text-indigo-600' : `${OPTION_THEMES[oi].labelBg}`}`}>{['A','B','C','D'][oi]}</span>
                        <div className="text-[0.8em] pt-0.5"><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                    </button>
                ))}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700">
                        <div className="text-[0.7em] font-medium mb-3 flex gap-2"><span className="text-indigo-600 font-bold">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-2">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-2 rounded-xl font-bold text-[0.5em] border transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-2 rounded-xl font-bold text-[0.5em] border transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white' : 'bg-white text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-6 p-6 bg-emerald-50 dark:bg-emerald-900/20 rounded-3xl border border-emerald-200 w-full relative">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-2 right-2 p-1 hover:bg-emerald-100 rounded-full no-print"><X className="w-5 h-5 text-emerald-600" /></button>
                    <h4 className="text-[0.7em] font-bold text-emerald-700 mb-2 flex items-center gap-2"><CheckCircle className="w-6 h-6" /> Đáp án: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.6em] font-medium leading-relaxed border-t border-emerald-100 pt-2"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-6 w-full py-3 bg-slate-100 dark:bg-slate-800 rounded-xl border border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all text-slate-400 hover:text-indigo-600 no-print">
                  <Eye className="w-5 h-5" />
                  <span className="text-[0.6em] font-bold uppercase">Xem Lời giải</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-20 h-20 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h2>
            <p className="text-xl text-slate-500 font-medium mb-10 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="Nhập tên..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-bold mb-8 border-2 border-transparent focus:border-indigo-600 outline-none" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        {/* Compact Header */}
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b sticky top-0 z-50 px-4 h-12 flex justify-between items-center no-print shadow-sm">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-2 hover:bg-slate-100 rounded-lg" title="Home"><Home className="w-5 h-5 text-indigo-600"/></button>
                <h1 className="text-sm font-bold truncate max-w-[150px] dark:text-white uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-1">
                <div className="flex gap-1 mr-2">
                    <button onClick={handleWordExportEquation} className="p-1.5 bg-emerald-600 text-white rounded-md hover:bg-emerald-700" title="Word Equation"><FileOutput className="w-4 h-4" /></button>
                    <button onClick={handleWordExportLatex} className="p-1.5 bg-amber-600 text-white rounded-md hover:bg-amber-700" title="Word Latex"><FileOutput className="w-4 h-4" /></button>
                </div>
                <button onClick={handleExport} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg relative" title="Save"><Save className="w-5 h-5"/><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-0.5">
                    <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md ${viewMode === 'list' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-4 h-4"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-1.5 rounded-md ${viewMode === 'slide' ? 'bg-white shadow text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-4 h-4"/></button>
                </div>
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-2 rounded-lg relative ${showAnswersGlobal ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400'}`} title="Show Answers"><Eye className="w-5 h-5" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-3 py-1.5 bg-emerald-600 text-white font-bold rounded-lg text-xs hover:bg-emerald-700">NỘP</button>}
                <button onClick={toggleFullScreen} className="p-2 rounded-lg hover:bg-slate-100" title="Fullscreen">{isFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-4 md:p-8 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-20 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-12 py-6 rounded-[3rem] font-black text-6xl border-8 shadow-2xl backdrop-blur-3xl ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/90 dark:bg-slate-800/90 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}

            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-2 p-4 bg-white/30 backdrop-blur shadow-lg rounded-full text-indigo-600 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronLeft className="w-8 h-8"/></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-2 p-4 bg-white/30 backdrop-blur shadow-lg rounded-full text-indigo-600 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
                </div>
            )}
        </main>

        {/* Compact Bottom Toolbar */}
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 z-[100] border border-white/10 shadow-xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-2 text-slate-400 hover:text-white relative"><LayoutGrid className="w-5 h-5"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-2 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`}><PenTool className="w-5 h-5"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-2 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`}><Dices className="w-5 h-5"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-6 bg-white/20"></div>
            <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-6 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-2 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-5 h-5"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-4" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-2xl w-full max-w-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-6 uppercase dark:text-white">Hẹn giờ</h3>
                    <div className="grid grid-cols-3 gap-3 mb-6">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setInitialTimerValue(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-4 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-2xl font-black text-xl">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setInitialTimerValue(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase">Dừng</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] max-w-lg w-full text-center shadow-2xl border-t-8 border-indigo-600">
                    <Trophy className="w-24 h-24 text-yellow-500 mx-auto mb-6 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-2xl text-slate-500 font-black uppercase mb-10">Xuất sắc, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl hover:bg-indigo-700 transition-all uppercase">XEM BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, Palette, Star, MonitorPlay, Timer as TimerIcon, BookOpen, School, Save } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';

interface StudyGuidePreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
}

const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc', 
    bg: 'bg-teal-50 dark:bg-slate-900', 
    primary: 'text-teal-700 dark:text-teal-400', 
    border: 'border-teal-500',
    highlight: 'text-teal-600 dark:text-teal-300'
  },
  blue: { 
    name: 'Xanh Dương', 
    bg: 'bg-blue-50 dark:bg-slate-900', 
    primary: 'text-blue-700 dark:text-blue-400', 
    border: 'border-blue-500',
    highlight: 'text-blue-600 dark:text-blue-300'
  },
  violet: { 
    name: 'Tím', 
    bg: 'bg-violet-50 dark:bg-slate-900', 
    primary: 'text-violet-700 dark:text-violet-400', 
    border: 'border-violet-500',
    highlight: 'text-violet-600 dark:text-violet-300'
  }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideStep, setSlideStep] = useState<1 | 2>(1);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>(role === 'teacher' ? 'slide' : 'doc');
  const [showExampleSolution, setShowExampleSolution] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 200%
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('teal');
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showNav, setShowNav] = useState(false);
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const slides = data.sections;

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();

      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();

      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') handleNextAction();
        if (e.key === 'ArrowLeft') handlePrevAction();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentSlide, slideStep, slides.length]);

  useEffect(() => { setShowExampleSolution(false); }, [currentSlide, slideStep]);

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => setTimer(prev => (prev !== null && prev > 0 ? prev - 1 : 0)), 1000);
    } else if (timer === 0) {
      setIsTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer]);

  const handleNextAction = () => {
    if (slideStep === 1 && slides[currentSlide].examples?.length) setSlideStep(2);
    else if (currentSlide < slides.length - 1) { 
        setCurrentSlide(v => v + 1); 
        setSlideStep(1); 
    }
  };

  const handlePrevAction = () => {
    if (slideStep === 2) setSlideStep(1);
    else if (currentSlide > 0) { 
        setCurrentSlide(v => v - 1); 
        setSlideStep(slides[currentSlide - 1].examples?.length ? 2 : 1); 
    }
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleExport = () => {
    const exportData = { type: 'theory', config: config, data: data, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Lecture_${data.topic.replace(/\s+/g, '_')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const ShortcutLabel = ({ children }: { children: React.ReactNode }) => (
    <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
