  const isSidePanelOpen = showBlackboard && blackboardMode === 'side';

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        {/* Compact Header */}
        <header className="bg-white/95 dark:bg-slate-800/95 backdrop-blur-md border-b p-4 h-12 flex justify-between items-center px-4 no-print sticky top-0 z-50">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-2 hover:bg-slate-100 rounded-lg"><RotateCcw className="w-5 h-5 text-slate-500"/></button>
                <h1 className="text-sm font-bold truncate max-w-[200px] uppercase dark:text-white">{data.topic}</h1>
            </div>
            <div className="flex items-center gap-2">
