                    </div>
                    <div className="h-full w-24 flex items-center justify-end pointer-events-auto group">
                        <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="mr-2 p-3 bg-white/30 backdrop-blur shadow-lg rounded-full text-indigo-600 opacity-0 group-hover:opacity-100 transition-all disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
                    </div>
