        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] w-full max-w-3xl shadow-2xl max-h-[80vh] overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6">
