import React, { useRef, useState, useEffect, useLayoutEffect } from 'react';
import { X, Eraser, Undo, Trash2, Minus, Circle, PenTool, Type, ChevronDown, ChevronUp, Grid3X3, Orbit, Square, Triangle, ChevronRight, ChevronLeft, PanelRight, PanelBottom, Image as ImageIcon } from 'lucide-react';

interface BlackboardProps {
  onClose: () => void;
  mode: 'bottom' | 'side';
  onModeChange: (mode: 'bottom' | 'side') => void;
}

type ToolType = 'pen' | 'eraser' | 'line' | 'dashed-line' | 'circle' | 'ellipse' | 'rectangle' | 'triangle' | 'text';
type ColorType = '#ffffff' | '#facc15' | '#f43f5e' | '#4ade80' | '#60a5fa';

const Blackboard: React.FC<BlackboardProps> = ({ onClose, mode, onModeChange }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const isDrawingRef = useRef(false);
  const startPosRef = useRef<{ x: number; y: number } | null>(null);
  const snapshotRef = useRef<ImageData | null>(null);

  const [isCollapsed, setIsCollapsed] = useState(false);
  const [tool, setTool] = useState<ToolType>('pen');
  const [color, setColor] = useState<ColorType>('#ffffff');
  const [history, setHistory] = useState<ImageData[]>([]);
  const [isGridMode, setIsGridMode] = useState(false);
  const [cursorCoords, setCursorCoords] = useState<{mathX: number, mathY: number} | null>(null);
  const [textInput, setTextInput] = useState<{ x: number; y: number; text: string } | null>(null);

  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number, grid: boolean) => {
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, width, height);

    if (grid) {
      const centerX = Math.floor(width / 2);
      const centerY = Math.floor(height / 2);
      const gridSize = 40;

      ctx.save();
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let x = centerX; x < width; x += gridSize) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
      for (let x = centerX; x > 0; x -= gridSize) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
      for (let y = centerY; y < height; y += gridSize) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
      for (let y = centerY; y > 0; y -= gridSize) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
      ctx.stroke();

      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, centerY); ctx.lineTo(width, centerY);
      ctx.lineTo(width - 10, centerY - 5); ctx.moveTo(width, centerY); ctx.lineTo(width - 10, centerY + 5);
      ctx.moveTo(centerX, height); ctx.lineTo(centerX, 0);
      ctx.lineTo(centerX - 5, 10); ctx.moveTo(centerX, 0); ctx.lineTo(centerX + 5, 10);
      ctx.stroke();

      ctx.fillStyle = '#94a3b8';
      ctx.font = '16px sans-serif';
      ctx.fillText('x', width - 20, centerY - 10);
      ctx.fillText('y', centerX + 10, 20);
      ctx.fillText('O', centerX - 20, centerY + 20);
      ctx.restore();
    }
  };

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    const ctx = canvas.getContext('2d');
    const resizeCanvas = () => {
      if (!canvas || !ctx || !container) return;
      const width = container.clientWidth;
      const height = container.clientHeight;
      if (canvas.width === width && canvas.height === height) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvas.width;
      tempCanvas.height = canvas.height;
      const tempCtx = tempCanvas.getContext('2d');
      if (tempCtx) tempCtx.drawImage(canvas, 0, 0);
      canvas.width = width;
      canvas.height = height;
      drawBackground(ctx, width, height, isGridMode);
      if (tempCanvas.width > 0) ctx.drawImage(tempCanvas, 0, 0);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
    };
    resizeCanvas();
    if (ctx) {
       const data = ctx.getImageData(0,0,1,1).data;
       if (data[3] === 0) drawBackground(ctx, canvas.width, canvas.height, isGridMode);
    }
    window.addEventListener('resize', resizeCanvas);
    return () => window.removeEventListener('resize', resizeCanvas);
  }, [isGridMode, mode, isCollapsed]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
       ctx.strokeStyle = tool === 'eraser' ? '#1e293b' : color;
       ctx.lineWidth = tool === 'eraser' ? 30 : 3;
       ctx.lineCap = 'round';
       ctx.lineJoin = 'round';
       ctx.setLineDash(tool === 'dashed-line' ? [10, 10] : []);
    }
  }, [tool, color]);

  useEffect(() => { if (textInput && inputRef.current) inputRef.current.focus(); }, [textInput]);

  const saveToHistory = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setHistory((prev) => [...prev, imageData].slice(-20));
    }
  };

  const undo = () => {
    if (history.length === 0) return;
    const newHistory = [...history];
    const previousState = newHistory.pop();
    setHistory(newHistory);
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx && previousState) ctx.putImageData(previousState, 0, 0);
    else if (canvas && ctx && newHistory.length === 0) drawBackground(ctx, canvas.width, canvas.height, isGridMode);
  };

  const clearBoard = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      saveToHistory();
      drawBackground(ctx, canvas.width, canvas.height, isGridMode);
      setTextInput(null);
    }
  };

  const toggleGrid = () => {
    const newMode = !isGridMode;
    setIsGridMode(newMode);
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
       saveToHistory();
       drawBackground(ctx, canvas.width, canvas.height, newMode);
    }
  };

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }
    const rect = canvas.getBoundingClientRect();
    return { x: clientX - rect.left, y: clientY - rect.top };
  };

  const handleTextCommit = () => {
    if (!textInput || !textInput.text.trim()) { setTextInput(null); return; }
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
        saveToHistory();
        ctx.save();
        ctx.font = 'bold 24px sans-serif';
        ctx.fillStyle = color;
        ctx.textBaseline = 'top'; 
        ctx.fillText(textInput.text, textInput.x, textInput.y);
        ctx.restore();
    }
    setTextInput(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext('2d');
            if (canvas && ctx) {
                saveToHistory();
                const canvasWidth = canvas.width;
                const scale = canvasWidth / img.width;
                const drawHeight = img.height * scale;
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, canvasWidth, drawHeight);
            }
        };
        img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (isCollapsed) return;
    const { x, y } = getCoordinates(e);
    if (tool === 'text') {
        if (textInput) handleTextCommit();
        else setTextInput({ x, y, text: '' });
        return;
    }
    if (textInput) { handleTextCommit(); return; }
    isDrawingRef.current = true;
    startPosRef.current = { x, y };
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      snapshotRef.current = ctx.getImageData(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.strokeStyle = tool === 'eraser' ? '#1e293b' : color;
      ctx.lineWidth = tool === 'eraser' ? 30 : 3;
    }
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    const { x, y } = getCoordinates(e);
    if (isGridMode && canvasRef.current) {
        const width = canvasRef.current.width;
        const height = canvasRef.current.height;
        const centerX = Math.floor(width / 2);
        const centerY = Math.floor(height / 2);
        setCursorCoords({ mathX: Math.round((x - centerX) / 40 * 10) / 10, mathY: Math.round(-(y - centerY) / 40 * 10) / 10 });
    } else { setCursorCoords(null); }
    if (!isDrawingRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      if (tool === 'pen' || tool === 'eraser') {
        ctx.lineTo(x, y);
        ctx.stroke();
      } else {
        const snapshot = snapshotRef.current;
        const startPos = startPosRef.current;
        if (snapshot && startPos) {
          ctx.putImageData(snapshot, 0, 0);
          ctx.beginPath();
          ctx.setLineDash([]);
          if (tool === 'line' || tool === 'dashed-line') {
             if (tool === 'dashed-line') ctx.setLineDash([10, 10]);
             ctx.moveTo(startPos.x, startPos.y); ctx.lineTo(x, y);
          } else if (tool === 'circle') {
             ctx.arc(startPos.x, startPos.y, Math.sqrt(Math.pow(x - startPos.x, 2) + Math.pow(y - startPos.y, 2)), 0, 2 * Math.PI);
          } else if (tool === 'ellipse') {
             ctx.ellipse(startPos.x, startPos.y, Math.abs(x - startPos.x), Math.abs(y - startPos.y), 0, 0, 2 * Math.PI);
          } else if (tool === 'rectangle') {
             ctx.rect(startPos.x, startPos.y, x - startPos.x, y - startPos.y);
          } else if (tool === 'triangle') {
             ctx.moveTo(startPos.x + (x - startPos.x) / 2, startPos.y); ctx.lineTo(startPos.x, y); ctx.lineTo(x, y); ctx.closePath();
          }
          ctx.stroke();
        }
      }
    }
  };

  const stopDrawing = () => { if (isDrawingRef.current) { isDrawingRef.current = false; saveToHistory(); } };

  const containerProps = mode === 'side' ? {
        className: `fixed top-0 right-0 bottom-0 z-[100] bg-slate-900 border-l-4 border-slate-700 shadow-2xl touch-none transition-transform duration-300 ease-in-out ${isCollapsed ? 'translate-x-[calc(100%-30px)]' : 'translate-x-0'}`,
        style: { width: '50vw' }
      } : {
        className: `fixed bottom-0 left-0 right-0 z-[100] bg-slate-900 border-t-4 border-slate-700 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] touch-none transition-transform duration-300 ease-in-out ${isCollapsed ? 'translate-y-[calc(100%-30px)]' : 'translate-y-0'}`,
        style: { height: '70vh' }
      };

  return (
    <div ref={containerRef} className={containerProps.className} style={containerProps.style}>
      {/* Tiny Grab Handle */}
      {mode === 'bottom' ? (
        <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-slate-800 text-white flex items-center gap-1 px-3 py-1 rounded-t-lg border-t border-x border-slate-600 cursor-pointer" onClick={() => setIsCollapsed(!isCollapsed)}>
            <span className="text-[10px] font-bold uppercase">Bảng</span>
            {isCollapsed ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
        </div>
      ) : (
         <div className="absolute top-1/2 -left-6 -translate-y-1/2 bg-slate-800 text-white flex flex-col items-center gap-1 px-1 py-3 rounded-l-lg border-l border-y border-slate-600 cursor-pointer" onClick={() => setIsCollapsed(!isCollapsed)}>
            {isCollapsed ? <ChevronLeft className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
            <span className="text-[10px] font-bold uppercase [writing-mode:vertical-rl] rotate-180">Bảng</span>
        </div>
      )}

      {isGridMode && cursorCoords && !isCollapsed && <div className="absolute top-2 left-2 bg-slate-900/80 text-indigo-300 px-2 py-1 rounded border border-slate-700 text-xs font-mono pointer-events-none">({cursorCoords.mathX}; {cursorCoords.mathY})</div>}
      <input ref={imageInputRef} type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
      <canvas ref={canvasRef} onMouseDown={startDrawing} onMouseMove={handleMouseMove} onMouseUp={stopDrawing} onMouseLeave={stopDrawing} onTouchStart={startDrawing} onTouchMove={handleMouseMove} onTouchEnd={stopDrawing} className="cursor-crosshair block w-full h-full" />
      {textInput && !isCollapsed && <input ref={inputRef} type="text" value={textInput.text} onChange={(e) => setTextInput({ ...textInput, text: e.target.value })} onBlur={handleTextCommit} onKeyDown={(e) => { if (e.key === 'Enter') handleTextCommit(); }} autoFocus className="absolute bg-transparent border border-dashed border-white/50 outline-none p-0 m-0 z-[110]" style={{ left: textInput.x, top: textInput.y, color: color, font: 'bold 24px sans-serif' }} />}

      {/* Tiny Toolbar */}
      {!isCollapsed && (
        <div className="absolute right-2 top-1/2 -translate-y-1/2 bg-slate-900/90 backdrop-blur-xl border border-white/10 p-1 rounded-lg shadow-xl flex flex-col items-center gap-1 z-[120]">
          <button onClick={() => onModeChange(mode === 'bottom' ? 'side' : 'bottom')} className="p-1 rounded hover:bg-white/10 text-yellow-400" title="Chuyển chế độ"><PanelBottom className="w-4 h-4" /></button>
          <div className="h-px w-full bg-white/20"></div>
          {['#ffffff', '#facc15', '#f43f5e', '#4ade80', '#60a5fa'].map((c) => (
              <button key={c} onClick={() => { setColor(c as ColorType); if (tool === 'eraser') setTool('pen'); }} className={`w-4 h-4 rounded-full border-2 ${color === c && tool !== 'eraser' ? 'border-white' : 'border-transparent'}`} style={{ backgroundColor: c }} />
          ))}
          <div className="h-px w-full bg-white/20"></div>
          {[
            { t: 'pen', i: PenTool }, { t: 'eraser', i: Eraser }, { t: 'text', i: Type }, 
            { t: 'line', i: Minus }, { t: 'circle', i: Circle }, { t: 'rectangle', i: Square }
          ].map((item) => (
             <button key={item.t} onClick={() => setTool(item.t as any)} className={`p-1 rounded ${tool === item.t ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'}`}><item.i className="w-4 h-4" /></button>
          ))}
          <button onClick={() => imageInputRef.current?.click()} className="p-1 text-slate-400 hover:text-white"><ImageIcon className="w-4 h-4" /></button>
          <div className="h-px w-full bg-white/20"></div>
          <button onClick={toggleGrid} className={`p-1 rounded ${isGridMode ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}><Grid3X3 className="w-4 h-4" /></button>
          <button onClick={undo} className="p-1 text-slate-400 hover:text-white"><Undo className="w-4 h-4" /></button>
          <button onClick={clearBoard} className="p-1 text-red-400 hover:text-white"><Trash2 className="w-4 h-4" /></button>
          <button onClick={onClose} className="p-1 mt-1 text-slate-500 hover:text-red-500"><X className="w-4 h-4" /></button>
        </div>
      )}
    </div>
  );
};

