                </button>
            </div>
          </div>
        )}

        {/* --- 3. CONFIG FORM --- */}
        {step === 'config' && selectedMode && (
          <div className="max-w-5xl mx-auto px-4 py-12 animate-fade-in">
             <div className="mb-10 flex items-center gap-6">
