                <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-10 max-h-[70vh] overflow-y-auto custom-scrollbar">
                    <section className="space-y-5">
                        <h4 className="font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest text-xs flex items-center gap-2"><Info className="w-4 h-4"/> Trình Chiếu</h4>
                        <div className="space-y-4">
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Đáp án</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">A</kbd></div>
