                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Quay số</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">R</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Hẹn giờ</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">T</kbd></div>
                        </div>
                    </section>
                    <section className="space-y-5">
                        <h4 className="font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest text-xs flex items-center gap-2"><Info className="w-4 h-4"/> Thao Tác</h4>
                        <div className="space-y-4">
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Toàn màn hình</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">F</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Lưu dự án</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">S</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Phóng to</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">+</kbd></div>
                            <div className="flex justify-between items-center"><span className="text-slate-600 dark:text-slate-300 font-bold text-sm">Thu nhỏ</span><kbd className="px-3 py-1 bg-slate-100 dark:bg-slate-700 rounded-lg border-2 border-slate-300 dark:border-slate-500 font-black text-xs">-</kbd></div>
