                ) : (
                    <div className={`h-full w-full flex flex-col items-start justify-start p-8 md:p-12 overflow-y-auto custom-scrollbar transition-all duration-300 ease-out ${theme.bg}`} style={{ fontSize: `${zoomLevel * 100}%` }}>
                        <div className={`w-full mb-6 pb-2 border-b-4 ${theme.border} flex justify-between items-end`}>
                            <h2 className={`text-[1.5em] font-black ${theme.primary} uppercase leading-none`}>{slides[currentSlide].title}</h2>
                            <span className={`text-[0.5em] font-bold ${theme.primary} opacity-40 uppercase mb-1`}>{currentSlide + 1}/{slides.length}</span>
                        </div>

                        {slideStep === 1 ? (
                            <div className="text-[1.1em] space-y-4 w-full animate-fade-in font-bold whitespace-pre-wrap leading-relaxed dark:text-zinc-100">
                                <MathRenderer content={slides[currentSlide].content} highlightClass={theme.highlight} />
                            </div>
                        ) : (
                            <div className="w-full bg-white dark:bg-zinc-900 p-8 rounded-[3rem] border-4 border-indigo-200 dark:border-indigo-900 shadow-xl animate-fade-in-up">
                                <h3 className={`text-[1em] font-black mb-4 flex items-center gap-3 ${theme.primary}`}><Star className="w-8 h-8 fill-current" /> Ví dụ</h3>
                                <div className="text-[1.1em] mb-6 font-extrabold text-slate-800 dark:text-slate-100"><MathRenderer content={slides[currentSlide].examples[0].problem}/></div>
                                {!showExampleSolution ? (
                                    <button onClick={() => setShowExampleSolution(true)} className="px-8 py-4 bg-indigo-600 text-white font-black text-[0.8em] rounded-2xl shadow-lg hover:scale-105 transition-all uppercase">Xem Lời giải</button>
                                ) : (
                                    <div className="w-full p-6 bg-emerald-50 dark:bg-emerald-900/30 rounded-[2rem] border-l-8 border-emerald-500 animate-fade-in text-[1em] font-bold dark:text-emerald-100">
                                        <MathRenderer content={slides[currentSlide].examples[0].solution} />
                                    </div>
                                )}
                            </div>
                        )}

                        {viewMode === 'slide' && timer !== null && (
                          <div className="fixed bottom-20 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                            <div className={`px-12 py-6 rounded-[3rem] font-black text-6xl border-8 shadow-xl backdrop-blur-3xl ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/95 dark:bg-zinc-800/95 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                              {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                            </div>
                          </div>
                        )}
                    </div>
                )}
            </div>

            {isSidePanelOpen && viewMode === 'slide' && (
                <div className="w-1/2 h-full bg-slate-800 border-l-4 border-slate-700 z-40 relative">
                    <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
                </div>
            )}

            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <div className="h-full w-24 flex items-center justify-start pointer-events-auto group">
                        <button onClick={handlePrevAction} disabled={currentSlide === 0 && slideStep === 1} className="ml-2 p-3 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 opacity-0 group-hover:opacity-100 transition-all disabled:hidden"><ChevronLeft className="w-8 h-8"/></button>
                    </div>
                    <div className="h-full w-24 flex items-center justify-end pointer-events-auto group">
                        <button onClick={handleNextAction} disabled={currentSlide === slides.length - 1 && slideStep === (slides[currentSlide].examples?.length ? 2 : 1)} className="mr-2 p-3 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 opacity-0 group-hover:opacity-100 transition-all disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
                    </div>
                </div>
            )}
        </main>

        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 z-[100] border border-white/10 shadow-xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-2 text-slate-400 hover:text-white relative"><LayoutGrid className="w-5 h-5"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-2 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`}><PenTool className="w-5 h-5"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-2 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`}><Dices className="w-5 h-5"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-6 bg-white/20"></div>
            <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-6 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-2 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-5 h-5"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-4" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-2xl w-full max-w-sm text-center">
                    <h3 className="text-2xl font-black mb-6 uppercase dark:text-white">Bấm giờ</h3>
                    <div className="grid grid-cols-3 gap-3 mb-4">
                        {[1, 2, 3, 4, 5].map(m => (<button key={m} onClick={() => { setTimer(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-4 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-2xl font-black text-xl">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-3 bg-red-50 text-red-600 rounded-xl font-bold uppercase text-sm">Dừng</button>
                    </div>
                </div>
            </div>
        )}

        {showThemeMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 flex items-center justify-center p-4" onClick={() => setShowThemeMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-2xl w-full max-w-md text-center">
                    <h3 className="text-xl font-black mb-6 dark:text-white uppercase">Màu Slide</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(Object.keys(SLIDE_THEMES) as ThemeKey[]).map((key) => (
                            <button key={key} onClick={() => { setActiveTheme(key); setShowThemeMenu(false); }} className={`p-3 rounded-2xl border-4 transition-all flex flex-col items-center gap-2 ${activeTheme === key ? 'border-indigo-600 scale-105' : 'border-slate-100'}`}>
                                <div className={`w-8 h-8 rounded-full ${SLIDE_THEMES[key].bg} border border-slate-300`}></div>
                                <span className="font-bold text-[10px] uppercase">{SLIDE_THEMES[key].name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showNav && (
            <div className="fixed inset-0 z-[110] bg-black/50 flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowNav(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] w-full max-w-3xl shadow-2xl max-h-[80vh] overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-black uppercase text-slate-800 dark:text-white">Mục lục ({slides.length})</h3>
                        <button onClick={() => setShowNav(false)} className="p-2 bg-slate-100 rounded-full"><X className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3 overflow-y-auto custom-scrollbar p-1">
                        {slides.map((s, i) => (
                            <button key={i} onClick={() => { setCurrentSlide(i); setSlideStep(1); setShowNav(false); }} className={`p-4 rounded-2xl text-left border-2 transition-all ${currentSlide === i ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 border-transparent hover:border-indigo-200'}`}>
                                <span className="block text-[10px] font-black opacity-60 uppercase">TRANG {i+1}</span>
                                <span className="font-bold text-sm line-clamp-2 uppercase">{s.title}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/20', border: 'border-blue-300 dark:border-blue-800', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/20', border: 'border-emerald-300 dark:border-emerald-800', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/20', border: 'border-amber-300 dark:border-amber-800', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/20', border: 'border-rose-300 dark:border-rose-800', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

const ShortcutLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
);

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 200%
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [initialTimerValue, setInitialTimerValue] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Khởi tạo AudioContext một lần
  const initAudio = () => {
    if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
        audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  // Hàm phát tiếng tick-tack vui nhộn cho đồng hồ
  const playTick = (freq = 800) => {
    try {
      const ctx = initAudio();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(freq * 0.5, ctx.currentTime + 0.1);

      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);

      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio error", e);
    }
  };

  // Hàm phát âm thanh phản hồi Đúng/Sai vui nhộn
  const playFeedback = (isCorrect: boolean) => {
    try {
        const ctx = initAudio();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        const now = ctx.currentTime;

        if (isCorrect) {
            // Âm thanh "Ding" vui nhộn (Sine wave, cao độ tăng)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(500, now);
            osc.frequency.exponentialRampToValueAtTime(1000, now + 0.1);
            osc.frequency.exponentialRampToValueAtTime(1500, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0.3, now + 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);

            osc.start(now);
            osc.stop(now + 0.6);
        } else {
            // Âm thanh "Buzz" (Sawtooth, cao độ giảm/trầm)
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(150, now);
            osc.frequency.linearRampToValueAtTime(100, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);

            osc.start(now);
            osc.stop(now + 0.3);
        }
    } catch (e) {
        console.warn("Audio error", e);
    }
  };

  // Helper xác định index đáp án đúng
  const getCorrectIndex = (q: Question) => {
    const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
    const index = ['A', 'B', 'C', 'D'].indexOf(correctLetter);
    return index !== -1 ? index : 0; // Mặc định 0 nếu không parse được
  };

  // Logic đếm ngược đồng hồ
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) {
            setIsTimerRunning(false);
            return 0;
          }
          const next = prev - 1;
          // Hiệu ứng âm thanh 5 giây cuối
          if (next <= 5 && next > 0) {
            playTick(next % 2 === 0 ? 1200 : 900);
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  // Ẩn đồng hồ khi học sinh đã chọn xong đáp án
  useEffect(() => {
    if (userAnswers[currentSlide] !== undefined && isTimerRunning) {
      setTimer(null);
      setIsTimerRunning(false);
    }
  }, [userAnswers[currentSlide]]);

  // Tự động hiện lại đồng hồ khi sang câu mới nếu trước đó có cài đặt timer
  useEffect(() => {
    if (initialTimerValue !== null && viewMode === 'slide' && !isSubmitted) {
      const hasAnswered = userAnswers[currentSlide] !== undefined;
      if (!hasAnswered) {
        setTimer(initialTimerValue);
        setIsTimerRunning(true);
      } else {
        setTimer(null);
        setIsTimerRunning(false);
      }
    }
  }, [currentSlide, viewMode]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      // Trong chế độ slide, tắt phím tắt A để tránh lộ đáp án, chỉ dùng click
      if (key === 'a' && role === 'teacher' && viewMode !== 'slide') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    // Style zoom luôn ở 200% (zoomLevel mặc định 2.0)
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    // Tìm index đáp án đúng
    const correctIndex = getCorrectIndex(q);

    return (
      <div className={`flex flex-col bg-white dark:bg-zinc-950 ${isSlide ? 'pt-2 pb-16 px-6 md:px-12 items-start justify-start w-full overflow-y-auto' : 'p-6 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-4 no-print border-b border-slate-100 dark:border-zinc-800 pb-2">
                <div className="flex items-center gap-2">
                  <span className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-md flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-slate-100 dark:bg-zinc-900 text-slate-500 whitespace-nowrap">{q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-1.5 bg-slate-50 dark:bg-zinc-900 rounded-lg hover:text-indigo-600 transition-colors relative" title="Đọc (V)"><Volume2 className="w-5 h-5" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`p-1.5 rounded-lg transition-all relative ${isHintVisible ? 'bg-amber-100 text-amber-600' : 'bg-slate-50 dark:bg-zinc-900 text-slate-400 dark:text-zinc-500'}`} title="Gợi ý (H)">
                      <Lightbulb className="w-5 h-5" />
                      {isSlide && <ShortcutLabel>H</ShortcutLabel>}
                  </button>
                )}
            </div>

            <div className="text-[1em] font-medium text-slate-900 dark:text-zinc-100 mb-6 w-full leading-normal">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-6 p-4 bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-300 rounded-r-xl">
                <h5 className="text-amber-700 font-bold text-[0.6em] uppercase mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4" /> Gợi ý:</h5>
                <ul className="space-y-2 pl-4 list-disc">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="text-amber-900 dark:text-amber-100 text-[0.6em]"><MathRenderer content={hint} inline /></li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-4 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => {
                    const isSelected = userAns === oi;
                    let buttonClass = `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`;
                    let labelClass = `${OPTION_THEMES[oi].labelBg}`;

                    // Logic màu sắc tương tác:
                    // Nếu đã chọn:
                    // - Đúng: Xanh (Emerald)
                    // - Sai: Đỏ (Red)
                    if (isSelected) {
                        const isCorrect = oi === correctIndex;
                        if (isCorrect) {
                            buttonClass = 'bg-emerald-600 border-emerald-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-emerald-600';
                        } else {
                            buttonClass = 'bg-red-600 border-red-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-red-600';
                        }
                    }

                    return (
                        <button 
                            key={oi} 
                            onClick={() => {
                                if (!isSubmitted) {
                                    setUserAnswers(prev => ({ ...prev, [idx]: oi }));
                                    // Phát âm thanh phản hồi ngay lập tức
                                    playFeedback(oi === correctIndex);
                                }
                            }} 
                            className={`group flex items-start gap-4 p-4 rounded-2xl border-2 transition-all text-left ${buttonClass}`}
                        >
                            <span className={`w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center font-bold text-[0.6em] ${labelClass}`}>{['A','B','C','D'][oi]}</span>
                            <div className={`text-[0.8em] pt-0.5 ${isSelected ? 'text-white' : 'dark:text-zinc-100'}`}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                        </button>
                    );
                })}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-4 bg-slate-50 dark:bg-zinc-900 rounded-2xl border border-slate-200 dark:border-zinc-700">
                        <div className="text-[0.7em] font-medium mb-3 flex gap-2 dark:text-zinc-200"><span className="text-indigo-600 font-bold">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-2">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-2 rounded-xl font-bold text-[0.5em] border transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white dark:bg-zinc-800 text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-2 rounded-xl font-bold text-[0.5em] border transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white' : 'bg-white dark:bg-zinc-800 text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-6 p-6 bg-emerald-50 dark:bg-emerald-900/20 rounded-3xl border border-emerald-200 w-full relative animate-fade-in">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-2 right-2 p-1 hover:bg-emerald-100 rounded-full no-print"><X className="w-5 h-5 text-emerald-600" /></button>
                    <h4 className="text-[0.7em] font-bold text-emerald-700 dark:text-emerald-400 mb-2 flex items-center gap-2"><CheckCircle className="w-6 h-6" /> Đáp án: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.6em] font-medium leading-relaxed border-t border-emerald-100 pt-2 dark:text-emerald-100"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-6 w-full py-3 bg-slate-100 dark:bg-zinc-900 rounded-xl border border-dashed border-slate-300 dark:border-zinc-700 flex items-center justify-center gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all text-slate-400 hover:text-indigo-600 no-print">
                  <Eye className="w-5 h-5" />
                  <span className="text-[0.6em] font-bold uppercase">Xem Lời giải (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-20 h-20 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h2>
            <p className="text-xl text-slate-500 font-medium mb-10 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="Nhập tên..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-bold mb-8 border-2 border-transparent focus:border-indigo-600 outline-none" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        {/* Compact Header */}
        <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 sticky top-0 z-50 px-2 h-10 flex justify-between items-center no-print shadow-sm">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg" title="Home"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
                <h1 className="text-xs font-bold truncate max-w-[150px] dark:text-zinc-200 uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-1">
                <div className="flex gap-1 mr-2">
                    <button onClick={handleWordExportEquation} className="p-1 bg-emerald-600 text-white rounded-md hover:bg-emerald-700" title="Word Equation"><FileOutput className="w-3.5 h-3.5" /></button>
                    <button onClick={handleWordExportLatex} className="p-1 bg-amber-600 text-white rounded-md hover:bg-amber-700" title="Word Latex"><FileOutput className="w-3.5 h-3.5" /></button>
                </div>
                <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative" title="Save"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex bg-slate-100 dark:bg-zinc-900 rounded-lg p-0.5">
                    <button onClick={() => setViewMode('list')} className={`p-1 rounded-md ${viewMode === 'list' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-3.5 h-3.5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-1 rounded-md ${viewMode === 'slide' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-3.5 h-3.5"/></button>
                </div>
                {/* Ẩn nút Show Answer ở chế độ Slide để tránh lộ bài */}
                {role === 'teacher' && viewMode !== 'slide' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-1.5 rounded-lg relative ${showAnswersGlobal ? 'text-indigo-600 bg-indigo-50 dark:bg-zinc-800' : 'text-slate-400'}`} title="Show Answers"><Eye className="w-4 h-4" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-2.5 py-1 bg-emerald-600 text-white font-bold rounded-lg text-[10px] hover:bg-emerald-700">NỘP</button>}
                <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 text-slate-600 dark:text-slate-300" title="Fullscreen">{isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-4 md:p-8 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-20 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-12 py-6 rounded-[3rem] font-black text-6xl border-8 shadow-2xl backdrop-blur-3xl ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/90 dark:bg-zinc-800/90 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}

            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-2 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronLeft className="w-8 h-8"/></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-2 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
                </div>
            )}
        </main>

        {/* Compact Bottom Toolbar */}
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 z-[100] border border-white/10 shadow-xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-2 text-slate-400 hover:text-white relative"><LayoutGrid className="w-5 h-5"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-2 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`}><PenTool className="w-5 h-5"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-2 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`}><Dices className="w-5 h-5"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-6 bg-white/20"></div>
            <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-6 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-2 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-5 h-5"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-4" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-2xl w-full max-w-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-6 uppercase dark:text-white">Hẹn giờ</h3>
                    <div className="grid grid-cols-3 gap-3 mb-6">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setInitialTimerValue(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-4 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-2xl font-black text-xl">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setInitialTimerValue(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase">Dừng</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] max-w-lg w-full text-center shadow-2xl border-t-8 border-indigo-600">
                    <Trophy className="w-24 h-24 text-yellow-500 mx-auto mb-6 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-2xl text-slate-500 font-black uppercase mb-10">Xuất sắc, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl hover:bg-indigo-700 transition-all uppercase">XEM BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, PenTool, Dices, X, ZoomIn, ZoomOut, MonitorPlay, Timer as TimerIcon, Trophy, User, CheckCircle, ArrowLeft, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput } from 'lucide-react';
import Blackboard from './Blackboard';
import RandomPicker from './RandomPicker';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
  onReset: () => void;
  onRegenerate: () => void;
}

const OPTION_THEMES = [
  { bg: 'bg-blue-50 dark:bg-blue-900/20', border: 'border-blue-300 dark:border-blue-800', text: 'text-blue-900 dark:text-blue-100', labelBg: 'bg-blue-600 text-white' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/20', border: 'border-emerald-300 dark:border-emerald-800', text: 'text-emerald-900 dark:text-emerald-100', labelBg: 'bg-emerald-600 text-white' },
  { bg: 'bg-amber-50 dark:bg-amber-900/20', border: 'border-amber-300 dark:border-amber-800', text: 'text-amber-900 dark:text-amber-100', labelBg: 'bg-amber-600 text-white' },
  { bg: 'bg-rose-50 dark:bg-rose-900/20', border: 'border-rose-300 dark:border-rose-800', text: 'text-rose-900 dark:text-rose-100', labelBg: 'bg-rose-600 text-white' }
];

const ShortcutLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
);

export const ExamPreview: React.FC<ExamPreviewProps> = ({ role, config, data, onReset, onRegenerate }) => {
  const [questions, setQuestions] = useState<Question[]>(data.questions);
  const [showAnswersGlobal, setShowAnswersGlobal] = useState(role === 'teacher');
  const [viewMode, setViewMode] = useState<'list' | 'slide'>(role === 'teacher' ? 'slide' : 'list');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(2.0); // Mặc định 200%
  const [isStarted, setIsStarted] = useState(role === 'teacher');
  const [studentName, setStudentName] = useState('');
  const [userAnswers, setUserAnswers] = useState<Record<number, any>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showScoreModal, setShowScoreModal] = useState(false);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');
  const [showRandomPicker, setShowRandomPicker] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showNav, setShowNav] = useState(false);
  const [timer, setTimer] = useState<number | null>(null);
  const [initialTimerValue, setInitialTimerValue] = useState<number | null>(null);
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);

  const [revealedAnswers, setRevealedAnswers] = useState<Set<number>>(new Set());
  const [revealedHints, setRevealedHints] = useState<Set<number>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Khởi tạo AudioContext một lần
  const initAudio = () => {
    if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
        audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  // Hàm phát tiếng tick-tack vui nhộn cho đồng hồ
  const playTick = (freq = 800) => {
    try {
      const ctx = initAudio();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(freq * 0.5, ctx.currentTime + 0.1);

      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);

      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio error", e);
    }
  };

  // Hàm phát âm thanh phản hồi Đúng/Sai vui nhộn
  const playFeedback = (isCorrect: boolean) => {
    try {
        const ctx = initAudio();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        const now = ctx.currentTime;

        if (isCorrect) {
            // Âm thanh "Ding" vui nhộn (Sine wave, cao độ tăng)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(500, now);
            osc.frequency.exponentialRampToValueAtTime(1000, now + 0.1);
            osc.frequency.exponentialRampToValueAtTime(1500, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0.3, now + 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);

            osc.start(now);
            osc.stop(now + 0.6);
        } else {
            // Âm thanh "Buzz" (Sawtooth, cao độ giảm/trầm)
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(150, now);
            osc.frequency.linearRampToValueAtTime(100, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);

            osc.start(now);
            osc.stop(now + 0.3);
        }
    } catch (e) {
        console.warn("Audio error", e);
    }
  };

  // Helper xác định index đáp án đúng
  const getCorrectIndex = (q: Question) => {
    const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
    const index = ['A', 'B', 'C', 'D'].indexOf(correctLetter);
    return index !== -1 ? index : 0; // Mặc định 0 nếu không parse được
  };

  // Logic đếm ngược đồng hồ
  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) {
            setIsTimerRunning(false);
            return 0;
          }
          const next = prev - 1;
          // Hiệu ứng âm thanh 5 giây cuối
          if (next <= 5 && next > 0) {
            playTick(next % 2 === 0 ? 1200 : 900);
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  // Ẩn đồng hồ khi học sinh đã chọn xong đáp án
  useEffect(() => {
    if (userAnswers[currentSlide] !== undefined && isTimerRunning) {
      setTimer(null);
      setIsTimerRunning(false);
    }
  }, [userAnswers[currentSlide]]);

  // Tự động hiện lại đồng hồ khi sang câu mới nếu trước đó có cài đặt timer
  useEffect(() => {
    if (initialTimerValue !== null && viewMode === 'slide' && !isSubmitted) {
      const hasAnswered = userAnswers[currentSlide] !== undefined;
      if (!hasAnswered) {
        setTimer(initialTimerValue);
        setIsTimerRunning(true);
      } else {
        setTimer(null);
        setIsTimerRunning(false);
      }
    }
  }, [currentSlide, viewMode]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();
      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'r') setShowRandomPicker(prev => !prev);
      if (key === 't') setShowTimerMenu(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide') toggleRevealHint(currentSlide);
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(0, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 5.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    const isSidePanelOpen = showBlackboard && blackboardMode === 'side';
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    const correctIndex = getCorrectIndex(q);

    return (
      <div className={`flex flex-col bg-white dark:bg-zinc-950 ${isSlide ? 'pt-2 pb-16 px-6 md:px-12 items-start justify-start w-full overflow-y-auto' : 'p-6 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-4 no-print border-b border-slate-100 dark:border-zinc-800 pb-2">
                <div className="flex items-center gap-2">
                  <span className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-md flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-slate-100 dark:bg-zinc-900 text-slate-500 whitespace-nowrap">{q.difficulty}</span>
                  {isSlide && <button onClick={readAloud} className="p-1.5 bg-slate-50 dark:bg-zinc-900 rounded-lg hover:text-indigo-600 transition-colors relative" title="Đọc (V)"><Volume2 className="w-5 h-5" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`p-1.5 rounded-lg transition-all relative ${isHintVisible ? 'bg-amber-100 text-amber-600' : 'bg-slate-50 dark:bg-zinc-900 text-slate-400 dark:text-zinc-500'}`} title="Gợi ý (H)">
                      <Lightbulb className="w-5 h-5" />
                      {isSlide && <ShortcutLabel>H</ShortcutLabel>}
                  </button>
                )}
            </div>

            <div className="text-[1em] font-bold text-slate-900 dark:text-zinc-100 mb-6 w-full leading-normal">
                <MathRenderer content={q.content} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-6 p-4 bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-300 rounded-r-xl">
                <h5 className="text-amber-700 font-bold text-[0.6em] uppercase mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4" /> Gợi ý:</h5>
                <ul className="space-y-2 pl-4 list-disc">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="text-amber-900 dark:text-amber-100 text-[0.6em] font-semibold"><MathRenderer content={hint} inline /></li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-4 ${isSidePanelOpen && isSlide ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => {
                    const isSelected = userAns === oi;
                    let buttonClass = `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`;
                    let labelClass = `${OPTION_THEMES[oi].labelBg}`;

                    if (isSelected) {
                        const isCorrect = oi === correctIndex;
                        if (isCorrect) {
                            buttonClass = 'bg-emerald-600 border-emerald-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-emerald-600';
                        } else {
                            buttonClass = 'bg-red-600 border-red-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-red-600';
                        }
                    }

                    return (
                        <button 
                            key={oi} 
                            onClick={() => {
                                if (!isSubmitted) {
                                    setUserAnswers(prev => ({ ...prev, [idx]: oi }));
                                    playFeedback(oi === correctIndex);
                                }
                            }} 
                            className={`group flex items-start gap-4 p-4 rounded-2xl border-2 transition-all text-left ${buttonClass}`}
                        >
                            <span className={`w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center font-bold text-[0.6em] ${labelClass}`}>{['A','B','C','D'][oi]}</span>
                            <div className={`text-[0.8em] pt-0.5 font-bold ${isSelected ? 'text-white' : 'dark:text-zinc-100'}`}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline /></div>
                        </button>
                    );
                })}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-4 bg-slate-50 dark:bg-zinc-900 rounded-2xl border border-slate-200 dark:border-zinc-700">
                        <div className="text-[0.7em] font-bold mb-3 flex gap-2 dark:text-zinc-200"><span className="text-indigo-600 font-black">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline /></div>
                        <div className="flex gap-2">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-2 rounded-xl font-black text-[0.5em] border transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white dark:bg-zinc-800 text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-2 rounded-xl font-black text-[0.5em] border transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white' : 'bg-white dark:bg-zinc-800 text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-6 p-6 bg-emerald-50 dark:bg-emerald-900/20 rounded-3xl border border-emerald-200 w-full relative animate-fade-in">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-2 right-2 p-1 hover:bg-emerald-100 rounded-full no-print"><X className="w-5 h-5 text-emerald-600" /></button>
                    <h4 className="text-[0.7em] font-black text-emerald-700 dark:text-emerald-400 mb-2 flex items-center gap-2"><CheckCircle className="w-6 h-6" /> Đáp án: <MathRenderer content={q.correctAnswer} inline /></h4>
                    <div className="text-[0.6em] font-bold leading-relaxed border-t border-emerald-100 pt-2 dark:text-emerald-100"><MathRenderer content={q.solution} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-6 w-full py-3 bg-slate-100 dark:bg-zinc-900 rounded-xl border border-dashed border-slate-300 dark:border-zinc-700 flex items-center justify-center gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all text-slate-400 hover:text-indigo-600 no-print">
                  <Eye className="w-5 h-5" />
                  <span className="text-[0.6em] font-black uppercase">Xem Lời giải (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-20 h-20 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h2>
            <p className="text-xl text-slate-500 font-bold mb-10 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="Nhập tên..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-8 border-2 border-transparent focus:border-indigo-600 outline-none" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        {/* Compact Header */}
        <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 sticky top-0 z-50 px-2 h-10 flex justify-between items-center no-print shadow-sm">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg" title="Home"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
                <h1 className="text-xs font-black truncate max-w-[150px] dark:text-zinc-200 uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-1">
                <div className="flex gap-1 mr-2">
                    <button onClick={handleWordExportEquation} className="p-1 bg-emerald-600 text-white rounded-md hover:bg-emerald-700" title="Word Equation"><FileOutput className="w-3.5 h-3.5" /></button>
                    <button onClick={handleWordExportLatex} className="p-1 bg-amber-600 text-white rounded-md hover:bg-amber-700" title="Word Latex"><FileOutput className="w-3.5 h-3.5" /></button>
                </div>
                <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative" title="Save"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex bg-slate-100 dark:bg-zinc-900 rounded-lg p-0.5">
                    <button onClick={() => setViewMode('list')} className={`p-1 rounded-md ${viewMode === 'list' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-3.5 h-3.5"/></button>
                    <button onClick={() => setViewMode('slide')} className={`p-1 rounded-md ${viewMode === 'slide' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-3.5 h-3.5"/></button>
                </div>
                {/* Khôi phục nút Show Answer ở chế độ Slide, nhưng vẫn phụ thuộc vào role teacher */}
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-1.5 rounded-lg relative ${showAnswersGlobal ? 'text-indigo-600 bg-indigo-50 dark:bg-zinc-800' : 'text-slate-400'}`} title="Show Answers"><Eye className="w-4 h-4" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-2.5 py-1 bg-emerald-600 text-white font-black rounded-lg text-[10px] hover:bg-emerald-700">NỘP</button>}
                <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 text-slate-600 dark:text-slate-300" title="Fullscreen">{isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}</button>
            </div>
        </header>

        <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-4 md:p-8 max-w-5xl mx-auto w-full'}`}>
            <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>
                {viewMode === 'list' ? questions.map((q, i) => renderQuestionCard(q, i, false)) : renderQuestionCard(questions[currentSlide], currentSlide, true)}
                {viewMode === 'slide' && timer !== null && (
                  <div className="absolute bottom-20 left-1/2 -translate-x-1/2 pointer-events-none z-[60]">
                    <div className={`px-12 py-6 rounded-[3rem] font-black text-6xl border-8 shadow-2xl backdrop-blur-3xl ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/90 dark:bg-zinc-800/90 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>{Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}</div>
                  </div>
                )}
            </div>
            {showBlackboard && blackboardMode === 'side' && viewMode === 'slide' && <div className="w-1/2 h-full bg-slate-800 border-l border-indigo-100 z-40 relative"><Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} /></div>}

            {viewMode === 'slide' && (
                <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                    <button onClick={() => setCurrentSlide(s => Math.max(0, s-1))} disabled={currentSlide === 0} className="ml-2 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronLeft className="w-8 h-8"/></button>
                    <button onClick={() => setCurrentSlide(s => Math.min(questions.length-1, s+1))} disabled={currentSlide === questions.length-1} className="mr-2 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
                </div>
            )}
        </main>

        {/* Compact Bottom Toolbar */}
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 z-[100] border border-white/10 shadow-xl items-center no-print">
            <button onClick={() => setShowNav(!showNav)} className="p-2 text-slate-400 hover:text-white relative"><LayoutGrid className="w-5 h-5"/><ShortcutLabel>M</ShortcutLabel></button>
            <button onClick={() => setShowBlackboard(true)} className={`p-2 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`}><PenTool className="w-5 h-5"/><ShortcutLabel>B</ShortcutLabel></button>
            <button onClick={() => setShowRandomPicker(true)} className={`p-2 transition-colors relative ${showRandomPicker ? 'text-indigo-400' : 'text-slate-400 hover:text-indigo-400'}`}><Dices className="w-5 h-5"/><ShortcutLabel>R</ShortcutLabel></button>
            <div className="w-px h-6 bg-white/20"></div>
            <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
            <div className="w-px h-6 bg-white/20"></div>
            <button onClick={() => setShowTimerMenu(!showTimerMenu)} className={`p-2 transition-colors relative ${timer ? 'text-red-400' : 'text-slate-400 hover:text-red-400'}`}><TimerIcon className="w-5 h-5"/><ShortcutLabel>T</ShortcutLabel></button>
        </div>

        {showTimerMenu && (
            <div className="fixed inset-0 z-[120] bg-black/50 backdrop-blur flex items-center justify-center p-4" onClick={() => setShowTimerMenu(false)}>
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-2xl w-full max-w-sm text-center" onClick={e => e.stopPropagation()}>
                    <h3 className="text-2xl font-black mb-6 uppercase dark:text-white">Hẹn giờ</h3>
                    <div className="grid grid-cols-3 gap-3 mb-6">
                        {[1, 2, 3, 5, 10, 15].map(m => (<button key={m} onClick={() => { setTimer(m*60); setInitialTimerValue(m*60); setIsTimerRunning(true); setShowTimerMenu(false); }} className="py-4 bg-slate-50 dark:bg-slate-700 hover:bg-indigo-600 hover:text-white rounded-2xl font-black text-xl">{m}P</button>))}
                        <button onClick={() => { setTimer(null); setInitialTimerValue(null); setIsTimerRunning(false); setShowTimerMenu(false); }} className="col-span-3 py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase">Dừng</button>
                    </div>
                </div>
            </div>
        )}

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] max-w-lg w-full text-center shadow-2xl border-t-8 border-indigo-600">
                    <Trophy className="w-24 h-24 text-yellow-500 mx-auto mb-6 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-2xl text-slate-500 font-black uppercase mb-10">Xuất sắc, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl hover:bg-indigo-700 transition-all uppercase">XEM BÀI GIẢI</button>
                </div>
            </div>
        )}

        {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
        {showRandomPicker && <RandomPicker onClose={() => setShowRandomPicker(false)} />}
    </div>
  );
};

import React, { useEffect, useRef } from 'react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
  highlightClass?: string;
}

declare global {
  interface Window {
    MathJax: any;
  }
}

// Mảng màu sắc rực rỡ để random cho công thức toán
const MATH_COLORS = [
  'text-cyan-600 dark:text-cyan-400',
  'text-fuchsia-600 dark:text-fuchsia-400',
  'text-lime-600 dark:text-lime-400',
  'text-orange-600 dark:text-orange-400',
  'text-sky-600 dark:text-sky-400',
  'text-rose-600 dark:text-rose-400',
  'text-violet-600 dark:text-violet-400'
];

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false, highlightClass = "" }) => {
  const containerRef = useRef<HTMLElement>(null);

  // Chọn màu dựa trên độ dài nội dung để cố định màu cho mỗi công thức (tránh flicker khi re-render)
  const getColorClass = (text: string) => {
    if (highlightClass) return highlightClass;
    const index = text.length % MATH_COLORS.length;
    return MATH_COLORS[index];
  };

  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          if (window.MathJax.typesetClear) {
            window.MathJax.typesetClear([containerRef.current]);
          }
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    renderMath();
  }, [content]);

  const processContent = (text: string) => {
    if (!text) return null;

    const sanitizedText = text.replace(/\\n/g, '\n');

    // Tách phần text thường và công thức toán (trong $...$)
    // Regex này giữ lại dấu phân cách trong mảng kết quả
    const parts = sanitizedText.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        // Bold markdown
        return (
          <strong key={index} className="font-black text-indigo-700 dark:text-indigo-300">
            {part.slice(2, -2)}
          </strong>
        );
      } else if (part.startsWith('$') && part.endsWith('$')) {
        // Math formula
        const colorClass = getColorClass(part);
        return (
          <span key={index} className={`font-bold ${colorClass} mx-1`}>
            {part}
          </span>
        );
      }
      return <span key={index}>{part}</span>;
    });
  };

  const contentKey = `math-${content.length}-${content.substring(0, 10)}`;

  if (inline) {
    return (
      <span 
        key={contentKey}
        ref={containerRef as React.RefObject<HTMLSpanElement>} 
        className="math-renderer inline-block align-middle whitespace-pre-wrap tex2jax_process"
      >
        {processContent(content)}
      </span>
    );
  }

  return (
    <div 
      key={contentKey}
      ref={containerRef as React.RefObject<HTMLDivElement>} 
      className="math-renderer block my-2 whitespace-pre-wrap tex2jax_process"
    >
      {processContent(content)}
    </div>
  );
};

export default MathRenderer;

import React, { useRef, useState, useEffect, useLayoutEffect } from 'react';
import { X, Eraser, Undo, Trash2, Minus, Circle, PenTool, Type, ChevronDown, ChevronUp, Grid3X3, Orbit, Square, Triangle, ChevronRight, ChevronLeft, PanelRight, PanelBottom, Image as ImageIcon } from 'lucide-react';

interface BlackboardProps {
  onClose: () => void;
  mode: 'bottom' | 'side';
  onModeChange: (mode: 'bottom' | 'side') => void;
}

type ToolType = 'pen' | 'eraser' | 'line' | 'dashed-line' | 'circle' | 'ellipse' | 'rectangle' | 'triangle' | 'text';
type ColorType = '#ffffff' | '#facc15' | '#f43f5e' | '#4ade80' | '#60a5fa';

const Blackboard: React.FC<BlackboardProps> = ({ onClose, mode, onModeChange }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const isDrawingRef = useRef(false);
  const startPosRef = useRef<{ x: number; y: number } | null>(null);
  const snapshotRef = useRef<ImageData | null>(null);

  const [isCollapsed, setIsCollapsed] = useState(false);
  const [tool, setTool] = useState<ToolType>('pen');
  const [color, setColor] = useState<ColorType>('#ffffff');
  const [history, setHistory] = useState<ImageData[]>([]);
  const [isGridMode, setIsGridMode] = useState(false);
  const [cursorCoords, setCursorCoords] = useState<{mathX: number, mathY: number} | null>(null);
  const [textInput, setTextInput] = useState<{ x: number; y: number; text: string } | null>(null);

  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number, grid: boolean) => {
    ctx.fillStyle = '#000000'; // Màu đen
    ctx.fillRect(0, 0, width, height);

    if (grid) {
      const centerX = Math.floor(width / 2);
      const centerY = Math.floor(height / 2);
      const gridSize = 40;

      ctx.save();
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let x = centerX; x < width; x += gridSize) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
      for (let x = centerX; x > 0; x -= gridSize) { ctx.moveTo(x, 0); ctx.lineTo(x, height); }
      for (let y = centerY; y < height; y += gridSize) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
      for (let y = centerY; y > 0; y -= gridSize) { ctx.moveTo(0, y); ctx.lineTo(width, y); }
      ctx.stroke();

      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, centerY); ctx.lineTo(width, centerY);
      ctx.lineTo(width - 10, centerY - 5); ctx.moveTo(width, centerY); ctx.lineTo(width - 10, centerY + 5);
      ctx.moveTo(centerX, height); ctx.lineTo(centerX, 0);
      ctx.lineTo(centerX - 5, 10); ctx.moveTo(centerX, 0); ctx.lineTo(centerX + 5, 10);
      ctx.stroke();

      ctx.fillStyle = '#94a3b8';
      ctx.font = '16px sans-serif';
      ctx.fillText('x', width - 20, centerY - 10);
      ctx.fillText('y', centerX + 10, 20);
      ctx.fillText('O', centerX - 20, centerY + 20);
      ctx.restore();
    }
  };

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    const ctx = canvas.getContext('2d');
    const resizeCanvas = () => {
      if (!canvas || !ctx || !container) return;
      const width = container.clientWidth;
      const height = container.clientHeight;
      if (canvas.width === width && canvas.height === height) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvas.width;
      tempCanvas.height = canvas.height;
      const tempCtx = tempCanvas.getContext('2d');
      if (tempCtx) tempCtx.drawImage(canvas, 0, 0);
      canvas.width = width;
      canvas.height = height;
      drawBackground(ctx, width, height, isGridMode);
      if (tempCanvas.width > 0) ctx.drawImage(tempCanvas, 0, 0);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
    };
    resizeCanvas();
    if (ctx) {
       const data = ctx.getImageData(0,0,1,1).data;
       if (data[3] === 0) drawBackground(ctx, canvas.width, canvas.height, isGridMode);
    }
    window.addEventListener('resize', resizeCanvas);
    return () => window.removeEventListener('resize', resizeCanvas);
  }, [isGridMode, mode, isCollapsed]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
       ctx.strokeStyle = tool === 'eraser' ? '#000000' : color; // Màu tẩy là đen
       ctx.lineWidth = tool === 'eraser' ? 30 : 3;
       ctx.lineCap = 'round';
       ctx.lineJoin = 'round';
       ctx.setLineDash(tool === 'dashed-line' ? [10, 10] : []);
    }
  }, [tool, color]);

  useEffect(() => { if (textInput && inputRef.current) inputRef.current.focus(); }, [textInput]);

  const saveToHistory = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setHistory((prev) => [...prev, imageData].slice(-20));
    }
  };

  const undo = () => {
    if (history.length === 0) return;
    const newHistory = [...history];
    const previousState = newHistory.pop();
    setHistory(newHistory);
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx && previousState) ctx.putImageData(previousState, 0, 0);
    else if (canvas && ctx && newHistory.length === 0) drawBackground(ctx, canvas.width, canvas.height, isGridMode);
  };

  const clearBoard = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      saveToHistory();
      drawBackground(ctx, canvas.width, canvas.height, isGridMode);
      setTextInput(null);
    }
  };

  const toggleGrid = () => {
    const newMode = !isGridMode;
    setIsGridMode(newMode);
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
       saveToHistory();
       drawBackground(ctx, canvas.width, canvas.height, newMode);
    }
  };

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }
    const rect = canvas.getBoundingClientRect();
    return { x: clientX - rect.left, y: clientY - rect.top };
  };

  const handleTextCommit = () => {
    if (!textInput || !textInput.text.trim()) { setTextInput(null); return; }
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
        saveToHistory();
        ctx.save();
        ctx.font = 'bold 24px sans-serif';
        ctx.fillStyle = color;
        ctx.textBaseline = 'top'; 
        ctx.fillText(textInput.text, textInput.x, textInput.y);
        ctx.restore();
    }
    setTextInput(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext('2d');
            if (canvas && ctx) {
                saveToHistory();
                const canvasWidth = canvas.width;
                const scale = canvasWidth / img.width;
                const drawHeight = img.height * scale;
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, canvasWidth, drawHeight);
            }
        };
        img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (isCollapsed) return;
    const { x, y } = getCoordinates(e);
    if (tool === 'text') {
        if (textInput) handleTextCommit();
        else setTextInput({ x, y, text: '' });
        return;
    }
    if (textInput) { handleTextCommit(); return; }
    isDrawingRef.current = true;
    startPosRef.current = { x, y };
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      snapshotRef.current = ctx.getImageData(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.strokeStyle = tool === 'eraser' ? '#000000' : color; // Màu tẩy là đen
      ctx.lineWidth = tool === 'eraser' ? 30 : 3;
    }
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    const { x, y } = getCoordinates(e);
    if (isGridMode && canvasRef.current) {
        const width = canvasRef.current.width;
        const height = canvasRef.current.height;
        const centerX = Math.floor(width / 2);
        const centerY = Math.floor(height / 2);
        setCursorCoords({ mathX: Math.round((x - centerX) / 40 * 10) / 10, mathY: Math.round(-(y - centerY) / 40 * 10) / 10 });
    } else { setCursorCoords(null); }
    if (!isDrawingRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (canvas && ctx) {
      if (tool === 'pen' || tool === 'eraser') {
        ctx.lineTo(x, y);
        ctx.stroke();
      } else {
        const snapshot = snapshotRef.current;
        const startPos = startPosRef.current;
        if (snapshot && startPos) {
          ctx.putImageData(snapshot, 0, 0);
          ctx.beginPath();
          ctx.setLineDash([]);
          if (tool === 'line' || tool === 'dashed-line') {
             if (tool === 'dashed-line') ctx.setLineDash([10, 10]);
             ctx.moveTo(startPos.x, startPos.y); ctx.lineTo(x, y);
          } else if (tool === 'circle') {
             ctx.arc(startPos.x, startPos.y, Math.sqrt(Math.pow(x - startPos.x, 2) + Math.pow(y - startPos.y, 2)), 0, 2 * Math.PI);
          } else if (tool === 'ellipse') {
             ctx.ellipse(startPos.x, startPos.y, Math.abs(x - startPos.x), Math.abs(y - startPos.y), 0, 0, 2 * Math.PI);
          } else if (tool === 'rectangle') {
             ctx.rect(startPos.x, startPos.y, x - startPos.x, y - startPos.y);
          } else if (tool === 'triangle') {
             ctx.moveTo(startPos.x + (x - startPos.x) / 2, startPos.y); ctx.lineTo(startPos.x, y); ctx.lineTo(x, y); ctx.closePath();
          }
          ctx.stroke();
        }
      }
    }
  };

  const stopDrawing = () => { if (isDrawingRef.current) { isDrawingRef.current = false; saveToHistory(); } };

  const containerProps = mode === 'side' ? {
        className: `fixed top-0 right-0 bottom-0 z-[100] bg-black border-l-4 border-slate-700 shadow-2xl touch-none transition-transform duration-300 ease-in-out ${isCollapsed ? 'translate-x-[calc(100%-30px)]' : 'translate-x-0'}`,
        style: { width: '50vw' }
      } : {
        className: `fixed bottom-0 left-0 right-0 z-[100] bg-black border-t-4 border-slate-700 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] touch-none transition-transform duration-300 ease-in-out ${isCollapsed ? 'translate-y-[calc(100%-30px)]' : 'translate-y-0'}`,
        style: { height: '70vh' }
      };

  return (
    <div ref={containerRef} className={containerProps.className} style={containerProps.style}>
      {/* Tiny Grab Handle */}
      {mode === 'bottom' ? (
        <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-slate-800 text-white flex items-center gap-1 px-3 py-1 rounded-t-lg border-t border-x border-slate-600 cursor-pointer" onClick={() => setIsCollapsed(!isCollapsed)}>
            <span className="text-[10px] font-bold uppercase">Bảng</span>
            {isCollapsed ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
        </div>
      ) : (
         <div className="absolute top-1/2 -left-6 -translate-y-1/2 bg-slate-800 text-white flex flex-col items-center gap-1 px-1 py-3 rounded-l-lg border-l border-y border-slate-600 cursor-pointer" onClick={() => setIsCollapsed(!isCollapsed)}>
            {isCollapsed ? <ChevronLeft className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
            <span className="text-[10px] font-bold uppercase [writing-mode:vertical-rl] rotate-180">Bảng</span>
        </div>
      )}

      {isGridMode && cursorCoords && !isCollapsed && <div className="absolute top-2 left-2 bg-slate-900/80 text-indigo-300 px-2 py-1 rounded border border-slate-700 text-xs font-mono pointer-events-none">({cursorCoords.mathX}; {cursorCoords.mathY})</div>}
      <input ref={imageInputRef} type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
      <canvas ref={canvasRef} onMouseDown={startDrawing} onMouseMove={handleMouseMove} onMouseUp={stopDrawing} onMouseLeave={stopDrawing} onTouchStart={startDrawing} onTouchMove={handleMouseMove} onTouchEnd={stopDrawing} className="cursor-crosshair block w-full h-full" />
      {textInput && !isCollapsed && <input ref={inputRef} type="text" value={textInput.text} onChange={(e) => setTextInput({ ...textInput, text: e.target.value })} onBlur={handleTextCommit} onKeyDown={(e) => { if (e.key === 'Enter') handleTextCommit(); }} autoFocus className="absolute bg-transparent border border-dashed border-white/50 outline-none p-0 m-0 z-[110]" style={{ left: textInput.x, top: textInput.y, color: color, font: 'bold 24px sans-serif' }} />}

      {/* Tiny Toolbar */}
      {!isCollapsed && (
        <div className="absolute right-2 top-1/2 -translate-y-1/2 bg-slate-900/90 backdrop-blur-xl border border-white/10 p-1 rounded-lg shadow-xl flex flex-col items-center gap-1 z-[120]">
          <button onClick={() => onModeChange(mode === 'bottom' ? 'side' : 'bottom')} className="p-1 rounded hover:bg-white/10 text-yellow-400" title="Chuyển chế độ"><PanelBottom className="w-4 h-4" /></button>
          <div className="h-px w-full bg-white/20"></div>
          {['#ffffff', '#facc15', '#f43f5e', '#4ade80', '#60a5fa'].map((c) => (
              <button key={c} onClick={() => { setColor(c as ColorType); if (tool === 'eraser') setTool('pen'); }} className={`w-4 h-4 rounded-full border-2 ${color === c && tool !== 'eraser' ? 'border-white' : 'border-transparent'}`} style={{ backgroundColor: c }} />
          ))}
          <div className="h-px w-full bg-white/20"></div>
          {[
            { t: 'pen', i: PenTool }, { t: 'eraser', i: Eraser }, { t: 'text', i: Type }, 
            { t: 'line', i: Minus }, { t: 'circle', i: Circle }, { t: 'rectangle', i: Square }
          ].map((item) => (
             <button key={item.t} onClick={() => setTool(item.t as any)} className={`p-1 rounded ${tool === item.t ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'}`}><item.i className="w-4 h-4" /></button>
          ))}
          <button onClick={() => imageInputRef.current?.click()} className="p-1 text-slate-400 hover:text-white"><ImageIcon className="w-4 h-4" /></button>
          <div className="h-px w-full bg-white/20"></div>
          <button onClick={toggleGrid} className={`p-1 rounded ${isGridMode ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}><Grid3X3 className="w-4 h-4" /></button>
          <button onClick={undo} className="p-1 text-slate-400 hover:text-white"><Undo className="w-4 h-4" /></button>
          <button onClick={clearBoard} className="p-1 text-red-400 hover:text-white"><Trash2 className="w-4 h-4" /></button>
          <button onClick={onClose} className="p-1 mt-1 text-slate-500 hover:text-red-500"><X className="w-4 h-4" /></button>
        </div>
      )}
    </div>
  );
};

export default Blackboard;

export enum DifficultyLevel {
  VERY_EASY = 'Rất dễ (Nhận biết)',
  EASY = 'Dễ (Thông hiểu)',
  MEDIUM = 'Trung bình (Vận dụng)',
  HARD = 'Khó (Vận dụng cao)',
  VERY_HARD = 'Rất khó (Xuất sắc)',
}

export enum QuestionType {
  MULTIPLE_CHOICE = 'Trắc nghiệm (4 chọn 1)',
  TRUE_FALSE = 'Trắc nghiệm Đúng/Sai',
  ESSAY = 'Tự luận',
  MIXED = 'Kết hợp (TN + Đúng/Sai + Tự luận)',
}

export enum Subject {
  MATH = 'Toán',
  PHYSICS = 'Vật Lý',
  CHEMISTRY = 'Hóa Học',
  BIOLOGY = 'Sinh Học',
  INFORMATICS = 'Tin Học',
  LITERATURE = 'Ngữ Văn',
  HISTORY = 'Lịch Sử',
  GEOGRAPHY = 'Địa Lý',
  ENGLISH = 'Tiếng Anh',
  GDCD = 'GDCD',
  SCIENCE = 'KHTN',
  CLASS_MEETING = 'Sinh hoạt lớp',
  LIFE_SKILLS = 'Kỹ năng sống',
  CAREER_GUIDANCE = 'Trải nghiệm hướng nghiệp',
}

export type GenMode = 'exam' | 'matrix' | 'theory' | 'polya';

export interface MatrixRow {
  topic: string;
  level: DifficultyLevel;
  count: number;
  type: QuestionType;
}

export interface ExamConfig {
  mode: GenMode;
  subject: Subject | string;
  grade: string;
  topic: string; // Used for single topic mode or as a title for matrix mode
  // Exam specific (Single Mode)
  questionType?: QuestionType;
  questionCount?: number;
  difficultyMode?: 'progressive' | 'fixed';
  targetLevel?: DifficultyLevel;
  // Matrix Mode
  matrixRows?: MatrixRow[];

  includeHints?: boolean;
  // Multimodal support
  uploadedFile?: {
    data: string; // base64 string
    mimeType: string;
  } | null;
}

export interface Question {
  id: number;
  content: string;
  type: QuestionType;
  difficulty: string; // e.g., "Nhận biết", "Vận dụng"
  options?: string[]; // For multiple choice
  correctAnswer: string;
  solution: string; // Detailed explanation
  hints?: string[]; // Step-by-step hints
}

export interface ExamMatrix {
  title?: string;
  objectives?: string[]; // Learning objectives
  summary: string;
  questions: Question[];
}

// Structures for Study Guide (Theory & Examples)
export interface Example {
  problem: string;
  solution: string;
  explanation: string;
}

export interface TheorySection {
  title: string;
  content: string; // Bullet points or paragraphs with LaTeX
  examples: Example[];
}

export interface StudyGuideData {
  topic: string;
  overview: string;
  sections: TheorySection[];
}

// Structures for Polya Method
export interface PolyaStep {
  stepName: string; // e.g., "Bước 1: Tìm hiểu đề bài"
  icon: 'search' | 'map' | 'wrench' | 'check';
  content: string; // LaTeX supported content
  keyPoints?: string[]; // Highlights
}

export interface PolyaData {
  title: string;
  problem: string;
  steps: PolyaStep[];
}

// Data structure for Export/Import
export interface ExportData {
  type: GenMode;
  timestamp: number;
  config: ExamConfig;
  data: ExamMatrix | StudyGuideData | PolyaData;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData, MatrixRow, DifficultyLevel, PolyaData } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const suggestMatrixStructure = async (subject: string, grade: string, title: string): Promise<MatrixRow[]> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const prompt = `
Bạn là chuyên gia khảo thí. Hãy gợi ý một cấu trúc ma trận đề thi chuẩn cho:
Môn: ${subject}
Lớp: ${grade}
Tiêu đề/Phạm vi: ${title}

TRẢ VỀ JSON MẢNG MatrixRow:
[
  { "topic": "Tên chuyên đề", "level": "Mức độ", "count": số_câu, "type": "Loại câu" }
]
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      },
    });
    return JSON.parse(response.text) as MatrixRow[];
  } catch (error) {
    console.error("Matrix suggestion failed:", error);
    return [];
  }
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let structureInstruction = "";
  if (config.mode === 'matrix' && config.matrixRows) {
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu, Chủ đề: "${row.topic}", Mức: ${row.level}, Dạng: ${row.type}.\n`;
      });
  } else {
      structureInstruction = `Chủ đề: "${config.topic}", Số lượng: ${config.questionCount} câu, Dạng: ${config.questionType}.`;
  }

  let promptText = `
Bạn là chuyên gia soạn đề kiểm tra môn ${config.subject}, lớp ${config.grade}.

QUY TẮC CỰC KỲ QUAN TRỌNG VỀ ĐỊNH DẠNG (BẮT BUỘC):
1. LATEX: Mọi công thức toán PHẢI đặt trong $...$ (Ví dụ: $V = \\\\frac{1}{3}Bh$). PHẢI escape backslash kép (\\\\) trong chuỗi JSON để không lỗi.
2. OPTIONS (PHẢI CÓ CHO TRẮC NGHIỆM): 
   - Với "Trắc nghiệm (4 chọn 1)": Mảng 'options' PHẢI có đúng 4 phần tử, mỗi phần tử bắt đầu bằng A., B., C., D. (Ví dụ: ["A. $x=1$", "B. $x=2$", "C. $x=3$", "D. $x=4$"])
   - Với "Trắc nghiệm Đúng/Sai": Mảng 'options' PHẢI có đúng 4 mệnh đề a), b), c), d).
   - Tuyệt đối không để 'options' null hoặc rỗng đối với các câu hỏi trắc nghiệm.
3. ĐÁP ÁN: 'correctAnswer' phải rõ ràng. Với Đúng/Sai: "a: Đúng, b: Sai, c: Đúng, d: Sai".

NỘI DUNG YÊU CẦU:
${structureInstruction}
- Ngôn ngữ: Tiếng Việt chuẩn mực.
- solution: Giải chi tiết từng bước.
- hints: 3-5 bước gợi ý ngắn gọn.

TRẢ VỀ JSON CHUẨN THEO SCHEMA.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["id", "content", "type", "difficulty", "correctAnswer", "solution", "hints", "options"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      summary: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "questions"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.1,
      },
    });

    const parsed = JSON.parse(response.text);
    return parsed as ExamMatrix;
  } catch (error: any) {
    console.error("Lỗi sinh đề:", error);
    throw new Error("Lỗi hệ thống AI: " + error.message);
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let promptText = `Soạn bài giảng slide môn ${config.subject}, ${config.grade}. Chủ đề: "${config.topic}". Dùng $...$ cho LaTeX và escape \\\\ trong JSON. Tách các ý bằng dấu ★.`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: promptText,
      config: {
        responseMimeType: "application/json",
        temperature: 0.4,
      },
    });
    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    throw new Error("Lỗi sinh bài giảng: " + error.message);
  }
};

export const generatePolyaSolution = async (config: ExamConfig): Promise<PolyaData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const promptText = `
  Bạn là một giáo sư toán học lỗi lạc, người áp dụng phương pháp của George Polya để hướng dẫn học sinh giải toán.
  Hãy phân tích bài toán sau đây theo 4 bước của Polya.

  BÀI TOÁN: "${config.topic}"

  YÊU CẦU ĐẦU RA (JSON):
  Hãy trả về một object JSON duy nhất với cấu trúc sau:
  {
    "title": "Tên ngắn gọn của bài toán",
    "problem": "Nội dung bài toán (có thể format lại cho đẹp bằng LaTeX)",
    "steps": [
      {
        "stepName": "Bước 1: Tìm hiểu đề bài",
        "icon": "search",
        "content": "Phân tích giả thiết (Cái đã cho), kết luận (Cái cần tìm). Vẽ hình nếu cần thiết (mô tả bằng lời). Định dạng LaTeX $...$ chuẩn.",
        "keyPoints": ["Giả thiết: ...", "Yêu cầu: ..."]
      },
      {
        "stepName": "Bước 2: Xây dựng chương trình giải",
        "icon": "map",
        "content": "Tìm mối liên hệ giữa giả thiết và kết luận. Nhớ lại các định lý, công thức liên quan. Lập kế hoạch từng bước.",
        "keyPoints": ["Sử dụng định lý...", "Đặt ẩn phụ...", "Chứng minh..."]
      },
      {
        "stepName": "Bước 3: Thực hiện chương trình giải",
        "icon": "wrench",
        "content": "Trình bày lời giải chi tiết, rõ ràng, tính toán chính xác. Dùng LaTeX cho công thức.",
        "keyPoints": []
      },
      {
        "stepName": "Bước 4: Kiểm tra và khai thác",
        "icon": "check",
        "content": "Kiểm tra lại kết quả. Thử lại bằng cách khác (nếu có). Mở rộng bài toán hoặc tổng quát hóa.",
        "keyPoints": ["Cách khác: ...", "Bài toán tương tự..."]
      }
    ]
  }
  `;

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        temperature: 0.3, // Low temp for logic precision
      },
    });

    return JSON.parse(response.text) as PolyaData;
  } catch (error: any) {
    console.error("Lỗi sinh Polya:", error);
    throw new Error("Lỗi hệ thống AI: " + error.message);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { SUBJECTS, GRADES, DIFFICULTY_LEVELS, QUESTION_TYPES, SAMPLE_TOPICS } from '../constants';
import { ExamConfig, Subject, QuestionType, DifficultyLevel, GenMode, MatrixRow } from '../types';
import { BookOpen, Brain, Sparkles, Layers, ListChecks, Presentation as PresentationIcon, FileText, Upload, Image as ImageIcon, X, Paperclip, Plus, Trash2, Table2, Loader2, Footprints } from 'lucide-react';

interface ConfigFormProps {
  onGenerate: (config: ExamConfig) => void;
  isLoading: boolean;
  onImport: (file: File) => void;
  forcedMode?: GenMode; // Prop mới
}

const ConfigForm: React.FC<ConfigFormProps> = ({ onGenerate, isLoading, onImport, forcedMode }) => {
  const [mode, setMode] = useState<GenMode>(forcedMode || 'exam');
  const [subject, setSubject] = useState<Subject | string>(Subject.MATH);
  const [grade, setGrade] = useState<string>(GRADES[11]); 

  // Đồng bộ mode nếu forcedMode thay đổi
  useEffect(() => {
    if (forcedMode) setMode(forcedMode);
  }, [forcedMode]);

  // Single Mode State
  const [topic, setTopic] = useState<string>('');
  const [questionType, setQuestionType] = useState<QuestionType>(QuestionType.MULTIPLE_CHOICE);
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficultyMode, setDifficultyMode] = useState<'progressive' | 'fixed'>('progressive');
  const [targetLevel, setTargetLevel] = useState<DifficultyLevel>(DifficultyLevel.MEDIUM);

  // Matrix Mode State
  const [matrixTitle, setMatrixTitle] = useState<string>('Đề ôn tập học kì');
  const [matrixRows, setMatrixRows] = useState<MatrixRow[]>([
    { topic: '', level: DifficultyLevel.EASY, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.MEDIUM, count: 2, type: QuestionType.MULTIPLE_CHOICE },
    { topic: '', level: DifficultyLevel.HARD, count: 1, type: QuestionType.ESSAY },
  ]);

  // File upload state
  const [uploadedFile, setUploadedFile] = useState<{name: string, data: string, mimeType: string} | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const resourceInputRef = useRef<HTMLInputElement>(null);

  const suggestedTopics = SAMPLE_TOPICS[subject as Subject] || [];

  const handleAddRow = () => {
    setMatrixRows([...matrixRows, { topic: '', level: DifficultyLevel.MEDIUM, count: 1, type: QuestionType.MULTIPLE_CHOICE }]);
  };

  const handleRemoveRow = (index: number) => {
    if (matrixRows.length > 1) {
      const newRows = [...matrixRows];
      newRows.splice(index, 1);
      setMatrixRows(newRows);
    }
  };

  const handleRowChange = (index: number, field: keyof MatrixRow, value: any) => {
    const newRows = [...matrixRows];
    newRows[index] = { ...newRows[index], [field]: value };
    setMatrixRows(newRows);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalTopic = mode === 'matrix' ? matrixTitle : (topic || (uploadedFile ? "Nội dung từ tài liệu đính kèm" : ""));

    onGenerate({
      mode,
      subject,
      grade,
      topic: finalTopic,
      questionType: mode === 'exam' ? questionType : undefined,
      questionCount: mode === 'exam' ? questionCount : undefined,
      difficultyMode: mode === 'exam' ? difficultyMode : undefined,
      targetLevel: mode === 'exam' && difficultyMode === 'fixed' ? targetLevel : undefined,
      matrixRows: mode === 'matrix' ? matrixRows : undefined,
      includeHints: true,
      uploadedFile: uploadedFile ? { data: uploadedFile.data, mimeType: uploadedFile.mimeType } : null
    });
  };

  const handleResourceFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64String = event.target?.result as string;
        const base64Data = base64String.split(',')[1];
        setUploadedFile({ name: file.name, mimeType: file.type, data: base64Data });
        if (mode !== 'matrix' && !topic) {
          setTopic("Nội dung tài liệu: " + file.name);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUploadedFile = () => {
    setUploadedFile(null);
    if (mode !== 'matrix' && topic.startsWith("Nội dung tài liệu:")) {
        setTopic("");
    }
  };

  return (
    <div className="w-full bg-white dark:bg-slate-800 rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative transition-all duration-300">

      {/* Ẩn Tab nếu forcedMode được bật */}
      {!forcedMode && (
        <div className="flex border-b border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 overflow-x-auto">
          <button onClick={() => setMode('exam')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'exam' ? 'border-blue-600 text-blue-700 bg-white' : 'border-transparent text-slate-500'}`}><ListChecks className="w-5 h-5" /> Đơn lẻ</button>
          <button onClick={() => setMode('matrix')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'matrix' ? 'border-indigo-600 text-indigo-700 bg-white' : 'border-transparent text-slate-500'}`}><Table2 className="w-5 h-5" /> Tổng hợp</button>
          <button onClick={() => setMode('theory')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'theory' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-slate-500'}`}><PresentationIcon className="w-5 h-5" /> Lý thuyết</button>
          <button onClick={() => setMode('polya')} className={`flex-1 min-w-[140px] py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${mode === 'polya' ? 'border-orange-600 text-orange-700 bg-white' : 'border-transparent text-slate-500'}`}><Footprints className="w-5 h-5" /> G.Polya</button>
        </div>
      )}

      <div className="p-10 border-b border-slate-50 dark:border-slate-700">
        <h2 className={`text-3xl font-black flex items-center gap-3 ${
            mode === 'exam' ? 'text-blue-700' : mode === 'matrix' ? 'text-indigo-700' : mode === 'theory' ? 'text-teal-700' : 'text-orange-600'
        } dark:text-white`}>
          <Sparkles className="w-8 h-8 text-yellow-500" />
          {mode === 'exam' && 'Cấu hình Đề Chuyên Đề'}
          {mode === 'matrix' && 'Cấu hình Ma Trận Tổng Hợp'}
          {mode === 'theory' && 'Cấu hình Bài Giảng Slide'}
          {mode === 'polya' && 'Giải Toán G.Polya'}
        </h2>
        <p className="text-slate-500 dark:text-slate-400 mt-2 text-sm font-medium">Điền các thông tin cần thiết để AI bắt đầu quá trình sáng tạo.</p>
      </div>

      <form onSubmit={handleSubmit} className="p-10 space-y-10">
        {mode !== 'polya' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Môn học</label>
                <select 
                  value={subject} 
                  onChange={(e) => setSubject(e.target.value)}
                  className="w-full rounded-2xl border-slate-200 dark:border-slate-700 border-2 p-4 text-slate-800 dark:text-slate-100 font-black focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 transition-all outline-none"
                >
                  {SUBJECTS.map((s) => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Khối lớp</label>
                <select 
                  value={grade} 
                  onChange={(e) => setGrade(e.target.value)}
                  className="w-full rounded-2xl border-slate-200 dark:border-slate-700 border-2 p-4 text-slate-800 dark:text-slate-100 font-black focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50 dark:bg-slate-900 transition-all outline-none"
                >
                  {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
          </div>
        )}

        {mode !== 'matrix' && (
            <div className="space-y-6">
                <div className="bg-slate-50 dark:bg-slate-900 p-8 rounded-[2rem] border-2 border-slate-100 dark:border-slate-700 relative">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 block">
                      {mode === 'polya' ? 'Nội dung bài toán' : 'Chủ đề bài giảng/Đề thi'}
                    </label>
                    <input type="file" ref={resourceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleResourceFileChange}/>

                    {!uploadedFile ? (
                        <div className="flex flex-col gap-4">
                            <div className="flex gap-4">
                            {mode === 'polya' ? (
                                <textarea
                                  value={topic}
                                  onChange={(e) => setTopic(e.target.value)}
                                  placeholder="Nhập đề bài toán vào đây..."
                                  rows={4}
                                  className="flex-grow rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-4 text-slate-900 dark:text-slate-100 font-bold focus:ring-4 focus:ring-indigo-500/20 outline-none resize-none"
                                />
                            ) : (
                                <input
                                    type="text"
                                    value={topic}
                                    onChange={(e) => setTopic(e.target.value)}
                                    placeholder="VD: Sóng ánh sáng, Hiện tượng cảm ứng điện từ..."
                                    className="flex-grow rounded-2xl border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 border-2 p-4 text-slate-900 dark:text-slate-100 font-bold focus:ring-4 focus:ring-indigo-500/20 outline-none"
                                />
                            )}
                            <button
                                type="button"
                                onClick={() => resourceInputRef.current?.click()}
                                className="flex-shrink-0 flex items-center gap-3 px-6 py-4 bg-white dark:bg-slate-800 border-2 border-indigo-200 dark:border-indigo-900 rounded-2xl text-indigo-700 dark:text-indigo-400 hover:bg-indigo-50 font-black transition-all shadow-sm"
                            >
                                <Paperclip className="w-5 h-5" /> <span className="hidden sm:inline">Ảnh/PDF</span>
                            </button>
                            </div>
                            {mode !== 'polya' && suggestedTopics.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                                {suggestedTopics.map(t => (
                                <button key={t} type="button" onClick={() => setTopic(t)} className="text-[10px] font-black uppercase tracking-widest bg-white dark:bg-slate-800 hover:bg-indigo-600 hover:text-white text-slate-400 px-4 py-2 rounded-full border border-slate-200 dark:border-slate-700 transition-all">
                                    + {t}
                                </button>
                                ))}
                            </div>
                            )}
                        </div>
                    ) : (
                        <div className="flex items-center justify-between bg-white dark:bg-slate-800 border-4 border-indigo-50 dark:border-indigo-900/30 p-4 rounded-2xl shadow-lg animate-fade-in-up">
                            <div className="flex items-center gap-4 overflow-hidden">
                                <div className="bg-indigo-600 p-3 rounded-xl text-white">
                                    {uploadedFile.mimeType.includes('pdf') ? <FileText className="w-6 h-6"/> : <ImageIcon className="w-6 h-6"/>}
                                </div>
                                <span className="font-black text-slate-800 dark:text-white truncate">{uploadedFile.name}</span>
                            </div>
                            <button type="button" onClick={clearUploadedFile} className="p-2 hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-full transition-colors"><X className="w-6 h-6" /></button>
                        </div>
                    )}
                </div>

                {mode === 'exam' && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-2">
                            <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Loại câu hỏi</label>
                            <select 
                                value={questionType} 
                                onChange={(e) => setQuestionType(e.target.value as QuestionType)}
                                className="w-full rounded-2xl border-slate-200 dark:border-slate-700 border-2 p-4 text-slate-800 dark:text-slate-100 font-bold bg-white dark:bg-slate-900 outline-none"
                            >
                                {QUESTION_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
                            </select>
                        </div>
                        <div className="space-y-2">
