import React, { useState, useRef, useEffect } from 'react';
import { PolyaData } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, Maximize, Minimize, PenTool, Home, Save, Search, Map, Wrench, CheckCircle, FileText, MonitorPlay, ZoomIn, ZoomOut } from 'lucide-react';
import Blackboard from './Blackboard';

interface PolyaPreviewProps {
  data: PolyaData;
  onReset: () => void;
}

const ShortcutLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
);

const PolyaPreview: React.FC<PolyaPreviewProps> = ({ data, onReset }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [viewMode, setViewMode] = useState<'slide' | 'doc'>('slide');
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(2.0);
  const [showBlackboard, setShowBlackboard] = useState(false);
  const [blackboardMode, setBlackboardMode] = useState<'bottom' | 'side'>('bottom');

  const containerRef = useRef<HTMLDivElement>(null);
  const steps = data.steps;

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();

      if (key === 'b') setShowBlackboard(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();

      if (viewMode === 'slide') {
        if (e.key === 'ArrowRight') setCurrentStep(s => Math.min(steps.length - 1, s + 1));
        if (e.key === 'ArrowLeft') setCurrentStep(s => Math.max(0, s - 1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode, currentStep, steps.length]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.2, 4.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.2, 0.5));

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'polya', data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Polya_${data.title}.json`; a.click();
  };

  const getStepIcon = (iconName: string) => {
    switch(iconName) {
      case 'search': return <Search className="w-12 h-12 text-blue-500" />;
      case 'map': return <Map className="w-12 h-12 text-amber-500" />;
      case 'wrench': return <Wrench className="w-12 h-12 text-emerald-500" />;
      case 'check': return <CheckCircle className="w-12 h-12 text-rose-500" />;
      default: return <Search className="w-12 h-12" />;
    }
  };

  const getStepColor = (index: number) => {
    const colors = ['border-blue-500 text-blue-700', 'border-amber-500 text-amber-700', 'border-emerald-500 text-emerald-700', 'border-rose-500 text-rose-700'];
    return colors[index % colors.length];
  };

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
      {/* Header */}
      <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 p-2 h-10 flex justify-between items-center px-2 no-print sticky top-0 z-50">
        <div className="flex items-center gap-2">
            <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
            <h1 className="text-xs font-black truncate max-w-[200px] uppercase dark:text-zinc-200">{data.title}</h1>
        </div>
        <div className="flex items-center gap-1.5">
            <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
            <div className="flex bg-slate-100 dark:bg-zinc-900 p-0.5 rounded-lg">
                <button onClick={() => setViewMode('doc')} className={`p-1 rounded-md ${viewMode === 'doc' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><FileText className="w-3.5 h-3.5"/></button>
                <button onClick={() => setViewMode('slide')} className={`p-1 rounded-md ${viewMode === 'slide' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-3.5 h-3.5"/></button>
            </div>
            <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 relative text-slate-600 dark:text-slate-300">
                {isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}
            </button>
        </div>
      </header>

      <main className={`flex-grow relative flex transition-all duration-500 ${viewMode === 'slide' ? 'overflow-hidden' : 'p-4 md:p-8 max-w-6xl mx-auto w-full'}`}>
         <div className={`transition-all duration-500 h-full flex flex-col ${showBlackboard && blackboardMode === 'side' && viewMode === 'slide' ? 'w-1/2' : 'w-full'}`}>

           {/* Document View */}
           {viewMode === 'doc' ? (
             <div className="bg-white dark:bg-zinc-950 p-12 rounded-[3rem] shadow-xl border border-slate-100 dark:border-zinc-800" style={{ fontSize: `${zoomLevel * 100}%` }}>
                <div className="mb-8 pb-6 border-b-2 border-slate-100 dark:border-zinc-800">
                   <h2 className="text-[1.5em] font-black text-indigo-700 dark:text-indigo-400 mb-2 uppercase">{data.title}</h2>
                   <div className="p-6 bg-slate-50 dark:bg-zinc-900 rounded-2xl border-l-4 border-slate-400 text-[1em] font-medium italic dark:text-zinc-300">
                      <MathRenderer content={data.problem} />
                   </div>
                </div>
                {steps.map((s, i) => (
                  <div key={i} className="mb-10 last:mb-0">
                     <h3 className={`text-[1.2em] font-black mb-4 uppercase border-b-4 inline-block pb-1 ${getStepColor(i)}`}>{s.stepName}</h3>
                     <div className="text-[1em] font-medium leading-relaxed dark:text-zinc-200 pl-4 border-l-2 border-slate-200 dark:border-slate-800">
                        <MathRenderer content={s.content} />
                     </div>
                     {s.keyPoints && s.keyPoints.length > 0 && (
                        <div className="mt-4 flex flex-wrap gap-2">
                           {s.keyPoints.map((k, ki) => (
                             <span key={ki} className="text-[0.7em] font-bold bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full text-slate-600 dark:text-slate-400">{k}</span>
                           ))}
                        </div>
                     )}
                  </div>
                ))}
             </div>
           ) : (
             /* Slide View */
             <div className="h-full w-full flex flex-col items-center justify-center p-8 md:p-12 transition-all duration-300 ease-out bg-white dark:bg-zinc-950 rounded-[3rem] shadow-2xl border-4 border-slate-100 dark:border-zinc-800" style={{ fontSize: `${zoomLevel * 100}%` }}>

                {/* Problem Statement Always Visible on Top (Small) */}
                <div className="w-full mb-6 p-4 bg-slate-50 dark:bg-zinc-900 rounded-2xl border border-slate-200 dark:border-zinc-800 max-h-[20vh] overflow-y-auto">
                    <div className="text-[0.6em] font-bold text-slate-500 uppercase mb-1">Đề bài:</div>
                    <div className="text-[0.8em] font-medium dark:text-zinc-300"><MathRenderer content={data.problem} inline /></div>
                </div>

                {/* Main Step Content */}
                <div className="flex-grow flex flex-col items-center justify-center w-full text-center animate-fade-in-up">
                    <div className="mb-6">{getStepIcon(steps[currentStep].icon)}</div>
                    <h2 className={`text-[2em] font-black mb-6 uppercase leading-none ${getStepColor(currentStep)}`}>{steps[currentStep].stepName}</h2>
                    <div className="text-[1.2em] font-bold text-slate-800 dark:text-zinc-100 w-full text-left leading-relaxed overflow-y-auto max-h-[50vh] custom-scrollbar p-4">
                       <MathRenderer content={steps[currentStep].content} />
                    </div>
                </div>

                {/* Step Indicators */}
                <div className="mt-8 flex gap-2">
                   {steps.map((_, i) => (
                      <div key={i} className={`h-2 rounded-full transition-all duration-300 ${i === currentStep ? 'w-12 bg-indigo-600' : 'w-2 bg-slate-200 dark:bg-slate-800'}`}></div>
                   ))}
                </div>
             </div>
           )}
         </div>

         {isSidePanelOpen && viewMode === 'slide' && (
            <div className="w-1/2 h-full bg-slate-800 border-l-4 border-slate-700 z-40 relative">
                <Blackboard onClose={() => setShowBlackboard(false)} mode="side" onModeChange={setBlackboardMode} />
            </div>
         )}

         {viewMode === 'slide' && (
             <div className="fixed inset-y-0 left-0 right-0 flex justify-between items-center pointer-events-none z-[80] no-print">
                 <button onClick={() => setCurrentStep(s => Math.max(0, s-1))} disabled={currentStep === 0} className="ml-6 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronLeft className="w-8 h-8"/></button>
                 <button onClick={() => setCurrentStep(s => Math.min(steps.length-1, s+1))} disabled={currentStep === steps.length-1} className="mr-6 p-4 bg-white/30 dark:bg-black/30 backdrop-blur shadow-lg rounded-full text-indigo-600 dark:text-indigo-400 hover:scale-110 transition-all pointer-events-auto disabled:hidden"><ChevronRight className="w-8 h-8"/></button>
             </div>
         )}
      </main>

      {/* Floating Toolbar */}
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 z-[100] border border-white/10 shadow-xl items-center no-print">
            <button onClick={() => setShowBlackboard(true)} className={`p-2 transition-colors relative ${showBlackboard ? 'text-yellow-400' : 'text-slate-400 hover:text-yellow-400'}`}><PenTool className="w-5 h-5"/><ShortcutLabel>B</ShortcutLabel></button>
            <div className="w-px h-6 bg-white/20"></div>
            <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
            </div>
      </div>

      {showBlackboard && blackboardMode === 'bottom' && <Blackboard onClose={() => setShowBlackboard(false)} mode="bottom" onModeChange={setBlackboardMode} />}
    </div>
  );
};

