import React, { useEffect, useRef } from 'react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
  highlightClass?: string;
}

declare global {
  interface Window {
    MathJax: any;
  }
}

// Mảng màu sắc rực rỡ để random cho công thức toán
const MATH_COLORS = [
  'text-cyan-600 dark:text-cyan-400',
  'text-fuchsia-600 dark:text-fuchsia-400',
  'text-lime-600 dark:text-lime-400',
  'text-orange-600 dark:text-orange-400',
  'text-sky-600 dark:text-sky-400',
  'text-rose-600 dark:text-rose-400',
  'text-violet-600 dark:text-violet-400'
];

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false, highlightClass = "" }) => {
  const containerRef = useRef<HTMLElement>(null);

  // Ensure content is safe
  const safeContent = content || "";

  // Chọn màu dựa trên độ dài nội dung để cố định màu cho mỗi công thức (tránh flicker khi re-render)
  const getColorClass = (text: string) => {
    if (highlightClass) return highlightClass;
    const index = text.length % MATH_COLORS.length;
    return MATH_COLORS[index];
  };

  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          if (window.MathJax.typesetClear) {
            window.MathJax.typesetClear([containerRef.current]);
          }
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    renderMath();
  }, [safeContent]);

  const processContent = (text: string) => {
    if (!text) return null;

    const sanitizedText = text.replace(/\\n/g, '\n');

    // Tách phần text thường và công thức toán (trong $...$)
    // Regex này giữ lại dấu phân cách trong mảng kết quả
    const parts = sanitizedText.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        // Bold markdown
        return (
          <strong key={index} className="font-black text-indigo-700 dark:text-indigo-300">
            {part.slice(2, -2)}
          </strong>
        );
      } else if (part.startsWith('$') && part.endsWith('$')) {
        // Math formula
        const colorClass = getColorClass(part);
        return (
          <span key={index} className={`font-bold ${colorClass} mx-1`}>
            {part}
          </span>
        );
      }
      return <span key={index}>{part}</span>;
    });
  };

  const contentKey = `math-${safeContent.length}-${safeContent.substring(0, 10)}`;

  if (inline) {
    return (
      <span 
        key={contentKey}
        ref={containerRef as React.RefObject<HTMLSpanElement>} 
        className="math-renderer inline-block align-middle whitespace-pre-wrap tex2jax_process"
      >
        {processContent(safeContent)}
      </span>
    );
  }

  return (
    <div 
      key={contentKey}
      ref={containerRef as React.RefObject<HTMLDivElement>} 
      className="math-renderer block my-2 whitespace-pre-wrap tex2jax_process"
    >
      {processContent(safeContent)}
    </div>
  );
};

export default MathRenderer;

import React, { useState, useRef, useEffect } from 'react';
import { PolyaData } from '../types';
