interface BankItem {
  id: string;
  title: string;
  date: number;
  type: 'exam' | 'theory' | 'polya';
  data: any;
  config: ExamConfig;
}

interface QuestionBankProps {
  bank: BankItem[];
  onLoad: (item: BankItem) => void;
  onDelete: (id: string) => void;
  onImport: (file: File) => void; // Import to bank
  onClose: () => void;
}

const GRADES_ORDER = [
  'Lớp 6', 'Lớp 7', 'Lớp 8', 'Lớp 9', 
  'Lớp 10', 'Lớp 11', 'Lớp 12', 
  'Ôn thi THPT QG', 'Khác'
];

const QuestionBank: React.FC<QuestionBankProps> = ({ bank, onLoad, onDelete, onImport, onClose }) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set(GRADES_ORDER));
  const [searchTerm, setSearchTerm] = useState('');

  // Group items by grade
  const groupedBank = bank.reduce((acc, item) => {
    const grade = item.config.grade || 'Khác';
    if (!acc[grade]) acc[grade] = [];
    acc[grade].push(item);
    return acc;
  }, {} as Record<string, BankItem[]>);

  // Toggle Folder
  const toggleGrade = (grade: string) => {
    const newSet = new Set(expandedGrades);
    if (newSet.has(grade)) newSet.delete(grade);
    else newSet.add(grade);
    setExpandedGrades(newSet);
  };

  const handleExportBank = () => {
    const blob = new Blob([JSON.stringify(bank, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `Ngan_Hang_Cau_Hoi_AI_Studio_${new Date().toLocaleDateString('vi-VN').replace(/\//g, '-')}.json`;
    a.click();
  };

  const filteredGrades = GRADES_ORDER.filter(grade => {
    const items = groupedBank[grade] || [];
    if (searchTerm) {
        return items.some(i => i.title.toLowerCase().includes(searchTerm.toLowerCase()));
    }
    return true; // Show all grades structure if no search, or hide empty ones? Let's show existing ones.
  }).filter(grade => groupedBank[grade] && groupedBank[grade].length > 0);

  return (
    <div className="fixed inset-0 z-[150] bg-black/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in" onClick={onClose}>
      <div className="bg-white dark:bg-slate-800 rounded-[2rem] w-full max-w-4xl h-[85vh] overflow-hidden shadow-2xl border-4 border-indigo-100 dark:border-slate-700 flex flex-col" onClick={e => e.stopPropagation()}>

        {/* Header */}
        <div className="bg-gradient-to-r from-emerald-600 to-teal-600 p-6 flex justify-between items-center text-white shrink-0">
            <div className="flex items-center gap-3">
                <Database className="w-8 h-8" />
                <div>
                    <h2 className="text-2xl font-black uppercase tracking-tighter">Ngân hàng bài học</h2>
                    <p className="text-xs font-medium opacity-90">{bank.length} nội dung đã lưu trữ</p>
                </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-full transition-colors"><X className="w-6 h-6"/></button>
        </div>

        {/* Toolbar */}
        <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex flex-col md:flex-row gap-4 bg-slate-50 dark:bg-slate-900 shrink-0">
            <div className="flex-1 relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                    type="text" 
                    placeholder="Tìm kiếm bài học..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm font-bold outline-none focus:ring-2 focus:ring-emerald-500"
                />
            </div>
            <div className="flex gap-2">
                <button 
                    onClick={() => {
                        const input = document.createElement('input');
                        input.type = 'file';
                        input.accept = '.json';
                        input.onchange = (e: any) => {
                            if (e.target.files[0]) onImport(e.target.files[0]);
                        };
                        input.click();
                    }}
                    className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-xl text-xs font-black uppercase text-slate-600 dark:text-slate-300 hover:bg-indigo-50 dark:hover:bg-slate-700 transition-colors"
                >
                    <Upload className="w-4 h-4" /> Import Ngân hàng
                </button>
                <button 
                    onClick={handleExportBank}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl text-xs font-black uppercase hover:bg-indigo-700 transition-colors shadow-lg"
                >
                    <Download className="w-4 h-4" /> Sao lưu về máy
                </button>
            </div>
        </div>

        {/* Tree View Content */}
        <div className="flex-grow overflow-y-auto custom-scrollbar p-6 bg-slate-50 dark:bg-slate-950">
            {bank.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                    <Database className="w-20 h-20 mb-4" />
                    <p className="font-bold">Ngân hàng trống</p>
                    <p className="text-xs">Lưu bài học từ màn hình xem trước để xem tại đây</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {filteredGrades.map((grade) => {
                        const items = groupedBank[grade].filter(i => !searchTerm || i.title.toLowerCase().includes(searchTerm.toLowerCase()));
                        if (items.length === 0) return null;

                        const isExpanded = expandedGrades.has(grade);

                        return (
                            <div key={grade} className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                                <button 
                                    onClick={() => toggleGrade(grade)}
                                    className="w-full flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-left"
                                >
                                    <div className="flex items-center gap-3">
                                        {isExpanded ? <ChevronDown className="w-5 h-5 text-slate-400" /> : <ChevronRight className="w-5 h-5 text-slate-400" />}
                                        <Folder className="w-6 h-6 text-yellow-500 fill-yellow-100 dark:fill-yellow-900/20" />
                                        <span className="font-black text-slate-700 dark:text-slate-200">{grade}</span>
                                        <span className="px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-[10px] font-bold text-slate-500">{items.length} file</span>
                                    </div>
                                </button>

                                {isExpanded && (
                                    <div className="border-t border-slate-100 dark:border-slate-800">
                                        {items.map((item) => (
                                            <div key={item.id} className="group flex items-center justify-between p-4 pl-12 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-colors border-b last:border-0 border-slate-50 dark:border-slate-800">
                                                <div className="flex items-center gap-4 overflow-hidden">
                                                    <div className={`p-2 rounded-lg shrink-0 ${
                                                        item.type === 'exam' ? 'bg-blue-100 text-blue-600' : 
                                                        item.type === 'theory' ? 'bg-purple-100 text-purple-600' : 'bg-orange-100 text-orange-600'
                                                    }`}>
                                                        <FileText className="w-5 h-5" />
                                                    </div>
                                                    <div className="min-w-0">
                                                        <h4 className="font-bold text-sm text-slate-800 dark:text-slate-200 truncate">{item.title}</h4>
                                                        <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase">
                                                            <span>{item.config.subject}</span>
                                                            <span>•</span>
                                                            <span>{new Date(item.date).toLocaleDateString('vi-VN')}</span>
                                                            <span>•</span>
                                                            <span className={`
                                                                ${item.type === 'exam' ? 'text-blue-500' : item.type === 'theory' ? 'text-purple-500' : 'text-orange-500'}
                                                            `}>
                                                                {item.type === 'exam' ? 'Đề thi' : item.type === 'theory' ? 'Bài giảng' : 'Polya'}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button 
                                                        onClick={() => onLoad(item)}
                                                        className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-lg flex items-center gap-2 font-bold text-xs"
                                                    >
                                                        <PlayCircle className="w-4 h-4" /> Mở
                                                    </button>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); onDelete(item.id); }}
                                                        className="p-2 bg-white dark:bg-slate-800 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg border border-slate-200 dark:border-slate-700 transition-colors"
                                                        title="Xóa"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

