import React, { useState } from 'react';
import { Folder, FileText, Trash2, Upload, Download, X, ChevronRight, ChevronDown, Search, Database, PlayCircle, Settings, Cloud, RefreshCw, Copy, Check, ExternalLink, HelpCircle } from 'lucide-react';
import { ExportData, ExamConfig } from '../types';

interface BankItem {
  id: string;
  title: string;
  date: number;
  type: 'exam' | 'theory' | 'polya';
  data: any;
  config: ExamConfig;
}

interface QuestionBankProps {
  bank: BankItem[];
  onLoad: (item: BankItem) => void;
  onDelete: (id: string) => void;
  onImport: (file: File) => void;
  onClose: () => void;
  // Cloud Props
  googleScriptUrl: string;
  onSaveConfig: (url: string) => void;
  onSyncUp: () => void;
  onSyncDown: () => void;
  isSyncing: boolean;
}

const GRADES_ORDER = [
  'Lớp 1', 'Lớp 2', 'Lớp 3', 'Lớp 4', 'Lớp 5',
  'Lớp 6', 'Lớp 7', 'Lớp 8', 'Lớp 9', 
  'Lớp 10', 'Lớp 11', 'Lớp 12', 
  'Ôn thi THPT QG', 'Khác'
];

const GAS_CODE = `function doGet(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var rows = sheet.getDataRange().getValues();
  var data = [];
  // Bỏ qua header row
  for (var i = 1; i < rows.length; i++) {
    try {
      if (rows[i][5]) { // Column F chứa JSON
         var item = JSON.parse(rows[i][5]);
         data.push(item);
      }
    } catch (err) {}
  }
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(["ID", "Title", "Grade", "Type", "Date", "Data"]);
  }
  var items = JSON.parse(e.postData.contents);
  if (!Array.isArray(items)) items = [items];

  // Xóa dữ liệu cũ (đơn giản hóa cho demo) hoặc append
  // Ở đây ta sẽ append những cái mới

  items.forEach(function(item) {
    sheet.appendRow([
      item.id, 
      item.title, 
      item.config.grade, 
      item.type, 
      new Date(item.date).toISOString(), 
      JSON.stringify(item)
    ]);
  });

  return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
}`;

const QuestionBank: React.FC<QuestionBankProps> = ({ 
  bank, onLoad, onDelete, onImport, onClose,
  googleScriptUrl, onSaveConfig, onSyncUp, onSyncDown, isSyncing 
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set(GRADES_ORDER));
  const [searchTerm, setSearchTerm] = useState('');
  const [showSettings, setShowSettings] = useState(false);
  const [tempUrl, setTempUrl] = useState(googleScriptUrl);
  const [copiedCode, setCopiedCode] = useState(false);

  // Group items by grade
  const groupedBank = bank.reduce((acc, item) => {
    const grade = item.config.grade || 'Khác';
    if (!acc[grade]) acc[grade] = [];
    acc[grade].push(item);
    return acc;
  }, {} as Record<string, BankItem[]>);

  // Toggle Folder
  const toggleGrade = (grade: string) => {
    const newSet = new Set(expandedGrades);
    if (newSet.has(grade)) newSet.delete(grade);
    else newSet.add(grade);
    setExpandedGrades(newSet);
  };

  const handleExportBank = () => {
