                        </div>
                    ) : (
                        <div className="space-y-4">
                            {filteredGrades.map((grade) => {
                                const items = groupedBank[grade].filter(i => !searchTerm || i.title.toLowerCase().includes(searchTerm.toLowerCase()));
                                if (items.length === 0) return null;

                                const isExpanded = expandedGrades.has(grade);

                                return (
                                    <div key={grade} className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                                        <button 
                                            onClick={() => toggleGrade(grade)}
                                            className="w-full flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-left"
                                        >
                                            <div className="flex items-center gap-3">
                                                {isExpanded ? <ChevronDown className="w-5 h-5 text-slate-400" /> : <ChevronRight className="w-5 h-5 text-slate-400" />}
                                                <Folder className="w-6 h-6 text-yellow-500 fill-yellow-100 dark:fill-yellow-900/20" />
                                                <span className="font-black text-slate-700 dark:text-slate-200">{grade}</span>
                                                <span className="px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-[10px] font-bold text-slate-500">{items.length} file</span>
                                            </div>
                                        </button>

                                        {isExpanded && (
                                            <div className="border-t border-slate-100 dark:border-slate-800">
                                                {items.map((item) => (
                                                    <div key={item.id} className="group flex items-center justify-between p-4 pl-12 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-colors border-b last:border-0 border-slate-50 dark:border-slate-800">
                                                        <div className="flex items-center gap-4 overflow-hidden">
                                                            <div className={`p-2 rounded-lg shrink-0 ${
                                                                item.type === 'exam' ? 'bg-blue-100 text-blue-600' : 
                                                                item.type === 'theory' ? 'bg-purple-100 text-purple-600' : 'bg-orange-100 text-orange-600'
                                                            }`}>
                                                                <FileText className="w-5 h-5" />
                                                            </div>
                                                            <div className="min-w-0">
                                                                <h4 className="font-bold text-sm text-slate-800 dark:text-slate-200 truncate">{item.title}</h4>
                                                                <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase">
                                                                    <span>{item.config.subject}</span>
                                                                    <span>•</span>
                                                                    <span>{new Date(item.date).toLocaleDateString('vi-VN')}</span>
                                                                    <span>•</span>
                                                                    <span className={`
                                                                        ${item.type === 'exam' ? 'text-blue-500' : item.type === 'theory' ? 'text-purple-500' : 'text-orange-500'}
                                                                    `}>
                                                                        {item.type === 'exam' ? 'Đề thi' : item.type === 'theory' ? 'Bài giảng' : 'Polya'}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>

                                                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                            <button 
                                                                onClick={() => onLoad(item)}
                                                                className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-lg flex items-center gap-2 font-bold text-xs"
                                                            >
                                                                <PlayCircle className="w-4 h-4" /> Mở
                                                            </button>
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); onDelete(item.id); }}
                                                                className="p-2 bg-white dark:bg-slate-800 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg border border-slate-200 dark:border-slate-700 transition-colors"
                                                                title="Xóa"
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </>
        )}
      </div>
    </div>
  );
};

export default QuestionBank;

import React, { useState, useEffect } from 'react';
import { ExamConfig, ExamMatrix, StudyGuideData, ExportData, PolyaData } from './types';
import { generateExam, generateStudyGuide, generatePolyaSolution } from './services/geminiService';
import ConfigForm from './components/ConfigForm';
import { ExamPreview } from './components/ExamPreview';
import StudyGuidePreview from './components/StudyGuidePreview';
import PolyaPreview from './components/PolyaPreview';
import LessonEditor from './components/LessonEditor';
import QuestionBank from './components/QuestionBank'; // Import new component
import { 
  GraduationCap, Loader2, Moon, Sun, AlertTriangle, 
  User, School, Download, Keyboard, X, Info, 
  Sparkles, Zap, BookOpen, LayoutDashboard, ArrowRight,
  FileText, Presentation, Table2, ShieldCheck, ChevronRight,
  Footprints, HelpCircle, FileCode, CheckSquare, MessageSquare, Copy, Check, PenTool, Database
} from 'lucide-react';

type AppStep = 'landing' | 'dashboard' | 'config' | 'preview' | 'editor';

// Interface for Bank Item
interface BankItem {
  id: string;
  title: string;
  date: number;
  type: 'exam' | 'theory' | 'polya';
  data: any;
  config: ExamConfig;
}

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ExamConfig | null>(null);
  const [role, setRole] = useState<'teacher' | 'student' | null>(null);
  const [selectedMode, setSelectedMode] = useState<'exam' | 'matrix' | 'theory' | 'polya' | null>(null);
  const [showUserGuide, setShowUserGuide] = useState(false);
  const [showQuestionBank, setShowQuestionBank] = useState(false); // State for Bank Modal
  const [bank, setBank] = useState<BankItem[]>([]); // Bank Data State
  const [googleScriptUrl, setGoogleScriptUrl] = useState<string>(''); // Cloud URL
  const [isSyncing, setIsSyncing] = useState(false);

  const [guideTab, setGuideTab] = useState<'general' | 'shortcuts' | 'templates' | 'faq' | 'prompts'>('general');
  const [copiedPrompt, setCopiedPrompt] = useState<string | null>(null);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('theme');
        if (saved) return saved === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
      }
    } catch (e) {}
    return false;
  });

  // Load Bank and Settings from Local Storage on Mount
  useEffect(() => {
    try {
      const savedBank = localStorage.getItem('ai_studio_bank');
      if (savedBank) {
        setBank(JSON.parse(savedBank));
      }
      const savedUrl = localStorage.getItem('ai_studio_gas_url');
      if (savedUrl) {
        setGoogleScriptUrl(savedUrl);
      }
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Save Bank to Local Storage whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem('ai_studio_bank', JSON.stringify(bank));
    } catch (e) {
      console.error("Failed to save bank to storage", e);
      alert("Cảnh báo: Bộ nhớ trình duyệt đã đầy. Một số bài học có thể không được lưu. Hãy xóa bớt bài cũ hoặc đồng bộ lên Google Sheet.");
    }
  }, [bank]);

  // Save Config URL
  const handleSaveConfig = (url: string) => {
    setGoogleScriptUrl(url);
    localStorage.setItem('ai_studio_gas_url', url);
    alert("Đã lưu địa chỉ kết nối Google Sheet.");
  };

  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      html.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const [examData, setExamData] = useState<ExamMatrix | null>(null);
  const [studyGuideData, setStudyGuideData] = useState<StudyGuideData | null>(null);
  const [polyaData, setPolyaData] = useState<PolyaData | null>(null);
  const [error, setError] = useState<string | null>(null);

  // --- Bank Functions ---
  const handleSaveToBank = () => {
    if (!config) return;

    let currentData;
    let type: 'exam' | 'theory' | 'polya' = 'exam';

    if (config.mode === 'theory') {
        currentData = studyGuideData;
        type = 'theory';
    } else if (config.mode === 'polya') {
        currentData = polyaData;
        type = 'polya';
    } else {
        currentData = examData;
        type = 'exam';
    }

    if (!currentData) return;

    // Check size roughly
    const jsonString = JSON.stringify(currentData);
    if (jsonString.length > 3000000) { // ~3MB warning
        if (!confirm("Bài học này có dung lượng lớn (có thể do chứa nhiều ảnh). Việc lưu có thể làm đầy bộ nhớ trình duyệt. Bạn có muốn tiếp tục?")) return;
    }

    const newItem: BankItem = {
        id: Date.now().toString(),
        title: config.topic,
        date: Date.now(),
        type: type,
        data: currentData,
        config: config
    };

    setBank(prev => [newItem, ...prev]);
    alert("Đã lưu vào Ngân hàng bài học (trên máy) thành công!");
  };

  const handleDeleteFromBank = (id: string) => {
    if (confirm("Bạn có chắc chắn muốn xóa bài này khỏi ngân hàng?")) {
        setBank(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleLoadFromBank = (item: BankItem) => {
    setConfig(item.config);
    if (item.type === 'theory') {
        setStudyGuideData(item.data);
        setExamData(null);
        setPolyaData(null);
    } else if (item.type === 'polya') {
        setPolyaData(item.data);
        setExamData(null);
        setStudyGuideData(null);
    } else {
        setExamData(item.data);
        setStudyGuideData(null);
        setPolyaData(null);
    }
    setRole('teacher');
    setShowQuestionBank(false);
    setStep('preview');
  };

  const handleImportBank = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const jsonStr = e.target?.result as string;
            const imported = JSON.parse(jsonStr);
            if (Array.isArray(imported)) {
                setBank(prev => [...imported, ...prev]);
                alert(`Đã nhập ${imported.length} bài vào ngân hàng.`);
            } else {
                alert("File không đúng định dạng ngân hàng.");
            }
        } catch (err) {
            alert("Lỗi đọc file.");
        }
    };
    reader.readAsText(file);
  };

  // --- Cloud Sync Functions ---
  const handleSyncUp = async () => {
    if (!googleScriptUrl) {
        alert("Vui lòng cấu hình URL Google Web App trong phần Cài đặt của Ngân hàng.");
        return;
    }
    setIsSyncing(true);
    try {
        await fetch(googleScriptUrl, {
            method: 'POST',
            mode: 'no-cors', // Google Apps Script Web App simple trigger often requires no-cors for opacity, but implies we can't read response easily.
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(bank)
        });
        // Note: with no-cors we can't check status 200, assuming success if no network error.
        alert("Đã gửi yêu cầu đồng bộ lên Google Sheet. Dữ liệu sẽ sớm xuất hiện trên Sheet.");
    } catch (e) {
        console.error(e);
        alert("Lỗi kết nối đến Google Sheet. Kiểm tra lại URL và mạng.");
    } finally {
        setIsSyncing(false);
    }
  };

  const handleSyncDown = async () => {
    if (!googleScriptUrl) {
        alert("Vui lòng cấu hình URL Google Web App trong phần Cài đặt của Ngân hàng.");
        return;
    }
    setIsSyncing(true);
    try {
        const response = await fetch(googleScriptUrl);
        const data = await response.json();
        if (Array.isArray(data)) {
            // Merge strategy: Add items that don't exist by ID?
            // For simplicity, let's append new items
            const currentIds = new Set(bank.map(b => b.id));
            const newItems = data.filter((item: BankItem) => !currentIds.has(item.id));

            if (newItems.length > 0) {
                setBank(prev => [...newItems, ...prev]);
                alert(`Đã tải về ${newItems.length} bài học mới từ Google Sheet.`);
            } else {
                alert("Dữ liệu trên máy đã cập nhật mới nhất so với Sheet.");
            }
        } else {
            alert("Dữ liệu từ Sheet không đúng định dạng.");
        }
    } catch (e) {
        console.error(e);
        alert("Lỗi tải dữ liệu từ Google Sheet. Hãy chắc chắn bạn đã triển khai Web App với quyền 'Anyone'.");
    } finally {
        setIsSyncing(false);
    }
  };
  // --- End Cloud Sync ---

  const handleGenerate = async (newConfig: ExamConfig) => {
    setLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      if (newConfig.mode === 'theory') {
        const data = await generateStudyGuide(newConfig);
        setStudyGuideData(data);
        setExamData(null);
        setPolyaData(null);
      } else if (newConfig.mode === 'polya') {
        const data = await generatePolyaSolution(newConfig);
        setPolyaData(data);
        setExamData(null);
        setStudyGuideData(null);
      } else {
        const data = await generateExam(newConfig);
        setExamData(data);
        setStudyGuideData(null);
        setPolyaData(null);
      }
      setStep('preview');
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Lỗi hệ thống AI. Vui lòng thử lại sau.");
    } finally {
      setLoading(false);
    }
  };

  const handleModeSelection = (mode: 'exam' | 'matrix' | 'theory' | 'polya') => {
    setSelectedMode(mode);
    setStep('config');
  };

  const handleReset = () => {
    setStep('landing');
    setRole(null);
    setSelectedMode(null);
    setExamData(null);
    setStudyGuideData(null);
    setPolyaData(null);
    setError(null);
  };

