];

const GAS_CODE = `function doGet(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var rows = sheet.getDataRange().getValues();
  var data = [];
  // Bỏ qua header row
  for (var i = 1; i < rows.length; i++) {
    try {
      if (rows[i][5]) { // Column F chứa JSON
         var item = JSON.parse(rows[i][5]);
         data.push(item);
      }
    } catch (err) {}
  }
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(["ID", "Title", "Grade", "Type", "Date", "Data"]);
  }
  var items = JSON.parse(e.postData.contents);
  if (!Array.isArray(items)) items = [items];

  // Xóa dữ liệu cũ (đơn giản hóa cho demo) hoặc append
  // Ở đây ta sẽ append những cái mới

  items.forEach(function(item) {
    sheet.appendRow([
      item.id, 
      item.title, 
      item.config.grade, 
      item.type, 
      new Date(item.date).toISOString(), 
      JSON.stringify(item)
    ]);
  });

  return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
}`;

