import React, { useEffect, useRef, useState } from 'react';
import { ChevronDown, Hand } from 'lucide-react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
  highlightClass?: string;
}

declare global {
  interface Window {
    MathJax: any;
  }
}

// Mảng màu sắc rực rỡ để random cho công thức toán
const MATH_COLORS = [
  'text-cyan-600 dark:text-cyan-400',
  'text-fuchsia-600 dark:text-fuchsia-400',
  'text-lime-600 dark:text-lime-400',
  'text-orange-600 dark:text-orange-400',
  'text-sky-600 dark:text-sky-400',
  'text-rose-600 dark:text-rose-400',
  'text-violet-600 dark:text-violet-400'
];

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false, highlightClass = "" }) => {
  const containerRef = useRef<HTMLElement>(null);

  // Ensure content is safe
  const safeContent = content || "";

  // Tách nội dung theo dòng mới (\n)
  // Nếu inline=true, ta không tách dòng mà render liền mạch.
  // Nếu inline=false, ta tách dòng để hỗ trợ tính năng "Click to reveal".
  const lines = (!inline && safeContent.includes('\n')) 
    ? safeContent.split('\n').filter(line => line.trim() !== '') 
    : [safeContent];

  // State quản lý số dòng đang hiển thị
  // Nếu có nhiều dòng và không phải inline, bắt đầu hiển thị 1 dòng.
  const [visibleLines, setVisibleLines] = useState(lines.length > 1 && !inline ? 1 : lines.length);

  // Reset khi nội dung thay đổi
  useEffect(() => {
    setVisibleLines(lines.length > 1 && !inline ? 1 : lines.length);
  }, [content, inline]);

  const handleReveal = (e: React.MouseEvent) => {
    if (inline || lines.length <= 1) return;
    e.stopPropagation(); // Ngăn chặn sự kiện click lan ra ngoài nếu cần
    if (visibleLines < lines.length) {
      setVisibleLines(prev => prev + 1);
    }
  };

  // Chọn màu dựa trên độ dài nội dung để cố định màu cho mỗi công thức (tránh flicker khi re-render)
  const getColorClass = (text: string) => {
    if (highlightClass) return highlightClass;
    const index = text.length % MATH_COLORS.length;
    return MATH_COLORS[index];
  };

  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          // Clear typeset cũ
          if (window.MathJax.typesetClear) {
            window.MathJax.typesetClear([containerRef.current]);
          }
          // Typeset lại
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    // Gọi renderMath mỗi khi content thay đổi HOẶC số dòng hiển thị thay đổi
    // setTimeout để đảm bảo DOM đã update dòng mới trước khi MathJax chạy
    const timer = setTimeout(() => {
        renderMath();
    }, 10);
    return () => clearTimeout(timer);
  }, [safeContent, visibleLines]);

  const processContent = (text: string) => {
    if (!text) return null;

    // Tách phần text thường và công thức toán (trong $...$)
    const parts = text.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        // Bold markdown
        return (
          <strong key={index} className="font-black text-indigo-700 dark:text-indigo-300">
            {part.slice(2, -2)}
          </strong>
        );
      } else if (part.startsWith('$') && part.endsWith('$')) {
        // Math formula
        const colorClass = getColorClass(part);
        return (
          <span key={index} className={`font-bold ${colorClass} mx-1`}>
            {part}
          </span>
        );
      }
      return <span key={index}>{part}</span>;
    });
  };

  const contentKey = `math-${safeContent.length}-${safeContent.substring(0, 10)}`;

  if (inline) {
    return (
      <span 
        key={contentKey}
        ref={containerRef as React.RefObject<HTMLSpanElement>} 
        className="math-renderer inline-block align-middle whitespace-pre-wrap tex2jax_process"
      >
        {processContent(safeContent.replace(/\\n/g, ' '))}
      </span>
    );
  }

  // Chế độ Block (hỗ trợ Click-to-reveal)
  return (
    <div 
      key={contentKey}
      ref={containerRef as React.RefObject<HTMLDivElement>} 
      className={`math-renderer block my-2 whitespace-pre-wrap tex2jax_process transition-all ${lines.length > 1 ? 'cursor-pointer hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl p-2 -mx-2' : ''}`}
      onClick={handleReveal}
      title={visibleLines < lines.length ? "Click để hiện dòng tiếp theo" : ""}
    >
      {lines.map((line, index) => {
         // Chỉ render những dòng được phép hiển thị
         if (index >= visibleLines) return null;

         return (
            <div key={index} className={`mb-2 last:mb-0 animate-fade-in ${index === visibleLines - 1 && index > 0 ? 'bg-indigo-50/50 dark:bg-indigo-900/10 rounded-lg px-2 -mx-2' : ''}`}>
                {processContent(line)}
            </div>
         );
      })}

      {/* Chỉ báo còn nội dung ẩn */}
      {visibleLines < lines.length && (
         <div className="flex justify-center mt-2 animate-bounce">
            <div className="bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-300 px-3 py-1 rounded-full text-[0.6em] font-bold uppercase tracking-widest flex items-center gap-1 shadow-sm">
                <Hand className="w-3 h-3" /> Click để xem tiếp ({lines.length - visibleLines} dòng) <ChevronDown className="w-3 h-3" />
            </div>
         </div>
      )}
    </div>
  );
};

export default MathRenderer;

