import React, { useEffect, useRef, useState } from 'react';

interface MathRendererProps {
  content: string;
  inline?: boolean;
  highlightClass?: string;
  className?: string; // Added className prop for flexibility
  palette?: 'default' | 'contrast'; // New prop for color mode
}

declare global {
  interface Window {
    MathJax: any;
  }
}

// Mảng màu sắc rực rỡ mặc định (Cầu vồng)
const MATH_COLORS = [
  'text-cyan-600 dark:text-cyan-400',
  'text-fuchsia-600 dark:text-fuchsia-400',
  'text-lime-600 dark:text-lime-400',
  'text-orange-600 dark:text-orange-400',
  'text-sky-600 dark:text-sky-400',
  'text-rose-600 dark:text-rose-400',
  'text-violet-600 dark:text-violet-400'
];

// Mảng 3 màu cơ bản tương phản cao cho chế độ trình chiếu tối (Vàng, Xanh Cyan, Xanh Lá Neon)
const CONTRAST_COLORS = [
  'text-yellow-600 dark:text-yellow-300', // Vàng tươi
  'text-cyan-600 dark:text-cyan-300',     // Xanh ngọc sáng
  'text-green-600 dark:text-green-300'     // Xanh lá neon
];

const MathRenderer: React.FC<MathRendererProps> = ({ content, inline = false, highlightClass = "", className = "", palette = 'default' }) => {
  const containerRef = useRef<HTMLElement>(null);

  // Ensure content is safe
  const safeContent = content || "";

  // Tách nội dung theo dòng mới (\n)
  const lines = (!inline && safeContent.includes('\n')) 
    ? safeContent.split('\n').filter(line => line.trim() !== '') 
    : [safeContent];

  // State quản lý số dòng đang hiển thị
  const [visibleLines, setVisibleLines] = useState(lines.length > 1 && !inline ? 1 : lines.length);

  // Reset khi nội dung thay đổi
  useEffect(() => {
    setVisibleLines(lines.length > 1 && !inline ? 1 : lines.length);
  }, [content, inline]);

  const handleReveal = (e: React.MouseEvent) => {
    if (inline || lines.length <= 1) return;
    e.stopPropagation(); 
    if (visibleLines < lines.length) {
      setVisibleLines(prev => prev + 1);
    }
  };

  const getColorClass = (text: string) => {
    if (highlightClass) return highlightClass;

    // Chọn bảng màu dựa trên props
    const colorPalette = palette === 'contrast' ? CONTRAST_COLORS : MATH_COLORS;
    const index = text.length % colorPalette.length;
    return colorPalette[index];
  };

  useEffect(() => {
    const renderMath = async () => {
      if (typeof window !== 'undefined' && window.MathJax && containerRef.current) {
        try {
          if (window.MathJax.typesetClear) {
            window.MathJax.typesetClear([containerRef.current]);
          }
          if (window.MathJax.typesetPromise) {
            await window.MathJax.typesetPromise([containerRef.current]);
          }
        } catch (err) {
          console.warn('MathJax rendering failed:', err);
        }
      }
    };
    const timer = setTimeout(() => {
        renderMath();
    }, 10);
    return () => clearTimeout(timer);
  }, [safeContent, visibleLines, palette]); // Re-render when palette changes

  const processContent = (text: string) => {
    if (!text) return null;
    const parts = text.split(/(\$[^$]+\$|\*\*[^*]+\*\*)/g);

    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return (
          <strong key={index} className="font-black text-indigo-700 dark:text-indigo-300">
            {part.slice(2, -2)}
          </strong>
        );
      } else if (part.startsWith('$') && part.endsWith('$')) {
        const colorClass = getColorClass(part);
        return (
          <span key={index} className={`font-bold ${colorClass} mx-1 transition-colors duration-300`}>
            {part}
          </span>
        );
      }
      return <span key={index}>{part}</span>;
    });
  };

  const contentKey = `math-${safeContent.length}-${safeContent.substring(0, 10)}`;

  if (inline) {
    return (
      <span 
        key={contentKey}
        ref={containerRef as React.RefObject<HTMLSpanElement>} 
        className={`math-renderer inline-block align-middle whitespace-pre-wrap tex2jax_process ${className}`}
      >
        {processContent(safeContent.replace(/\\n/g, ' '))}
      </span>
    );
  }

  // Chế độ Block (hỗ trợ Click-to-reveal)
  return (
    <div 
      key={contentKey}
      ref={containerRef as React.RefObject<HTMLDivElement>} 
      className={`math-renderer block my-2 whitespace-pre-wrap tex2jax_process transition-all w-full ${lines.length > 1 ? 'cursor-pointer min-h-full' : ''} ${className}`}
      onClick={handleReveal}
      title={visibleLines < lines.length ? "Click để hiện dòng tiếp theo" : ""}
    >
      {lines.map((line, index) => {
         if (index >= visibleLines) return null;

         return (
            <div key={index} className={`mb-3 last:mb-0 animate-fade-in ${index === visibleLines - 1 && index > 0 ? 'bg-indigo-50/50 dark:bg-indigo-900/10 rounded-lg px-2 -mx-2 py-1' : ''}`}>
                {processContent(line)}
            </div>
         );
      })}
    </div>
  );
};

export default MathRenderer;

