      if (isDraggingVerticalRef.current) {
        isDraggingVerticalRef.current = false;
        document.body.style.cursor = 'default';
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const startResizeWeb = () => {
    isDraggingWebRef.current = true;
    document.body.style.cursor = 'col-resize';
    const iframe = document.getElementById('web-view-iframe');
    if (iframe) iframe.style.pointerEvents = 'none';
  };

  const startResizeVertical = () => {
    isDraggingVerticalRef.current = true;
    document.body.style.cursor = 'row-resize';
  };

  const playTick = (freq = 800, type: 'tick' | 'alarm' = 'tick') => {
    try {
      const ctx = initAudio();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      const now = ctx.currentTime;

      if (type === 'alarm') {
        // Âm thanh báo động 3s cuối (Cao độ, ngắt quãng rõ)
        osc.type = 'square';
        osc.frequency.setValueAtTime(1500, now);
        osc.frequency.linearRampToValueAtTime(1200, now + 0.1);

        gain.gain.setValueAtTime(0.2, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);

        osc.start(now);
        osc.stop(now + 0.15);
      } else {
        // Tiếng tick bình thường
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, now);
        osc.frequency.exponentialRampToValueAtTime(freq * 0.5, now + 0.1);

        gain.gain.setValueAtTime(0.15, now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.1);

        osc.start(now);
        osc.stop(now + 0.1);
      }
    } catch (e) {
      console.warn("Audio error", e);
    }
  };

  const playFeedback = (isCorrect: boolean) => {
    try {
        const ctx = initAudio();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        const now = ctx.currentTime;

        if (isCorrect) {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(500, now);
            osc.frequency.exponentialRampToValueAtTime(1000, now + 0.1);
            osc.frequency.exponentialRampToValueAtTime(1500, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0.3, now + 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);

            osc.start(now);
            osc.stop(now + 0.6);
        } else {
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(150, now);
            osc.frequency.linearRampToValueAtTime(100, now + 0.3);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);

            osc.start(now);
            osc.stop(now + 0.3);
        }
    } catch (e) {
        console.warn("Audio error", e);
    }
  };

  const getCorrectIndex = (q: Question) => {
    const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
    const index = ['A', 'B', 'C', 'D'].indexOf(correctLetter);
    return index !== -1 ? index : 0; 
  };

  useEffect(() => {
    let interval: any;
    if (isTimerRunning && timer !== null && timer > 0) {
      interval = setInterval(() => {
        setTimer(prev => {
          if (prev === null || prev <= 0) {
            setIsTimerRunning(false);
            return 0;
          }
          const next = prev - 1;

          // Logic âm thanh mới: 
          // 3 giây cuối (3, 2, 1): Tiếng báo động lớn
          // Dưới 10 giây (10-4): Tiếng tick dồn dập
          if (next <= 3 && next > 0) {
             playTick(1500, 'alarm');
          } else if (next <= 10 && next > 3) {
             playTick(next % 2 === 0 ? 1000 : 800, 'tick');
          }

          return next;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isTimerRunning, timer !== null]);

  useEffect(() => {
    setTimer(null);
    setIsTimerRunning(false);
  }, [currentSlide]);

  useEffect(() => {
    if (userAnswers[currentSlide] !== undefined && isTimerRunning) {
      setTimer(null);
      setIsTimerRunning(false);
    }
  }, [userAnswers[currentSlide]]);

  useEffect(() => {
    if (!isStarted) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();

      if (['1', '2', '3', '4', '5'].includes(key)) {
        const minutes = parseInt(key);
        setTimer(minutes * 60);
        setIsTimerRunning(true);
      }

      if (key === 'a' && role === 'teacher') setShowAnswersGlobal(prev => !prev);
      if (key === 'w') setShowWebView(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 's') handleExport();
      if (key === 'h' && viewMode === 'slide' && currentSlide >= 0) toggleRevealHint(currentSlide);
      if (key === 'h' && e.altKey) setShowToolbar(prev => !prev); 
      if (key === 'v') readAloud();
      if (key === '=' || key === '+') handleZoomIn();
      if (key === '-' || key === '_') handleZoomOut();
      if (key === 'l') setOptionLayout(prev => (prev === 'grid' ? 'stack' : 'grid'));
      if (viewMode === 'slide' && questions.length > 0) {
        if (e.key === 'ArrowRight') setCurrentSlide(s => Math.min(questions.length-1, s+1));
        if (e.key === 'ArrowLeft') setCurrentSlide(s => Math.max(-1, s-1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isStarted, role, viewMode, questions.length, currentSlide]);

  useEffect(() => {
    if (viewMode === 'slide' && !showAnswersGlobal && !isSubmitted) {
      setRevealedAnswers(new Set());
      setRevealedHints(new Set());
    }
  }, [currentSlide, viewMode, isSubmitted]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleWordExportEquation = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'equation');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word Equation. Vui lòng thử lại.");
    }
  };

  const handleWordExportLatex = async () => {
    try {
      await exportExamToWord(data, config.subject as string, config.grade, 'latex');
    } catch (e) {
      console.error(e);
      alert("Lỗi xuất Word LaTeX. Vui lòng thử lại.");
    }
  };

  const readAloud = () => {
    if (currentSlide < 0 || !questions[currentSlide]) return;
    const q = questions[currentSlide];
    let textToRead = q.content.replace(/\$([^$]+)\$/g, (match, formula) => {
        const cleanFormula = formula.trim();
        return cleanFormula.length < 6 ? cleanFormula : "[công thức]"; 
    });

    textToRead = textToRead.replace(/\*\*/g, "");

    const utterance = new SpeechSynthesisUtterance(textToRead);
    utterance.lang = 'vi-VN';
    utterance.rate = 0.95;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(utterance);
  };

  const calculateScore = () => {
    let rawScore = 0;
    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      if (userAns === undefined) return;
      if (q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) {
        const correctLetter = q.correctAnswer.trim().charAt(0).toUpperCase();
        if (['A', 'B', 'C', 'D'][userAns] === correctLetter) rawScore += 1;
      } else if (q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) {
        const correctStr = q.correctAnswer.toLowerCase();
        let subCorrect = 0;
        [0, 1, 2, 3].forEach(i => {
           const label = ['a', 'b', 'c', 'd'][i];
           const isCorrectTrue = correctStr.includes(`${label}: đúng`) || correctStr.includes(`${label}: đ`);
           if (userAnswers[idx]?.[i] === isCorrectTrue) subCorrect++;
        });
        if (subCorrect === 4) rawScore += 1;
      } else if (q.type === QuestionType.ESSAY || q.type.includes('Tự luận')) {
        if (userAns.toString().trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) rawScore += 1;
      }
    });
    return ((rawScore / questions.length) * 10).toFixed(1);
  };

  const handleZoomIn = () => setZoomLevel(prev => Math.min(prev + 0.1, 8.0));
  const handleZoomOut = () => setZoomLevel(prev => Math.max(prev - 0.1, 0.5));

  const toggleRevealAnswer = (idx: number) => setRevealedAnswers(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });
  const toggleRevealHint = (idx: number) => setRevealedHints(prev => {
    const n = new Set(prev); n.has(idx) ? n.delete(idx) : n.add(idx); return n;
  });

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'exam', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `Exam_${config.topic}.json`; a.click();
  };

  const renderQuestionCard = (q: Question, idx: number, isSlide: boolean) => {
    if (!q) return null;
    const zoomStyle: React.CSSProperties = { 
      fontSize: `${zoomLevel}rem`,
      transition: 'font-size 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
    };
    const userAns = userAnswers[idx];
    const hasChosen = userAns !== undefined;
    const isAnswerVisible = (showAnswersGlobal || isSubmitted || revealedAnswers.has(idx)) && (hasChosen || showAnswersGlobal);
    const isHintVisible = revealedHints.has(idx);

    const correctIndex = getCorrectIndex(q);

    if (isSlide && isAnswerVisible) {
      return (
        <div className="flex flex-col h-full w-full overflow-hidden relative" style={zoomStyle}>
          <div 
            style={{ height: `${verticalSplitRatio}%` }} 
            className="border-b-4 border-emerald-500/30 overflow-y-auto p-6 md:px-12 bg-white dark:bg-zinc-950 shadow-md z-10 shrink-0"
          >
             <div className="flex items-center justify-between mb-4">
               <div className="flex items-center gap-2">
                 <span className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-md flex-shrink-0">{idx + 1}</span>
                 <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-slate-100 dark:bg-zinc-900 text-slate-500 whitespace-nowrap">{q.difficulty}</span>
               </div>
             </div>

             <div className="text-[0.8em] font-bold text-slate-900 dark:text-zinc-100 mb-4 w-full leading-normal">
                <MathRenderer content={q.content} palette={mathPalette} />
             </div>

             <div className="grid gap-2 grid-cols-2">
                 {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => {
                    const isSelected = userAns === oi;
                    const isCorrect = oi === correctIndex;
                    let colorClass = "bg-slate-50 dark:bg-zinc-900 text-slate-600";
                    if (isCorrect) colorClass = "bg-emerald-100 text-emerald-800 font-bold border-emerald-300";
                    else if (isSelected) colorClass = "bg-red-100 text-red-800 border-red-300";

                    return (
                        <div key={oi} className={`p-2 rounded-lg border text-[0.6em] flex items-start gap-2 ${colorClass}`}>
                            <span className="font-black">{['A','B','C','D'][oi]}.</span>
                            <MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline palette={mathPalette} />
                        </div>
                    );
                 })}
             </div>
          </div>

          <div 
            className="h-3 bg-slate-100 dark:bg-zinc-800 hover:bg-indigo-500 dark:hover:bg-indigo-500 cursor-row-resize flex items-center justify-center z-50 transition-colors shadow-sm"
            onMouseDown={startResizeVertical}
          >
            <GripHorizontal className="w-4 h-4 text-slate-400" />
          </div>

          <div 
            style={{ height: `calc(${100 - verticalSplitRatio}% - 12px)` }} 
            className="bg-emerald-50 dark:bg-emerald-900/10 flex flex-col relative animate-fade-in-up"
          >
              <div className="sticky top-0 bg-emerald-50/95 dark:bg-zinc-900/95 py-3 px-6 z-20 flex justify-between items-center border-b border-emerald-200 dark:border-emerald-800/50 shrink-0">
                  <h4 className="text-[0.7em] font-black text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                      <CheckCircle className="w-6 h-6" /> Lời giải chi tiết (Đáp án: {q.correctAnswer})
                  </h4>
                  <button onClick={() => toggleRevealAnswer(idx)} className="p-2 bg-white/50 hover:bg-white rounded-full text-slate-500 hover:text-red-500 transition-colors shadow-sm">
                      <X className="w-5 h-5" />
                  </button>
              </div>

              <div className="flex-grow overflow-y-auto w-full px-6 pb-10">
                  <div className="text-[0.8em] font-medium leading-relaxed dark:text-emerald-100 w-full min-h-[50%]">
                      <MathRenderer content={q.solution} palette={mathPalette} />
                  </div>
              </div>
          </div>
        </div>
      );
    }

    return (
      <div className={`flex flex-col bg-white dark:bg-zinc-950 ${isSlide ? 'pt-2 pb-16 px-6 md:px-12 items-start justify-start w-full overflow-y-auto' : 'p-6 rounded-3xl mb-8 border border-slate-200 dark:border-slate-800 shadow-xl'}`} style={zoomStyle}>
        <div className="w-full flex flex-col items-start">
            <div className="flex items-center justify-between w-full mb-4 no-print border-b border-slate-100 dark:border-zinc-800 pb-2">
                <div className="flex items-center gap-2">
                  <span className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-md flex-shrink-0">{idx + 1}</span>
                  <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-slate-100 dark:bg-zinc-900 text-slate-500 whitespace-nowrap">{q.difficulty}</span>
                  {q.differentiation && (
                    <span className="text-[0.4em] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-amber-50 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300 whitespace-nowrap">
                      {q.differentiation}
                    </span>
                  )}
                  {isSlide && <button onClick={readAloud} className="p-1.5 bg-slate-50 dark:bg-zinc-900 rounded-lg hover:text-indigo-600 transition-colors relative" title="Đọc (V)"><Volume2 className="w-5 h-5" /><ShortcutLabel>V</ShortcutLabel></button>}
                </div>
                {q.hints && q.hints.length > 0 && (
                  <button onClick={() => toggleRevealHint(idx)} className={`p-1.5 rounded-lg transition-all relative ${isHintVisible ? 'bg-amber-100 text-amber-600' : 'bg-slate-50 dark:bg-zinc-900 text-slate-400 dark:text-zinc-500'}`} title="Gợi ý (H)">
                      <Lightbulb className="w-5 h-5" />
                      {isSlide && <ShortcutLabel>H</ShortcutLabel>}
                  </button>
                )}
            </div>

            <div className="text-[1em] font-bold text-slate-900 dark:text-zinc-100 mb-6 w-full leading-normal">
                <MathRenderer content={q.content} palette={mathPalette} />
            </div>

            {isHintVisible && q.hints && q.hints.length > 0 && (
              <div className="w-full mb-6 p-4 bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-300 rounded-r-xl">
                <h5 className="text-amber-700 font-bold text-[0.6em] uppercase mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4" /> Gợi ý:</h5>
                <ul className="space-y-2 pl-4 list-disc">
                  {q.hints.map((hint, hIdx) => (
                    <li key={hIdx} className="text-amber-900 dark:text-amber-100 text-[0.6em] font-semibold"><MathRenderer content={hint} inline palette={mathPalette} /></li>
                  ))}
                </ul>
              </div>
            )}

            <div className={`w-full grid gap-4 ${optionLayout === 'stack' ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2'}`}>
                {(q.type === QuestionType.MULTIPLE_CHOICE || q.type.includes('4 chọn 1')) && q.options?.map((o, oi) => {
                    const isSelected = userAns === oi;
                    let buttonClass = `${OPTION_THEMES[oi].bg} ${OPTION_THEMES[oi].border} hover:border-indigo-400`;
                    let labelClass = `${OPTION_THEMES[oi].labelBg}`;

                    if (isSelected) {
                        const isCorrect = oi === correctIndex;
                        if (isCorrect) {
                            buttonClass = 'bg-emerald-600 border-emerald-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-emerald-600';
                        } else {
                            buttonClass = 'bg-red-600 border-red-600 text-white scale-[1.02] shadow-xl';
                            labelClass = 'bg-white text-red-600';
                        }
                    }

                    return (
                        <button 
                            key={oi} 
                            onClick={() => {
                                if (!isSubmitted) {
                                    setUserAnswers(prev => ({ ...prev, [idx]: oi }));
                                    playFeedback(oi === correctIndex);
                                }
                            }} 
                            className={`group flex items-start gap-4 p-4 rounded-2xl border-2 transition-all text-left ${buttonClass}`}
                        >
                            <span className={`w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center font-bold text-[0.6em] ${labelClass}`}>{['A','B','C','D'][oi]}</span>
                            <div className={`text-[0.8em] pt-0.5 font-bold ${isSelected ? 'text-white' : 'dark:text-zinc-100'}`}><MathRenderer content={o.replace(/^[A-D][\.\)\s]+/, '')} inline palette={mathPalette} /></div>
                        </button>
                    );
                })}

                {(q.type === QuestionType.TRUE_FALSE || q.type.includes('Đúng/Sai')) && q.options?.map((o, oi) => (
                    <div key={oi} className="flex flex-col p-4 bg-slate-50 dark:bg-zinc-900 rounded-2xl border border-slate-200 dark:border-zinc-700">
                        <div className="text-[0.7em] font-bold mb-3 flex gap-2 dark:text-zinc-200"><span className="text-indigo-600 font-black">{['a','b','c','d'][oi]})</span><MathRenderer content={o.replace(/^[a-d][).]\s*/, '')} inline palette={mathPalette} /></div>
                        <div className="flex gap-2">
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: true}}))} className={`flex-1 py-2 rounded-xl font-black text-[0.5em] border transition-all ${userAns?.[oi] === true ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white dark:bg-zinc-800 text-emerald-600 border-emerald-200'}`}>ĐÚNG</button>
                           <button onClick={() => !isSubmitted && setUserAnswers(p => ({...p, [idx]: {...(p[idx]||{}), [oi]: false}}))} className={`flex-1 py-2 rounded-xl font-black text-[0.5em] border transition-all ${userAns?.[oi] === false ? 'bg-red-600 border-red-600 text-white' : 'bg-white dark:bg-zinc-800 text-red-600 border-red-200'}`}>SAI</button>
                        </div>
                    </div>
                ))}
            </div>

            {isAnswerVisible ? (
                <div className="mt-6 p-6 bg-emerald-50 dark:bg-emerald-900/20 rounded-3xl border border-emerald-200 w-full relative animate-fade-in">
                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-2 right-2 p-1 hover:bg-emerald-100 rounded-full no-print"><X className="w-5 h-5 text-emerald-600" /></button>
                    <h4 className="text-[0.7em] font-black text-emerald-700 dark:text-emerald-400 mb-2 flex items-center gap-2"><CheckCircle className="w-6 h-6" /> Đáp án: <MathRenderer content={q.correctAnswer} inline palette={mathPalette} /></h4>
                    <div className="text-[0.6em] font-bold leading-relaxed border-t border-emerald-100 pt-2 dark:text-emerald-100"><MathRenderer content={q.solution} palette={mathPalette} /></div>
                </div>
            ) : hasChosen && (
              <button onClick={() => toggleRevealAnswer(idx)} className="mt-6 w-full py-3 bg-slate-100 dark:bg-zinc-900 rounded-xl border border-dashed border-slate-300 dark:border-zinc-700 flex items-center justify-center gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all text-slate-400 hover:text-indigo-600 no-print">
                  <Eye className="w-5 h-5" />
                  <span className="text-[0.6em] font-black uppercase">Xem Lời giải (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  const renderTitleSlide = () => (
    <div className="flex flex-col items-center justify-center bg-white dark:bg-zinc-950 pt-2 pb-16 px-6 md:px-12 w-full h-full text-center" style={{fontSize: `${zoomLevel}rem`}}>
        <div className="max-w-5xl w-full flex flex-col gap-10">
            {/* Topic Header */}
            <div className="p-12 bg-slate-50 dark:bg-zinc-900 rounded-[4rem] border-8 border-indigo-100 dark:border-zinc-800 shadow-2xl animate-fade-in-up">
                <div className="flex justify-center mb-6">
                    <GraduationCap className="w-[3em] h-[3em] text-indigo-600 dark:text-indigo-400 drop-shadow-xl" />
                </div>
                <h1 className="text-[1.8em] font-black uppercase tracking-tighter text-slate-900 dark:text-white mb-6 leading-none">
                    {config.topic}
                </h1>
                <div className="w-48 h-3 bg-gradient-to-r from-indigo-500 to-violet-500 rounded-full mx-auto mb-8 opacity-80"></div>
                <p className="text-[0.8em] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                    {config.subject} • {config.grade}
                </p>
                <div className="mt-6 flex justify-center gap-4">
                    <span className="px-6 py-2 bg-white dark:bg-black rounded-full border border-slate-200 dark:border-slate-800 text-[0.5em] font-bold text-slate-500 shadow-sm">
                        {questions.length} Câu hỏi
                    </span>
                    <span className="px-6 py-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-full border border-indigo-100 dark:border-indigo-800 text-[0.5em] font-bold text-indigo-600 dark:text-indigo-400 shadow-sm">
                        Chế độ Luyện Tập
                    </span>
                </div>
            </div>

            <div className="flex justify-center">
                <button 
                    onClick={() => setCurrentSlide(0)} 
                    className="px-12 py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-full font-black text-[0.8em] hover:scale-105 active:scale-95 transition-all shadow-2xl animate-bounce"
                >
                    BẮT ĐẦU NGAY
                </button>
            </div>
        </div>
    </div>
  );

  if (!isStarted) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 p-6">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl max-w-lg w-full text-center border-4 border-indigo-100 animate-fade-in-up">
            <School className="w-20 h-20 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-4xl font-black mb-4 dark:text-white uppercase tracking-tighter leading-none">{config.topic}</h2>
            <p className="text-xl text-slate-500 font-bold mb-10 italic">{config.subject} - {config.grade}</p>
            <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="Nhập tên..." className="w-full p-6 rounded-2xl bg-slate-100 dark:bg-slate-900 text-center text-2xl font-black mb-8 border-2 border-transparent focus:border-indigo-600 outline-none" />
            <button onClick={() => { setIsStarted(true); if(role === 'student') setViewMode('list'); }} disabled={!studentName.trim()} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl shadow-xl disabled:opacity-50 hover:bg-indigo-700 active:scale-95 transition-all uppercase">VÀO LÀM BÀI</button>
        </div>
    </div>
  );

  if (!questions || questions.length === 0) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
            <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700">
                <p className="text-red-500 font-bold mb-4">Không tìm thấy dữ liệu câu hỏi.</p>
                <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors">Quay lại</button>
            </div>
        </div>
    );
  }

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
        {/* Compact Header */}
        <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 sticky top-0 z-50 px-2 h-10 flex justify-between items-center no-print shadow-sm">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg" title="Home"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
                <h1 className="text-xs font-black truncate max-w-[150px] dark:text-zinc-200 uppercase">{config.topic}</h1>
            </div>
            <div className="flex items-center gap-1">
                {onEdit && (
                  <button onClick={onEdit} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-lg mr-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20" title="Chỉnh sửa">
                    <PenTool className="w-4 h-4" />
                  </button>
                )}
                {onSaveToBank && (
                  <button onClick={onSaveToBank} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 rounded-lg mr-2 hover:bg-emerald-50 dark:hover:bg-emerald-900/20" title="Lưu vào Ngân hàng">
                    <Database className="w-4 h-4" />
                  </button>
                )}
                <div className="flex gap-1 mr-2">
                    <button onClick={handleWordExportEquation} className="p-1 bg-emerald-600 text-white rounded-md hover:bg-emerald-700" title="Word Equation"><FileOutput className="w-3.5 h-3.5" /></button>
                    <button onClick={handleWordExportLatex} className="p-1 bg-amber-600 text-white rounded-md hover:bg-amber-700" title="Word Latex"><FileOutput className="w-3.5 h-3.5" /></button>
                </div>
                <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative" title="Save"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
                <div className="flex bg-slate-100 dark:bg-zinc-900 rounded-lg p-0.5">
                    <button onClick={() => { setViewMode('list'); setCurrentSlide(0); }} className={`p-1 rounded-md ${viewMode === 'list' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><ListChecks className="w-3.5 h-3.5"/></button>
                    <button onClick={() => { setViewMode('slide'); setCurrentSlide(-1); }} className={`p-1 rounded-md ${viewMode === 'slide' ? 'bg-white dark:bg-zinc-800 shadow text-indigo-600' : 'text-slate-400'}`}><MonitorPlay className="w-3.5 h-3.5"/></button>
                </div>
                <button onClick={() => setOptionLayout(prev => (prev === 'grid' ? 'stack' : 'grid'))} className={`p-1.5 rounded-lg relative ${optionLayout === 'stack' ? 'text-amber-600 bg-amber-50 dark:bg-zinc-800' : 'text-slate-400'}`} title="Chế độ xuống dòng">
                  <ListChecks className="w-4 h-4" />
                  <ShortcutLabel>L</ShortcutLabel>
                </button>
                {role === 'teacher' && <button onClick={() => setShowAnswersGlobal(!showAnswersGlobal)} className={`p-1.5 rounded-lg relative ${showAnswersGlobal ? 'text-indigo-600 bg-indigo-50 dark:bg-zinc-800' : 'text-slate-400'}`} title="Show Answers"><Eye className="w-4 h-4" /><ShortcutLabel>A</ShortcutLabel></button>}
                {!isSubmitted && <button onClick={() => { setIsSubmitted(true); setShowScoreModal(true); setIsTimerRunning(false); }} className="px-2.5 py-1 bg-emerald-600 text-white font-black rounded-lg text-[10px] hover:bg-emerald-700">NỘP</button>}
                <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 text-slate-600 dark:text-slate-300" title="Fullscreen">{isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}</button>
            </div>
        </header>

        {/* Main Content Area - Split Screen */}
        <div className="flex flex-grow relative overflow-hidden">
            <main 
                className={`flex flex-col relative transition-all duration-0 ${viewMode === 'slide' ? '' : 'p-4 md:p-8'} `}
                style={{ 
                    width: showWebView ? `${webSplitRatio}%` : '100%',
                    maxWidth: showWebView ? 'none' : '',
                }}
            >
                <div className={`transition-all duration-500 h-full flex flex-col ${!showWebView && viewMode !== 'slide' ? 'max-w-5xl mx-auto w-full' : 'w-full'}`}>
                    {viewMode === 'list' 
                      ? (
                        <>
                          {renderExamMeta(false)}
                          {questions.map((q, i) => renderQuestionCard(q, i, false))}
                        </>
                      )
                      : (currentSlide === -1 ? renderTitleSlide() : renderQuestionCard(questions[currentSlide], currentSlide, true))
                    }

                    {/* Timer Display Bottom Left - HUGE SIZE */}
                    {viewMode === 'slide' && timer !== null && (
                      <div className="fixed bottom-8 left-8 z-[200] pointer-events-none">
                        <div className={`px-12 py-4 rounded-[3rem] font-black text-[8rem] leading-none border-8 shadow-2xl backdrop-blur-3xl transition-colors duration-200 ${timer <= 10 ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/90 dark:bg-zinc-800/90 border-indigo-600 text-indigo-600 dark:text-indigo-400'}`}>
                            {Math.floor(timer/60)}:{String(timer%60).padStart(2,'0')}
                        </div>
                      </div>
                    )}
                </div>
            </main>

            {/* Resizer Handle */}
            {showWebView && (
                <div 
                    className="w-2 bg-slate-200 dark:bg-zinc-800 hover:bg-indigo-500 dark:hover:bg-indigo-500 cursor-col-resize flex items-center justify-center z-[110] transition-colors"
                    onMouseDown={startResizeWeb}
                >
                    <GripVertical className="w-4 h-4 text-slate-400" />
                </div>
            )}

            {/* Right Panel: Web View */}
            {showWebView && (
                <div 
                    className="h-full bg-white dark:bg-black relative shadow-2xl z-[100]"
                    style={{ width: `${100 - webSplitRatio}%` }}
                >
                    <button onClick={() => setShowWebView(false)} className="absolute top-2 right-2 z-[160] p-1.5 bg-red-600 hover:bg-red-700 text-white rounded-full shadow-lg transition-transform hover:scale-110"><X className="w-4 h-4"/></button>
                    <iframe 
                        id="web-view-iframe"
                        src="https://bangsmart-fj2k.vercel.app/" 
                        className="w-full h-full border-0" 
                        allow="accelerometer; camera; encrypted-media; geolocation; gyroscope; microphone; midi; clipboard-read; clipboard-write; display-capture"
                        allowFullScreen
                    />
                </div>
            )}
        </div>

        {/* Floating Toolbar Area */}
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[150] flex flex-col items-center gap-2 no-print">
            {showToolbar ? (
                <div className="bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 border border-white/10 shadow-xl items-center animate-fade-in-up">
                    <button onClick={() => setShowNav(!showNav)} className="p-2 text-slate-400 hover:text-white relative"><LayoutGrid className="w-5 h-5"/><ShortcutLabel>M</ShortcutLabel></button>
                    <button onClick={() => setShowWebView(true)} className={`p-2 transition-colors relative ${showWebView ? 'text-teal-400' : 'text-slate-400 hover:text-teal-400'}`}><Globe className="w-5 h-5"/><ShortcutLabel>W</ShortcutLabel></button>
                    <div className="w-px h-6 bg-white/20"></div>
                    <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                        <button onClick={handleZoomOut} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                        <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                        <button onClick={handleZoomIn} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
                    </div>
                    {/* Math Palette Toggle */}
                    <div className="w-px h-6 bg-white/20"></div>
                    <button onClick={() => setMathPalette(prev => prev === 'default' ? 'contrast' : 'default')} className={`p-2 rounded-full transition-colors ${mathPalette === 'contrast' ? 'text-yellow-400 bg-white/10' : 'text-slate-400 hover:text-white'}`} title="Màu công thức (Chế độ tối)">
                        <Wand2 className="w-5 h-5" />
                    </button>
                    <div className="w-px h-6 bg-white/20"></div>
                    <button onClick={() => setShowToolbar(false)} className="p-2 text-slate-400 hover:text-white rounded-full hover:bg-white/10 transition-colors" title="Ẩn menu">
                        <ChevronDown className="w-5 h-5"/>
                    </button>
                </div>
            ) : (
                <button onClick={() => setShowToolbar(true)} className="bg-slate-900/50 hover:bg-slate-900/90 backdrop-blur-md text-white p-2 rounded-full border border-white/10 shadow-lg transition-all hover:scale-110" title="Hiện menu">
                    <ChevronUp className="w-6 h-6"/>
                </button>
            )}
        </div>

        {showScoreModal && (
            <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-2xl flex items-center justify-center p-8 animate-fade-in">
                <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] max-w-lg w-full text-center shadow-2xl border-t-8 border-indigo-600">
                    <Trophy className="w-24 h-24 text-yellow-500 mx-auto mb-6 animate-bounce" />
                    <h2 className="text-8xl font-black text-indigo-600 dark:text-indigo-400 mb-4 tracking-tighter">{calculateScore()}/10</h2>
                    <p className="text-2xl text-slate-500 font-black uppercase mb-10">Xuất sắc, {studentName}!</p>
                    <button onClick={() => { setShowScoreModal(false); setShowAnswersGlobal(true); setViewMode('list'); }} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-2xl hover:bg-indigo-700 transition-all uppercase">XEM BÀI GIẢI</button>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, ZoomIn, ZoomOut, Palette, Star, MonitorPlay, BookOpen, School, Save, Globe, GripVertical, ChevronDown, ChevronUp, X, PenTool, Database, Wand2 } from 'lucide-react';

interface StudyGuidePreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
  onEdit?: () => void;
  onSaveToBank?: () => void; // Added onSaveToBank prop
}

const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc', 
    bg: 'bg-teal-50 dark:bg-zinc-950', 
    primary: 'text-teal-700 dark:text-teal-400', 
    border: 'border-teal-500',
    highlight: 'text-teal-600 dark:text-teal-300'
  },
  blue: { 
    name: 'Xanh Dương', 
    bg: 'bg-blue-50 dark:bg-zinc-950', 
    primary: 'text-blue-700 dark:text-blue-400', 
    border: 'border-blue-500',
    highlight: 'text-blue-600 dark:text-blue-300'
  },
  violet: { 
    name: 'Tím', 
    bg: 'bg-violet-50 dark:bg-zinc-950', 
    primary: 'text-violet-700 dark:text-violet-400', 
    border: 'border-violet-500',
    highlight: 'text-violet-600 dark:text-violet-300'
  }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const ShortcutLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
);

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ role, config, data, onReset, onRegenerate, onEdit, onSaveToBank }) => {
  const [currentSection, setCurrentSection] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(4.0);
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('violet');
  const [showWebView, setShowWebView] = useState(false);
  const [showToolbar, setShowToolbar] = useState(true);
  const [mathPalette, setMathPalette] = useState<'default' | 'contrast'>('default'); // New Math Palette State

  // Web View Resizing State
  const [webSplitRatio, setWebSplitRatio] = useState(50);
  const isDraggingWebRef = useRef(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const sections = data?.sections || [];

  // Handle Dragging
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDraggingWebRef.current) return;
      const newRatio = (e.clientX / window.innerWidth) * 100;
      setWebSplitRatio(Math.min(80, Math.max(20, newRatio)));
    };

    const handleMouseUp = () => {
      if (isDraggingWebRef.current) {
        isDraggingWebRef.current = false;
        document.body.style.cursor = 'default';
        const iframe = document.getElementById('web-view-iframe');
        if (iframe) iframe.style.pointerEvents = 'auto';
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const startResize = () => {
    isDraggingWebRef.current = true;
    document.body.style.cursor = 'col-resize';
    const iframe = document.getElementById('web-view-iframe');
    if (iframe) iframe.style.pointerEvents = 'none';
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();

      if (key === 'w') setShowWebView(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 'h' && e.altKey) setShowToolbar(prev => !prev);
      if (key === '=' || key === '+') setZoomLevel(prev => Math.min(prev + 0.2, 8.0));
      if (key === '-' || key === '_') setZoomLevel(prev => Math.max(prev - 0.2, 0.5));
      if (sections.length > 0) {
        if (e.key === 'ArrowRight') setCurrentSection(s => Math.min(sections.length - 1, s + 1));
        if (e.key === 'ArrowLeft') setCurrentSection(s => Math.max(0, s - 1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSection, sections.length]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'theory', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `StudyGuide_${config.topic}.json`; a.click();
  };

  const theme = SLIDE_THEMES[activeTheme];

  const renderMetaList = (label: string, items?: string[], toneClass?: string) => {
    if (!items || items.length === 0) return null;
    return (
      <div className="flex flex-wrap items-start gap-2">
        <span className={`text-[0.6em] font-black uppercase tracking-widest ${toneClass || 'text-slate-500'}`}>{label}:</span>
        <div className="flex flex-wrap gap-2">
          {items.map((item, idx) => (
            <span key={`${label}-${idx}`} className="text-[0.7em] font-bold bg-slate-100 dark:bg-zinc-900 px-3 py-1 rounded-full text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-zinc-700">
              {item}
            </span>
          ))}
        </div>
      </div>
    );
  };

  const renderDifferentiation = (labelClass?: string) => {
    const plan = data?.differentiation;
    if (!plan || (!plan.basic?.length && !plan.advanced?.length && !plan.application?.length)) return null;
    return (
      <div className="space-y-2">
        <div className={`text-[0.6em] font-black uppercase tracking-widest ${labelClass || 'text-slate-500'}`}>Phân hóa:</div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
          {plan.basic && plan.basic.length > 0 && (
            <div className="p-3 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800">
              <div className="text-[0.6em] font-black text-emerald-700 dark:text-emerald-300 uppercase mb-1">Cơ bản</div>
              <ul className="list-disc pl-4 text-[0.7em] text-emerald-900 dark:text-emerald-100 space-y-1">
                {plan.basic.map((item, idx) => <li key={`basic-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
          {plan.advanced && plan.advanced.length > 0 && (
            <div className="p-3 rounded-2xl bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
              <div className="text-[0.6em] font-black text-blue-700 dark:text-blue-300 uppercase mb-1">Nâng cao</div>
              <ul className="list-disc pl-4 text-[0.7em] text-blue-900 dark:text-blue-100 space-y-1">
                {plan.advanced.map((item, idx) => <li key={`adv-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
          {plan.application && plan.application.length > 0 && (
            <div className="p-3 rounded-2xl bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800">
              <div className="text-[0.6em] font-black text-amber-700 dark:text-amber-300 uppercase mb-1">Vận dụng</div>
              <ul className="list-disc pl-4 text-[0.7em] text-amber-900 dark:text-amber-100 space-y-1">
                {plan.application.map((item, idx) => <li key={`app-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
        </div>
      </div>
    );
  };

  if (!sections || sections.length === 0) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
            <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700">
                <p className="text-red-500 font-bold mb-4">Không tìm thấy nội dung bài giảng.</p>
                <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors">Quay lại</button>
            </div>
        </div>
    );
  }

  const currentSectionData = sections[currentSection];

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
      {/* Header */}
      <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 p-2 h-10 flex justify-between items-center px-2 no-print sticky top-0 z-50">
        <div className="flex items-center gap-2">
            <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
            <h1 className="text-xs font-black truncate max-w-[200px] uppercase dark:text-zinc-200">{config.topic}</h1>
        </div>
        <div className="flex items-center gap-1.5">
            {onEdit && (
                <button onClick={onEdit} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-lg mr-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20" title="Chỉnh sửa">
                <PenTool className="w-4 h-4" />
                </button>
            )}
            {onSaveToBank && (
              <button onClick={onSaveToBank} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 rounded-lg mr-2 hover:bg-emerald-50 dark:hover:bg-emerald-900/20" title="Lưu vào Ngân hàng">
                <Database className="w-4 h-4" />
              </button>
            )}
            <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
            <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 relative text-slate-600 dark:text-slate-300">
                {isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}
            </button>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="flex flex-grow relative overflow-hidden">
          {/* Slide Content */}
          <main 
            className={`flex flex-col relative transition-all duration-0`}
            style={{ 
                width: showWebView ? `${webSplitRatio}%` : '100%',
                maxWidth: showWebView ? 'none' : '',
            }}
          >
             <div className={`h-full w-full flex flex-col items-center justify-between p-6 md:p-8 transition-all duration-300 ease-out rounded-[2.5rem] shadow-2xl border-4 overflow-hidden ${theme.bg} ${theme.border}`} style={{ fontSize: `${zoomLevel * 100}%` }}>

                {/* Slide Content */}
                <div className="w-full flex-grow overflow-y-auto custom-scrollbar flex flex-col gap-8 animate-fade-in-up">
                    <div className="shrink-0 text-center border-b-2 border-slate-200 dark:border-slate-800 pb-6">
                        <div className="flex justify-center items-center gap-2 mb-2">
                            <span className="px-3 py-1 rounded-full bg-slate-200 dark:bg-slate-800 text-[0.4em] font-black text-slate-500 uppercase tracking-widest">
                                Slide {currentSection + 1}/{sections.length}
                            </span>
                            {currentSectionData.differentiationLevel && (
                                <span className="px-3 py-1 rounded-full bg-amber-100 dark:bg-amber-900/30 text-[0.4em] font-black text-amber-600 uppercase tracking-widest">
                                    {currentSectionData.differentiationLevel}
                                </span>
                            )}
                        </div>
                        <h2 className={`text-[2em] font-black uppercase tracking-tighter leading-none ${theme.primary} mb-4`}>
                            <MathRenderer content={currentSectionData.title} palette={mathPalette} />
                        </h2>
                        {renderMetaList('Mục tiêu', currentSectionData.objectives)}
                    </div>

                    <div className="flex-grow w-full space-y-8">
                        <div className="text-[1em] font-medium leading-relaxed dark:text-slate-200 whitespace-pre-wrap">
                            <MathRenderer content={currentSectionData.content} palette={mathPalette} />
                        </div>

                        {currentSectionData.examples && currentSectionData.examples.length > 0 && (
                            <div className="grid gap-6">
                                {currentSectionData.examples.map((ex, exi) => (
                                    <div key={exi} className="bg-white/50 dark:bg-white/5 p-6 rounded-3xl border border-slate-200 dark:border-slate-800">
                                        <div className="flex items-center gap-2 mb-2 font-black text-[0.8em] text-amber-600 uppercase tracking-widest">
                                            <Star className="w-[1em] h-[1em]" /> Ví dụ {exi + 1}
                                        </div>
                                        <div className="mb-4 text-[0.9em] font-bold"><MathRenderer content={ex.problem} palette={mathPalette} /></div>
                                        <div className="pl-4 border-l-4 border-emerald-400">
                                            <div className="text-[0.8em] italic text-emerald-700 dark:text-emerald-400 mb-1 font-bold">Lời giải:</div>
                                            <div className="text-[0.8em] dark:text-slate-300"><MathRenderer content={ex.solution} palette={mathPalette} /></div>
                                        </div>
                                        {ex.explanation && (
                                            <div className="mt-4 text-[0.7em] text-slate-500 italic bg-slate-100 dark:bg-slate-900 p-3 rounded-xl">
                                                💡 {ex.explanation}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}

                        {(currentSectionData.guidingQuestions?.length || currentSectionData.activities?.length) && (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t border-slate-200 dark:border-slate-800">
                                {currentSectionData.guidingQuestions && currentSectionData.guidingQuestions.length > 0 && (
                                    <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-2xl">
                                        <h4 className="text-[0.6em] font-black text-blue-600 uppercase mb-2">Câu hỏi gợi mở</h4>
                                        <ul className="list-disc pl-4 space-y-1">
                                            {currentSectionData.guidingQuestions.map((q, i) => (
                                                <li key={i} className="text-[0.7em] text-blue-900 dark:text-blue-100 font-medium"><MathRenderer content={q} inline palette={mathPalette} /></li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                                {currentSectionData.activities && currentSectionData.activities.length > 0 && (
                                    <div className="bg-violet-50 dark:bg-violet-900/10 p-4 rounded-2xl">
                                        <h4 className="text-[0.6em] font-black text-violet-600 uppercase mb-2">Hoạt động</h4>
                                        <ul className="list-disc pl-4 space-y-1">
                                            {currentSectionData.activities.map((a, i) => (
                                                <li key={i} className="text-[0.7em] text-violet-900 dark:text-violet-100 font-medium"><MathRenderer content={a} inline palette={mathPalette} /></li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="w-full mt-4 h-1 bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden shrink-0">
                    <div 
                        className={`h-full transition-all duration-300 ${activeTheme === 'teal' ? 'bg-teal-500' : activeTheme === 'blue' ? 'bg-blue-500' : 'bg-violet-500'}`}
                        style={{ width: `${((currentSection + 1) / sections.length) * 100}%` }}
                    ></div>
                </div>
             </div>
          </main>

          {/* Resizer Handle */}
          {showWebView && (
             <div 
                className="w-2 bg-slate-200 dark:bg-zinc-800 hover:bg-indigo-500 dark:hover:bg-indigo-500 cursor-col-resize flex items-center justify-center z-[110] transition-colors"
                onMouseDown={startResize}
             >
                <GripVertical className="w-4 h-4 text-slate-400" />
             </div>
          )}

          {/* Right Panel: Web View */}
          {showWebView && (
            <div 
                className="h-full bg-white dark:bg-black relative shadow-2xl z-[100]"
                style={{ width: `${100 - webSplitRatio}%` }}
            >
                <button onClick={() => setShowWebView(false)} className="absolute top-2 right-2 z-[160] p-1.5 bg-red-600 hover:bg-red-700 text-white rounded-full shadow-lg transition-transform hover:scale-110"><X className="w-4 h-4"/></button>
                <iframe 
                    id="web-view-iframe"
                    src="https://bangsmart-fj2k.vercel.app/" 
                    className="w-full h-full border-0" 
                    allow="accelerometer; camera; encrypted-media; geolocation; gyroscope; microphone; midi; clipboard-read; clipboard-write; display-capture"
                    allowFullScreen
                />
            </div>
          )}
      </div>

      {/* Floating Toolbar Area */}
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[150] flex flex-col items-center gap-2 no-print">
        {showToolbar ? (
            <div className="bg-slate-900/90 backdrop-blur-md rounded-full p-1.5 flex gap-2 border border-white/10 shadow-xl items-center animate-fade-in-up">
                <button onClick={() => setShowWebView(true)} className={`p-2 transition-colors relative ${showWebView ? 'text-teal-400' : 'text-slate-400 hover:text-teal-400'}`}><Globe className="w-5 h-5"/><ShortcutLabel>W</ShortcutLabel></button>
                <div className="w-px h-6 bg-white/20"></div>
                <div className="flex items-center gap-1 bg-black/20 rounded-full px-2 py-0.5">
                    <button onClick={() => setZoomLevel(prev => Math.max(prev - 0.2, 0.5))} className="p-1 text-slate-400 hover:text-white relative"><ZoomOut className="w-4 h-4"/><ShortcutLabel>-</ShortcutLabel></button>
                    <span className="text-xs font-bold text-white min-w-[30px] text-center">{zoomLevel.toFixed(1)}x</span>
                    <button onClick={() => setZoomLevel(prev => Math.min(prev + 0.2, 8.0))} className="p-1 text-slate-400 hover:text-white relative"><ZoomIn className="w-4 h-4"/><ShortcutLabel>+</ShortcutLabel></button>
                </div>
                <div className="w-px h-6 bg-white/20"></div>

                {/* Theme Toggles */}
                <div className="flex gap-1">
                    {(Object.keys(SLIDE_THEMES) as ThemeKey[]).map(t => (
                        <button 
                            key={t}
                            onClick={() => setActiveTheme(t)}
                            className={`w-6 h-6 rounded-full border-2 transition-all ${activeTheme === t ? 'border-white scale-110' : 'border-transparent opacity-50 hover:opacity-100'}`}
                            style={{ backgroundColor: t === 'teal' ? '#14b8a6' : t === 'blue' ? '#3b82f6' : '#8b5cf6' }}
                        />
                    ))}
                </div>

                {/* Math Palette Toggle */}
                <div className="w-px h-6 bg-white/20"></div>
                <button onClick={() => setMathPalette(prev => prev === 'default' ? 'contrast' : 'default')} className={`p-2 rounded-full transition-colors ${mathPalette === 'contrast' ? 'text-yellow-400 bg-white/10' : 'text-slate-400 hover:text-white'}`} title="Màu công thức (Chế độ tối)">
                    <Wand2 className="w-5 h-5" />
                </button>

                <div className="w-px h-6 bg-white/20"></div>
                <button onClick={() => setShowToolbar(false)} className="p-2 text-slate-400 hover:text-white rounded-full hover:bg-white/10 transition-colors" title="Ẩn menu">
                    <ChevronDown className="w-5 h-5"/>
                </button>
            </div>
        ) : (
            <button onClick={() => setShowToolbar(true)} className="bg-slate-900/50 hover:bg-slate-900/90 backdrop-blur-md text-white p-2 rounded-full border border-white/10 shadow-lg transition-all hover:scale-110" title="Hiện menu">
                <ChevronUp className="w-6 h-6"/>
            </button>
        )}
      </div>
    </div>
  );
};

export default StudyGuidePreview;

import React, { useState, useEffect, useRef } from 'react';
import { ExamConfig, StudyGuideData, TheorySection } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, RotateCcw, FileText, Maximize, Minimize, LayoutGrid, ZoomIn, ZoomOut, Palette, Star, MonitorPlay, BookOpen, School, Save, Globe, GripVertical, ChevronDown, ChevronUp, X, PenTool, Database, Wand2, Home } from 'lucide-react';

interface StudyGuidePreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: StudyGuideData;
  onReset: () => void;
  onRegenerate: () => void;
  onEdit?: () => void;
  onSaveToBank?: () => void; // Added onSaveToBank prop
}

const SLIDE_THEMES = {
  teal: { 
    name: 'Xanh Ngọc', 
    bg: 'bg-teal-50 dark:bg-zinc-950', 
    primary: 'text-teal-700 dark:text-teal-400', 
    border: 'border-teal-500',
    highlight: 'text-teal-600 dark:text-teal-300'
  },
  blue: { 
    name: 'Xanh Dương', 
    bg: 'bg-blue-50 dark:bg-zinc-950', 
    primary: 'text-blue-700 dark:text-blue-400', 
    border: 'border-blue-500',
    highlight: 'text-blue-600 dark:text-blue-300'
  },
  violet: { 
    name: 'Tím', 
    bg: 'bg-violet-50 dark:bg-zinc-950', 
    primary: 'text-violet-700 dark:text-violet-400', 
    border: 'border-violet-500',
    highlight: 'text-violet-600 dark:text-violet-300'
  }
};

type ThemeKey = keyof typeof SLIDE_THEMES;

const ShortcutLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] font-bold px-1 rounded shadow-sm pointer-events-none">{children}</span>
);

const StudyGuidePreview: React.FC<StudyGuidePreviewProps> = ({ role, config, data, onReset, onRegenerate, onEdit, onSaveToBank }) => {
  const [currentSection, setCurrentSection] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(4.0);
  const [activeTheme, setActiveTheme] = useState<ThemeKey>('violet');
  const [showWebView, setShowWebView] = useState(false);
  const [showToolbar, setShowToolbar] = useState(true);
  const [mathPalette, setMathPalette] = useState<'default' | 'contrast'>('default'); // New Math Palette State

  // Web View Resizing State
  const [webSplitRatio, setWebSplitRatio] = useState(50);
  const isDraggingWebRef = useRef(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const sections = data?.sections || [];

  // Handle Dragging
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDraggingWebRef.current) return;
      const newRatio = (e.clientX / window.innerWidth) * 100;
      setWebSplitRatio(Math.min(80, Math.max(20, newRatio)));
    };

    const handleMouseUp = () => {
      if (isDraggingWebRef.current) {
        isDraggingWebRef.current = false;
        document.body.style.cursor = 'default';
        const iframe = document.getElementById('web-view-iframe');
        if (iframe) iframe.style.pointerEvents = 'auto';
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const startResize = () => {
    isDraggingWebRef.current = true;
    document.body.style.cursor = 'col-resize';
    const iframe = document.getElementById('web-view-iframe');
    if (iframe) iframe.style.pointerEvents = 'none';
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const key = e.key.toLowerCase();

      if (key === 'w') setShowWebView(prev => !prev);
      if (key === 'f') toggleFullScreen();
      if (key === 'h' && e.altKey) setShowToolbar(prev => !prev);
      if (key === '=' || key === '+') setZoomLevel(prev => Math.min(prev + 0.2, 8.0));
      if (key === '-' || key === '_') setZoomLevel(prev => Math.max(prev - 0.2, 0.5));
      if (sections.length > 0) {
        if (e.key === 'ArrowRight') setCurrentSection(s => Math.min(sections.length - 1, s + 1));
        if (e.key === 'ArrowLeft') setCurrentSection(s => Math.max(0, s - 1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentSection, sections.length]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) containerRef.current?.requestFullscreen().then(() => setIsFullscreen(true));
    else if (document.exitFullscreen) document.exitFullscreen().then(() => setIsFullscreen(false));
  };

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ type: 'theory', config, data, timestamp: Date.now() }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `StudyGuide_${config.topic}.json`; a.click();
  };

  const theme = SLIDE_THEMES[activeTheme];

  const renderMetaList = (label: string, items?: string[], toneClass?: string) => {
    if (!items || items.length === 0) return null;
    return (
      <div className="flex flex-wrap items-start gap-2">
        <span className={`text-[0.6em] font-black uppercase tracking-widest ${toneClass || 'text-slate-500'}`}>{label}:</span>
        <div className="flex flex-wrap gap-2">
          {items.map((item, idx) => (
            <span key={`${label}-${idx}`} className="text-[0.7em] font-bold bg-slate-100 dark:bg-zinc-900 px-3 py-1 rounded-full text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-zinc-700">
              {item}
            </span>
          ))}
        </div>
      </div>
    );
  };

  const renderDifferentiation = (labelClass?: string) => {
    const plan = data?.differentiation;
    if (!plan || (!plan.basic?.length && !plan.advanced?.length && !plan.application?.length)) return null;
    return (
      <div className="space-y-2">
        <div className={`text-[0.6em] font-black uppercase tracking-widest ${labelClass || 'text-slate-500'}`}>Phân hóa:</div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
          {plan.basic && plan.basic.length > 0 && (
            <div className="p-3 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800">
              <div className="text-[0.6em] font-black text-emerald-700 dark:text-emerald-300 uppercase mb-1">Cơ bản</div>
              <ul className="list-disc pl-4 text-[0.7em] text-emerald-900 dark:text-emerald-100 space-y-1">
                {plan.basic.map((item, idx) => <li key={`basic-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
          {plan.advanced && plan.advanced.length > 0 && (
            <div className="p-3 rounded-2xl bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
              <div className="text-[0.6em] font-black text-blue-700 dark:text-blue-300 uppercase mb-1">Nâng cao</div>
              <ul className="list-disc pl-4 text-[0.7em] text-blue-900 dark:text-blue-100 space-y-1">
                {plan.advanced.map((item, idx) => <li key={`adv-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
          {plan.application && plan.application.length > 0 && (
            <div className="p-3 rounded-2xl bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800">
              <div className="text-[0.6em] font-black text-amber-700 dark:text-amber-300 uppercase mb-1">Vận dụng</div>
              <ul className="list-disc pl-4 text-[0.7em] text-amber-900 dark:text-amber-100 space-y-1">
                {plan.application.map((item, idx) => <li key={`app-${idx}`}>{item}</li>)}
              </ul>
            </div>
          )}
        </div>
      </div>
    );
  };

  if (!sections || sections.length === 0) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
            <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700">
                <p className="text-red-500 font-bold mb-4">Không tìm thấy nội dung bài giảng.</p>
                <button onClick={onReset} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors">Quay lại</button>
            </div>
        </div>
    );
  }

  const currentSectionData = sections[currentSection];

  return (
    <div ref={containerRef} className={`min-h-screen flex flex-col bg-slate-50 dark:bg-black ${isFullscreen ? 'fixed inset-0 z-[100]' : ''}`}>
      {/* Header */}
      <header className="bg-white/95 dark:bg-zinc-950/95 backdrop-blur-md border-b border-slate-200 dark:border-zinc-800 p-2 h-10 flex justify-between items-center px-2 no-print sticky top-0 z-50">
        <div className="flex items-center gap-2">
            <button onClick={onReset} className="p-1.5 hover:bg-slate-100 dark:hover:bg-zinc-800 rounded-lg"><Home className="w-4 h-4 text-indigo-600 dark:text-indigo-400"/></button>
            <h1 className="text-xs font-black truncate max-w-[200px] uppercase dark:text-zinc-200">{config.topic}</h1>
        </div>
        <div className="flex items-center gap-1.5">
            {onEdit && (
                <button onClick={onEdit} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-lg mr-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20" title="Chỉnh sửa">
                <PenTool className="w-4 h-4" />
                </button>
            )}
            {onSaveToBank && (
              <button onClick={onSaveToBank} className="p-1.5 bg-slate-100 dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 rounded-lg mr-2 hover:bg-emerald-50 dark:hover:bg-emerald-900/20" title="Lưu vào Ngân hàng">
                <Database className="w-4 h-4" />
              </button>
            )}
            <button onClick={handleExport} className="p-1.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-zinc-800 rounded-lg relative"><Save className="w-4 h-4"/><ShortcutLabel>S</ShortcutLabel></button>
            <button onClick={toggleFullScreen} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-zinc-800 relative text-slate-600 dark:text-slate-300">
                {isFullscreen ? <Minimize className="w-4 h-4"/> : <Maximize className="w-4 h-4"/>}
            </button>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="flex flex-grow relative overflow-hidden">
          {/* Slide Content */}
          <main 
            className={`flex flex-col relative transition-all duration-0`}
            style={{ 
                width: showWebView ? `${webSplitRatio}%` : '100%',
                maxWidth: showWebView ? 'none' : '',
            }}
          >
             <div className={`h-full w-full flex flex-col items-center justify-between p-6 md:p-8 transition-all duration-300 ease-out rounded-[2.5rem] shadow-2xl border-4 overflow-hidden ${theme.bg} ${theme.border}`} style={{ fontSize: `${zoomLevel * 100}%` }}>

                {/* Slide Content */}
                <div className="w-full flex-grow overflow-y-auto custom-scrollbar flex flex-col gap-8 animate-fade-in-up">
                    <div className="shrink-0 text-center border-b-2 border-slate-200 dark:border-slate-800 pb-6">
                        <div className="flex justify-center items-center gap-2 mb-2">
                            <span className="px-3 py-1 rounded-full bg-slate-200 dark:bg-slate-800 text-[0.4em] font-black text-slate-500 uppercase tracking-widest">
                                Slide {currentSection + 1}/{sections.length}
                            </span>
                            {currentSectionData.differentiationLevel && (
                                <span className="px-3 py-1 rounded-full bg-amber-100 dark:bg-amber-900/30 text-[0.4em] font-black text-amber-600 uppercase tracking-widest">
                                    {currentSectionData.differentiationLevel}
                                </span>
                            )}
                        </div>
                        <h2 className={`text-[2em] font-black uppercase tracking-tighter leading-none ${theme.primary} mb-4`}>
                            <MathRenderer content={currentSectionData.title} palette={mathPalette} />
                        </h2>
                        {renderMetaList('Mục tiêu', currentSectionData.objectives)}
                    </div>

                    <div className="flex-grow w-full space-y-8">
                        <div className="text-[1em] font-medium leading-relaxed dark:text-slate-200 whitespace-pre-wrap">
                            <MathRenderer content={currentSectionData.content} palette={mathPalette} />
                        </div>

                        {currentSectionData.examples && currentSectionData.examples.length > 0 && (
                            <div className="grid gap-6">
                                {currentSectionData.examples.map((ex, exi) => (
                                    <div key={exi} className="bg-white/50 dark:bg-white/5 p-6 rounded-3xl border border-slate-200 dark:border-slate-800">
                                        <div className="flex items-center gap-2 mb-2 font-black text-[0.8em] text-amber-600 uppercase tracking-widest">
                                            <Star className="w-[1em] h-[1em]" /> Ví dụ {exi + 1}
                                        </div>
                                        <div className="mb-4 text-[0.9em] font-bold"><MathRenderer content={ex.problem} palette={mathPalette} /></div>
                                        <div className="pl-4 border-l-4 border-emerald-400">
                                            <div className="text-[0.8em] italic text-emerald-700 dark:text-emerald-400 mb-1 font-bold">Lời giải:</div>
                                            <div className="text-[0.8em] dark:text-slate-300"><MathRenderer content={ex.solution} palette={mathPalette} /></div>
                                        </div>
                                        {ex.explanation && (
                                            <div className="mt-4 text-[0.7em] text-slate-500 italic bg-slate-100 dark:bg-slate-900 p-3 rounded-xl">
                                                💡 {ex.explanation}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}

                        {(currentSectionData.guidingQuestions?.length || currentSectionData.activities?.length) && (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t border-slate-200 dark:border-slate-800">
                                {currentSectionData.guidingQuestions && currentSectionData.guidingQuestions.length > 0 && (
                                    <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-2xl">
                                        <h4 className="text-[0.6em] font-black text-blue-600 uppercase mb-2">Câu hỏi gợi mở</h4>
                                        <ul className="list-disc pl-4 space-y-1">
                                            {currentSectionData.guidingQuestions.map((q, i) => (
                                                <li key={i} className="text-[0.7em] text-blue-900 dark:text-blue-100 font-medium"><MathRenderer content={q} inline palette={mathPalette} /></li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                                {currentSectionData.activities && currentSectionData.activities.length > 0 && (
                                    <div className="bg-violet-50 dark:bg-violet-900/10 p-4 rounded-2xl">
                                        <h4 className="text-[0.6em] font-black text-violet-600 uppercase mb-2">Hoạt động</h4>
                                        <ul className="list-disc pl-4 space-y-1">
                                            {currentSectionData.activities.map((a, i) => (
                                                <li key={i} className="text-[0.7em] text-violet-900 dark:text-violet-100 font-medium"><MathRenderer content={a} inline palette={mathPalette} /></li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="w-full mt-4 h-1 bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden shrink-0">
                    <div 
