                            />
                        ))}
                    </div>
                )}

                {/* Math Palette Toggle */}
                <div className="w-px h-6 bg-white/20"></div>
                <button onClick={() => setMathPalette(prev => prev === 'default' ? 'contrast' : 'default')} className={`p-2 rounded-full transition-colors ${mathPalette === 'contrast' ? 'text-yellow-400 bg-white/10' : 'text-slate-400 hover:text-white'}`} title="Màu công thức (Chế độ tối)">
                    <Wand2 className="w-5 h-5" />
