import React, { useState, useRef, useEffect } from 'react';
import { ExamConfig, ExamMatrix, Question, QuestionType } from '../types';
import MathRenderer from './MathRenderer';
import { ChevronLeft, ChevronRight, Maximize, Minimize, LayoutGrid, ZoomIn, ZoomOut, MonitorPlay, CheckCircle, ListChecks, School, Eye, Lightbulb, HelpCircle, Save, Home, Volume2, FileOutput, Globe, GripVertical, GripHorizontal, ChevronDown, ChevronUp, X, Trophy, GraduationCap, PenTool, Database, Target, Wand2, Image as ImageIcon } from 'lucide-react';
import { exportExamToWord } from '../utils/docxUtils';

interface ExamPreviewProps {
  role: 'teacher' | 'student';
  config: ExamConfig;
  data: ExamMatrix;
