                                    className="w-6 h-6 rounded-full overflow-hidden cursor-pointer border-none p-0"
                                    title="Màu tùy chọn"
                                />
                                <span className="text-[10px] text-slate-400 font-bold uppercase">Tùy chọn</span>
                                {customMathColor && <button onClick={() => setCustomMathColor(null)} className="ml-auto text-[10px] text-red-400 hover:underline">Xóa</button>}
                            </div>
                        </div>
                    )}
                </div>

                {/* Background Image Toggle with Presets - CLICK TO OPEN */}
                <div className="relative">
                    <button 
                        onClick={() => setActiveMenu(activeMenu === 'bg' ? null : 'bg')}
                        className={`p-2 rounded-full transition-colors ${backgroundImage ? 'text-emerald-400 bg-white/10' : activeMenu === 'bg' ? 'text-white bg-white/20' : 'text-slate-400 hover:text-white'}`} 
                        title="Ảnh nền"
                    >
                        <ImageIcon className="w-5 h-5" />
                    </button>

                    {activeMenu === 'bg' && (
                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-4 flex bg-slate-800 p-2 rounded-xl shadow-2xl border border-slate-700 flex-col gap-2 min-w-[140px] animate-fade-in-up max-h-[300px] overflow-y-auto custom-scrollbar">
                            {BG_PRESETS.map((bg, idx) => (
                                <button key={bg.id} onClick={() => handleSetBgPreset(idx)} className="text-left px-3 py-1.5 text-xs font-bold text-slate-300 hover:text-white hover:bg-slate-700 rounded-lg transition-colors truncate">
                                    {bg.name}
                                </button>
                            ))}
                            <div className="h-px bg-slate-700 my-1"></div>
                            <input ref={bgInputRef} type="file" accept="image/*" className="hidden" onChange={handleBgUpload} />
                            <button onClick={() => bgInputRef.current?.click()} className="text-left px-3 py-1.5 text-xs font-bold text-indigo-400 hover:text-indigo-300 hover:bg-slate-700 rounded-lg transition-colors flex items-center gap-2">
                                <Upload className="w-3 h-3"/> Tải lên
                            </button>
                            {backgroundImage && (
                                <button onClick={clearBgImage} className="text-left px-3 py-1.5 text-xs font-bold text-red-400 hover:text-red-300 hover:bg-slate-700 rounded-lg transition-colors">
                                    Xóa ảnh nền
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="w-px h-6 bg-white/20"></div>
                <button onClick={() => setShowToolbar(false)} className="p-2 text-slate-400 hover:text-white rounded-full hover:bg-white/10 transition-colors" title="Ẩn menu">
                    <ChevronDown className="w-5 h-5"/>
                </button>
            </div>
        ) : (
            <button onClick={() => setShowToolbar(true)} className="bg-slate-900/50 hover:bg-slate-900/90 backdrop-blur-md text-white p-2 rounded-full border border-white/10 shadow-lg transition-all hover:scale-110" title="Hiện menu">
                <ChevronUp className="w-6 h-6"/>
            </button>
        )}
      </div>
    </div>
  );
};

