export default PolyaPreview;

export enum DifficultyLevel {
  VERY_EASY = 'Rất dễ (Nhận biết)',
  EASY = 'Dễ (Thông hiểu)',
  MEDIUM = 'Trung bình (Vận dụng)',
  HARD = 'Khó (Vận dụng cao)',
  VERY_HARD = 'Rất khó (Xuất sắc)',
}

export enum QuestionType {
  MULTIPLE_CHOICE = 'Trắc nghiệm (4 chọn 1)',
  TRUE_FALSE = 'Trắc nghiệm Đúng/Sai',
  ESSAY = 'Tự luận',
  MIXED = 'Kết hợp (TN + Đúng/Sai + Tự luận)',
}

export enum Subject {
  MATH = 'Toán',
  PHYSICS = 'Vật Lý',
  CHEMISTRY = 'Hóa Học',
  BIOLOGY = 'Sinh Học',
  INFORMATICS = 'Tin Học',
  LITERATURE = 'Ngữ Văn',
  HISTORY = 'Lịch Sử',
  GEOGRAPHY = 'Địa Lý',
  ENGLISH = 'Tiếng Anh',
  GDCD = 'GDCD',
  SCIENCE = 'KHTN',
  CLASS_MEETING = 'Sinh hoạt lớp',
  LIFE_SKILLS = 'Kỹ năng sống',
  CAREER_GUIDANCE = 'Trải nghiệm hướng nghiệp',
}

export type GenMode = 'exam' | 'matrix' | 'theory' | 'polya';

export type DifferentiationLevel = 'Cơ bản' | 'Nâng cao' | 'Vận dụng';

export interface DifferentiationPlan {
  basic?: string[];
  advanced?: string[];
  application?: string[];
}

export interface MatrixRow {
  topic: string;
  level: DifficultyLevel;
  count: number;
  type: QuestionType;
}

export interface ExamConfig {
  mode: GenMode;
  subject: Subject | string;
  grade: string;
  topic: string; // Used for single topic mode or as a title for matrix mode
  // Exam specific (Single Mode)
  questionType?: QuestionType;
  questionCount?: number;
  difficultyMode?: 'progressive' | 'fixed';
  targetLevel?: DifficultyLevel;
  // Matrix Mode
  matrixRows?: MatrixRow[];

  includeHints?: boolean;
  // Multimodal support
  uploadedFile?: {
    data: string; // base64 string
    mimeType: string;
  } | null;
}

export interface Question {
  id: number;
  content: string;
  type: QuestionType;
  difficulty: string; // e.g., "Nhận biết", "Vận dụng"
  differentiation?: DifferentiationLevel;
  options?: string[]; // For multiple choice
  correctAnswer: string;
  solution: string; // Detailed explanation
  hints?: string[]; // Step-by-step hints
  rubric?: string[]; // Short rubric for essay
  openAnswerGuidance?: string; // Open-answer guidance for essay
}

export interface ExamMatrix {
  title?: string;
  keyConcepts?: string; // New field for Core Knowledge/Formulas
  objectives?: string[]; // Learning objectives
  competencies?: string[]; // Competencies/skills
  differentiation?: DifferentiationPlan; // Differentiation guidance
  summary: string;
  questions: Question[];
}

// Structures for Study Guide (Theory & Examples)
export interface Example {
  problem: string;
  solution: string;
  explanation: string;
}

export interface TheorySection {
  title: string;
  objectives?: string[];
  competencies?: string[];
  differentiationLevel?: DifferentiationLevel;
  content: string; // Bullet points or paragraphs with LaTeX
  examples: Example[];
  guidingQuestions?: string[];
  activities?: string[]; // e.g., think-pair-share, exit ticket
}

export interface StudyGuideData {
  topic: string;
  overview: string;
  objectives?: string[];
  competencies?: string[];
  differentiation?: DifferentiationPlan;
  exitTicket?: string[];
  sections: TheorySection[];
}

// Structures for Polya Method
export interface PolyaStep {
  stepName: string; // e.g., "Bước 1: Tìm hiểu đề bài"
  icon: 'search' | 'map' | 'wrench' | 'check';
  content: string; // LaTeX supported content
  keyPoints?: string[]; // Highlights
}

export interface PolyaData {
  title: string;
  problem: string;
  steps: PolyaStep[];
}

// Data structure for Export/Import
export interface ExportData {
  type: GenMode;
  timestamp: number;
  config: ExamConfig;
  data: ExamMatrix | StudyGuideData | PolyaData;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamConfig, Question, QuestionType, ExamMatrix, StudyGuideData, MatrixRow, DifficultyLevel, PolyaData } from "../types";

const createClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const suggestMatrixStructure = async (subject: string, grade: string, title: string): Promise<MatrixRow[]> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const prompt = `
Bạn là chuyên gia khảo thí. Hãy gợi ý một cấu trúc ma trận đề thi chuẩn cho:
Môn: ${subject}
Lớp: ${grade}
Tiêu đề/Phạm vi: ${title}

TRẢ VỀ JSON MẢNG MatrixRow:
[
  { "topic": "Tên chuyên đề", "level": "Mức độ", "count": số_câu, "type": "Loại câu" }
]
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      },
    });
    return JSON.parse(response.text) as MatrixRow[];
  } catch (error) {
    console.error("Matrix suggestion failed:", error);
    return [];
  }
};

export const generateExam = async (config: ExamConfig): Promise<ExamMatrix> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  let structureInstruction = "";
  if (config.mode === 'matrix' && config.matrixRows) {
      config.matrixRows.forEach((row, idx) => {
          structureInstruction += `- Phần ${idx+1}: ${row.count} câu, Chủ đề: "${row.topic}", Mức: ${row.level}, Dạng: ${row.type}.\n`;
      });
  } else {
      structureInstruction = `Chủ đề: "${config.topic}", Số lượng: ${config.questionCount} câu, Dạng: ${config.questionType}.`;
  }

  let promptText = `
VAI TRÒ: Bạn là một GIÁO VIÊN TOÁN XUẤT SẮC CÓ 30 NĂM KINH NGHIỆM, chuyên luyện thi và hướng dẫn học sinh thực hành. Phong cách của bạn là sư phạm, chặt chẽ, chú trọng vào bản chất và tư duy.

NHIỆM VỤ: Soạn một chuyên đề luyện tập môn ${config.subject} lớp ${config.grade}.

YÊU CẦU CẤU TRÚC JSON (BẮT BUỘC):
1. keyConcepts (QUAN TRỌNG): Trước khi vào bài tập, bạn PHẢI cung cấp một phần tóm tắt "Kiến thức trọng tâm".
   - Bao gồm các công thức quan trọng nhất, định lý, hệ quả, hoặc phương pháp giải nhanh (mẹo) liên quan đến chủ đề này.
   - Trình bày dưới dạng danh sách (gạch đầu dòng) hoặc các đoạn văn ngắn gọn.
   - SỬ DỤNG LATEX CHUẨN cho mọi công thức Toán/Lý/Hóa.
   - Dùng '\\n' để xuống dòng rõ ràng.

2. questions: Danh sách câu hỏi luyện tập.
   - LATEX: Mọi công thức toán PHẢI đặt trong $...$ (Ví dụ: $V = \\\\frac{1}{3}Bh$). PHẢI escape backslash kép (\\\\).
   - OPTIONS: Trắc nghiệm phải có đủ 4 đáp án A, B, C, D.
   - SOLUTION (Lời giải): Giải chi tiết từng bước (Step-by-Step) như giáo viên đang giảng bài trên bảng. Tách dòng bằng '\\n'.

NỘI DUNG CỤ THỂ:
${structureInstruction}

TRẢ VỀ JSON CHUẨN THEO SCHEMA.
  `;

  const questionSchema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      content: { type: Type.STRING },
      type: { type: Type.STRING },
      difficulty: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctAnswer: { type: Type.STRING },
      solution: { type: Type.STRING },
      hints: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["id", "content", "type", "difficulty", "correctAnswer", "solution", "hints", "options"],
  };

  const responseSchema = {
    type: Type.OBJECT,
    properties: {
      summary: { type: Type.STRING },
      keyConcepts: { type: Type.STRING, description: "Tóm tắt kiến thức trọng tâm, công thức quan trọng của chuyên đề." },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      questions: {
        type: Type.ARRAY,
        items: questionSchema,
      },
    },
    required: ["summary", "keyConcepts", "questions"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.1,
      },
    });

    const parsed = JSON.parse(response.text);
    return parsed as ExamMatrix;
  } catch (error: any) {
    console.error("Lỗi sinh đề:", error);
    throw new Error("Lỗi hệ thống AI: " + error.message);
  }
};

export const generateStudyGuide = async (config: ExamConfig): Promise<StudyGuideData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const promptText = `
Bạn là chuyên gia sư phạm và thiết kế bài giảng điện tử.
Hãy soạn một bài giảng slide (Study Guide) chi tiết cho:
Môn: ${config.subject}
Lớp: ${config.grade}
Chủ đề: "${config.topic}"

YÊU CẦU NỘI DUNG:
1. Tổng quan bài học hấp dẫn.
2. Mục tiêu và Năng lực cần đạt rõ ràng (theo định hướng GDPT 2018).
3. Phân hóa dạy học: Kế hoạch hỗ trợ học sinh Cơ bản, Nâng cao, Vận dụng.
4. Các phần (sections) tương ứng với các slide/hoạt động dạy học.
   - Mỗi section có tiêu đề, nội dung chính (Content).
   - Ví dụ minh họa (Examples) có lời giải chi tiết.
   - Câu hỏi gợi mở (Guiding Questions) để giáo viên tương tác.
   - Hoạt động (Activities) đề xuất (ví dụ: Thảo luận nhóm, Trò chơi...).
5. Exit Ticket: 2-3 câu hỏi kiểm tra cuối giờ.

QUY TẮC ĐỊNH DẠNG & TRÌNH BÀY:
- LaTeX: Dùng $...$ cho công thức toán. Escape backslash (\\\\) trong chuỗi JSON.
- Content & Solution: Sử dụng ký tự \\n để ngắt dòng giữa các ý hoặc các bước giải. Ứng dụng sẽ sử dụng tính năng "Click để hiện tiếp" dựa trên ký tự này.
- DifferentiationLevel trong section: Chọn "Cơ bản", "Nâng cao" hoặc "Vận dụng".

TRẢ VỀ JSON KHỚP SCHEMA.
  `;

  // Define Schemas for Study Guide
  const exampleSchema = {
    type: Type.OBJECT,
    properties: {
      problem: { type: Type.STRING },
      solution: { type: Type.STRING },
      explanation: { type: Type.STRING },
    },
    required: ["problem", "solution", "explanation"],
  };

  const theorySectionSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiationLevel: { type: Type.STRING },
      content: { type: Type.STRING },
      examples: { type: Type.ARRAY, items: exampleSchema },
      guidingQuestions: { type: Type.ARRAY, items: { type: Type.STRING } },
      activities: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
    required: ["title", "content", "examples"],
  };

  const differentiationPlanSchema = {
    type: Type.OBJECT,
    properties: {
      basic: { type: Type.ARRAY, items: { type: Type.STRING } },
      advanced: { type: Type.ARRAY, items: { type: Type.STRING } },
      application: { type: Type.ARRAY, items: { type: Type.STRING } },
    }
  };

  const studyGuideSchema = {
    type: Type.OBJECT,
    properties: {
      topic: { type: Type.STRING },
      overview: { type: Type.STRING },
      objectives: { type: Type.ARRAY, items: { type: Type.STRING } },
      competencies: { type: Type.ARRAY, items: { type: Type.STRING } },
      differentiation: differentiationPlanSchema,
      exitTicket: { type: Type.ARRAY, items: { type: Type.STRING } },
      sections: { type: Type.ARRAY, items: theorySectionSchema },
    },
    required: ["topic", "overview", "sections"],
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: studyGuideSchema,
        temperature: 0.4,
      },
    });
    return JSON.parse(response.text) as StudyGuideData;
  } catch (error: any) {
    console.error("Lỗi sinh bài giảng:", error);
    throw new Error("Lỗi sinh bài giảng: " + error.message);
  }
};

export const generatePolyaSolution = async (config: ExamConfig): Promise<PolyaData> => {
  const ai = createClient();
  const modelName = "gemini-3-flash-preview";

  const promptText = `
  Bạn là một giáo sư toán học lỗi lạc, người áp dụng phương pháp của George Polya để hướng dẫn học sinh giải toán.
  Hãy phân tích bài toán sau đây theo 4 bước của Polya.

  BÀI TOÁN: "${config.topic}"

  QUY TẮC QUAN TRỌNG VỀ ĐỊNH DẠNG JSON:
  1. Trả về đúng định dạng JSON.
  2. Với các công thức Toán học (LaTeX), bạn PHẢI sử dụng double backslash (\\\\) thay vì single backslash (\\).
     Ví dụ: Viết "$\\\\frac{1}{2}$" thay vì "$\\frac{1}{2}$".
  3. TRÌNH BÀY: Sử dụng \\n để tách dòng các bước tư duy. Ứng dụng sẽ hiển thị từng dòng khi click (Click-to-reveal).

  YÊU CẦU ĐẦU RA (JSON):
  Hãy trả về một object JSON duy nhất với cấu trúc sau:
  {
    "title": "Tên ngắn gọn của bài toán",
    "problem": "Nội dung bài toán (có thể format lại cho đẹp bằng LaTeX)",
    "steps": [
      {
        "stepName": "Bước 1: Tìm hiểu đề bài",
        "icon": "search",
        "content": "Phân tích giả thiết (Cái đã cho), kết luận (Cái cần tìm).\\nVẽ hình nếu cần thiết (mô tả bằng lời).\\nĐịnh dạng LaTeX $...$ chuẩn.",
        "keyPoints": ["Giả thiết: ...", "Yêu cầu: ..."]
      },
      {
        "stepName": "Bước 2: Xây dựng chương trình giải",
        "icon": "map",
        "content": "Tìm mối liên hệ giữa giả thiết và kết luận.\\nNhớ lại các định lý, công thức liên quan.\\nLập kế hoạch từng bước.",
        "keyPoints": ["Sử dụng định lý...", "Đặt ẩn phụ...", "Chứng minh..."]
      },
      {
        "stepName": "Bước 3: Thực hiện chương trình giải",
        "icon": "wrench",
        "content": "Trình bày lời giải chi tiết, rõ ràng, tính toán chính xác.\\nDùng LaTeX cho công thức.\\nTách các bước tính bằng \\n.",
        "keyPoints": []
      },
      {
        "stepName": "Bước 4: Kiểm tra và khai thác",
        "icon": "check",
        "content": "Kiểm tra lại kết quả.\\nThử lại bằng cách khác (nếu có).\\nMở rộng bài toán hoặc tổng quát hóa.",
        "keyPoints": ["Cách khác: ...", "Bài toán tương tự..."]
      }
    ]
  }
  `;

  const polyaSchema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING },
      problem: { type: Type.STRING },
      steps: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            stepName: { type: Type.STRING },
            icon: { type: Type.STRING },
            content: { type: Type.STRING },
            keyPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["stepName", "icon", "content", "keyPoints"]
        }
      }
    },
    required: ["title", "problem", "steps"]
  };

  try {
    const parts: any[] = [{ text: promptText }];
    if (config.uploadedFile) {
        parts.push({ inlineData: { mimeType: config.uploadedFile.mimeType, data: config.uploadedFile.data } });
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: polyaSchema,
        temperature: 0.3,
      },
    });

    return JSON.parse(response.text) as PolyaData;
  } catch (error: any) {
    console.error("Lỗi sinh Polya:", error);
    throw new Error("Lỗi hệ thống AI: " + error.message);
  }
};

