              <button onClick={() => toggleRevealAnswer(idx)} className="mt-6 w-full py-3 bg-slate-100 dark:bg-zinc-900 rounded-xl border border-dashed border-slate-300 dark:border-zinc-700 flex items-center justify-center gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all text-slate-400 hover:text-indigo-600 no-print">
                  <Eye className="w-5 h-5" />
                  <span className="text-[0.6em] font-black uppercase">Xem Lời giải (A)</span>
              </button>
            )}
        </div>
      </div>
    );
  };

  const renderKeyConceptsSlide = () => (
    <div className="flex flex-col w-full h-full text-left bg-black" style={{fontSize: `${zoomLevel}rem`}}>
        <div className="w-full h-full flex flex-col overflow-hidden relative bg-black">

            {/* Header Sticky */}
            <div className="w-full p-6 md:p-10 border-b border-white/20 flex justify-between items-start shrink-0 bg-black/90 backdrop-blur-md z-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-600/30">
                        <BookOpen className="w-[1.8em] h-[1.8em]" />
                    </div>
                    <div>
                        <h2 className="text-[1.5em] font-black uppercase tracking-tighter text-white leading-none">
                            Kiến thức trọng tâm
                        </h2>
                        <div className="h-1 w-20 bg-indigo-500 rounded-full my-3"></div>
                        <p className="text-[0.6em] font-bold uppercase tracking-widest text-slate-400">
                            {config.topic} • {config.subject}
                        </p>
                    </div>
                </div>

                <button 
                    onClick={() => setCurrentSlide(0)} 
                    className="group px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black text-[0.7em] hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center gap-3"
                >
                    Bắt đầu luyện tập <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                </button>
            </div>

            {/* Scrollable Content - Full Width */}
            <div className="flex-grow overflow-y-auto custom-scrollbar p-6 md:p-12 w-full">
                <div className="max-w-none w-full text-[0.9em] font-medium leading-relaxed text-white">
                    <MathRenderer content={data.keyConcepts || "Không có nội dung."} customColor="#facc15" />
                </div>

                {/* Footer spacer */}
                <div className="h-20"></div>
            </div>
        </div>
    </div>
  );

  const renderTitleSlide = () => (
    <div className={`flex flex-col items-center justify-center pt-2 pb-16 px-6 md:px-12 w-full h-full text-center ${!backgroundImage ? 'bg-white dark:bg-zinc-950' : ''}`} style={{fontSize: `${zoomLevel}rem`}}>
        <div className="max-w-5xl w-full flex flex-col gap-10">
            {/* Topic Header */}
            <div className={`p-12 rounded-[4rem] border-8 shadow-2xl animate-fade-in-up ${backgroundImage ? 'bg-white/90 backdrop-blur-sm border-indigo-200' : 'bg-slate-50 dark:bg-zinc-900 border-indigo-100 dark:border-zinc-800'}`}>
                <div className="flex justify-center mb-6">
                    <GraduationCap className="w-[3em] h-[3em] text-indigo-600 dark:text-indigo-400 drop-shadow-xl" />
                </div>
                <h1 className="text-[1.8em] font-black uppercase tracking-tighter text-slate-900 dark:text-white mb-6 leading-none">
                    {config.topic}
                </h1>
                <div className="w-48 h-3 bg-gradient-to-r from-indigo-500 to-violet-500 rounded-full mx-auto mb-8 opacity-80"></div>
                <p className="text-[0.8em] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
