                    <button onClick={() => toggleRevealAnswer(idx)} className="absolute top-2 right-2 p-1 hover:bg-emerald-100 rounded-full no-print"><X className="w-5 h-5 text-emerald-600" /></button>
                    <h4 className="text-[0.7em] font-black text-emerald-700 dark:text-emerald-400 mb-2 flex items-center gap-2"><CheckCircle className="w-6 h-6" /> Đáp án: <MathRenderer content={q.correctAnswer} inline customColor={customMathColor} /></h4>
                    <div className={`text-[0.6em] font-bold leading-relaxed border-t border-emerald-100 pt-2 ${backgroundImage ? 'text-emerald-900' : 'dark:text-emerald-100'}`}><MathRenderer content={q.solution} customColor={customMathColor} /></div>
