            <div className="w-full p-6 md:p-10 border-b border-white/20 flex justify-between items-start shrink-0 bg-black/90 backdrop-blur-md z-10">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-600/30">
                        <BookOpen className="w-[1.8em] h-[1.8em]" />
                    </div>
                    <div>
                        <h2 className="text-[1.5em] font-black uppercase tracking-tighter text-white leading-none">
                            Kiến thức trọng tâm
                        </h2>
                        <div className="h-1 w-20 bg-indigo-500 rounded-full my-3"></div>
                        <p className="text-[0.6em] font-bold uppercase tracking-widest text-slate-400">
                            {config.topic} • {config.subject}
                        </p>
                    </div>
                </div>

                <button 
                    onClick={() => setCurrentSlide(0)} 
                    className="group px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black text-[0.7em] hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center gap-3"
                >
                    Bắt đầu luyện tập <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                </button>
