                typeToUse = 'theory';
                dataToUse = imported as any;
                configToUse = { mode: 'theory', subject: 'Khác', grade: 'Khác', topic: 'Imported Lesson' };
            } else if (imported.steps && Array.isArray(imported.steps)) {
                typeToUse = 'polya';
                dataToUse = imported as any;
                configToUse = { mode: 'polya', subject: 'Khác', grade: 'Khác', topic: 'Imported Polya' };
            }
        }

        if (typeToUse === 'theory') {
          setStudyGuideData(dataToUse as StudyGuideData);
          setExamData(null);
          setPolyaData(null);
        } else if (typeToUse === 'polya') {
          setPolyaData(dataToUse as PolyaData);
          setExamData(null);
          setStudyGuideData(null);
        } else {
          setExamData(dataToUse as ExamMatrix);
          setStudyGuideData(null);
          setPolyaData(null);
        }
        setConfig(configToUse);
        setStep('preview');
        setRole('teacher');
        setError(null);
      } catch (err: any) {
        setError("Lỗi đọc file: " + err.message);
      }
    };
    reader.readAsText(file);
  };

