                                        { k: '→ / ←', d: 'Chuyển Slide tiếp theo / trước đó' },
                                        { k: '+ / -', d: 'Phóng to / Thu nhỏ cỡ chữ' },
                                        { k: '1 - 5', d: 'Đặt hẹn giờ nhanh (1-5 phút)' },
                                        { k: 'A', d: 'Hiện/Ẩn đáp án (Chế độ Exam)' },
                                        { k: 'H', d: 'Hiện gợi ý câu hỏi (Chế độ Exam)' },
                                        { k: 'V', d: 'Đọc to nội dung câu hỏi (Text-to-Speech)' },
                                        { k: 'L', d: 'Đổi bố cục đáp án (Ngang/Dọc)' },
                                        { k: 'Alt + C', d: 'Đổi màu chữ (Tự động/Đen/Trắng/Xanh)' },
                                    ].map((item, idx) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700">
                                            <span className="font-medium text-slate-600 dark:text-slate-300 text-sm">{item.d}</span>
                                            <kbd className="px-3 py-1 bg-white dark:bg-slate-800 border-b-2 border-slate-300 dark:border-slate-600 rounded-lg font-black font-mono text-indigo-600 text-xs">{item.k}</kbd>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {guideTab === 'templates' && (
                            <div className="space-y-6">
                                <h4 className="text-2xl font-black text-indigo-600 dark:text-indigo-400">File Mẫu JSON</h4>
                                <p className="text-slate-600 dark:text-slate-300">
                                    Tải về các file mẫu chuẩn để tham khảo cấu trúc dữ liệu. Bạn có thể chỉnh sửa thủ công hoặc dùng để training cho AI khác.
                                </p>
                                <div className="grid grid-cols-1 gap-4">
                                    <button onClick={() => downloadSample('exam')} className="flex items-center justify-between p-4 bg-blue-50 hover:bg-blue-100 dark:bg-blue-900/20 dark:hover:bg-blue-900/30 rounded-2xl transition-colors group">
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-blue-600 text-white rounded-xl"><FileText className="w-6 h-6"/></div>
                                            <div className="text-left">
                                                <h5 className="font-bold text-blue-800 dark:text-blue-300">Mẫu Đề Thi (Exam)</h5>
                                                <p className="text-xs text-blue-600 dark:text-blue-400">Cấu trúc câu hỏi trắc nghiệm, tự luận, options, solution.</p>
                                            </div>
                                        </div>
                                        <Download className="w-5 h-5 text-blue-600 dark:text-blue-400 group-hover:scale-110 transition-transform"/>
                                    </button>

                                    <button onClick={() => downloadSample('theory')} className="flex items-center justify-between p-4 bg-violet-50 hover:bg-violet-100 dark:bg-violet-900/20 dark:hover:bg-violet-900/30 rounded-2xl transition-colors group">
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-violet-600 text-white rounded-xl"><Presentation className="w-6 h-6"/></div>
                                            <div className="text-left">
                                                <h5 className="font-bold text-violet-800 dark:text-violet-300">Mẫu Bài Giảng (Study Guide)</h5>
                                                <p className="text-xs text-violet-600 dark:text-violet-400">Cấu trúc sections, examples, activities.</p>
                                            </div>
                                        </div>
                                        <Download className="w-5 h-5 text-violet-600 dark:text-violet-400 group-hover:scale-110 transition-transform"/>
                                    </button>

                                    <button onClick={() => downloadSample('polya')} className="flex items-center justify-between p-4 bg-orange-50 hover:bg-orange-100 dark:bg-orange-900/20 dark:hover:bg-orange-900/30 rounded-2xl transition-colors group">
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-orange-600 text-white rounded-xl"><Footprints className="w-6 h-6"/></div>
                                            <div className="text-left">
                                                <h5 className="font-bold text-orange-800 dark:text-orange-300">Mẫu Giải Toán Polya</h5>
                                                <p className="text-xs text-orange-600 dark:text-orange-400">Cấu trúc 4 bước giải toán tư duy.</p>
                                            </div>
                                        </div>
                                        <Download className="w-5 h-5 text-orange-600 dark:text-orange-400 group-hover:scale-110 transition-transform"/>
                                    </button>
                                </div>
                            </div>
                        )}

                        {guideTab === 'prompts' && (
                            <div className="space-y-8">
                                <div>
                                    <h4 className="text-2xl font-black text-indigo-600 dark:text-indigo-400 mb-2">Câu lệnh Prompt AI Chuẩn</h4>
                                    <p className="text-slate-600 dark:text-slate-300 text-sm">
                                        Copy các câu lệnh này và dán vào ChatGPT, Claude, hoặc Gemini để tạo nội dung bài học, sau đó lưu kết quả thành file <code>.json</code> và Import vào ứng dụng.
                                    </p>
                                </div>

                                {[
                                    { id: 'exam', title: 'Prompt Tạo Đề Thi', content: PROMPTS.exam, color: 'blue' },
                                    { id: 'theory', title: 'Prompt Soạn Bài Giảng', content: PROMPTS.theory, color: 'violet' },
                                    { id: 'polya', title: 'Prompt Giải Toán Polya', content: PROMPTS.polya, color: 'orange' },
                                ].map((p) => (
                                    <div key={p.id} className="relative group">
                                        <div className="flex justify-between items-end mb-2">
                                            <h5 className={`font-bold uppercase text-xs tracking-widest text-${p.color}-600`}>{p.title}</h5>
                                            <button 
                                                onClick={() => copyToClipboard(p.content, p.id)}
                                                className={`flex items-center gap-1 text-[10px] font-black uppercase bg-${p.color}-50 text-${p.color}-600 px-3 py-1.5 rounded-lg hover:bg-${p.color}-100 transition-colors`}
                                            >
                                                {copiedPrompt === p.id ? <Check className="w-3 h-3"/> : <Copy className="w-3 h-3"/>}
                                                {copiedPrompt === p.id ? 'Đã sao chép' : 'Sao chép'}
                                            </button>
                                        </div>
                                        <pre className="p-4 bg-slate-900 text-slate-300 rounded-2xl text-[11px] font-mono whitespace-pre-wrap border border-slate-700 max-h-60 overflow-y-auto custom-scrollbar">
                                            {p.content}
                                        </pre>
                                    </div>
                                ))}
                            </div>
                        )}

                        {guideTab === 'faq' && (
                            <div className="space-y-6">
                                <h4 className="text-2xl font-black text-indigo-600 dark:text-indigo-400">Câu hỏi thường gặp</h4>
                                <div className="space-y-4">
                                    <div className="p-5 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800">
                                        <h5 className="font-bold text-slate-800 dark:text-white mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4 text-indigo-500"/> Làm sao để sử dụng Offline?</h5>
                                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">
                                            Ứng dụng hoạt động trên trình duyệt. Bạn cần internet để AI sinh nội dung lần đầu. Sau khi nội dung đã hiện ra hoặc bạn đã Import file JSON, bạn có thể ngắt mạng và trình chiếu bình thường.
                                        </p>
                                    </div>
                                    <div className="p-5 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800">
                                        <h5 className="font-bold text-slate-800 dark:text-white mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4 text-indigo-500"/> Tôi có thể nhập file Word/PDF không?</h5>
                                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">
                                            Hiện tại bạn có thể đính kèm ảnh chụp hoặc file PDF của tài liệu vào phần cấu hình để AI "đọc" và sinh ra bài học tương ứng. Tuy nhiên, để import trực tiếp vào trình chiếu, bạn cần dùng file chuẩn JSON của ứng dụng.
                                        </p>
                                    </div>
                                    <div className="p-5 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800">
                                        <h5 className="font-bold text-slate-800 dark:text-white mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4 text-indigo-500"/> Công thức Toán bị lỗi hiển thị?</h5>
                                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">
                                            Hãy đảm bảo công thức Toán được đặt trong dấu <code>$...$</code>. Nếu bạn tự viết file JSON, hãy chú ý escape dấu gạch chéo ngược, ví dụ <code>\\frac</code> thay vì <code>\frac</code>.
                                        </p>
                                    </div>
                                    <div className="p-5 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800">
                                        <h5 className="font-bold text-slate-800 dark:text-white mb-2 flex items-center gap-2"><HelpCircle className="w-4 h-4 text-indigo-500"/> Dữ liệu của tôi được lưu ở đâu?</h5>
                                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">
                                            Mọi dữ liệu được lưu cục bộ trên trình duyệt của bạn (LocalStorage) hoặc lưu về máy dưới dạng file JSON. Chúng tôi không lưu trữ dữ liệu của bạn trên máy chủ (trừ khi bạn dùng tính năng đồng bộ Google Sheet cá nhân).
                                        </p>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default App;
